export interface MCQItem {
  id: string;
  section: string;
  unit: string;
  chapter: string;
  questionNumber: string;
  question: string;
  options: Record<string, string>;
  correctOption: string;
  correctAnswer: string;
  questionType: string;
  explanation?: any;
}

export const MCQ_BANK_6: MCQItem[] = [{"id":"P1_U6_MCQ_001","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_001","question":"Country A's Gross Domestic Product (GDP) has fallen for two consecutive quarters, accompanied by rising unemployment and falling consumer spending. Which stage of the business cycle is Country A experiencing?","options":{"A":"Boom","B":"Recession","C":"Growth","D":"Slump"},"correctOption":"B","correctAnswer":"Recession","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a recession occurs when GDP falls, leading to declining business confidence, lower consumer demand, and rising unemployment.","distractor_reasons":{"A":"Incorrect because a boom is characterised by rapid GDP growth, high consumer spending, and very low unemployment.","B":"Correct selection.","C":"Incorrect because the growth stage involves rising GDP, increasing output, and falling unemployment.","D":"Incorrect because a slump is a prolonged and severe depression at the lowest point of the cycle, rather than an initial two-quarter downturn."}}},{"id":"P1_U6_MCQ_002","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_002","question":"An economy enters a prolonged slump with severe unemployment, frequent business closures, and very low household incomes. Which business objective should a luxury furniture manufacturer prioritise during this stage?","options":{"A":"Rapid overseas expansion through takeovers","B":"Maximising dividend payouts to shareholders","C":"Launching higher-priced exclusive designer ranges","D":"Short-term survival by cutting unnecessary costs"},"correctOption":"D","correctAnswer":"Short-term survival by cutting unnecessary costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because during a slump, demand for expensive non-essential goods collapses, making survival through strict cost control the top priority.","distractor_reasons":{"A":"Incorrect because expensive external growth increases financial risk when revenues and cash flows are severely depressed.","B":"Incorrect because retaining cash inside the business is essential for survival rather than paying large dividends.","C":"Incorrect because consumers have very low disposable incomes during a slump and avoid high-priced luxury goods.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_003","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_003","question":"Country B is experiencing an economic boom with record consumer spending and near-full employment. What is a likely operational challenge for a domestic engineering company during this stage?","options":{"A":"Shortages of skilled workers forcing the firm to offer higher wages","B":"Falling customer orders causing high levels of spare factory capacity","C":"Deflation reducing the selling prices of its engineering products","D":"High levels of cyclical unemployment lowering domestic demand"},"correctOption":"A","correctAnswer":"Shortages of skilled workers forcing the firm to offer higher wages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because during a boom, low unemployment creates labour shortages, forcing businesses to compete for skilled staff by raising wages.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because customer orders and capacity utilisation are typically at their highest during a boom.","C":"Incorrect because high demand during a boom usually causes prices to rise (inflation), not fall (deflation).","D":"Incorrect because unemployment is very low during an economic boom, not high."}}},{"id":"P1_U6_MCQ_004","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_004","question":"Following two years of slow activity, an economy moves into the growth stage of the business cycle as GDP rises and unemployment falls. How is this change most likely to affect a domestic airline?","options":{"A":"Ticket sales will fall as households save a greater share of their income","B":"The airline will have to make pilots redundant due to lower passenger numbers","C":"Demand for leisure and business flights will rise as incomes and confidence grow","D":"The government will immediately impose price ceilings on domestic airfares"},"correctOption":"C","correctAnswer":"Demand for leisure and business flights will rise as incomes and confidence grow","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because rising employment and disposable incomes during the growth stage increase spending on travel and holidays.","distractor_reasons":{"A":"Incorrect because higher consumer confidence during economic growth encourages spending rather than precautionary saving.","B":"Incorrect because rising passenger demand leads to hiring more staff rather than making redundancies.","C":"Correct selection.","D":"Incorrect because economic growth does not automatically trigger government price controls on air travel."}}},{"id":"P1_U6_MCQ_005","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_005","question":"Annual inflation in Country C jumps from 2% to 11%, causing rapid increases in the prices of flour, electricity, and wages. How does this high inflation negatively affect a local bakery?","options":{"A":"Its existing fixed-rate bank loans become more expensive in real terms","B":"Its production costs rise, squeezing profit margins or forcing price increases","C":"Its customers gain higher real purchasing power and buy fewer basic goods","D":"Its exported pastries become cheaper and more competitive in foreign markets"},"correctOption":"B","correctAnswer":"Its production costs rise, squeezing profit margins or forcing price increases","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high inflation raises input costs (materials, energy, wages), reducing profit margins unless prices are raised, which can lower sales.","distractor_reasons":{"A":"Incorrect because fixed-rate debt repayments actually become smaller in real terms when prices and revenues inflate.","B":"Correct selection.","C":"Incorrect because high inflation reduces consumers' real purchasing power if wages do not keep pace with rising prices.","D":"Incorrect because higher domestic inflation makes a country's exports more expensive and less competitive abroad."}}},{"id":"P1_U6_MCQ_006","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_006","question":"Government policies successfully reduce unemployment in Country D from 9% to 4% over eighteen months. What is a direct benefit of this change for a national supermarket chain?","options":{"A":"Higher total consumer spending increases supermarket sales revenue","B":"Recruiting low-skilled warehouse workers becomes much easier and cheaper","C":"Consumers switch exclusively from branded groceries to cheaper basic items","D":"The supermarket no longer needs to offer competitive prices to attract shoppers"},"correctOption":"A","correctAnswer":"Higher total consumer spending increases supermarket sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because more people earning wages increases household disposable income and total spending in retail stores.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower unemployment shrinks the pool of available job seekers, making recruitment harder and pushing wages up.","C":"Incorrect because higher employment raises incomes, often encouraging shoppers to buy more premium or branded goods.","D":"Incorrect because competition among supermarkets remains strong regardless of lower national unemployment."}}},{"id":"P1_U6_MCQ_007","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_007","question":"A government announces that its primary macroeconomic objective for the next five years is to achieve steady economic growth. How is economic growth measured in an economy?","options":{"A":"By a fall in the annual Consumer Price Index (CPI)","B":"By an increase in the total value of imported consumer goods","C":"By a rise in the central bank's base interest rate","D":"By an increase in the total value of goods and services produced (GDP)"},"correctOption":"D","correctAnswer":"By an increase in the total value of goods and services produced (GDP)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because economic growth is defined as an increase in a country's Gross Domestic Product (GDP), the total value of output produced in a year.","distractor_reasons":{"A":"Incorrect because changes in the CPI measure inflation, not economic growth.","B":"Incorrect because rising imports alone worsen the balance of payments and do not measure domestic production.","C":"Incorrect because interest rates are a monetary policy tool, not a measure of economic output.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_008","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_008","question":"To reduce a government budget deficit, the finance minister increases personal income tax rates across all income brackets. How will this fiscal policy change affect a manufacturer of luxury sports watches?","options":{"A":"Production costs will rise directly because income tax is paid out of company profits","B":"Sales will increase as higher-income earners buy more watches to avoid paying tax","C":"Demand will fall because consumers have less disposable income to spend on luxuries","D":"Export prices will automatically rise due to higher personal taxation"},"correctOption":"C","correctAnswer":"Demand will fall because consumers have less disposable income to spend on luxuries","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because income tax is a direct tax on individuals' earnings; raising it reduces disposable income and lowers demand for luxury items.","distractor_reasons":{"A":"Incorrect because tax on company profits is corporation tax, whereas income tax is levied on individuals' wages and salaries.","B":"Incorrect because buying luxury watches does not exempt individuals from paying income tax on their earnings.","C":"Correct selection.","D":"Incorrect because personal income tax does not directly alter export prices or exchange rates."}}},{"id":"P1_U6_MCQ_009","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_009","question":"A government reduces the rate of corporation tax from 28% to 19% to encourage private sector investment. What is the immediate effect of this change on profitable limited companies?","options":{"A":"Their sales revenue increases immediately due to lower retail prices","B":"They retain more profit after tax to reinvest in expansion or pay dividends","C":"Their variable costs of raw materials fall by 9%","D":"Their employees receive a 9% increase in net take-home pay"},"correctOption":"B","correctAnswer":"They retain more profit after tax to reinvest in expansion or pay dividends","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because corporation tax is a direct tax on company profits; lowering it leaves businesses with higher retained profit after tax.","distractor_reasons":{"A":"Incorrect because corporation tax is charged on profit rather than on the selling price of products (which would be an indirect tax).","B":"Correct selection.","C":"Incorrect because corporation tax does not alter the cost of raw materials or variable production expenses.","D":"Incorrect because employees' take-home pay is affected by personal income tax, not corporation tax."}}},{"id":"P1_U6_MCQ_010","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_010","question":"The government introduces a new 15% indirect tax (sales tax) on carbonated soft drinks to discourage unhealthy consumption. How is this tax likely to affect soft drink producers?","options":{"A":"Retail prices will rise, reducing sales volume unless producers absorb the tax","B":"The tax will only be paid by companies that make a net profit at year-end","C":"Production efficiency will improve automatically due to lower fixed costs","D":"Consumer demand will remain unchanged because indirect taxes do not affect prices"},"correctOption":"A","correctAnswer":"Retail prices will rise, reducing sales volume unless producers absorb the tax","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an indirect tax is added to the price of goods; passing it to consumers raises prices and reduces demand, while absorbing it lowers profit margins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because indirect taxes are levied on sales transactions regardless of whether the business makes a profit (unlike corporation tax).","C":"Incorrect because a sales tax does not reduce a firm's fixed production costs or improve efficiency.","D":"Incorrect because indirect taxes directly increase the final price paid by consumers."}}},{"id":"P1_U6_MCQ_011","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_011","question":"During an economic downturn, a government increases public spending by $10 billion to build new highways, bridges, and high-speed rail networks. Which businesses benefit most directly from this policy?","options":{"A":"Foreign luxury car importers","B":"Private healthcare insurance providers","C":"Domestic construction firms and building material suppliers","D":"Local hairdressers and beauty salons"},"correctOption":"C","correctAnswer":"Domestic construction firms and building material suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because government infrastructure projects directly award contracts to construction companies and boost demand for cement, steel, and aggregates.","distractor_reasons":{"A":"Incorrect because infrastructure spending does not directly target luxury car imports.","B":"Incorrect because transport infrastructure investment does not directly fund private health insurance.","C":"Correct selection.","D":"Incorrect because personal service businesses only benefit indirectly later if workers spend their wages locally."}}},{"id":"P1_U6_MCQ_012","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_012","question":"To control national debt, a government announces substantial cuts in public sector spending on state schools and public hospitals. How will this affect a domestic business that manufactures medical equipment and school furniture?","options":{"A":"Its corporation tax rate will automatically increase","B":"Its borrowing costs will fall due to higher interest rates","C":"Its export sales will be banned by the Ministry of Finance","D":"Its domestic sales revenue will fall due to fewer government contracts"},"correctOption":"D","correctAnswer":"Its domestic sales revenue will fall due to fewer government contracts","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because state schools and public hospitals are funded by government spending; budget cuts reduce their orders for furniture and medical equipment.","distractor_reasons":{"A":"Incorrect because cutting government expenditure is separate from changing corporation tax rates.","B":"Incorrect because higher interest rates increase borrowing costs rather than lower them.","C":"Incorrect because domestic budget cuts do not ban private businesses from exporting abroad.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_013","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_013","question":"In response to rising inflation, a country's central bank raises interest rates from 3% to 6.5%. How does this monetary policy decision affect a manufacturing business planning to borrow $2 million to buy automated machinery?","options":{"A":"The cost of borrowing decreases, making the machinery cheaper to finance","B":"Interest repayments rise, reducing the expected profitability of the investment","C":"The business will receive a government grant to cover the extra interest","D":"Consumers will borrow more money, increasing demand for manufactured goods"},"correctOption":"B","correctAnswer":"Interest repayments rise, reducing the expected profitability of the investment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher interest rates increase the cost of borrowing, raising loan repayments and making capital investment projects less profitable.","distractor_reasons":{"A":"Incorrect because higher interest rates make borrowing more expensive, not cheaper.","B":"Correct selection.","C":"Incorrect because central bank interest rate hikes do not automatically come with government grants.","D":"Incorrect because higher interest rates discourage consumers from borrowing and encourage saving instead."}}},{"id":"P1_U6_MCQ_014","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_014","question":"A central bank lowers interest rates from 5% to 1.5% to stimulate a sluggish economy. Why is a residential housebuilding company likely to see an increase in demand for new homes?","options":{"A":"Lower mortgage interest rates make monthly home loan repayments more affordable","B":"Higher interest returns on bank deposits encourage families to save instead of buying","C":"Income tax rates automatically fall whenever the central bank cuts interest rates","D":"Building materials become cheaper because tariffs are removed"},"correctOption":"A","correctAnswer":"Lower mortgage interest rates make monthly home loan repayments more affordable","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because most homes are bought using mortgages; lower interest rates reduce monthly mortgage costs, boosting housing demand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower interest rates reduce the reward for saving, encouraging spending rather than saving.","C":"Incorrect because income tax is controlled by government fiscal policy, not central bank monetary policy.","D":"Incorrect because interest rate cuts do not remove import tariffs on building materials."}}},{"id":"P1_U6_MCQ_015","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_015","question":"A private limited company earns an annual profit before tax of $250,000. The government increases the rate of corporation tax from 20% to 24%. How much additional tax will the company have to pay?","options":{"A":"$60,000","B":"$50,000","C":"$10,000","D":"$4,000"},"correctOption":"C","correctAnswer":"$10,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because at 20%, tax is $50,000 ($250,000 × 0.20), and at 24%, tax is $60,000 ($250,000 × 0.24), resulting in $10,000 of additional tax.","distractor_reasons":{"A":"Incorrect because $60,000 is the total new tax bill, not the additional tax caused by the 4% increase.","B":"Incorrect because $50,000 was the original tax paid at the 20% rate.","C":"Correct selection.","D":"Incorrect because $4,000 is 4% of $100,000 rather than 4% of $250,000."}}},{"id":"P1_U6_MCQ_016","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_016","question":"Following a sharp rise in central bank interest rates, a profitable retail chain still wants to open three new stores this year. What is the most sensible financial response for the retail chain?","options":{"A":"Take out a large variable-rate bank overdraft to fund the entire expansion","B":"Increase selling prices by 30% while consumer spending is falling","C":"Sell shares to the general public as a sole trader","D":"Use internal retained profits instead of bank loans to finance the new stores"},"correctOption":"D","correctAnswer":"Use internal retained profits instead of bank loans to finance the new stores","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because using retained profit avoids expensive interest payments on external loans when interest rates are high.","distractor_reasons":{"A":"Incorrect because bank overdrafts carry high variable interest rates and are unsuitable for long-term store expansion.","B":"Incorrect because raising prices sharply when high interest rates are already squeezing consumer budgets would cause sales to collapse.","C":"Incorrect because a retail chain is a company, and sole traders cannot issue shares to the public.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_017","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_017","question":"The government raises income tax and sales tax (VAT), causing household disposable incomes to fall across the country. How might a clothing retailer best respond to maintain its sales volume?","options":{"A":"Focus exclusively on high-priced designer eveningwear","B":"Introduce a range of lower-priced, value-for-money everyday clothing","C":"Close its online store and rely solely on expensive city-centre boutiques","D":"Increase its marketing budget for luxury silk garments"},"correctOption":"B","correctAnswer":"Introduce a range of lower-priced, value-for-money everyday clothing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when higher taxes reduce disposable income, consumers become more price-sensitive and switch to affordable, value-for-money items.","distractor_reasons":{"A":"Incorrect because demand for high-priced luxury clothing falls sharply when disposable incomes drop.","B":"Correct selection.","C":"Incorrect because increasing fixed rent overheads while closing lower-cost online channels worsens profitability during a downturn.","D":"Incorrect because promoting expensive luxury fabrics ignores the drop in consumer purchasing power."}}},{"id":"P1_U6_MCQ_018","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_018","question":"A car dealership sells 75% of its vehicles to customers using bank loans and hire purchase agreements. Why is this business particularly vulnerable to an increase in interest rates?","options":{"A":"Higher interest rates increase monthly credit repayments, deterring car buyers","B":"Higher interest rates reduce the value of the dealership's existing car inventory","C":"Higher interest rates automatically increase import tariffs on foreign cars","D":"Higher interest rates lower the wages paid to dealership mechanics"},"correctOption":"A","correctAnswer":"Higher interest rates increase monthly credit repayments, deterring car buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expensive consumer durables like cars are commonly purchased on credit; higher interest rates make financing much costlier for buyers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because interest rate changes do not directly reduce the physical value of vehicles in stock.","C":"Incorrect because tariffs are trade taxes set by government, not consequences of interest rate changes.","D":"Incorrect because higher interest rates do not reduce existing employee wage rates."}}},{"id":"P1_U6_MCQ_019","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_019","question":"A government decides to shift its tax system by lowering direct taxes while increasing indirect taxes. Which pair of policy changes accurately reflects this decision?","options":{"A":"Raising corporation tax and lowering Value Added Tax (VAT)","B":"Raising personal income tax and lowering import tariffs","C":"Lowering Value Added Tax (VAT) and raising excise duties on fuel","D":"Lowering personal income tax and raising Value Added Tax (VAT)"},"correctOption":"D","correctAnswer":"Lowering personal income tax and raising Value Added Tax (VAT)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because income tax is a direct tax on earnings, while Value Added Tax (VAT) is an indirect tax on spending on goods and services.","distractor_reasons":{"A":"Incorrect because this raises a direct tax (corporation tax) and lowers an indirect tax (VAT), the exact opposite of the policy.","B":"Incorrect because this raises a direct tax (income tax) and lowers an indirect tax (import tariffs).","C":"Incorrect because both VAT and excise duties are indirect taxes on expenditure.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_020","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_020","question":"After years of erratic price rises, a central bank successfully stabilises annual inflation at a low rate of 2%. How does low and stable inflation benefit a commercial construction company?","options":{"A":"It eliminates all competition from foreign construction firms","B":"It guarantees that government spending on infrastructure will double","C":"It allows more accurate forecasting of future material costs when bidding for contracts","D":"It ensures that employees will never ask for pay rises"},"correctOption":"C","correctAnswer":"It allows more accurate forecasting of future material costs when bidding for contracts","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because stable, predictable inflation reduces uncertainty about future raw material and labour costs, helping firms price long-term contracts accurately.","distractor_reasons":{"A":"Incorrect because low domestic inflation makes domestic firms more competitive, but it does not ban foreign competitors.","B":"Incorrect because price stability does not guarantee an increase in government infrastructure spending.","C":"Correct selection.","D":"Incorrect because workers still seek modest wage increases to match the 2% inflation rate."}}},{"id":"P1_U6_MCQ_021","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_021","question":"Country E imports $90 billion worth of goods and services while exporting only $65 billion, creating a persistent balance of payments deficit. Which government action might be taken to correct this imbalance?","options":{"A":"Increasing corporation tax exclusively on domestic exporters","B":"Introducing import tariffs or offering grants to boost domestic exporting firms","C":"Encouraging consumers to buy more foreign luxury products","D":"Raising the legal minimum wage to increase production costs for exporters"},"correctOption":"B","correctAnswer":"Introducing import tariffs or offering grants to boost domestic exporting firms","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because discouraging imports (via tariffs) and supporting domestic exporters helps reduce a balance of payments current account deficit.","distractor_reasons":{"A":"Incorrect because taxing exporters would reduce exports further and worsen the deficit.","B":"Correct selection.","C":"Incorrect because increasing imports would widen the trade deficit even further.","D":"Incorrect because raising production costs makes domestic firms less competitive against foreign rivals."}}},{"id":"P1_U6_MCQ_022","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_022","question":"During an economic downturn, national unemployment rises from 4% to 10%. Why might a budget fast-food restaurant chain experience some operational benefits during this period?","options":{"A":"Bank interest rates will automatically rise to 15%","B":"Consumers will eat out more frequently at expensive fine-dining restaurants","C":"Government corporation tax rates will drop to zero for all restaurants","D":"It is easier to recruit staff without raising wages, and diners switch from costly restaurants"},"correctOption":"D","correctAnswer":"It is easier to recruit staff without raising wages, and diners switch from costly restaurants","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because higher unemployment increases the supply of job applicants (reducing wage pressure) and prompts budget-conscious consumers to switch from expensive restaurants to cheaper fast food.","distractor_reasons":{"A":"Incorrect because central banks typically lower, rather than raise, interest rates during an economic downturn.","B":"Incorrect because falling incomes reduce spending at expensive fine-dining restaurants.","C":"Incorrect because governments do not eliminate corporation tax during downturns as they still need tax revenue.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_023","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_023","question":"To pull the economy out of a recession, a government decides to use expansionary fiscal policy. Which combination of policies represents expansionary fiscal policy?","options":{"A":"Cutting income tax rates and increasing government spending","B":"Raising interest rates and reducing the money supply","C":"Increasing corporation tax and cutting public infrastructure budgets","D":"Raising Value Added Tax (VAT) and increasing interest rates"},"correctOption":"A","correctAnswer":"Cutting income tax rates and increasing government spending","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fiscal policy involves taxation and government spending; cutting taxes and raising public spending boosts total demand in the economy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because interest rates and money supply are instruments of contractionary monetary policy, not expansionary fiscal policy.","C":"Incorrect because higher taxes and lower government spending reduce total demand (contractionary fiscal policy).","D":"Incorrect because raising VAT reduces consumer spending and interest rates are a monetary policy tool."}}},{"id":"P1_U6_MCQ_024","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_024","question":"A logistics company financed its fleet of 50 delivery trucks using long-term variable-rate bank loans. If the central bank raises interest rates by 3 percentage points, what is the immediate impact on the company's income statement?","options":{"A":"Gross profit rises because fuel costs decrease","B":"Sales revenue increases automatically due to higher freight charges","C":"Finance expenses increase, reducing profit before tax","D":"Current assets increase due to higher cash balances"},"correctOption":"C","correctAnswer":"Finance expenses increase, reducing profit before tax","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because higher interest rates increase the interest payable on variable-rate bank loans, raising expenses and lowering profit.","distractor_reasons":{"A":"Incorrect because interest rate changes do not reduce fuel costs or alter gross profit.","B":"Incorrect because higher interest rates do not automatically increase customer demand or revenue.","C":"Correct selection.","D":"Incorrect because higher loan repayments cause greater cash outflows, reducing rather than increasing cash balances."}}},{"id":"P1_U6_MCQ_025","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_025","question":"The government raises the indirect sales tax on smartphones from 10% to 20% in a highly competitive market. If a smartphone manufacturer decides to absorb the tax increase rather than raise its retail price, what will happen?","options":{"A":"Its fixed factory rent will increase by 10%","B":"Its profit margin per smartphone sold will decrease","C":"Its customers will pay 10% more at the checkout","D":"Its total revenue will increase by 10%"},"correctOption":"B","correctAnswer":"Its profit margin per smartphone sold will decrease","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because absorbing an indirect tax means keeping the final retail price unchanged while paying a larger tax amount per unit to the government, reducing profit per unit.","distractor_reasons":{"A":"Incorrect because sales taxes apply to product sales, not commercial property rents.","B":"Correct selection.","C":"Incorrect because absorbing the tax means the manufacturer does not pass the increase on to customers.","D":"Incorrect because if selling prices and sales volume remain unchanged, revenue does not increase."}}},{"id":"P1_U6_MCQ_026","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_026","question":"Over the past twenty years, businesses worldwide have increasingly sourced components from abroad, operated factories in multiple countries, and sold products to global consumers. Which term best describes this trend?","options":{"A":"Protectionism","B":"Nationalisation","C":"Globalisation","D":"Privatisation"},"correctOption":"C","correctAnswer":"Globalisation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because globalisation refers to the increasing interconnectedness and integration of world economies through international trade, investment, and production.","distractor_reasons":{"A":"Incorrect because protectionism involves government restrictions (such as tariffs and quotas) designed to limit international trade.","B":"Incorrect because nationalisation is the transfer of private sector businesses into state ownership.","C":"Correct selection.","D":"Incorrect because privatisation is the sale of state-owned enterprises to the private sector."}}},{"id":"P1_U6_MCQ_027","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_027","question":"A software firm in India provides 24-hour technical support and accounting services for retail companies located in the UK and USA. Which factor has most enabled this global business model?","options":{"A":"Advances in high-speed internet and digital communication technology","B":"Increases in import tariffs on physical goods","C":"Higher corporate tax rates in newly industrialised countries","D":"Strict import quotas on foreign software engineers"},"correctOption":"A","correctAnswer":"Advances in high-speed internet and digital communication technology","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because improvements in telecommunications, cloud computing, and the internet allow services to be delivered instantly across borders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because import tariffs restrict trade rather than enabling cross-border services.","C":"Incorrect because higher taxes would discourage rather than facilitate international outsourcing.","D":"Incorrect because quotas restrict trade flows and do not explain remote digital service delivery."}}},{"id":"P1_U6_MCQ_028","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_028","question":"A medium-sized biscuit manufacturer in Country X starts exporting its products to five fast-growing Asian economies due to globalisation. What is a major benefit of this strategy for the manufacturer?","options":{"A":"It eliminates all cultural and packaging differences between markets","B":"It avoids all transport and shipping costs","C":"It guarantees a monopoly position in every foreign country","D":"It increases total potential sales and spreads risk if Country X enters a recession"},"correctOption":"D","correctAnswer":"It increases total potential sales and spreads risk if Country X enters a recession","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because entering international markets expands the customer base and reduces dependence on a single domestic economy.","distractor_reasons":{"A":"Incorrect because businesses must adapt packaging, ingredients, and marketing to suit different local cultures.","B":"Incorrect because exporting goods abroad increases shipping and logistics expenses.","C":"Incorrect because global markets usually involve intense competition from both local and international rivals.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_029","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_029","question":"Following the removal of trade barriers, low-cost foreign furniture manufacturers begin selling flat-pack furniture online to consumers in Country Y. What is the main threat this poses to traditional furniture makers in Country Y?","options":{"A":"Domestic raw materials will become completely unavailable","B":"Increased price competition may reduce their market share and profit margins","C":"The government of Country Y will ban domestic furniture production","D":"Local consumers will stop buying furniture altogether"},"correctOption":"B","correctAnswer":"Increased price competition may reduce their market share and profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because globalisation exposes domestic firms to foreign competitors who may have lower production costs, threatening domestic sales and profitability.","distractor_reasons":{"A":"Incorrect because foreign competition in finished furniture does not eliminate local timber supplies.","B":"Correct selection.","C":"Incorrect because free trade allows competition rather than banning domestic producers.","D":"Incorrect because consumers still buy furniture, but may switch to cheaper imported brands."}}},{"id":"P1_U6_MCQ_030","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_030","question":"Countries X, Y, and Z sign a regional free trade agreement removing all customs duties and volume restrictions on goods traded between them. How does this benefit a car parts producer in Country X?","options":{"A":"Its products face higher taxes when sold in Country Y","B":"It is legally protected from any competition from firms in Country Z","C":"It can export components to car factories in Countries Y and Z without paying tariffs","D":"All three countries automatically adopt a single shared currency"},"correctOption":"C","correctAnswer":"It can export components to car factories in Countries Y and Z without paying tariffs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because free trade agreements eliminate tariffs and quotas between member states, making exports cheaper and more competitive within the bloc.","distractor_reasons":{"A":"Incorrect because free trade removes customs duties (tariffs) rather than increasing them.","B":"Incorrect because free trade increases competition among member countries rather than protecting firms from rivals.","C":"Correct selection.","D":"Incorrect because a free trade agreement removes trade barriers and does not automatically create a currency union."}}},{"id":"P1_U6_MCQ_031","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_031","question":"To protect domestic steelmakers from cheap foreign steel, the government of Country A imposes a 25% tax on all imported steel. What is this trade restriction called?","options":{"A":"An import quota","B":"An import tariff","C":"An export subsidy","D":"A currency depreciation"},"correctOption":"B","correctAnswer":"An import tariff","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an import tariff is a tax levied by a government on imported goods, raising their price in the domestic market.","distractor_reasons":{"A":"Incorrect because an import quota is a physical limit on the quantity of goods imported, not a percentage tax.","B":"Correct selection.","C":"Incorrect because an export subsidy is a government payment to domestic exporters to lower their prices abroad.","D":"Incorrect because currency depreciation is a fall in the exchange rate value of a currency."}}},{"id":"P1_U6_MCQ_032","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_032","question":"The government of Country B rules that no more than 50,000 foreign-manufactured cars may be imported into the country each year. What is this trade barrier known as?","options":{"A":"An import tariff","B":"A free trade agreement","C":"A corporation tax","D":"An import quota"},"correctOption":"D","correctAnswer":"An import quota","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an import quota places a strict physical limit on the maximum quantity of a product that can be imported during a given period.","distractor_reasons":{"A":"Incorrect because a tariff is a tax on imports rather than a numerical limit on quantity.","B":"Incorrect because free trade agreements remove trade barriers rather than restrict import volumes.","C":"Incorrect because corporation tax is a direct tax on business profits.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_033","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_033","question":"A government introduces a high import tariff on imported aluminium to protect local mining companies. How does this decision negatively affect a domestic manufacturer of aluminium cans?","options":{"A":"Its raw material costs rise, making its cans more expensive and less competitive","B":"It can no longer sell any aluminium cans to domestic beverage companies","C":"Its labour productivity immediately falls by 50%","D":"It is forced to relocate its headquarters to a foreign country"},"correctOption":"A","correctAnswer":"Its raw material costs rise, making its cans more expensive and less competitive","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because if a domestic manufacturer relies on imported aluminium, a tariff raises its input costs and reduces its competitiveness.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a tariff raises the cost of imported inputs but does not ban domestic sales of finished cans.","C":"Incorrect because trade taxes affect material costs rather than workers' physical productivity.","D":"Incorrect because higher material costs may reduce profits, but do not legally force headquarters relocation."}}},{"id":"P1_U6_MCQ_034","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_034","question":"A government wants to protect its domestic textile industry from foreign imports while also raising extra tax revenue to fund public infrastructure. Which policy measure achieves both aims?","options":{"A":"Imposing a strict import quota on foreign textiles","B":"Signing a bilateral free trade agreement","C":"Introducing an import tariff on foreign textiles","D":"Encouraging domestic consumers to buy imported clothing"},"correctOption":"C","correctAnswer":"Introducing an import tariff on foreign textiles","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an import tariff raises the price of imports (protecting local producers) and generates customs tax revenue for the government.","distractor_reasons":{"A":"Incorrect because an import quota restricts the volume of imports without directly collecting tax revenue for the government.","B":"Incorrect because free trade removes tariffs and reduces protection for domestic producers.","C":"Correct selection.","D":"Incorrect because encouraging imports harms domestic textile manufacturers."}}},{"id":"P1_U6_MCQ_035","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_035","question":"TechGlobal plc operates a research centre in Germany, assembly plants in Vietnam and Mexico, and retail stores across 30 countries. Why is TechGlobal plc classified as a multinational company (MNC)?","options":{"A":"Because it exports its finished goods to customers in more than one country","B":"Because it is owned jointly by several national governments","C":"Because its shares are listed on a domestic stock exchange","D":"Because it has production or service operations located in more than one country"},"correctOption":"D","correctAnswer":"Because it has production or service operations located in more than one country","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a multinational company (MNC) is defined as a business with factories, offices, or operations in more than one country.","distractor_reasons":{"A":"Incorrect because a purely domestic firm that simply exports products abroad is an exporter, not an MNC.","B":"Incorrect because MNCs are private sector companies, not state-owned international bodies.","C":"Incorrect because stock exchange listing makes a firm a public limited company, not necessarily an MNC.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_036","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_036","question":"Country Z imposes a 30% import tariff on all foreign-built cars. To overcome this barrier, a Japanese car manufacturer builds a new assembly plant inside Country Z. What is the primary benefit of becoming an MNC in this case?","options":{"A":"Avoiding import tariffs and reducing transport costs to customers in Country Z","B":"Eliminating the need to comply with Country Z's employment laws","C":"Ensuring zero competition from any other car manufacturers","D":"Avoiding all corporation taxes globally"},"correctOption":"A","correctAnswer":"Avoiding import tariffs and reducing transport costs to customers in Country Z","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because producing vehicles inside Country Z means they are no longer imports, avoiding the 30% tariff and lowering shipping costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because MNCs must obey the local labour and safety laws of every host country in which they operate.","C":"Incorrect because locating locally still involves competing against domestic and other foreign brands.","D":"Incorrect because MNCs are still liable to pay corporation taxes in the countries where they earn profits."}}},{"id":"P1_U6_MCQ_037","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_037","question":"A European electronics manufacturer decides to establish a new assembly factory in a newly industrialised country. Apart from avoiding trade barriers, what is a key cost advantage of locating there?","options":{"A":"Higher average hourly wage rates than in Europe","B":"Lower labour costs and potential government grants for inward investment","C":"Stricter and more expensive environmental regulations","D":"Higher bank interest rates on local loans"},"correctOption":"B","correctAnswer":"Lower labour costs and potential government grants for inward investment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because MNCs frequently locate factories in newly industrialised countries to benefit from lower wage costs, cheaper land, and government incentives.","distractor_reasons":{"A":"Incorrect because wage rates in newly industrialised countries are typically lower, not higher, than in Western Europe.","B":"Correct selection.","C":"Incorrect because higher regulatory costs would be a disadvantage rather than a cost advantage.","D":"Incorrect because higher borrowing costs would deter rather than attract investment."}}},{"id":"P1_U6_MCQ_038","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_038","question":"A domestic appliance maker imports electric motors at a pre-tariff price of $40 per unit. The government introduces a 15% import tariff on electric motors. What is the new cost per motor including the tariff?","options":{"A":"$41.50","B":"$34.00","C":"$46.00","D":"$55.00"},"correctOption":"C","correctAnswer":"$46.00","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a 15% tariff on $40 adds $6 ($40 × 0.15 = $6), bringing the total cost per motor to $46.","distractor_reasons":{"A":"Incorrect because $1.50 is 15% of $10, not 15% of $40.","B":"Incorrect because $34.00 subtracts 15% instead of adding the tariff tax.","C":"Correct selection.","D":"Incorrect because $55.00 adds $15 rather than 15% of $40."}}},{"id":"P1_U6_MCQ_039","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_039","question":"A global pharmaceutical company invests $300 million to build a new production facility in Country M. What is a major advantage of this investment for the host country, Country M?","options":{"A":"Local pharmaceutical firms face less competition in the domestic market","B":"All profits generated by the factory are guaranteed to stay in Country M","C":"The host government no longer needs to collect any taxes","D":"New jobs are created for local workers and tax revenues for the government increase"},"correctOption":"D","correctAnswer":"New jobs are created for local workers and tax revenues for the government increase","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because inward investment by an MNC creates employment, boosts GDP, and increases tax revenue paid to the host government.","distractor_reasons":{"A":"Incorrect because the entry of a large MNC increases competition for local firms rather than reducing it.","B":"Incorrect because MNCs frequently repatriate profits back to their home country.","C":"Incorrect because governments still collect taxes from businesses and workers to fund public services.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_040","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_040","question":"An international smartphone maker sets up a manufacturing plant in Country N and exports 85% of the phones assembled there to neighbouring nations. How does this improve Country N's economy?","options":{"A":"It increases Country N's imports and widens its trade deficit","B":"It increases Country N's exports, improving its balance of payments","C":"It reduces consumer choice in Country N","D":"It eliminates the depletion of all natural resources"},"correctOption":"B","correctAnswer":"It increases Country N's exports, improving its balance of payments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because goods produced locally by an MNC and sold abroad count as exports for the host country, improving its balance of payments.","distractor_reasons":{"A":"Incorrect because exporting 85% of output increases exports rather than imports.","B":"Correct selection.","C":"Incorrect because MNCs typically increase consumer choice by introducing new products.","D":"Incorrect because manufacturing uses energy and raw materials rather than eliminating resource depletion."}}},{"id":"P1_U6_MCQ_041","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_041","question":"Although a foreign-owned supermarket chain generates $80 million in annual profits in Country P, it transfers $70 million back to its headquarters in its home country. Which disadvantage of MNCs does this illustrate?","options":{"A":"Repatriation of profits","B":"Transfer of advanced technology","C":"Increased consumer choice","D":"Creation of local employment"},"correctOption":"A","correctAnswer":"Repatriation of profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because repatriation of profits occurs when an MNC sends profits earned in a host country back to its home country rather than reinvesting them locally.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because technology transfer is a benefit to the host country, not the outflow of profits.","C":"Incorrect because wider product availability is an advantage for host-country shoppers.","D":"Incorrect because job creation is a benefit to the host economy, whereas profit outflow is a drawback."}}},{"id":"P1_U6_MCQ_042","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_042","question":"A large multinational coffee chain opens 40 outlets across Country Q, using its huge purchasing economies of scale to undercut local cafes. What is a likely negative consequence for Country Q?","options":{"A":"Consumers in Country Q have fewer places to buy coffee","B":"Total tax revenue collected by Country Q's government falls to zero","C":"Small local coffee shops may be forced out of business due to intense competition","D":"Foreign investment in Country Q becomes illegal"},"correctOption":"C","correctAnswer":"Small local coffee shops may be forced out of business due to intense competition","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because MNCs have massive financial and marketing resources that can drive smaller domestic businesses out of the market.","distractor_reasons":{"A":"Incorrect because 40 new outlets initially increase consumer choice.","B":"Incorrect because the MNC still pays taxes on its sales and profits in Country Q.","C":"Correct selection.","D":"Incorrect because competition from an MNC does not make foreign investment illegal."}}},{"id":"P1_U6_MCQ_043","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_043","question":"A multinational mining company operates in Country R, extracting rare minerals while employing local workers only in low-paid manual jobs and bringing in senior managers from abroad. Which criticisms of MNCs are shown here?","options":{"A":"High tariffs and import quotas","B":"Improved infrastructure and technology transfer","C":"Rising export revenues and higher consumer choice","D":"Exploitation of natural resources and limited high-skilled jobs for locals"},"correctOption":"D","correctAnswer":"Exploitation of natural resources and limited high-skilled jobs for locals","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because MNCs are often criticised for depleting host-country natural resources and reserving senior, well-paid roles for expatriate staff.","distractor_reasons":{"A":"Incorrect because tariffs and quotas are government trade barriers, not MNC employment or extraction practices.","B":"Incorrect because infrastructure and technology transfer are potential benefits rather than criticisms.","C":"Incorrect because higher exports and choice are advantages to the host country.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_044","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_044","question":"The exchange rate of Country X's currency appreciates sharply against all major foreign currencies. How does this appreciation affect businesses in Country X?","options":{"A":"Exports become cheaper abroad and imports become more expensive domestically","B":"Exports become more expensive abroad and imports become cheaper domestically","C":"Both exports and imports become more expensive","D":"Both exports and imports become cheaper"},"correctOption":"B","correctAnswer":"Exports become more expensive abroad and imports become cheaper domestically","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an appreciating currency buys more foreign currency, making imported goods cheaper in local currency while making exports dearer for foreign buyers.","distractor_reasons":{"A":"Incorrect because this describes the effects of a currency depreciation, not an appreciation.","B":"Correct selection.","C":"Incorrect because exchange rate movements affect export prices and import prices in opposite directions.","D":"Incorrect because an appreciation lowers import prices while raising export prices."}}},{"id":"P1_U6_MCQ_045","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_045","question":"A US manufacturer exports precision tools priced at $500 per set to customers in Germany. If the US dollar appreciates from $1 = €0.80 to $1 = €0.90, what happens to the price paid by German customers in euros?","options":{"A":"It increases from €400 to €450","B":"It decreases from €450 to €400","C":"It increases from €500 to €555","D":"It remains unchanged at €400"},"correctOption":"A","correctAnswer":"It increases from €400 to €450","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at $1 = €0.80, $500 costs €400 ($500 × 0.80), whereas at $1 = €0.90, $500 costs €450 ($500 × 0.90).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the dollar appreciated (bought more euros), so the euro price increased rather than decreased.","C":"Incorrect because €555 divides by 0.90 instead of multiplying $500 by 0.90.","D":"Incorrect because the dollar selling price is fixed at $500, so the euro equivalent rises when the dollar appreciates."}}},{"id":"P1_U6_MCQ_046","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_046","question":"Country Y's currency depreciates by 15% against the US dollar over six months. How does this benefit a domestic software exporter in Country Y that sells most of its products to US businesses?","options":{"A":"Its imported computer hardware becomes 15% cheaper","B":"Its domestic employees automatically accept a 15% pay cut","C":"Its software becomes cheaper in US dollars, boosting price competitiveness and export sales","D":"Its corporation tax liability in Country Y is eliminated"},"correctOption":"C","correctAnswer":"Its software becomes cheaper in US dollars, boosting price competitiveness and export sales","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when a currency depreciates, foreign buyers need less of their own currency to buy the exporter's products, increasing export competitiveness.","distractor_reasons":{"A":"Incorrect because a currency depreciation makes imported hardware more expensive, not cheaper.","B":"Incorrect because exchange rate depreciation does not reduce domestic workers' nominal wages.","C":"Correct selection.","D":"Incorrect because currency movements do not exempt exporters from paying corporation tax."}}},{"id":"P1_U6_MCQ_047","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_047","question":"A bakery in Country Z imports 90% of its wheat and sugar from abroad and sells all its bread locally. Why is a sharp depreciation of Country Z's currency a major problem for this bakery?","options":{"A":"Foreign tourists will stop buying bread in Country Z","B":"Domestic wheat farmers will face lower import tariffs","C":"The bakery's fixed rent payments will double","D":"The cost of imported wheat and sugar rises in local currency, squeezing profit margins"},"correctOption":"D","correctAnswer":"The cost of imported wheat and sugar rises in local currency, squeezing profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a weaker domestic currency requires more local currency to pay for foreign raw materials, increasing variable costs.","distractor_reasons":{"A":"Incorrect because a currency depreciation makes Country Z cheaper for foreign tourists, not more expensive.","B":"Incorrect because exchange rate changes do not alter import tariff rates.","C":"Incorrect because local property rent is agreed in domestic currency and is unaffected by exchange rates.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_048","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_048","question":"A UK printing company imports specialist paper from the USA priced at $12,000. If the British pound depreciates from £1 = $1.50 to £1 = $1.20, how much more does the paper cost the UK company in pounds?","options":{"A":"£1,000","B":"£2,000","C":"£8,000","D":"£10,000"},"correctOption":"B","correctAnswer":"£2,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because at £1 = $1.50, $12,000 costs £8,000 ($12,000 ÷ 1.50), and at £1 = $1.20, $12,000 costs £10,000 ($12,000 ÷ 1.20), an increase of £2,000.","distractor_reasons":{"A":"Incorrect because the difference between £10,000 and £8,000 is £2,000, not £1,000.","B":"Correct selection.","C":"Incorrect because £8,000 was the original cost before the pound depreciated.","D":"Incorrect because £10,000 is the new total cost, not the extra amount paid."}}},{"id":"P1_U6_MCQ_049","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_049","question":"Country A's currency appreciates significantly against other currencies. How is this likely to affect a luxury beach resort located in Country A that relies heavily on international tourists?","options":{"A":"Bookings from overseas tourists will fall because holidays in Country A become more expensive","B":"Bookings from overseas tourists will rise because flights to Country A become cheaper","C":"Domestic staff wages at the resort will fall automatically","D":"Imported food and drinks served at the resort will become much more expensive"},"correctOption":"A","correctAnswer":"Bookings from overseas tourists will fall because holidays in Country A become more expensive","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inbound tourism acts like an export; an appreciating currency makes hotel stays in Country A costlier for foreign visitors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a stronger local currency makes holidays in Country A more expensive, not cheaper, for foreigners.","C":"Incorrect because exchange rate appreciation does not lower domestic wages.","D":"Incorrect because an appreciating currency makes imported food and drinks cheaper in local currency."}}},{"id":"P1_U6_MCQ_050","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_050","question":"An exporting clothing manufacturer in Country B faces a 10% appreciation of its domestic currency, threatening its overseas sales. Which action could the manufacturer take to remain competitive in foreign markets?","options":{"A":"Raise its domestic selling prices by 10% to compensate","B":"Lobby the government to place high tariffs on its own raw material imports","C":"Accept a lower profit margin so its selling price in foreign currency stays unchanged","D":"Stop exporting and rely entirely on a shrinking domestic market"},"correctOption":"C","correctAnswer":"Accept a lower profit margin so its selling price in foreign currency stays unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lowering the domestic export price (absorbing the currency rise via reduced profit margins) keeps the foreign-currency price competitive.","distractor_reasons":{"A":"Incorrect because raising prices would make the clothes even more expensive and further reduce sales.","B":"Incorrect because tariffs on imported raw materials would raise production costs and worsen competitiveness.","C":"Correct selection.","D":"Incorrect because abandoning established export markets completely sacrifices revenue and increases reliance on one market."}}},{"id":"P1_U6_MCQ_051","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_051","question":"A large cement manufacturer relies heavily on coal-fired kilns to power its production process. Which negative environmental impact is directly caused by burning coal in this way?","options":{"A":"Increased biodiversity in surrounding rivers","B":"Reduction in landfill waste","C":"Creation of renewable solar energy","D":"Release of carbon dioxide contributing to global warming"},"correctOption":"D","correctAnswer":"Release of carbon dioxide contributing to global warming","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because burning fossil fuels like coal emits greenhouse gases such as carbon dioxide, driving global warming and climate change.","distractor_reasons":{"A":"Incorrect because industrial emissions and quarrying harm rather than improve local biodiversity.","B":"Incorrect because burning coal produces ash and air pollution rather than reducing landfill waste.","C":"Incorrect because coal is a non-renewable fossil fuel, not a renewable energy source.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_052","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_052","question":"A commercial logging company cuts down large areas of tropical rainforest without planting new trees to replace them. Which environmental problem does this business activity illustrate?","options":{"A":"Noise pollution in urban centres","B":"Depletion of natural resources","C":"Increased use of biodegradable packaging","D":"Generation of external social benefits"},"correctOption":"B","correctAnswer":"Depletion of natural resources","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because harvesting timber faster than forests can regenerate uses up natural resources, leaving less for future generations.","distractor_reasons":{"A":"Incorrect because logging takes place in forests rather than creating urban noise pollution.","B":"Correct selection.","C":"Incorrect because deforestation destroys habitats rather than promoting sustainable packaging.","D":"Incorrect because unreplenished deforestation creates external costs (habitat loss, carbon release), not external benefits."}}},{"id":"P1_U6_MCQ_053","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_053","question":"A chemical factory discharges untreated wastewater into a nearby river, killing fish and destroying the livelihoods of local fishermen. How are the financial losses suffered by the fishermen classified?","options":{"A":"External costs","B":"Private costs","C":"External benefits","D":"Fixed production costs"},"correctOption":"A","correctAnswer":"External costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external costs are negative impacts of a business decision paid by third parties outside the business who receive no compensation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because private costs are the direct expenses paid by the chemical factory itself (e.g., wages, raw materials).","C":"Incorrect because external benefits are positive side effects experienced by society, whereas the fishermen suffer harm.","D":"Incorrect because fixed costs are internal business overheads like rent, not harm imposed on outsiders."}}},{"id":"P1_U6_MCQ_054","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_054","question":"To improve access to its new distribution warehouse, a logistics company pays for a new paved road and street lighting that local residents can also use free of charge. What does the residents' free use of the road represent?","options":{"A":"A private cost to the local community","B":"An external cost of business expansion","C":"An external benefit of a business decision","D":"A variable cost of production"},"correctOption":"C","correctAnswer":"An external benefit of a business decision","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because external benefits are positive spill-over gains enjoyed by the rest of society as a result of a business's activity.","distractor_reasons":{"A":"Incorrect because residents use the road free of charge and did not pay for its construction.","B":"Incorrect because safer, faster travel for residents is a positive benefit, not a cost.","C":"Correct selection.","D":"Incorrect because variable costs are internal expenses that vary with output, not community benefits."}}},{"id":"P1_U6_MCQ_055","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_055","question":"A government evaluates a proposal to build a new coal-fired power station by adding the operator's construction and fuel expenses to the environmental and health costs imposed on nearby citizens. What is the sum of these two figures called?","options":{"A":"Private cost","B":"Social benefit","C":"External benefit","D":"Social cost"},"correctOption":"D","correctAnswer":"Social cost","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because social cost equals private costs (paid by the business) plus external costs (borne by the rest of society).","distractor_reasons":{"A":"Incorrect because private cost includes only the business's own internal expenses, excluding external pollution costs.","B":"Incorrect because social benefit measures total positive gains to the business and society, not total costs.","C":"Incorrect because external benefit refers to positive spill-overs to third parties.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_056","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_056","question":"A pharmaceutical firm develops a vaccine that generates $50 million in sales revenue for the company and saves the public health system $120 million by preventing disease outbreaks. What is the $170 million total gain known as?","options":{"A":"Private benefit","B":"Social benefit","C":"Social cost","D":"External cost"},"correctOption":"B","correctAnswer":"Social benefit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because social benefit equals private benefits ($50 million) plus external benefits ($120 million).","distractor_reasons":{"A":"Incorrect because private benefit is only the $50 million gained directly by the pharmaceutical company.","B":"Correct selection.","C":"Incorrect because social cost measures negative expenses and harms, not positive gains.","D":"Incorrect because external cost refers to negative impacts on third parties."}}},{"id":"P1_U6_MCQ_057","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_057","question":"Before approving a major new airport runway, the government carries out a cost-benefit analysis weighing private and external impacts. Under what condition is the project considered beneficial to society as a whole?","options":{"A":"When private costs exceed private benefits","B":"When external costs are greater than external benefits","C":"When total social benefits exceed total social costs","D":"When the airline company makes a short-term loss"},"correctOption":"C","correctAnswer":"When total social benefits exceed total social costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cost-benefit analysis approves projects where total social benefits (private + external) outweigh total social costs (private + external).","distractor_reasons":{"A":"Incorrect because if private costs exceed private benefits, the business itself makes a loss.","B":"Incorrect because high external costs (such as aircraft noise and emissions) reduce net social welfare.","C":"Correct selection.","D":"Incorrect because a loss-making airline indicates private costs exceed private revenues."}}},{"id":"P1_U6_MCQ_058","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_058","question":"A furniture manufacturer sources timber only from certified forests where new trees are planted for every tree harvested, and powers its factory using solar panels. Which concept best describes this approach?","options":{"A":"Sustainable development","B":"Economies of scale","C":"External growth","D":"Market skimming"},"correctOption":"A","correctAnswer":"Sustainable development","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainable development involves meeting current production needs without depleting resources or harming the environment for future generations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because economies of scale refer to lower average unit costs from larger-scale production.","C":"Incorrect because external growth involves mergers and takeovers with other businesses.","D":"Incorrect because market skimming is a pricing strategy for innovative new products."}}},{"id":"P1_U6_MCQ_059","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_059","question":"A bottled water company faces customer criticism over millions of discarded single-use plastic bottles polluting local beaches. Which action would most effectively reduce its negative environmental impact?","options":{"A":"Increasing TV advertising to promote its existing plastic bottles","B":"Dumping unsold plastic bottles in remote rural areas","C":"Lowering the selling price of bottled water to increase sales volume","D":"Switching to 100% recycled or biodegradable plant-based packaging"},"correctOption":"D","correctAnswer":"Switching to 100% recycled or biodegradable plant-based packaging","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because using recycled or biodegradable materials directly reduces non-recyclable plastic waste and resource depletion.","distractor_reasons":{"A":"Incorrect because advertising does not change the physical environmental damage caused by single-use plastics.","B":"Incorrect because illegal dumping increases environmental pollution and violates legal controls.","C":"Incorrect because increasing sales of single-use plastic bottles worsens plastic waste.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_060","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_060","question":"A large manufacturing plant invests $1.5 million in rooftop solar panels and wind turbines to replace electricity generated from fossil fuels. What is a long-term financial advantage of this investment?","options":{"A":"Initial capital expenditure falls to zero","B":"Ongoing electricity bills fall significantly once the equipment is paid for","C":"The business no longer needs to pay corporation tax","D":"Raw material prices drop immediately"},"correctOption":"B","correctAnswer":"Ongoing electricity bills fall significantly once the equipment is paid for","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because although renewable energy systems have high initial setup costs, solar and wind power generate electricity at very low ongoing operating costs.","distractor_reasons":{"A":"Incorrect because buying and installing solar panels and wind turbines requires high upfront capital investment.","B":"Correct selection.","C":"Incorrect because using renewable energy does not exempt profitable businesses from corporation tax.","D":"Incorrect because renewable electricity lowers energy bills rather than raw material costs."}}},{"id":"P1_U6_MCQ_061","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_061","question":"Even in a country with few environmental regulations, a cosmetics company voluntarily eliminates plastic packaging and invests in carbon-neutral delivery. What is a major commercial reason for taking this decision?","options":{"A":"It guarantees lower production costs in the first month","B":"It eliminates all competition from low-cost rivals","C":"It improves brand image and attracts environmentally conscious customers, boosting sales","D":"It allows the company to ignore consumer protection laws"},"correctOption":"C","correctAnswer":"It improves brand image and attracts environmentally conscious customers, boosting sales","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consumers increasingly prefer eco-friendly brands, enhancing reputation, customer loyalty, and long-term sales.","distractor_reasons":{"A":"Incorrect because sustainable packaging and carbon-neutral delivery usually increase short-term costs.","B":"Incorrect because low-cost rivals can still compete on price.","C":"Correct selection.","D":"Incorrect because environmental initiatives do not exempt a firm from consumer protection laws."}}},{"id":"P1_U6_MCQ_062","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_062","question":"A factory incurs private production costs of $400,000 per month while emitting smoke that causes $85,000 per month in external health and cleaning costs to the local community. What is the monthly social cost of the factory's production?","options":{"A":"$485,000","B":"$315,000","C":"$85,000","D":"$400,000"},"correctOption":"A","correctAnswer":"$485,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social cost is the sum of private costs ($400,000) and external costs ($85,000), which equals $485,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $315,000 subtracts external costs from private costs instead of adding them.","C":"Incorrect because $85,000 represents only the external cost, omitting private costs.","D":"Incorrect because $400,000 represents only the private cost, omitting external costs."}}},{"id":"P1_U6_MCQ_063","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_063","question":"A clothing manufacturer wants to switch entirely to organic cotton and non-toxic dyes, which cost 20% more than conventional materials. What is the main short-term disadvantage of becoming more environmentally friendly in this way?","options":{"A":"Employees will become less motivated and leave the firm","B":"The government will fine the business for using organic materials","C":"Brand image will deteriorate among eco-friendly shoppers","D":"Higher material costs will either reduce profit margins or force higher selling prices"},"correctOption":"D","correctAnswer":"Higher material costs will either reduce profit margins or force higher selling prices","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because eco-friendly inputs and cleaner processes often raise unit costs in the short term, squeezing profits or reducing price competitiveness.","distractor_reasons":{"A":"Incorrect because working for an environmentally responsible firm usually improves employee pride and retention.","B":"Incorrect because governments encourage rather than penalise sustainable materials.","C":"Incorrect because using organic materials enhances brand image among green consumers.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_064","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_064","question":"To stop factories from polluting local waterways, a government passes a law setting strict maximum limits on toxic waste discharges and imposing heavy fines on offenders. How does this legal control affect businesses?","options":{"A":"Businesses can freely dump waste as long as they pay dividends to shareholders","B":"Businesses must invest in filtration equipment or cleaner processes, increasing compliance costs","C":"Businesses are no longer allowed to manufacture any chemical products","D":"Businesses receive automatic subsidies equal to 100% of their operating costs"},"correctOption":"B","correctAnswer":"Businesses must invest in filtration equipment or cleaner processes, increasing compliance costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because environmental legal controls force firms to change how they produce (e.g., installing waste treatment systems), raising production costs.","distractor_reasons":{"A":"Incorrect because legal limits apply to all firms regardless of dividend payments.","B":"Correct selection.","C":"Incorrect because pollution limits regulate waste disposal methods rather than banning chemical manufacturing entirely.","D":"Incorrect because legal regulations impose compliance obligations rather than automatic 100% cost subsidies."}}},{"id":"P1_U6_MCQ_065","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_065","question":"Local planning laws prohibit heavy manufacturing plants and noisy 24-hour distribution depots from operating within 5 kilometres of residential housing or national parks. Which business decision is directly restricted by this environmental law?","options":{"A":"Which pricing method to use for finished goods","B":"Whether to recruit internal or external managers","C":"Where a business can locate its operations","D":"How to calculate the acid test liquidity ratio"},"correctOption":"C","correctAnswer":"Where a business can locate its operations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because environmental zoning and planning controls directly dictate where polluting or noisy businesses are permitted to locate.","distractor_reasons":{"A":"Incorrect because zoning regulations restrict physical location rather than pricing strategies.","B":"Incorrect because location controls do not govern HR recruitment methods.","C":"Correct selection.","D":"Incorrect because accounting formulas are unaffected by land-use planning laws."}}},{"id":"P1_U6_MCQ_066","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_066","question":"The government passes legislation banning the manufacture and sale of single-use plastic straws and non-recyclable foam food containers. Which aspect of business activity does this legal control directly affect?","options":{"A":"What products and packaging materials businesses are allowed to produce and sell","B":"The rate of interest banks charge on business overdrafts","C":"The exchange rate between the domestic currency and the euro","D":"The minimum age at which shareholders can vote at an AGM"},"correctOption":"A","correctAnswer":"What products and packaging materials businesses are allowed to produce and sell","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because product bans legally restrict what goods or packaging materials businesses can manufacture and sell.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because environmental product bans do not control bank interest rates.","C":"Incorrect because product regulations do not determine foreign exchange rates.","D":"Incorrect because company governance rules are unrelated to plastic bans."}}},{"id":"P1_U6_MCQ_067","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_067","question":"A government introduces a high landfill tax charged per tonne of commercial waste dumped by businesses. What is the intended effect of this tax on business behaviour?","options":{"A":"To encourage businesses to throw away more unsold inventory","B":"To lower the cost of using non-recyclable packaging","C":"To force all manufacturing businesses to close down","D":"To create a financial incentive for businesses to reduce waste and recycle more"},"correctOption":"D","correctAnswer":"To create a financial incentive for businesses to reduce waste and recycle more","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because taxing landfill disposal makes waste expensive, encouraging firms to minimise waste, reuse materials, and recycle.","distractor_reasons":{"A":"Incorrect because higher disposal taxes penalise throwing away waste rather than encouraging it.","B":"Incorrect because non-recyclable packaging ends up in landfill and becomes more expensive to dispose of.","C":"Incorrect because the tax aims to change production and waste habits, not shut down industry.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_068","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_068","question":"Under a government pollution permit scheme, factories are issued permits allowing a set amount of carbon emissions, and firms that pollute less can sell their spare permits to other businesses. How does this system reward sustainable firms?","options":{"A":"They are exempt from paying employee wages","B":"They can generate extra revenue by selling unused permits to higher-polluting firms","C":"They receive an automatic monopoly in their industry","D":"They no longer need to follow health and safety laws"},"correctOption":"B","correctAnswer":"They can generate extra revenue by selling unused permits to higher-polluting firms","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because tradable pollution permits create a financial reward for cleaner businesses that cut emissions below their allowance and sell excess permits.","distractor_reasons":{"A":"Incorrect because emission permits do not affect wage obligations to employees.","B":"Correct selection.","C":"Incorrect because permit trading does not grant monopoly rights.","D":"Incorrect because workplace health and safety laws still apply fully."}}},{"id":"P1_U6_MCQ_069","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_069","question":"A dairy company collects used glass milk bottles from customers, washes and sterilises them, and refills them with fresh milk without melting the glass down. Which sustainable practice is the company using?","options":{"A":"Recycling","B":"Depletion of resources","C":"Reusing","D":"Incineration"},"correctOption":"C","correctAnswer":"Reusing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because reusing means using an item again for the same or another purpose without breaking it down and reprocessing the raw material.","distractor_reasons":{"A":"Incorrect because recycling involves breaking down and reprocessing used materials (e.g., melting glass) to manufacture new products.","B":"Incorrect because reusing bottles conserves raw materials rather than depleting them.","C":"Correct selection.","D":"Incorrect because incineration involves burning waste rather than refilling containers."}}},{"id":"P1_U6_MCQ_070","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_070","question":"The local community demands that a metal refinery install expensive air filters to stop smoke pollution, while shareholders demand higher dividend payouts this year. What does this situation illustrate?","options":{"A":"A conflict between the objectives of different stakeholder groups","B":"A reduction in external costs through higher profits","C":"A fall in fixed costs caused by environmental regulation","D":"An external benefit enjoyed by shareholders"},"correctOption":"A","correctAnswer":"A conflict between the objectives of different stakeholder groups","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal stakeholders (shareholders wanting short-term profit/dividends) often have objectives that conflict with external stakeholders (local residents wanting a clean environment).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because avoiding air filters maintains high external pollution costs rather than reducing them.","C":"Incorrect because installing filtration equipment increases fixed capital costs.","D":"Incorrect because dividends are private financial returns to owners, not external benefits to society."}}},{"id":"P1_U6_MCQ_071","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_071","question":"Country A enforces strict, costly environmental laws on chemical manufacturers, whereas neighbouring Country B has no environmental controls. What competitive problem might chemical firms in Country A face?","options":{"A":"Consumers in Country A will refuse to buy environmentally safe chemicals","B":"Country A's firms will experience higher labour productivity than Country B's firms","C":"Country A's firms will automatically receive tariff-free access to Country B","D":"Rivals in Country B can produce at lower cost and undercut Country A's firms on price"},"correctOption":"D","correctAnswer":"Rivals in Country B can produce at lower cost and undercut Country A's firms on price","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because businesses in countries with weak environmental rules avoid pollution-control costs, enabling them to charge lower prices than compliant rivals.","distractor_reasons":{"A":"Incorrect because consumers generally prefer safe products, though some may still buy cheaper imports.","B":"Incorrect because environmental regulations do not automatically raise labour productivity.","C":"Incorrect because environmental laws do not determine international trade tariffs.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_072","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_072","question":"An outdoor clothing company commits to achieving zero carbon emissions and donates 1% of sales to environmental conservation. Apart from customer loyalty, how does this benefit the company's human resource management?","options":{"A":"It eliminates the need to provide employment contracts","B":"It makes it easier to attract and retain skilled, motivated employees who share those values","C":"It allows the company to pay below the legal minimum wage","D":"It removes the need for any employee training"},"correctOption":"B","correctAnswer":"It makes it easier to attract and retain skilled, motivated employees who share those values","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because employees take pride in working for environmentally responsible businesses, improving recruitment and reducing labour turnover.","distractor_reasons":{"A":"Incorrect because written contracts of employment remain a legal requirement.","B":"Correct selection.","C":"Incorrect because environmental commitments do not exempt employers from minimum wage laws.","D":"Incorrect because employees still require training, especially in sustainable production methods."}}},{"id":"P1_U6_MCQ_073","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_073","question":"A car manufacturer introduces lean production and computer-controlled laser cutting to minimise sheet-metal offcuts and reduce defective parts. How does this benefit both profitability and the environment?","options":{"A":"It increases raw material purchases and expands landfill usage","B":"It raises average unit costs while increasing carbon emissions","C":"It lowers material and waste disposal costs while conserving natural resources","D":"It slows down production and increases inventory holding costs"},"correctOption":"C","correctAnswer":"It lowers material and waste disposal costs while conserving natural resources","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cutting waste reduces raw material expenditure and landfill fees (boosting profit) while using fewer scarce natural resources.","distractor_reasons":{"A":"Incorrect because reducing offcuts decreases raw material usage and landfill waste.","B":"Incorrect because lower waste reduces average unit costs and lowers environmental harm.","C":"Correct selection.","D":"Incorrect because lean production speeds up processes and reduces inventory levels."}}},{"id":"P1_U6_MCQ_074","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_074","question":"A stone quarrying company operates heavy blasting machinery and dust-emitting trucks next to a quiet village, causing local house prices to fall. What type of externality is this?","options":{"A":"Noise and air pollution acting as an external cost on villagers","B":"An external benefit increasing villagers' wealth","C":"A private benefit enjoyed by the quarrying company","D":"A government subsidy reducing production costs"},"correctOption":"A","correctAnswer":"Noise and air pollution acting as an external cost on villagers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because noise, dust, and falling property values are negative side effects imposed on uninvolved third parties (the villagers).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because falling house prices and pollution reduce villagers' wellbeing rather than benefiting them.","C":"Incorrect because private benefits are internal gains (like sales revenue) received by the business.","D":"Incorrect because a subsidy is financial support from the government, not environmental disruption."}}},{"id":"P1_U6_MCQ_075","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_075","question":"To encourage delivery companies to replace diesel vans with zero-emission electric vans, a government offers a $5,000 grant for every electric van purchased. How does this policy affect delivery businesses?","options":{"A":"It bans all delivery companies from operating in city centres","B":"It increases the corporation tax rate on logistics companies","C":"It forces businesses to pay higher fuel taxes on electric vehicles","D":"It lowers the net capital cost of adopting cleaner technology, speeding up transition"},"correctOption":"D","correctAnswer":"It lowers the net capital cost of adopting cleaner technology, speeding up transition","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because government grants reduce the high upfront purchase price of environmentally friendly equipment, encouraging faster adoption.","distractor_reasons":{"A":"Incorrect because a purchase grant is a financial incentive, not a city-centre ban.","B":"Incorrect because grants provide financial support rather than raising corporation tax.","C":"Incorrect because electric vans do not use diesel/petrol and are incentivised rather than penalised.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_076","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_076","question":"A food manufacturer chooses to pay its cocoa farmers 25% above the market price and refuses to use artificial additives, even though neither action is required by law. Which concept best describes this approach?","options":{"A":"Legal compliance","B":"Ethical business decision-making","C":"Short-term profit maximisation","D":"Predatory pricing"},"correctOption":"B","correctAnswer":"Ethical business decision-making","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because business ethics involves doing what is morally right for stakeholders even when the law does not require it.","distractor_reasons":{"A":"Incorrect because legal compliance means obeying minimum laws, whereas paying above-market fair prices goes beyond legal obligations.","B":"Correct selection.","C":"Incorrect because paying 25% more for raw materials reduces short-term profit margins.","D":"Incorrect because predatory pricing is setting artificially low prices to drive competitors out of business."}}},{"id":"P1_U6_MCQ_077","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_077","question":"A clothing brand outsources production to a factory in a country where there is no legal minimum wage, paying workers just $1 per day for 12-hour shifts. How would business analysts evaluate this practice?","options":{"A":"It is illegal in the host country and therefore unethical","B":"It is both illegal and ethical because it creates jobs","C":"It is ethical because it maximises dividends for shareholders","D":"It may be legal in that country, but it is widely considered unethical due to worker exploitation"},"correctOption":"D","correctAnswer":"It may be legal in that country, but it is widely considered unethical due to worker exploitation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an action can be strictly legal under weak local laws while still being unethical if it exploits workers with poverty wages.","distractor_reasons":{"A":"Incorrect because the scenario states there is no legal minimum wage in that country, so the pay rate is not breaking local law.","B":"Incorrect because paying poverty wages for 12-hour shifts is unethical, not ethical.","C":"Incorrect because ethics considers fairness to all stakeholders (including workers), not solely shareholder dividends.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_078","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_078","question":"During a routine inspection, a global sportswear brand discovers that one of its overseas textile suppliers is employing 12-year-old children. What is the most ethical response for the sportswear brand?","options":{"A":"Stop using the supplier unless child labour ceases immediately, and support education for affected children","B":"Ignore the discovery so production costs remain low","C":"Demand a 20% price discount from the supplier in exchange for keeping the issue secret","D":"Increase orders from the supplier to boost short-term profits"},"correctOption":"A","correctAnswer":"Stop using the supplier unless child labour ceases immediately, and support education for affected children","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical businesses refuse to profit from child labour, enforcing strict supplier codes of conduct and protecting children's welfare.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ignoring child labour is unethical and risks severe reputational damage if exposed.","C":"Incorrect because extorting a discount to hide child labour is deeply unethical.","D":"Incorrect because expanding orders encourages further exploitation of underage workers."}}},{"id":"P1_U6_MCQ_079","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_079","question":"A supermarket chain decides to pay all its store and warehouse employees a 'living wage' that is significantly higher than the government's legal minimum wage. What is a likely benefit of this ethical decision?","options":{"A":"Immediate reduction in total hourly wage expenses","B":"Exemption from paying Value Added Tax on grocery sales","C":"Higher employee motivation, better customer service, and lower staff turnover","D":"Elimination of all competition from rival supermarkets"},"correctOption":"C","correctAnswer":"Higher employee motivation, better customer service, and lower staff turnover","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because paying fair, living wages increases worker motivation and loyalty, reducing recruitment costs and improving service quality.","distractor_reasons":{"A":"Incorrect because paying higher hourly wages increases direct labour costs.","B":"Incorrect because wage policies do not exempt retailers from sales taxes.","C":"Correct selection.","D":"Incorrect because rival supermarkets continue to compete in the market."}}},{"id":"P1_U6_MCQ_080","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_080","question":"A coffee roaster joins the Fairtrade scheme, guaranteeing small-scale coffee growers in developing countries a minimum fair price even when global coffee prices crash. How does this affect the coffee roaster?","options":{"A":"Its raw material costs are lower than buying from non-Fairtrade suppliers","B":"Its raw material costs are higher, but its ethical brand image attracts loyal customers","C":"It no longer needs to advertise or promote its coffee products","D":"It is legally forbidden from selling coffee to supermarkets"},"correctOption":"B","correctAnswer":"Its raw material costs are higher, but its ethical brand image attracts loyal customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Fairtrade certification increases input costs for the business, but enhances brand reputation and customer willingness to pay.","distractor_reasons":{"A":"Incorrect because Fairtrade guarantees higher, fairer prices to farmers, raising input costs for the buyer.","B":"Correct selection.","C":"Incorrect because the business must still promote its Fairtrade credentials to inform consumers.","D":"Incorrect because Fairtrade products are widely sold through major supermarkets."}}},{"id":"P1_U6_MCQ_081","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_081","question":"A furniture retailer refuses to buy timber from suppliers involved in illegal logging and insists on certified sustainable wood. What is this business practice called?","options":{"A":"Predatory pricing","B":"Horizontal integration","C":"Social enterprise franchising","D":"Ethical sourcing"},"correctOption":"D","correctAnswer":"Ethical sourcing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ethical sourcing means ensuring that raw materials and components are obtained from suppliers that respect human rights and the environment.","distractor_reasons":{"A":"Incorrect because predatory pricing is an anti-competitive pricing tactic.","B":"Incorrect because horizontal integration is merging with or taking over a competitor at the same production stage.","C":"Incorrect because franchising is a method of business expansion using licensed outlets.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_082","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_082","question":"A construction company bidding for a major overseas infrastructure contract is asked by a corrupt local official for a secret cash payment to guarantee winning the bid. What is the ethical decision for the company?","options":{"A":"Refuse to pay the bribe, even if it means losing the contract","B":"Pay the bribe and record it as 'marketing expenses' in the accounts","C":"Offer double the bribe to secure additional contracts","D":"Ask a subcontractor to pay the bribe on its behalf"},"correctOption":"A","correctAnswer":"Refuse to pay the bribe, even if it means losing the contract","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because refusing bribery and corruption upholds moral integrity and avoids severe legal penalties and reputational ruin.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because falsifying accounts to conceal bribery is both unethical and illegal.","C":"Incorrect because increasing a bribe deepens illegal and unethical corruption.","D":"Incorrect because using a third party to pay a bribe is still unethical and illegal."}}},{"id":"P1_U6_MCQ_083","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_083","question":"A snack food company decides to stop advertising high-sugar sweets during children's television programmes, even though such adverts are still permitted by law. Which area of business ethics does this demonstrate?","options":{"A":"Fair supplier pricing","B":"Transparent financial reporting","C":"Ethical marketing and promotion","D":"Just-in-time inventory control"},"correctOption":"C","correctAnswer":"Ethical marketing and promotion","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ethical marketing involves avoiding manipulative or harmful promotions targeted at vulnerable groups such as children.","distractor_reasons":{"A":"Incorrect because this decision concerns advertising to consumers, not payments to suppliers.","B":"Incorrect because financial reporting relates to accounting disclosures rather than TV adverts.","C":"Correct selection.","D":"Incorrect because JIT is an operations inventory technique, not an ethical marketing decision."}}},{"id":"P1_U6_MCQ_084","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_084","question":"A skincare brand stops testing its new products on animals and switches to more expensive laboratory alternatives. Why might this decision reduce profits in the short term?","options":{"A":"Consumers will boycott brands that stop testing on animals","B":"Alternative testing methods increase research and development costs","C":"The government imposes an extra tax on cruelty-free cosmetics","D":"Employees will demand pay cuts to work for an ethical brand"},"correctOption":"B","correctAnswer":"Alternative testing methods increase research and development costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ethical alternatives often involve higher R&D or production costs initially, squeezing short-term profit margins.","distractor_reasons":{"A":"Incorrect because animal-welfare consumers reward cruelty-free brands with higher loyalty rather than boycotting them.","B":"Correct selection.","C":"Incorrect because governments do not tax businesses for ending animal testing.","D":"Incorrect because employees do not take pay cuts; rather, the firm attracts motivated staff."}}},{"id":"P1_U6_MCQ_085","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_085","question":"Why does behaving ethically often create a direct conflict with a business's objective of maximising short-term profit?","options":{"A":"Ethical businesses are legally prohibited from making any profit","B":"Ethical products always suffer from poor quality and high defect rates","C":"Ethical businesses are not allowed to advertise on social media","D":"Paying fair wages, using sustainable materials, and auditing suppliers increase operating costs"},"correctOption":"D","correctAnswer":"Paying fair wages, using sustainable materials, and auditing suppliers increase operating costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ethical practices typically raise labour, material, and compliance costs, lowering short-term profits unless higher prices can be charged.","distractor_reasons":{"A":"Incorrect because ethical private sector businesses aim to make profits responsibly (unlike charities).","B":"Incorrect because ethical products are often higher quality due to better materials and motivated staff.","C":"Incorrect because ethical businesses actively use social media to communicate their values.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_086","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_086","question":"Despite higher material costs, an ethical chocolate company achieves higher long-term profits than its non-ethical rivals. How does ethical behaviour lead to higher long-term profitability?","options":{"A":"Strong brand reputation builds customer loyalty, allowing premium prices and repeat sales","B":"Suppliers agree to provide cocoa beans completely free of charge","C":"The business avoids paying any rent or utility bills","D":"Employees agree to work unpaid overtime every week"},"correctOption":"A","correctAnswer":"Strong brand reputation builds customer loyalty, allowing premium prices and repeat sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a strong ethical reputation differentiates the brand, increases customer loyalty, and allows the firm to charge higher prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ethical firms pay higher, fairer prices to suppliers rather than getting free supplies.","C":"Incorrect because ethical behaviour does not remove standard business overhead costs.","D":"Incorrect because exploiting workers with unpaid overtime would be unethical."}}},{"id":"P1_U6_MCQ_087","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_087","question":"An investigative newspaper reveals that a well-known fashion retailer's garments are made in unsafe overseas sweatshops. What is the most immediate consequence for the retailer?","options":{"A":"Increased share price due to lower factory wage costs","B":"Higher customer loyalty from price-conscious shoppers","C":"Severe damage to brand image and falling sales as customers switch to ethical rivals","D":"Automatic government grants to improve its overseas factories"},"correctOption":"C","correctAnswer":"Severe damage to brand image and falling sales as customers switch to ethical rivals","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because negative publicity from unethical practices damages reputation, destroys consumer trust, and reduces sales revenue.","distractor_reasons":{"A":"Incorrect because bad publicity and falling sales usually cause a company's share price to fall.","B":"Incorrect because exposure of sweatshop labour alienates customers rather than building loyalty.","C":"Correct selection.","D":"Incorrect because governments do not reward unethical practices with grants."}}},{"id":"P1_U6_MCQ_088","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_088","question":"A public limited company publishes an annual sustainability and ethics report detailing its fair-trade supply chain and zero-tolerance policy on corruption. How does this help the company raise capital?","options":{"A":"It forces commercial banks to offer interest-free loans","B":"It attracts ethical investment funds and socially responsible shareholders to buy its shares","C":"It allows the company to issue shares without a prospectus","D":"It eliminates all financial risk for shareholders"},"correctOption":"B","correctAnswer":"It attracts ethical investment funds and socially responsible shareholders to buy its shares","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because many institutional investors and ethical funds only invest in businesses that meet strict ethical and environmental standards.","distractor_reasons":{"A":"Incorrect because commercial banks charge interest based on risk and market rates, not ethical reports.","B":"Correct selection.","C":"Incorrect because legal requirements for share issues still apply to all public limited companies.","D":"Incorrect because all equity investments carry commercial risk regardless of ethical policies."}}},{"id":"P1_U6_MCQ_089","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_089","question":"A software company is widely recognised for treating staff fairly, promoting diversity, and supporting local community charities. How does this ethical reputation affect its workforce?","options":{"A":"Absenteeism and labour turnover increase rapidly","B":"Employees become less productive because they do not fear unfair dismissal","C":"The company has to spend much more on recruitment advertising","D":"High-calibre applicants are attracted to join the firm and existing staff stay longer"},"correctOption":"D","correctAnswer":"High-calibre applicants are attracted to join the firm and existing staff stay longer","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ethical employers enjoy higher staff morale, lower labour turnover, and stronger appeal to talented job candidates.","distractor_reasons":{"A":"Incorrect because fair treatment reduces absenteeism and labour turnover rather than increasing them.","B":"Incorrect because motivated, well-treated employees are generally more productive.","C":"Incorrect because a strong reputation as a good employer attracts applicants organically, lowering recruitment costs.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_090","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_090","question":"To ensure that managers and staff across 20 international branches follow consistent moral standards regarding gifts, supplier fairness, and honesty, a company introduces a formal document. What is this document called?","options":{"A":"An ethical code of conduct","B":"A statement of financial position","C":"A job analysis","D":"A cash flow forecast"},"correctOption":"A","correctAnswer":"An ethical code of conduct","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an ethical code of conduct sets out the moral principles and standards of behaviour expected from all employees and managers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a statement of financial position records a firm's assets, liabilities, and capital.","C":"Incorrect because a job analysis identifies the tasks and responsibilities of a specific job role.","D":"Incorrect because a cash flow forecast predicts future cash inflows and outflows."}}},{"id":"P1_U6_MCQ_091","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_091","question":"A major electronics brand publishes the names and addresses of all its component factories online and hires independent auditors to inspect working conditions. Why does the brand take this action?","options":{"A":"To help competitors copy its manufacturing secrets","B":"To avoid paying import tariffs on finished electronics","C":"To ensure supply chain transparency and prove that suppliers meet ethical labour standards","D":"To reduce the fixed costs of its head office"},"correctOption":"C","correctAnswer":"To ensure supply chain transparency and prove that suppliers meet ethical labour standards","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because independent audits and supply chain transparency demonstrate accountability and reassure customers that workers are treated ethically.","distractor_reasons":{"A":"Incorrect because listing factory locations does not give away proprietary product designs.","B":"Incorrect because publishing factory lists does not exempt goods from customs tariffs.","C":"Correct selection.","D":"Incorrect because hiring independent auditors increases administrative expenses rather than lowering fixed costs."}}},{"id":"P1_U6_MCQ_092","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_092","question":"An ethical toy manufacturer uses safe, non-toxic paints and pays fair wages, while a rival imports cheap toys made with low-cost labour and sells them at half the price. What risk does the ethical manufacturer face?","options":{"A":"Being fined by the government for paying fair wages","B":"Losing price-sensitive customers to the cheaper unethical competitor","C":"Having its products banned for being too safe","D":"Facing higher employee turnover than the sweatshop rival"},"correctOption":"B","correctAnswer":"Losing price-sensitive customers to the cheaper unethical competitor","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a key disadvantage of being ethical is that higher costs lead to higher prices, causing shoppers who care only about low prices to buy from unethical rivals.","distractor_reasons":{"A":"Incorrect because governments do not fine businesses for paying fair wages.","B":"Correct selection.","C":"Incorrect because safe products comply with consumer protection laws and are never banned for safety.","D":"Incorrect because fair wages reduce employee turnover compared to low-paying rivals."}}},{"id":"P1_U6_MCQ_093","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_093","question":"A large supermarket chain has strong buying power over small local fruit farmers. Which action by the supermarket would be considered unethical?","options":{"A":"Paying farmers promptly within 14 days of delivery","B":"Signing long-term supply contracts at guaranteed prices","C":"Helping farmers fund sustainable irrigation systems","D":"Delaying invoice payments for six months, forcing small farmers into cash flow crises"},"correctOption":"D","correctAnswer":"Delaying invoice payments for six months, forcing small farmers into cash flow crises","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because abusing dominant market power to delay payments harms small suppliers' liquidity and is an unethical business practice.","distractor_reasons":{"A":"Incorrect because prompt payment supports suppliers' cash flow and is ethical.","B":"Incorrect because stable, guaranteed contracts protect farmers from price volatility.","C":"Incorrect because supporting suppliers' sustainability is a socially responsible practice.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_094","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_094","question":"During a year when profits fell by 30%, the Board of Directors of a manufacturing plc froze factory workers' wages and made 200 staff redundant, while awarding the Chief Executive a $4 million bonus. What is the likely impact of this decision?","options":{"A":"Widespread anger among employees and negative media publicity damaging the company's image","B":"Higher motivation among the remaining factory workers","C":"Increased customer loyalty due to strong executive leadership","D":"Lower corporation tax rates for the company"},"correctOption":"A","correctAnswer":"Widespread anger among employees and negative media publicity damaging the company's image","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because excessive executive bonuses alongside worker redundancies are seen as unfair and unethical, harming employee morale and public reputation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wage freezes and redundancies combined with huge executive bonuses severely demotivate remaining staff.","C":"Incorrect because negative media coverage of executive greed alienates customers.","D":"Incorrect because executive bonus decisions do not lower statutory corporation tax rates."}}},{"id":"P1_U6_MCQ_095","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_095","question":"A car manufacturer discovers a minor braking fault in a newly released model before any accidents have occurred or any government safety agency has intervened. What is the ethical course of action?","options":{"A":"Keep the fault secret until the next annual model update","B":"Deny any problem exists if customers complain","C":"Voluntarily recall all affected cars immediately and repair the fault free of charge","D":"Export the faulty cars to countries with weaker safety laws"},"correctOption":"C","correctAnswer":"Voluntarily recall all affected cars immediately and repair the fault free of charge","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because prioritising customer safety through a prompt, voluntary recall protects lives and preserves long-term brand trust.","distractor_reasons":{"A":"Incorrect because hiding a known braking defect endangers lives and is both unethical and illegal.","B":"Incorrect because lying to customers about safety defects destroys credibility and invites legal action.","C":"Correct selection.","D":"Incorrect because dumping unsafe products in other countries is highly unethical."}}},{"id":"P1_U6_MCQ_096","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_096","question":"A telecommunications company provides free internet access to rural schools and ensures all its suppliers pay fair wages, accepting slightly lower annual dividends. Which concept best describes this approach?","options":{"A":"Autocratic leadership","B":"Corporate Social Responsibility (CSR)","C":"Diseconomies of scale","D":"Penetration pricing"},"correctOption":"B","correctAnswer":"Corporate Social Responsibility (CSR)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Corporate Social Responsibility (CSR) means a business accepts moral obligations to benefit society and stakeholders beyond just making profit.","distractor_reasons":{"A":"Incorrect because autocratic leadership is a management style where decisions are made without consulting staff.","B":"Correct selection.","C":"Incorrect because diseconomies of scale are rising unit costs caused by a business growing too large.","D":"Incorrect because penetration pricing is setting a low initial price to enter a new market."}}},{"id":"P1_U6_MCQ_097","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_097","question":"A European retailer opens a clothing factory in a developing country where safety laws are weak. Why should the retailer still enforce its strict European health, safety, and wage standards in the new factory?","options":{"A":"Because foreign governments require European companies to charge higher retail prices","B":"Because enforcing high standards makes the factory cheaper to operate in the short term","C":"Because low-wage workers are legally barred from working in modern factories","D":"To uphold ethical principles and protect its global brand image from bad publicity"},"correctOption":"D","correctAnswer":"To uphold ethical principles and protect its global brand image from bad publicity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers in home markets hold MNCs accountable for their global operations; double standards can trigger boycotts and brand damage.","distractor_reasons":{"A":"Incorrect because host governments do not dictate retail prices in Europe.","B":"Incorrect because higher safety and wage standards increase operating costs in the short term.","C":"Incorrect because no law bars workers from modern factories.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_098","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_098","question":"A bottled beverage company prints '100% Eco-Friendly and Ethically Sourced' on its labels, but an investigation proves its bottles are non-recyclable plastic and its farmers are underpaid. What is the main business risk of making false ethical claims?","options":{"A":"Total loss of consumer trust, negative publicity, and potential fines for misleading promotion","B":"Immediate reduction in variable packaging costs","C":"Higher employee motivation and easier recruitment","D":"Exemption from government consumer protection laws"},"correctOption":"A","correctAnswer":"Total loss of consumer trust, negative publicity, and potential fines for misleading promotion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 'greenwashing' or false ethical claims destroy brand credibility when exposed and violate legal controls against misleading advertising.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because exposure of false claims leads to costly packaging redesigns and falling sales, not cost savings.","C":"Incorrect because dishonesty embarrasses employees and harms morale.","D":"Incorrect because misleading claims directly violate consumer protection laws."}}},{"id":"P1_U6_MCQ_099","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_099","question":"A banking group establishes a confidential hotline allowing employees to report suspected fraud, bribery, or unethical behaviour by managers without fear of dismissal. How does this policy support ethical business operations?","options":{"A":"It eliminates the need for external financial audits","B":"It guarantees higher interest rates on customer savings accounts","C":"It helps detect and stop unethical practices early before major damage occurs","D":"It allows managers to ignore the ethical code of conduct"},"correctOption":"C","correctAnswer":"It helps detect and stop unethical practices early before major damage occurs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because protecting whistleblowers encourages staff to expose misconduct internally so senior leaders can resolve issues before legal or reputational scandals erupt.","distractor_reasons":{"A":"Incorrect because limited companies are still legally required to have external financial audits.","B":"Incorrect because internal ethics hotlines do not determine customer interest rates.","C":"Correct selection.","D":"Incorrect because the hotline enforces compliance with the ethical code rather than allowing managers to ignore it."}}},{"id":"P1_U6_MCQ_100","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_100","question":"During a severe recession, an ethical coffee chain experiences falling sales and rising losses, forcing management to choose between cutting supplier Fairtrade premiums or closing stores and making 300 staff redundant. What does this dilemma show?","options":{"A":"Ethical businesses never face difficult trade-offs during economic downturns","B":"Recessions always increase profits for ethical retailers","C":"Redundant employees are not entitled to any legal notice","D":"Maintaining costly ethical commitments can conflict with business survival and job protection"},"correctOption":"D","correctAnswer":"Maintaining costly ethical commitments can conflict with business survival and job protection","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when survival is threatened, managers often face difficult ethical trade-offs between different stakeholder groups (e.g., suppliers vs employees).","distractor_reasons":{"A":"Incorrect because the scenario clearly illustrates a difficult ethical trade-off.","B":"Incorrect because falling consumer spending during a recession reduces sales and profits.","C":"Incorrect because employment contracts and legal controls still require proper notice and redundancy procedures.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_101","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_101","question":"A group of citizens and conservationists forms an organisation to campaign against deforestation by palm oil plantations and persuade food companies to change their ingredients. What is this organisation called?","options":{"A":"A public limited company","B":"A pressure group","C":"A trade association","D":"A central bank"},"correctOption":"B","correctAnswer":"A pressure group","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a pressure group consists of people with a shared interest or concern who act together to influence business decisions and government policy.","distractor_reasons":{"A":"Incorrect because a public limited company is a profit-seeking business owned by shareholders.","B":"Correct selection.","C":"Incorrect because a trade association represents businesses within an industry rather than external campaigners.","D":"Incorrect because a central bank manages a country's currency and interest rates."}}},{"id":"P1_U6_MCQ_102","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_102","question":"An animal welfare group urges shoppers across the country to stop buying cosmetics from Brand X until Brand X ends animal testing. Which pressure group tactic is being used?","options":{"A":"Government lobbying","B":"Workplace strike action","C":"A consumer boycott","D":"A hostile takeover"},"correctOption":"C","correctAnswer":"A consumer boycott","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a consumer boycott involves persuading consumers to refuse to buy a business's products in order to force a change in company policy.","distractor_reasons":{"A":"Incorrect because lobbying involves persuading politicians to pass laws, whereas here shoppers are asked to stop buying.","B":"Incorrect because strikes are carried out by employees/trade unions, not external shoppers.","C":"Correct selection.","D":"Incorrect because a hostile takeover is one business buying a majority of shares in another business."}}},{"id":"P1_U6_MCQ_103","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_103","question":"Following a widespread consumer boycott organised by an environmental group, a fast-fashion retailer's monthly sales revenue drops by 25%. Why does this pressure group action often force management to change its policies?","options":{"A":"Falling sales revenue and bad publicity threaten company profits and shareholder returns","B":"Pressure groups have the legal power to arrest company directors","C":"The boycott automatically doubles the retailer's corporation tax rate","D":"Suppliers are legally prohibited from delivering clothes during a boycott"},"correctOption":"A","correctAnswer":"Falling sales revenue and bad publicity threaten company profits and shareholder returns","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because private sector businesses depend on sales to make profits; a successful boycott directly reduces revenue and damages brand value.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pressure groups are non-governmental organisations with no legal power to arrest people.","C":"Incorrect because consumer boycotts do not alter government tax rates.","D":"Incorrect because suppliers are not legally barred from delivering goods during a consumer boycott."}}},{"id":"P1_U6_MCQ_104","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_104","question":"Representatives of an environmental pressure group meet regularly with government ministers to present scientific evidence and persuade Parliament to ban single-use plastic packaging. Which method of influence is this?","options":{"A":"Consumer boycott","B":"Industrial strike","C":"Price skimming","D":"Lobbying"},"correctOption":"D","correctAnswer":"Lobbying","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lobbying involves directly contacting and persuading politicians or government officials to pass laws that restrict or guide business behaviour.","distractor_reasons":{"A":"Incorrect because a boycott targets consumers to stop buying products, rather than meeting lawmakers.","B":"Incorrect because a strike is a stoppage of work by employees.","C":"Incorrect because price skimming is a business pricing strategy.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_105","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_105","question":"A local community pressure group collects 50,000 signatures from residents opposing a supermarket's plan to build a superstore on a public park, and presents the document to the town council. Which tactic is the group using?","options":{"A":"A hostile takeover bid","B":"A petition","C":"Direct industrial sabotage","D":"Predatory pricing"},"correctOption":"B","correctAnswer":"A petition","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a petition gathers signatures from supporters to demonstrate strong public opposition to a business or government decision.","distractor_reasons":{"A":"Incorrect because a takeover bid involves purchasing shares in a company.","B":"Correct selection.","C":"Incorrect because collecting signatures is a peaceful, legal democratic action, not sabotage.","D":"Incorrect because predatory pricing is an anti-competitive business pricing tactic."}}},{"id":"P1_U6_MCQ_106","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_106","question":"Climate activists stage a peaceful protest outside the flagship store of a major oil company, attracting national television news crews. What is the main objective of holding protests outside a company's premises?","options":{"A":"To generate media coverage and negative publicity that pressures the company into changing its practices","B":"To legally force the company to transfer ownership to the protesters","C":"To increase the company's short-term share price","D":"To replace the company's Board of Directors immediately"},"correctOption":"A","correctAnswer":"To generate media coverage and negative publicity that pressures the company into changing its practices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public demonstrations attract media attention, damaging the target business's public image and pressuring management to respond.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because protests do not transfer legal ownership of private businesses.","C":"Incorrect because negative publicity usually harms rather than boosts a company's share price.","D":"Incorrect because only shareholders voting at an AGM can replace directors."}}},{"id":"P1_U6_MCQ_107","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_107","question":"A pressure group launches a viral social media video campaign exposing toxic waste dumping by a clothing brand, reaching 10 million viewers in three days. Why are social media campaigns so effective for modern pressure groups?","options":{"A":"They are legally binding on all businesses in the country","B":"They allow pressure groups to collect corporation tax directly from businesses","C":"They guarantee that the targeted business will go bankrupt within a week","D":"They spread awareness globally at very low cost and rapidly damage the target's brand reputation"},"correctOption":"D","correctAnswer":"They spread awareness globally at very low cost and rapidly damage the target's brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because social media enables pressure groups to reach millions of consumers quickly and cheaply, creating instant reputational pressure.","distractor_reasons":{"A":"Incorrect because social media posts carry moral and commercial pressure, not legal force.","B":"Incorrect because only government tax authorities collect corporation tax.","C":"Incorrect because while brand damage can reduce sales, bankruptcy is not guaranteed.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_108","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_108","question":"Why do international pressure groups frequently target large, well-known consumer brands rather than small, unknown local businesses?","options":{"A":"Small local businesses are legally exempt from all environmental and ethical laws","B":"Well-known brands never respond to public criticism","C":"High-profile brands rely heavily on brand image and attract much greater media coverage when criticised","D":"Large brands do not care about their sales revenue or public reputation"},"correctOption":"C","correctAnswer":"High-profile brands rely heavily on brand image and attract much greater media coverage when criticised","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because famous consumer brands invest heavily in reputation and attract intense media attention, making them more sensitive to bad publicity.","distractor_reasons":{"A":"Incorrect because small businesses must still obey environmental and employment laws.","B":"Incorrect because major brands often respond quickly to protect their valuable brand image.","C":"Correct selection.","D":"Incorrect because large brands are highly protective of their reputation and sales revenue."}}},{"id":"P1_U6_MCQ_109","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_109","question":"A consumer pressure group calls for a boycott of a bottled soft drink brand over its excessive plastic packaging. Under which condition is this consumer boycott most likely to succeed?","options":{"A":"When the targeted brand is a monopoly supplier of an essential life-saving medicine","B":"When consumers can easily switch to affordable, eco-friendly rival drinks at the same price","C":"When the pressure group has zero funding and no media coverage","D":"When the public strongly disagrees with the pressure group's message"},"correctOption":"B","correctAnswer":"When consumers can easily switch to affordable, eco-friendly rival drinks at the same price","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because boycotts succeed far more easily when close, affordable substitutes exist so shoppers suffer little inconvenience by switching brands.","distractor_reasons":{"A":"Incorrect because consumers cannot easily boycott a monopoly provider of an essential product.","B":"Correct selection.","C":"Incorrect because lack of funds and publicity prevents the boycott message from reaching consumers.","D":"Incorrect because public sympathy is essential for consumers to participate in a boycott."}}},{"id":"P1_U6_MCQ_110","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_110","question":"A small pressure group campaigns against a major airline's expansion, but fails to attract media attention or public support. Why is the airline likely to continue with its expansion plans?","options":{"A":"Without wide public sympathy or media coverage, the group cannot significantly harm the airline's sales or image","B":"Airlines are legally forbidden from communicating with pressure groups","C":"Pressure groups are not allowed to exist in countries with private airlines","D":"Expansion always reduces an airline's fixed costs to zero"},"correctOption":"A","correctAnswer":"Without wide public sympathy or media coverage, the group cannot significantly harm the airline's sales or image","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a pressure group's influence depends heavily on public support, financial resources, and media coverage; without them, business impact is minimal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses frequently meet and negotiate with pressure groups.","C":"Incorrect because pressure groups operate freely in democratic economies.","D":"Incorrect because expansion increases fixed costs such as aircraft and airport fees."}}},{"id":"P1_U6_MCQ_111","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_111","question":"How does a pressure group differ from a political party?","options":{"A":"A pressure group aims to win elections and form the national government","B":"A pressure group is owned and funded entirely by private shareholders","C":"A pressure group is illegal in most countries, whereas political parties are legal","D":"A pressure group focuses on influencing specific issues or business practices without seeking to form the government"},"correctOption":"D","correctAnswer":"A pressure group focuses on influencing specific issues or business practices without seeking to form the government","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because pressure groups campaign on targeted causes (such as the environment or consumer rights) rather than standing for election to govern the whole country.","distractor_reasons":{"A":"Incorrect because winning elections to form a government is the aim of a political party, not a pressure group.","B":"Incorrect because pressure groups are non-profit campaign organisations funded by members and donations, not shareholders.","C":"Incorrect because peaceful pressure groups are legal in democratic societies.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_112","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_112","question":"An industrial chemical supplier sells raw dyes only to other factories and does not sell directly to the general public. Why might a direct consumer boycott be less effective against this supplier than against a high-street clothing retailer?","options":{"A":"Industrial chemical suppliers never cause any environmental pollution","B":"High-street retailers do not care about their brand image","C":"Ordinary consumers do not buy directly from the chemical supplier, so they cannot directly withhold purchases from it","D":"Consumer boycotts are illegal against business-to-business suppliers"},"correctOption":"C","correctAnswer":"Ordinary consumers do not buy directly from the chemical supplier, so they cannot directly withhold purchases from it","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because shoppers cannot boycott a business whose products they do not directly buy; instead, pressure groups must target the retail brands that buy from that supplier.","distractor_reasons":{"A":"Incorrect because chemical plants can cause significant pollution.","B":"Incorrect because high-street retailers are highly sensitive to brand reputation.","C":"Correct selection.","D":"Incorrect because boycotts are not illegal; they are simply impractical when a firm has no direct retail consumers."}}},{"id":"P1_U6_MCQ_113","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_113","question":"After an environmental group criticises a supermarket chain for excessive plastic food trays, the supermarket meets with the group and agrees to phase out non-recyclable trays within two years. What is a key benefit of this constructive response?","options":{"A":"It immediately eliminates all packaging costs for the supermarket","B":"It ends negative publicity, improves brand reputation, and avoids a damaging consumer boycott","C":"It exempts the supermarket from paying corporate taxes","D":"It prevents competitors from using recyclable packaging"},"correctOption":"B","correctAnswer":"It ends negative publicity, improves brand reputation, and avoids a damaging consumer boycott","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because engaging constructively and adapting practices turns potential bad publicity into positive PR and protects customer loyalty.","distractor_reasons":{"A":"Incorrect because switching to recyclable trays still incurs packaging expenses.","B":"Correct selection.","C":"Incorrect because sustainable packaging agreements do not waive corporate tax obligations.","D":"Incorrect because competitors are free to adopt recyclable packaging too."}}},{"id":"P1_U6_MCQ_114","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_114","question":"A pressure group accuses a food manufacturer of using uncertified palm oil, even though the manufacturer already uses 100% certified sustainable palm oil. How should the manufacturer respond?","options":{"A":"Launch a public relations campaign publishing independent certification proof to correct the false claim","B":"Stop using certified palm oil and switch to cheaper uncertified oil","C":"Close down all its factories immediately","D":"Ignore the accusation completely while sales plummet"},"correctOption":"A","correctAnswer":"Launch a public relations campaign publishing independent certification proof to correct the false claim","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when a business is already acting responsibly, transparent communication and public relations protect its reputation from misinformation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because abandoning sustainable sourcing would validate the criticism and harm the brand.","C":"Incorrect because closing factories is an extreme overreaction when the firm is already compliant.","D":"Incorrect because remaining silent allows false claims to damage consumer trust."}}},{"id":"P1_U6_MCQ_115","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_115","question":"A tiny protest group demands that a regional bus operator immediately replace its entire diesel bus fleet with expensive hydrogen buses, despite having almost no public backing. Why might the bus operator decide to ignore this demand for now?","options":{"A":"Hydrogen buses are illegal to operate on public roads","B":"Bus operators are banned from ever changing their vehicles","C":"Pressure groups can only target manufacturing firms, not service businesses","D":"The high cost of immediate fleet replacement outweighs the negligible threat to sales from a group with no public support"},"correctOption":"D","correctAnswer":"The high cost of immediate fleet replacement outweighs the negligible threat to sales from a group with no public support","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because businesses weigh the financial cost of meeting pressure group demands against the commercial risk of ignoring them; with minimal public support, the risk is very low.","distractor_reasons":{"A":"Incorrect because hydrogen buses are legal and increasingly used in public transport.","B":"Incorrect because bus operators regularly upgrade fleets when financially viable.","C":"Incorrect because pressure groups target both manufacturing and service businesses.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_116","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_116","question":"When several major retailers refuse to stop giving away free single-use plastic bags, an environmental pressure group shifts its strategy to lobbying Parliament. What is the pressure group trying to achieve?","options":{"A":"To buy a majority of shares in the retail companies","B":"To lower the corporation tax paid by supermarkets","C":"To get the government to pass a law banning or taxing free plastic bags across all retailers","D":"To encourage shoppers to use more plastic bags"},"correctOption":"C","correctAnswer":"To get the government to pass a law banning or taxing free plastic bags across all retailers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when direct persuasion fails, pressure groups lobby governments to introduce legal controls that force all businesses to comply.","distractor_reasons":{"A":"Incorrect because lobbying lawmakers does not involve buying company shares.","B":"Incorrect because environmental groups want to discourage plastic use, not cut retailer taxes.","C":"Correct selection.","D":"Incorrect because the group aims to eliminate single-use plastic bags."}}},{"id":"P1_U6_MCQ_117","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_117","question":"In response to sustained pressure group campaigns against high sugar levels in children's cereals, a food company reformulates its recipes with 30% less sugar and highlights this on the box. Which two elements of the marketing mix has the company changed?","options":{"A":"Price and Place","B":"Product and Promotion","C":"Place and Promotion","D":"Price and Product"},"correctOption":"B","correctAnswer":"Product and Promotion","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because changing the cereal recipe alters the 'Product', while highlighting the lower sugar content on packaging is 'Promotion'.","distractor_reasons":{"A":"Incorrect because neither the selling price nor the distribution channels (Place) were changed in the scenario.","B":"Correct selection.","C":"Incorrect because distribution channels (Place) were not altered.","D":"Incorrect because no change in selling price was mentioned."}}},{"id":"P1_U6_MCQ_118","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_118","question":"An environmental pressure group buys a small number of shares in a large oil public limited company so its members can attend the Annual General Meeting (AGM) and question the Board of Directors on climate targets. Which tactic is this?","options":{"A":"Shareholder activism","B":"Consumer boycott","C":"Import quota lobbying","D":"Predatory pricing"},"correctOption":"A","correctAnswer":"Shareholder activism","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because owning shares entitles the pressure group to attend the AGM, propose resolutions, and publicly challenge directors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because buying shares to attend an AGM is internal shareholder pressure, not a consumer boycott.","C":"Incorrect because import quotas are government trade restrictions.","D":"Incorrect because predatory pricing is an anti-competitive pricing strategy."}}},{"id":"P1_U6_MCQ_119","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_119","question":"Residents in a farming valley form a pressure group to oppose a mining company's plan to dump mine tailings near the valley's main river. How does this pressure group protect external stakeholders?","options":{"A":"By increasing the mining company's short-term profit margins","B":"By helping the mining company avoid paying local property taxes","C":"By reducing the wages paid to local farm workers","D":"By defending the local community's clean water supply and agricultural livelihoods from external costs"},"correctOption":"D","correctAnswer":"By defending the local community's clean water supply and agricultural livelihoods from external costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because community pressure groups give local residents a collective voice to prevent businesses from imposing environmental external costs on them.","distractor_reasons":{"A":"Incorrect because stopping cheap waste dumping increases the mining company's disposal costs rather than boosting profits.","B":"Incorrect because pressure groups do not help companies avoid taxes.","C":"Incorrect because protecting local farms preserves agricultural jobs and incomes.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_120","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_120","question":"Besides bargaining for their own members' wages, trade unions sometimes campaign alongside social groups for stricter national workplace safety laws and higher statutory minimum wages. In this wider role, how are trade unions acting?","options":{"A":"As multinational companies","B":"As central bank regulators","C":"As pressure groups influencing government policy and business standards","D":"As private limited companies"},"correctOption":"C","correctAnswer":"As pressure groups influencing government policy and business standards","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when trade unions lobby governments and campaign for wider social and legal reforms, they act as pressure groups.","distractor_reasons":{"A":"Incorrect because trade unions represent workers, whereas MNCs are international businesses.","B":"Incorrect because central banks regulate monetary policy and banking stability.","C":"Correct selection.","D":"Incorrect because trade unions are worker organisations, not shareholder-owned companies."}}},{"id":"P1_U6_MCQ_121","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_121","question":"A seafood company works closely with a marine conservation pressure group to adopt sustainable fishing methods and earns the group's official eco-label on its packaging. What is the main commercial benefit of this partnership?","options":{"A":"The company no longer needs to pay its fishermen","B":"The eco-label boosts consumer trust and acts as a competitive advantage over rival brands","C":"The company is legally guaranteed a 100% market share","D":"Fishing boat fuel becomes completely free"},"correctOption":"B","correctAnswer":"The eco-label boosts consumer trust and acts as a competitive advantage over rival brands","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because independent endorsement from a respected pressure group builds strong brand credibility and differentiates the product in the market.","distractor_reasons":{"A":"Incorrect because employees must still be paid fair wages.","B":"Correct selection.","C":"Incorrect because eco-labels attract customers but do not create a legal monopoly.","D":"Incorrect because fuel costs are still incurred by fishing vessels."}}},{"id":"P1_U6_MCQ_122","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_122","question":"A large clothing plc suffers months of negative media headlines after a human rights pressure group exposes poor working conditions in its supply chain. Apart from lower sales, how could this affect the company's finances?","options":{"A":"Ethical investors may sell their shares and banks may view the company as higher risk, making finance harder to raise","B":"The company's existing bank loans will automatically be cancelled without repayment","C":"The company's share price will rise because all publicity increases profits","D":"Suppliers will lower their prices by 50% to help the retailer"},"correctOption":"A","correctAnswer":"Ethical investors may sell their shares and banks may view the company as higher risk, making finance harder to raise","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reputational damage and falling sales reduce investor confidence, lowering share prices and making lenders more cautious.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banks do not forgive debts when a borrower suffers bad publicity.","C":"Incorrect because severe reputational scandals reduce expected future profits and depress share prices.","D":"Incorrect because improving working conditions usually increases rather than lowers supplier costs."}}},{"id":"P1_U6_MCQ_123","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_123","question":"An independent consumer pressure group tests household electrical appliances and publishes a report revealing that Brand Y's heaters overheat dangerously. What is the likely effect of this report on Brand Y?","options":{"A":"Brand Y's sales will increase because consumers appreciate honest testing","B":"Brand Y will face lower quality-control costs","C":"Brand Y will be exempt from consumer protection laws","D":"Brand Y will face a sharp drop in sales, costly product recalls, and possible government safety investigations"},"correctOption":"D","correctAnswer":"Brand Y will face a sharp drop in sales, costly product recalls, and possible government safety investigations","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumer watchdogs expose unsafe products, leading to collapsed demand, expensive recalls, and regulatory intervention.","distractor_reasons":{"A":"Incorrect because reports showing a product is dangerous cause consumers to avoid buying it.","B":"Incorrect because fixing design flaws increases quality and engineering costs.","C":"Incorrect because safety exposures trigger stricter enforcement of consumer protection laws.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_124","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_124","question":"Why has globalisation made it much harder for multinational companies to hide unethical or environmentally damaging practices in distant supplier factories?","options":{"A":"Because all countries now have identical minimum wage laws","B":"Because multinational companies no longer use overseas suppliers","C":"Because global communication and social media allow pressure groups to expose local abuses worldwide in real time","D":"Because import tariffs prevent any news from crossing national borders"},"correctOption":"C","correctAnswer":"Because global communication and social media allow pressure groups to expose local abuses worldwide in real time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because instant global internet and social media networks enable activists and journalists to broadcast evidence of abuses directly to consumers worldwide.","distractor_reasons":{"A":"Incorrect because minimum wage and environmental laws still vary significantly between countries.","B":"Incorrect because global supply chains remain widespread across industries.","C":"Correct selection.","D":"Incorrect because tariffs apply to traded goods, not digital news and social media."}}},{"id":"P1_U6_MCQ_125","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_125","question":"What is the ultimate goal of pressure groups when they organise boycotts, petitions, and media campaigns against private sector businesses?","options":{"A":"To take over daily management of the businesses and maximise shareholder dividends","B":"To force businesses to consider social, ethical, or environmental responsibilities alongside profit","C":"To eliminate all government regulations on business activity","D":"To reduce competition by driving all ethical firms out of the market"},"correctOption":"B","correctAnswer":"To force businesses to consider social, ethical, or environmental responsibilities alongside profit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because pressure groups aim to influence business decisions so companies act responsibly towards society, workers, consumers, and the environment.","distractor_reasons":{"A":"Incorrect because pressure groups do not seek to run businesses or maximise shareholder dividends.","B":"Correct selection.","C":"Incorrect because pressure groups often lobby for stronger, not weaker, government regulation.","D":"Incorrect because pressure groups support ethical practices rather than trying to eliminate ethical firms."}}},{"id":"P1_U6_MCQ_126","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_126","question":"After three years of rapid expansion, Country A's GDP growth slows sharply, interest rates hit a five-year high, and consumer confidence begins to drop. Which risk should an electronics retailer watch out for as the economy moves from the boom stage toward a recession?","options":{"A":"Holding excessive levels of expensive inventory that cannot be sold as demand falls","B":"Being unable to find any suppliers willing to sell smartphones and laptops","C":"Immediate deflation doubling the real value of cash held in till drawers","D":"Sudden labour shortages forcing the retailer to double shop assistants' wages"},"correctOption":"A","correctAnswer":"Holding excessive levels of expensive inventory that cannot be sold as demand falls","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because businesses often over-order stock at the peak of a boom; when demand falls into a recession, they are left with unsold inventory that ties up cash.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suppliers generally have excess stock rather than shortages when consumer demand begins to slow.","C":"Incorrect because prices do not instantly halve at the end of a boom, and retailers hold minimal cash in tills.","D":"Incorrect because severe labour shortages occur during the height of a boom, whereas slowing growth eases wage pressure."}}},{"id":"P1_U6_MCQ_127","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_127","question":"During a severe recession, household incomes fall and many consumers switch away from premium supermarkets to discount grocery stores selling low-priced own-label food. How does this shift affect a discount grocery chain?","options":{"A":"Its sales revenue and market share may increase despite the economic downturn","B":"Its fixed store rents will automatically double due to rising unemployment","C":"It will be forced by the government to raise its grocery prices","D":"Its suppliers will refuse to deliver basic food items during a recession"},"correctOption":"A","correctAnswer":"Its sales revenue and market share may increase despite the economic downturn","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because discount retailers sell basic necessity goods at low prices, attracting price-conscious shoppers whose incomes have fallen during a recession.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commercial property rents typically remain fixed under lease agreements or fall during a recession.","C":"Incorrect because governments do not force discount supermarkets to raise food prices during a downturn.","D":"Incorrect because food suppliers rely on discount chains for steady sales volume during recessions."}}},{"id":"P1_U6_MCQ_128","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_128","question":"An economy is stuck in a deep slump with high spare factory capacity across the manufacturing sector. Why is an industrial machinery maker likely to postpone investing in a new $5 million assembly line?","options":{"A":"Existing machines are already underused and future customer orders remain too uncertain","B":"Corporation tax rates are always set at 100% during a slump","C":"Machinery manufacturers are legally banned from expanding during a slump","D":"Worker productivity increases automatically without any capital investment"},"correctOption":"A","correctAnswer":"Existing machines are already underused and future customer orders remain too uncertain","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because low business confidence and spare capacity during a slump mean existing factories can meet weak demand without expensive new capital expenditure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because governments often lower, rather than raise, taxes during a slump to encourage investment.","C":"Incorrect because there is no legal ban on business investment during an economic slump.","D":"Incorrect because productivity does not automatically rise without investment in training or technology."}}},{"id":"P1_U6_MCQ_129","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_129","question":"Country B enters a sustained economic growth phase, with rising GDP, expanding business investment, and falling unemployment. Which human resource action will a fast-growing software firm most likely need to take?","options":{"A":"Make its senior software developers redundant to cut fixed costs","B":"Freeze all staff recruitment and close its training department","C":"Recruit additional skilled programmers and offer competitive pay packages to retain staff","D":"Cut hourly wage rates by 15% due to high national unemployment"},"correctOption":"C","correctAnswer":"Recruit additional skilled programmers and offer competitive pay packages to retain staff","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because rising demand during economic growth requires extra staff, while falling unemployment increases competition for skilled workers.","distractor_reasons":{"A":"Incorrect because growing demand requires expanding capacity rather than making key developers redundant.","B":"Incorrect because freezing recruitment would prevent the firm from meeting rising customer orders.","C":"Correct selection.","D":"Incorrect because unemployment falls during the growth stage, putting upward rather than downward pressure on wages."}}},{"id":"P1_U6_MCQ_130","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_130","question":"Rapid inflation of 14% per year causes wholesale ingredient, packaging, and energy prices to change almost every month. What is a direct operational cost for a national restaurant chain caused by this high inflation?","options":{"A":"Frequent 'menu costs' from constantly updating printed menus, websites, and price lists","B":"Lower interest rates charged on all new commercial bank loans","C":"Automatic reductions in employee wage demands","D":"Increased international competitiveness of its domestic food exports"},"correctOption":"A","correctAnswer":"Frequent 'menu costs' from constantly updating printed menus, websites, and price lists","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high inflation forces businesses to repeatedly revise and reprint menus, catalogues, and digital pricing systems, increasing administrative costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because central banks typically raise, rather than lower, interest rates to fight high inflation.","C":"Incorrect because workers demand higher wages during high inflation to protect their living standards.","D":"Incorrect because high domestic inflation makes a country's exports more expensive and less competitive."}}},{"id":"P1_U6_MCQ_131","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_131","question":"Country C experiences a period of deflation, where average retail prices fall by 3% per year. Why is this a problem for a retailer selling expensive home appliances such as televisions and washing machines?","options":{"A":"Consumers delay buying big-ticket items because they expect prices to be even lower next month","B":"The real value of the retailer's fixed debt repayments decreases every month","C":"Consumers rush to spend all their savings immediately before prices fall further","D":"Import tariffs on foreign appliances are automatically abolished"},"correctOption":"A","correctAnswer":"Consumers delay buying big-ticket items because they expect prices to be even lower next month","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because during deflation, consumers postpone non-urgent expensive purchases in anticipation of cheaper prices later, causing retail sales to fall.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because falling prices increase, rather than decrease, the real burden of fixed debt repayments.","C":"Incorrect because falling prices encourage consumers to delay spending, whereas rising inflation encourages buying early.","D":"Incorrect because deflation does not automatically remove government import tariffs."}}},{"id":"P1_U6_MCQ_132","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_132","question":"A major shipbuilding yard in a coastal town closes down, leaving 4,000 workers unemployed. How does this rise in local unemployment affect independent cafes, cinemas, and clothing shops in the town?","options":{"A":"Their sales fall sharply because unemployed households cut back on non-essential local spending","B":"Their corporation tax rate increases to pay for unemployment benefits","C":"Their sales increase because unemployed workers have more free time to shop","D":"Their electricity and water bills drop to zero"},"correctOption":"A","correctAnswer":"Their sales fall sharply because unemployed households cut back on non-essential local spending","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job losses reduce household disposable incomes across the community, causing a knock-on fall in demand for local retail and leisure businesses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because national corporation tax rates are not raised specifically on local shops when a factory closes.","C":"Incorrect because having more free time does not increase spending when household income has collapsed.","D":"Incorrect because utility suppliers continue charging businesses for energy and water used."}}},{"id":"P1_U6_MCQ_133","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_133","question":"Country D achieves 6% annual economic growth for three consecutive years, leading to surging freight volumes across the country. Which challenge might a road haulage company face as a result of this rapid growth?","options":{"A":"Severe road congestion and shortages of qualified truck drivers increasing delivery costs","B":"Falling demand for transporting raw materials and finished goods","C":"High levels of spare warehouse capacity and idle delivery lorries","D":"Government bans on private logistics companies operating on highways"},"correctOption":"A","correctAnswer":"Severe road congestion and shortages of qualified truck drivers increasing delivery costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid economic growth strains transport infrastructure (causing traffic delays) and tightens the labour market for skilled drivers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher GDP means more goods are produced and transported, increasing haulage demand.","C":"Incorrect because warehouses and lorries operate near full capacity during strong economic growth.","D":"Incorrect because economic growth does not lead to bans on private transport firms."}}},{"id":"P1_U6_MCQ_134","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_134","question":"Which of the following is one of the four main government economic objectives studied in Business Studies?","options":{"A":"Achieving low and stable inflation","B":"Maximising dividend payouts for all public limited companies","C":"Eliminating all imports from foreign countries","D":"Ensuring every business operates as a sole trader"},"correctOption":"A","correctAnswer":"Achieving low and stable inflation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the four core macroeconomic objectives are low inflation, low unemployment, economic growth, and a positive/balanced balance of payments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dividend levels are decided by company directors and shareholders, not government economic targets.","C":"Incorrect because governments aim for a sustainable balance of payments, not zero imports.","D":"Incorrect because governments allow multiple legal forms of business ownership (sole traders, partnerships, limited companies)."}}},{"id":"P1_U6_MCQ_135","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_135","question":"To boost household spending, a government raises the tax-free personal income tax allowance so workers keep more of their wages before paying tax. Which type of business will benefit most from this fiscal policy change?","options":{"A":"A domestic retailer selling mid-priced family clothing and household goods","B":"A company that only manufactures military equipment for foreign governments","C":"A debt collection agency relying on households defaulting on loans","D":"An insolvency practitioner specialising in closing bankrupt shops"},"correctOption":"A","correctAnswer":"A domestic retailer selling mid-priced family clothing and household goods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting personal income tax increases workers' disposable income, directly boosting domestic retail spending on family goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because foreign defence contracts depend on overseas government budgets rather than domestic income tax.","C":"Incorrect because higher disposable incomes help households pay their bills, reducing loan defaults.","D":"Incorrect because stronger retail sales reduce business failures rather than increasing insolvencies."}}},{"id":"P1_U6_MCQ_136","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_136","question":"A manufacturing company makes an annual profit before tax of $480,000. The government reduces the rate of corporation tax from 25% to 20%. How much tax does the company save as a result of this tax cut?","options":{"A":"$24,000","B":"$96,000","C":"$120,000","D":"$5,000"},"correctOption":"A","correctAnswer":"$24,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at 25%, tax was $120,000 ($480,000 × 0.25), and at 20%, tax is $96,000 ($480,000 × 0.20), resulting in a tax saving of $24,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $96,000 is the new total tax bill after the cut, not the amount saved.","C":"Incorrect because $120,000 was the original tax paid before the tax cut.","D":"Incorrect because $5,000 is 5% of $100,000 rather than 5% of $480,000."}}},{"id":"P1_U6_MCQ_137","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_137","question":"A government raises indirect excise duties on diesel and petrol by 20% to reduce carbon emissions. How does this tax change directly affect a national parcel delivery company?","options":{"A":"Its variable transport costs rise, reducing profit margins unless delivery fees are increased","B":"Its parcel delivery vans become exempt from road safety inspections","C":"Its corporation tax rate automatically drops by 20%","D":"Its competitors' fuel costs fall while its own costs rise"},"correctOption":"A","correctAnswer":"Its variable transport costs rise, reducing profit margins unless delivery fees are increased","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fuel is a major variable operating cost for delivery businesses; higher fuel duty increases running costs per delivery.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher fuel taxes do not waive vehicle safety regulations.","C":"Incorrect because indirect fuel taxes do not reduce direct corporation tax rates.","D":"Incorrect because fuel excise duties apply equally to all businesses buying diesel and petrol."}}},{"id":"P1_U6_MCQ_138","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_138","question":"The government increases Value Added Tax (VAT), a general indirect sales tax, from 15% to 20%. Why does this hurt a high-street hairdressing salon more than an online software firm selling mainly to other businesses?","options":{"A":"Individual consumers cannot reclaim VAT on haircuts, so the effective price rises by 5%","B":"Hairdressing salons must pay VAT even if they make zero sales all year","C":"Software firms are legally exempt from paying any taxes anywhere in the world","D":"Hairdressers must pay VAT twice on every haircut"},"correctOption":"A","correctAnswer":"Individual consumers cannot reclaim VAT on haircuts, so the effective price rises by 5%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because final household consumers bear the full price increase of VAT, whereas VAT-registered business customers can usually reclaim VAT on purchases.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because VAT is charged as a percentage of sales revenue; zero sales means zero VAT owed.","C":"Incorrect because software companies are subject to corporation tax and sales taxes like other firms.","D":"Incorrect because VAT is only charged once on the final price paid by the salon customer."}}},{"id":"P1_U6_MCQ_139","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_139","question":"To encourage domestic innovation, a government increases public expenditure by offering research and development (R&D) grants to biotechnology firms. How does this government spending benefit a biotech start-up?","options":{"A":"It reduces the financial risk and net cost of developing new medical treatments","B":"It guarantees that every new drug will be approved without clinical trials","C":"It eliminates all competition from international pharmaceutical companies","D":"It forces banks to cancel the start-up's existing loans"},"correctOption":"A","correctAnswer":"It reduces the financial risk and net cost of developing new medical treatments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because government R&D grants provide non-repayable funds that help cover expensive research costs and lower financial risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because medical safety trials remain mandatory regardless of government funding.","C":"Incorrect because grants support domestic firms but do not ban foreign competitors.","D":"Incorrect because grants do not cancel existing commercial bank debt."}}},{"id":"P1_U6_MCQ_140","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_140","question":"In a capital city where 35% of residents work as civil servants, teachers, or hospital staff, the government freezes public sector wages for three years to cut spending. How will this affect local restaurants and shops in the city?","options":{"A":"Local consumer spending will stagnate or fall as public sector workers' real incomes shrink","B":"Local shops will see a boom in luxury spending by civil servants","C":"Local businesses will pay lower property taxes automatically","D":"Interest rates in the capital city will drop to zero"},"correctOption":"A","correctAnswer":"Local consumer spending will stagnate or fall as public sector workers' real incomes shrink","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because freezing wages for a huge portion of the local workforce reduces their real purchasing power, lowering sales for nearby shops and restaurants.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because frozen wages combined with inflation reduce, rather than boost, luxury spending.","C":"Incorrect because central government wage freezes do not automatically reduce local business property taxes.","D":"Incorrect because interest rates are set nationally by the central bank, not locally for one city."}}},{"id":"P1_U6_MCQ_141","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_141","question":"A hotel chain expanded rapidly using variable-rate mortgages and now owes $10 million to banks. How does a central bank decision to cut interest rates from 6% to 3% help this hotel chain?","options":{"A":"Its annual interest payments fall by half, improving cash flow and net profit","B":"Its hotel room occupancy drops because holidays become more expensive","C":"Its property assets lose half their market value","D":"It is forced to repay the entire $10 million loan immediately"},"correctOption":"A","correctAnswer":"Its annual interest payments fall by half, improving cash flow and net profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because halving the interest rate on variable-rate debt halves the annual interest expense, directly boosting cash flow and profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower interest rates leave consumers with more disposable income, boosting leisure travel.","C":"Incorrect because lower interest rates generally support or raise property values rather than halving them.","D":"Incorrect because lower interest rates reduce repayment pressure rather than triggering immediate principal repayment."}}},{"id":"P1_U6_MCQ_142","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_142","question":"When the central bank raises interest rates sharply, commercial banks increase the interest paid on household savings accounts from 1% to 5.5%. Why does this reduce sales for a luxury jewellery store?","options":{"A":"Households have a stronger incentive to save money in banks rather than spend on luxury items","B":"Gold and diamond prices become regulated by the central bank","C":"Jewellery stores are legally required to close on weekends when interest rates rise","D":"Income tax rates rise automatically whenever savings rates increase"},"correctOption":"A","correctAnswer":"Households have a stronger incentive to save money in banks rather than spend on luxury items","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher interest rates increase the opportunity cost of spending—saving yields a higher return, encouraging households to save instead of buying luxuries.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because central banks set base interest rates, not retail jewellery prices.","C":"Incorrect because interest rate changes do not restrict retail opening hours.","D":"Incorrect because income tax is controlled by government fiscal policy, not bank deposit rates."}}},{"id":"P1_U6_MCQ_143","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_143","question":"A bakery has an existing variable-rate bank loan of $500,000. If the central bank raises interest rates from 4% to 7% per year, by how much will the bakery's annual interest expense increase?","options":{"A":"$15,000","B":"$35,000","C":"$20,000","D":"$3,000"},"correctOption":"A","correctAnswer":"$15,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at 4%, annual interest is $20,000 ($500,000 × 0.04), and at 7%, annual interest is $35,000 ($500,000 × 0.07), an increase of $15,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $35,000 is the new total annual interest payment, not the increase.","C":"Incorrect because $20,000 was the original annual interest payment at 4%.","D":"Incorrect because $3,000 is 3% of $100,000 rather than 3% of $500,000."}}},{"id":"P1_U6_MCQ_144","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_144","question":"To boost long-term economic growth, a government invests heavily in technical colleges, digital skills bootcamps, and university engineering scholarships. How does this government spending benefit manufacturing businesses?","options":{"A":"It increases the supply of skilled workers, raising productivity and lowering recruitment bottlenecks","B":"It immediately lowers the central bank's base interest rate","C":"It removes all import tariffs on foreign manufactured goods","D":"It allows factories to ignore workplace health and safety standards"},"correctOption":"A","correctAnswer":"It increases the supply of skilled workers, raising productivity and lowering recruitment bottlenecks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because government spending on education and training improves workforce skills, increasing labour productivity and reducing skill shortages for firms.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because education spending is fiscal policy and does not directly lower central bank interest rates.","C":"Incorrect because training budgets do not alter international trade tariffs.","D":"Incorrect because safety regulations apply regardless of government education funding."}}},{"id":"P1_U6_MCQ_145","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_145","question":"Facing high inflation in raw material prices, a food manufacturer signs a two-year fixed-price supply contract with its flour and sugar suppliers. What is the main advantage of this response?","options":{"A":"It protects the manufacturer against further input price rises, making costs predictable","B":"It forces consumers to buy twice as much bread and biscuits","C":"It exempts the manufacturer from paying Value Added Tax","D":"It eliminates the need to store any flour or sugar"},"correctOption":"A","correctAnswer":"It protects the manufacturer against further input price rises, making costs predictable","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because locking in fixed input prices shields the business from ongoing inflation in ingredient costs and stabilises profit margins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supplier contracts stabilise costs but do not force consumers to buy more products.","C":"Incorrect because supply contracts do not alter tax obligations.","D":"Incorrect because physical ingredients still require storage and inventory management."}}},{"id":"P1_U6_MCQ_146","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_146","question":"During an economic recession, sales of $1,200 smartphones fall sharply as consumers hold onto older phones. Which strategic response would best help a smartphone maker maintain revenue during the downturn?","options":{"A":"Launch a reliable $250 budget smartphone model alongside interest-free monthly payment plans","B":"Raise the price of all smartphones by 25% to maintain total revenue","C":"Stop all product research and cancel customer warranties","D":"Sell exclusively in countries experiencing severe slumps"},"correctOption":"A","correctAnswer":"Launch a reliable $250 budget smartphone model alongside interest-free monthly payment plans","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because introducing lower-priced models and affordable instalment plans matches consumers' reduced purchasing power during a recession.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raising prices during a recession when incomes are falling will cause sales to collapse further.","C":"Incorrect because cancelling warranties damages brand trust and deters cautious buyers.","D":"Incorrect because focusing only on depressed markets worsens sales rather than spreading risk."}}},{"id":"P1_U6_MCQ_147","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_147","question":"Interest rates on commercial bank loans have risen to 9%, making borrowing very expensive. How could a profitable public limited company (plc) raise $15 million for a new warehouse without paying high bank interest?","options":{"A":"Issue new shares on the stock exchange or use retained profits","B":"Use a high-interest bank overdraft for five years","C":"Stop paying suppliers for two years","D":"Borrow money using personal credit cards"},"correctOption":"A","correctAnswer":"Issue new shares on the stock exchange or use retained profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because equity finance (issuing shares) and internal finance (retained profit) do not incur interest charges, making them attractive when interest rates are high.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overdrafts carry even higher interest rates than long-term loans and can be recalled at short notice.","C":"Incorrect because refusing to pay suppliers breaches contracts and cuts off deliveries.","D":"Incorrect because credit cards carry extremely high interest rates and cannot fund $15 million projects."}}},{"id":"P1_U6_MCQ_148","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_148","question":"A government cuts income tax and increases public spending to reduce unemployment, but businesses already operating at full capacity respond by raising their prices. Which macroeconomic conflict does this illustrate?","options":{"A":"Policies aimed at lowering unemployment and boosting growth can trigger higher inflation","B":"Lower taxes always cause GDP to shrink and unemployment to double","C":"Full capacity always leads to deflation and falling wages","D":"Increasing government spending always lowers import levels to zero"},"correctOption":"A","correctAnswer":"Policies aimed at lowering unemployment and boosting growth can trigger higher inflation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because stimulating demand when firms are near full capacity creates excess demand, pulling prices upward and causing inflation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower taxes boost spending and GDP rather than shrinking the economy.","C":"Incorrect because operating at full capacity creates upward price pressure (inflation), not deflation.","D":"Incorrect because higher incomes from public spending usually increase demand for imports rather than eliminating them."}}},{"id":"P1_U6_MCQ_149","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_149","question":"The government raises the national legal minimum wage by 12%. Why does this affect a labour-intensive garment factory much more than a highly automated chemical plant?","options":{"A":"Wages make up a much larger share of total costs in a labour-intensive factory, and many workers earn near the minimum wage","B":"Automated chemical plants are legally exempt from all employment laws","C":"Garment factories are not allowed to raise their selling prices","D":"Chemical plants do not pay any taxes on their profits"},"correctOption":"A","correctAnswer":"Wages make up a much larger share of total costs in a labour-intensive factory, and many workers earn near the minimum wage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because labour-intensive firms employ large numbers of lower-paid workers, so minimum wage hikes cause a much bigger percentage jump in total costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because chemical plants must obey minimum wage laws too, though their engineers usually already earn well above the minimum.","C":"Incorrect because garment makers can raise prices, though competition may limit their ability to do so.","D":"Incorrect because chemical companies pay corporation tax like other businesses."}}},{"id":"P1_U6_MCQ_150","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_150","question":"In its annual budget speech, a government announces four policy measures. Which of these measures is an example of monetary policy rather than fiscal policy?","options":{"A":"Instructing the central bank to raise base interest rates by 0.75%","B":"Reducing corporation tax on small businesses from 20% to 15%","C":"Increasing government spending on state hospitals by $3 billion","D":"Introducing a new 5% indirect sales tax on luxury yachts"},"correctOption":"A","correctAnswer":"Instructing the central bank to raise base interest rates by 0.75%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because monetary policy involves controlling interest rates and the money supply, whereas fiscal policy covers taxation and government expenditure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because changing corporation tax is a fiscal policy measure.","C":"Incorrect because changing government expenditure is a fiscal policy measure.","D":"Incorrect because introducing a new sales tax is a fiscal policy measure."}}},{"id":"P1_U6_MCQ_151","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_151","question":"The invention of standardised shipping containers and larger refrigerated cargo vessels has dramatically reduced the cost of transporting fresh fruit across oceans. How has this contributed to globalisation?","options":{"A":"It allows agricultural exporters to sell perishable goods profitably to distant international markets","B":"It increases import tariffs on all agricultural products worldwide","C":"It forces consumers to buy only locally grown seasonal fruit","D":"It eliminates the need for any customs checks at international ports"},"correctOption":"A","correctAnswer":"It allows agricultural exporters to sell perishable goods profitably to distant international markets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because faster, cheaper global transport enables businesses to trade bulky and perishable goods across continents at competitive prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because transport technology lowers shipping costs and does not raise government tariffs.","C":"Incorrect because refrigerated shipping expands year-round access to imported fruit rather than restricting choice.","D":"Incorrect because goods crossing borders still undergo customs and biosecurity inspections."}}},{"id":"P1_U6_MCQ_152","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_152","question":"Rapid economic development in newly industrialised countries has created hundreds of millions of new middle-class consumers. What opportunity does this aspect of globalisation create for a European luxury cosmetics brand?","options":{"A":"Access to huge, fast-growing overseas consumer markets with rising disposable incomes","B":"Complete elimination of all marketing and distribution costs","C":"Automatic protection from all local and international competitors","D":"Exemption from labelling requirements in foreign countries"},"correctOption":"A","correctAnswer":"Access to huge, fast-growing overseas consumer markets with rising disposable incomes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising incomes in emerging economies expand global demand for branded and luxury consumer goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because entering new foreign markets requires significant marketing and distribution investment.","C":"Incorrect because global expansion brings intense competition from rival brands.","D":"Incorrect because cosmetics must still meet local ingredient and language labelling laws."}}},{"id":"P1_U6_MCQ_153","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_153","question":"A bicycle manufacturer in Germany sources steel frames from Taiwan, gears from Japan, and tyres from Thailand before assembling the bikes in Germany. What is the main advantage of this global sourcing strategy?","options":{"A":"Obtaining high-quality specialist components at lower unit costs from the most efficient global suppliers","B":"Eliminating any risk of shipping delays across oceans","C":"Avoiding all foreign exchange rate movements","D":"Reducing the number of suppliers to a single local firm"},"correctOption":"A","correctAnswer":"Obtaining high-quality specialist components at lower unit costs from the most efficient global suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because globalisation enables firms to buy specialised parts from whichever country produces them best and cheapest, lowering production costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sourcing from multiple distant countries actually increases exposure to shipping delays.","C":"Incorrect because buying components from multiple countries involves dealing with multiple foreign currencies.","D":"Incorrect because global sourcing involves multiple international suppliers rather than one local supplier."}}},{"id":"P1_U6_MCQ_154","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_154","question":"A UK car plant relies on just-in-time deliveries of electronic microchips shipped from East Asia. When a major typhoon closes Asian ports for three weeks, the UK factory has to halt production. Which risk of globalisation does this illustrate?","options":{"A":"Long global supply chains leave domestic production vulnerable to distant disruptions","B":"Import tariffs on British cars immediately rise to 100%","C":"UK workers become less skilled when components are imported","D":"Domestic consumers stop buying cars whenever typhoons occur abroad"},"correctOption":"A","correctAnswer":"Long global supply chains leave domestic production vulnerable to distant disruptions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because interdependent global supply chains mean natural disasters, strikes, or port closures in one country can halt production thousands of miles away.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because weather disruptions at ports do not trigger automatic tariff hikes.","C":"Incorrect because worker skills are unaffected by port delays.","D":"Incorrect because the problem is a supply-side shortage of microchips, not a collapse in car demand."}}},{"id":"P1_U6_MCQ_155","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_155","question":"As international labour mobility increases under globalisation, experienced hospital nurses and software engineers in Country K migrate abroad for higher salaries. How does this affect businesses and hospitals in Country K?","options":{"A":"They suffer skill shortages and must raise pay or improve conditions to retain remaining staff","B":"They benefit from an oversupply of cheap, experienced specialists","C":"Their corporation tax bills are refunded by the government","D":"They no longer need to train newly hired graduates"},"correctOption":"A","correctAnswer":"They suffer skill shortages and must raise pay or improve conditions to retain remaining staff","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the emigration of skilled professionals ('brain drain') shrinks the domestic talent pool, creating recruitment difficulties and wage pressure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because outward migration reduces, rather than increases, the supply of skilled specialists.","C":"Incorrect because skill emigration does not trigger tax refunds.","D":"Incorrect because losing experienced staff increases the need to train new recruits."}}},{"id":"P1_U6_MCQ_156","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_156","question":"Member countries of a regional trade bloc agree to use identical safety, labelling, and technical standards for all electrical appliances sold within the bloc. How does this benefit a toaster manufacturer inside the bloc?","options":{"A":"It can sell the exact same toaster model across all member countries without costly redesigns or separate safety tests","B":"It is guaranteed a 100% market share in every member country","C":"It no longer has to pay wages to factory quality inspectors","D":"Its raw material costs drop to zero"},"correctOption":"A","correctAnswer":"It can sell the exact same toaster model across all member countries without costly redesigns or separate safety tests","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because harmonised product regulations eliminate non-tariff barriers, allowing firms to achieve economies of scale with standardised products.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because competitors within the bloc also enjoy the same ease of market access.","C":"Incorrect because quality assurance staff are still required to meet the shared standards.","D":"Incorrect because standardised regulations reduce compliance costs, not raw material prices."}}},{"id":"P1_U6_MCQ_157","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_157","question":"Country L has just established its own domestic solar panel industry, which currently has higher unit costs than established foreign manufacturers. Why might Country L's government place temporary tariffs on imported solar panels?","options":{"A":"To protect the 'infant industry' until domestic firms grow large enough to achieve economies of scale and compete globally","B":"To force domestic solar panel factories to close down immediately","C":"To make solar energy more expensive so citizens burn more coal","D":"To reduce government customs tax revenue"},"correctOption":"A","correctAnswer":"To protect the 'infant industry' until domestic firms grow large enough to achieve economies of scale and compete globally","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because protecting new ('infant') industries from established foreign rivals gives domestic firms time to grow, invest, and lower unit costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tariffs shield domestic factories from foreign competition rather than closing them.","C":"Incorrect because the goal is to build a competitive domestic green industry, not promote coal.","D":"Incorrect because tariffs increase, rather than reduce, customs tax revenue."}}},{"id":"P1_U6_MCQ_158","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_158","question":"Country A imposes a 25% tariff on cheese imported from Country B. In retaliation, Country B places a 25% tariff on cars exported from Country A. What is the main drawback of protectionism shown here?","options":{"A":"Trade wars harm exporting industries in both countries and reduce overall international trade","B":"Consumers in both countries enjoy much lower prices for cheese and cars","C":"Car manufacturers in Country A automatically double their overseas profits","D":"Both countries achieve faster economic growth through fewer exports"},"correctOption":"A","correctAnswer":"Trade wars harm exporting industries in both countries and reduce overall international trade","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because protectionist tariffs often provoke retaliatory tariffs from trading partners, damaging efficient domestic exporters.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tariffs raise prices for consumers in both countries.","C":"Incorrect because retaliatory tariffs make Country A's cars more expensive in Country B, reducing sales and profits.","D":"Incorrect because falling exports and higher costs slow down economic growth."}}},{"id":"P1_U6_MCQ_159","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_159","question":"A government imposes a strict import quota limiting foreign sugar imports to 10,000 tonnes per year, far below national demand. How does this quota affect domestic consumers and food manufacturers?","options":{"A":"Sugar becomes scarce, driving up domestic prices and increasing costs for bakeries and sweet makers","B":"Sugar becomes completely free for all domestic bakeries","C":"Foreign sugar exporters pay higher customs duties directly to the government","D":"Domestic sugar producers are forced to lower their prices by 50%"},"correctOption":"A","correctAnswer":"Sugar becomes scarce, driving up domestic prices and increasing costs for bakeries and sweet makers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an import quota restricts total supply in the market, pushing domestic prices up and raising input costs for local food producers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because restricting supply raises prices rather than making sugar free.","C":"Incorrect because quotas limit physical volume rather than collecting a percentage customs tax (which is a tariff).","D":"Incorrect because reduced foreign competition allows domestic producers to charge higher, not lower, prices."}}},{"id":"P1_U6_MCQ_160","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_160","question":"A retail chain imports 500 laptops at a pre-tariff price of $600 each. If the government charges a 12% import tariff on laptops, what is the total cost of the shipment including the tariff?","options":{"A":"$336,000","B":"$300,000","C":"$36,000","D":"$312,000"},"correctOption":"A","correctAnswer":"$336,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the pre-tariff shipment value is $300,000 (500 × $600), and a 12% tariff adds $36,000 ($300,000 × 0.12), giving a total cost of $336,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $300,000 is the pre-tariff value excluding the 12% customs duty.","C":"Incorrect because $36,000 is only the tariff amount, not the total cost of the laptops.","D":"Incorrect because $312,000 adds $12,000 instead of 12% of $300,000."}}},{"id":"P1_U6_MCQ_161","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_161","question":"Company X has one factory and one head office in Spain and ships handmade leather shoes by courier to online customers in 40 countries. Company Y has factories in Spain, Morocco, and Brazil. Which statement is accurate?","options":{"A":"Company Y is a multinational company (MNC), whereas Company X is an exporter","B":"Both Company X and Company Y are multinational companies","C":"Company X is a multinational company, whereas Company Y is a sole trader","D":"Neither company is involved in international business"},"correctOption":"A","correctAnswer":"Company Y is a multinational company (MNC), whereas Company X is an exporter","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an MNC must have physical operations (factories, offices, or stores) in more than one country; merely exporting from one home base does not make a firm an MNC.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Company X has no physical facilities outside Spain.","C":"Incorrect because Company X has no overseas operations and Company Y operates across three countries.","D":"Incorrect because both firms engage in international trade and operations."}}},{"id":"P1_U6_MCQ_162","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_162","question":"An electric vehicle battery manufacturer establishes mining and refining operations in Chile and Australia. What is the primary strategic reason for becoming a multinational company in this case?","options":{"A":"To secure direct access to scarce raw materials such as lithium required for battery production","B":"To avoid paying any wages to mining engineers","C":"To eliminate all transport distances between mines and customers","D":"To ensure its shares can never be bought by foreign investors"},"correctOption":"A","correctAnswer":"To secure direct access to scarce raw materials such as lithium required for battery production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because many MNCs expand abroad to secure reliable, direct supplies of key natural resources and minerals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because skilled mining engineers in Australia and Chile command high salaries.","C":"Incorrect because locating near raw materials still requires shipping refined materials to battery factories.","D":"Incorrect because operating overseas does not restrict stock market share ownership."}}},{"id":"P1_U6_MCQ_163","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_163","question":"A telecommunications company finds that almost every adult in its small domestic market already owns a mobile phone contract, leaving little room for growth. Why might it become an MNC?","options":{"A":"To enter larger, unsaturated overseas markets where mobile phone ownership is still growing rapidly","B":"Because governments force profitable companies to close their domestic headquarters","C":"To avoid having to provide customer service to any subscribers","D":"Because operating in multiple countries guarantees zero fixed costs"},"correctOption":"A","correctAnswer":"To enter larger, unsaturated overseas markets where mobile phone ownership is still growing rapidly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when a domestic market is saturated, expanding operations into growing foreign markets is a major way to increase sales and profits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because governments do not force profitable firms to close their domestic headquarters.","C":"Incorrect because telecom MNCs must still provide customer support in every country they serve.","D":"Incorrect because building telecom networks abroad involves massive fixed capital costs."}}},{"id":"P1_U6_MCQ_164","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_164","question":"When an American fast-food MNC opens restaurants in India, it removes beef from its menu and introduces spicy vegetarian burgers. Which challenge of operating as an MNC does this illustrate?","options":{"A":"Adapting products and marketing to respect local cultural and religious preferences","B":"Overcoming import quotas on computer software","C":"Avoiding corporation tax in the United States","D":"Reducing the span of control in its American head office"},"correctOption":"A","correctAnswer":"Adapting products and marketing to respect local cultural and religious preferences","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because MNCs must adapt their products, menus, and promotional campaigns to suit diverse cultural and religious norms in host countries.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fast-food menu adaptation has nothing to do with software import quotas.","C":"Incorrect because menu changes are driven by local consumer tastes, not US tax avoidance.","D":"Incorrect because localising menus is a marketing adaptation, not a head-office organisational chart change."}}},{"id":"P1_U6_MCQ_165","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_165","question":"A multinational engineering group operates subsidiaries across 25 countries speaking 15 different languages and spanning multiple time zones. Which operational problem is the MNC likely to experience?","options":{"A":"Communication delays and difficulties coordinating decisions across distant branches","B":"Complete inability to sell products outside its home city","C":"Lack of access to international financial markets","D":"Zero competition from local businesses in host countries"},"correctOption":"A","correctAnswer":"Communication delays and difficulties coordinating decisions across distant branches","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managing operations across multiple countries, languages, and time zones creates communication barriers and coordination diseconomies of scale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an MNC with 25 country subsidiaries actively sells across global markets.","C":"Incorrect because large MNCs usually enjoy superior access to global capital markets.","D":"Incorrect because MNCs face competition from domestic and international rivals in host countries."}}},{"id":"P1_U6_MCQ_166","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_166","question":"Before opening a major manufacturing hub in a developing region, a multinational logistics company funds the upgrading of nearby roads, electricity grids, and port facilities. How does this benefit the host country?","options":{"A":"Improved local infrastructure benefits domestic businesses and residents as well as the MNC","B":"Local businesses are banned from using the upgraded roads and electricity grids","C":"The host government's tax revenue falls to zero permanently","D":"All natural resources in the region are preserved untouched"},"correctOption":"A","correctAnswer":"Improved local infrastructure benefits domestic businesses and residents as well as the MNC","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because MNC investment often brings improvements to transport, energy, and telecom infrastructure that boost the wider host economy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because public roads and power grids upgraded for industrial development also serve local firms and communities.","C":"Incorrect because economic activity generated by the MNC increases tax revenues.","D":"Incorrect because industrial development uses energy and land rather than leaving areas untouched."}}},{"id":"P1_U6_MCQ_167","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_167","question":"A multinational aerospace manufacturer builds a component factory in Country M and trains 1,500 local engineers in advanced computer-aided manufacturing techniques. What is this benefit to Country M called?","options":{"A":"Technology and skills transfer","B":"Repatriation of profits","C":"Import tariff protection","D":"Currency depreciation"},"correctOption":"A","correctAnswer":"Technology and skills transfer","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because MNCs introduce modern production methods and train local workers, raising the skill level and productivity of the host country's workforce.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because repatriation of profits refers to sending earnings back to the MNC's home country.","C":"Incorrect because tariffs are government taxes on imports.","D":"Incorrect because currency depreciation is a fall in the exchange rate."}}},{"id":"P1_U6_MCQ_168","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_168","question":"Ten years after opening a clothing assembly plant in Country N, a multinational fashion group suddenly closes the factory and moves production to another country where wages are 30% lower. What disadvantage of MNCs does this show?","options":{"A":"MNCs can be 'footloose', relocating quickly to chase lower costs and causing sudden regional unemployment","B":"MNCs are legally required to stay in every host country for at least 100 years","C":"Closing a factory always increases the host government's tax revenue","D":"Local suppliers benefit from losing their largest customer"},"correctOption":"A","correctAnswer":"MNCs can be 'footloose', relocating quickly to chase lower costs and causing sudden regional unemployment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because MNCs often shift production between countries as relative wage costs change, leaving host communities with sudden job losses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because private MNCs can close overseas branches when they are no longer cost-competitive.","C":"Incorrect because factory closures reduce income tax, sales tax, and corporation tax receipts.","D":"Incorrect because local suppliers lose orders and may also be forced to close."}}},{"id":"P1_U6_MCQ_169","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_169","question":"A huge multinational oil company accounts for 20% of Country P's GDP and threatens to cancel future investments if Country P passes stricter pollution laws. Which drawback of MNCs does this illustrate?","options":{"A":"Excessive economic power allowing MNCs to influence host government policies","B":"Increased consumer choice in domestic retail markets","C":"Higher exports improving the balance of payments","D":"Improved training for local environmental scientists"},"correctOption":"A","correctAnswer":"Excessive economic power allowing MNCs to influence host government policies","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large MNCs contribute heavily to jobs and GDP, giving them bargaining power to pressure host governments into relaxing taxes or regulations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because threatening to withdraw investment over pollution rules is a political/regulatory issue, not retail consumer choice.","C":"Incorrect because the scenario highlights regulatory coercion rather than trade balance gains.","D":"Incorrect because resisting pollution laws undermines environmental standards."}}},{"id":"P1_U6_MCQ_170","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_170","question":"In a floating exchange rate system, the value of Country Q's currency rises from $1.20 to $1.45 over one year due to strong foreign demand for Country Q's exports. What is this rise in currency value called?","options":{"A":"Currency appreciation","B":"Currency depreciation","C":"Cost-push inflation","D":"Import quota"},"correctOption":"A","correctAnswer":"Currency appreciation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because currency appreciation occurs when a currency increases in value relative to other currencies, buying more foreign currency per unit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because depreciation is a fall in the value of a currency against other currencies.","C":"Incorrect because inflation measures rising domestic prices of goods and services, not exchange rate movements.","D":"Incorrect because an import quota is a government limit on import quantities."}}},{"id":"P1_U6_MCQ_171","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_171","question":"A Japanese camera manufacturer exports a camera priced at ¥60,000 to the United States. If the Japanese yen depreciates from $1 = ¥100 to $1 = ¥120, what happens to the camera's selling price in US dollars?","options":{"A":"It falls from $600 to $500","B":"It rises from $500 to $600","C":"It rises from $600 to $720","D":"It stays unchanged at $600"},"correctOption":"A","correctAnswer":"It falls from $600 to $500","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at $1 = ¥100, ¥60,000 equals $600 (60,000 ÷ 100), and at $1 = ¥120, ¥60,000 equals $500 (60,000 ÷ 120).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the yen depreciated (each dollar now buys more yen), making Japanese goods cheaper in dollars.","C":"Incorrect because $720 multiplies by 1.2 instead of dividing ¥60,000 by 120.","D":"Incorrect because the yen price is fixed at ¥60,000, so the US dollar price changes with the exchange rate."}}},{"id":"P1_U6_MCQ_172","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_172","question":"A European airline buys aviation fuel priced in US dollars at $200,000 per shipment. If the euro appreciates from €1 = $1.00 to €1 = $1.25, how much does the fuel shipment cost the airline in euros?","options":{"A":"€160,000","B":"€250,000","C":"€200,000","D":"€125,000"},"correctOption":"A","correctAnswer":"€160,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at €1 = $1.25, $200,000 costs €160,000 ($200,000 ÷ 1.25), down from €200,000 when €1 = $1.00.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because €250,000 multiplies by 1.25 instead of dividing $200,000 by 1.25.","C":"Incorrect because €200,000 was the cost before the euro appreciated.","D":"Incorrect because €125,000 simply uses the exchange rate digits rather than dividing $200,000 by 1.25."}}},{"id":"P1_U6_MCQ_173","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_173","question":"Why do volatile, rapidly fluctuating exchange rates create difficulties for businesses that import raw materials and export finished goods?","options":{"A":"It becomes hard to predict future costs and revenues, making long-term contracts and budgeting risky","B":"Fluctuating exchange rates make international trade completely illegal","C":"Banks refuse to hold bank accounts for exporting companies","D":"Volatile exchange rates eliminate all domestic demand"},"correctOption":"A","correctAnswer":"It becomes hard to predict future costs and revenues, making long-term contracts and budgeting risky","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unpredictable exchange rate swings can turn a profitable export order into a loss between signing the contract and receiving payment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because floating exchange rates are standard in global trade and do not make trade illegal.","C":"Incorrect because banks provide foreign exchange accounts and services to exporters.","D":"Incorrect because domestic sales in home currency are not directly eliminated by exchange rate swings."}}},{"id":"P1_U6_MCQ_174","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_174","question":"Country R's currency depreciates sharply, making imported plastic packaging 25% more expensive for a domestic food producer. What is a practical operational response for the food producer?","options":{"A":"Switch to buying packaging from domestic suppliers priced in local currency","B":"Double the amount of imported packaging purchased each month","C":"Stop packaging its food products altogether","D":"Ask the central bank to ban all domestic manufacturing"},"correctOption":"A","correctAnswer":"Switch to buying packaging from domestic suppliers priced in local currency","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sourcing from domestic suppliers avoids expensive foreign currency payments and protects profit margins when the local currency weakens.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because buying more expensive imports would worsen variable costs and cash outflows.","C":"Incorrect because food products require hygienic packaging to meet health and safety laws.","D":"Incorrect because central banks manage monetary policy and cannot ban manufacturing."}}},{"id":"P1_U6_MCQ_175","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_175","question":"A Swiss precision watchmaker faces a long-term appreciation of the Swiss franc, which makes its watches more expensive abroad. How can the company maintain strong export sales despite higher foreign-currency prices?","options":{"A":"Focus on non-price factors such as superior quality, luxury brand image, and innovative design","B":"Lower product quality to match cheap mass-produced watches","C":"Stop advertising in all overseas markets","D":"Refuse to accept payments in major foreign currencies"},"correctOption":"A","correctAnswer":"Focus on non-price factors such as superior quality, luxury brand image, and innovative design","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when currency appreciation harms price competitiveness, differentiating through quality, branding, and innovation makes demand less price-sensitive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cutting quality destroys a luxury watchmaker's reputation and unique selling point.","C":"Incorrect because reducing promotion weakens brand appeal in competitive export markets.","D":"Incorrect because making it harder for foreign buyers to pay reduces export sales further."}}},{"id":"P1_U6_MCQ_176","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_176","question":"A large open-cast coal mining company clears 500 hectares of scenic hills next to a national park, leaving massive scars on the landscape and destroying wildlife habitats. Which environmental impacts are illustrated here?","options":{"A":"Visual pollution and loss of biodiversity","B":"Noise reduction and soil enrichment","C":"Renewable energy generation and reforestation","D":"External social benefits for tourism businesses"},"correctOption":"A","correctAnswer":"Visual pollution and loss of biodiversity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because open-cast mining spoils natural scenery (visual pollution) and destroys ecosystems (loss of biodiversity).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because open-cast mining increases noise and strips away fertile topsoil.","C":"Incorrect because coal is a non-renewable fossil fuel and clearing land destroys forests.","D":"Incorrect because scarring scenic hills next to a national park harms tourism rather than helping it."}}},{"id":"P1_U6_MCQ_177","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_177","question":"An online fast-fashion retailer promises free next-day delivery on every single item, resulting in thousands of half-empty delivery vans driving through city streets every day. Which environmental problem does this business model worsen?","options":{"A":"Traffic congestion and urban air pollution from exhaust emissions","B":"Over-reliance on solar-powered shipping vessels","C":"Depletion of deep-sea fish stocks","D":"Increased recycling of glass bottles"},"correctOption":"A","correctAnswer":"Traffic congestion and urban air pollution from exhaust emissions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because frequent, small-load road deliveries increase vehicle numbers, worsening traffic congestion and carbon/particulate air pollution.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because urban courier vans run mostly on diesel or petrol rather than solar shipping.","C":"Incorrect because city delivery vans affect air quality and traffic, not marine fish stocks.","D":"Incorrect because next-day fashion deliveries generate cardboard/plastic waste rather than glass recycling."}}},{"id":"P1_U6_MCQ_178","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_178","question":"An oil refinery suffers a pipeline leak. It pays $2 million to repair its own pipes and clean up its yard, while local hotels lose $3.5 million in cancelled bookings due to polluted beaches. How are these two costs classified?","options":{"A":"$2 million is a private cost; $3.5 million is an external cost","B":"$2 million is an external cost; $3.5 million is a private cost","C":"Both figures are external benefits to the community","D":"Both figures are private fixed costs paid by the hotels"},"correctOption":"A","correctAnswer":"$2 million is a private cost; $3.5 million is an external cost","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because private costs are paid directly by the business responsible ($2m), whereas external costs are unpaid damages imposed on third parties ($3.5m lost by hotels).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because it reverses private costs (borne by the refinery) and external costs (borne by third-party hotels).","C":"Incorrect because both figures represent financial losses and damages, not positive benefits.","D":"Incorrect because the refinery pays for its own pipe repairs, not the hotels."}}},{"id":"P1_U6_MCQ_179","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_179","question":"A commercial timber company plants 2 million new trees on degraded land to harvest in 25 years. While the trees grow, they absorb carbon dioxide and prevent soil erosion for surrounding farms. What do the carbon absorption and flood prevention represent?","options":{"A":"External benefits enjoyed by society","B":"Private costs paid by the timber company","C":"External costs imposed on local farmers","D":"Variable manufacturing expenses"},"correctOption":"A","correctAnswer":"External benefits enjoyed by society","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external benefits are positive side effects experienced by third parties (farmers and wider society) without paying the business for them.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because private costs are the expenses of buying and planting seedlings, not environmental gains.","C":"Incorrect because flood prevention and cleaner air help farmers rather than harming them.","D":"Incorrect because environmental improvements for society are externalities, not internal factory expenses."}}},{"id":"P1_U6_MCQ_180","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_180","question":"A private solar farm generates $320,000 per year in electricity sales revenue (private benefit) and reduces local air pollution healthcare expenses by $95,000 per year (external benefit). What is the annual social benefit?","options":{"A":"$415,000","B":"$225,000","C":"$320,000","D":"$95,000"},"correctOption":"A","correctAnswer":"$415,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social benefit equals private benefit ($320,000) plus external benefit ($95,000), which totals $415,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $225,000 subtracts external benefit from private benefit instead of adding them.","C":"Incorrect because $320,000 includes only the private benefit to the solar farm.","D":"Incorrect because $95,000 includes only the external benefit to society."}}},{"id":"P1_U6_MCQ_181","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_181","question":"A proposed chemical plant is estimated to generate $900,000 in social benefits, while incurring $650,000 in private costs and $300,000 in external pollution costs. Based on cost-benefit analysis, what should the government decide?","options":{"A":"Reject the proposal because total social costs ($950,000) exceed total social benefits ($900,000)","B":"Approve the proposal because private benefits exceed private costs","C":"Approve the proposal because external costs are smaller than private costs","D":"Reject the proposal because private costs are greater than external costs"},"correctOption":"A","correctAnswer":"Reject the proposal because total social costs ($950,000) exceed total social benefits ($900,000)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social cost is $950,000 ($650,000 + $300,000), which exceeds social benefit ($900,000) by $50,000, resulting in a net loss to society.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because government cost-benefit analysis considers total social costs and benefits, not just private figures.","C":"Incorrect because comparing external costs to private costs does not determine whether society gains overall.","D":"Incorrect because private costs exceeding external costs is normal and is not a criterion for rejection."}}},{"id":"P1_U6_MCQ_182","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_182","question":"A smartphone manufacturer offers customers a $50 discount on a new phone when they return their old phone, then extracts gold, cobalt, and aluminium from the old devices to build new ones. Which sustainable concept is this?","options":{"A":"Recycling materials to reduce resource depletion and electronic waste","B":"Increasing landfill waste to lower production costs","C":"Planned obsolescence to maximise short-term mining","D":"Generating external pollution costs for local rivers"},"correctOption":"A","correctAnswer":"Recycling materials to reduce resource depletion and electronic waste","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recovering and reprocessing metals from used electronics recycles scarce minerals and prevents toxic e-waste from entering landfills.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because taking back old phones reduces rather than increases landfill waste.","C":"Incorrect because recovering metals reduces the need for new mining.","D":"Incorrect because recycling reduces environmental pollution rather than creating it."}}},{"id":"P1_U6_MCQ_183","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_183","question":"A denim jeans factory installs a closed-loop water filtration system that cleans and reuses 95% of the water used in dyeing fabric, instead of pumping freshwater from a river and dumping dyed water back. What are the two main benefits?","options":{"A":"It prevents river water pollution and reduces the factory's metered water bills","B":"It eliminates all employee wage costs and doubles denim prices","C":"It increases chemical waste discharges and lowers product quality","D":"It exempts the factory from paying corporation tax"},"correctOption":"A","correctAnswer":"It prevents river water pollution and reduces the factory's metered water bills","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because closed-loop water recycling eliminates toxic dye discharges into rivers while cutting ongoing freshwater purchase costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because water filtration does not eliminate worker wages or double retail prices.","C":"Incorrect because closed-loop filtration prevents chemical discharges rather than increasing them.","D":"Incorrect because environmental investments do not exempt companies from corporation tax."}}},{"id":"P1_U6_MCQ_184","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_184","question":"A supermarket chain replaces air-freighted imported vegetables with seasonal produce grown by farmers within 50 kilometres of its stores. How does reducing 'food miles' help the environment?","options":{"A":"It significantly lowers transport fuel consumption and greenhouse gas emissions","B":"It increases the amount of plastic wrapping needed per vegetable","C":"It encourages more long-haul cargo flights","D":"It depletes overseas soil fertility faster"},"correctOption":"A","correctAnswer":"It significantly lowers transport fuel consumption and greenhouse gas emissions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sourcing locally cuts long-distance air and road transport, substantially reducing carbon emissions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shorter local supply chains often require less protective packaging.","C":"Incorrect because local sourcing replaces rather than encourages long-haul air freight.","D":"Incorrect because buying locally reduces pressure on overseas agricultural land."}}},{"id":"P1_U6_MCQ_185","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_185","question":"An insurance company replaces all halogen bulbs in its 12-storey office building with motion-sensor LED lighting and smart thermostats. Why is this an attractive environmental measure for the business?","options":{"A":"It cuts electricity consumption and lowers overhead utility bills with a relatively fast payback period","B":"It increases carbon emissions while raising employee productivity","C":"It forces clients to visit the office in person instead of using the website","D":"It eliminates the need to pay commercial property rent"},"correctOption":"A","correctAnswer":"It cuts electricity consumption and lowers overhead utility bills with a relatively fast payback period","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because energy-efficiency upgrades reduce both carbon emissions and ongoing electricity/heating overheads, creating a win-win for profit and the planet.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because LED lighting and smart thermostats reduce, rather than increase, carbon emissions.","C":"Incorrect because office energy management has no effect on how clients access services.","D":"Incorrect because utility savings lower energy bills, not property rent."}}},{"id":"P1_U6_MCQ_186","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_186","question":"Growing public concern over climate change and urban air quality has created new market opportunities. Which business strategy directly capitalises on this environmental trend?","options":{"A":"A bicycle manufacturer launching a range of lightweight electric commuter bikes","B":"A car maker discontinuing all hybrid and electric models to focus only on diesel SUVs","C":"A cleaning brand replacing biodegradable sprays with toxic aerosol chemicals","D":"A retailer introducing extra layers of non-recyclable plastic shrink-wrap"},"correctOption":"A","correctAnswer":"A bicycle manufacturer launching a range of lightweight electric commuter bikes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because developing zero-emission transport options meets growing consumer demand for sustainable alternatives, creating a profitable new revenue stream.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because abandoning electric vehicles ignores rising green demand and tighter emission rules.","C":"Incorrect because switching to toxic aerosols alienates environmentally aware consumers.","D":"Incorrect because increasing single-use plastic triggers customer backlash and potential regulatory fines."}}},{"id":"P1_U6_MCQ_187","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_187","question":"A traditional petrol-engine car manufacturer decides to transition its factories to produce battery-electric vehicles over the next five years. What is a major financial challenge of this green transition?","options":{"A":"Massive upfront capital investment in research, battery technology, and retooling factories","B":"Complete lack of consumer interest in zero-emission vehicles","C":"Governments banning the sale of electric vehicles in city centres","D":"Lower employee training requirements because electric cars use identical parts to petrol cars"},"correctOption":"A","correctAnswer":"Massive upfront capital investment in research, battery technology, and retooling factories","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because developing green technologies and re-equipping factories requires huge capital expenditure before full sales returns are realised.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumer demand for electric vehicles is growing rapidly.","C":"Incorrect because governments are banning petrol/diesel cars in cities, not electric vehicles.","D":"Incorrect because electric vehicles use completely different powertrains, requiring extensive staff retraining."}}},{"id":"P1_U6_MCQ_188","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_188","question":"Before a property developer can build a huge new shopping mall near a wetland reserve, environmental law requires it to fund an independent Environmental Impact Assessment (EIA). How does this legal control affect the developer?","options":{"A":"It increases pre-construction costs and delays building until wildlife and drainage protections are approved","B":"It allows the developer to drain the wetland immediately without planning permission","C":"It guarantees that the shopping mall will make a profit in its first year","D":"It exempts the developer from paying construction workers' wages"},"correctOption":"A","correctAnswer":"It increases pre-construction costs and delays building until wildlife and drainage protections are approved","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mandatory EIAs add time and consultancy costs to major projects and may require costly design changes to prevent external damage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the assessment prevents unapproved destruction of sensitive wetlands.","C":"Incorrect because environmental approvals do not guarantee commercial retail success.","D":"Incorrect because employment obligations are unaffected by planning regulations."}}},{"id":"P1_U6_MCQ_189","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_189","question":"A city council introduces an Ultra-Low Emission Zone (ULEZ), charging older, high-polluting diesel lorries $100 per day to enter the city centre. How does this regulation influence a food wholesaler delivering to city restaurants?","options":{"A":"It creates a strong financial incentive to upgrade to cleaner electric or low-emission delivery trucks","B":"It lowers the wholesaler's daily delivery costs when using old diesel lorries","C":"It forces all city restaurants to close down permanently","D":"It removes all traffic speed limits inside the city centre"},"correctOption":"A","correctAnswer":"It creates a strong financial incentive to upgrade to cleaner electric or low-emission delivery trucks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because daily pollution charges raise operating costs for older vehicles, making cleaner fleet investment more financially attractive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a $100 daily charge increases, rather than lowers, the cost of using older diesel lorries.","C":"Incorrect because restaurants remain open and continue receiving deliveries from compliant vehicles.","D":"Incorrect because emission zones regulate exhaust pollution, not speed limits."}}},{"id":"P1_U6_MCQ_190","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_190","question":"A government introduces a carbon tax charged per tonne of carbon dioxide emitted by industrial factories and power stations. What is the main purpose of a carbon tax?","options":{"A":"To make polluting firms pay for their external costs and encourage investment in cleaner energy","B":"To reward factories that burn the largest quantities of coal","C":"To lower the retail price of fossil fuels for heavy industry","D":"To eliminate all forms of taxation on multinational companies"},"correctOption":"A","correctAnswer":"To make polluting firms pay for their external costs and encourage investment in cleaner energy","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a carbon tax 'internalises' external pollution costs, raising the cost of fossil fuels so firms switch to energy efficiency and renewables.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because burning more coal increases carbon emissions and results in a higher tax bill.","C":"Incorrect because a carbon tax raises, rather than lowers, the effective cost of fossil fuels.","D":"Incorrect because a carbon tax adds an environmental levy rather than removing corporate taxes."}}},{"id":"P1_U6_MCQ_191","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_191","question":"To accelerate green manufacturing, a government allows businesses to deduct 100% of the cost of solar panels and heat pumps from their taxable profits in the first year. How does this tax incentive help businesses?","options":{"A":"It lowers their corporation tax bill in the year of purchase, improving cash flow for green investments","B":"It bans businesses from using electricity from the national grid","C":"It increases their Value Added Tax rate by 10%","D":"It forces businesses to sell their solar panels after twelve months"},"correctOption":"A","correctAnswer":"It lowers their corporation tax bill in the year of purchase, improving cash flow for green investments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because accelerated tax allowances reduce taxable profit and corporation tax payable, lowering the net cost of eco-friendly capital equipment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax incentives encourage green upgrades without banning grid electricity.","C":"Incorrect because corporation tax allowances do not raise indirect VAT rates.","D":"Incorrect because businesses keep and operate the equipment for decades to save energy."}}},{"id":"P1_U6_MCQ_192","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_192","question":"A beverage company redesigns its glass juice bottles so each bottle uses 20% less glass while holding the exact same amount of juice. Which waste-management principle is the company applying?","options":{"A":"Reducing resource consumption at the source","B":"Landfill incineration","C":"Resource depletion","D":"External cost creation"},"correctOption":"A","correctAnswer":"Reducing resource consumption at the source","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 'reducing' means designing products and packaging to use fewer raw materials and energy from the outset.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because incineration involves burning waste rather than cutting material weight.","C":"Incorrect because using 20% less glass conserves silica and energy rather than depleting resources.","D":"Incorrect because lighter bottles cut transport fuel emissions and waste, reducing external costs."}}},{"id":"P1_U6_MCQ_193","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_193","question":"A coal-mining company plans to close its last underground coal mine five years early to cut carbon emissions, but the local trade union opposes the closure because 800 miners will lose their jobs. Which conflict does this show?","options":{"A":"Environmental sustainability objectives conflicting with employees' job security","B":"Shareholders demanding lower dividends to protect wildlife","C":"Customers demanding higher coal prices","D":"Suppliers refusing to sell safety helmets to miners"},"correctOption":"A","correctAnswer":"Environmental sustainability objectives conflicting with employees' job security","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because closing polluting industries benefits the environment but creates immediate unemployment for workers who depend on those jobs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the conflict here is between environmental goals and worker employment, not shareholder dividends.","C":"Incorrect because customers do not demand higher prices.","D":"Incorrect because supplier equipment sales are not the cause of the conflict."}}},{"id":"P1_U6_MCQ_194","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_194","question":"A bakery switches to compostable cornstarch wrapping, which adds $0.30 to the cost of each loaf of bread. During a period of falling household incomes, many regular shoppers switch to a rival bakery selling cheaper plastic-wrapped bread. What does this illustrate?","options":{"A":"Consumers may say they care about the environment, but many are unwilling to pay higher prices when budgets are tight","B":"Compostable packaging is illegal in most food retail markets","C":"Lowering prices always causes customers to leave a business","D":"Rival bakeries are not allowed to use plastic packaging"},"correctOption":"A","correctAnswer":"Consumers may say they care about the environment, but many are unwilling to pay higher prices when budgets are tight","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because passing higher green packaging costs onto consumers can backfire if shoppers are price-sensitive and cheaper non-green alternatives exist.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because compostable packaging is legal and widely encouraged.","C":"Incorrect because customers switched *to* the rival because of its lower price.","D":"Incorrect because the rival bakery is clearly still legally selling plastic-wrapped bread."}}},{"id":"P1_U6_MCQ_195","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_195","question":"A supermarket chain installs GPS route-optimisation software across its fleet of 400 delivery trucks to avoid traffic jams and minimise empty return journeys. How does this benefit the supermarket?","options":{"A":"It cuts diesel fuel expenditure while simultaneously reducing carbon dioxide emissions","B":"It increases vehicle maintenance costs and delivery delays","C":"It eliminates the need to hire any truck drivers","D":"It doubles the amount of food wasted in transit"},"correctOption":"A","correctAnswer":"It cuts diesel fuel expenditure while simultaneously reducing carbon dioxide emissions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shorter, more efficient delivery routes reduce fuel bills (boosting profit) and lower exhaust emissions (helping the environment).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fewer kilometres driven reduces wear-and-tear maintenance and avoids delays.","C":"Incorrect because GPS route software assists drivers rather than replacing them.","D":"Incorrect because faster, direct deliveries keep perishable food fresher and reduce waste."}}},{"id":"P1_U6_MCQ_196","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_196","question":"A toothpaste manufacturer stops putting its plastic toothpaste tubes inside outer cardboard boxes, selling the tubes directly on shop shelves. Why is this packaging change both environmentally friendly and profitable?","options":{"A":"It eliminates unnecessary cardboard waste and saves millions of dollars in packaging and transport costs","B":"It makes the toothpaste tubes heavier so fewer fit onto each delivery pallet","C":"It forces consumers to buy twice as much toothpaste","D":"It increases the factory's landfill disposal fees"},"correctOption":"A","correctAnswer":"It eliminates unnecessary cardboard waste and saves millions of dollars in packaging and transport costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because removing redundant outer packaging saves trees and energy while cutting material purchasing and shipping costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because removing boxes makes products lighter and more compact, fitting *more* units per pallet.","C":"Incorrect because packaging removal does not change how quickly consumers use toothpaste.","D":"Incorrect because eliminating cardboard boxes reduces waste disposal costs."}}},{"id":"P1_U6_MCQ_197","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_197","question":"A chemical plating factory illegally dumps toxic heavy metals into a storm drain at night to save $10,000 in hazardous waste treatment fees, and is caught by environmental inspectors. What are the likely consequences?","options":{"A":"Heavy statutory fines, clean-up orders, potential closure of the plant, and severe reputational ruin","B":"A government innovation award for cutting operating expenses","C":"Higher share prices due to improved short-term cash flow","D":"Exemption from future environmental inspections"},"correctOption":"A","correctAnswer":"Heavy statutory fines, clean-up orders, potential closure of the plant, and severe reputational ruin","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because breaking environmental laws leads to severe legal penalties, mandatory remediation costs, criminal liability, and loss of customers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because illegal dumping is prosecuted, not rewarded.","C":"Incorrect because fines, clean-up liabilities, and scandal cause share prices to fall.","D":"Incorrect because offenders face much stricter and more frequent regulatory monitoring."}}},{"id":"P1_U6_MCQ_198","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_198","question":"A packaging printer obtains ISO 14001 environmental management certification and Forest Stewardship Council (FSC) accreditation. How does this help the printer win contracts with major international supermarket chains?","options":{"A":"Large retailers increasingly require their suppliers to prove strict environmental standards to protect their own brand image","B":"Certified printers are allowed to charge 500% more than market prices automatically","C":"ISO certification exempts the printer from paying employee wages","D":"Supermarkets are legally barred from buying from non-certified printers in every country"},"correctOption":"A","correctAnswer":"Large retailers increasingly require their suppliers to prove strict environmental standards to protect their own brand image","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because major consumer brands audit their supply chains and prefer accredited eco-friendly suppliers to meet their own sustainability targets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suppliers must still offer competitive prices alongside environmental credentials.","C":"Incorrect because environmental certifications have no impact on wage obligations.","D":"Incorrect because certification is usually a commercial requirement set by retailers rather than a universal law."}}},{"id":"P1_U6_MCQ_199","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_199","question":"Severe droughts and floods linked to climate change destroy 40% of a region's coffee harvest. How does this environmental disruption affect an international coffee-shop chain?","options":{"A":"Wholesale coffee bean prices surge, increasing variable costs and squeezing profit margins","B":"Coffee beans become much cheaper due to excess global supply","C":"Customers stop drinking coffee permanently","D":"The coffee chain's store rents drop automatically"},"correctOption":"A","correctAnswer":"Wholesale coffee bean prices surge, increasing variable costs and squeezing profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because climate-driven crop failures reduce raw material supply, driving up commodity prices and production costs for food and drink firms.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because destroying 40% of the harvest creates a shortage, raising rather than lowering prices.","C":"Incorrect because consumer demand for coffee remains strong despite supply shocks.","D":"Incorrect because commercial store rents are unaffected by agricultural harvests."}}},{"id":"P1_U6_MCQ_200","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_200","question":"When evaluating whether a manufacturing business should invest in environmentally friendly processes, which statement provides the most balanced conclusion?","options":{"A":"Although green investments raise short-term costs, they often lower long-term energy/waste bills, avoid legal fines, and boost brand loyalty","B":"Becoming environmentally friendly always guarantees immediate profit increases in the first week","C":"Businesses should ignore the environment completely because consumers never care about pollution","D":"Environmental laws only apply to public sector hospitals and schools, never private businesses"},"correctOption":"A","correctAnswer":"Although green investments raise short-term costs, they often lower long-term energy/waste bills, avoid legal fines, and boost brand loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a balanced evaluation weighs higher initial capital/material costs against long-term cost efficiencies, legal compliance, and stronger reputation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because green investments usually require upfront spending before generating long-term returns.","C":"Incorrect because ignoring environmental impacts risks fines, boycotts, and lost sales.","D":"Incorrect because environmental legislation heavily regulates private sector factories and firms."}}},{"id":"P1_U6_MCQ_201","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_201","question":"A profitable multinational tech firm uses complex legal accounting loopholes to shift its profits to a zero-tax island, paying almost no corporation tax in the countries where it makes billions in sales. How is this practice viewed?","options":{"A":"It may be strictly legal, but it is widely criticised as unethical because it deprives host societies of public service funding","B":"It is illegal in every country and automatically results in immediate imprisonment of all shareholders","C":"It is considered highly ethical because it reduces government spending on schools and hospitals","D":"It is a form of Fairtrade certification"},"correctOption":"A","correctAnswer":"It may be strictly legal, but it is widely criticised as unethical because it deprives host societies of public service funding","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because aggressive tax avoidance exploits legal loopholes without breaking the law, yet raises major ethical concerns about fairness to society.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because legal tax avoidance uses permitted loopholes (unlike illegal tax evasion) and shareholders have limited liability.","C":"Incorrect because starving public services of fair tax contributions is widely viewed as socially irresponsible.","D":"Incorrect because Fairtrade concerns fair prices for farmers, not corporate tax structuring."}}},{"id":"P1_U6_MCQ_202","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_202","question":"An investment bank conducts an independent pay audit and immediately increases salaries for female and minority managers so that all staff doing equal work receive identical pay. Which area of business ethics does this demonstrate?","options":{"A":"Fairness, equality, and non-discrimination in human resource management","B":"Predatory pricing against smaller banks","C":"Environmental waste reduction","D":"Import tariff avoidance"},"correctOption":"A","correctAnswer":"Fairness, equality, and non-discrimination in human resource management","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ensuring equal pay and fair career opportunities for all employees regardless of gender or background is a core ethical HR principle.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internal pay audits relate to employee fairness, not pricing strategy.","C":"Incorrect because pay equality addresses social fairness rather than environmental waste.","D":"Incorrect because staff pay reviews are unrelated to customs duties."}}},{"id":"P1_U6_MCQ_203","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_203","question":"In a country where building regulations do not require safety harnesses for scaffolding workers, a construction firm still provides top-grade harnesses, helmets, and daily safety briefings for every worker. Why is this an ethical decision?","options":{"A":"The firm prioritises workers' lives and wellbeing above saving money on safety equipment","B":"Safety harnesses increase the speed at which workers lay bricks by 50%","C":"The firm is trying to avoid paying workers their hourly wages","D":"The government fines companies that do not buy imported harnesses"},"correctOption":"A","correctAnswer":"The firm prioritises workers' lives and wellbeing above saving money on safety equipment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because voluntarily investing in worker safety beyond weak legal requirements demonstrates moral responsibility toward employees.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because safety equipment protects lives rather than speeding up bricklaying.","C":"Incorrect because providing safety gear does not replace paying wages.","D":"Incorrect because the scenario states local regulations do not require harnesses."}}},{"id":"P1_U6_MCQ_204","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_204","question":"Senior managers at a retail plc deliberately delay recording $20 million of supplier invoices until the next financial year so this year's profits look higher and share prices rise. How would you classify this behaviour?","options":{"A":"Both unethical and illegal financial misrepresentation","B":"Ethical corporate social responsibility","C":"Just-in-time inventory management","D":"Fairtrade accounting"},"correctOption":"A","correctAnswer":"Both unethical and illegal financial misrepresentation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because falsifying financial statements misleads shareholders, banks, and tax authorities, violating both moral honesty and company law.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because deceiving investors is the opposite of corporate social responsibility.","C":"Incorrect because JIT is a stock control system, not manipulating accounting records.","D":"Incorrect because 'Fairtrade accounting' is not a valid accounting or ethical concept."}}},{"id":"P1_U6_MCQ_205","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_205","question":"A jewellery maker traces every diamond and gram of gold back to certified mines to ensure none of its materials fund armed conflict or rely on forced labour. Which ethical practice is this?","options":{"A":"Responsible and conflict-free ethical sourcing","B":"Penetration pricing","C":"Horizontal takeover","D":"Autocratic delegation"},"correctOption":"A","correctAnswer":"Responsible and conflict-free ethical sourcing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical sourcing verifies that raw materials are extracted without human rights abuses or funding violence.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because penetration pricing is setting a low initial price to gain market share.","C":"Incorrect because horizontal takeover means buying a competitor in the same industry.","D":"Incorrect because autocratic leadership is a management style, not a supply chain practice."}}},{"id":"P1_U6_MCQ_206","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_206","question":"A budget airline advertises $29 flights, but adds unavoidable $45 'booking fees' and $30 'airport check-in charges' only on the final payment screen. Why is this 'drip pricing' considered unethical marketing?","options":{"A":"It deceives consumers about the true total price and exploits their time invested in booking","B":"It makes flights too cheap for the airline to pay for aviation fuel","C":"It forces passengers to buy shares in the airline","D":"It reduces the airline's sales revenue on every ticket"},"correctOption":"A","correctAnswer":"It deceives consumers about the true total price and exploits their time invested in booking","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because hiding mandatory charges until checkout misleads customers and undermines honest, transparent pricing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the hidden fees actually raise the final price far above $29.","C":"Incorrect because hidden booking fees do not involve purchasing company shares.","D":"Incorrect because drip pricing increases revenue per ticket at the expense of customer trust."}}},{"id":"P1_U6_MCQ_207","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_207","question":"A vitamin company refuses to run adverts claiming its herbal pills 'cure memory loss' because clinical studies show no proven effect, even though competitors make similar exaggerated claims. What is the long-term benefit of honest advertising?","options":{"A":"It builds lasting consumer trust and protects the company from regulatory fines and lawsuits","B":"It eliminates the need to manufacture the vitamins safely","C":"It lowers corporation tax rates to 0%","D":"It forces competitors to share their profits"},"correctOption":"A","correctAnswer":"It builds lasting consumer trust and protects the company from regulatory fines and lawsuits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because truthful marketing earns customer credibility and avoids legal penalties under consumer protection laws.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because product safety and quality control remain essential.","C":"Incorrect because honest advertising does not waive corporation tax.","D":"Incorrect because competitors remain independent businesses."}}},{"id":"P1_U6_MCQ_208","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_208","question":"An online furniture retailer offers a clear, no-quibble 30-day return policy and repairs any manufacturing faults free of charge without hiding behind confusing legal small print. How does this ethical customer policy affect the retailer?","options":{"A":"It encourages repeat purchases and positive word-of-mouth recommendations from satisfied shoppers","B":"It causes customers to stop buying furniture online","C":"It increases shipping tariffs on imported timber","D":"It lowers employee motivation in the customer service team"},"correctOption":"A","correctAnswer":"It encourages repeat purchases and positive word-of-mouth recommendations from satisfied shoppers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because treating customers fairly after a sale builds brand loyalty, reduces perceived buying risk, and drives repeat business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because generous, clear return policies reassure online buyers and boost sales.","C":"Incorrect because customer service policies do not affect import tariffs.","D":"Incorrect because empowered customer service staff who can resolve problems fairly experience higher job satisfaction."}}},{"id":"P1_U6_MCQ_209","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_209","question":"A large clothing brand gives its small fabric suppliers six months' advance notice before reducing orders, allowing the suppliers time to find new clients without making sudden layoffs. Which stakeholder group is being treated ethically?","options":{"A":"Suppliers (and indirectly the suppliers' employees)","B":"Commercial bank lenders","C":"Government tax collectors","D":"Competing clothing retailers"},"correctOption":"A","correctAnswer":"Suppliers (and indirectly the suppliers' employees)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because giving fair notice of order changes protects suppliers from sudden financial shock and helps them protect their workers' jobs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this decision manages supplier relationships rather than bank loans.","C":"Incorrect because advance notice of orders is not aimed at tax authorities.","D":"Incorrect because the brand is assisting its own fabric suppliers, not rival retailers."}}},{"id":"P1_U6_MCQ_210","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_210","question":"A pharmaceutical company spends $800 million developing a breakthrough cancer drug. Charging a very high price recovers R&D costs for shareholders, but means patients in low-income countries cannot afford the medicine. What does this illustrate?","options":{"A":"An ethical dilemma between commercial profit incentives and social welfare/access to healthcare","B":"A violation of minimum wage legislation","C":"A simple way to eliminate all research and development expenses","D":"A trade barrier caused by import quotas"},"correctOption":"A","correctAnswer":"An ethical dilemma between commercial profit incentives and social welfare/access to healthcare","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pharmaceutical pricing involves a classic ethical conflict between funding future innovation/shareholder returns and saving lives affordably.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because drug pricing concerns consumer access and R&D recovery, not minimum wage laws.","C":"Incorrect because the $800 million R&D cost has already been spent.","D":"Incorrect because the issue is pricing affordability rather than government import quotas."}}},{"id":"P1_U6_MCQ_211","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_211","question":"A car parts factory plans to introduce robots that will cut unit costs by 20% and keep the firm competitive, but will replace 250 long-serving assembly workers. What is the most ethical way for management to handle this change?","options":{"A":"Consult with workers early, retrain as many as possible for robot maintenance/quality roles, and offer generous redundancy support","B":"Dismiss all 250 workers without notice on Friday afternoon to save redundancy pay","C":"Hide the automation plan from workers until the robots arrive on the factory floor","D":"Cut the remaining workers' wages in half to pay for the robots"},"correctOption":"A","correctAnswer":"Consult with workers early, retrain as many as possible for robot maintenance/quality roles, and offer generous redundancy support","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical employers communicate transparently, invest in retraining staff where possible, and treat displaced workers with dignity and fair support.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because abrupt dismissal without notice is both unethical and usually illegal.","C":"Incorrect because secrecy destroys trust and causes severe industrial unrest.","D":"Incorrect because slashing remaining staff pay breaches contracts and is unfair."}}},{"id":"P1_U6_MCQ_212","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_212","question":"A global hotel chain operates a resort in a country governed by an authoritarian regime with poor human rights. If the hotel chain closes the resort on ethical grounds, 1,200 local staff will fall into poverty. What does this show?","options":{"A":"Ethical decisions in international business are complex and often involve unintended harm to local workers","B":"Closing overseas hotels always increases a company's annual profits","C":"Human rights groups never care about local employment in developing countries","D":"Multinational companies are legally forbidden from operating outside their home country"},"correctOption":"A","correctAnswer":"Ethical decisions in international business are complex and often involve unintended harm to local workers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because withdrawing from a country can create a genuine ethical dilemma: avoiding association with a regime versus depriving innocent local workers of their livelihoods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because closing a profitable resort reduces revenue and incurs write-off costs.","C":"Incorrect because ethical analysts carefully weigh worker livelihoods alongside broader human rights concerns.","D":"Incorrect because MNCs legally operate across dozens of countries worldwide."}}},{"id":"P1_U6_MCQ_213","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_213","question":"A food processor invests heavily in rigorous hygiene testing and voluntarily recalls any batch with even a tiny risk of allergen contamination. How does this ethical stance protect the company financially?","options":{"A":"It prevents severe customer illnesses, costly product liability lawsuits, and permanent brand destruction","B":"It lowers the cost of raw ingredients by 40%","C":"It eliminates the need for business insurance","D":"It allows the company to ignore food labelling laws"},"correctOption":"A","correctAnswer":"It prevents severe customer illnesses, costly product liability lawsuits, and permanent brand destruction","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because proactive safety ethics prevent catastrophic legal claims, regulatory shutdowns, and loss of public trust.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because strict hygiene testing increases, rather than lowers, quality control costs.","C":"Incorrect because food businesses still maintain product liability insurance.","D":"Incorrect because allergen testing supports compliance with food labelling laws rather than ignoring them."}}},{"id":"P1_U6_MCQ_214","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_214","question":"During a global shortage of semiconductor chips, microchip suppliers prioritise deliveries to an electronics firm known for paying invoices early and honouring contracts fairly, rather than a rival that regularly demands late discounts. What benefit of ethical behaviour does this show?","options":{"A":"Treating suppliers ethically builds mutual trust and loyalty, ensuring reliable supply during shortages","B":"Ethical firms receive microchips completely free of charge during shortages","C":"Suppliers are legally prohibited from selling to unethical companies","D":"Paying invoices early increases variable production costs by 50%"},"correctOption":"A","correctAnswer":"Treating suppliers ethically builds mutual trust and loyalty, ensuring reliable supply during shortages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fair, reliable treatment of suppliers turns them into loyal partners who prioritise the business when supplies are tight.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ethical firms still pay market prices for components.","C":"Incorrect because suppliers choose their preferred customers commercially rather than through legal bans.","D":"Incorrect because paying on time does not increase unit component prices by 50%."}}},{"id":"P1_U6_MCQ_215","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_215","question":"An ethical investment bank refuses to lend money to tobacco manufacturers, weapons producers, or coal mining companies. What is a potential commercial disadvantage of applying strict ethical screening?","options":{"A":"It narrows the bank's pool of potential clients and rejects profitable business opportunities","B":"It forces the bank to pay higher interest rates to savers","C":"It makes the bank's employees less motivated","D":"It violates central bank reserve regulations"},"correctOption":"A","correctAnswer":"It narrows the bank's pool of potential clients and rejects profitable business opportunities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because turning away lucrative clients in controversial industries limits revenue growth in the short to medium term.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ethical screening of borrowers does not force higher deposit interest rates.","C":"Incorrect because employees generally feel proud working for an institution with clear moral principles.","D":"Incorrect because banks are free to choose which sectors they lend to within regulatory capital rules."}}},{"id":"P1_U6_MCQ_216","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_216","question":"A global clothing brand sources cotton from farms in India, yarn from mills in Vietnam, and sewing from factories in Bangladesh. Why is ensuring full ethical compliance across its entire supply chain difficult and costly?","options":{"A":"Monitoring hundreds of indirect sub-suppliers across multiple countries requires expensive, continuous independent audits","B":"Cotton farmers are legally barred from speaking to clothing brands","C":"Independent auditors are illegal in developing countries","D":"Supply chain audits automatically double import tariffs"},"correctOption":"A","correctAnswer":"Monitoring hundreds of indirect sub-suppliers across multiple countries requires expensive, continuous independent audits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because complex, multi-tiered global supply chains make it costly and challenging to verify working conditions at every stage of production.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because brands can directly engage with farms and cooperatives.","C":"Incorrect because third-party social audits are legal and widely used globally.","D":"Incorrect because supply chain audits are private quality/ethics checks and do not affect customs tariffs."}}},{"id":"P1_U6_MCQ_217","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_217","question":"Why does having a strong ethical reputation usually boost sales more for a branded coffee chain or fashion retailer than for a company mining unbranded crushed gravel for road building?","options":{"A":"Individual retail consumers buy branded goods visibly and care about brand values, whereas gravel is an anonymous commodity bought mainly on price and proximity","B":"Mining companies are legally prohibited from behaving ethically","C":"Coffee chains never face any competition from rival cafes","D":"Road builders do not use crushed gravel"},"correctOption":"A","correctAnswer":"Individual retail consumers buy branded goods visibly and care about brand values, whereas gravel is an anonymous commodity bought mainly on price and proximity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer-facing lifestyle brands rely heavily on emotional appeal and reputation, whereas bulk raw commodities compete primarily on price and logistics.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mining companies are expected to follow strict safety and environmental ethics.","C":"Incorrect because coffee chains face intense competition, making ethical differentiation valuable.","D":"Incorrect because crushed gravel is an essential input for road construction."}}},{"id":"P1_U6_MCQ_218","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_218","question":"A software company donates 500 refurbished laptops to underfunded local schools and gives every employee three paid days per year to volunteer teaching coding skills. Which concept does this illustrate?","options":{"A":"Corporate Social Responsibility (CSR)","B":"Predatory pricing","C":"Hostile takeover strategy","D":"Diseconomies of scale"},"correctOption":"A","correctAnswer":"Corporate Social Responsibility (CSR)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because CSR involves businesses voluntarily contributing resources and skills to improve the wellbeing of the wider community.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because predatory pricing is setting below-cost prices to destroy competitors.","C":"Incorrect because a takeover involves buying control of another company.","D":"Incorrect because diseconomies of scale refer to rising average costs when a firm grows too large."}}},{"id":"P1_U6_MCQ_219","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_219","question":"Short-term institutional shareholders pressure a clothing plc to cut supplier payments so dividends rise this year, while ethical consumer groups demand higher wages for garment workers. What does this illustrate?","options":{"A":"Conflicting expectations between profit-focused owners and socially concerned external stakeholders","B":"Complete agreement among all stakeholders on every business decision","C":"A fall in fixed factory rent caused by shareholder voting","D":"How higher dividends automatically improve overseas factory safety"},"correctOption":"A","correctAnswer":"Conflicting expectations between profit-focused owners and socially concerned external stakeholders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers often face competing pressures from shareholders seeking higher short-term financial returns and stakeholders demanding ethical treatment of workers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario highlights a direct clash of priorities between stakeholder groups.","C":"Incorrect because shareholder dividend demands do not lower commercial rent.","D":"Incorrect because paying higher dividends reduces cash available for improving supplier wages and safety."}}},{"id":"P1_U6_MCQ_220","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_220","question":"A hotel group chooses to buy all its bed linen from a certified local cooperative paying fair wages rather than from an unverified overseas supplier charging 15% less. What is a secondary benefit of buying from the local supplier?","options":{"A":"Shorter delivery lead times, easier quality inspections, and lower transport emissions","B":"Guaranteed exemption from paying local business taxes","C":"Complete elimination of laundry expenses","D":"Automatic 100% hotel room occupancy year-round"},"correctOption":"A","correctAnswer":"Shorter delivery lead times, easier quality inspections, and lower transport emissions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical local sourcing also brings operational advantages such as faster deliveries, lower carbon footprint, and direct oversight of quality.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because buying locally does not exempt hotels from business taxes.","C":"Incorrect because bed linen still needs regular laundering regardless of where it was bought.","D":"Incorrect because supplier choice supports brand image but cannot guarantee 100% occupancy."}}},{"id":"P1_U6_MCQ_221","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_221","question":"A fitness app collects users' daily heart-rate and location data. Even though its terms and conditions would legally allow selling the data to health insurers, the company refuses to sell any user data. Why is this an ethical decision?","options":{"A":"It respects customer privacy and trust rather than exploiting personal data for extra profit","B":"Selling user data is the only way a fitness app can ever earn revenue","C":"Health insurers are legally barred from using computers","D":"Refusing to sell data increases the app's server electricity costs by 90%"},"correctOption":"A","correctAnswer":"It respects customer privacy and trust rather than exploiting personal data for extra profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because protecting customer data privacy beyond bare legal minimums builds user trust and upholds moral integrity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fitness apps earn revenue through subscriptions or legitimate in-app features.","C":"Incorrect because insurers use digital systems; the issue is customer data privacy.","D":"Incorrect because not selling data does not increase server electricity consumption."}}},{"id":"P1_U6_MCQ_222","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_222","question":"Instead of gluing batteries inside its smartphones so customers must buy a new phone every two years, a manufacturer designs modular phones with easily replaceable batteries and seven years of software updates. Which unethical practice is this firm rejecting?","options":{"A":"Planned obsolescence","B":"Fairtrade sourcing","C":"Cost-plus pricing","D":"Internal recruitment"},"correctOption":"A","correctAnswer":"Planned obsolescence","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because planned obsolescence is intentionally designing products to wear out or become outdated quickly to force repeat purchases, which harms consumers and the environment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Fairtrade ensures fair prices for commodity producers.","C":"Incorrect because cost-plus pricing is adding a profit markup to unit costs.","D":"Incorrect because internal recruitment is filling job vacancies from within the existing workforce."}}},{"id":"P1_U6_MCQ_223","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_223","question":"At a retail bank, branch managers are told they will be fired unless they hit extreme sales targets, leading staff to secretly open unauthorised accounts for customers. What does this scandal reveal about business ethics?","options":{"A":"Unrealistic profit/sales targets set by senior leaders can pressure employees into unethical behaviour","B":"Bank employees never care about keeping their jobs","C":"Opening unauthorised customer accounts is good customer service","D":"Ethical codes of conduct work automatically even when targets reward dishonesty"},"correctOption":"A","correctAnswer":"Unrealistic profit/sales targets set by senior leaders can pressure employees into unethical behaviour","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because organisational culture and reward systems strongly influence behaviour; extreme targets without ethical safeguards encourage misconduct.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fear of losing their jobs was the exact reason staff felt pressured to cheat.","C":"Incorrect because opening fake or unauthorised accounts is fraudulent and harms customers.","D":"Incorrect because written ethical rules fail if management rewards unethical shortcuts."}}},{"id":"P1_U6_MCQ_224","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_224","question":"A supermarket chain ensures it pays its full corporation tax in every country where it operates, refuses to use aggressive tax havens, and publishes a clear country-by-country tax report. Which stakeholder group benefits directly from this ethical tax policy?","options":{"A":"The government and local citizens who rely on tax revenues to fund public infrastructure and healthcare","B":"Overseas tax-haven accounting firms","C":"Competing supermarkets that avoid paying taxes","D":"Foreign import tariff collectors"},"correctOption":"A","correctAnswer":"The government and local citizens who rely on tax revenues to fund public infrastructure and healthcare","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because paying fair corporate taxes funds public goods (roads, schools, hospitals) that support both society and business operations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because refusing to use tax havens reduces business for tax-avoidance consultants.","C":"Incorrect because rival firms do not receive the taxes paid to the government.","D":"Incorrect because corporation tax is paid to domestic revenue authorities, not foreign customs."}}},{"id":"P1_U6_MCQ_225","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_225","question":"When a respected outdoor clothing company with a 30-year record of ethical behaviour accidentally ships a batch of jackets with faulty zippers, customers patiently accept replacements without abandoning the brand. Why does this happen?","options":{"A":"Long-term ethical behaviour builds deep brand trust and goodwill that protects the firm during occasional mistakes","B":"Customers are legally prohibited from returning faulty jackets to ethical brands","C":"Faulty zippers increase the resale value of outdoor jackets","D":"No other companies manufacture outdoor jackets"},"correctOption":"A","correctAnswer":"Long-term ethical behaviour builds deep brand trust and goodwill that protects the firm during occasional mistakes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consistent integrity builds reputational goodwill, making customers far more forgiving when an honest operational mistake occurs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumer protection laws always entitle buyers to a refund or replacement for faulty goods.","C":"Incorrect because manufacturing defects reduce product value.","D":"Incorrect because the outdoor clothing market is highly competitive."}}},{"id":"P1_U6_MCQ_226","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_226","question":"Which of the following organisations is the best example of a pressure group?","options":{"A":"An independent environmental campaign charity fighting to stop ocean plastic pollution","B":"A public limited supermarket chain selling organic vegetables","C":"The government's Ministry of Finance setting annual income tax rates","D":"A central bank controlling national interest rates"},"correctOption":"A","correctAnswer":"An independent environmental campaign charity fighting to stop ocean plastic pollution","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an environmental campaign charity is a non-governmental group formed by people with a shared cause to influence businesses and governments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a supermarket plc is a profit-making private sector business.","C":"Incorrect because a government ministry is part of the state, not an external pressure group.","D":"Incorrect because a central bank is a public monetary authority."}}},{"id":"P1_U6_MCQ_227","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_227","question":"Activists from a forest conservation pressure group hang a giant protest banner across the entrance of a major paper manufacturer's headquarters just as television cameras arrive. What is the purpose of this direct action?","options":{"A":"To attract immediate media coverage and embarrass the company into adopting sustainable forestry practices","B":"To purchase a controlling 51% share stake in the paper company","C":"To help the paper company advertise its new office stationery range","D":"To lower the paper company's electricity bills"},"correctOption":"A","correctAnswer":"To attract immediate media coverage and embarrass the company into adopting sustainable forestry practices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dramatic, visual protests generate news headlines that damage a company's public image and pressure executives to respond.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hanging a banner is a publicity protest, not a financial share purchase.","C":"Incorrect because the protest generates negative publicity rather than promoting the company's products.","D":"Incorrect because protests do not reduce utility costs."}}},{"id":"P1_U6_MCQ_228","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_228","question":"A consumer and environmental watchdog publishes an annual 'Supermarket Sustainability Scorecard' ranking the ten largest grocery chains from best to worst on plastic waste and fair farmer pay. How does this tactic influence supermarkets?","options":{"A":"Supermarkets near the bottom improve their practices to avoid bad publicity and losing ethical shoppers to higher-ranked rivals","B":"Supermarkets at the bottom are automatically nationalised by the government","C":"Supermarkets at the top are fined for scoring too highly","D":"The scorecard has no effect because shoppers never read news reports"},"correctOption":"A","correctAnswer":"Supermarkets near the bottom improve their practices to avoid bad publicity and losing ethical shoppers to higher-ranked rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public league tables create reputational competition, motivating lower-ranked brands to improve so they do not lose market share.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pressure group scorecards carry reputational weight, not automatic nationalisation.","C":"Incorrect because top-ranked supermarkets gain positive publicity rather than fines.","D":"Incorrect because media coverage of consumer rankings strongly influences brand perception."}}},{"id":"P1_U6_MCQ_229","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_229","question":"An animal rights pressure group organises 80,000 supporters to send emails and social media messages to a fast-food chain demanding cage-free eggs. Why might the fast-food chain agree to this demand?","options":{"A":"The high volume of messages signals strong consumer feeling and warns of a potential boycott if the firm ignores it","B":"Receiving 80,000 emails legally obliges a company to change its menu within 24 hours","C":"Cage-free eggs are always 80% cheaper than standard eggs","D":"The pressure group offers to pay the fast-food chain's corporation tax"},"correctOption":"A","correctAnswer":"The high volume of messages signals strong consumer feeling and warns of a potential boycott if the firm ignores it","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because coordinated supporter campaigns demonstrate organised public pressure and alert managers to reputational and sales risks.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because email campaigns exert commercial and moral pressure, not legal compulsion.","C":"Incorrect because higher animal-welfare standards usually cost slightly more rather than 80% less.","D":"Incorrect because pressure groups do not pay corporate taxes for businesses."}}},{"id":"P1_U6_MCQ_230","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_230","question":"A well-funded environmental pressure group takes a water utility company to court for illegally discharging untreated sewage into protected coastal waters. Which method of influence is the group using?","options":{"A":"Legal action to enforce environmental regulations","B":"A consumer boycott of tap water","C":"Workplace strike action by water engineers","D":"Predatory pricing"},"correctOption":"A","correctAnswer":"Legal action to enforce environmental regulations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pressure groups with sufficient funds often use the courts to hold companies accountable for breaking environmental or safety laws.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because households cannot realistically boycott their local monopoly tap-water supplier.","C":"Incorrect because strikes are carried out by employees/unions, not external pressure groups.","D":"Incorrect because predatory pricing is an anti-competitive business pricing tactic."}}},{"id":"P1_U6_MCQ_231","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_231","question":"Why are large, well-funded international pressure groups generally much more successful at changing multinational corporate policies than tiny, unfunded local groups?","options":{"A":"They can afford professional researchers, lawyers, global media campaigns, and sustained lobbying","B":"They are allowed to pass laws directly without Parliament's approval","C":"They own 100% of the shares in all multinational companies","D":"They are exempt from obeying defamation and protest laws"},"correctOption":"A","correctAnswer":"They can afford professional researchers, lawyers, global media campaigns, and sustained lobbying","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because financial resources enable pressure groups to gather credible evidence, run high-impact publicity campaigns, and sustain pressure over time.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because only elected legislatures/governments can pass laws.","C":"Incorrect because pressure groups are independent campaign bodies, not sole owners of MNCs.","D":"Incorrect because pressure groups must still obey national laws when campaigning."}}},{"id":"P1_U6_MCQ_232","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_232","question":"Several world-famous musicians and actors publicly endorse a pressure group's campaign against a clothing brand's use of real animal fur. How does celebrity endorsement affect the pressure group's influence?","options":{"A":"It massively increases media coverage and public awareness, putting far greater pressure on the clothing brand","B":"It legally forces the clothing brand to shut down all its factories immediately","C":"It reduces public interest in the pressure group's message","D":"It increases the clothing brand's sales of fur coats"},"correctOption":"A","correctAnswer":"It massively increases media coverage and public awareness, putting far greater pressure on the clothing brand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because celebrity backing attracts mainstream entertainment and news coverage, rapidly spreading the campaign message to millions of consumers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because celebrity endorsements create reputational pressure, not legal closure orders.","C":"Incorrect because high-profile figures amplify public interest rather than reducing it.","D":"Incorrect because negative publicity from celebrities usually causes fur sales to drop sharply."}}},{"id":"P1_U6_MCQ_233","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_233","question":"A human rights pressure group launches a major media exposé on a tech company's factory conditions one week before the company floats its shares on the stock exchange (IPO). Why is this timing particularly effective?","options":{"A":"Negative publicity right before a share issue threatens investor confidence and could lower the share price, pressuring directors to act fast","B":"Stock exchanges are legally closed whenever a pressure group publishes a report","C":"Investors prefer buying shares in companies facing major human rights scandals","D":"The tech company cannot hire any lawyers during an IPO"},"correctOption":"A","correctAnswer":"Negative publicity right before a share issue threatens investor confidence and could lower the share price, pressuring directors to act fast","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because companies are most sensitive to reputational risks during major product launches or stock market flotations when investor trust is critical.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because stock exchanges operate normally during pressure group campaigns.","C":"Incorrect because scandals increase risk and deter institutional and ethical investors.","D":"Incorrect because companies retain legal advisers throughout an IPO."}}},{"id":"P1_U6_MCQ_234","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_234","question":"Members of a protest group vandalise local grocery stores and block ambulances while campaigning against food packaging waste. Why is this tactic likely to fail?","options":{"A":"Violent or disruptive actions that harm ordinary citizens alienate the public and destroy sympathy for the group's cause","B":"Vandalism automatically increases the grocery stores' sales revenue","C":"Governments always reward violent protests by passing immediate laws in their favour","D":"Grocery stores are not allowed to repair damaged windows"},"correctOption":"A","correctAnswer":"Violent or disruptive actions that harm ordinary citizens alienate the public and destroy sympathy for the group's cause","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pressure groups rely on public support; extreme or illegal tactics turn public opinion against the campaigners.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because vandalism disrupts trade and causes repair costs rather than increasing sales.","C":"Incorrect because governments refuse to yield to illegal violence and prosecute offenders.","D":"Incorrect because businesses promptly repair property damage."}}},{"id":"P1_U6_MCQ_235","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_235","question":"An environmental pressure group campaigns to stop a new copper mine, while a local workers' coalition campaigns in favour of the mine because it will create 1,000 well-paid jobs. What does this illustrate?","options":{"A":"Different pressure groups often have conflicting objectives, forcing governments and businesses to weigh competing interests","B":"Environmental groups and workers' groups always agree on every industrial project","C":"Copper mines never create any jobs or environmental impacts","D":"Pressure groups are banned from campaigning on mining projects"},"correctOption":"A","correctAnswer":"Different pressure groups often have conflicting objectives, forcing governments and businesses to weigh competing interests","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because society contains multiple interest groups with competing priorities (e.g., conservation vs local employment), complicating decision-making.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario clearly shows two groups taking opposite sides.","C":"Incorrect because mining projects create both economic employment and environmental disruption.","D":"Incorrect because pressure groups actively campaign on major resource projects."}}},{"id":"P1_U6_MCQ_236","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_236","question":"A specialist manufacturer produces industrial ball bearings sold only to heavy machinery factories and has no consumer-facing brand. Why might this firm be less worried about a pressure group's public media campaign than a soft-drinks brand?","options":{"A":"Its industrial buyers purchase based on technical specifications and price rather than retail public image","B":"Industrial manufacturers are legally exempt from all environmental and safety laws","C":"Soft-drinks brands never spend money on marketing or brand image","D":"Pressure groups are legally forbidden from criticising industrial factories"},"correctOption":"A","correctAnswer":"Its industrial buyers purchase based on technical specifications and price rather than retail public image","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because B2B component suppliers do not rely on mass-market consumer branding, making them less immediately vulnerable to public boycotts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because industrial firms must obey all environmental and workplace laws.","C":"Incorrect because soft-drinks companies invest heavily in brand image, making them very sensitive to bad publicity.","D":"Incorrect because pressure groups can criticise any business, though B2B firms feel less direct retail pressure."}}},{"id":"P1_U6_MCQ_237","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_237","question":"To stop a consumer pressure group from convincing Parliament to pass strict laws on video game advertising, major gaming companies set up their own voluntary Advertising Standards Code. Why do industries create self-regulatory codes?","options":{"A":"To show they can act responsibly on their own and avoid stricter, costlier government legislation","B":"To make video games illegal to sell to adults","C":"To increase the corporation tax rate on gaming companies","D":"To eliminate all video game advertising permanently"},"correctOption":"A","correctAnswer":"To show they can act responsibly on their own and avoid stricter, costlier government legislation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because voluntary industry self-regulation addresses pressure group concerns proactively while giving businesses more flexibility than rigid statutory laws.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because self-regulation aims to keep products marketable responsibly, not ban them.","C":"Incorrect because industry codes do not alter tax rates.","D":"Incorrect because companies want to continue advertising within agreed ethical guidelines."}}},{"id":"P1_U6_MCQ_238","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_238","question":"A global coffee chain invites leaders of environmental and fair-trade pressure groups onto an external advisory panel to review its sustainability plans twice a year. What is the main advantage of this approach?","options":{"A":"The company can identify and solve potential ethical or environmental issues early before public protests erupt","B":"The pressure group leaders take over full legal ownership of the coffee chain","C":"The coffee chain no longer has to pay its coffee suppliers","D":"All rival coffee chains are banned from opening new stores"},"correctOption":"A","correctAnswer":"The company can identify and solve potential ethical or environmental issues early before public protests erupt","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because regular dialogue with pressure groups acts as an early-warning system and builds constructive trust instead of public confrontation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an advisory panel offers advice; shareholders retain ownership.","C":"Incorrect because suppliers must still be paid fair prices.","D":"Incorrect because advisory panels do not restrict market competition."}}},{"id":"P1_U6_MCQ_239","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_239","question":"When environmental pressure groups lobby the government to double taxes on domestic steelmakers, a steel industry association meets with ministers to warn that 15,000 domestic jobs would be lost to foreign imports. What is the steel association doing?","options":{"A":"Counter-lobbying the government to protect its business interests","B":"Organising a consumer boycott of steel bridges","C":"Paying bribes to environmental protesters","D":"Applying for Fairtrade certification"},"correctOption":"A","correctAnswer":"Counter-lobbying the government to protect its business interests","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because business groups and trade associations also lobby politicians to argue against regulations or taxes that threaten competitiveness and employment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the steel association is meeting government ministers, not calling for a consumer boycott.","C":"Incorrect because legal lobbying involves presenting economic arguments to lawmakers, not bribery.","D":"Incorrect because Fairtrade applies to agricultural/craft producers, not heavy steelmakers."}}},{"id":"P1_U6_MCQ_240","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_240","question":"Following intense pressure group scrutiny, a sportswear manufacturer hires 30 full-time compliance officers to inspect its overseas supplier factories and publish annual ethics reports. How does this affect the manufacturer's costs?","options":{"A":"Its administrative and compliance overhead costs increase","B":"Its fixed salary costs drop by 30%","C":"Its raw cotton costs fall to zero","D":"Its bank loan interest rates are cut in half"},"correctOption":"A","correctAnswer":"Its administrative and compliance overhead costs increase","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because responding to pressure group demands through auditing, reporting, and cleaner processes raises administrative and operating expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hiring 30 additional compliance officers increases, rather than reduces, salary expenses.","C":"Incorrect because factory audits do not eliminate raw material costs.","D":"Incorrect because compliance staffing does not halve bank interest rates."}}},{"id":"P1_U6_MCQ_241","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_241","question":"Years of pressure group campaigns highlighting the environmental impact of cattle farming led major food companies to invest millions in developing plant-based burgers. Which positive economic effect of pressure groups does this demonstrate?","options":{"A":"Pressure groups can stimulate product innovation and help create profitable new sustainable markets","B":"Pressure groups always force food companies to stop all research and development","C":"Plant-based burgers are legally required to be given away for free","D":"Cattle farming was banned worldwide by pressure groups"},"correctOption":"A","correctAnswer":"Pressure groups can stimulate product innovation and help create profitable new sustainable markets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because highlighting social and environmental concerns shifts consumer preferences, driving businesses to innovate and develop new green products.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pressure group campaigns encouraged *more* R&D into plant-based alternatives.","C":"Incorrect because food companies sell plant-based burgers commercially at a profit.","D":"Incorrect because pressure groups shifted market demand rather than banning cattle farming."}}},{"id":"P1_U6_MCQ_242","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_242","question":"A student environmental pressure group stages protests at university career fairs whenever a controversial oil and gas company sets up a recruitment stand. How does this affect the company's human resource management?","options":{"A":"It damages the company's employer brand and makes it harder to recruit talented graduates","B":"It allows the company to pay graduates below the legal minimum wage","C":"It eliminates the need to conduct job interviews","D":"It forces universities to ban all engineering degrees"},"correctOption":"A","correctAnswer":"It damages the company's employer brand and makes it harder to recruit talented graduates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because younger job seekers increasingly value ethical and environmental credentials; campus protests deter graduates from applying.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because minimum wage laws still apply regardless of recruitment challenges.","C":"Incorrect because recruitment selection processes are still required.","D":"Incorrect because universities continue offering engineering degrees."}}},{"id":"P1_U6_MCQ_243","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_243","question":"After a pressure group publishes satellite photos linking a palm oil plantation to illegal rainforest burning, three major global biscuit makers immediately cancel their contracts with that plantation. What does this show?","options":{"A":"Pressure groups can indirectly force raw material suppliers to change by persuading major retail brands to drop unethical suppliers","B":"Biscuit makers no longer use any vegetable oils in baking","C":"Satellite photos are illegal to use in environmental research","D":"The plantation will earn higher profits after losing its three largest buyers"},"correctOption":"A","correctAnswer":"Pressure groups can indirectly force raw material suppliers to change by persuading major retail brands to drop unethical suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because targeting famous consumer brands causes those brands to enforce strict ethical standards down their supply chains.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because biscuit makers switch to certified sustainable oil suppliers rather than stopping baking.","C":"Incorrect because environmental watchdogs legally use satellite monitoring to track deforestation.","D":"Incorrect because losing three major customers severely harms the plantation's revenue and profits."}}},{"id":"P1_U6_MCQ_244","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_244","question":"Residents in a quiet village form a local action group to oppose a logistics firm's plan to build a 24-hour distribution hub on nearby farmland, citing noise and lorry traffic. How does this local pressure group differ from a global NGO like Greenpeace?","options":{"A":"It focuses narrowly on protecting a specific local community from a single project rather than campaigning on global issues","B":"It is a profit-seeking public limited company listed on the stock exchange","C":"It has the legal power to arrest lorry drivers","D":"It seeks to win national elections and form the central government"},"correctOption":"A","correctAnswer":"It focuses narrowly on protecting a specific local community from a single project rather than campaigning on global issues","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because local community pressure groups form around a specific local planning or environmental issue, whereas international NGOs campaign broadly across countries.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because community pressure groups are non-profit resident organisations, not plcs.","C":"Incorrect because only the police have legal powers of arrest.","D":"Incorrect because forming a national government is the goal of a political party."}}},{"id":"P1_U6_MCQ_245","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_245","question":"Following years of lobbying by health and consumer pressure groups, a government passes a law requiring all packaged foods to display clear 'traffic-light' nutritional labels showing sugar, salt, and fat levels. How does this affect food manufacturers?","options":{"A":"They incur packaging redesign costs and face pressure to reformulate unhealthy recipes to avoid 'red' warning labels","B":"They are banned from selling any packaged foods in supermarkets","C":"Their corporation tax rate drops automatically when they use red labels","D":"They no longer need to list ingredients on food packets"},"correctOption":"A","correctAnswer":"They incur packaging redesign costs and face pressure to reformulate unhealthy recipes to avoid 'red' warning labels","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mandatory nutritional labelling increases compliance/printing costs and encourages healthier recipes so shoppers are not deterred by red warning indicators.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because foods can still be sold legally as long as they display the required nutritional labels.","C":"Incorrect because nutritional labels do not reduce corporation tax rates.","D":"Incorrect because ingredient lists remain a mandatory legal requirement."}}},{"id":"P1_U6_MCQ_246","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_246","question":"How does a pressure group differ from a trade association (such as the National Federation of Retailers)?","options":{"A":"A trade association represents and lobbies for businesses within an industry, whereas a pressure group campaigns on social, ethical, or environmental causes","B":"A trade association is always a charity, whereas a pressure group is always a sole trader","C":"Trade associations are illegal in democratic economies, whereas pressure groups are state-owned","D":"Pressure groups aim to increase business profits, whereas trade associations call for consumer boycotts"},"correctOption":"A","correctAnswer":"A trade association represents and lobbies for businesses within an industry, whereas a pressure group campaigns on social, ethical, or environmental causes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade associations promote the commercial interests of member businesses, whereas pressure groups seek to influence business and government behavior on broader public issues.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade associations are funded by member businesses, and pressure groups are non-profit campaign groups, not sole traders.","C":"Incorrect because both trade associations and peaceful pressure groups operate legally in democratic economies.","D":"Incorrect because this reverses their roles."}}},{"id":"P1_U6_MCQ_247","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_247","question":"When an environmental pressure group exposes excessive plastic waste by the three largest multinational bottled-water companies, how can a small, independent company selling water in infinitely recyclable aluminium cans benefit?","options":{"A":"Eco-conscious consumers boycotting the big brands switch to the small company's aluminium-canned water, boosting its sales","B":"The small company is automatically fined for the big companies' plastic waste","C":"Aluminium cans become illegal to manufacture","D":"The small company must lower its prices to zero"},"correctOption":"A","correctAnswer":"Eco-conscious consumers boycotting the big brands switch to the small company's aluminium-canned water, boosting its sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pressure group campaigns against large polluters raise consumer awareness and drive shoppers toward smaller, genuinely sustainable niche competitors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fines apply only to offending companies, not sustainable competitors.","C":"Incorrect because recyclable aluminium cans are encouraged rather than banned.","D":"Incorrect because rising green demand often allows sustainable niche brands to charge a healthy margin."}}},{"id":"P1_U6_MCQ_248","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_248","question":"After a pressure group criticises a fast-food chain for deforestation in its beef supply chain, the chain's Chief Executive publicly insults the protesters as 'ignorant extremists' without addressing the deforestation evidence. Why is this a poor PR response?","options":{"A":"Attacking protesters aggressively generates even more negative media coverage and makes the company look arrogant and guilty","B":"Insulting protesters automatically lowers the price of wholesale beef","C":"It forces the pressure group to delete all its social media accounts","D":"It exempts the fast-food chain from paying Value Added Tax"},"correctOption":"A","correctAnswer":"Attacking protesters aggressively generates even more negative media coverage and makes the company look arrogant and guilty","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because hostile public reactions escalate media scandals ('Streisand effect') and alienate ordinary consumers who expect transparency and accountability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because public relations blunders do not lower raw material costs.","C":"Incorrect because aggressive corporate remarks usually energise pressure groups and attract more supporters.","D":"Incorrect because PR statements have no effect on tax obligations."}}},{"id":"P1_U6_MCQ_249","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_249","question":"A proposal to build a third runway at a major international airport is supported by airlines and construction unions, opposed by local noise-abatement pressure groups, and evaluated by the government. What does this situation demonstrate?","options":{"A":"Major business expansions affect multiple external stakeholders and pressure groups, requiring governments to balance economic growth against environmental and community costs","B":"Airports have zero external costs on surrounding neighbourhoods","C":"Pressure groups always have the final legal vote on airport construction","D":"Airlines never benefit from increased runway capacity"},"correctOption":"A","correctAnswer":"Major business expansions affect multiple external stakeholders and pressure groups, requiring governments to balance economic growth against environmental and community costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large infrastructure decisions involve competing economic benefits (jobs, trade) and external costs (noise, emissions), with pressure groups voicing community/environmental concerns.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because aircraft noise and air pollution are major external costs for local residents.","C":"Incorrect because pressure groups lobby and campaign, while elected governments make the final planning decision.","D":"Incorrect because extra runway capacity allows airlines to operate more flights and grow revenue."}}},{"id":"P1_U6_MCQ_250","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_250","question":"Overall, what is the primary role of pressure groups in relation to private sector business activity in a mixed economy?","options":{"A":"To act as an external check on corporate power by representing social, consumer, and environmental interests that might otherwise be ignored in the pursuit of profit","B":"To manage the daily operations and payroll of public limited companies","C":"To set official central bank interest rates and exchange rates","D":"To eliminate all consumer choice so every household buys identical products"},"correctOption":"A","correctAnswer":"To act as an external check on corporate power by representing social, consumer, and environmental interests that might otherwise be ignored in the pursuit of profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pressure groups give citizens a collective voice to hold businesses and governments accountable for ethical, social, and environmental impacts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because company managers and directors run daily business operations.","C":"Incorrect because central banks manage interest rates and monetary policy.","D":"Incorrect because pressure groups encourage ethical and sustainable product choices rather than eliminating choice."}}},{"id":"P1_U6_MCQ_251","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_251","question":"After eighteen months of falling GDP, retail sales and business investment begin to rise again, and unemployment starts to fall slowly. Which strategic action should a car components manufacturer take as the economy moves from recession into the growth stage?","options":{"A":"Close half of its assembly plants permanently to reduce fixed overheads","B":"Gradually increase raw material orders and begin recruiting and training production staff","C":"Sell off all its core manufacturing machinery at scrap value","D":"Raise selling prices by 40% immediately while spare capacity is still high"},"correctOption":"B","correctAnswer":"Gradually increase raw material orders and begin recruiting and training production staff","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because early signs of economic recovery require businesses to prepare inventory and workforce capacity to meet rising future orders.","distractor_reasons":{"A":"Incorrect because closing factories permanently during recovery would leave the firm unable to meet growing demand.","B":"Correct selection.","C":"Incorrect because selling essential machinery prevents the firm from expanding output as the economy grows.","D":"Incorrect because sharp price hikes during early recovery when spare capacity still exists would lose orders to competitors."}}},{"id":"P1_U6_MCQ_252","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_252","question":"During an economic boom, household disposable incomes rise rapidly across Country A. Which type of business is likely to experience the largest percentage increase in sales revenue during this stage?","options":{"A":"A producer of basic table salt and plain flour","B":"A funeral directors' service","C":"A luxury yacht builder and overseas holiday operator","D":"A municipal tap-water utility company"},"correctOption":"C","correctAnswer":"A luxury yacht builder and overseas holiday operator","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because luxury goods and foreign holidays are highly sensitive to rising incomes, experiencing huge surges in demand during a boom.","distractor_reasons":{"A":"Incorrect because basic food staples have steady demand regardless of whether incomes rise or fall.","B":"Incorrect because demand for funeral services is unaffected by economic booms.","C":"Correct selection.","D":"Incorrect because household water consumption remains relatively stable across the business cycle."}}},{"id":"P1_U6_MCQ_253","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_253","question":"Why are businesses with very high levels of debt (high gearing) most likely to go bankrupt during a prolonged economic slump?","options":{"A":"Corporation tax rates double automatically for indebted companies during a slump","B":"Employees are legally prohibited from working for indebted companies in a slump","C":"Suppliers must give indebted firms free raw materials during a slump","D":"Falling sales reduce cash inflows, making it impossible to pay fixed loan interest and repayments"},"correctOption":"D","correctAnswer":"Falling sales reduce cash inflows, making it impossible to pay fixed loan interest and repayments","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because debt interest and loan repayments are fixed financial obligations that must still be paid even when revenue collapses in a slump.","distractor_reasons":{"A":"Incorrect because corporation tax is paid only on profits, not doubled on indebted firms.","B":"Incorrect because no law bars employees from working for indebted businesses.","C":"Incorrect because suppliers tighten credit terms rather than giving free goods during a slump.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_254","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_254","question":"A sharp global rise in crude oil and natural gas prices drives up electricity, plastics, and transport costs across Country B, causing general inflation to rise to 9%. How does this cost-push inflation affect a domestic ceramics manufacturer?","options":{"A":"Its kiln energy and shipping costs rise sharply, squeezing profit margins","B":"Its overseas export competitiveness improves automatically","C":"Its customers gain higher real disposable incomes","D":"Its variable production costs fall by 9%"},"correctOption":"A","correctAnswer":"Its kiln energy and shipping costs rise sharply, squeezing profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising energy and transport costs directly increase unit production expenses, reducing profit margins if prices cannot be raised.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher domestic costs and inflation make exports dearer and less competitive abroad.","C":"Incorrect because rapid inflation erodes consumers' real purchasing power.","D":"Incorrect because higher energy and material prices increase, rather than decrease, variable costs."}}},{"id":"P1_U6_MCQ_255","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_255","question":"When inflation stays above 10% for two consecutive years, workers repeatedly demand large annual pay rises to maintain their living standards. What problem does this create for businesses?","options":{"A":"Lower recruitment costs due to high unemployment","B":"A wage-price spiral that keeps business labour costs and selling prices rising continuously","C":"A fall in the nominal value of inventory held in warehouses","D":"Lower interest rates on variable-rate business overdrafts"},"correctOption":"B","correctAnswer":"A wage-price spiral that keeps business labour costs and selling prices rising continuously","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher wage settlements increase business costs, forcing firms to raise prices further and creating ongoing inflationary instability.","distractor_reasons":{"A":"Incorrect because high inflation is often accompanied by tight labour markets rather than cheap recruitment.","B":"Correct selection.","C":"Incorrect because inflation increases, rather than reduces, the nominal monetary value of physical stock.","D":"Incorrect because central banks raise interest rates to combat persistent high inflation."}}},{"id":"P1_U6_MCQ_256","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_256","question":"Annual inflation in Country X is 8%, while inflation in its main trading partners is only 1.5%. Assuming exchange rates stay constant, how will this affect businesses in Country X?","options":{"A":"Exporters in Country X will lose overseas sales as their prices rise much faster than foreign rivals' prices","B":"Imported foreign goods will become much more expensive than domestic goods","C":"Country X's balance of payments will move into a large trade surplus","D":"Domestic firms will no longer face any competition from imports"},"correctOption":"A","correctAnswer":"Exporters in Country X will lose overseas sales as their prices rise much faster than foreign rivals' prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher domestic inflation makes Country X's goods relatively dearer than foreign goods, hurting exports and encouraging cheaper imports.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because foreign goods with 1.5% inflation become relatively cheaper than domestic goods with 8% inflation.","C":"Incorrect because falling exports and rising imports worsen the balance of payments into a deficit.","D":"Incorrect because relatively cheaper foreign products increase import competition."}}},{"id":"P1_U6_MCQ_257","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_257","question":"Automated self-checkout machines and online banking cause unemployment among former retail cashiers and bank tellers, even while technology firms struggle to hire software engineers. Why is this a problem for growing tech businesses?","options":{"A":"Unemployed retail cashiers cannot immediately fill specialised engineering vacancies without extensive retraining","B":"High overall unemployment forces software engineers to accept minimum wage","C":"Technology firms are legally required to hire only former bank tellers","D":"Automation eliminates all need for software engineers"},"correctOption":"A","correctAnswer":"Unemployed retail cashiers cannot immediately fill specialised engineering vacancies without extensive retraining","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because structural/technological unemployment creates a skills mismatch: abundant unskilled applicants cannot fill technical skill shortages.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because scarce software engineers still command high salaries despite unemployment in other sectors.","C":"Incorrect because private firms are free to recruit candidates with relevant qualifications.","D":"Incorrect because automation increases demand for software engineers to build and maintain systems."}}},{"id":"P1_U6_MCQ_258","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_258","question":"Country Y's Gross Domestic Product (GDP) increases from $400 billion in Year 1 to $420 billion in Year 2. What is the annual rate of economic growth, and how does it generally affect business confidence?","options":{"A":"20% growth, which lowers business confidence","B":"5% growth, which boosts business confidence and encourages capital investment","C":"2% growth, which forces firms to cut production","D":"5% recession, which increases redundancies"},"correctOption":"B","correctAnswer":"5% growth, which boosts business confidence and encourages capital investment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ($20bn ÷ $400bn) × 100 = 5% GDP growth, signalling rising demand and encouraging firms to invest and expand.","distractor_reasons":{"A":"Incorrect because $20bn is 5% of $400bn, not 20%, and growth boosts confidence.","B":"Correct selection.","C":"Incorrect because the percentage increase is 5%, not 2%.","D":"Incorrect because rising GDP represents economic growth, not a recession."}}},{"id":"P1_U6_MCQ_259","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_259","question":"Why does a government aim to avoid a large, persistent deficit on the current account of its balance of payments?","options":{"A":"Because a deficit means the country is spending more on foreign imports than it earns from exports, risking currency weakness and domestic job losses","B":"Because a deficit means domestic exporters are selling too many goods abroad","C":"Because a deficit automatically forces all domestic businesses to close","D":"Because a deficit reduces government tax revenue to zero"},"correctOption":"A","correctAnswer":"Because a deficit means the country is spending more on foreign imports than it earns from exports, risking currency weakness and domestic job losses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a current account deficit indicates high import leakage and weak export competitiveness, which can weaken the currency and harm domestic output.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because high export earnings create a surplus, not a deficit.","C":"Incorrect because a trade deficit creates competitive pressure but does not close all domestic businesses.","D":"Incorrect because governments still collect domestic income, sales, and corporate taxes."}}},{"id":"P1_U6_MCQ_260","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_260","question":"A government introduces a new top personal income tax bracket of 50% on annual earnings above $200,000, while leaving tax rates for middle- and low-income earners unchanged. Which business will be most negatively affected?","options":{"A":"A discount supermarket selling staple groceries","B":"A public bus operator serving low-income commuters","C":"A dealership selling bespoke luxury sports cars and private yachts","D":"A manufacturer of standard school exercise books"},"correctOption":"C","correctAnswer":"A dealership selling bespoke luxury sports cars and private yachts","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because raising income tax specifically on high earners reduces the disposable income of wealthy consumers who buy luxury goods.","distractor_reasons":{"A":"Incorrect because middle- and low-income shoppers' tax rates were unchanged, and staple food demand is stable.","B":"Incorrect because bus commuters are unaffected by a tax rise on earnings above $200,000.","C":"Correct selection.","D":"Incorrect because school stationery demand depends on student numbers rather than top-bracket income tax."}}},{"id":"P1_U6_MCQ_261","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_261","question":"During a difficult trading year, Company A makes a net loss of $40,000, while Company B makes a net profit before tax of $100,000. If the government's corporation tax rate is 22%, how much corporation tax does each company pay?","options":{"A":"Company A pays $8,800; Company B pays $22,000","B":"Company A pays $0; Company B pays $22,000","C":"Company A pays $40,000; Company B pays $78,000","D":"Both companies pay $22,000"},"correctOption":"B","correctAnswer":"Company A pays $0; Company B pays $22,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because corporation tax is levied only on business profits; a loss-making business pays $0, while Company B pays 22% of $100,000 ($22,000).","distractor_reasons":{"A":"Incorrect because businesses do not pay corporation tax on financial losses.","B":"Correct selection.","C":"Incorrect because $78,000 is Company B's profit *after* tax, and Company A pays zero tax.","D":"Incorrect because Company A made a loss and therefore has no taxable profit."}}},{"id":"P1_U6_MCQ_262","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_262","question":"The government imposes a new 25% indirect sales tax on cinema tickets, where demand is highly price-sensitive (elastic), and a 25% indirect tax on petrol, where demand is price-insensitive (inelastic). Which statement is most accurate?","options":{"A":"Cinemas can pass the entire tax onto customers without losing any ticket sales","B":"Petrol stations will lose 90% of their customers immediately","C":"Both industries will see identical percentage drops in sales volume","D":"Cinemas will suffer a much larger fall in sales volume if they raise prices than petrol stations will"},"correctOption":"D","correctAnswer":"Cinemas will suffer a much larger fall in sales volume if they raise prices than petrol stations will","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when demand is price-elastic (cinemas), passing an indirect tax onto prices causes a sharp drop in quantity demanded, whereas inelastic necessities (petrol) retain most buyers.","distractor_reasons":{"A":"Incorrect because price-sensitive cinema-goers will switch to home streaming if ticket prices jump.","B":"Incorrect because drivers still need fuel to commute and work, making demand inelastic in the short term.","C":"Incorrect because consumer responsiveness to price changes differs sharply between entertainment and fuel.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_263","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_263","question":"A government increases public spending on state pensions and unemployment benefits during an economic slowdown. How does this fiscal policy help domestic retail businesses?","options":{"A":"It maintains household spending power among low-income groups, supporting demand for everyday goods","B":"It lowers the central bank's base interest rate automatically","C":"It eliminates all indirect taxes on retail sales","D":"It forces retail employees to accept lower hourly wages"},"correctOption":"A","correctAnswer":"It maintains household spending power among low-income groups, supporting demand for everyday goods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because welfare and pension payments are spent quickly on food, clothing, and household necessities, stabilising retail revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because welfare spending is fiscal policy and does not automatically cut interest rates.","C":"Incorrect because sales taxes such as VAT remain in place.","D":"Incorrect because transfer payments do not lower legal or market wage rates."}}},{"id":"P1_U6_MCQ_264","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_264","question":"To encourage domestic manufacturing of electric bicycles, a government provides a $200 production subsidy to domestic manufacturers for every electric bike built. What is the direct effect of this subsidy?","options":{"A":"It raises production costs and forces manufacturers to increase retail prices","B":"It lowers unit production costs, enabling manufacturers to charge more competitive prices or earn higher margins","C":"It bans all domestic sales of electric bicycles","D":"It increases the corporation tax rate on bicycle makers"},"correctOption":"B","correctAnswer":"It lowers unit production costs, enabling manufacturers to charge more competitive prices or earn higher margins","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a government production subsidy reduces a firm's effective cost per unit, improving price competitiveness and profitability.","distractor_reasons":{"A":"Incorrect because subsidies reduce, rather than raise, effective unit costs.","B":"Correct selection.","C":"Incorrect because subsidies encourage higher output and sales.","D":"Incorrect because subsidies provide financial support rather than higher taxes."}}},{"id":"P1_U6_MCQ_265","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_265","question":"A home furniture retailer offers 'Buy Now, Pay Over 24 Months' credit deals financed through a partner bank. When the central bank cuts interest rates from 6% to 2%, why does the retailer's sales volume increase?","options":{"A":"Financing monthly instalment plans becomes much cheaper, making big-ticket furniture more affordable for shoppers","B":"Timber and fabric raw material prices fall by 4% automatically","C":"Households earn higher interest on bank savings and stop buying furniture","D":"The government lowers Value Added Tax on sofas by 4%"},"correctOption":"A","correctAnswer":"Financing monthly instalment plans becomes much cheaper, making big-ticket furniture more affordable for shoppers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lower interest rates reduce the cost of consumer credit and monthly instalment payments, stimulating demand for expensive household goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because interest rate cuts lower borrowing costs rather than directly cutting timber prices.","C":"Incorrect because lower interest rates reduce returns on savings, encouraging spending rather than saving.","D":"Incorrect because VAT is fiscal policy, not an automatic consequence of interest rate cuts."}}},{"id":"P1_U6_MCQ_266","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_266","question":"Company X has $8 million in variable-rate bank loans, whereas Company Y has zero debt and $5 million in cash reserves. If the central bank raises interest rates by 4 percentage points, how are the two firms affected?","options":{"A":"Both companies suffer identical increases in interest expenses","B":"Company X faces much higher loan interest expenses, while Company Y earns higher interest income on its cash reserves","C":"Company Y faces higher loan interest costs, while Company X pays zero interest","D":"Neither company is affected by interest rate changes"},"correctOption":"B","correctAnswer":"Company X faces much higher loan interest expenses, while Company Y earns higher interest income on its cash reserves","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher interest rates penalise net borrowers (increasing loan expenses) while benefiting cash-rich businesses (increasing deposit interest earned).","distractor_reasons":{"A":"Incorrect because Company Y has no debt and therefore pays no loan interest.","B":"Correct selection.","C":"Incorrect because it reverses the financial positions of Company X and Company Y.","D":"Incorrect because both firms' net finance costs/income and customer demand are affected."}}},{"id":"P1_U6_MCQ_267","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_267","question":"When Country A's central bank raises interest rates significantly above those in other countries, international investors move money into Country A's banks to earn higher returns, causing Country A's currency to appreciate. How does this double impact affect a domestic exporter in Country A?","options":{"A":"Both borrowing costs and foreign-currency export prices decrease","B":"Borrowing costs fall while export sales double","C":"Borrowing costs rise and its exports become more expensive abroad, reducing competitiveness","D":"Corporation tax falls to zero while imports become more expensive"},"correctOption":"C","correctAnswer":"Borrowing costs rise and its exports become more expensive abroad, reducing competitiveness","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because higher interest rates raise financing costs for the exporter while the resulting currency appreciation makes its products dearer to overseas buyers.","distractor_reasons":{"A":"Incorrect because higher interest rates increase borrowing costs and currency appreciation raises foreign export prices.","B":"Incorrect because both higher interest rates and currency appreciation hurt domestic exporters.","C":"Correct selection.","D":"Incorrect because monetary policy does not waive corporation tax, and appreciation makes imports cheaper."}}},{"id":"P1_U6_MCQ_268","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_268","question":"With bank loan interest rates at an all-time high of 10%, a printing firm needs a new $300,000 digital press to fulfill a two-year contract. Which financing option avoids taking out a costly bank loan?","options":{"A":"Leasing the digital press through monthly rental payments","B":"Using a high-interest bank overdraft for two years","C":"Issuing debentures at a 12% fixed interest rate","D":"Delaying supplier payments until legal action is taken"},"correctOption":"A","correctAnswer":"Leasing the digital press through monthly rental payments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing allows a business to use equipment for a fixed monthly fee without borrowing a large capital sum or paying upfront purchase costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bank overdrafts typically carry even higher interest rates than term loans.","C":"Incorrect because 12% debentures are long-term debt carrying an even higher interest burden.","D":"Incorrect because defaulting on supplier invoices destroys trade credit and risks court action."}}},{"id":"P1_U6_MCQ_269","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_269","question":"Country Z raises its corporation tax rate from 18% to 32%, while neighbouring Country W keeps its corporation tax at 15%. What is a long-term risk for Country Z's economy?","options":{"A":"Multinational companies may relocate new factories and headquarters to Country W to retain more post-tax profit","B":"Consumer prices in Country Z will fall by 14% immediately","C":"Unemployment in Country Z will drop to 0%","D":"All businesses in Country W will move to Country Z"},"correctOption":"A","correctAnswer":"Multinational companies may relocate new factories and headquarters to Country W to retain more post-tax profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high corporation tax reduces after-tax returns on investment, discouraging inward investment and prompting firms to relocate to lower-tax countries.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher business taxes do not cause retail prices to drop by 14%.","C":"Incorrect because lower business investment tends to reduce job creation rather than eliminating unemployment.","D":"Incorrect because firms prefer lower-tax jurisdictions, so movement would be out of Country Z, not into it."}}},{"id":"P1_U6_MCQ_270","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_270","question":"During a recession, a clothing manufacturer notices that its high-end designer suits are making heavy losses, while its basic workwear uniforms remain profitable. What is the most sensible operational response?","options":{"A":"Discontinue the loss-making designer suits and focus resources on profitable workwear uniforms","B":"Double production of the loss-making designer suits","C":"Close down the profitable workwear division to subsidise designer suits","D":"Raise prices on all items by 50%"},"correctOption":"A","correctAnswer":"Discontinue the loss-making designer suits and focus resources on profitable workwear uniforms","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rationalising the product portfolio to cut loss-making lines preserves cash flow and focuses capacity on profitable segments during a downturn.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because expanding an unprofitable product line increases losses and drains cash.","C":"Incorrect because shutting down the only profitable division would lead to business failure.","D":"Incorrect because large price increases during a recession would destroy demand for workwear too."}}},{"id":"P1_U6_MCQ_271","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_271","question":"High inflation has pushed up hourly factory wage rates by 9% this year. How can a furniture manufacturer offset these higher wage costs without raising its retail prices?","options":{"A":"Invest in staff training and automated machinery to increase output per worker (labour productivity)","B":"Hire twice as many workers to produce the exact same quantity of furniture","C":"Stop performing quality checks so defective furniture is shipped to shops","D":"Reduce working hours while keeping weekly pay unchanged"},"correctOption":"A","correctAnswer":"Invest in staff training and automated machinery to increase output per worker (labour productivity)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because raising labour productivity reduces the labour cost per unit produced, absorbing wage increases without harming profit margins or prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because doubling staff for the same output doubles unit labour costs.","C":"Incorrect because shipping defective products causes returns, refunds, and lost customers.","D":"Incorrect because paying the same weekly wage for fewer hours increases unit labour costs further."}}},{"id":"P1_U6_MCQ_272","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_272","question":"A restaurant owner pays taxes on the restaurant's annual net profit and also collects a 10% tax added onto customers' meal bills to pass to the government. Which types of tax are these?","options":{"A":"Tax on net profit is an indirect tax; tax on meal bills is a direct tax","B":"Both taxes are direct taxes on income","C":"Both taxes are indirect taxes on expenditure","D":"Tax on net profit is a direct tax (corporation tax); tax on meal bills is an indirect tax (sales tax/VAT)"},"correctOption":"D","correctAnswer":"Tax on net profit is a direct tax (corporation tax); tax on meal bills is an indirect tax (sales tax/VAT)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because direct taxes are levied directly on income or company profits, whereas indirect taxes are added to the price of goods and services bought.","distractor_reasons":{"A":"Incorrect because it reverses the definitions of direct and indirect taxes.","B":"Incorrect because a sales tax added to customer meal bills is an indirect tax on spending.","C":"Incorrect because tax on company profit is a direct tax.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_273","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_273","question":"To reduce rapid inflation, a government increases income tax and cuts public infrastructure spending (contractionary fiscal policy). What is a major risk of this policy for domestic businesses?","options":{"A":"Consumer and government demand may fall too sharply, pushing the economy into a recession and raising unemployment","B":"Inflation will immediately accelerate to 50% per year","C":"Businesses will face severe shortages of raw materials due to booming demand","D":"Commercial banks will be forced to lend money at 0% interest"},"correctOption":"A","correctAnswer":"Consumer and government demand may fall too sharply, pushing the economy into a recession and raising unemployment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher taxes and lower public spending reduce total spending in the economy, which cools inflation but risks slowing growth and causing job losses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because contractionary fiscal policy reduces demand and lowers, rather than accelerates, inflation.","C":"Incorrect because falling demand creates spare capacity rather than supply shortages.","D":"Incorrect because fiscal policy changes do not force banks to offer 0% loans."}}},{"id":"P1_U6_MCQ_274","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_274","question":"Why do mergers and takeovers between companies usually increase significantly during the growth stage of the business cycle?","options":{"A":"High business confidence, rising profits, and accessible finance encourage firms to expand rapidly to capture growing market demand","B":"Governments ban organic internal growth during economic expansions","C":"Company share prices are at their lowest possible slump levels","D":"Businesses want to reduce their total production capacity during growth"},"correctOption":"A","correctAnswer":"High business confidence, rising profits, and accessible finance encourage firms to expand rapidly to capture growing market demand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because strong profit growth and optimistic market forecasts give businesses the cash, confidence, and finance needed for external expansion.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internal growth is always legal.","C":"Incorrect because share prices rise during economic growth rather than sitting at slump lows.","D":"Incorrect because firms merge and acquire rivals to *expand* capacity and market share during growth."}}},{"id":"P1_U6_MCQ_275","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_275","question":"A small independent bakery operates as a sole trader with no bank loans and sells basic loaves of bread locally. Which government economic policy change will have the most immediate impact on this bakery?","options":{"A":"A 2% cut in corporation tax rates","B":"A 10% increase in personal income tax rates and higher indirect taxes on flour and electricity","C":"The removal of import tariffs on luxury foreign yachts","D":"A slight change in stock exchange listing rules for public limited companies"},"correctOption":"B","correctAnswer":"A 10% increase in personal income tax rates and higher indirect taxes on flour and electricity","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a sole trader pays personal income tax (not corporation tax) and is directly affected by indirect taxes on energy and ingredients.","distractor_reasons":{"A":"Incorrect because sole traders are unincorporated and pay personal income tax on profits, not corporation tax.","B":"Correct selection.","C":"Incorrect because yacht tariffs have no direct bearing on a local bread bakery.","D":"Incorrect because stock exchange rules apply only to public limited companies (plcs)."}}},{"id":"P1_U6_MCQ_276","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_276","question":"Global streaming platforms and social media have led teenagers in Brazil, South Korea, and Germany to wear similar sportswear brands and listen to the same music. How does this trend benefit global sportswear brands?","options":{"A":"They can sell standardised products with global marketing campaigns, achieving huge economies of scale","B":"They no longer need to pay any transport or customs fees","C":"They are legally protected from all local competitors in every country","D":"They must design completely different shoes for every single city"},"correctOption":"A","correctAnswer":"They can sell standardised products with global marketing campaigns, achieving huge economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because converging global consumer tastes allow companies to produce larger runs of standardised designs and spread marketing costs worldwide.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because physical goods still incur shipping and customs costs when crossing borders.","C":"Incorrect because globalisation increases competition rather than granting legal monopolies.","D":"Incorrect because converging tastes reduce, rather than increase, the need for localized designs."}}},{"id":"P1_U6_MCQ_277","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_277","question":"A European telecommunications company moves its telephone customer support centre to an overseas country where English-speaking graduates earn 60% less. What is a common operational risk of this offshoring decision?","options":{"A":"Time-zone differences, accent barriers, or lack of local product familiarity may reduce customer satisfaction","B":"The company's total wage bill will increase by 60%","C":"Domestic customers are legally barred from calling overseas support centres","D":"International telephone lines become completely free of charge"},"correctOption":"A","correctAnswer":"Time-zone differences, accent barriers, or lack of local product familiarity may reduce customer satisfaction","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because while offshoring services lowers wage costs, cultural/language differences and scripted responses can frustrate domestic customers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower overseas salaries reduce, rather than increase, the total wage bill.","C":"Incorrect because offshore call centres are legally and widely used across industries.","D":"Incorrect because international telecom infrastructure still incurs operating expenses."}}},{"id":"P1_U6_MCQ_278","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_278","question":"When Country M removes trade barriers, efficient foreign appliance makers enter the market with high-quality, competitively priced washing machines. How can this increased global competition benefit domestic appliance makers in the long run?","options":{"A":"It forces domestic firms to innovate, cut waste, and improve quality to survive, making them more efficient","B":"It allows domestic firms to raise prices while lowering product quality","C":"It guarantees that domestic firms will keep 100% of their original market share","D":"It eliminates the need for domestic firms to invest in research and development"},"correctOption":"A","correctAnswer":"It forces domestic firms to innovate, cut waste, and improve quality to survive, making them more efficient","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because exposure to world-class rivals eliminates complacency and pushes domestic businesses to raise productivity and innovation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raising prices while lowering quality would cause customers to switch immediately to imports.","C":"Incorrect because foreign competition typically reduces domestic firms' market share unless they adapt.","D":"Incorrect because stronger competition requires *more*, not less, investment in R&D."}}},{"id":"P1_U6_MCQ_279","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_279","question":"Under globalisation, large foreign corporations frequently launch takeover bids to buy successful domestic public limited companies. Why might employees in the domestic company worry about a foreign takeover?","options":{"A":"The new foreign owners may close domestic factories or head offices to cut costs and consolidate operations abroad","B":"Foreign owners are legally required to double all domestic employees' salaries","C":"The domestic company will immediately stop selling any products","D":"Employees will have to pay corporation tax out of their personal savings"},"correctOption":"A","correctAnswer":"The new foreign owners may close domestic factories or head offices to cut costs and consolidate operations abroad","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because foreign acquirers often rationalise duplicated departments or shift production to lower-cost countries, leading to domestic redundancies.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because foreign buyers are not legally required to double staff pay.","C":"Incorrect because acquirers buy profitable firms to expand sales, not stop selling.","D":"Incorrect because corporation tax is paid by the company out of profits, not by employees."}}},{"id":"P1_U6_MCQ_280","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_280","question":"Countries in a single-market trade bloc allow free movement of goods, services, capital, and workers across member borders without work visas or customs checks. How does this help a construction firm in Member Country A?","options":{"A":"It can easily recruit skilled builders from Member Country B during labour shortages and bid for projects across the bloc","B":"It is protected by a 50% import tariff against builders from Member Country B","C":"It cannot invest any capital in neighbouring member countries","D":"It is guaranteed government subsidies for every house built"},"correctOption":"A","correctAnswer":"It can easily recruit skilled builders from Member Country B during labour shortages and bid for projects across the bloc","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because free movement of labour and services within a single market helps firms overcome local skill shortages and expand regionally.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a single market eliminates tariffs between member states rather than imposing a 50% tariff.","C":"Incorrect because free movement of capital explicitly allows cross-border investment within the bloc.","D":"Incorrect because single-market membership does not guarantee housing construction subsidies."}}},{"id":"P1_U6_MCQ_281","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_281","question":"Instead of charging a customs tax, Country X introduces unnecessarily complex packaging inspections and unique technical rules that apply only to foreign electronics, delaying imports at ports for months. What is this trade barrier called?","options":{"A":"A non-tariff barrier","B":"A free trade agreement","C":"Currency appreciation","D":"An export subsidy"},"correctOption":"A","correctAnswer":"A non-tariff barrier","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because non-tariff barriers use bureaucratic red tape, administrative delays, or restrictive standards to limit imports without using formal tariffs or quotas.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because free trade agreements remove rather than create trade obstacles.","C":"Incorrect because currency appreciation is an exchange rate movement, not a port inspection rule.","D":"Incorrect because export subsidies are payments to domestic exporters, not rules blocking imports."}}},{"id":"P1_U6_MCQ_282","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_282","question":"Country A's government pays huge cash subsidies to its domestic solar panel exporters so they can sell solar panels in Country B below their actual production cost. Why might Country B impose a tariff on Country A's solar panels?","options":{"A":"To prevent unfair foreign 'dumping' from destroying Country B's domestic solar manufacturers","B":"To make solar panels much more expensive for consumers in Country A","C":"To eliminate all customs tax revenue in Country B","D":"To encourage Country A to increase its export subsidies further"},"correctOption":"A","correctAnswer":"To prevent unfair foreign 'dumping' from destroying Country B's domestic solar manufacturers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because anti-dumping tariffs counter unfair foreign state subsidies so domestic producers can compete on a level playing field.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Country B's import tariff affects prices inside Country B, not Country A.","C":"Incorrect because import tariffs generate customs tax revenue for Country B.","D":"Incorrect because tariffs discourage subsidised exports by neutralising their price advantage."}}},{"id":"P1_U6_MCQ_283","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_283","question":"A government places a permanent 40% tariff on all imported cars to protect its two domestic car manufacturers. What is a long-term disadvantage of permanent protectionism for the domestic car industry?","options":{"A":"Without foreign competition, domestic car makers may become inefficient, slow to innovate, and charge high prices for lower quality","B":"Domestic consumers will enjoy much lower car prices and wider brand choice","C":"Domestic car makers will automatically become the world's top exporters","D":"Steel and tyre costs for domestic car makers will drop to zero"},"correctOption":"A","correctAnswer":"Without foreign competition, domestic car makers may become inefficient, slow to innovate, and charge high prices for lower quality","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shielding domestic firms permanently from competition removes the incentive to improve efficiency, quality, and innovation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tariffs raise prices and reduce consumer choice.","C":"Incorrect because inefficient, protected domestic producers struggle to compete in global export markets.","D":"Incorrect because tariffs on finished cars do not eliminate raw material costs."}}},{"id":"P1_U6_MCQ_284","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_284","question":"A bicycle assembler imports gear sets at a pre-tariff price of $50 each. If the government introduces a 20% import tariff on bicycle parts, and other production costs are $90 per bike, what is the new total unit cost per bicycle?","options":{"A":"$140","B":"$150","C":"$160","D":"$100"},"correctOption":"B","correctAnswer":"$150","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a 20% tariff on $50 adds $10 ($50 × 0.20 = $10), making the gear set cost $60; adding $90 of other costs gives $150 per bicycle.","distractor_reasons":{"A":"Incorrect because $140 ($50 + $90) omits the $10 import tariff.","B":"Correct selection.","C":"Incorrect because $160 adds $20 instead of 20% of $50 ($10).","D":"Incorrect because $100 omits most of the other production costs."}}},{"id":"P1_U6_MCQ_285","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_285","question":"A successful bakery chain based in Malaysia opens twelve physical retail cafes and a central baking kitchen in Singapore. How does this change the classification of the business?","options":{"A":"It becomes a multinational company (MNC) because it operates production and retail facilities in more than one country","B":"It becomes a public sector corporation owned by both governments","C":"It becomes a sole trader because it operates in two countries","D":"It remains a purely domestic business because Malaysia and Singapore are neighbours"},"correctOption":"A","correctAnswer":"It becomes a multinational company (MNC) because it operates production and retail facilities in more than one country","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because operating physical production and retail branches across two or more sovereign countries defines a multinational company (MNC).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because opening overseas branches does not transfer ownership to governments.","C":"Incorrect because legal ownership form (sole trader vs limited company) is unrelated to operating in two countries.","D":"Incorrect because operating across national borders makes a firm multinational regardless of geographical proximity."}}},{"id":"P1_U6_MCQ_286","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_286","question":"A European supermarket MNC operates stores across Western Europe, North America, and Southeast Asia. How does this geographic spread reduce commercial risk for the company?","options":{"A":"If one region enters an economic recession, strong sales and profits in growing regions can offset the downturn","B":"It ensures that all three regions experience recessions at the exact same time","C":"It eliminates all competition from local supermarkets in every country","D":"It allows the company to avoid paying rent on any of its stores"},"correctOption":"A","correctAnswer":"If one region enters an economic recession, strong sales and profits in growing regions can offset the downturn","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because diversifying operations across multiple continents spreads economic and political risk so the firm is not dependent on a single economy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because different regions are often at different stages of the business cycle, which is why diversification reduces risk.","C":"Incorrect because MNCs face intense competition from local chains in every market.","D":"Incorrect because store rent and property costs apply in every country."}}},{"id":"P1_U6_MCQ_287","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_287","question":"An automotive manufacturer from Country A opens a major software and artificial intelligence research lab in California, USA, even though engineering salaries there are very high. What is the main reason for this MNC investment?","options":{"A":"To access world-leading specialist talent, universities, and technological innovation clusters","B":"To take advantage of cheap, unskilled manual labour","C":"To avoid paying any wages to software engineers","D":"To reduce global sales of electric vehicles"},"correctOption":"A","correctAnswer":"To access world-leading specialist talent, universities, and technological innovation clusters","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because MNCs establish R&D centres in high-tech hubs to tap into specialised skills, innovation ecosystems, and cutting-edge knowledge.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because California has high salaries and is chosen for high-skill innovation, not cheap manual labour.","C":"Incorrect because engineers in technology hubs receive very high salaries.","D":"Incorrect because AI and software research supports innovation and future vehicle sales."}}},{"id":"P1_U6_MCQ_288","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_288","question":"When a multinational carmaker builds an assembly factory in Country T, dozens of small local businesses win contracts to supply seat covers, packaging, catering, security, and truck transport. What is this benefit to Country T?","options":{"A":"Indirect job creation and business growth across the local domestic supply chain","B":"Repatriation of all local profits back to the MNC's home country","C":"Elimination of all local small businesses due to monopoly control","D":"A fall in Country T's Gross Domestic Product"},"correctOption":"A","correctAnswer":"Indirect job creation and business growth across the local domestic supply chain","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because MNCs often purchase local goods and services, creating a multiplier effect of extra orders and employment for domestic suppliers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local supplier contracts keep revenue circulating inside Country T's economy.","C":"Incorrect because the scenario shows local small businesses growing through new supplier contracts.","D":"Incorrect because increased production and supplier activity raise Country T's GDP."}}},{"id":"P1_U6_MCQ_289","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_289","question":"Before a foreign multinational supermarket entered Country V, domestic grocery chains charged high prices and offered poor customer service. Two years after the MNC opened stores, domestic chains improved store cleanliness and lowered prices. Why?","options":{"A":"Increased competition from the MNC forced local businesses to become more efficient and customer-focused","B":"The foreign MNC gave away all its groceries for free","C":"The government banned domestic supermarkets from making any profit","D":"Domestic supermarkets stopped selling food altogether"},"correctOption":"A","correctAnswer":"Increased competition from the MNC forced local businesses to become more efficient and customer-focused","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because MNC entry introduces modern retail standards and price competition, spurring domestic firms to improve efficiency and service quality.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because MNCs operate to earn profits, not give away goods for free.","C":"Incorrect because the improvements were driven by market competition, not a government profit ban.","D":"Incorrect because domestic chains adapted and continued competing in the grocery market."}}},{"id":"P1_U6_MCQ_290","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_290","question":"A wealthy multinational tech firm opens offices in a developing city and offers salaries 50% higher than local firms can afford, hiring away the best local engineers and accountants. What problem does this create for domestic businesses?","options":{"A":"Local firms suffer a talent shortage and rising wage costs as their best staff leave for the MNC","B":"Local firms immediately double their profits due to lower staff numbers","C":"The MNC is forced to share its patents with all local competitors","D":"Consumer spending in the city drops to zero"},"correctOption":"A","correctAnswer":"Local firms suffer a talent shortage and rising wage costs as their best staff leave for the MNC","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because MNCs can outbid smaller domestic firms for scarce skilled workers, making it harder and costlier for local businesses to retain talent.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because losing key engineers and accountants harms productivity and profits at local firms.","C":"Incorrect because MNCs protect their intellectual property and do not hand patents to rivals.","D":"Incorrect because higher MNC salaries actually increase local consumer spending."}}},{"id":"P1_U6_MCQ_291","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_291","question":"Why do critics sometimes accuse multinational chemical and mining companies of causing severe environmental damage in developing host countries?","options":{"A":"Some MNCs locate polluting processes in countries with weaker environmental laws and enforcement to cut compliance costs","B":"Developing countries always have the strictest pollution fines in the world","C":"Multinational companies are legally prohibited from using clean technology","D":"Environmental damage always increases an MNC's brand reputation"},"correctOption":"A","correctAnswer":"Some MNCs locate polluting processes in countries with weaker environmental laws and enforcement to cut compliance costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because differing regulatory standards can tempt irresponsible MNCs to exploit lax pollution controls in host nations, imposing external costs on local communities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because weaker regulations or limited enforcement capacity are what create the risk of exploitation.","C":"Incorrect because MNCs are free to use clean technology anywhere and often possess superior green tech.","D":"Incorrect because environmental scandals severely harm an MNC's global reputation."}}},{"id":"P1_U6_MCQ_292","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_292","question":"A UK furniture exporter sells a dining table to a US customer for $2,400. When the order is signed, the exchange rate is £1 = $1.20. By the time the customer pays, the pound appreciates to £1 = $1.50. How much less does the UK exporter receive in pounds?","options":{"A":"£2,000","B":"£1,600","C":"£400","D":"£300"},"correctOption":"C","correctAnswer":"£400","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because at £1 = $1.20, $2,400 equals £2,000 ($2,400 ÷ 1.20), whereas at £1 = $1.50, $2,400 equals £1,600 ($2,400 ÷ 1.50), a reduction of £400.","distractor_reasons":{"A":"Incorrect because £2,000 was the original pound value before the pound appreciated.","B":"Incorrect because £1,600 is the new pound value received, not the reduction.","C":"Correct selection.","D":"Incorrect because the difference between £2,000 and £1,600 is £400, not £300."}}},{"id":"P1_U6_MCQ_293","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_293","question":"A Malaysian electronics retailer imports smartphones from a supplier priced at $30,000 USD. If the Malaysian ringgit depreciates from $1 = RM4.00 to $1 = RM4.50, what happens to the retailer's import cost in ringgit?","options":{"A":"It falls from RM135,000 to RM120,000","B":"It rises from RM120,000 to RM135,000","C":"It stays unchanged at RM120,000","D":"It rises from RM30,000 to RM45,000"},"correctOption":"B","correctAnswer":"It rises from RM120,000 to RM135,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because at $1 = RM4.00, $30,000 costs RM120,000 (30,000 × 4.00), and at $1 = RM4.50, $30,000 costs RM135,000 (30,000 × 4.50).","distractor_reasons":{"A":"Incorrect because a depreciation of the ringgit means more ringgit are needed per dollar, increasing the cost.","B":"Correct selection.","C":"Incorrect because the supplier's price is fixed in US dollars, so the ringgit cost increases.","D":"Incorrect because $30,000 multiplied by 4.00 and 4.50 equals RM120,000 and RM135,000."}}},{"id":"P1_U6_MCQ_294","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_294","question":"Country E's currency appreciates by 20% against the euro. Which domestic business in Country E will benefit most directly from this currency appreciation?","options":{"A":"A retailer that imports French wine and Italian designer clothes to sell in Country E","B":"A domestic hotel chain relying on European tourists visiting Country E","C":"A factory in Country E that exports 90% of its machinery to Germany","D":"A domestic wheat farmer competing against cheap imported European grain"},"correctOption":"A","correctAnswer":"A retailer that imports French wine and Italian designer clothes to sell in Country E","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because currency appreciation makes imported goods cheaper in local currency, lowering purchase costs for importers and boosting their profit margins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because appreciation makes holidays in Country E more expensive for European tourists, reducing bookings.","C":"Incorrect because appreciation makes exported machinery dearer in euros, hurting German sales.","D":"Incorrect because cheaper imported grain undercuts domestic farmers on price."}}},{"id":"P1_U6_MCQ_295","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_295","question":"Country F's currency depreciates sharply, making overseas foreign holidays much more expensive for citizens of Country F while making Country F much cheaper for foreign visitors. How does this affect domestic seaside hotels in Country F?","options":{"A":"Occupancy and revenue rise due to both more foreign tourists and more domestic families choosing holidays at home","B":"Occupancy collapses because domestic families take twice as many overseas flights","C":"Hotel staff wages fall by the exact percentage of the currency depreciation","D":"Domestic hotels are forced to close during the summer peak season"},"correctOption":"A","correctAnswer":"Occupancy and revenue rise due to both more foreign tourists and more domestic families choosing holidays at home","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because currency depreciation boosts inbound tourism (exports of services) and encourages domestic residents to substitute local holidays for costly foreign trips.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because foreign holidays become dearer, discouraging overseas travel by locals.","C":"Incorrect because local wage contracts in domestic currency do not fall when the exchange rate drops.","D":"Incorrect because stronger tourist demand increases hotel bookings rather than forcing closures."}}},{"id":"P1_U6_MCQ_296","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_296","question":"An electronics manufacturer in Country G imports 60% of its microchips from abroad and exports 60% of its finished laptops to overseas buyers. If Country G's currency depreciates, why is the net impact on the manufacturer's profits partly cushioned?","options":{"A":"Higher local-currency costs for imported microchips are partly offset by higher export competitiveness and foreign revenue","B":"Both imported microchips and exported laptops become 60% cheaper","C":"Currency depreciation has zero effect on either imports or exports","D":"The government refunds all import bills whenever the currency depreciates"},"correctOption":"A","correctAnswer":"Higher local-currency costs for imported microchips are partly offset by higher export competitiveness and foreign revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because currency depreciation hurts the import side (higher input costs) while helping the export side (cheaper foreign prices / higher local-currency revenue).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because imported microchips become *more expensive* in domestic currency when the currency depreciates.","C":"Incorrect because both input costs and export prices change, though in offsetting directions.","D":"Incorrect because governments do not refund private businesses for exchange rate movements."}}},{"id":"P1_U6_MCQ_297","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_297","question":"A UK software exporter regularly receives payments in US dollars and also buys cloud-hosting services priced in US dollars. How can the exporter reduce the risk of frequent exchange rate fluctuations between pounds and dollars?","options":{"A":"Keep a US dollar bank account so dollar revenues directly pay dollar expenses without converting currencies back and forth","B":"Convert all dollars into pounds every morning and back into dollars every afternoon","C":"Stop selling software to US customers completely","D":"Ask the UK government to ban all foreign currencies"},"correctOption":"A","correctAnswer":"Keep a US dollar bank account so dollar revenues directly pay dollar expenses without converting currencies back and forth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because matching foreign-currency inflows with foreign-currency outflows in a foreign currency account avoids repeated conversion fees and exchange rate swings.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because converting currencies twice daily incurs unnecessary bank fees and exposes the firm to daily rate swings.","C":"Incorrect because abandoning a major export market sacrifices revenue unnecessarily.","D":"Incorrect because governments cannot ban major international currencies used in global trade."}}},{"id":"P1_U6_MCQ_298","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_298","question":"Why do exporting and importing businesses generally prefer stable exchange rates over rapidly fluctuating exchange rates?","options":{"A":"Stable exchange rates reduce financial uncertainty, making it easier to price international contracts and forecast profit margins","B":"Stable exchange rates eliminate all shipping and insurance costs","C":"Stable exchange rates guarantee that every export business makes a profit","D":"Stable exchange rates remove all domestic taxes on business profits"},"correctOption":"A","correctAnswer":"Stable exchange rates reduce financial uncertainty, making it easier to price international contracts and forecast profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because exchange rate stability allows firms to quote accurate international prices and plan budgets without fear of sudden currency losses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because freight and marine insurance costs still apply regardless of currency stability.","C":"Incorrect because profitability still depends on costs, quality, and competition.","D":"Incorrect because currency stability does not waive corporation tax."}}},{"id":"P1_U6_MCQ_299","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_299","question":"A small family business in Scotland sells traditional hand-knitted wool sweaters through an international e-commerce platform and ships orders worldwide by air courier. How has globalisation benefited this small firm?","options":{"A":"Digital platforms and global logistics enable small niche firms to reach global customers without building expensive overseas stores","B":"It has turned the family business into a massive state-owned monopoly","C":"It has eliminated all competition from other clothing brands worldwide","D":"It exempts the business from paying any UK taxes"},"correctOption":"A","correctAnswer":"Digital platforms and global logistics enable small niche firms to reach global customers without building expensive overseas stores","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because e-commerce and international parcel networks allow even small businesses to export globally with minimal capital investment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the firm remains a small private family business.","C":"Incorrect because global markets feature intense competition.","D":"Incorrect because domestic taxes still apply to profits earned from export sales."}}},{"id":"P1_U6_MCQ_300","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_300","question":"A developing country's government offers a five-year tax holiday to attract a multinational electronics factory. Which balanced evaluation best reflects the impact of this policy?","options":{"A":"While the host country sacrifices short-term tax revenue and risks profit repatriation, it gains immediate job creation, worker training, and export growth","B":"Tax holidays guarantee that the MNC will stay in the country forever and reinvest 100% of its profits locally","C":"MNCs never bring any benefits to developing economies and always destroy GDP","D":"Host governments always earn maximum tax revenue during a five-year tax holiday"},"correctOption":"A","correctAnswer":"While the host country sacrifices short-term tax revenue and risks profit repatriation, it gains immediate job creation, worker training, and export growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because evaluating MNC inward investment requires weighing trade-offs: lost tax receipts and profit outflows versus jobs, skills transfer, and exports.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because MNCs can still relocate once the tax holiday ends and often repatriate profits.","C":"Incorrect because MNCs frequently boost employment, GDP, and infrastructure.","D":"Incorrect because a tax holiday specifically waives corporate taxes for five years."}}},{"id":"P1_U6_MCQ_301","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_301","question":"A large commercial farm applies excessive chemical fertilisers and pesticides to maximise short-term crop yields, causing toxic chemicals to wash into nearby lakes and kill aquatic life. Which environmental impact does this illustrate?","options":{"A":"Water pollution and damage to local ecosystems caused by agricultural business activity","B":"Reduction in greenhouse gas emissions through organic farming","C":"Creation of external benefits for local fishing clubs","D":"Conservation of non-renewable mineral resources"},"correctOption":"A","correctAnswer":"Water pollution and damage to local ecosystems caused by agricultural business activity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because chemical runoff from intensive farming pollutes waterways and harms biodiversity, creating negative environmental externalities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because synthetic chemical overuse is the opposite of organic farming.","C":"Incorrect because killing fish creates external costs, not benefits, for local fishing clubs.","D":"Incorrect because soil and water degradation harms natural ecosystems rather than conserving resources."}}},{"id":"P1_U6_MCQ_302","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_302","question":"A fast-fashion retailer sells ultra-cheap synthetic polyester garments designed to be worn only a few times before being thrown away. Which two environmental problems are worsened by this business model?","options":{"A":"Rapidly overflowing landfill sites and microplastic pollution from synthetic fibres","B":"Increased reforestation and lower fossil fuel extraction","C":"Reduced water consumption in textile dyeing","D":"Improved soil quality from biodegradable natural wool"},"correctOption":"A","correctAnswer":"Rapidly overflowing landfill sites and microplastic pollution from synthetic fibres","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because disposable synthetic clothing increases solid landfill waste and sheds non-biodegradable microplastics derived from fossil fuels.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because polyester is made from petrochemicals, increasing rather than lowering fossil fuel use.","C":"Incorrect because fast-fashion mass production consumes vast amounts of water for dyeing.","D":"Incorrect because polyester is synthetic plastic, not biodegradable wool."}}},{"id":"P1_U6_MCQ_303","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_303","question":"To cut carbon emissions in its supply chain, a global clothing brand switches from transporting garments by cargo aircraft to transporting them by container ship. Why is this more environmentally friendly?","options":{"A":"Sea freight produces far lower carbon dioxide emissions per tonne of cargo carried than air freight","B":"Container ships travel faster than commercial cargo planes","C":"Air freight requires zero aviation fuel","D":"Sea freight eliminates the need to manufacture clothes"},"correctOption":"A","correctAnswer":"Sea freight produces far lower carbon dioxide emissions per tonne of cargo carried than air freight","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because maritime shipping is vastly more fuel-efficient per tonne-kilometre than aviation, dramatically reducing transport carbon footprint.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sea freight is much slower than air freight, requiring better inventory planning.","C":"Incorrect because cargo planes burn large quantities of jet fuel.","D":"Incorrect because changing transport mode reduces shipping emissions, not manufacturing."}}},{"id":"P1_U6_MCQ_304","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_304","question":"A private engineering academy charges tuition fees to train apprentices (earning $1.2 million in revenue) and also reduces local youth crime and welfare costs by $400,000 per year. How are these two figures classified?","options":{"A":"$1.2 million is a private benefit; $400,000 is an external benefit","B":"$1.2 million is an external cost; $400,000 is a private cost","C":"Both figures are external costs borne by taxpayers","D":"$1.2 million is an external benefit; $400,000 is a private benefit"},"correctOption":"A","correctAnswer":"$1.2 million is a private benefit; $400,000 is an external benefit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because private benefits are financial gains received directly by the business ($1.2m fees), whereas external benefits are positive gains enjoyed by wider society ($400k public savings).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both figures represent positive gains (benefits), not costs.","C":"Incorrect because lower crime and welfare spending save taxpayers money rather than imposing costs.","D":"Incorrect because it reverses private benefit and external benefit."}}},{"id":"P1_U6_MCQ_305","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_305","question":"A property developer builds a huge out-of-town retail park without upgrading local roads, resulting in severe daily traffic jams that cost local commuters and delivery drivers $150,000 per month in wasted fuel and delays. What are these commuter losses?","options":{"A":"External costs imposed on third parties outside the business","B":"Private fixed costs paid by the property developer","C":"External benefits increasing local productivity","D":"Private revenues earned by retail park shops"},"correctOption":"A","correctAnswer":"External costs imposed on third parties outside the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because traffic congestion and wasted fuel suffered by uninvolved road users are negative spill-overs (external costs) of the retail park's operation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the developer does not pay for commuters' wasted fuel and lost time.","C":"Incorrect because traffic gridlock harms rather than benefits commuters.","D":"Incorrect because wasted fuel is a cost to drivers, not revenue to shops."}}},{"id":"P1_U6_MCQ_306","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_306","question":"A coal-fired power station incurs $750,000 per week in private fuel, wage, and maintenance costs, while its smoke and carbon emissions cause $220,000 per week in external health and environmental costs. What is the weekly social cost?","options":{"A":"$530,000","B":"$750,000","C":"$970,000","D":"$220,000"},"correctOption":"C","correctAnswer":"$970,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social cost is the sum of private costs ($750,000) and external costs ($220,000), which equals $970,000.","distractor_reasons":{"A":"Incorrect because $530,000 subtracts external costs from private costs instead of adding them.","B":"Incorrect because $750,000 includes only private costs.","C":"Correct selection.","D":"Incorrect because $220,000 includes only external costs."}}},{"id":"P1_U6_MCQ_307","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_307","question":"An electric tram operator earns $600,000 per month in passenger ticket sales (private benefit) and reduces road traffic congestion and air pollution costs for city residents by $250,000 per month (external benefit). What is the monthly social benefit?","options":{"A":"$350,000","B":"$850,000","C":"$600,000","D":"$250,000"},"correctOption":"B","correctAnswer":"$850,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because social benefit equals private benefit ($600,000) plus external benefit ($250,000), totalling $850,000.","distractor_reasons":{"A":"Incorrect because $350,000 subtracts external benefit from private benefit.","B":"Correct selection.","C":"Incorrect because $600,000 omits the external benefit to city residents.","D":"Incorrect because $250,000 omits the private benefit to the tram operator."}}},{"id":"P1_U6_MCQ_308","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_308","question":"A mining firm proposes a project expected to generate $5 million in private profit for shareholders, but cost-benefit analysis shows it will cause $9 million in external river contamination and farmland loss. Why should the government block the project?","options":{"A":"Because the heavy external costs outweigh the private gains, resulting in a net social loss to the country","B":"Because private businesses are never allowed to earn a profit","C":"Because external costs are smaller than private profits","D":"Because cost-benefit analysis ignores all environmental damage"},"correctOption":"A","correctAnswer":"Because the heavy external costs outweigh the private gains, resulting in a net social loss to the country","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when external damages ($9m) exceed the net private benefits ($5m), total social costs exceed total social benefits, making society worse off.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because private firms are encouraged to make profits provided social benefits exceed social costs.","C":"Incorrect because $9 million in external costs is larger, not smaller, than $5 million in profit.","D":"Incorrect because cost-benefit analysis explicitly incorporates external environmental and social impacts."}}},{"id":"P1_U6_MCQ_309","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_309","question":"Instead of selling office carpet tiles outright, a flooring manufacturer leases carpet tiles to corporate offices, replaces only worn tiles, and recycles old tiles into new flooring. How does this circular-economy model support sustainable development?","options":{"A":"It drastically reduces raw material extraction and landfill waste while building recurring revenue for the manufacturer","B":"It forces corporate offices to throw away entire carpets every six months","C":"It increases petroleum consumption by using non-recyclable glues","D":"It eliminates the need for any customer service or maintenance"},"correctOption":"A","correctAnswer":"It drastically reduces raw material extraction and landfill waste while building recurring revenue for the manufacturer","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retaining ownership and refurbishing/recycling materials closes the resource loop, conserving natural resources and reducing waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because modular replacement avoids throwing away entire undamaged carpets.","C":"Incorrect because circular design uses recyclable materials rather than virgin petrochemicals.","D":"Incorrect because leasing involves ongoing maintenance and tile replacement."}}},{"id":"P1_U6_MCQ_310","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_310","question":"An e-commerce company replaces polystyrene foam packing peanuts with biodegradable mushroom-based packaging that dissolves harmlessly in garden soil. What is a major benefit of this change?","options":{"A":"It eliminates persistent non-biodegradable plastic waste and enhances the company's green brand image","B":"It increases landfill taxes paid by the e-commerce company","C":"It makes parcels much heavier and doubles air freight emissions","D":"It forces customers to return every cardboard box by courier"},"correctOption":"A","correctAnswer":"It eliminates persistent non-biodegradable plastic waste and enhances the company's green brand image","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because biodegradable packaging decomposes naturally without polluting soil or oceans, appealing to eco-conscious online shoppers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because biodegradable packaging reduces waste sent to landfill.","C":"Incorrect because mushroom-based packaging is lightweight like foam.","D":"Incorrect because customers can compost it at home rather than returning it."}}},{"id":"P1_U6_MCQ_311","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_311","question":"A bakery installs a heat-recovery system that captures waste heat from its bread ovens to warm water and heat its office building. How does this affect the bakery?","options":{"A":"It reduces natural gas and electricity consumption, cutting both energy bills and carbon emissions","B":"It increases the bakery's fixed utility bills every winter","C":"It reduces the quality of the bread baked in the ovens","D":"It forces the bakery to hire twice as many bakers"},"correctOption":"A","correctAnswer":"It reduces natural gas and electricity consumption, cutting both energy bills and carbon emissions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reusing waste industrial heat lowers primary fuel demand, simultaneously reducing overhead costs and greenhouse gas emissions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because capturing waste heat reduces, rather than increases, heating utility bills.","C":"Incorrect because heat recovery uses exhaust heat without altering baking oven temperatures.","D":"Incorrect because automated heat-exchange systems do not require extra baking staff."}}},{"id":"P1_U6_MCQ_312","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_312","question":"A hotel group builds solar-powered eco-lodges using local timber, eliminates single-use plastics, and funds local rainforest conservation. Why is this eco-tourism venture able to charge premium room rates?","options":{"A":"Growing numbers of environmentally conscious travellers are willing to pay more for authentic, low-impact holidays","B":"Governments force tourists to stay only in eco-lodges by law","C":"Solar power is always completely free to install with zero upfront cost","D":"Eco-lodges do not have to pay wages to housekeeping or reception staff"},"correctOption":"A","correctAnswer":"Growing numbers of environmentally conscious travellers are willing to pay more for authentic, low-impact holidays","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising environmental awareness creates profitable niche demand where sustainable differentiation supports premium pricing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tourists choose eco-lodges voluntarily rather than by legal compulsion.","C":"Incorrect because solar installations require substantial initial capital expenditure.","D":"Incorrect because hospitality staff must still be paid fair wages."}}},{"id":"P1_U6_MCQ_313","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_313","question":"More frequent extreme storms and coastal flooding linked to climate change repeatedly damage a port-side warehouse and disrupt deliveries. What is a direct financial impact on the warehouse business?","options":{"A":"Commercial property insurance premiums rise sharply and repair costs reduce net profits","B":"Insurance companies lower premiums because storms are unpredictable","C":"Flooding automatically increases warehouse storage capacity","D":"Customers pay higher prices for water-damaged inventory"},"correctOption":"A","correctAnswer":"Commercial property insurance premiums rise sharply and repair costs reduce net profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because climate-related physical risks increase asset damage, business interruption losses, and fixed insurance overheads.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher flood risk leads insurers to raise premiums or refuse cover.","C":"Incorrect because flood damage reduces usable warehouse space.","D":"Incorrect because damaged inventory must be written off as a loss."}}},{"id":"P1_U6_MCQ_314","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_314","question":"Under new Extended Producer Responsibility (EPR) legislation, drinks manufacturers must pay a fee based on the weight of plastic and glass packaging they place on the market to fund municipal recycling. How does this law influence product design?","options":{"A":"Manufacturers redesign bottles to be lighter and easier to recycle in order to minimise their statutory packaging fees","B":"Manufacturers switch to thicker, heavier, non-recyclable plastic bottles","C":"Manufacturers stop selling beverages in bottles or cans completely","D":"Manufacturers receive a government bonus for every tonne of non-recyclable waste created"},"correctOption":"A","correctAnswer":"Manufacturers redesign bottles to be lighter and easier to recycle in order to minimise their statutory packaging fees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because linking legal fees directly to packaging weight and recyclability creates a financial incentive for eco-design.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because heavier, non-recyclable packaging would incur the highest statutory fees.","C":"Incorrect because beverages still require containers, so firms optimise packaging rather than stopping sales.","D":"Incorrect because EPR laws penalise rather than reward non-recyclable packaging."}}},{"id":"P1_U6_MCQ_315","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_315","question":"To protect nearby residents from aircraft noise pollution, a city airport enforces a strict legal curfew banning all cargo and passenger flights between 11:00 PM and 6:00 AM. How does this affect an overnight express courier company?","options":{"A":"It must reschedule flights or invest in quieter modern aircraft, potentially increasing operating costs or delivery times","B":"It can fly louder, older cargo planes freely throughout the night","C":"Its aviation fuel becomes exempt from all taxes","D":"It no longer needs to employ any pilots or ground handlers"},"correctOption":"A","correctAnswer":"It must reschedule flights or invest in quieter modern aircraft, potentially increasing operating costs or delivery times","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because environmental noise regulations restrict operating hours and require costly fleet upgrades or route adjustments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the curfew explicitly bans flights during night hours.","C":"Incorrect because airport noise curfews do not waive fuel taxes.","D":"Incorrect because daytime flights still require full flight and ground crews."}}},{"id":"P1_U6_MCQ_316","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_316","question":"A government offers annual subsidies to farmers who restore native hedgerows, reduce chemical fertiliser use, and plant cover crops to capture soil carbon. How does this policy affect farm businesses?","options":{"A":"It compensates farmers for adopting sustainable practices that protect biodiversity and soil health","B":"It forces farmers to convert farmland into industrial factories","C":"It increases taxes on organic and sustainable farms","D":"It bans farmers from selling food to domestic supermarkets"},"correctOption":"A","correctAnswer":"It compensates farmers for adopting sustainable practices that protect biodiversity and soil health","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because environmental subsidies offset any lower short-term yields or transition costs, making sustainable agriculture financially viable.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the subsidies reward ecological land stewardship, not industrial construction.","C":"Incorrect because subsidies provide financial payments rather than higher taxes.","D":"Incorrect because sustainable farms continue supplying supermarkets."}}},{"id":"P1_U6_MCQ_317","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_317","question":"A government introduces higher annual road taxes on high-emission petrol company cars and zero road tax on electric company cars. How is a large sales-driven corporation likely to respond?","options":{"A":"Replace its petrol company car fleet with electric vehicles to reduce tax and fuel overheads","B":"Buy more high-emission petrol cars to increase its tax bill","C":"Stop its sales representatives from ever visiting clients","D":"Pay higher dividends by ignoring vehicle tax rules"},"correctOption":"A","correctAnswer":"Replace its petrol company car fleet with electric vehicles to reduce tax and fuel overheads","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because differential environmental taxation makes low-emission vehicles cheaper to run, shifting corporate purchasing decisions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses seek to minimise avoidable tax overheads.","C":"Incorrect because sales teams still visit clients using lower-tax electric vehicles.","D":"Incorrect because ignoring vehicle tax laws results in fines and vehicle impoundment."}}},{"id":"P1_U6_MCQ_318","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_318","question":"An airline advertises '100% Carbon-Neutral Flights' based on questionable tree-planting offsets while its actual jet fuel emissions continue rising every year. Consumer watchdogs ban the advert for 'greenwashing'. What is the main lesson for businesses?","options":{"A":"Environmental marketing claims must be genuine, transparent, and backed by real emission reductions to avoid legal bans and loss of trust","B":"Businesses should make exaggerated green claims because regulators never check adverts","C":"Planting trees eliminates the need for airlines to buy aviation fuel","D":"Advertising bans always increase ticket sales and customer loyalty"},"correctOption":"A","correctAnswer":"Environmental marketing claims must be genuine, transparent, and backed by real emission reductions to avoid legal bans and loss of trust","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because misleading environmental claims ('greenwashing') provoke regulatory enforcement, negative headlines, and consumer cynicism.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because advertising regulators actively penalise unsubstantiated environmental claims.","C":"Incorrect because aircraft still burn jet fuel; offsets do not eliminate fuel consumption.","D":"Incorrect because public censure for greenwashing damages brand credibility."}}},{"id":"P1_U6_MCQ_319","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_319","question":"Environmental campaigners demand a heavy environmental tax on aviation fuel to cut carbon emissions, while budget airlines and holidaymakers oppose the tax because flight prices will rise. Which conflict does this show?","options":{"A":"Environmental protection goals conflicting with consumer demand for low-priced travel and airline industry growth","B":"Airlines demanding higher fuel taxes to reduce passenger numbers","C":"Environmental groups campaigning for cheaper jet fuel","D":"Complete agreement between airlines and climate activists"},"correctOption":"A","correctAnswer":"Environmental protection goals conflicting with consumer demand for low-priced travel and airline industry growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internalising carbon externalities through green taxes raises prices for consumers and reduces demand for airlines.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because airlines oppose higher fuel taxes that raise costs and reduce bookings.","C":"Incorrect because environmental groups want higher, not lower, costs on polluting fuels.","D":"Incorrect because the two groups hold opposing positions on aviation taxation."}}},{"id":"P1_U6_MCQ_320","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_320","question":"A renewable energy company plans to build 30 giant wind turbines on a scenic rural hillside to supply clean electricity to 100,000 homes, but local residents protest against the visual impact and turbine noise. What does this illustrate?","options":{"A":"Even environmentally beneficial green projects can create local external costs and face community opposition","B":"Wind turbines burn coal and release toxic smoke","C":"Local residents never have any right to comment on planning applications","D":"Renewable energy projects never require any land or planning approval"},"correctOption":"A","correctAnswer":"Even environmentally beneficial green projects can create local external costs and face community opposition","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because onshore wind farms reduce national carbon emissions while still generating localised visual and noise externalities for nearby residents.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wind turbines generate zero-carbon electricity without burning fossil fuels.","C":"Incorrect because planning consultations allow local residents to voice objections.","D":"Incorrect because wind farms require land acquisition and environmental/planning permits."}}},{"id":"P1_U6_MCQ_321","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_321","question":"Several major commercial banks now offer 'sustainability-linked loans' with lower interest rates to businesses that meet verified targets for cutting carbon emissions and water waste. How does this affect business decision-making?","options":{"A":"It creates a direct financial incentive to adopt sustainable practices by lowering the cost of borrowing capital","B":"It forces businesses to increase their carbon emissions to qualify for loans","C":"It eliminates the need to ever repay the loan principal","D":"It applies only to sole traders with zero employees"},"correctOption":"A","correctAnswer":"It creates a direct financial incentive to adopt sustainable practices by lowering the cost of borrowing capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cheaper access to finance rewards environmentally responsible businesses and improves the financial return on green projects.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because interest discounts are earned by *reducing*, not increasing, emissions.","C":"Incorrect because loans must still be repaid, just at a lower interest rate.","D":"Incorrect because sustainability-linked loans are widely used by medium and large companies."}}},{"id":"P1_U6_MCQ_322","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_322","question":"A supermarket chain discovers that 85% of its total carbon footprint comes not from its own stores, but from the farms and factories producing the food it sells. What is the most effective way for the supermarket to reduce its overall environmental impact?","options":{"A":"Collaborate with suppliers to set emission-reduction targets, support sustainable farming, and cut supply-chain packaging","B":"Turn off store refrigerators at night so fresh meat and milk spoil","C":"Stop selling all food items and sell only plastic toys","D":"Ignore supplier emissions because they happen outside the supermarket's own buildings"},"correctOption":"A","correctAnswer":"Collaborate with suppliers to set emission-reduction targets, support sustainable farming, and cut supply-chain packaging","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because addressing upstream supply-chain ('Scope 3') emissions targets the largest source of environmental impact in retail.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because spoiling perishable food increases food waste and violates hygiene laws.","C":"Incorrect because abandoning core grocery operations is commercially unrealistic.","D":"Incorrect because consumers and pressure groups hold retailers accountable for their supply chains."}}},{"id":"P1_U6_MCQ_323","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_323","question":"A microchip manufacturing plant requires millions of litres of ultra-pure water daily. During a severe regional drought, local authorities ration water supplies, forcing the plant to cut output by 30%. What does this demonstrate?","options":{"A":"Depletion and scarcity of natural resources can directly disrupt business production and reduce revenues","B":"Microchip factories can operate without any water or electricity","C":"Droughts always lower raw material and utility costs for manufacturers","D":"Water rationing increases factory output by 30%"},"correctOption":"A","correctAnswer":"Depletion and scarcity of natural resources can directly disrupt business production and reduce revenues","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because businesses depend on natural ecosystems and resources; environmental degradation and water scarcity create serious operational risks.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because semiconductor fabrication is heavily dependent on water and power.","C":"Incorrect because resource scarcity increases costs and restricts production.","D":"Incorrect because water rationing forced a 30% *cut* in output."}}},{"id":"P1_U6_MCQ_324","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_324","question":"According to the environmental waste hierarchy, why is 'preventing/reducing' packaging waste at the design stage better than 'recycling' used packaging?","options":{"A":"Preventing waste avoids using raw materials, manufacturing energy, and recycling transport/reprocessing energy altogether","B":"Recycling is illegal in most industrialised countries","C":"Preventing waste increases the amount of rubbish sent to landfill","D":"Recycling requires zero energy or collection vehicles"},"correctOption":"A","correctAnswer":"Preventing waste avoids using raw materials, manufacturing energy, and recycling transport/reprocessing energy altogether","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because while recycling is beneficial, collecting, sorting, and melting materials still consumes energy; using less material upfront saves the most resources.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recycling is legal and widely encouraged.","C":"Incorrect because reducing material usage decreases landfill waste.","D":"Incorrect because recycling processes require significant transport and industrial energy."}}},{"id":"P1_U6_MCQ_325","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_325","question":"A domestic cement manufacturer argues against a new national carbon tax, claiming foreign cement importers do not pay the tax and will capture the market. How can a government enforce green standards domestically without harming local firms' competitiveness?","options":{"A":"Apply an equivalent carbon border adjustment charge on imported cement from countries without carbon pricing","B":"Exempt domestic cement factories from all safety and pollution laws","C":"Ban all domestic construction projects permanently","D":"Subsidise foreign cement importers so their prices fall further"},"correctOption":"A","correctAnswer":"Apply an equivalent carbon border adjustment charge on imported cement from countries without carbon pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because charging an equivalent carbon fee on high-emission imports levels the playing field while maintaining incentives for cleaner production.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because removing domestic pollution laws abandons environmental protection.","C":"Incorrect because banning construction would destroy the domestic economy.","D":"Incorrect because subsidising foreign imports would worsen the disadvantage for local producers."}}},{"id":"P1_U6_MCQ_326","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_326","question":"Even though commercial contracts in Country A legally allow large retailers 90 days to pay invoices, a major department store commits to paying all small independent suppliers within 10 days. Why is this considered an ethical business practice?","options":{"A":"It goes beyond minimum legal rules to protect small suppliers' cash flow and survival","B":"It forces small suppliers to take out high-interest bank overdrafts","C":"It increases the department store's corporation tax rate","D":"It violates competition laws in Country A"},"correctOption":"A","correctAnswer":"It goes beyond minimum legal rules to protect small suppliers' cash flow and survival","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because using purchasing power fairly—rather than exploiting legal loopholes to delay payments—demonstrates ethical responsibility toward suppliers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fast payment gives suppliers cash quickly, *preventing* the need for overdrafts.","C":"Incorrect because paying suppliers promptly does not increase corporation tax rates.","D":"Incorrect because prompt payment is completely legal and encouraged."}}},{"id":"P1_U6_MCQ_327","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_327","question":"A tech consultancy provides six months of fully paid parental leave, confidential mental health counselling, and strict limits on after-hours emails, exceeding statutory employment laws. What is a key business benefit of these ethical HR policies?","options":{"A":"Lower stress-related absenteeism, higher staff loyalty, and stronger employee productivity","B":"Higher staff turnover and constant recruitment expenses","C":"Exemption from paying employee salaries during busy months","D":"Reduced customer trust in the consultancy's advice"},"correctOption":"A","correctAnswer":"Lower stress-related absenteeism, higher staff loyalty, and stronger employee productivity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because caring for employee wellbeing beyond legal minimums reduces burnout and turnover while boosting engagement and performance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supportive HR policies reduce, rather than increase, staff turnover.","C":"Incorrect because salaries must still be paid according to employment contracts.","D":"Incorrect because ethical treatment of employees enhances corporate reputation."}}},{"id":"P1_U6_MCQ_328","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_328","question":"A courier company classifies all its full-time delivery drivers as 'independent contractors' on zero-hours arrangements so it can avoid paying sick pay, holiday pay, and minimum-wage guarantees. How is this practice commonly evaluated?","options":{"A":"It may exploit legal grey areas to cut labour costs, but is widely criticised as unethical for shifting financial insecurity onto workers","B":"It is universally praised by trade unions as the most ethical employment model","C":"It guarantees drivers higher pensions and guaranteed weekly income","D":"It increases fixed salary overheads for the courier company"},"correctOption":"A","correctAnswer":"It may exploit legal grey areas to cut labour costs, but is widely criticised as unethical for shifting financial insecurity onto workers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because depriving regular workers of basic security and benefits through technical contract classifications raises major ethical concerns even where not yet banned.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade unions strongly oppose insecure gig/zero-hours exploitation.","C":"Incorrect because zero-hours contractor status removes guaranteed hours and paid leave.","D":"Incorrect because the firm uses this model specifically to *reduce* fixed labour costs."}}},{"id":"P1_U6_MCQ_329","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_329","question":"A cosmetics brand pledges never to digitally retouch models' skin in its skincare advertisements and clearly discloses when photos use studio lighting. Which aspect of business ethics does this demonstrate?","options":{"A":"Honest, transparent, and socially responsible marketing","B":"Predatory pricing against rival cosmetics brands","C":"Vertical backward integration","D":"Tariff avoidance in export markets"},"correctOption":"A","correctAnswer":"Honest, transparent, and socially responsible marketing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because avoiding deceptive digital manipulation respects consumers' right to truthful information and promotes healthy body image.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because advertising standards relate to promotion, not predatory pricing.","C":"Incorrect because vertical integration involves acquiring suppliers or distributors.","D":"Incorrect because marketing transparency is unrelated to customs tariffs."}}},{"id":"P1_U6_MCQ_330","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_330","question":"A consumer finance company refuses to offer high-interest short-term loans to borrowers who clearly cannot afford the repayments, even when doing so would generate high late-fee profits. Why is this an ethical lending policy?","options":{"A":"It protects vulnerable customers from falling into unmanageable debt spirals","B":"It forces borrowers to take out larger loans from illegal lenders","C":"It eliminates the finance company's need to check credit scores","D":"It increases the central bank's base interest rate"},"correctOption":"A","correctAnswer":"It protects vulnerable customers from falling into unmanageable debt spirals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because responsible lending avoids exploiting financially vulnerable people for short-term fee income.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because responsible lenders often signpost struggling applicants to free debt advice charities.","C":"Incorrect because affordability checks require *more* thorough credit assessment.","D":"Incorrect because individual lending decisions do not set central bank interest rates."}}},{"id":"P1_U6_MCQ_331","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_331","question":"After a severe hurricane knocks out power across a region, a hardware store chain keeps prices for bottled water, flashlights, and portable generators at their normal pre-storm levels instead of tripling them. Which unethical practice is the chain avoiding?","options":{"A":"Price gouging (exploiting emergencies to charge excessive prices for essentials)","B":"Penetration pricing","C":"Fairtrade sourcing","D":"Batch production"},"correctOption":"A","correctAnswer":"Price gouging (exploiting emergencies to charge excessive prices for essentials)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because exploiting disasters to profit from desperate families is widely condemned as unethical and destroys community goodwill.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because penetration pricing sets *low* prices to enter a new market.","C":"Incorrect because Fairtrade ensures fair minimum prices for farmers.","D":"Incorrect because batch production is an operations manufacturing method."}}},{"id":"P1_U6_MCQ_332","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_332","question":"A global tea brand funds protective clothing, health clinics, and clean drinking water for workers on the independent tea estates that supply its leaves. What is the main business rationale for this ethical supply-chain investment?","options":{"A":"It ensures a healthy, stable, and productive supply chain while protecting the brand from human rights scandals","B":"It reduces the retail price of tea to zero","C":"It exempts the tea brand from paying import tariffs","D":"It eliminates the need to package the tea leaves"},"correctOption":"A","correctAnswer":"It ensures a healthy, stable, and productive supply chain while protecting the brand from human rights scandals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because investing in supplier welfare secures reliable, high-quality agricultural output and strengthens brand reputation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tea is still sold commercially at a profit.","C":"Incorrect because supply-chain welfare programmes do not waive customs duties.","D":"Incorrect because finished tea still requires packaging for retail sale."}}},{"id":"P1_U6_MCQ_333","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_333","question":"A restaurant chain switches exclusively to free-range chicken and eggs, increasing its ingredient costs by 18%. Under what condition will this ethical change increase the chain's long-term net profit?","options":{"A":"If enough customers value animal welfare and are willing to visit more often or pay slightly higher menu prices","B":"If customers stop eating at the restaurant completely","C":"If the government doubles Value Added Tax on free-range meals","D":"If suppliers stop delivering eggs during weekends"},"correctOption":"A","correctAnswer":"If enough customers value animal welfare and are willing to visit more often or pay slightly higher menu prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher ethical input costs are profitable in the long run when increased customer loyalty and price premiums outweigh the extra ingredient expense.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because losing customers would reduce revenue and cause losses.","C":"Incorrect because higher taxes would reduce rather than increase net profit.","D":"Incorrect because supply disruptions would harm restaurant sales."}}},{"id":"P1_U6_MCQ_334","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_334","question":"A shipping company's perishable fruit cargo is held up at a foreign port, and a port official hints that an unofficial $500 'facilitation fee' in cash will clear the paperwork immediately. What does an ethical anti-corruption policy require?","options":{"A":"Refusing to pay the bribe and reporting the demand through official legal channels, even if the cargo is delayed","B":"Paying the $500 cash and hiding it under 'port fuel expenses'","C":"Offering $2,000 so future shipments bypass customs inspections entirely","D":"Telling the ship's captain to pay the bribe out of his own salary"},"correctOption":"A","correctAnswer":"Refusing to pay the bribe and reporting the demand through official legal channels, even if the cargo is delayed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical companies maintain zero tolerance for bribery and facilitation payments, even when refusing causes short-term operational inconvenience.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because falsifying accounting records to hide a bribe is illegal and unethical.","C":"Incorrect because escalating bribery deepens criminal corruption.","D":"Incorrect because passing unethical demands onto employees is unfair and still implicates the company."}}},{"id":"P1_U6_MCQ_335","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_335","question":"A purchasing manager at a manufacturing firm is offered a free luxury cruise by a supplier that is currently bidding for a $2 million packaging contract. Why does the company's ethical code prohibit accepting the gift?","options":{"A":"It creates a conflict of interest that could bias supplier selection away from the best value and quality for the company","B":"Cruises are illegal for business managers to take during annual leave","C":"Accepting gifts increases the company's corporation tax bill","D":"Suppliers are not allowed to bid for packaging contracts"},"correctOption":"A","correctAnswer":"It creates a conflict of interest that could bias supplier selection away from the best value and quality for the company","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because accepting expensive gifts from bidding suppliers compromises impartial, merit-based procurement decisions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because personal holidays are legal; the ethical issue is accepting favours from a bidding supplier.","C":"Incorrect because gift policies concern integrity rather than corporation tax calculations.","D":"Incorrect because suppliers legitimately bid for contracts based on price and quality."}}},{"id":"P1_U6_MCQ_336","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_336","question":"During a severe economic downturn, the Chief Executive and senior directors of an airline volunteer to take a 50% salary cut for one year so the airline can avoid cutting the pay of frontline cabin crew and baggage handlers. How does this ethical leadership affect the business?","options":{"A":"It builds immense staff trust, unity, and loyalty, motivating workers to deliver great service during recovery","B":"It causes frontline staff to go on strike immediately","C":"It forces the airline to sell all its airplanes","D":"It violates minimum wage legislation"},"correctOption":"A","correctAnswer":"It builds immense staff trust, unity, and loyalty, motivating workers to deliver great service during recovery","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shared sacrifice by senior leaders demonstrates fairness and earns strong employee commitment and goodwill.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because protecting frontline pay prevents industrial disputes rather than causing strikes.","C":"Incorrect because executive pay cuts save cash rather than forcing asset sales.","D":"Incorrect because senior executives still earn well above the legal minimum wage after a 50% cut."}}},{"id":"P1_U6_MCQ_337","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_337","question":"An engineering consultancy loses a lucrative overseas contract because it refuses to pay a bribe, but international development banks subsequently award it three larger contracts specifically because of its clean anti-corruption record. What does this show?","options":{"A":"Ethical behaviour may sacrifice short-term revenue but opens doors to higher-quality, long-term business opportunities","B":"Bribing officials is always the best way to win international development contracts","C":"Development banks prefer working with companies convicted of corruption","D":"Ethical consultancies never lose any contracts"},"correctOption":"A","correctAnswer":"Ethical behaviour may sacrifice short-term revenue but opens doors to higher-quality, long-term business opportunities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because institutional clients and reputable partners actively seek trustworthy suppliers, turning integrity into a long-term competitive advantage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because corruption blacklists firms from reputable global contracts.","C":"Incorrect because development banks strictly exclude corrupt contractors.","D":"Incorrect because the firm initially lost a contract before winning better ones later."}}},{"id":"P1_U6_MCQ_338","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_338","question":"Several major pension funds announce they will no longer invest in companies that produce tobacco or fail to meet human rights standards. How does this ethical investment trend pressure businesses?","options":{"A":"Unethical companies face falling share prices and higher costs of raising capital, encouraging directors to improve ethical standards","B":"Unethical companies receive free capital from pension funds","C":"Public limited companies no longer need shareholders","D":"Ethical companies are banned from listing shares on stock exchanges"},"correctOption":"A","correctAnswer":"Unethical companies face falling share prices and higher costs of raising capital, encouraging directors to improve ethical standards","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because institutional investors control vast sums of capital; divestment lowers share prices and restricts access to equity finance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pension funds withdraw capital from unethical companies rather than funding them.","C":"Incorrect because plcs rely on shareholders for equity finance.","D":"Incorrect because stock exchanges welcome ethical companies."}}},{"id":"P1_U6_MCQ_339","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_339","question":"An audit of a small garment factory supplying a global retailer reveals poor fire-exit signage and excessive overtime. Instead of immediately cancelling orders and putting 400 workers out of work, the retailer funds safety upgrades and trains factory managers. Why is this considered a highly ethical approach?","options":{"A":"It fixes the root causes of poor working conditions while protecting local workers' jobs and incomes","B":"It allows the retailer to ignore fire safety permanently","C":"It lowers the retailer's product quality standards","D":"It forces the factory to pay bribes to safety inspectors"},"correctOption":"A","correctAnswer":"It fixes the root causes of poor working conditions while protecting local workers' jobs and incomes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because collaborative remediation genuinely improves worker safety without destroying the livelihoods of vulnerable workers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because funding upgrades directly resolves the fire safety deficiencies.","C":"Incorrect because better-managed factories typically produce higher, more consistent quality.","D":"Incorrect because genuine safety improvements eliminate any need to bribe inspectors."}}},{"id":"P1_U6_MCQ_340","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_340","question":"A large retailer discovers that its automated résumé-screening software unfairly rejects qualified female and older applicants because it was trained on historical hiring data. What is the ethical response?","options":{"A":"Suspend the biased algorithm, audit the selection criteria, and ensure fair equal-opportunity hiring for all candidates","B":"Continue using the biased software because it saves HR managers time","C":"Stop hiring any new employees permanently","D":"Hide the discovery from senior management"},"correctOption":"A","correctAnswer":"Suspend the biased algorithm, audit the selection criteria, and ensure fair equal-opportunity hiring for all candidates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical human resource management requires eliminating unfair discrimination—whether human or algorithmic—to ensure equal opportunity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because administrative convenience does not justify unfair discrimination.","C":"Incorrect because businesses still need to recruit staff fairly.","D":"Incorrect because covering up discrimination breaches ethical and legal standards."}}},{"id":"P1_U6_MCQ_341","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_341","question":"A fast-fashion chain copies unique jacket patterns created by an independent young artist without permission or payment, selling thousands of cheap imitations. How is this practice viewed?","options":{"A":"Unethical intellectual property theft that exploits independent creators and harms brand integrity","B":"Ethical corporate social responsibility supporting local artists","C":"Fairtrade partnership marketing","D":"A legal way to increase the independent artist's profits"},"correctOption":"A","correctAnswer":"Unethical intellectual property theft that exploits independent creators and harms brand integrity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because appropriating original creative designs without licensing or credit is unethical and often infringes copyright/design laws.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because copying without payment harms rather than supports the artist.","C":"Incorrect because Fairtrade involves fair payment and consent.","D":"Incorrect because cheap imitations steal sales and profits away from the original creator."}}},{"id":"P1_U6_MCQ_342","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_342","question":"Before building a new logistics hub near a town with high youth unemployment, a company holds town-hall consultations with residents and partners with local colleges to offer 150 paid apprenticeships to local school leavers. What benefit does this bring?","options":{"A":"Strong community support, smooth planning approval, and a loyal locally trained workforce","B":"Increased local protests and consumer boycotts","C":"Higher staff recruitment costs from bringing in workers from abroad","D":"Exemption from paying local property taxes"},"correctOption":"A","correctAnswer":"Strong community support, smooth planning approval, and a loyal locally trained workforce","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because engaging respectfully with local communities and investing in local skills builds goodwill and reduces local opposition.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because creating local apprenticeships generates community support rather than protests.","C":"Incorrect because training local school leavers reduces reliance on expensive external recruitment.","D":"Incorrect because community programmes do not waive business property taxes."}}},{"id":"P1_U6_MCQ_343","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_343","question":"A toy manufacturer exports plastic building blocks to a developing country where safety warning labels are not required by law, yet still prints clear age-restriction warnings and uses non-toxic, BPA-free plastics. Why?","options":{"A":"Because ethical businesses apply consistent child-safety standards everywhere rather than lowering safety where laws are weak","B":"Because non-toxic plastics are banned in developing countries","C":"Because warning labels make toys cheaper to manufacture","D":"Because customs officials destroy any toys that have safety labels"},"correctOption":"A","correctAnswer":"Because ethical businesses apply consistent child-safety standards everywhere rather than lowering safety where laws are weak","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because moral responsibility for consumer safety applies equally to all customers worldwide regardless of local legal gaps.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because safe, non-toxic plastics are legal everywhere.","C":"Incorrect because higher-grade safe plastics and multi-language labels add slightly to unit costs.","D":"Incorrect because safety labels facilitate, rather than hinder, customs clearance."}}},{"id":"P1_U6_MCQ_344","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_344","question":"A global company writes a detailed ethical code of conduct, but managers still reward salespeople who lie to customers about product features to close deals. Why does the ethical code fail in practice?","options":{"A":"Because senior leaders must reinforce ethical rules through training, role modelling, and penalising dishonest behaviour","B":"Because ethical codes of conduct are illegal in sales departments","C":"Because lying to customers always builds long-term customer loyalty","D":"Because salespeople are exempt from following company policies"},"correctOption":"A","correctAnswer":"Because senior leaders must reinforce ethical rules through training, role modelling, and penalising dishonest behaviour","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a written code only shapes behaviour when management actively enforces it and aligns incentives with ethical conduct.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ethical codes are standard corporate governance tools.","C":"Incorrect because misleading customers destroys trust when the truth emerges.","D":"Incorrect because company codes apply to all staff, especially customer-facing sales teams."}}},{"id":"P1_U6_MCQ_345","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_345","question":"How does a socially and ethically responsible public limited company (plc) differ from a social enterprise?","options":{"A":"A plc's primary objective is still earning profit for shareholders while behaving ethically, whereas a social enterprise's primary objective is achieving a social or environmental mission","B":"A plc is not allowed to make any profit, whereas a social enterprise pays high dividends to stock market investors","C":"A social enterprise breaks employment laws, whereas a plc obeys them","D":"There is no difference in how their profits are distributed"},"correctOption":"A","correctAnswer":"A plc's primary objective is still earning profit for shareholders while behaving ethically, whereas a social enterprise's primary objective is achieving a social or environmental mission","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical plcs balance profit maximisation with moral standards, whereas social enterprises reinvest most surpluses directly into their social purpose.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses the primary financial structure of plcs and social enterprises.","C":"Incorrect because both types of organisation must obey employment laws.","D":"Incorrect because plcs distribute dividends to shareholders, while social enterprises reinvest surpluses into their social mission."}}},{"id":"P1_U6_MCQ_346","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_346","question":"After a social media company is fined for secretly selling teenagers' personal data to advertisers, top university computer science graduates turn down job offers from the firm. Which cost of unethical behaviour does this illustrate?","options":{"A":"Loss of employer reputation making it harder and more expensive to recruit skilled talent","B":"Lower corporation tax rates on technology profits","C":"Increased customer sign-ups from privacy-conscious teenagers","D":"Reduced server electricity expenses"},"correctOption":"A","correctAnswer":"Loss of employer reputation making it harder and more expensive to recruit skilled talent","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unethical scandals tarnish a firm's reputation among skilled professionals, creating recruitment and retention difficulties.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because privacy fines add costs rather than reducing corporation tax.","C":"Incorrect because privacy scandals drive users away rather than attracting them.","D":"Incorrect because ethical scandals do not reduce utility costs."}}},{"id":"P1_U6_MCQ_347","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_347","question":"A food company wants to pay higher Fairtrade prices to poor cocoa farmers, which requires raising chocolate prices by 20%, but low-income families can no longer afford its products. What does this dilemma highlight?","options":{"A":"Ethical obligations to one stakeholder group (suppliers) can sometimes conflict with affordability for another group (low-income consumers)","B":"Paying higher prices to farmers always lowers retail prices for shoppers","C":"Food companies are legally forbidden from paying fair prices to farmers","D":"Low-income consumers prefer paying higher prices for basic food"},"correctOption":"A","correctAnswer":"Ethical obligations to one stakeholder group (suppliers) can sometimes conflict with affordability for another group (low-income consumers)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers often have to balance competing ethical claims between fair producer incomes and affordable consumer prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher raw material costs push retail prices up unless absorbed by the firm.","C":"Incorrect because paying fair prices is completely legal.","D":"Incorrect because budget-conscious shoppers need affordable prices."}}},{"id":"P1_U6_MCQ_348","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_348","question":"An online retailer invests heavily in advanced encryption and promptly notifies customers within 24 hours when a minor software vulnerability is patched, even before any data is stolen. How does this ethical transparency help the retailer?","options":{"A":"It demonstrates honesty and respect for customer security, strengthening long-term trust in the brand","B":"It causes customers to cancel all their accounts immediately","C":"It eliminates the need to maintain a website","D":"It increases import tariffs on parcel deliveries"},"correctOption":"A","correctAnswer":"It demonstrates honesty and respect for customer security, strengthening long-term trust in the brand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because proactive security investment and open communication reassure customers that their personal and payment data is protected.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because proactive transparency builds trust, whereas covering up breaches causes customer flight.","C":"Incorrect because an online retailer depends on its website for sales.","D":"Incorrect because cybersecurity policies do not affect customs tariffs."}}},{"id":"P1_U6_MCQ_349","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_349","question":"In its annual Corporate Social Responsibility (CSR) report, an outdoor gear brand openly admits that while it achieved 100% recycled packaging, it missed its target for reducing air-freight emissions and explains its new plan to fix it. Why is admitting setbacks valuable?","options":{"A":"Honest reporting builds genuine credibility with consumers and NGOs rather than looking like polished public relations spin","B":"Admitting missed targets legally exempts the company from environmental laws","C":"Investors prefer companies that hide all operational problems","D":"It automatically lowers the cost of air freight by 50%"},"correctOption":"A","correctAnswer":"Honest reporting builds genuine credibility with consumers and NGOs rather than looking like polished public relations spin","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because transparent disclosure of both achievements and shortfalls proves authentic accountability and strengthens stakeholder trust.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because honest reporting does not exempt a firm from legal regulations.","C":"Incorrect because transparent risk disclosure builds investor confidence.","D":"Incorrect because reporting emissions does not reduce freight prices."}}},{"id":"P1_U6_MCQ_350","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_350","question":"When evaluating whether adopting strict ethical policies is always the best financial decision for a business, which conclusion is most accurate?","options":{"A":"Ethical behaviour usually enhances brand loyalty, staff retention, and long-term profit, though higher costs can hurt price competitiveness in purely price-driven markets","B":"Ethical behaviour always reduces operating costs immediately in every single industry","C":"Unethical businesses never make short-term profits and always go bankrupt within one month","D":"Ethical behaviour is only relevant to charities and has no impact on private sector businesses"},"correctOption":"A","correctAnswer":"Ethical behaviour usually enhances brand loyalty, staff retention, and long-term profit, though higher costs can hurt price competitiveness in purely price-driven markets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a balanced evaluation recognises both the strong long-term reputational/HR rewards of ethics and the short-term cost pressures in price-sensitive markets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fair wages and ethical sourcing frequently *increase* short-term costs.","C":"Incorrect because unethical firms can sometimes earn high short-term profits before facing scandals or regulation.","D":"Incorrect because ethical issues heavily affect private sector brands, investors, employees, and sales."}}},{"id":"P1_U6_MCQ_351","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_351","question":"A consumer rights organisation campaigns publicly against high-street banks charging hidden overdraft fees, urging regulators to ban the charges and publishing guides helping customers switch banks. What type of organisation is this?","options":{"A":"A consumer pressure group","B":"A commercial investment bank","C":"A multinational manufacturing company","D":"A central bank monetary committee"},"correctOption":"A","correctAnswer":"A consumer pressure group","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a consumer pressure group represents the interests of buyers and campaigns to stop unfair business practices and influence regulation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commercial banks are the profit-making businesses being campaigned against.","C":"Incorrect because it is a non-profit advocacy group, not a manufacturer.","D":"Incorrect because a central bank is a state monetary authority, not an external consumer campaign group."}}},{"id":"P1_U6_MCQ_352","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_352","question":"A health pressure group releases a widely reported study showing that a popular brand of children's fruit juice contains more sugar per glass than cola. What is the main purpose of publishing this research?","options":{"A":"To inform and alarm parents through media coverage, pressuring the manufacturer to cut sugar levels to protect its sales","B":"To advertise the fruit juice brand so its sales double","C":"To buy a controlling stake in the juice manufacturer","D":"To reduce government spending on public healthcare"},"correctOption":"A","correctAnswer":"To inform and alarm parents through media coverage, pressuring the manufacturer to cut sugar levels to protect its sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public awareness campaigns use credible research and media publicity to shift consumer perception and force companies to reformulate products.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because highlighting high sugar creates negative publicity, not free promotion.","C":"Incorrect because publishing health research does not involve purchasing company shares.","D":"Incorrect because the immediate goal is changing consumer behaviour and manufacturer recipes."}}},{"id":"P1_U6_MCQ_353","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_353","question":"An environmental group launches a 'Switch Off Brand X' boycott, asking drivers not to buy petrol from Brand X's service stations because Brand X cancelled its renewable energy investments. If 15% of drivers switch to rival petrol stations, how does this affect Brand X?","options":{"A":"Brand X suffers an immediate drop in sales revenue and market share, pressuring management to reconsider its strategy","B":"Brand X's fixed station rent and staff costs fall by 15% automatically","C":"Brand X is legally prohibited from lowering its petrol prices","D":"Rival petrol stations share their extra profits with Brand X"},"correctOption":"A","correctAnswer":"Brand X suffers an immediate drop in sales revenue and market share, pressuring management to reconsider its strategy","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because losing 15% of sales volume directly reduces revenue and profit while fixed station overheads remain unchanged.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed costs such as property leases and station staffing do not drop automatically when customers leave.","C":"Incorrect because Brand X can legally adjust prices, though a boycott is driven by ethical concerns.","D":"Incorrect because rival fuel retailers keep the sales gained from Brand X."}}},{"id":"P1_U6_MCQ_354","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_354","question":"Public health pressure groups spend two years meeting with Members of Parliament and health ministers, resulting in a new law taxing high-sugar soft drinks. Which pressure group method achieved this outcome?","options":{"A":"Political lobbying","B":"Workplace strike action","C":"Predatory pricing","D":"Hostile takeover"},"correctOption":"A","correctAnswer":"Political lobbying","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lobbying involves directly persuading lawmakers and government officials to pass legislation that changes business behaviour.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because strikes are work stoppages by employees/trade unions.","C":"Incorrect because predatory pricing is an anti-competitive business tactic.","D":"Incorrect because a takeover involves buying control of a company."}}},{"id":"P1_U6_MCQ_355","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_355","question":"A youth climate group collects 600,000 signatures on an online petition demanding that a major supermarket chain stop destroying unsold food and instead donate it to food banks. Why might the supermarket agree?","options":{"A":"600,000 signatures represent huge potential customer loss and media embarrassment if ignored, whereas donating surplus food creates positive publicity","B":"Online petitions legally force supermarket directors to resign within 48 hours","C":"Donating food to charities increases landfill disposal taxes","D":"Supermarkets are legally barred from speaking to charities"},"correctOption":"A","correctAnswer":"600,000 signatures represent huge potential customer loss and media embarrassment if ignored, whereas donating surplus food creates positive publicity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a massive petition signals widespread public concern and gives the business an opportunity to turn bad publicity into positive CSR.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because petitions carry public and moral weight, not automatic legal removal of directors.","C":"Incorrect because donating surplus food *reduces* waste sent to landfill.","D":"Incorrect because supermarkets regularly partner with food banks and charities."}}},{"id":"P1_U6_MCQ_356","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_356","question":"Activists stage a peaceful demonstration outside the annual shareholder conference of a major bank that lends billions of dollars to new coal mining projects. What are the activists hoping to achieve?","options":{"A":"To attract press attention and embarrass shareholders and executives into adopting greener lending policies","B":"To close down all personal bank accounts in the country by force","C":"To raise the central bank's base interest rate","D":"To help the bank sell more coal mining loans"},"correctOption":"A","correctAnswer":"To attract press attention and embarrass shareholders and executives into adopting greener lending policies","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because protesting at high-profile corporate events links the brand with controversy in financial media, pressuring executives and investors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because peaceful protests seek publicity and policy change, not physical closure of accounts.","C":"Incorrect because base interest rates are set by the central bank.","D":"Incorrect because the activists want the bank to *stop* financing coal projects."}}},{"id":"P1_U6_MCQ_357","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_357","question":"An ethical investment pressure group buys shares in a global clothing plc and submits a formal resolution at the Annual General Meeting (AGM) requiring the company to publish factory wages across its supply chain. How does this tactic work?","options":{"A":"It uses shareholder voting rights to force the Board of Directors to publicly debate and respond to ethical issues","B":"It stops all customers from entering the retailer's shops","C":"It forces the government to nationalise the clothing plc","D":"It eliminates the retailer's need to pay dividends"},"correctOption":"A","correctAnswer":"It uses shareholder voting rights to force the Board of Directors to publicly debate and respond to ethical issues","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholder activism leverages legal ownership rights at the AGM to attract institutional investor support and media scrutiny.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because AGM resolutions operate inside shareholder governance, not by blocking store doors.","C":"Incorrect because shareholder resolutions do not cause state nationalisation.","D":"Incorrect because dividend policy is separate from supply-chain wage disclosure."}}},{"id":"P1_U6_MCQ_358","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_358","question":"A wildlife conservation group campaigns against a cosmetics company using ingredients harvested from endangered rainforest habitats, featuring emotional images of endangered orangutans in national newspapers. Why is this campaign likely to be influential?","options":{"A":"Strong public sympathy and emotive media coverage create intense reputational pressure on the consumer brand","B":"Consumers never care about endangered wildlife","C":"Cosmetics companies do not rely on brand image to sell products","D":"Newspaper coverage is illegal for pressure groups"},"correctOption":"A","correctAnswer":"Strong public sympathy and emotive media coverage create intense reputational pressure on the consumer brand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because issues that evoke strong public sympathy and visual media interest quickly mobilise consumers against targeted brands.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wildlife conservation commands strong public sympathy.","C":"Incorrect because cosmetics rely heavily on positive brand image and aspirational marketing.","D":"Incorrect because media coverage is one of the primary legal channels used by pressure groups."}}},{"id":"P1_U6_MCQ_359","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_359","question":"A pressure group calls for a boycott of Brand A's coffee capsules because they are made of non-recyclable aluminium/plastic, while Brand B and Brand C sell fully compostable coffee capsules at the exact same price in the same supermarkets. Why is this boycott very likely to succeed?","options":{"A":"Close, affordable, eco-friendly substitutes are readily available, making it effortless for shoppers to switch brands","B":"Brand A has a complete legal monopoly over all coffee sales","C":"Supermarkets are forced to give away Brand A's capsules for free","D":"Compostable capsules are illegal to sell in supermarkets"},"correctOption":"A","correctAnswer":"Close, affordable, eco-friendly substitutes are readily available, making it effortless for shoppers to switch brands","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because boycotts achieve high participation when switching to a rival brand requires zero extra cost or inconvenience.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Brand B and Brand C provide direct competition.","C":"Incorrect because supermarkets do not give products away for free during a boycott.","D":"Incorrect because compostable capsules are legal and actively promoted."}}},{"id":"P1_U6_MCQ_360","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_360","question":"Why do well-established international NGOs (such as Greenpeace or Amnesty International) often succeed in changing multinational corporate behaviour where small local groups fail?","options":{"A":"They have global brand recognition, large memberships, financial resources, and coordinated campaigns across multiple countries simultaneously","B":"They are owned by the United Nations and have the power to imprison company CEOs","C":"They are permitted to break national laws in every country","D":"Multinational companies are legally required to obey all NGO demands within 24 hours"},"correctOption":"A","correctAnswer":"They have global brand recognition, large memberships, financial resources, and coordinated campaigns across multiple countries simultaneously","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because scale, funding, research expertise, and global media reach give major NGOs sustained leverage over multinational corporations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because NGOs are independent non-governmental bodies without judicial arrest powers.","C":"Incorrect because NGOs must operate within national laws.","D":"Incorrect because NGO influence works through reputational, consumer, and political pressure rather than automatic legal compulsion."}}},{"id":"P1_U6_MCQ_361","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_361","question":"A consumer pressure group urges citizens to boycott the sole private electricity grid company in a region over high executive bonuses. Why is this consumer boycott unlikely to succeed?","options":{"A":"The electricity grid company is a natural monopoly providing an essential service with no alternative supplier for households to switch to","B":"Households do not use electricity for lighting or heating","C":"Electricity companies never care about government regulation","D":"Consumer boycotts are illegal against utility companies"},"correctOption":"A","correctAnswer":"The electricity grid company is a natural monopoly providing an essential service with no alternative supplier for households to switch to","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumers cannot realistically stop buying an essential monopoly utility; instead, pressure groups must lobby the government regulator.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because electricity is an essential daily necessity.","C":"Incorrect because monopoly utilities are heavily influenced by government regulators, which is where pressure groups must focus.","D":"Incorrect because boycotts are not illegal; they are simply impractical without substitutes."}}},{"id":"P1_U6_MCQ_362","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_362","question":"During a severe economic recession, a pressure group calls on shoppers to boycott a budget discount clothing retailer and buy instead from expensive ethical boutiques. Why might the boycott have limited impact during the recession?","options":{"A":"Falling household disposable incomes force many shoppers to prioritise low prices over ethical campaign goals","B":"Discount clothing retailers are legally exempt from all consumer boycotts","C":"Ethical boutiques always sell clothes cheaper than discount retailers","D":"Shoppers stop wearing clothes during economic recessions"},"correctOption":"A","correctAnswer":"Falling household disposable incomes force many shoppers to prioritise low prices over ethical campaign goals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when consumer budgets are squeezed in a downturn, price sensitivity rises and fewer shoppers can afford expensive ethical alternatives.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no retailer is legally exempt from boycotts.","C":"Incorrect because ethical boutiques typically charge higher prices due to fair wages and organic materials.","D":"Incorrect because clothing remains a basic necessity, though shoppers buy cheaper items."}}},{"id":"P1_U6_MCQ_363","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_363","question":"A radical protest group blocks commuters from reaching work on morning trains and sprays paint on historic public monuments to protest against fossil fuels. Why can extreme tactics weaken a pressure group's influence?","options":{"A":"They alienate ordinary citizens and shift media focus from the environmental issue onto the protesters' disruptive behaviour","B":"They automatically force Parliament to pass every law the group demands","C":"They increase public sympathy among delayed commuters","D":"They lower the cost of renewable energy immediately"},"correctOption":"A","correctAnswer":"They alienate ordinary citizens and shift media focus from the environmental issue onto the protesters' disruptive behaviour","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because alienating the general public undermines the broad social support that gives pressure groups political and commercial leverage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because governments avoid rewarding disruptive or illegal protests.","C":"Incorrect because disrupting ordinary workers' commutes generates anger rather than sympathy.","D":"Incorrect because street protests do not lower energy engineering costs."}}},{"id":"P1_U6_MCQ_364","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_364","question":"After marine conservationists criticise a tuna fishing company for accidentally trapping dolphins in its nets, the company works with the pressure group to adopt dolphin-safe nets and puts the group's certification logo on its cans. What is the result?","options":{"A":"A win-win outcome: dolphin deaths drop dramatically and the company gains stronger brand reputation and higher sales","B":"The fishing company goes bankrupt because consumers hate dolphin-safe tuna","C":"The pressure group takes over ownership of all fishing boats","D":"Tuna cans become illegal to sell in supermarkets"},"correctOption":"A","correctAnswer":"A win-win outcome: dolphin deaths drop dramatically and the company gains stronger brand reputation and higher sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because constructive cooperation turns pressure group scrutiny into an endorsed competitive advantage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumers strongly prefer certified dolphin-safe tuna.","C":"Incorrect because the pressure group certifies the standard rather than owning the business.","D":"Incorrect because certified tuna is welcomed by supermarkets and shoppers."}}},{"id":"P1_U6_MCQ_365","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_365","question":"A coffee chain is criticised online by a pressure group for using disposable paper cups, even though the chain already offers a $0.50 discount to customers bringing reusable mugs and recycles 100% of its cups in-store. How should the chain respond?","options":{"A":"Use public relations and social media to clearly publicise its existing recycling scheme and reusable-cup discount","B":"Cancel its reusable-cup discount and stop recycling cups","C":"Close all its coffee shops permanently","D":"Sue its own customers for buying coffee"},"correctOption":"A","correctAnswer":"Use public relations and social media to clearly publicise its existing recycling scheme and reusable-cup discount","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because effective PR communicates genuine sustainability initiatives to correct public misconceptions and protect brand image.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because abandoning existing green initiatives would worsen environmental impact and criticism.","C":"Incorrect because closing stores is an extreme and unnecessary reaction.","D":"Incorrect because attacking customers would destroy the business."}}},{"id":"P1_U6_MCQ_366","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_366","question":"Following pressure group campaigns warning that tiny plastic microbeads in facial scrubs pollute oceans and enter the food chain, major cosmetics firms voluntarily replace microbeads with natural ground apricot seeds before any law is passed. Why?","options":{"A":"To protect brand reputation, satisfy eco-conscious shoppers, and stay ahead of inevitable government bans","B":"Because ground apricot seeds are illegal in cosmetics","C":"Because pressure groups paid the cosmetics firms' R&D budgets","D":"To increase ocean plastic pollution"},"correctOption":"A","correctAnswer":"To protect brand reputation, satisfy eco-conscious shoppers, and stay ahead of inevitable government bans","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because proactive product reformulation avoids consumer boycotts and positions brands ahead of upcoming regulatory restrictions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because natural exfoliants like apricot seeds are safe and legal.","C":"Incorrect because companies fund their own product reformulation.","D":"Incorrect because replacing plastic microbeads *reduces* ocean plastic pollution."}}},{"id":"P1_U6_MCQ_367","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_367","question":"A three-person protest group stands outside a regional quarry demanding the quarry close permanently, even though the quarry obeys all environmental laws and employs 200 local residents. Why will the quarry owner likely ignore this demand?","options":{"A":"The tiny group has minimal public support and no realistic way to harm the quarry's business-to-business sales, whereas closing would destroy 200 jobs","B":"Quarry owners are legally forbidden from speaking to the public","C":"Quarries do not need any customers to survive","D":"Environmental laws prohibit closing quarries"},"correctOption":"A","correctAnswer":"The tiny group has minimal public support and no realistic way to harm the quarry's business-to-business sales, whereas closing would destroy 200 jobs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers evaluate the credibility and commercial impact of pressure group actions; a tiny, unrepresentative group poses negligible risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quarry owners can communicate publicly whenever needed.","C":"Incorrect because quarries rely on construction customers, who are unaffected by three protesters.","D":"Incorrect because owners can close a business commercially, though there is no reason to do so here."}}},{"id":"P1_U6_MCQ_368","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_368","question":"When health pressure groups lobby the government to ban all advertising of confectionery and snacks, the Food Manufacturers' Trade Association submits economic research to ministers arguing for targeted restrictions on children's TV only. What is the trade association doing?","options":{"A":"Lobbying the government on behalf of member businesses to achieve a more balanced, commercially workable regulation","B":"Organising a consumer boycott of all supermarkets","C":"Setting central bank interest rates","D":"Acting as an environmental conservation charity"},"correctOption":"A","correctAnswer":"Lobbying the government on behalf of member businesses to achieve a more balanced, commercially workable regulation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because business trade associations represent industry interests in policy debates to counter total bans with compromise regulations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because food manufacturers want consumers to buy snacks, not boycott supermarkets.","C":"Incorrect because central banks manage interest rates.","D":"Incorrect because trade associations represent commercial businesses, not environmental charities."}}},{"id":"P1_U6_MCQ_369","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_369","question":"In response to sustained pressure group campaigns, a chocolate manufacturer switches to certified fair-trade cocoa, recyclable paper wrappers, and independent supply-chain audits. What is the immediate impact on the firm's unit costs?","options":{"A":"Unit production and administrative costs increase, which may squeeze profit margins unless retail prices or sales volumes rise","B":"Unit production costs fall by 50% immediately","C":"All factory labour costs are eliminated","D":"Corporation tax drops to 0%"},"correctOption":"A","correctAnswer":"Unit production and administrative costs increase, which may squeeze profit margins unless retail prices or sales volumes rise","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because meeting pressure group standards for ethical sourcing, sustainable packaging, and auditing adds direct and overhead expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ethical ingredients, eco-packaging, and audits raise rather than lower unit costs.","C":"Incorrect because factory workers are still needed to make the chocolate.","D":"Incorrect because corporate taxes still apply to profits."}}},{"id":"P1_U6_MCQ_370","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_370","question":"How can pressure group activity cause both a threat and an opportunity for different businesses in the same industry?","options":{"A":"Polluting or unethical market leaders lose sales from boycotts, while smaller eco-friendly rivals gain market share from ethically motivated shoppers","B":"All businesses in the industry lose 100% of their customers simultaneously","C":"Pressure groups legally ban all businesses from selling products","D":"Both ethical and unethical businesses receive identical government fines"},"correctOption":"A","correctAnswer":"Polluting or unethical market leaders lose sales from boycotts, while smaller eco-friendly rivals gain market share from ethically motivated shoppers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pressure groups shift consumer preferences away from irresponsible firms toward responsible competitors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumers switch brands rather than abandoning the entire product category.","C":"Incorrect because pressure groups do not have legal power to ban industries.","D":"Incorrect because ethical competitors are praised rather than fined."}}},{"id":"P1_U6_MCQ_371","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_371","question":"After a human rights pressure group publishes a report linking a major fashion plc to forced labour in its cotton supply chain, several large institutional investors sell millions of the company's shares. What is the immediate effect on the fashion plc?","options":{"A":"Its share price falls, reducing the market value of the company and making it harder to raise equity finance","B":"Its share price doubles because more shares are available to buy","C":"Its bank loans are automatically forgiven","D":"It becomes a private sole trader immediately"},"correctOption":"A","correctAnswer":"Its share price falls, reducing the market value of the company and making it harder to raise equity finance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because heavy selling of shares driven by ethical and reputational risk depresses the company's share price on the stock exchange.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because heavy selling pressure lowers, rather than doubles, share prices.","C":"Incorrect because debt obligations remain unaffected by share sell-offs.","D":"Incorrect because share trading on the stock market does not turn a plc into a sole trader."}}},{"id":"P1_U6_MCQ_372","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_372","question":"When an online video platform refuses to remove dangerous misinformation, a consumer pressure group contacts major household brands and persuades them to pause their paid adverts on the platform. Why is this indirect tactic so effective?","options":{"A":"Advertising revenue is the platform's main income source, so losing major advertisers threatens its profits and forces policy changes","B":"Pressure groups own all television and online advertising agencies","C":"Online platforms do not care about earning advertising revenue","D":"Advertising on the internet is illegal in all countries"},"correctOption":"A","correctAnswer":"Advertising revenue is the platform's main income source, so losing major advertisers threatens its profits and forces policy changes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because household brands fear brand association with harmful content, and pulling ad spend hits the platform's primary revenue stream.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pressure groups persuade independent advertisers rather than owning agencies.","C":"Incorrect because ad-supported digital platforms depend heavily on advertising income.","D":"Incorrect because online advertising is legal and huge globally."}}},{"id":"P1_U6_MCQ_373","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_373","question":"A local neighbourhood group campaigns against a nightclub's application for a 4:00 AM music licence, while a national health charity campaigns for warning labels on all alcoholic drinks sold nationwide. What is the key difference between these two pressure groups?","options":{"A":"The neighbourhood group seeks a localised planning decision affecting one venue, whereas the national charity seeks nationwide regulatory change across an entire industry","B":"The neighbourhood group is a profit-seeking plc, whereas the national charity is a government ministry","C":"The national charity relies on illegal vandalism, whereas the neighbourhood group sets interest rates","D":"Only national charities are allowed to submit petitions"},"correctOption":"A","correctAnswer":"The neighbourhood group seeks a localised planning decision affecting one venue, whereas the national charity seeks nationwide regulatory change across an entire industry","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pressure groups vary in scale from local community associations targeting single sites to national organisations influencing broad legislation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both are non-profit pressure groups, not a plc or a government ministry.","C":"Incorrect because neither relies on vandalism or controls monetary policy.","D":"Incorrect because local resident groups frequently use petitions in local council planning."}}},{"id":"P1_U6_MCQ_374","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_374","question":"An environmental pressure group campaigns to halt offshore oil drilling to protect marine ecosystems and future generations, while oil workers and shareholders support drilling to preserve jobs and dividends. What does this illustrate?","options":{"A":"Pressure groups voice the interests of external and future stakeholders who lack direct voting power inside the company","B":"Oil workers and environmental pressure groups always share identical short-term goals","C":"Shareholders have no financial interest in company dividends","D":"Offshore oil drilling has zero impact on marine environments"},"correctOption":"A","correctAnswer":"Pressure groups voice the interests of external and future stakeholders who lack direct voting power inside the company","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because wildlife and future generations cannot vote at AGMs or bargain like unions, so pressure groups advocate on their behalf.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because oil workers' immediate employment goals often clash with environmental campaigns to end drilling.","C":"Incorrect because shareholders invest in companies expecting dividend returns and capital growth.","D":"Incorrect because offshore drilling carries ecological and carbon risks."}}},{"id":"P1_U6_MCQ_375","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_375","question":"Which statement provides the best overall evaluation of pressure groups as an external influence on business activity?","options":{"A":"Although pressure groups lack direct legal authority, their ability to mobilise consumers, media, investors, and lawmakers makes them a powerful force pushing businesses toward ethical and sustainable behaviour","B":"Pressure groups have complete legal power to shut down any private business without a court hearing","C":"Pressure groups have zero influence on modern businesses because consumers never care about ethics or the environment","D":"Pressure groups only exist in command economies where there are no private sector businesses"},"correctOption":"A","correctAnswer":"Although pressure groups lack direct legal authority, their ability to mobilise consumers, media, investors, and lawmakers makes them a powerful force pushing businesses toward ethical and sustainable behaviour","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pressure groups exercise indirect influence through reputation, sales boycotts, investor pressure, and political lobbying rather than direct legal powers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pressure groups cannot unilaterally shut down businesses by law.","C":"Incorrect because many major corporations have altered products and supply chains due to pressure group campaigns.","D":"Incorrect because independent pressure groups thrive in democratic mixed economies."}}},{"id":"P1_U6_MCQ_376","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_376","question":"During an economic boom in Country A, unemployment falls to 2.5% and factories operate at 98% capacity. What recruitment challenge is a rapidly expanding logistics company most likely to face?","options":{"A":"An oversupply of experienced lorry drivers willing to work for minimum wage","B":"Severe skill shortages and upward pressure on wages to attract and retain drivers","C":"A legal ban on hiring new full-time employees during a boom","D":"Falling demand for parcel deliveries across the country"},"correctOption":"B","correctAnswer":"Severe skill shortages and upward pressure on wages to attract and retain drivers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because near-full employment during a boom shrinks the pool of available workers, forcing firms to offer higher pay and benefits to recruit staff.","distractor_reasons":{"A":"Incorrect because labour is scarce during a boom, not oversupplied.","B":"Correct selection.","C":"Incorrect because governments do not ban hiring during an economic boom.","D":"Incorrect because consumer and business spending—and therefore deliveries—surge during a boom."}}},{"id":"P1_U6_MCQ_377","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_377","question":"Country B enters a recession after two consecutive quarters of falling GDP. Which consumer product is most likely to experience an increase in sales volume as shoppers adjust their budgets?","options":{"A":"Luxury Swiss mechanical watches","B":"Long-haul first-class airline tickets","C":"Supermarket own-brand dried pasta and canned beans","D":"Bespoke designer evening gowns"},"correctOption":"C","correctAnswer":"Supermarket own-brand dried pasta and canned beans","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because falling real incomes during a recession cause consumers to trade down from expensive brands and restaurant meals to low-cost staple foods.","distractor_reasons":{"A":"Incorrect because luxury watches are non-essential big-ticket items whose demand drops sharply in a recession.","B":"Incorrect because businesses and households cut expensive air travel during downturns.","C":"Correct selection.","D":"Incorrect because high-end fashion purchases are postponed when incomes fall."}}},{"id":"P1_U6_MCQ_378","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_378","question":"A commercial real estate developer owns several half-empty shopping malls during a deep economic slump. Why are property developers particularly vulnerable during a slump?","options":{"A":"Retailers go bankrupt and cancel leases, while the developer still owes large fixed loan interest payments","B":"Construction material costs always triple during a slump","C":"Governments confiscate all empty shopping malls without compensation","D":"Interest rates always rise to 25% during a slump"},"correctOption":"A","correctAnswer":"Retailers go bankrupt and cancel leases, while the developer still owes large fixed loan interest payments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because real estate projects rely heavily on borrowed capital with high fixed interest charges, while tenant defaults slash rental inflows in a slump.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because weak construction demand usually lowers material prices during a slump.","C":"Incorrect because private property rights remain protected during downturns.","D":"Incorrect because central banks cut interest rates during a slump to stimulate recovery."}}},{"id":"P1_U6_MCQ_379","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_379","question":"Annual inflation in Country C rises from 2% to 11%. Why does high inflation make long-term investment planning difficult for a manufacturing business?","options":{"A":"It becomes much harder to forecast future raw material costs, wage demands, and project profitability accurately","B":"All business bank loans are automatically cancelled when inflation exceeds 10%","C":"Customers always buy twice as many luxury goods when prices rise rapidly","D":"Export prices become 11% cheaper in foreign currencies automatically"},"correctOption":"A","correctAnswer":"It becomes much harder to forecast future raw material costs, wage demands, and project profitability accurately","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid, unpredictable price and wage rises create uncertainty over future costs and real returns, deterring capital investment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because loan contracts remain legally binding.","C":"Incorrect because high inflation erodes real purchasing power and reduces discretionary spending.","D":"Incorrect because higher domestic inflation makes exports *more expensive*, not cheaper."}}},{"id":"P1_U6_MCQ_380","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_380","question":"A chain of print-and-mail marketing agencies faces a steady decline in demand as businesses switch to digital social media advertising, leading to redundancies among print machine operators. Which type of unemployment does this illustrate?","options":{"A":"Seasonal unemployment","B":"Structural unemployment caused by long-term technological and industry change","C":"Frictional unemployment caused by workers voluntarily taking a one-week holiday","D":"Cyclical unemployment caused solely by a temporary winter storm"},"correctOption":"B","correctAnswer":"Structural unemployment caused by long-term technological and industry change","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because permanent shifts in technology and consumer habits shrink traditional industries and leave workers with outdated skills.","distractor_reasons":{"A":"Incorrect because the decline in print advertising is permanent, not tied to seasons of the year.","B":"Correct selection.","C":"Incorrect because workers were made redundant due to industry decline, not brief job transitions.","D":"Incorrect because weather disruptions do not explain long-term digital substitution."}}},{"id":"P1_U6_MCQ_381","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_381","question":"Why do most governments aim for a low, stable inflation rate of around 2% rather than 0% or falling prices (deflation)?","options":{"A":"Mild inflation encourages consumers to spend now rather than delay purchases, and allows businesses to adjust real wages smoothly","B":"Mild inflation eliminates the need for businesses to pay corporation tax","C":"Falling prices always increase business profits and worker wages","D":"A 2% inflation rate guarantees zero unemployment"},"correctOption":"A","correctAnswer":"Mild inflation encourages consumers to spend now rather than delay purchases, and allows businesses to adjust real wages smoothly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because low, predictable inflation supports steady consumer spending and business pricing confidence without causing a deflationary slump.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses still pay corporation tax on profits regardless of inflation.","C":"Incorrect because falling prices (deflation) squeeze business margins and cause shoppers to postpone buying.","D":"Incorrect because some frictional and structural unemployment always exists."}}},{"id":"P1_U6_MCQ_382","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_382","question":"Country D's Gross Domestic Product (GDP) falls from $600 billion to $582 billion over a year. What is the percentage change in GDP?","options":{"A":"+3.0%","B":"-18.0%","C":"-3.0%","D":"-0.3%"},"correctOption":"C","correctAnswer":"-3.0%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because GDP fell by $18 billion ($582bn - $600bn = -$18bn), and (-$18bn ÷ $600bn) × 100 = -3.0%.","distractor_reasons":{"A":"Incorrect because GDP decreased rather than increased.","B":"Incorrect because -$18 billion is the dollar fall, not the percentage change.","C":"Correct selection.","D":"Incorrect because 18 ÷ 600 = 0.03, which is 3.0%, not 0.3%."}}},{"id":"P1_U6_MCQ_383","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_383","question":"Country E records $95 billion in exports of goods and services and $120 billion in imports of goods and services during the year. What is Country E's trade balance on the current account?","options":{"A":"A surplus of $25 billion","B":"A deficit of $25 billion","C":"A surplus of $215 billion","D":"A balanced current account of $0"},"correctOption":"B","correctAnswer":"A deficit of $25 billion","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because export earnings ($95bn) minus import expenditure ($120bn) equals -$25 billion, which is a current account trade deficit.","distractor_reasons":{"A":"Incorrect because imports exceed exports, creating a deficit rather than a surplus.","B":"Correct selection.","C":"Incorrect because $215 billion adds exports and imports instead of finding the net balance.","D":"Incorrect because exports and imports are not equal."}}},{"id":"P1_U6_MCQ_384","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_384","question":"A government cuts the basic rate of personal income tax from 20% to 16% to stimulate economic activity. How does this policy affect a domestic chain of mid-range family restaurants?","options":{"A":"Households have higher disposable income, increasing spending on eating out and boosting restaurant revenue","B":"Restaurant corporation tax increases by 4% automatically","C":"Restaurants must lower their menu prices by 4% by law","D":"Restaurant kitchen staff immediately receive 4% lower gross wages"},"correctOption":"A","correctAnswer":"Households have higher disposable income, increasing spending on eating out and boosting restaurant revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lower personal income tax leaves workers with more take-home pay to spend on leisure and dining out.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because personal income tax is separate from corporation tax on company profits.","C":"Incorrect because income tax cuts do not legally force restaurants to cut menu prices.","D":"Incorrect because gross wages remain unchanged while workers' net take-home pay rises."}}},{"id":"P1_U6_MCQ_385","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_385","question":"A limited company earns $250,000 in net profit before tax. If the government lowers the corporation tax rate from 24% to 20%, how much extra post-tax profit does the company retain?","options":{"A":"$4,000","B":"$10,000","C":"$50,000","D":"$60,000"},"correctOption":"B","correctAnswer":"$10,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because tax falls from $60,000 (24% of $250,000) to $50,000 (20% of $250,000), leaving the company with $10,000 more retained profit.","distractor_reasons":{"A":"Incorrect because 4% of $250,000 is $10,000, not $4,000.","B":"Correct selection.","C":"Incorrect because $50,000 is the new total tax bill, not the tax saving.","D":"Incorrect because $60,000 was the old tax bill before the rate cut."}}},{"id":"P1_U6_MCQ_386","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_386","question":"The government raises Value Added Tax (VAT) from 15% to 20% on all non-essential consumer goods. A clothing retailer decides to absorb the entire tax increase itself rather than raising shelf prices. What is the immediate effect on the retailer?","options":{"A":"Its sales volume is protected from price-sensitive shoppers, but its profit margin per garment falls","B":"Its profit margin per garment rises by 5%","C":"Customers pay 5% more at the checkout","D":"The retailer no longer has to pay VAT to the tax authority"},"correctOption":"A","correctAnswer":"Its sales volume is protected from price-sensitive shoppers, but its profit margin per garment falls","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because keeping retail prices unchanged preserves customer demand, but paying higher tax out of the same selling price reduces unit profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because absorbing a tax rise reduces, rather than increases, profit margins.","C":"Incorrect because the retailer chose not to raise shelf prices.","D":"Incorrect because the retailer is still legally required to remit the 20% VAT collected."}}},{"id":"P1_U6_MCQ_387","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_387","question":"To reduce traffic congestion and healthcare costs, a government imposes a heavy specific excise duty on cigarettes and alcohol. Which business is most directly affected?","options":{"A":"A domestic brewery and tobacco manufacturer facing higher retail prices and lower sales volumes","B":"A manufacturer of children's wooden toys","C":"A software company selling accounting apps to schools","D":"A domestic wind turbine installation firm"},"correctOption":"A","correctAnswer":"A domestic brewery and tobacco manufacturer facing higher retail prices and lower sales volumes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because excise duties are targeted indirect taxes levied on specific demerit goods such as alcohol and tobacco.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because excise taxes on alcohol and tobacco do not apply to children's toys.","C":"Incorrect because educational software is unaffected by tobacco and alcohol duties.","D":"Incorrect because renewable energy firms are not taxed by alcohol/tobacco excise duties."}}},{"id":"P1_U6_MCQ_388","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_388","question":"A government announces a $15 billion public infrastructure programme to build new high-speed railways, bridges, and regional hospitals. Which businesses benefit first from this fiscal spending?","options":{"A":"Civil engineering contractors, steel producers, and cement suppliers winning government construction contracts","B":"Overseas luxury cruise operators","C":"Foreign currency exchange bureaus at international airports","D":"Private tutoring agencies for primary school pupils"},"correctOption":"A","correctAnswer":"Civil engineering contractors, steel producers, and cement suppliers winning government construction contracts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public capital expenditure on transport and hospitals flows directly into construction, engineering, and building-material businesses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because domestic infrastructure contracts do not go to overseas cruise lines.","C":"Incorrect because currency bureaus are unaffected by domestic hospital construction.","D":"Incorrect because infrastructure building does not directly fund private tutoring firms."}}},{"id":"P1_U6_MCQ_389","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_389","question":"Why does increased government spending on state universities, technical colleges, and vocational apprenticeships benefit private sector employers in the long term?","options":{"A":"It expands the supply of skilled, productive workers, reducing business training costs and boosting innovation","B":"It lowers the central bank's base interest rate immediately","C":"It eliminates all minimum wage regulations for graduates","D":"It forces graduates to work without pay for private companies"},"correctOption":"A","correctAnswer":"It expands the supply of skilled, productive workers, reducing business training costs and boosting innovation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public investment in education and skills raises human capital and labour productivity across the economy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because education spending is fiscal policy and does not set monetary interest rates.","C":"Incorrect because minimum wage laws still protect all employees.","D":"Incorrect because graduates are paid market salaries."}}},{"id":"P1_U6_MCQ_390","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_390","question":"A housebuilding company relies on customers taking out 25-year bank mortgages to buy new homes. When the central bank raises interest rates from 3% to 7%, what happens to the housebuilder?","options":{"A":"Monthly mortgage repayments become much more expensive, causing homebuyer demand and house sales to fall","B":"Mortgages become cheaper, causing house prices to double overnight","C":"Brick and timber costs fall by 4% automatically","D":"The housebuilder receives a government grant for every unsold house"},"correctOption":"A","correctAnswer":"Monthly mortgage repayments become much more expensive, causing homebuyer demand and house sales to fall","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher interest rates sharply raise monthly mortgage costs, pricing many buyers out of the housing market.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher interest rates make mortgages *more expensive*, not cheaper.","C":"Incorrect because interest rate hikes do not automatically cut raw material costs.","D":"Incorrect because governments do not automatically subsidise unsold private homes."}}},{"id":"P1_U6_MCQ_391","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_391","question":"A packaging manufacturer plans to borrow $1,000,000 to buy an automated folding machine expected to generate $75,000 in annual extra profit. If the bank loan interest rate rises from 5% to 9% per year, what should the manufacturer decide?","options":{"A":"Postpone or cancel the investment because annual loan interest ($90,000) now exceeds the expected annual profit ($75,000)","B":"Proceed immediately because $90,000 in interest is less than $75,000 in profit","C":"Borrow $2,000,000 instead to double the interest expense","D":"Ignore the interest rate because bank loans do not require interest payments"},"correctOption":"A","correctAnswer":"Postpone or cancel the investment because annual loan interest ($90,000) now exceeds the expected annual profit ($75,000)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at 9% interest, annual financing cost ($90,000) exceeds the $75,000 return, making the debt-financed investment loss-making.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $90,000 is greater than $75,000, resulting in a net loss of $15,000 per year.","C":"Incorrect because borrowing more at 9% would double the net loss.","D":"Incorrect because interest is a mandatory cost of bank borrowing."}}},{"id":"P1_U6_MCQ_392","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_392","question":"Why do central banks usually raise interest rates when inflation climbs far above target?","options":{"A":"Higher interest rates discourage borrowing, encourage saving, and cool down excessive consumer and business spending","B":"Higher interest rates encourage households to borrow more money and spend faster","C":"Higher interest rates directly cut government income tax rates","D":"Higher interest rates force supermarkets to give away groceries for free"},"correctOption":"A","correctAnswer":"Higher interest rates discourage borrowing, encourage saving, and cool down excessive consumer and business spending","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because raising the cost of borrowing and the reward for saving reduces aggregate demand, easing inflationary pressure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because expensive credit discourages rather than encourages borrowing.","C":"Incorrect because tax rates are set by the government's fiscal budget, not the central bank.","D":"Incorrect because interest rates influence borrowing costs, not mandatory free food."}}},{"id":"P1_U6_MCQ_393","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_393","question":"A supermarket chain relies heavily on a short-term bank overdraft to pay suppliers before customers buy groceries. How does a sharp rise in interest rates affect this supermarket?","options":{"A":"Its daily overdraft interest charges rise immediately, increasing working capital financing costs","B":"Overdrafts are exempt from interest rate changes by law","C":"Suppliers must give the supermarket an extra 12 months of free credit","D":"Customer spending on luxury supermarket items doubles"},"correctOption":"A","correctAnswer":"Its daily overdraft interest charges rise immediately, increasing working capital financing costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bank overdrafts carry variable interest rates that adjust almost immediately when central bank rates rise.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overdrafts are variable-rate facilities and among the first to become more expensive.","C":"Incorrect because suppliers also face higher financing costs and often tighten credit terms.","D":"Incorrect because higher interest rates squeeze household budgets and reduce luxury spending."}}},{"id":"P1_U6_MCQ_394","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_394","question":"In Country F, the government cuts corporation tax to attract investment, while at the same time the central bank raises interest rates sharply to fight inflation. Why is the overall impact on business investment uncertain?","options":{"A":"Lower corporation tax increases after-tax returns, but higher interest rates raise borrowing costs and dampen consumer demand","B":"Both policies reduce business costs to zero","C":"Businesses are legally forbidden from investing when taxes are cut","D":"Interest rates never affect businesses that pay corporation tax"},"correctOption":"A","correctAnswer":"Lower corporation tax increases after-tax returns, but higher interest rates raise borrowing costs and dampen consumer demand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expansionary tax cuts and contractionary interest rate hikes pull business investment incentives in opposite directions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher interest rates increase borrowing costs.","C":"Incorrect because tax cuts are designed to encourage investment.","D":"Incorrect because loan-financed firms are directly affected by interest rate increases."}}},{"id":"P1_U6_MCQ_395","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_395","question":"A manufacturing firm wants to raise $5 million for factory expansion during a period of very high bank interest rates. How can it raise long-term capital without paying high annual loan interest?","options":{"A":"Issue new shares (equity finance) or use retained profits from previous years","B":"Use a high-interest bank overdraft for five years","C":"Take out multiple short-term payday loans","D":"Stop paying employee wages for six months"},"correctOption":"A","correctAnswer":"Issue new shares (equity finance) or use retained profits from previous years","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profits incur no interest charges and equity share issues do not require fixed interest payments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overdrafts carry very high variable interest rates.","C":"Incorrect because short-term loans carry extreme interest costs and are unsuitable for factory expansion.","D":"Incorrect because withholding earned wages is illegal and causes immediate strikes."}}},{"id":"P1_U6_MCQ_396","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_396","question":"During a recession, a hotel chain notices that corporate business travel bookings have fallen by 45%, while weekend leisure stays by domestic families have fallen by only 5%. Which marketing adjustment makes the best strategic sense?","options":{"A":"Launch discounted weekend family break packages and family-friendly amenities to capture domestic leisure demand","B":"Double room rates for corporate conferences immediately","C":"Close all hotels on weekends and open only on Tuesdays","D":"Stop advertising completely until the recession ends"},"correctOption":"A","correctAnswer":"Launch discounted weekend family break packages and family-friendly amenities to capture domestic leisure demand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because targeting the more resilient domestic leisure segment helps maintain hotel occupancy and cash flow during a downturn.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raising prices in a collapsing corporate segment would lose the remaining bookings.","C":"Incorrect because weekends are the strongest demand period in this scenario.","D":"Incorrect because targeted promotional offers are needed to attract budget-conscious holidaymakers."}}},{"id":"P1_U6_MCQ_397","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_397","question":"A government raises the statutory national minimum wage by 12% during a period of low economic growth. Which business is likely to experience the biggest percentage increase in its total operating costs?","options":{"A":"A labour-intensive cleaning and catering agency where most staff earn the minimum wage","B":"A highly automated software firm employing a small team of highly paid senior engineers","C":"An automated hydroelectric power plant with only five specialist technicians","D":"A self-service online domain-name registrar with no minimum-wage staff"},"correctOption":"A","correctAnswer":"A labour-intensive cleaning and catering agency where most staff earn the minimum wage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because labour-intensive businesses employing many minimum-wage workers see a direct, large jump in their main cost component.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because senior software engineers already earn far above the statutory minimum wage.","C":"Incorrect because automated utilities have low labour-to-capital cost ratios and highly paid technicians.","D":"Incorrect because the firm has no workers paid at the minimum wage."}}},{"id":"P1_U6_MCQ_398","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_398","question":"When high inflation erodes household savings and reduces real incomes, consumers become much more price-sensitive. How can a branded breakfast cereal maker retain market share without damaging its brand image?","options":{"A":"Introduce value-sized economy packs or loyalty-app coupons rather than lowering ingredient quality","B":"Replace oats and fruit with cheap sawdust while keeping prices high","C":"Raise retail prices by 30% above all supermarket own-brand cereals","D":"Stop supplying supermarkets and sell only from its factory gate"},"correctOption":"A","correctAnswer":"Introduce value-sized economy packs or loyalty-app coupons rather than lowering ingredient quality","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because targeted promotions and larger value packs improve affordability for stretched shoppers without permanently cheapening brand perception.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because degrading product quality destroys brand trust and violates food safety laws.","C":"Incorrect because large price hikes during high price sensitivity drive shoppers to own-label rivals.","D":"Incorrect because abandoning supermarket distribution would collapse sales volume."}}},{"id":"P1_U6_MCQ_399","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_399","question":"A government runs a large budget deficit during a severe recession by cutting taxes and increasing public spending (expansionary fiscal policy). What is the primary macroeconomic goal of this policy?","options":{"A":"To boost total spending in the economy, create jobs, and pull the country out of recession","B":"To deliberately increase unemployment to 20%","C":"To force domestic businesses to shut down factories","D":"To reduce household disposable income"},"correctOption":"A","correctAnswer":"To boost total spending in the economy, create jobs, and pull the country out of recession","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tax cuts and higher government expenditure stimulate aggregate demand, supporting business sales and employment during a downturn.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because expansionary fiscal policy aims to *reduce* unemployment.","C":"Incorrect because higher demand helps businesses keep factories open.","D":"Incorrect because tax cuts *increase* household disposable income."}}},{"id":"P1_U6_MCQ_400","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_400","question":"Why does a change in government fiscal or monetary policy often take 12 to 18 months before having its full impact on business sales and investment?","options":{"A":"Because households and firms need time to adjust spending habits, renew fixed-rate loans, and complete investment plans (time lags)","B":"Because commercial banks are legally banned from changing interest rates for two years","C":"Because businesses only check their bank accounts once every five years","D":"Because tax laws apply only to businesses founded over 100 years ago"},"correctOption":"A","correctAnswer":"Because households and firms need time to adjust spending habits, renew fixed-rate loans, and complete investment plans (time lags)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fixed-rate mortgages, existing supplier contracts, and capital project lead times create implementation time lags.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banks adjust variable rates promptly, though fixed-rate contracts take time to expire.","C":"Incorrect because businesses monitor cash flows continuously.","D":"Incorrect because tax policies apply to all active businesses regardless of age."}}},{"id":"P1_U6_MCQ_401","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_401","question":"Improvements in container shipping, refrigerated air cargo, and high-speed fibre-optic internet have dramatically lowered cross-border transport and communication costs. What major economic trend have these changes accelerated?","options":{"A":"Globalisation—the growing integration of national economies through international trade, investment, and supply chains","B":"Complete economic self-sufficiency where countries stop trading with one another","C":"The elimination of all multinational corporations","D":"A return to barter trade without money"},"correctOption":"A","correctAnswer":"Globalisation—the growing integration of national economies through international trade, investment, and supply chains","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cheaper, faster logistics and instant global communications are key technological drivers of globalisation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower transport and communication costs *increase*, rather than eliminate, trade.","C":"Incorrect because globalisation has fuelled the expansion of MNCs.","D":"Incorrect because modern global trade relies on international financial systems, not barter."}}},{"id":"P1_U6_MCQ_402","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_402","question":"A footwear company in Country A outsources shoe stitching to a supplier in Country B where wage rates are much lower, while keeping design and marketing in Country A. What is a potential drawback of this global supply chain?","options":{"A":"Longer shipping lead times and vulnerability to port delays or ethical scandals at the overseas supplier","B":"Unit stitching costs increase by 200%","C":"The company can no longer sell shoes in Country A","D":"Designers in Country A must work without computers"},"correctOption":"A","correctAnswer":"Longer shipping lead times and vulnerability to port delays or ethical scandals at the overseas supplier","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because offshoring production stretches supply chains across borders, increasing transport risks and requiring strict quality and ethical monitoring.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower overseas wages reduce, rather than raise, unit production costs.","C":"Incorrect because finished shoes are imported back into Country A and sold globally.","D":"Incorrect because design teams in Country A continue operating normally."}}},{"id":"P1_U6_MCQ_403","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_403","question":"How does membership in a regional free trade area (such as ASEAN or USMCA) benefit an exporter located in a member country?","options":{"A":"Its products enter other member countries with zero or reduced tariffs, making them more price-competitive against non-member rivals","B":"It receives a guaranteed government bailout if it makes a loss","C":"All member countries are forced to use the exact same currency","D":"Foreign competitors from member countries are banned from selling in its home market"},"correctOption":"A","correctAnswer":"Its products enter other member countries with zero or reduced tariffs, making them more price-competitive against non-member rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because free trade agreements remove customs duties between member states, lowering landed export prices and expanding market access.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because free trade agreements do not guarantee bailouts for unprofitable firms.","C":"Incorrect because free trade areas remove tariffs without requiring a common currency.","D":"Incorrect because free trade works both ways, allowing member rivals access too."}}},{"id":"P1_U6_MCQ_404","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_404","question":"Country X imposes an import quota limiting foreign steel imports to 500,000 tonnes per year. How does this quota differ from an import tariff?","options":{"A":"A quota sets a strict physical limit on the quantity imported rather than raising government tax revenue per tonne","B":"A quota removes all limits on foreign steel imports","C":"A quota lowers the domestic price of steel below world prices","D":"A quota is paid by domestic steel mills to foreign governments"},"correctOption":"A","correctAnswer":"A quota sets a strict physical limit on the quantity imported rather than raising government tax revenue per tonne","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an import quota restricts the maximum physical volume of imports allowed into the country, whereas a tariff is a customs tax.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a quota specifically caps import volume.","C":"Incorrect because restricting supply raises domestic prices above world levels.","D":"Incorrect because quotas are physical volume caps, not payments to foreign governments."}}},{"id":"P1_U6_MCQ_405","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_405","question":"When Country Y places high import tariffs on foreign agricultural produce to protect its own farmers, Country Z retaliates by placing high tariffs on Country Y's exported cars and machinery. What is this situation called?","options":{"A":"A trade war that harms exporters and raises consumer prices in both countries","B":"A customs union with free trade","C":"Currency appreciation","D":"Horizontal integration"},"correctOption":"A","correctAnswer":"A trade war that harms exporters and raises consumer prices in both countries","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tit-for-tat tariff retaliation escalates into a trade war, shrinking export markets and raising costs for businesses and consumers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tariffs create trade barriers rather than free trade.","C":"Incorrect because tariffs are trade taxes, not exchange rate movements.","D":"Incorrect because horizontal integration is a merger between firms in the same industry."}}},{"id":"P1_U6_MCQ_406","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_406","question":"Why might a government use temporary tariffs to protect a newly established 'infant industry' such as domestic electric battery manufacturing?","options":{"A":"To give new domestic firms time to grow, gain experience, and achieve economies of scale before competing with giant foreign rivals","B":"To prevent domestic consumers from ever buying electric vehicles","C":"To ensure domestic battery firms remain tiny and inefficient forever","D":"To eliminate all domestic employment in manufacturing"},"correctOption":"A","correctAnswer":"To give new domestic firms time to grow, gain experience, and achieve economies of scale before competing with giant foreign rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because infant industry protection shields emerging strategic industries until they reach competitive scale and efficiency.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the goal is building a competitive domestic battery supply.","C":"Incorrect because the protection is intended to be temporary while firms scale up.","D":"Incorrect because nurturing domestic manufacturing creates jobs."}}},{"id":"P1_U6_MCQ_407","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_407","question":"A Japanese car manufacturer builds a large assembly plant inside the European Union primarily so its cars are classified as locally produced and avoid the EU's 10% import tariff on finished vehicles. Which motive for becoming an MNC does this illustrate?","options":{"A":"Bypassing trade barriers and tariffs to gain direct access to a large regional market","B":"Accessing cheaper wages than in developing countries","C":"Escaping all environmental and safety laws","D":"Reducing total global car sales"},"correctOption":"A","correctAnswer":"Bypassing trade barriers and tariffs to gain direct access to a large regional market","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because producing inside a trade bloc avoids external import tariffs and cuts long-distance shipping costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because European manufacturing wages are relatively high; the motive is tariff-free market access.","C":"Incorrect because the EU enforces strict environmental and safety regulations.","D":"Incorrect because local assembly boosts competitiveness and EU sales."}}},{"id":"P1_U6_MCQ_408","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_408","question":"A multinational mining company extracts raw lithium in Country M, processes it in Country N, and manufactures electric vehicle batteries in Country P. Why do MNCs locate extraction plants close to raw material deposits?","options":{"A":"Transporting bulky, heavy raw ores over long distances is expensive, so locating near deposits cuts freight costs and secures supply","B":"Raw lithium deposits can easily be moved to any country by aeroplane","C":"Mining companies never need transport infrastructure","D":"Governments ban mining near natural deposits"},"correctOption":"A","correctAnswer":"Transporting bulky, heavy raw ores over long distances is expensive, so locating near deposits cuts freight costs and secures supply","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because natural resources are geographically fixed and heavy raw materials are costly to transport before processing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mineral deposits are fixed in the ground.","C":"Incorrect because mines require roads, railways, and ports to ship output.","D":"Incorrect because mining can only take place where mineral reserves exist."}}},{"id":"P1_U6_MCQ_409","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_409","question":"When a multinational technology company opens a regional data centre and software hub in Country K, local university graduates gain training in advanced cloud engineering and later launch their own local tech start-ups. What benefit to Country K is this?","options":{"A":"Technology and skills transfer that upgrades the capabilities of the domestic workforce","B":"Increased brain drain as all graduates leave Country K","C":"Immediate closure of all local universities","D":"Lower tax revenues for Country K's government"},"correctOption":"A","correctAnswer":"Technology and skills transfer that upgrades the capabilities of the domestic workforce","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because MNCs introduce modern management practices and technical know-how that spill over into the host economy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local tech jobs help retain skilled graduates inside Country K.","C":"Incorrect because MNCs often partner with local universities rather than closing them.","D":"Incorrect because new tech jobs and start-ups expand the tax base."}}},{"id":"P1_U6_MCQ_410","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_410","question":"A foreign multinational retail chain enters a developing economy and rapidly drives hundreds of small independent family-owned shops out of business through bulk-buying discounts. Why is this a concern for the host country?","options":{"A":"Loss of local entrepreneurship, displacement of traditional retail jobs, and reduced competition once local rivals close","B":"Retail prices immediately rise by 500% on day one","C":"Consumers are forced to grow all their own food","D":"The MNC is legally barred from paying wages to local cashiers"},"correctOption":"A","correctAnswer":"Loss of local entrepreneurship, displacement of traditional retail jobs, and reduced competition once local rivals close","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because giant MNCs enjoy massive economies of scale that smaller domestic firms cannot match, leading to local business closures.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because MNCs initially use low prices to capture market share.","C":"Incorrect because shoppers still buy groceries from the supermarket.","D":"Incorrect because MNCs must pay local employees according to national labour laws."}}},{"id":"P1_U6_MCQ_411","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_411","question":"What is meant by 'profit repatriation' by a multinational corporation operating in a host country?","options":{"A":"Sending profits earned by the local subsidiary back to shareholders in the MNC's home country rather than reinvesting them locally","B":"Donating 100% of local profits to host-country charities","C":"Paying double corporation tax in the host country","D":"Lowering product prices below production cost"},"correctOption":"A","correctAnswer":"Sending profits earned by the local subsidiary back to shareholders in the MNC's home country rather than reinvesting them locally","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because MNCs exist to generate returns for their parent company shareholders, meaning much of the surplus flows out of the host economy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because MNCs are commercial profit-making enterprises, not charities.","C":"Incorrect because repatriation refers to transferring after-tax profits abroad.","D":"Incorrect because selling below cost is predatory pricing/dumping, not profit repatriation."}}},{"id":"P1_U6_MCQ_412","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_412","question":"Why do critics argue that some massive multinational corporations can exert undue influence over smaller host-country governments?","options":{"A":"An MNC's annual revenue may exceed the host country's GDP, allowing it to threaten relocating factories if taxes or labour rules are tightened","B":"MNCs elect the host country's prime minister directly","C":"Host-country governments are legally prohibited from passing any business laws","D":"MNCs own the host country's military forces"},"correctOption":"A","correctAnswer":"An MNC's annual revenue may exceed the host country's GDP, allowing it to threaten relocating factories if taxes or labour rules are tightened","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the economic weight of major employers gives MNCs strong bargaining leverage over tax incentives and regulatory policies.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because citizens, not corporations, vote in national elections.","C":"Incorrect because sovereign governments have legal authority to legislate, though they weigh economic trade-offs.","D":"Incorrect because private MNCs do not own national militaries."}}},{"id":"P1_U6_MCQ_413","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_413","question":"A German machinery manufacturer exports a printing press priced at €50,000 to a buyer in the United States. If the exchange rate changes from €1 = $1.10 to €1 = $1.25, what happens to the US dollar price of the printing press?","options":{"A":"It rises from $55,000 to $62,500","B":"It falls from $62,500 to $55,000","C":"It stays unchanged at $50,000","D":"It falls from $55,000 to $40,000"},"correctOption":"A","correctAnswer":"It rises from $55,000 to $62,500","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because €50,000 × 1.10 = $55,000, and when the euro appreciates to €1 = $1.25, €50,000 × 1.25 = $62,500.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the euro appreciated against the dollar, making the press dearer in dollars.","C":"Incorrect because €50,000 is the euro price, not the dollar price.","D":"Incorrect because multiplying 50,000 by 1.25 equals $62,500, not $40,000."}}},{"id":"P1_U6_MCQ_414","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_414","question":"A Canadian timber exporter sells lumber to a UK construction firm for £100,000. When the contract is signed, £1 = CAD 1.70. When payment arrives, the pound has depreciated to £1 = CAD 1.55. How much does the Canadian exporter receive in Canadian dollars?","options":{"A":"CAD 170,000","B":"CAD 155,000","C":"CAD 15,000","D":"CAD 100,000"},"correctOption":"B","correctAnswer":"CAD 155,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because £100,000 converted at the new exchange rate of £1 = CAD 1.55 equals CAD 155,000 (down from CAD 170,000).","distractor_reasons":{"A":"Incorrect because CAD 170,000 was the value at the old exchange rate of 1.70.","B":"Correct selection.","C":"Incorrect because CAD 15,000 is the exchange rate loss, not the total amount received.","D":"Incorrect because £100,000 is the British pound invoice amount."}}},{"id":"P1_U6_MCQ_415","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_415","question":"Country Z's currency depreciates by 15% against all major foreign currencies. A domestic baker in Country Z relies heavily on imported wheat and imported butter. How is the baker affected?","options":{"A":"The domestic-currency cost of imported wheat and butter rises, squeezing profit margins unless bread prices are increased","B":"Imported wheat and butter become 15% cheaper in local currency","C":"The baker's electricity bill falls by 15% automatically","D":"Local customers stop eating bread completely"},"correctOption":"A","correctAnswer":"The domestic-currency cost of imported wheat and butter rises, squeezing profit margins unless bread prices are increased","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because currency depreciation means more units of domestic currency are required to pay for imported ingredients, raising variable costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because depreciation makes imports *more expensive*, whereas appreciation makes them cheaper.","C":"Incorrect because domestic utility tariffs do not drop when the currency depreciates.","D":"Incorrect because bread is a basic staple food with relatively inelastic demand."}}},{"id":"P1_U6_MCQ_416","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_416","question":"When Country M's currency appreciates significantly, a domestic smartphone manufacturer in Country M finds its exports are now 12% dearer in overseas markets. If demand for its smartphones abroad is price-elastic, what will happen to its export sales revenue?","options":{"A":"Export sales volume will fall by more than 12%, causing total export sales revenue to decrease sharply","B":"Export sales volume will stay completely unchanged","C":"Export sales revenue will double","D":"Overseas buyers will pay 12% less in their own currency"},"correctOption":"A","correctAnswer":"Export sales volume will fall by more than 12%, causing total export sales revenue to decrease sharply","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when demand is price-elastic, a 12% price increase causes a larger percentage drop in quantity demanded, lowering total revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because price-elastic buyers switch readily to cheaper rival smartphone brands.","C":"Incorrect because losing substantial sales volume reduces revenue.","D":"Incorrect because currency appreciation makes exports *more expensive* in foreign currency."}}},{"id":"P1_U6_MCQ_417","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_417","question":"Why might a luxury Swiss watchmaker suffer a smaller drop in export sales volume after a currency appreciation than a manufacturer of standard unbranded steel nails?","options":{"A":"Luxury watches have strong brand loyalty and price-inelastic demand, whereas unbranded steel nails compete almost entirely on price","B":"Steel nails are never used in construction outside Switzerland","C":"Currency appreciation does not apply to luxury watches","D":"Swiss watchmakers give their watches away for free when the franc appreciates"},"correctOption":"A","correctAnswer":"Luxury watches have strong brand loyalty and price-inelastic demand, whereas unbranded steel nails compete almost entirely on price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because strong differentiation and prestige make demand for luxury watches relatively price-insensitive compared to undifferentiated commodities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because steel nails are widely traded commodities.","C":"Incorrect because exchange rate movements affect all exported goods.","D":"Incorrect because luxury watchmakers maintain high prices."}}},{"id":"P1_U6_MCQ_418","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_418","question":"A global fast-food chain expands into India and replaces beef burgers on its menu with spicy paneer, chickpea, and chicken burgers. Which challenge of operating internationally does this strategy address?","options":{"A":"Adapting products to respect local cultural, religious, and dietary preferences","B":"Avoiding all corporate income taxes in India","C":"Eliminating the need to train local restaurant staff","D":"Preventing any local Indian competitors from opening restaurants"},"correctOption":"A","correctAnswer":"Adapting products to respect local cultural, religious, and dietary preferences","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because successful multinationals 'glocalise'—adapting menus and marketing to local cultural and religious norms.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because menu adaptation has nothing to do with tax avoidance.","C":"Incorrect because local staff still require full operational training.","D":"Incorrect because local competitors remain free to operate."}}},{"id":"P1_U6_MCQ_419","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_419","question":"Before entering a new overseas market, why should a domestic business research the foreign country's legal system and employment laws?","options":{"A":"Because rules on product labelling, minimum wages, working hours, and contracts differ between countries and must be obeyed to avoid fines","B":"Because a business always follows its home country's laws even when operating abroad","C":"Because foreign countries never have consumer protection laws","D":"Because legal research eliminates exchange rate fluctuations"},"correctOption":"A","correctAnswer":"Because rules on product labelling, minimum wages, working hours, and contracts differ between countries and must be obeyed to avoid fines","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because businesses must comply with the statutory employment, safety, and consumer regulations of every host country in which they operate.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses operating in a foreign territory are subject to that host nation's laws.","C":"Incorrect because most countries enforce consumer safety and labelling regulations.","D":"Incorrect because legal research does not fix currency exchange rates."}}},{"id":"P1_U6_MCQ_420","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_420","question":"A medium-sized furniture maker wants to enter a foreign market quickly without investing huge capital in building its own overseas factories or stores. Which entry method suits this goal best?","options":{"A":"Forming a joint venture with an established local distributor or licensing its designs to a local partner","B":"Building five wholly owned factories from scratch in the foreign country","C":"Buying out the largest multinational conglomerate in the world","D":"Stopping all domestic production immediately"},"correctOption":"A","correctAnswer":"Forming a joint venture with an established local distributor or licensing its designs to a local partner","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because joint ventures and licensing share capital costs and leverage a local partner's existing distribution network and market knowledge.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wholly owned greenfield factories require massive capital investment and carry high risk.","C":"Incorrect because a medium-sized firm lacks the funds to acquire a giant conglomerate.","D":"Incorrect because abandoning its profitable home base would endanger the firm."}}},{"id":"P1_U6_MCQ_421","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_421","question":"When a domestic manufacturing company expands into a mature, saturated foreign market where local brands are already deeply loyal to customers, what marketing challenge will it face?","options":{"A":"High promotional and advertising costs needed to build brand awareness and persuade buyers to switch","B":"Zero competition from any domestic or foreign businesses","C":"Customers automatically buying its unknown brand at premium prices","D":"Exemption from paying shipping and customs fees"},"correctOption":"A","correctAnswer":"High promotional and advertising costs needed to build brand awareness and persuade buyers to switch","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because breaking into established markets requires heavy marketing expenditure and competitive pricing to overcome existing brand loyalty.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because saturated markets have intense competition.","C":"Incorrect because unknown entrants rarely command premium prices without heavy brand building.","D":"Incorrect because normal logistics and customs costs still apply."}}},{"id":"P1_U6_MCQ_422","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_422","question":"Country P's currency depreciates steadily over three years. How can a domestic manufacturer in Country P take advantage of this currency trend?","options":{"A":"Expand export marketing efforts abroad where its goods are now more price-competitive, and source more raw materials from domestic suppliers","B":"Import 100% of its raw materials from abroad and stop exporting completely","C":"Raise its domestic-currency export prices by 50% above foreign rivals","D":"Convert all its cash reserves into foreign debt"},"correctOption":"A","correctAnswer":"Expand export marketing efforts abroad where its goods are now more price-competitive, and source more raw materials from domestic suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a weaker currency boosts export price competitiveness while substituting domestic inputs for costly imports protects profit margins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because importing all inputs while abandoning exports maximises the cost penalty and misses the export opportunity.","C":"Incorrect because excessive price hikes would wipe out the export price advantage.","D":"Incorrect because foreign-currency debt becomes *more expensive* to repay when the domestic currency depreciates."}}},{"id":"P1_U6_MCQ_423","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_423","question":"A multinational consumer goods firm has 45 subsidiaries across four continents. What organisational challenge often arises as an MNC grows across so many countries?","options":{"A":"Communication delays, cultural misunderstandings between head office and regional managers, and diseconomies of scale","B":"Complete inability to sell products in more than one country","C":"Lower total sales revenue than a single local corner shop","D":"A legal requirement that all 45 subsidiaries use the exact same language in local shops"},"correctOption":"A","correctAnswer":"Communication delays, cultural misunderstandings between head office and regional managers, and diseconomies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managing vast global operations across time zones and cultures increases coordination complexity and diseconomies of scale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because MNCs actively sell across dozens of countries.","C":"Incorrect because global MNCs generate vastly higher revenues than small local shops.","D":"Incorrect because local stores communicate in the local language of each market."}}},{"id":"P1_U6_MCQ_424","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_424","question":"Why might a host government require a foreign multinational company to form a joint venture with a local state or private company rather than owning 100% of the local subsidiary?","options":{"A":"To ensure local firms share in profits, gain management expertise, and retain partial control over key national industries","B":"To prevent the multinational from bringing any technology into the country","C":"To guarantee that the joint venture makes a financial loss every year","D":"To avoid collecting any tax revenue from the business"},"correctOption":"A","correctAnswer":"To ensure local firms share in profits, gain management expertise, and retain partial control over key national industries","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mandatory joint-venture rules help host countries capture technology transfer and retain domestic ownership stakes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because host governments use joint ventures specifically to *acquire* foreign technology and skills.","C":"Incorrect because both partners want the venture to be profitable.","D":"Incorrect because governments tax joint-venture profits normally."}}},{"id":"P1_U6_MCQ_425","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_425","question":"Which statement provides the most balanced evaluation of globalisation for businesses in a developing economy?","options":{"A":"Globalisation opens vast export markets and attracts foreign investment and technology, though weak domestic firms risk closure against powerful foreign rivals","B":"Globalisation guarantees that every small domestic business will become a global monopoly","C":"Globalisation destroys all economic growth and forces every country into permanent recession","D":"Globalisation only affects agricultural farms and has zero impact on services or manufacturing"},"correctOption":"A","correctAnswer":"Globalisation opens vast export markets and attracts foreign investment and technology, though weak domestic firms risk closure against powerful foreign rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because globalisation creates major export and investment opportunities while simultaneously exposing uncompetitive local firms to intense foreign competition.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because many small local firms struggle against foreign competition rather than becoming monopolies.","C":"Incorrect because globalisation has driven rapid export-led growth in many developing economies.","D":"Incorrect because globalisation transforms manufacturing, retail, finance, and digital services."}}},{"id":"P1_U6_MCQ_426","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_426","question":"A textile dyeing factory discharges untreated chemical wastewater into a river, forcing a downstream municipal water company to spend $300,000 per year on extra water purification. What is this $300,000 expense?","options":{"A":"An external cost imposed on a third party by the textile factory's production","B":"A private benefit earned by the textile factory's shareholders","C":"An external benefit that improves river biodiversity","D":"A fixed overhead voluntarily paid by the textile factory"},"correctOption":"A","correctAnswer":"An external cost imposed on a third party by the textile factory's production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the purification cost is suffered by an uninvolved third party (the water utility and its customers) rather than paid by the polluting factory.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because it is a financial cost caused by pollution, not a benefit.","C":"Incorrect because untreated wastewater harms biodiversity and creates an external cost.","D":"Incorrect because the downstream water company, not the factory, bears this cost."}}},{"id":"P1_U6_MCQ_427","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_427","question":"A commercial forestry company plants 500,000 native trees on degraded hillside land. The company expects to earn $2 million from future sustainable timber sales (private benefit), while the new forest prevents flooding and absorbs carbon worth $900,000 to society (external benefit). What is the total social benefit?","options":{"A":"$1.1 million","B":"$2.0 million","C":"$2.9 million","D":"$0.9 million"},"correctOption":"C","correctAnswer":"$2.9 million","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social benefit equals private benefit ($2.0m) plus external benefit ($0.9m), which is $2.9 million.","distractor_reasons":{"A":"Incorrect because $1.1m subtracts external benefit from private benefit instead of adding them.","B":"Incorrect because $2.0m includes only the private benefit to the forestry firm.","C":"Correct selection.","D":"Incorrect because $0.9m includes only the external benefit to society."}}},{"id":"P1_U6_MCQ_428","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_428","question":"A chemical plant's monthly private production costs are $420,000, and its air emissions impose $85,000 per month in external respiratory health costs on nearby residents. What is the plant's monthly social cost?","options":{"A":"$335,000","B":"$420,000","C":"$505,000","D":"$85,000"},"correctOption":"C","correctAnswer":"$505,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social cost = private cost ($420,000) + external cost ($85,000) = $505,000.","distractor_reasons":{"A":"Incorrect because $335,000 subtracts external costs from private costs.","B":"Incorrect because $420,000 includes only private costs.","C":"Correct selection.","D":"Incorrect because $85,000 includes only external costs."}}},{"id":"P1_U6_MCQ_429","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_429","question":"What is meant by 'sustainable development' in a business context?","options":{"A":"Meeting the needs of today's consumers and businesses without depleting natural resources or harming ecosystems for future generations","B":"Maximising short-term resource extraction even if forests and fisheries collapse permanently","C":"Stopping all economic production and closing every factory permanently","D":"Using only non-renewable fossil fuels because they are cheaper"},"correctOption":"A","correctAnswer":"Meeting the needs of today's consumers and businesses without depleting natural resources or harming ecosystems for future generations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainable development balances current economic activity with long-term environmental stewardship and resource conservation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because exhausting finite resources is unsustainable.","C":"Incorrect because sustainable development seeks responsible growth, not halting all human activity.","D":"Incorrect because sustainability requires transitioning toward renewable energy."}}},{"id":"P1_U6_MCQ_430","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_430","question":"A furniture maker sources all its oak and pine from forests certified by the Forest Stewardship Council (FSC), where new trees are replanted for every tree harvested. How does this benefit the furniture maker?","options":{"A":"It secures a renewable long-term timber supply and allows the firm to use the recognised FSC eco-label to attract environmentally conscious buyers","B":"It makes the timber completely free of charge","C":"It eliminates the need for carpenters and woodworking machines","D":"It exempts the furniture maker from paying Value Added Tax"},"correctOption":"A","correctAnswer":"It secures a renewable long-term timber supply and allows the firm to use the recognised FSC eco-label to attract environmentally conscious buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because credible third-party sustainability certification prevents future resource depletion and adds marketing value.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because certified sustainable timber often costs slightly more than uncertified wood.","C":"Incorrect because manufacturing furniture still requires skilled workers and equipment.","D":"Incorrect because eco-certification does not waive sales taxes."}}},{"id":"P1_U6_MCQ_431","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_431","question":"A commercial fishing fleet voluntarily uses larger-mesh fishing nets that allow young, undersized fish to escape and mature before breeding. Why is this sustainable practice commercially smart in the long run?","options":{"A":"It prevents fish stocks from collapsing, ensuring the business can continue harvesting fish profitably in future years","B":"It increases the quantity of unsaleable juvenile fish caught today","C":"It eliminates fuel costs for fishing trawlers","D":"It forces consumers to stop eating fish"},"correctOption":"A","correctAnswer":"It prevents fish stocks from collapsing, ensuring the business can continue harvesting fish profitably in future years","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because overfishing destroys the natural capital on which the fishing business depends; preserving breeding stocks ensures long-term survival.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because larger mesh specifically reduces juvenile bycatch.","C":"Incorrect because fishing boats still consume marine fuel.","D":"Incorrect because sustainable catches supply fish to consumers."}}},{"id":"P1_U6_MCQ_432","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_432","question":"An electronics manufacturer designs smartphones with modular batteries and screens that can be easily repaired with standard tools, rather than glued shut. How does this support environmental sustainability?","options":{"A":"It extends product lifespan and reduces toxic electronic waste (e-waste) and rare-earth mining","B":"It forces customers to throw away their phones every six months","C":"It increases the amount of hazardous heavy metals sent to landfills","D":"It makes smartphones impossible to recycle"},"correctOption":"A","correctAnswer":"It extends product lifespan and reduces toxic electronic waste (e-waste) and rare-earth mining","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because designing for repairability slows resource consumption and cuts hazardous e-waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because easy repairs extend phone life rather than encouraging frequent replacement.","C":"Incorrect because longer device lifespans *reduce* landfill waste.","D":"Incorrect because modular parts are easier to disassemble and recycle."}}},{"id":"P1_U6_MCQ_433","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_433","question":"A government introduces a 'landfill tax' charging businesses $120 for every tonne of solid waste sent to landfill sites, while recycled waste incurs zero tax. How is a large supermarket chain likely to respond?","options":{"A":"Invest in in-store cardboard compactors, food-waste anaerobic digestion, and reusable delivery crates to cut landfill costs","B":"Send twice as much mixed rubbish to landfill sites","C":"Stop selling fresh fruit and vegetables","D":"Burn all its plastic packaging in store car parks"},"correctOption":"A","correctAnswer":"Invest in in-store cardboard compactors, food-waste anaerobic digestion, and reusable delivery crates to cut landfill costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a steep landfill tax makes recycling and waste reduction financially profitable compared to disposal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sending more waste to landfill would sharply increase tax expenses.","C":"Incorrect because fresh produce is a core supermarket category.","D":"Incorrect because open burning of plastic waste is illegal and hazardous."}}},{"id":"P1_U6_MCQ_434","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_434","question":"To reduce urban air pollution, a city government establishes a Low Emission Zone (LEZ) that charges older diesel delivery vans $50 per day to enter the city centre, while electric vans enter free. How does this affect a local parcel courier?","options":{"A":"It creates a strong financial case to lease or buy electric delivery vans for city-centre routes","B":"It lowers the operating cost of old diesel vans in the city centre","C":"It bans all online shopping deliveries inside the city","D":"It forces couriers to deliver parcels only on foot"},"correctOption":"A","correctAnswer":"It creates a strong financial case to lease or buy electric delivery vans for city-centre routes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because avoiding a $50 daily congestion/emission charge rapidly offsets the higher upfront cost of electric vans.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the $50 daily fee *increases* the cost of running older diesel vans.","C":"Incorrect because deliveries are still permitted, especially with zero-emission vehicles.","D":"Incorrect because electric vans and cargo bikes can legally enter free of charge."}}},{"id":"P1_U6_MCQ_435","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_435","question":"A government sets strict legal limits on sulphur dioxide emissions from factories and imposes heavy fines plus temporary factory closure orders on firms that exceed the limit. Why do governments use regulation alongside green taxes?","options":{"A":"Because dangerous toxic pollutants require guaranteed maximum safety limits rather than allowing rich firms to pay a tax and keep polluting","B":"Because fines never cost businesses any money","C":"Because green taxes are illegal under international law","D":"Because regulations allow factories to release unlimited toxic smoke"},"correctOption":"A","correctAnswer":"Because dangerous toxic pollutants require guaranteed maximum safety limits rather than allowing rich firms to pay a tax and keep polluting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because command-and-control regulations set absolute ceilings on harmful emissions where public health is at immediate risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because heavy fines and shutdowns impose severe financial penalties.","C":"Incorrect because environmental taxes are widely used alongside regulations.","D":"Incorrect because regulations specifically *cap* emissions."}}},{"id":"P1_U6_MCQ_436","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_436","question":"A start-up company manufactures reusable insulated stainless-steel water bottles and markets them as an eco-friendly alternative to single-use plastic bottles. Which external trend is creating rapid growth for this business?","options":{"A":"Rising consumer awareness of ocean plastic pollution and changing social attitudes toward single-use plastics","B":"Falling global population and declining demand for drinking water","C":"Government bans on reusable metal bottles","D":"A sharp drop in the price of single-use plastic waste"},"correctOption":"A","correctAnswer":"Rising consumer awareness of ocean plastic pollution and changing social attitudes toward single-use plastics","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because environmental concern acts as a major market opportunity for innovative green products and eco-entrepreneurs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because demand for hydration products remains strong worldwide.","C":"Incorrect because governments encourage reusable bottles and restrict single-use plastics.","D":"Incorrect because consumer preference has shifted away from disposable plastic."}}},{"id":"P1_U6_MCQ_437","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_437","question":"A detergent manufacturer launches a concentrated liquid detergent in small recyclable pouches that require 70% less plastic and 60% less lorry space to transport than bulky jugs. How does this innovation help both the environment and business profits?","options":{"A":"It cuts carbon emissions and plastic waste while simultaneously lowering packaging material and haulage costs per wash","B":"It increases packaging material costs and transport fuel bills","C":"It forces customers to buy three times more water in heavy plastic bottles","D":"It reduces supermarket shelf space efficiency"},"correctOption":"A","correctAnswer":"It cuts carbon emissions and plastic waste while simultaneously lowering packaging material and haulage costs per wash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lightweight concentrated packaging is a classic 'eco-efficiency' win-win that lowers unit costs and environmental footprint.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because using 70% less plastic and 60% less lorry space *reduces* costs.","C":"Incorrect because concentrated detergent removes excess water from the packaging.","D":"Incorrect because compact pouches take up *less* shelf space per wash."}}},{"id":"P1_U6_MCQ_438","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_438","question":"Why might a small family-owned bakery struggle more than a large multinational food corporation to comply with complex new environmental reporting and carbon-auditing laws?","options":{"A":"The small bakery lacks specialist sustainability staff and cannot spread fixed compliance and auditing fees over millions of units","B":"Small bakeries are legally required to pay double the carbon tax rate of multinationals","C":"Multinational corporations are exempt from all environmental laws","D":"Small bakeries never use electricity or ovens"},"correctOption":"A","correctAnswer":"The small bakery lacks specialist sustainability staff and cannot spread fixed compliance and auditing fees over millions of units","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because regulatory compliance carries fixed administrative costs that fall disproportionately heavily on small businesses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax rates are not doubled for small firms.","C":"Incorrect because MNCs face strict environmental reporting mandates.","D":"Incorrect because bakeries use ovens and energy."}}},{"id":"P1_U6_MCQ_439","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_439","question":"A water-bottling company extracts millions of litres of groundwater daily from a rural aquifer, causing local farmers' irrigation wells to run dry during summer. Which conflict between stakeholder groups does this illustrate?","options":{"A":"The company's profit and production goals conflicting with the local community's and farmers' access to shared natural resources","B":"Local farmers demanding the bottling company pump even more water","C":"Shareholders asking the company to stop selling bottled water","D":"Complete harmony between industrial water extraction and local agriculture"},"correctOption":"A","correctAnswer":"The company's profit and production goals conflicting with the local community's and farmers' access to shared natural resources","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because over-exploiting a common natural resource imposes severe external costs on neighbouring agricultural businesses and residents.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local farmers suffer when their wells dry up.","C":"Incorrect because shareholders seek profitable output unless stopped by regulation or protests.","D":"Incorrect because depleting the shared aquifer creates direct conflict."}}},{"id":"P1_U6_MCQ_440","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_440","question":"A clothing retailer installs rooftop solar panels costing $200,000 that save $40,000 per year in electricity bills and cut carbon emissions by 80 tonnes annually. How long will it take for the electricity savings to pay back the initial investment?","options":{"A":"2 years","B":"5 years","C":"8 years","D":"20 years"},"correctOption":"B","correctAnswer":"5 years","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because $200,000 initial cost ÷ $40,000 annual electricity savings = 5 years payback, after which the firm enjoys lower overheads and cleaner energy.","distractor_reasons":{"A":"Incorrect because 2 years × $40,000 = $80,000, which is less than $200,000.","B":"Correct selection.","C":"Incorrect because 8 years × $40,000 = $320,000.","D":"Incorrect because 200,000 ÷ 40,000 = 5, not 20."}}},{"id":"P1_U6_MCQ_441","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_441","question":"A supermarket chain places 'Carbon Footprint Score' labels (from A to E) on all food products so shoppers can see the greenhouse gas impact of their groceries. How is this likely to influence food suppliers?","options":{"A":"Suppliers will compete to reduce farming and packaging emissions to earn an 'A' rating and avoid losing eco-conscious shoppers","B":"Suppliers will deliberately increase emissions to get an 'E' rating","C":"Shoppers will stop buying any food with an 'A' rating","D":"Supermarkets will stop selling fresh vegetables"},"correctOption":"A","correctAnswer":"Suppliers will compete to reduce farming and packaging emissions to earn an 'A' rating and avoid losing eco-conscious shoppers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because transparent environmental labelling nudges consumer choice and creates competitive pressure across the supply chain.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because poor environmental ratings deter eco-conscious buyers.","C":"Incorrect because 'A' represents the lowest, most desirable carbon footprint.","D":"Incorrect because vegetables typically score very well ('A') on carbon footprint."}}},{"id":"P1_U6_MCQ_442","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_442","question":"Why do some budget airlines resist investing immediately in Sustainable Aviation Fuel (SAF) even though it cuts lifecycle carbon emissions by up to 80%?","options":{"A":"Sustainable Aviation Fuel currently costs two to four times more than conventional jet fuel, which would raise ticket prices and reduce price competitiveness","B":"Sustainable Aviation Fuel is banned by international aviation authorities","C":"Conventional jet fuel produces zero carbon emissions","D":"Airlines do not spend any money on fuel"},"correctOption":"A","correctAnswer":"Sustainable Aviation Fuel currently costs two to four times more than conventional jet fuel, which would raise ticket prices and reduce price competitiveness","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high short-term input costs create a commercial dilemma in price-competitive industries unless matched by mandates or subsidies.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because SAF is approved and actively blended into commercial flights.","C":"Incorrect because conventional kerosene jet fuel is a major source of CO2 emissions.","D":"Incorrect because fuel is one of an airline's largest operating expenses."}}},{"id":"P1_U6_MCQ_443","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_443","question":"A city council builds a new underground metro line. Construction causes two years of noise and dust for shopkeepers (external cost), but once open, it reduces traffic jams, cuts air pollution, and brings thousands of extra shoppers to high-street stores (external benefit). How should the council evaluate this project?","options":{"A":"Use cost-benefit analysis to compare total long-term social benefits against total social costs, rather than looking only at short-term disruption","B":"Cancel the project because any temporary construction dust is always unacceptable","C":"Ignore all environmental and community impacts completely","D":"Charge shopkeepers a fine for having fewer customers during construction"},"correctOption":"A","correctAnswer":"Use cost-benefit analysis to compare total long-term social benefits against total social costs, rather than looking only at short-term disruption","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public infrastructure decisions weigh temporary private/external construction costs against decades of social and environmental benefits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because long-term social benefits often far outweigh temporary construction disruption.","C":"Incorrect because public bodies must assess social and environmental externalities.","D":"Incorrect because councils often provide business-rate relief rather than fines during roadworks."}}},{"id":"P1_U6_MCQ_444","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_444","question":"A paper manufacturer shifts from bleaching office paper with chlorine gas (which produces toxic dioxins) to using an oxygen-based bleaching process after installing new filtration equipment. What type of environmental business response is this?","options":{"A":"Investing in cleaner production technology to prevent pollution at source","B":"Relocating pollution to another country","C":"Greenwashing without changing manufacturing processes","D":"Bribing environmental inspectors"},"correctOption":"A","correctAnswer":"Investing in cleaner production technology to prevent pollution at source","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because upgrading industrial processes eliminates toxic waste generation rather than merely hiding or moving it.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the firm upgraded its own domestic plant.","C":"Incorrect because the firm made a genuine technical improvement to its manufacturing process.","D":"Incorrect because installing cleaner technology achieves authentic compliance."}}},{"id":"P1_U6_MCQ_445","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_445","question":"A hotel chain removes miniature single-use plastic shampoo bottles from all 10,000 guest rooms and installs refillable wall-mounted dispensers. Which two outcomes does this achieve?","options":{"A":"Eliminates millions of single-use plastic bottles per year and lowers bulk toiletry purchasing costs","B":"Increases plastic waste and triples housekeeping supply costs","C":"Forces guests to bring their own soap from home","D":"Violates hospitality hygiene regulations"},"correctOption":"A","correctAnswer":"Eliminates millions of single-use plastic bottles per year and lowers bulk toiletry purchasing costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bulk refillable dispensers simultaneously cut plastic packaging waste and unit supply expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bulk refills reduce both plastic waste and unit costs.","C":"Incorrect because soap and shampoo are still provided in the dispensers.","D":"Incorrect because tamper-proof wall dispensers meet hotel hygiene standards."}}},{"id":"P1_U6_MCQ_446","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_446","question":"A national government sets a legally binding target for all new passenger cars sold after 2035 to be zero-emission vehicles. How does this long-term environmental policy affect traditional petrol-engine carmakers today?","options":{"A":"They must redirect billions of dollars in R&D and factory retooling toward electric vehicles and battery supply chains now to avoid becoming obsolete","B":"They can continue investing solely in petrol engines indefinitely","C":"They must stop selling all cars immediately this year","D":"They receive government subsidies to build more petrol refineries"},"correctOption":"A","correctAnswer":"They must redirect billions of dollars in R&D and factory retooling toward electric vehicles and battery supply chains now to avoid becoming obsolete","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because clear long-term regulatory deadlines reshape corporate strategy, R&D allocation, and supply-chain investments years in advance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ignoring the 2035 phase-out would leave the automaker with no legal product to sell.","C":"Incorrect because the phase-out date is 2035, giving a transition period.","D":"Incorrect because policy is shifting away from fossil-fuel transport."}}},{"id":"P1_U6_MCQ_447","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_447","question":"Under a 'cap-and-trade' emissions trading scheme, heavy industries are given a limited number of carbon permits; firms that cut emissions below their allowance can sell spare permits to higher-emitting firms. Why is this system used?","options":{"A":"It puts a market price on carbon emissions and financially rewards businesses that innovate to cut pollution fastest","B":"It allows factories to release unlimited greenhouse gases for free","C":"It forces every factory to shut down within one week","D":"It applies only to small family hairdressers"},"correctOption":"A","correctAnswer":"It puts a market price on carbon emissions and financially rewards businesses that innovate to cut pollution fastest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cap-and-trade caps total industry emissions while creating a financial reward (selling surplus permits) for green efficiency.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because total permits are strictly capped and excess emitters must buy permits.","C":"Incorrect because firms can continue operating by cutting emissions or purchasing permits.","D":"Incorrect because cap-and-trade targets major industrial emitters such as power stations and steelworks."}}},{"id":"P1_U6_MCQ_448","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_448","question":"A ski resort operating at low altitude experiences shorter winter snow seasons due to rising global temperatures. How might the business adapt strategically to this environmental change?","options":{"A":"Diversify into year-round mountain biking, hiking, and eco-wellness retreats so it is not dependent solely on winter snow","B":"Raise winter lift-pass prices by 300% while keeping the resort closed all summer","C":"Ignore climate trends and build ten new ski lifts on bare rock","D":"Stop maintaining its hotel facilities"},"correctOption":"A","correctAnswer":"Diversify into year-round mountain biking, hiking, and eco-wellness retreats so it is not dependent solely on winter snow","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because diversifying into summer and autumn outdoor tourism protects revenue against climate-driven declines in winter snowfall.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because huge price hikes for shorter snow seasons would drive skiers away.","C":"Incorrect because building ski lifts where snow is unreliable wastes capital.","D":"Incorrect because high-quality facilities are essential to attract year-round guests."}}},{"id":"P1_U6_MCQ_449","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_449","question":"A coffee roaster offers a 20% discount to customers who bring refillable containers to its stores and composts 100% of its coffee chaff waste with local urban farms. Beyond environmental benefits, what marketing advantage does this create?","options":{"A":"Strong word-of-mouth publicity, repeat footfall, and differentiation from less sustainable coffee chains","B":"Higher packaging waste disposal bills","C":"Lower customer retention among eco-conscious buyers","D":"Legal exemption from food hygiene inspections"},"correctOption":"A","correctAnswer":"Strong word-of-mouth publicity, repeat footfall, and differentiation from less sustainable coffee chains","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because visible, authentic circular-economy initiatives build community goodwill and repeat customer visits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because refillable containers and composting *reduce* waste bills.","C":"Incorrect because eco-conscious buyers are strongly attracted to zero-waste shops.","D":"Incorrect because food hygiene rules still apply to all food and drink businesses."}}},{"id":"P1_U6_MCQ_450","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_450","question":"Which statement best evaluates whether becoming environmentally sustainable always reduces a business's profit?","options":{"A":"Although green technologies and sustainable materials often require high upfront investment, they frequently increase long-term profit through lower energy/waste bills, stronger brand loyalty, and avoided green taxes","B":"Environmental sustainability always bankrupts businesses within two years","C":"Green initiatives never require any initial capital outlay or higher material costs","D":"Consumers always refuse to buy products from environmentally responsible companies"},"correctOption":"A","correctAnswer":"Although green technologies and sustainable materials often require high upfront investment, they frequently increase long-term profit through lower energy/waste bills, stronger brand loyalty, and avoided green taxes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a balanced evaluation distinguishes between short-term capital/input costs and long-term cost savings, tax avoidance, and revenue growth.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because many sustainable firms outperform rivals in profitability and resilience.","C":"Incorrect because renewable energy, eco-packaging, and certified inputs often cost more initially.","D":"Incorrect because growing segments of consumers actively prefer sustainable brands."}}},{"id":"P1_U6_MCQ_451","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_451","question":"In Country A, the statutory minimum wage is $8.00 per hour, which is not enough for a family to afford basic housing and food. A clothing retailer voluntarily pays all store and warehouse staff a 'Real Living Wage' of $12.50 per hour. What does this illustrate?","options":{"A":"Acting ethically by going beyond minimum legal requirements to ensure fair living standards for employees","B":"Breaking employment law by paying above the statutory rate","C":"Predatory pricing to eliminate rival clothing retailers","D":"Profit repatriation to foreign shareholders"},"correctOption":"A","correctAnswer":"Acting ethically by going beyond minimum legal requirements to ensure fair living standards for employees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethics concerns moral principles above bare legal compliance, such as paying a genuine living wage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the minimum wage is a legal floor; paying more is completely legal.","C":"Incorrect because employee wage rates are HR policy, not predatory pricing.","D":"Incorrect because paying higher wages invests in domestic staff rather than sending profits abroad."}}},{"id":"P1_U6_MCQ_452","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_452","question":"A toy company uses colourful cartoon characters in online mobile games to trick young children into making accidental in-app purchases using their parents' credit cards without clear warnings. Why is this practice widely condemned as unethical?","options":{"A":"It deliberately exploits vulnerable young consumers and deceives parents rather than selling transparently","B":"It lowers the price of mobile games to zero","C":"It increases parental control over household spending","D":"It supports fairtrade toy manufacturing"},"correctOption":"A","correctAnswer":"It deliberately exploits vulnerable young consumers and deceives parents rather than selling transparently","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because manipulative marketing aimed at children breaches ethical standards of honesty and consumer protection.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hidden in-app charges extract money deceptively.","C":"Incorrect because it bypasses parental awareness.","D":"Incorrect because deceptive digital billing has nothing to do with Fairtrade."}}},{"id":"P1_U6_MCQ_453","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_453","question":"A profitable multinational technology company uses complex accounting loopholes to route all its profits through a zero-tax island, paying almost zero corporation tax in the countries where it earns billions in sales. Why do critics view this as unethical even if technically legal?","options":{"A":"Because the company uses public roads, schools, and legal systems in those countries without contributing its fair share of taxes to fund them","B":"Because paying zero tax is always a criminal offence in every country","C":"Because low taxes reduce the company's retained profits","D":"Because customers prefer companies that avoid paying public taxes"},"correctOption":"A","correctAnswer":"Because the company uses public roads, schools, and legal systems in those countries without contributing its fair share of taxes to fund them","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because aggressive tax avoidance highlights the gap between strict legality and moral fairness toward host societies.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax avoidance exploits legal loopholes (unlike illegal tax evasion), which is precisely why it is an ethical debate.","C":"Incorrect because avoiding tax increases retained profits, which is why firms do it.","D":"Incorrect because tax-avoidance scandals frequently spark consumer boycotts."}}},{"id":"P1_U6_MCQ_454","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_454","question":"A coffee roaster joins the Fairtrade Foundation, guaranteeing smallholder coffee farmers a fair minimum price above production costs plus an extra social premium for local schools and clinics. What is the main trade-off for the coffee roaster?","options":{"A":"Higher raw coffee bean purchase costs in exchange for stronger ethical brand reputation and access to socially conscious consumers","B":"Lower raw coffee bean purchase costs and zero marketing benefits","C":"Complete exemption from import customs inspections","D":"Loss of all supermarket retail shelf space"},"correctOption":"A","correctAnswer":"Higher raw coffee bean purchase costs in exchange for stronger ethical brand reputation and access to socially conscious consumers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Fairtrade sourcing raises direct input costs while differentiating the brand and justifying premium retail prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Fairtrade guarantees *higher* minimum prices to farmers, raising input costs.","C":"Incorrect because normal customs inspections still apply.","D":"Incorrect because supermarkets actively stock certified Fairtrade brands."}}},{"id":"P1_U6_MCQ_455","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_455","question":"A pharmaceutical company discovers during internal testing that a popular painkiller causes rare heart side effects, even though regulators have not yet requested a recall. What is the ethical action for the company's directors?","options":{"A":"Immediately notify health regulators, warn doctors and patients, and voluntarily recall the product despite the short-term financial loss","B":"Hide the test results and double advertising spending to sell remaining stock quickly","C":"Destroy the laboratory records and blame competitors","D":"Export the remaining stock to countries with weaker drug regulators"},"correctOption":"A","correctAnswer":"Immediately notify health regulators, warn doctors and patients, and voluntarily recall the product despite the short-term financial loss","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because protecting human health and life overrides short-term profit, and honest voluntary recalls preserve long-term trust.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because knowingly selling harmful medicine is deeply unethical and exposes the firm to catastrophic lawsuits.","C":"Incorrect because falsifying or destroying safety data is illegal and immoral.","D":"Incorrect because dumping unsafe products in developing nations is a severe ethical violation."}}},{"id":"P1_U6_MCQ_456","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_456","question":"An accounting firm establishes an anonymous 'whistleblowing hotline' so junior employees can safely report fraud, harassment, or safety violations without fear of being fired. Why is a whistleblowing policy important for ethical governance?","options":{"A":"It uncovers unethical or illegal misconduct early before it escalates into a major scandal that destroys the business","B":"It encourages employees to commit accounting fraud","C":"It replaces the need for external financial audits","D":"It allows managers to punish employees who report safety hazards"},"correctOption":"A","correctAnswer":"It uncovers unethical or illegal misconduct early before it escalates into a major scandal that destroys the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because safe internal reporting channels empower staff to speak up and allow senior management to correct wrongdoing promptly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because whistleblowing deters fraud by increasing the chance of detection.","C":"Incorrect because independent external audits are still legally required for companies.","D":"Incorrect because ethical whistleblowing policies strictly protect reporters from retaliation."}}},{"id":"P1_U6_MCQ_457","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_457","question":"A construction company wins a major government highway contract, and it later emerges that the company's sales director paid $200,000 in secret bribes to government procurement officials. What are two likely consequences for the company?","options":{"A":"Heavy criminal fines, cancellation of the contract, and permanent blacklisting from future public-sector tenders","B":"A government award for business excellence and lower corporation tax","C":"Higher share prices and praise from ethical investment funds","D":"Automatic exemption from all anti-corruption laws"},"correctOption":"A","correctAnswer":"Heavy criminal fines, cancellation of the contract, and permanent blacklisting from future public-sector tenders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bribery carries severe criminal penalties, contract termination, reputational ruin, and exclusion from future government bids.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because corruption results in prosecution, not awards or tax cuts.","C":"Incorrect because bribery scandals cause share prices to plunge and ethical funds to divest.","D":"Incorrect because international anti-bribery laws prosecute corporate bribery strictly."}}},{"id":"P1_U6_MCQ_458","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_458","question":"A skincare brand commits to '100% Cruelty-Free' testing, refusing to test ingredients on animals and refusing to sell in markets that mandate animal testing. How does this ethical stance affect the business?","options":{"A":"It limits entry into certain overseas markets in the short term, but builds fierce loyalty among ethical consumers globally","B":"It forces the brand to test every cream on live animals","C":"It eliminates all product safety testing requirements","D":"It makes skincare ingredients completely free"},"correctOption":"A","correctAnswer":"It limits entry into certain overseas markets in the short term, but builds fierce loyalty among ethical consumers globally","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sticking to core ethical principles may require sacrificing certain sales channels while strengthening brand authenticity and customer devotion.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 'cruelty-free' means *no* animal testing.","C":"Incorrect because products still undergo modern non-animal dermatological safety testing.","D":"Incorrect because cruelty-free ingredients still carry normal purchasing costs."}}},{"id":"P1_U6_MCQ_459","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_459","question":"A large supermarket chain signs an ethical supplier charter promising never to cancel fresh produce orders at the last minute or force farmers to pay retroactive discounts after harvest. Why is this ethical practice commercially beneficial to the supermarket?","options":{"A":"Farmers trust the supermarket, invest in better crop quality, and prioritise supplying the supermarket during shortages","B":"Farmers stop growing vegetables completely","C":"The supermarket pays higher corporation tax on fruit sales","D":"Customers stop shopping at the supermarket"},"correctOption":"A","correctAnswer":"Farmers trust the supermarket, invest in better crop quality, and prioritise supplying the supermarket during shortages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because treating suppliers fairly builds long-term collaborative partnerships, reliable supply, and superior product quality.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because predictable contracts encourage farmers to invest and expand.","C":"Incorrect because fair supplier contracts do not increase corporation tax rates.","D":"Incorrect because consumers increasingly reward retailers that treat farmers fairly."}}},{"id":"P1_U6_MCQ_460","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_460","question":"A global sportswear company discovers that a sub-contractor two tiers down its supply chain is employing 13-year-old children in violation of international labour standards. What should the sportswear company do first?","options":{"A":"Intervene immediately to remove the children from factory work, fund their schooling and family income support, and enforce strict supplier audits","B":"Deny responsibility because the factory is a sub-contractor rather than directly owned","C":"Keep buying from the factory secretly because child labour is cheaper","D":"Fire the auditor who discovered the child labour"},"correctOption":"A","correctAnswer":"Intervene immediately to remove the children from factory work, fund their schooling and family income support, and enforce strict supplier audits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical brands take responsibility for their entire supply chain and remediate child labour in ways that protect the children's welfare and education.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumers and NGOs hold brands accountable for sub-contracted tier-2/tier-3 factories.","C":"Incorrect because tolerating child labour is a grave human rights violation and brand disaster.","D":"Incorrect because independent audits are vital for uncovering and fixing abuses."}}},{"id":"P1_U6_MCQ_461","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_461","question":"An electronics retailer introduces a '14-Day Honest Price Guarantee', automatically refunding the difference if an item goes on sale within two weeks of purchase, and trains staff never to pressure elderly customers into buying unnecessary extended warranties. How does this impact sales?","options":{"A":"It builds high customer trust, repeat business, and positive word-of-mouth referrals","B":"It causes customers to feel cheated and never return","C":"It violates consumer protection laws","D":"It eliminates all retail store rent expenses"},"correctOption":"A","correctAnswer":"It builds high customer trust, repeat business, and positive word-of-mouth referrals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because treating customers fairly and protecting vulnerable shoppers creates strong lifetime customer loyalty.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fair refunds and honest advice make customers feel respected.","C":"Incorrect because consumer laws encourage transparent, non-coercive selling.","D":"Incorrect because store rent is unaffected by customer service policies."}}},{"id":"P1_U6_MCQ_462","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_462","question":"Why do multinational businesses often find it challenging to apply a single global ethical code of conduct across all countries?","options":{"A":"Cultural norms around gift-giving, working hours, and local wage expectations differ across regions, requiring clear boundaries between cultural respect and core human rights","B":"Because ethical codes are illegal outside Europe and North America","C":"Because employees in overseas subsidiaries are not allowed to read company policies","D":"Because currency exchange rates change ethical principles every day"},"correctOption":"A","correctAnswer":"Cultural norms around gift-giving, working hours, and local wage expectations differ across regions, requiring clear boundaries between cultural respect and core human rights","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because global managers must navigate cultural differences (e.g., modest hospitality vs bribery) while upholding universal ethical standards.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because corporate codes of conduct are legal worldwide.","C":"Incorrect because MNCs translate and train local staff on their ethical codes.","D":"Incorrect because moral principles do not fluctuate with exchange rates."}}},{"id":"P1_U6_MCQ_463","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_463","question":"A telecommunications monopoly raises monthly broadband prices by 25% for loyal elderly customers who do not switch providers, while offering cheap deals only to new customers. How is this pricing practice viewed?","options":{"A":"Unethical exploitation of loyal or less tech-savvy customers ('loyalty penalty')","B":"Ethical corporate social responsibility supporting pensioners","C":"Penetration pricing to enter a brand-new market","D":"Cost-plus pricing based on falling broadband costs"},"correctOption":"A","correctAnswer":"Unethical exploitation of loyal or less tech-savvy customers ('loyalty penalty')","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because penalising loyal customers who struggle to compare tariffs is widely criticised as unfair and unethical.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because charging elderly customers more harms rather than supports them.","C":"Incorrect because penetration pricing sets *low* introductory prices, whereas this overcharges existing users.","D":"Incorrect because the price hike is driven by customer inertia, not rising costs."}}},{"id":"P1_U6_MCQ_464","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_464","question":"A manufacturing firm introduces a 'Suppliers' Diversity & Inclusion Programme', actively mentoring and awarding contracts to small businesses owned by women, ethnic minorities, and disabled entrepreneurs. What is a strategic benefit of this ethical initiative?","options":{"A":"It broadens the firm's supplier base, fosters fresh innovation, and strengthens community reputation","B":"It reduces product quality by ignoring supplier performance standards","C":"It eliminates all raw material costs","D":"It prevents the firm from selling to large corporate clients"},"correctOption":"A","correctAnswer":"It broadens the firm's supplier base, fosters fresh innovation, and strengthens community reputation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inclusive procurement widens competition among capable suppliers and enhances corporate reputation with clients and regulators.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supplier diversity programmes mentor diverse firms to meet full quality standards.","C":"Incorrect because suppliers are still paid fair commercial rates.","D":"Incorrect because many large corporate and government clients actively require supplier diversity from their contractors."}}},{"id":"P1_U6_MCQ_465","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_465","question":"A food delivery app company decides to pay for personal accident insurance, free safety helmets, and paid rest breaks for all its couriers, adding $3 million per year to operating costs. Which stakeholder group experiences a short-term financial trade-off?","options":{"A":"Shareholders, who may receive slightly lower short-term dividends while worker welfare improves","B":"Couriers, whose safety and benefits deteriorate","C":"Helmet manufacturers, who lose all sales","D":"Local hospitals, which treat more injured couriers"},"correctOption":"A","correctAnswer":"Shareholders, who may receive slightly lower short-term dividends while worker welfare improves","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because spending $3 million on courier safety reduces short-term distributable profit for shareholders in favour of employee/worker wellbeing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because couriers directly gain better safety gear and insurance.","C":"Incorrect because buying safety helmets increases orders for helmet makers.","D":"Incorrect because better safety equipment reduces serious courier injuries."}}},{"id":"P1_U6_MCQ_466","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_466","question":"An investment bank discovers that one of its top-earning traders achieved huge profits by secretly manipulating market prices, breaking both ethical rules and financial regulations. What is the most ethical leadership response?","options":{"A":"Dismiss the trader, return ill-gotten gains, self-report the breach to financial regulators, and tighten internal controls","B":"Promote the trader and give him a larger bonus because he made high profits","C":"Cover up the manipulation so regulators never find out","D":"Train all other traders to copy the same manipulation"},"correctOption":"A","correctAnswer":"Dismiss the trader, return ill-gotten gains, self-report the breach to financial regulators, and tighten internal controls","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical integrity requires rejecting profits earned through dishonesty, holding wrongdoers accountable, and cooperating with regulators.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rewarding misconduct destroys ethical culture and invites massive regulatory penalties.","C":"Incorrect because covering up financial crime compounds legal liability.","D":"Incorrect because institutionalising market manipulation would destroy the bank."}}},{"id":"P1_U6_MCQ_467","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_467","question":"A social media platform introduces default screen-time reminders and disables addictive infinite-scroll features for users under 18, even though this slightly reduces daily ad impressions. What does this decision demonstrate?","options":{"A":"Prioritising teenage mental wellbeing and digital ethics over maximum short-term advertising revenue","B":"Attempting to increase teen addiction to mobile screens","C":"Violating data protection laws","D":"Eliminating all users over the age of 18"},"correctOption":"A","correctAnswer":"Prioritising teenage mental wellbeing and digital ethics over maximum short-term advertising revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because voluntarily curbing addictive design features for minors puts user welfare above short-term ad clicks.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because disabling infinite scroll and adding reminders *reduces* addictive usage.","C":"Incorrect because protecting young users enhances responsible governance.","D":"Incorrect because adult users remain on the platform."}}},{"id":"P1_U6_MCQ_468","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_468","question":"Why might a business operating in a highly price-competitive, low-margin commodity industry (such as basic bulk gravel or unbranded sugar) find it harder to pass on higher ethical sourcing costs to customers than a branded coffee shop?","options":{"A":"Commodity buyers view the product as identical and switch immediately to the cheapest rival, whereas branded coffee drinkers are willing to pay a premium for ethical values","B":"Commodity businesses are legally forbidden from behaving ethically","C":"Branded coffee shops never pay for raw coffee beans","D":"Gravel quarries do not have any employees or suppliers"},"correctOption":"A","correctAnswer":"Commodity buyers view the product as identical and switch immediately to the cheapest rival, whereas branded coffee drinkers are willing to pay a premium for ethical values","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because brand differentiation allows consumer-facing firms to monetise ethical values via price premiums, whereas undifferentiated commodities compete purely on price.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all businesses can behave ethically, though cost recovery differs by market structure.","C":"Incorrect because coffee shops purchase roasted coffee beans at significant cost.","D":"Incorrect because quarries employ workers and use equipment suppliers."}}},{"id":"P1_U6_MCQ_469","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_469","question":"A clothing company publishes a list of every single factory it uses worldwide, including factory addresses, worker numbers, and recent independent audit scores, on its public website. How does this 'supply-chain transparency' benefit the company?","options":{"A":"It demonstrates accountability, builds trust with consumers and human rights NGOs, and deters factory abuses","B":"It allows the company to hide sweatshop conditions from the public","C":"It lowers import tariffs to zero automatically","D":"It stops competitors from ever making clothes"},"correctOption":"A","correctAnswer":"It demonstrates accountability, builds trust with consumers and human rights NGOs, and deters factory abuses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because radical transparency proves the brand has nothing to hide and invites constructive accountability across its supply network.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because publishing factory locations makes conditions *visible*, not hidden.","C":"Incorrect because tariff rates are set by customs laws, not website disclosures.","D":"Incorrect because competitors still operate normally."}}},{"id":"P1_U6_MCQ_470","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_470","question":"When a supermarket chain donates 1% of its pre-tax profits every year to local youth sports clubs and community food pantries, which term best describes this activity?","options":{"A":"Corporate Social Responsibility (CSR) and community philanthropy","B":"Hostile horizontal takeover","C":"Price discrimination","D":"Tax evasion"},"correctOption":"A","correctAnswer":"Corporate Social Responsibility (CSR) and community philanthropy","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because voluntary financial and social contributions to improve local community wellbeing are a core pillar of CSR.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a takeover involves acquiring a rival company.","C":"Incorrect because price discrimination involves charging different customer groups different prices.","D":"Incorrect because charitable donations are legitimate CSR, not illegal tax evasion."}}},{"id":"P1_U6_MCQ_471","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_471","question":"A recruitment agency removes candidates' names, photos, addresses, and university names from job applications before sending them to hiring managers ('blind recruitment'). What ethical goal does this achieve?","options":{"A":"Preventing unconscious bias based on gender, ethnicity, age, or social background so hiring is based strictly on skills and merit","B":"Ensuring only candidates from wealthy neighbourhoods are hired","C":"Making it impossible to contact successful candidates for interviews","D":"Lowering the statutory minimum wage for new hires"},"correctOption":"A","correctAnswer":"Preventing unconscious bias based on gender, ethnicity, age, or social background so hiring is based strictly on skills and merit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because anonymising personal identifiers promotes genuine equal opportunity and fair merit-based selection.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because removing addresses eliminates postcode/wealth bias.","C":"Incorrect because HR retains contact details separately to invite shortlisted candidates.","D":"Incorrect because blind recruitment ensures fair selection, not lower wages."}}},{"id":"P1_U6_MCQ_472","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_472","question":"A fast-food restaurant advertises a 'Giant Double Steak Burger' using professional food styling where the burger looks twice as large as the actual sandwich served to customers. Why is this an ethical and legal issue?","options":{"A":"Misleading advertising deceives consumers, breaches advertising standards codes, and damages customer trust","B":"Customers always enjoy receiving smaller portions than advertised","C":"Food photography is illegal in all restaurants","D":"Smaller burgers increase customer satisfaction scores"},"correctOption":"A","correctAnswer":"Misleading advertising deceives consumers, breaches advertising standards codes, and damages customer trust","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because deceptive product representation violates ethical marketing principles and consumer protection rules.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because feeling misled frustrates customers and reduces repeat visits.","C":"Incorrect because accurate food photography is completely legal.","D":"Incorrect because unmet expectations lower customer satisfaction."}}},{"id":"P1_U6_MCQ_473","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_473","question":"A company's Board of Directors links 25% of senior executives' annual bonuses to achieving verified targets for workplace safety, staff retention, and carbon reduction alongside financial profit. Why is this governance structure effective?","options":{"A":"It aligns managers' personal financial incentives with long-term ethical and sustainable performance rather than short-term profit alone","B":"It guarantees that the company will never make any profit","C":"It encourages managers to ignore workplace safety","D":"It eliminates the need for employees to follow safety rules"},"correctOption":"A","correctAnswer":"It aligns managers' personal financial incentives with long-term ethical and sustainable performance rather than short-term profit alone","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tying executive pay to non-financial ethical metrics ensures leaders treat ethics as a core strategic priority.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 75% of the bonus remains tied to financial performance and sustainable firms remain profitable.","C":"Incorrect because linking bonuses to safety motivates managers to *improve* safety.","D":"Incorrect because all workers and managers must follow safety procedures."}}},{"id":"P1_U6_MCQ_474","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_474","question":"A global coffee chain closes all 8,000 of its stores for one afternoon—losing millions of dollars in daily sales—to conduct mandatory anti-bias and inclusive customer service training for all 175,000 employees after an incident in one store. Why did management make this costly decision?","options":{"A":"To demonstrate genuine commitment to ethical values, repair brand reputation, and prevent future discrimination across the chain","B":"Because the company wanted to permanently go out of business","C":"Because coffee beans had become illegal to sell","D":"To avoid paying employees their afternoon wages"},"correctOption":"A","correctAnswer":"To demonstrate genuine commitment to ethical values, repair brand reputation, and prevent future discrimination across the chain","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because decisive, visible investment in staff values protects long-term brand equity even at high short-term revenue cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the closure was for a single afternoon to strengthen the brand's future.","C":"Incorrect because coffee sales resumed immediately after training.","D":"Incorrect because staff were paid to attend the mandatory training session."}}},{"id":"P1_U6_MCQ_475","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_475","question":"How can unethical business practices in a single company eventually lead to stricter government laws affecting the entire industry?","options":{"A":"Public scandals and media outrage force governments to pass new regulations that impose higher compliance costs on all firms in the sector","B":"Governments reward unethical scandals by removing all industry regulations","C":"Unethical scandals automatically reduce compliance costs for competitors","D":"Lawmakers ignore all major corporate scandals"},"correctOption":"A","correctAnswer":"Public scandals and media outrage force governments to pass new regulations that impose higher compliance costs on all firms in the sector","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when businesses fail to self-regulate ethically, governments step in with statutory laws to protect stakeholders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because scandals prompt *tighter*, not looser, regulation.","C":"Incorrect because new statutory rules raise compliance costs across the industry.","D":"Incorrect because public outcry pressures politicians to legislate."}}},{"id":"P1_U6_MCQ_476","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_476","question":"What is the primary difference between a pressure group and a political party?","options":{"A":"A pressure group seeks to influence specific business practices or government policies on particular issues without seeking to form the government itself","B":"A pressure group runs candidates to become prime minister and run the whole country","C":"A pressure group is a profit-making public limited company","D":"A pressure group has the legal authority to pass criminal laws"},"correctOption":"A","correctAnswer":"A pressure group seeks to influence specific business practices or government policies on particular issues without seeking to form the government itself","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pressure groups focus on advocating specific causes (environmental, consumer, ethical) rather than winning general elections to govern.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because contesting elections to form a government is the role of a political party.","C":"Incorrect because pressure groups are non-profit advocacy organisations.","D":"Incorrect because only parliaments/governments pass laws; pressure groups lobby lawmakers."}}},{"id":"P1_U6_MCQ_477","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_477","question":"An animal welfare pressure group launches a viral social media video campaign exposing cramped cage conditions at a large egg producer, using a hashtag that trends nationally for two weeks. How does social media increase pressure group power?","options":{"A":"It allows pressure groups to reach millions of consumers instantly at very low cost, threatening rapid brand damage","B":"It legally forces supermarkets to close down within 24 hours","C":"It prevents consumers from reading any news about the company","D":"It eliminates the egg producer's feed and electricity expenses"},"correctOption":"A","correctAnswer":"It allows pressure groups to reach millions of consumers instantly at very low cost, threatening rapid brand damage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because viral digital campaigns amplify negative publicity at negligible cost, putting immediate reputational pressure on consumer brands.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because social media generates reputational pressure, not automatic legal closure.","C":"Incorrect because viral posts *spread* information widely rather than hiding it.","D":"Incorrect because operating expenses are unaffected by social media hashtags."}}},{"id":"P1_U6_MCQ_478","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_478","question":"During a consumer boycott organised by an environmental pressure group against a bottled-water brand, what is the immediate financial risk to the targeted business?","options":{"A":"Falling sales revenue and excess unsold inventory while fixed factory and marketing overheads continue","B":"An immediate 50% increase in profit margins","C":"A government subsidy compensating the firm for lost sales","D":"Automatic elimination of all fixed overhead costs"},"correctOption":"A","correctAnswer":"Falling sales revenue and excess unsold inventory while fixed factory and marketing overheads continue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because boycotts reduce cash inflows from sales while fixed costs still have to be paid, squeezing profits and cash flow.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower sales volumes reduce rather than increase profits.","C":"Incorrect because governments do not compensate firms for consumer boycotts.","D":"Incorrect because rent, salaries, and loan interest remain payable."}}},{"id":"P1_U6_MCQ_479","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_479","question":"A road-safety pressure group presents detailed crash statistics to transport ministers, persuading the government to make automatic emergency braking mandatory in all new cars. How has this pressure group affected car manufacturers?","options":{"A":"Indirectly, by successfully lobbying the government to introduce new legal safety standards that manufacturers must obey","B":"Directly, by buying 51% of shares in every car manufacturer","C":"By banning all citizens from owning cars","D":"By lowering car manufacturing costs to zero"},"correctOption":"A","correctAnswer":"Indirectly, by successfully lobbying the government to introduce new legal safety standards that manufacturers must obey","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pressure groups frequently influence business operations indirectly by convincing governments to legislate.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the group used political lobbying, not a corporate takeover.","C":"Incorrect because cars remain legal with enhanced safety equipment.","D":"Incorrect because adding mandatory safety sensors increases unit production costs."}}},{"id":"P1_U6_MCQ_480","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_480","question":"Why is a pressure group campaign against a well-known high-street fashion retailer much more likely to succeed than a campaign against an anonymous mining company that sells raw iron ore only to steel mills?","options":{"A":"The fashion retailer relies directly on consumer brand image and faces thousands of retail competitors, whereas the mining firm has no direct retail shoppers to boycott it","B":"Mining companies are legally immune from all environmental laws","C":"Fashion retailers never care about sales revenue","D":"Iron ore mining has zero impact on the environment"},"correctOption":"A","correctAnswer":"The fashion retailer relies directly on consumer brand image and faces thousands of retail competitors, whereas the mining firm has no direct retail shoppers to boycott it","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because business-to-consumer (B2C) brands are highly sensitive to public reputation and consumer boycotts, unlike behind-the-scenes B2B commodity suppliers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mining companies must obey environmental regulations.","C":"Incorrect because fashion retailers depend heavily on sales and brand appeal.","D":"Incorrect because mining has major environmental impacts, making it a target for lobbying rather than retail boycotts."}}},{"id":"P1_U6_MCQ_481","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_481","question":"A disability rights pressure group audits the websites of 20 major online supermarkets and publishes a league table ranking them from most accessible to least accessible for blind and visually impaired shoppers. Why is publishing a league table effective?","options":{"A":"Low-ranked supermarkets suffer public embarrassment and risk losing disabled shoppers and their families to higher-ranked rivals","B":"League tables legally shut down the bottom ten supermarkets","C":"Supermarkets prefer finishing at the bottom of public customer-service rankings","D":"Blind shoppers never buy groceries online"},"correctOption":"A","correctAnswer":"Low-ranked supermarkets suffer public embarrassment and risk losing disabled shoppers and their families to higher-ranked rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because comparative public scorecards create peer competition and reputational pressure for laggards to improve.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because NGO league tables create reputational pressure, not legal closures.","C":"Incorrect because retailers strive to avoid negative public rankings.","D":"Incorrect because accessible online grocery shopping is hugely valuable for visually impaired customers."}}},{"id":"P1_U6_MCQ_482","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_482","question":"A local residents' pressure group opposes a delivery depot operating heavy lorries through narrow residential streets at 3:00 AM. How can the depot manager constructively resolve the conflict?","options":{"A":"Meet with resident representatives, restrict heavy lorry movements to daytime hours, and reroute vehicles onto the main ring road","B":"Increase 3:00 AM lorry deliveries through the residential streets","C":"Refuse to speak to residents and ignore noise complaints","D":"Close the entire business permanently without exploring route changes"},"correctOption":"A","correctAnswer":"Meet with resident representatives, restrict heavy lorry movements to daytime hours, and reroute vehicles onto the main ring road","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because constructive stakeholder dialogue and practical operational adjustments resolve local friction without sacrificing the business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because worsening the noise nuisance would provoke council enforcement and protests.","C":"Incorrect because ignoring valid community complaints risks local council night-time bans.","D":"Incorrect because adjusting delivery times and routes solves the problem without closing the depot."}}},{"id":"P1_U6_MCQ_483","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_483","question":"A pressure group calls for a boycott of the only pharmaceutical manufacturer producing a life-saving insulin medicine over high prices. Why will diabetic patients not participate in a consumer boycott?","options":{"A":"Insulin is a vital life-saving necessity with no immediate substitute, so patients must keep buying it to survive","B":"Diabetic patients do not care about medicine prices","C":"Pharmaceutical companies give away all medicines for free","D":"Pressure groups are legally banned from criticising drug prices"},"correctOption":"A","correctAnswer":"Insulin is a vital life-saving necessity with no immediate substitute, so patients must keep buying it to survive","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because boycotts fail when the product is an essential necessity lacking close substitutes; pressure groups must instead lobby health regulators.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because patients care deeply about high prices, which is why advocates lobby governments for price caps.","C":"Incorrect because commercial drugmakers charge prices to recover R&D and earn profits.","D":"Incorrect because advocacy groups regularly campaign on medicine affordability."}}},{"id":"P1_U6_MCQ_484","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_484","question":"A coalition of 40 environmental and consumer pressure groups forms a joint campaign demanding a ban on toxic 'forever chemicals' (PFAS) in non-stick frying pans. Why is a coalition more effective than a single small pressure group?","options":{"A":"Pooling funds, scientific researchers, media contacts, and millions of members creates far stronger political and commercial leverage","B":"Coalitions are legally allowed to pass laws without Parliament","C":"Coalitions eliminate all manufacturing costs for cookware firms","D":"Single small pressure groups always have more money than 40 groups combined"},"correctOption":"A","correctAnswer":"Pooling funds, scientific researchers, media contacts, and millions of members creates far stronger political and commercial leverage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because uniting multiple organisations amplifies credibility, financial backing, and voter/consumer reach.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because coalitions still lobby lawmakers rather than passing laws themselves.","C":"Incorrect because switching away from PFAS requires R&D into alternative coatings.","D":"Incorrect because combining 40 organisations pools vastly greater resources."}}},{"id":"P1_U6_MCQ_485","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_485","question":"After pressure groups campaign against palm oil linked to rainforest deforestation, a biscuit manufacturer switches to 100% certified sustainable palm oil (RSPO) and partners with the conservation group to audit its plantations. What is a financial cost and a financial benefit of this decision?","options":{"A":"Cost: higher raw ingredient prices and auditing fees; Benefit: protected brand reputation and continued sales to eco-conscious shoppers and supermarkets","B":"Cost: lower ingredient prices; Benefit: loss of all supermarket contracts","C":"Cost: zero expenses; Benefit: automatic exemption from corporation tax","D":"Cost: closure of all biscuit factories; Benefit: lower labour productivity"},"correctOption":"A","correctAnswer":"Cost: higher raw ingredient prices and auditing fees; Benefit: protected brand reputation and continued sales to eco-conscious shoppers and supermarkets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because responding positively to pressure groups raises input/audit costs in the short term while safeguarding long-term sales and retail listings.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because certified sustainable ingredients cost *more*, and supermarkets reward sustainable sourcing.","C":"Incorrect because certification carries real costs and does not waive corporation tax.","D":"Incorrect because the firm continues operating its factories."}}},{"id":"P1_U6_MCQ_486","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_486","question":"A local heritage pressure group campaigns to stop a supermarket chain from demolishing a historic 19th-century Victorian train station to build a car park. The supermarket revises its plans to restore the historic station building as the entrance hall of its new store. Why was this compromise smart?","options":{"A":"It won planning approval quickly, turned local critics into supporters, and created a distinctive, attractive store","B":"It prevented the supermarket from opening any store in the town","C":"It destroyed the historic building completely","D":"It eliminated all construction expenses"},"correctOption":"A","correctAnswer":"It won planning approval quickly, turned local critics into supporters, and created a distinctive, attractive store","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because adapting plans to address community concerns avoids costly legal planning delays and builds local goodwill.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the compromise enabled the store to open.","C":"Incorrect because the historic facade was restored rather than demolished.","D":"Incorrect because restoring a heritage building adds some upfront renovation expense."}}},{"id":"P1_U6_MCQ_487","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_487","question":"Why might a fast-food chain choose to reformulate its menu to lower salt and saturated fat levels after a health pressure group announces an upcoming national awareness campaign?","options":{"A":"To pre-empt negative media coverage, avoid potential government taxes, and appeal to increasingly health-conscious families","B":"Because salt and fat are illegal in all food products","C":"Because pressure groups pay half of the restaurant's rent","D":"To reduce customer visits by 50%"},"correctOption":"A","correctAnswer":"To pre-empt negative media coverage, avoid potential government taxes, and appeal to increasingly health-conscious families","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because proactive adaptation neutralises bad publicity before it damages brand image and reduces the risk of statutory regulation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because salt and fat are legal ingredients, though high levels attract health criticism.","C":"Incorrect because pressure groups do not subsidise business rent.","D":"Incorrect because healthier options help retain health-conscious customers."}}},{"id":"P1_U6_MCQ_488","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_488","question":"When an oil company is targeted by climate protesters at major international sports events it sponsors, several sports governing bodies decide not to renew their sponsorship deals with the oil company. How has pressure group activity affected the oil company?","options":{"A":"It has lost valuable brand-building sponsorship platforms due to reputational risk felt by its commercial partners","B":"It has doubled its crude oil reserves automatically","C":"It has been exempted from paying environmental taxes","D":"It has gained free television advertising during all sports finals"},"correctOption":"A","correctAnswer":"It has lost valuable brand-building sponsorship platforms due to reputational risk felt by its commercial partners","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because secondary pressure on business partners (such as sports bodies, banks, or insurers) isolates targeted firms from mainstream marketing channels.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because losing sports sponsorships does not create oil reserves.","C":"Incorrect because sponsorship losses do not reduce taxes.","D":"Incorrect because losing sponsorship removes brand visibility at major events."}}},{"id":"P1_U6_MCQ_489","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_489","question":"A small fringe group with no scientific evidence claims on a blog that 5G mobile phone masts cause illness and demands that telecom companies dismantle all masts. Why will telecom companies ignore the demand to remove masts while publishing clear scientific safety facts?","options":{"A":"Dismantling masts would destroy an essential modern service, while the group lacks scientific credibility or broad public backing; calm factual PR reassures customers","B":"Telecom companies are legally required to dismantle masts whenever one person complains","C":"5G networks operate without any masts or antennas","D":"Scientific facts are banned from company websites"},"correctOption":"A","correctAnswer":"Dismantling masts would destroy an essential modern service, while the group lacks scientific credibility or broad public backing; calm factual PR reassures customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because businesses distinguish between credible, widely supported pressure groups and unfounded fringe claims, responding to the latter with factual communication.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because unfounded complaints do not trigger legal shutdowns.","C":"Incorrect because mobile networks physically require base-station masts.","D":"Incorrect because companies routinely publish independent health and safety data."}}},{"id":"P1_U6_MCQ_490","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_490","question":"A passenger-rights pressure group lobbies the government to force airlines to pay automatic cash compensation of $400 whenever a flight is delayed by more than three hours due to airline fault. How does this affect airlines' operations?","options":{"A":"It increases potential penalty costs for delays, motivating airlines to invest in better aircraft maintenance and realistic flight schedules","B":"It allows airlines to delay flights indefinitely without informing passengers","C":"It eliminates aviation fuel taxes for delayed flights","D":"It forces passengers to pay airlines $400 when a flight is delayed"},"correctOption":"A","correctAnswer":"It increases potential penalty costs for delays, motivating airlines to invest in better aircraft maintenance and realistic flight schedules","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer-protection laws achieved by pressure groups create financial penalties that push firms to improve reliability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mandatory compensation penalises, rather than encourages, avoidable delays.","C":"Incorrect because passenger compensation rules do not waive fuel taxes.","D":"Incorrect because the airline compensates the delayed passenger."}}},{"id":"P1_U6_MCQ_491","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_491","question":"An anti-gambling pressure group persuades television broadcasters and football clubs to stop accepting shirt sponsorships from online betting companies. What is the direct business impact on online betting firms?","options":{"A":"Loss of major mass-market advertising channels, making customer acquisition harder and potentially slowing revenue growth","B":"Lower corporation tax rates on gambling profits","C":"Automatic doubling of active online gamblers","D":"Elimination of all website server costs"},"correctOption":"A","correctAnswer":"Loss of major mass-market advertising channels, making customer acquisition harder and potentially slowing revenue growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because restricting high-visibility sponsorship channels limits a firm's promotional mix and brand exposure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because advertising restrictions do not lower tax rates.","C":"Incorrect because losing major sports visibility tends to slow customer sign-ups.","D":"Incorrect because IT and server overheads remain unchanged."}}},{"id":"P1_U6_MCQ_492","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_492","question":"How can a business's employees themselves act similarly to an internal pressure group on ethical and environmental issues?","options":{"A":"Skilled employees may sign open letters, threaten to resign, or refuse to work on projects they view as unethical or environmentally destructive","B":"Employees can pass national laws in Parliament during lunch breaks","C":"Employees can set the central bank's base interest rate","D":"Employees never care about the ethical reputation of their employer"},"correctOption":"A","correctAnswer":"Skilled employees may sign open letters, threaten to resign, or refuse to work on projects they view as unethical or environmentally destructive","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because modern employees—especially scarce tech and professional staff—frequently push management to drop unethical contracts or adopt green targets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because only elected legislatures pass national laws.","C":"Incorrect because central banks set monetary policy.","D":"Incorrect because workplace values strongly influence employee morale and retention."}}},{"id":"P1_U6_MCQ_493","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_493","question":"A consumer pressure group publishes test results showing that a popular brand of children's car seats fails high-speed side-impact safety tests, even though it passed older minimum legal tests. Why will the manufacturer recall and redesign the seat immediately?","options":{"A":"Because no parent will buy a car seat perceived as unsafe, so ignoring the report would permanently destroy the brand","B":"Because pressure groups have legal power to arrest company directors","C":"Because redesigning car seats costs zero money","D":"Because parents prefer cheaper car seats even if they fail crash tests"},"correctOption":"A","correctAnswer":"Because no parent will buy a car seat perceived as unsafe, so ignoring the report would permanently destroy the brand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because for safety-critical family products, credible independent safety criticism collapses demand overnight unless resolved immediately.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumer groups publish test results rather than exercising police arrest powers.","C":"Incorrect because product recalls and engineering redesigns are very costly, yet essential for survival.","D":"Incorrect because safety is the primary purchasing criterion for child car seats."}}},{"id":"P1_U6_MCQ_494","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_494","question":"A farming trade association (a business pressure group) lobbies the government to block imports of cheap foreign beef produced with growth hormones banned domestically. What is the trade association trying to achieve?","options":{"A":"Protect domestic farmers from lower-cost foreign competition by insisting imports meet the same strict production standards","B":"Lower domestic beef prices by 50% to hurt local farmers","C":"Ban domestic consumers from ever eating beef","D":"Increase corporation taxes on domestic farms"},"correctOption":"A","correctAnswer":"Protect domestic farmers from lower-cost foreign competition by insisting imports meet the same strict production standards","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because producer pressure groups lobby governments for trade rules and standards that protect their members' livelihoods and competitiveness.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because farmers' associations seek to protect farm incomes, not depress prices.","C":"Incorrect because beef farmers want consumers to buy domestic beef.","D":"Incorrect because trade associations lobby for lower, not higher, taxes on their industry."}}},{"id":"P1_U6_MCQ_495","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_495","question":"Why do pressure groups often time their protests, reports, and boycotts to coincide with major corporate events such as a new product launch or the holiday shopping season?","options":{"A":"Media interest and potential sales impact are highest at those moments, giving the pressure group maximum leverage","B":"Protests are illegal during all other months of the year","C":"Businesses close all their shops during the holiday shopping season","D":"Consumers stop reading news during product launches"},"correctOption":"A","correctAnswer":"Media interest and potential sales impact are highest at those moments, giving the pressure group maximum leverage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because targeting peak revenue periods and high-visibility media moments maximises the commercial pressure on executives to negotiate.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because peaceful protests are legal year-round.","C":"Incorrect because peak shopping seasons are when stores are busiest and most vulnerable to disruption.","D":"Incorrect because media attention around major launches amplifies the campaign's reach."}}},{"id":"P1_U6_MCQ_496","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_496","question":"A toy retailer stops selling plastic water pistols and war-themed toys after parents' pressure groups campaign against violent toys for young children. How does this decision affect the retailer?","options":{"A":"It loses sales from that specific product line, but strengthens its family-friendly brand image and wins approval from parents","B":"It is forced to close all its toy shops permanently","C":"It receives a government fine for changing its product range","D":"All other educational toys become impossible to sell"},"correctOption":"A","correctAnswer":"It loses sales from that specific product line, but strengthens its family-friendly brand image and wins approval from parents","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because aligning product assortments with target-market values sacrifices minor niche sales to reinforce core customer trust.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dropping one controversial toy line leaves the rest of the store thriving.","C":"Incorrect because retailers are free to choose which legal products they stock.","D":"Incorrect because educational and creative toys typically see stronger parent support."}}},{"id":"P1_U6_MCQ_497","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_497","question":"When evaluating the impact of a pressure group's boycott on a multinational business, why is it important to consider whether the boycott is local or international?","options":{"A":"A boycott limited to one small town barely affects a global MNC's total revenue, whereas a coordinated international boycott across major markets threatens global profits","B":"A local boycott in one town always bankrupts a multinational corporation","C":"International boycotts have zero effect on multinational companies","D":"Multinational companies only sell products in one small town"},"correctOption":"A","correctAnswer":"A boycott limited to one small town barely affects a global MNC's total revenue, whereas a coordinated international boycott across major markets threatens global profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because scale matters: an MNC's geographic diversification insulates it from isolated local protests unless the campaign spreads internationally.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because one small town represents a tiny fraction of a global MNC's sales.","C":"Incorrect because global boycotts across key markets can severely hit MNC revenues and share prices.","D":"Incorrect because MNCs operate across multiple countries."}}},{"id":"P1_U6_MCQ_498","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_498","question":"A pressure group campaigns against a major bank's plans to close its last remaining rural bank branches, arguing that elderly residents and small rural shops will be unable to deposit cash. How could the bank respond to satisfy both cost-cutting goals and the pressure group?","options":{"A":"Share banking hubs with other banks in rural post offices or run mobile banking vans on scheduled days rather than leaving villages with zero service","B":"Close all branches immediately without offering any alternative services","C":"Keep every large, loss-making branch open 24 hours a day seven days a week","D":"Charge rural elderly customers $50 every time they check their balance"},"correctOption":"A","correctAnswer":"Share banking hubs with other banks in rural post offices or run mobile banking vans on scheduled days rather than leaving villages with zero service","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shared banking hubs and mobile vans cut fixed branch overheads while preserving essential community access and goodwill.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because total abandonment fuels fierce public and political backlash.","C":"Incorrect because keeping underused branches open 24/7 is financially unsustainable.","D":"Incorrect because punitive fees would outrage regulators and customers."}}},{"id":"P1_U6_MCQ_499","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_499","question":"How do pressure groups act as an 'early warning system' for forward-thinking business managers?","options":{"A":"They highlight emerging social, ethical, and environmental concerns early, giving proactive firms time to adapt before laws change or scandals erupt","B":"They secretly manage the business's daily payroll and accounting","C":"They guarantee that consumer tastes will never change","D":"They prevent governments from ever passing new regulations"},"correctOption":"A","correctAnswer":"They highlight emerging social, ethical, and environmental concerns early, giving proactive firms time to adapt before laws change or scandals erupt","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pressure group campaigns often signal future shifts in consumer expectations and legislation, enabling early movers to gain a competitive edge.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pressure groups are external bodies, not internal administrators.","C":"Incorrect because pressure groups actively drive changes in consumer attitudes.","D":"Incorrect because pressure groups frequently campaign *for* new regulations."}}},{"id":"P1_U6_MCQ_500","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_500","question":"A multinational food manufacturer faces sustained pressure group campaigns over plastic packaging, high sugar content, and supply-chain deforestation. Which comprehensive strategic response is most effective for long-term business survival?","options":{"A":"Set measurable, independently verified targets for recyclable packaging, healthier product reformulation, and deforestation-free sourcing, and report progress transparently","B":"Spend millions on misleading green adverts without changing any ingredients or packaging","C":"Ignore all pressure groups, consumers, and lawmakers until sales collapse","D":"Close the company and return all assets to the government"},"correctOption":"A","correctAnswer":"Set measurable, independently verified targets for recyclable packaging, healthier product reformulation, and deforestation-free sourcing, and report progress transparently","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because genuine operational reform backed by transparent verification addresses the root causes of external pressure and secures long-term competitiveness.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because greenwashing backfires severely when exposed by pressure groups and regulators.","C":"Incorrect because ignoring major external shifts in consumer and regulatory expectations leads to long-term decline.","D":"Incorrect because adapting products and supply chains allows the business to thrive profitably."}}},{"id":"P1_U6_MCQ_501","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_501","question":"What is meant by the term Gross Domestic Product (GDP)?","options":{"A":"The total monetary value of all final goods and services produced within a country in a given time period.","B":"The total amount of tax revenue collected by a government from private businesses each year.","C":"The percentage increase in the average price level of goods and services over twelve months.","D":"The difference between the value of a country's exports and the value of its imports."},"correctOption":"A","correctAnswer":"The total monetary value of all final goods and services produced within a country in a given time period.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross Domestic Product (GDP) measures the total value of output of goods and services produced inside an economy over a specific period, usually a year.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this describes government tax receipts rather than national economic output.","C":"Incorrect because a sustained rise in average prices defines inflation, not GDP.","D":"Incorrect because exports minus imports measures the trade balance on the balance of payments."}}},{"id":"P1_U6_MCQ_502","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_502","question":"What is meant by the economic term inflation?","options":{"A":"A period of two consecutive quarters of falling national output.","B":"A sustained increase in the average price level of goods and services in an economy over time.","C":"An increase in the external value of a country's currency against foreign currencies.","D":"A fall in the total number of people actively seeking paid employment."},"correctOption":"B","correctAnswer":"A sustained increase in the average price level of goods and services in an economy over time.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inflation is defined as a persistent rise in general prices across an economy, which reduces the purchasing power of money.","distractor_reasons":{"A":"Incorrect because two consecutive quarters of falling GDP defines an economic recession.","B":"Correct selection.","C":"Incorrect because a rise in a currency's value defines currency appreciation.","D":"Incorrect because a fall in job seekers relates to falling unemployment or a shrinking labour force."}}},{"id":"P1_U6_MCQ_503","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_503","question":"Which statement accurately defines unemployment?","options":{"A":"All citizens in a country who are retired, in full-time school, or unable to work.","B":"Workers who are employed on part-time contracts rather than full-time contracts.","C":"People who are willing and able to work at current wage rates but cannot find a job.","D":"Employees who voluntarily leave one job and start another job on the same day."},"correctOption":"C","correctAnswer":"People who are willing and able to work at current wage rates but cannot find a job.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unemployment includes individuals of working age who are actively seeking work and available to start, yet are without paid employment.","distractor_reasons":{"A":"Incorrect because retirees and full-time students are economically inactive rather than unemployed.","B":"Incorrect because part-time workers are classified as employed.","C":"Correct selection.","D":"Incorrect because moving immediately into another job involves no period of unemployment."}}},{"id":"P1_U6_MCQ_504","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_504","question":"What does the balance of payments record for a country?","options":{"A":"The total value of wages paid to public sector employees each year.","B":"The difference between government tax revenue and government expenditure.","C":"The total amount of money borrowed by private businesses from commercial banks.","D":"The financial record of all economic transactions between residents of a country and the rest of the world."},"correctOption":"D","correctAnswer":"The financial record of all economic transactions between residents of a country and the rest of the world.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the balance of payments records all international inflows and outflows of money, including exports and imports of goods and services.","distractor_reasons":{"A":"Incorrect because public sector wages are part of government expenditure, not international transactions.","B":"Incorrect because government revenue minus spending is the fiscal budget balance.","C":"Incorrect because domestic bank lending is recorded in domestic monetary statistics.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_505","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_505","question":"Which characteristics describe the growth stage of the business cycle?","options":{"A":"Rising GDP, falling unemployment, increasing consumer spending, and higher business investment.","B":"Falling GDP, rising business bankruptcies, and high spare factory capacity.","C":"Negative economic growth, collapsing business confidence, and rising redundancies.","D":"Minimum levels of national output, severe deflation, and mass long-term unemployment."},"correctOption":"A","correctAnswer":"Rising GDP, falling unemployment, increasing consumer spending, and higher business investment.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the growth stage is marked by expanding national output (GDP), rising employment, higher incomes, and growing business optimism.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because falling GDP and rising bankruptcies characterise a recession or slump.","C":"Incorrect because negative GDP growth and rising redundancies occur during a recession.","D":"Incorrect because the trough of lowest output and mass unemployment defines a slump."}}},{"id":"P1_U6_MCQ_506","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_506","question":"Which feature is most closely associated with the boom stage of the business cycle?","options":{"A":"Widespread spare production capacity and falling prices across most industries.","B":"Very high consumer demand, low unemployment, skill shortages, and rising inflationary pressure.","C":"Two consecutive quarters of declining Gross Domestic Product.","D":"High levels of cyclical unemployment and falling business profits."},"correctOption":"B","correctAnswer":"Very high consumer demand, low unemployment, skill shortages, and rising inflationary pressure.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an economic boom represents the peak of the business cycle, where rapid spending creates labour shortages, capacity bottlenecks, and rising inflation.","distractor_reasons":{"A":"Incorrect because spare capacity and falling prices occur during a slump.","B":"Correct selection.","C":"Incorrect because two quarters of falling GDP defines a recession.","D":"Incorrect because high cyclical unemployment occurs in recessions and slumps, not booms."}}},{"id":"P1_U6_MCQ_507","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_507","question":"How is an economic recession formally defined?","options":{"A":"A period when the annual inflation rate rises above 5%.","B":"A period when a country's exports exceed its imports.","C":"A period of negative economic growth where real GDP falls for two or more consecutive quarters.","D":"A period when commercial banks lower interest rates to stimulate borrowing."},"correctOption":"C","correctAnswer":"A period of negative economic growth where real GDP falls for two or more consecutive quarters.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because economists define a recession as at least two successive quarters (six months) of contracting real GDP.","distractor_reasons":{"A":"Incorrect because rising prices define inflation, which is distinct from falling national output.","B":"Incorrect because exports exceeding imports describes a trade surplus.","C":"Correct selection.","D":"Incorrect because cutting interest rates is a policy response to a downturn, not the definition of a recession."}}},{"id":"P1_U6_MCQ_508","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_508","question":"Which stage of the business cycle represents a prolonged and severe downturn with very high unemployment and low consumer confidence?","options":{"A":"Boom","B":"Recovery","C":"Expansion","D":"Slump"},"correctOption":"D","correctAnswer":"Slump","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a slump is the lowest trough of the business cycle, characterised by deep, prolonged contraction, business failures, and high unemployment.","distractor_reasons":{"A":"Incorrect because a boom is the peak of rapid growth and low unemployment.","B":"Incorrect because recovery occurs when GDP begins rising again after a downturn.","C":"Incorrect because expansion refers to sustained upward growth in GDP.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_509","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_509","question":"What is meant by fiscal policy?","options":{"A":"The use of government taxation and public expenditure to influence aggregate demand and economic activity.","B":"The control of interest rates and the money supply by a country's central bank.","C":"The imposition of import quotas and tariffs to restrict foreign competition.","D":"The setting of exchange rates by commercial currency traders."},"correctOption":"A","correctAnswer":"The use of government taxation and public expenditure to influence aggregate demand and economic activity.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fiscal policy involves government decisions on direct and indirect tax rates alongside government spending levels.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because changing interest rates and the money supply defines monetary policy.","C":"Incorrect because tariffs and quotas are trade protectionist measures.","D":"Incorrect because floating exchange rates are determined by market supply and demand."}}},{"id":"P1_U6_MCQ_510","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_510","question":"What is meant by monetary policy?","options":{"A":"Government changes to income tax and corporation tax rates.","B":"Central bank decisions regarding interest rates and the supply of money in the economy.","C":"Government spending on state schools, hospitals, and highways.","D":"Legal regulations setting minimum environmental standards for factories."},"correctOption":"B","correctAnswer":"Central bank decisions regarding interest rates and the supply of money in the economy.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because monetary policy regulates the cost of borrowing (interest rates) and money supply to control inflation and economic activity.","distractor_reasons":{"A":"Incorrect because changing tax rates is an instrument of fiscal policy.","B":"Correct selection.","C":"Incorrect because public infrastructure and social spending are components of fiscal policy.","D":"Incorrect because environmental rules are regulatory policies rather than monetary policy."}}},{"id":"P1_U6_MCQ_511","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_511","question":"What is the main aim of government supply-side policies?","options":{"A":"To reduce consumer spending by raising Value Added Tax on all goods.","B":"To increase import tariffs on foreign raw materials.","C":"To improve the productive efficiency, competitiveness, and long-term output capacity of the economy.","D":"To raise central bank interest rates to discourage business investment."},"correctOption":"C","correctAnswer":"To improve the productive efficiency, competitiveness, and long-term output capacity of the economy.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because supply-side policies (such as education, training, deregulation, and infrastructure investment) enhance productivity and long-run economic growth.","distractor_reasons":{"A":"Incorrect because raising VAT is a contractionary fiscal policy aimed at reducing demand.","B":"Incorrect because import tariffs are protectionist barriers rather than supply-side efficiency reforms.","C":"Correct selection.","D":"Incorrect because raising interest rates is contractionary monetary policy."}}},{"id":"P1_U6_MCQ_512","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_512","question":"What is a direct tax?","options":{"A":"A tax added onto the selling price of goods and services when they are purchased.","B":"A customs duty charged only on goods imported from abroad.","C":"A fee paid by consumers to obtain a passport or driving licence.","D":"A tax levied directly on the income of individuals or the profits of businesses."},"correctOption":"D","correctAnswer":"A tax levied directly on the income of individuals or the profits of businesses.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because direct taxes (such as income tax and corporation tax) are paid directly by individuals or companies to the government based on earnings or profits.","distractor_reasons":{"A":"Incorrect because a tax levied on spending on goods and services is an indirect tax.","B":"Incorrect because a customs duty on imports is an indirect trade tax (tariff).","C":"Incorrect because administrative fees for licences are user charges, not direct taxes on income.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_513","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_513","question":"Which of the following is the best definition of an indirect tax?","options":{"A":"A tax levied on expenditure on goods and services, collected by businesses on behalf of the government.","B":"A tax deducted directly from an employee's monthly salary.","C":"A tax paid by limited companies on their annual net profit.","D":"A tax paid by homeowners on the value of inherited property."},"correctOption":"A","correctAnswer":"A tax levied on expenditure on goods and services, collected by businesses on behalf of the government.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because indirect taxes (such as VAT, GST, and excise duties) are imposed on the purchase of goods and services rather than directly on income.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax deducted from wages is personal income tax, which is a direct tax.","C":"Incorrect because tax on company profits is corporation tax, which is a direct tax.","D":"Incorrect because wealth/inheritance taxes are direct taxes on assets."}}},{"id":"P1_U6_MCQ_514","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_514","question":"What is personal income tax?","options":{"A":"A tax paid by public limited companies on their retained profits.","B":"A direct tax levied on the wages, salaries, and other earnings of individuals.","C":"A sales tax added to restaurant meals and hotel rooms.","D":"A tax paid by exporters when shipping goods overseas."},"correctOption":"B","correctAnswer":"A direct tax levied on the wages, salaries, and other earnings of individuals.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because personal income tax is a direct tax charged on individuals' earned and unearned income.","distractor_reasons":{"A":"Incorrect because tax on limited company profits is corporation tax.","B":"Correct selection.","C":"Incorrect because tax on meals and hotels is an indirect sales tax (VAT).","D":"Incorrect because taxes on traded goods are customs duties/tariffs."}}},{"id":"P1_U6_MCQ_515","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_515","question":"What is corporation tax?","options":{"A":"An indirect tax charged on luxury imported vehicles.","B":"A tax paid by employees on their annual bonuses.","C":"A direct tax levied on the net profits made by limited companies.","D":"A tax charged on the total sales revenue of loss-making businesses."},"correctOption":"C","correctAnswer":"A direct tax levied on the net profits made by limited companies.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because corporation tax is a direct tax calculated as a percentage of a limited company's taxable profit.","distractor_reasons":{"A":"Incorrect because tax on imported vehicles is an import tariff or indirect excise tax.","B":"Incorrect because tax on employee bonuses is personal income tax.","C":"Correct selection.","D":"Incorrect because corporation tax is levied on profits, not revenue, so loss-making firms do not pay it."}}},{"id":"P1_U6_MCQ_516","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_516","question":"How are Value Added Tax (VAT) and Goods and Services Tax (GST) classified?","options":{"A":"Direct taxes on business profits","B":"Direct taxes on personal wealth","C":"Monetary policy instruments set by commercial banks","D":"Indirect taxes on consumer spending"},"correctOption":"D","correctAnswer":"Indirect taxes on consumer spending","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because VAT and GST are broad-based indirect taxes added to the price of goods and services bought by consumers.","distractor_reasons":{"A":"Incorrect because tax on business profits is corporation tax (a direct tax).","B":"Incorrect because VAT/GST taxes spending transactions rather than accumulated wealth.","C":"Incorrect because VAT/GST are fiscal tax policies set by governments, not commercial banks.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_517","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_517","question":"Which of the following is an example of government expenditure within fiscal policy?","options":{"A":"Public funding for state hospitals, national road networks, and state education.","B":"A commercial bank raising its mortgage interest rate.","C":"A private limited company paying dividends to its shareholders.","D":"A central bank buying foreign currency to manage the exchange rate."},"correctOption":"A","correctAnswer":"Public funding for state hospitals, national road networks, and state education.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because government expenditure includes public spending on healthcare, education, defence, welfare, and infrastructure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commercial mortgage rates reflect monetary policy and banking markets.","C":"Incorrect because dividend payments are private sector distributions to shareholders.","D":"Incorrect because foreign exchange intervention is a monetary/exchange-rate operation."}}},{"id":"P1_U6_MCQ_518","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_518","question":"What is an interest rate?","options":{"A":"The percentage of a company's profit paid to the government as corporation tax.","B":"The cost of borrowing money and the reward paid to savers for depositing money.","C":"The price of one country's currency expressed in terms of another currency.","D":"The annual percentage rise in consumer prices across an economy."},"correctOption":"B","correctAnswer":"The cost of borrowing money and the reward paid to savers for depositing money.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an interest rate represents the percentage fee charged on loans and the percentage return earned on savings.","distractor_reasons":{"A":"Incorrect because this describes the corporation tax rate.","B":"Correct selection.","C":"Incorrect because the price of one currency in terms of another is the exchange rate.","D":"Incorrect because the annual rise in prices is the inflation rate."}}},{"id":"P1_U6_MCQ_519","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_519","question":"How does a rise in central bank interest rates generally affect households and businesses?","options":{"A":"Borrowing becomes cheaper and saving becomes less attractive, causing spending to surge.","B":"Loan repayments fall and disposable incomes increase immediately.","C":"Borrowing becomes more expensive and saving becomes more attractive, reducing consumer and investment spending.","D":"Corporation tax rates automatically fall to offset higher loan costs."},"correctOption":"C","correctAnswer":"Borrowing becomes more expensive and saving becomes more attractive, reducing consumer and investment spending.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because higher interest rates increase debt servicing costs for borrowers and raise returns on bank deposits, dampening total spending.","distractor_reasons":{"A":"Incorrect because this describes the effect of a *cut* in interest rates.","B":"Incorrect because variable-rate loan and mortgage repayments *rise* when interest rates increase.","C":"Correct selection.","D":"Incorrect because monetary interest rate decisions do not automatically change fiscal tax rates."}}},{"id":"P1_U6_MCQ_520","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_520","question":"What is the direct effect of an increase in personal income tax rates on consumers?","options":{"A":"Gross wages increase automatically.","B":"Indirect taxes such as VAT are eliminated.","C":"Export prices become cheaper in foreign currencies.","D":"Household disposable income falls, reducing spending on non-essential goods."},"correctOption":"D","correctAnswer":"Household disposable income falls, reducing spending on non-essential goods.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because higher income tax deducts a larger share of gross earnings, leaving consumers with less net disposable income to spend.","distractor_reasons":{"A":"Incorrect because raising income tax reduces net take-home pay rather than raising gross wages.","B":"Incorrect because income tax changes do not eliminate indirect sales taxes.","C":"Incorrect because domestic income tax rates do not directly alter foreign exchange rates.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_521","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_521","question":"What is meant by disposable income?","options":{"A":"The income remaining for individuals to spend or save after direct taxes such as income tax have been deducted.","B":"Total gross salary before any income tax or social security deductions.","C":"The total revenue earned by a business before deducting operating expenses.","D":"Money borrowed by a household using high-interest credit cards."},"correctOption":"A","correctAnswer":"The income remaining for individuals to spend or save after direct taxes such as income tax have been deducted.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because disposable income is net personal income after direct taxes, representing actual household purchasing power.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because earnings before tax deductions are referred to as gross income.","C":"Incorrect because business income before expenses is sales revenue or turnover.","D":"Incorrect because credit card debt is borrowing, not earned income."}}},{"id":"P1_U6_MCQ_522","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_522","question":"Which combination of government actions represents expansionary fiscal policy?","options":{"A":"Increasing income tax rates and cutting public infrastructure spending.","B":"Cutting tax rates and increasing government expenditure to boost aggregate demand.","C":"Raising central bank interest rates and reducing the money supply.","D":"Imposing higher import tariffs and reducing export subsidies."},"correctOption":"B","correctAnswer":"Cutting tax rates and increasing government expenditure to boost aggregate demand.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because lowering taxes and raising government spending inject extra demand into the economy to stimulate growth and employment.","distractor_reasons":{"A":"Incorrect because higher taxes and lower public spending describe contractionary fiscal policy.","B":"Correct selection.","C":"Incorrect because raising interest rates is contractionary monetary policy.","D":"Incorrect because tariffs and export subsidies are trade policy instruments."}}},{"id":"P1_U6_MCQ_523","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_523","question":"Why does a central bank implement contractionary monetary policy by raising interest rates?","options":{"A":"To encourage households to borrow more money during a deep slump.","B":"To depreciate the domestic currency and boost import prices.","C":"To reduce excessive spending and borrowing in order to lower high inflation.","D":"To increase government budget deficits through higher tax cuts."},"correctOption":"C","correctAnswer":"To reduce excessive spending and borrowing in order to lower high inflation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because raising interest rates cools down overheated demand and slows rapid price increases.","distractor_reasons":{"A":"Incorrect because central banks *cut* interest rates during a slump to encourage borrowing.","B":"Incorrect because higher interest rates attract foreign capital and tend to *appreciate* the currency.","C":"Correct selection.","D":"Incorrect because tax cuts are fiscal policy, not monetary policy."}}},{"id":"P1_U6_MCQ_524","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_524","question":"What causes cost-push inflation in an economy?","options":{"A":"A rapid fall in raw material and energy prices across global markets.","B":"A severe recession causing high unemployment and falling wages.","C":"Government cuts to indirect sales taxes such as VAT.","D":"Rising production costs, such as higher wages or energy prices, forcing businesses to raise selling prices."},"correctOption":"D","correctAnswer":"Rising production costs, such as higher wages or energy prices, forcing businesses to raise selling prices.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cost-push inflation occurs when higher input costs (wages, oil, raw materials) squeeze profit margins and push businesses to pass higher prices onto consumers.","distractor_reasons":{"A":"Incorrect because falling input prices lower production costs and ease inflationary pressure.","B":"Incorrect because recessions reduce demand and usually lower inflation.","C":"Incorrect because cutting indirect taxes reduces final retail prices.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_525","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_525","question":"What is meant by economic growth?","options":{"A":"An increase in the real value of goods and services produced in an economy (real GDP) over time.","B":"A sustained rise in the general price level of consumer goods.","C":"An increase in the total number of unemployed workers in a country.","D":"A persistent deficit on the current account of the balance of payments."},"correctOption":"A","correctAnswer":"An increase in the real value of goods and services produced in an economy (real GDP) over time.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because economic growth measures the expansion of an economy's output of goods and services, typically tracked by annual percentage increases in real GDP.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rising general prices define inflation, not real output growth.","C":"Incorrect because rising unemployment is a symptom of economic contraction, not growth.","D":"Incorrect because a trade deficit reflects external trade flows rather than domestic output growth."}}},{"id":"P1_U6_MCQ_526","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_526","question":"What is meant by the term globalisation?","options":{"A":"The policy of banning all foreign imports to protect domestic industries.","B":"The growing integration and interdependence of national economies through cross-border trade, investment, and capital flows.","C":"The requirement that businesses sell their products only within their local town.","D":"The replacement of private sector businesses with state-owned monopolies."},"correctOption":"B","correctAnswer":"The growing integration and interdependence of national economies through cross-border trade, investment, and capital flows.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because globalisation describes the increasing interconnectedness of markets, production chains, and economies across the world.","distractor_reasons":{"A":"Incorrect because banning imports is extreme protectionism, the opposite of globalisation.","B":"Correct selection.","C":"Incorrect because globalisation expands business reach beyond local and national borders.","D":"Incorrect because state ownership is nationalisation, unrelated to globalisation."}}},{"id":"P1_U6_MCQ_527","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_527","question":"What is meant by free trade?","options":{"A":"Businesses giving away products to overseas customers without charging money.","B":"Trade controlled strictly by government import quotas and high customs duties.","C":"International trade between countries without artificial barriers such as tariffs, quotas, or embargoes.","D":"Trade that takes place only between businesses located inside the same city."},"correctOption":"C","correctAnswer":"International trade between countries without artificial barriers such as tariffs, quotas, or embargoes.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because free trade allows goods, services, and capital to cross national borders freely without government-imposed trade restrictions.","distractor_reasons":{"A":"Incorrect because 'free' refers to the absence of government trade barriers, not a zero price.","B":"Incorrect because quotas and customs duties define protectionism rather than free trade.","C":"Correct selection.","D":"Incorrect because free trade refers to unrestricted *international* commerce."}}},{"id":"P1_U6_MCQ_528","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_528","question":"What is protectionism in international trade?","options":{"A":"Removing all customs checks and import taxes between countries.","B":"Encouraging foreign multinational companies to take over domestic firms.","C":"A central bank policy of lowering interest rates to boost domestic borrowing.","D":"Government measures, such as tariffs and quotas, designed to shield domestic businesses from foreign competition."},"correctOption":"D","correctAnswer":"Government measures, such as tariffs and quotas, designed to shield domestic businesses from foreign competition.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because protectionism uses trade barriers to restrict imports and protect domestic industries and jobs from overseas rivals.","distractor_reasons":{"A":"Incorrect because removing trade barriers defines free trade.","B":"Incorrect because protectionism seeks to shield domestic producers rather than promote foreign takeovers.","C":"Incorrect because changing interest rates is monetary policy.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_529","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_529","question":"What is an import tariff?","options":{"A":"A government tax or customs duty placed on goods imported from abroad, raising their domestic selling price.","B":"A strict physical limit on the maximum quantity of a product allowed to enter a country.","C":"A financial grant paid by a government to help domestic exporters lower their prices.","D":"A total legal ban on all trade with a specific foreign country."},"correctOption":"A","correctAnswer":"A government tax or customs duty placed on goods imported from abroad, raising their domestic selling price.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a tariff is a customs tax levied on imports to make foreign goods more expensive relative to domestic substitutes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a physical limit on import volume defines an import quota.","C":"Incorrect because a financial grant to domestic producers is a subsidy.","D":"Incorrect because a complete legal ban on trade defines an embargo."}}},{"id":"P1_U6_MCQ_530","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_530","question":"What is an import quota?","options":{"A":"A percentage sales tax charged on all goods sold inside domestic shops.","B":"A physical restriction setting the maximum quantity or volume of a specific good that may be imported into a country.","C":"A currency exchange rate fixed permanently by the central bank.","D":"A trade agreement eliminating all barriers between neighbouring countries."},"correctOption":"B","correctAnswer":"A physical restriction setting the maximum quantity or volume of a specific good that may be imported into a country.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an import quota caps the physical number of units or weight of a foreign good permitted to enter the domestic market.","distractor_reasons":{"A":"Incorrect because a general sales tax is VAT or GST, not a quota.","B":"Correct selection.","C":"Incorrect because a fixed exchange rate is a currency regime, not a quantitative trade limit.","D":"Incorrect because eliminating trade barriers describes a free trade area."}}},{"id":"P1_U6_MCQ_531","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_531","question":"What is a key difference between an import tariff and an import quota?","options":{"A":"A tariff encourages free trade, whereas a quota restricts imports.","B":"A tariff applies only to services, whereas a quota applies only to agricultural crops.","C":"A tariff generates customs tax revenue for the government, whereas a quota sets a fixed physical limit on import volume without directly raising tax revenue.","D":"A tariff is imposed by private businesses, whereas a quota is imposed by consumers."},"correctOption":"C","correctAnswer":"A tariff generates customs tax revenue for the government, whereas a quota sets a fixed physical limit on import volume without directly raising tax revenue.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a tariff is a tax that raises government revenue while allowing unlimited imports if buyers pay the tax, whereas a quota caps import quantity directly.","distractor_reasons":{"A":"Incorrect because both tariffs and quotas are protectionist barriers that restrict trade.","B":"Incorrect because both instruments can be applied across manufactured and agricultural goods.","C":"Correct selection.","D":"Incorrect because both tariffs and quotas are government trade policy tools."}}},{"id":"P1_U6_MCQ_532","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_532","question":"What is a regional trade bloc?","options":{"A":"A single multinational company that controls 100% of global supply.","B":"A government department that collects corporation tax from sole traders.","C":"A complete ban on foreign direct investment within a continent.","D":"A group of countries that agree to reduce or eliminate trade barriers such as tariffs and quotas among member states."},"correctOption":"D","correctAnswer":"A group of countries that agree to reduce or eliminate trade barriers such as tariffs and quotas among member states.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a trade bloc (such as the EU, ASEAN, or USMCA) promotes free trade among member countries while often maintaining external rules for non-members.","distractor_reasons":{"A":"Incorrect because a single dominant firm is a monopoly, not an intergovernmental trade bloc.","B":"Incorrect because domestic tax collection is handled by a national revenue authority.","C":"Incorrect because trade blocs encourage, rather than ban, cross-border trade and investment among members.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_533","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_533","question":"What is the correct definition of a multinational company (MNC)?","options":{"A":"A business organisation that has operations, production facilities, or service outlets in more than one country.","B":"Any domestic business that sells its products to foreign tourists visiting its home country.","C":"A business that imports raw materials from abroad but operates factories in only one country.","D":"A public sector corporation owned jointly by the United Nations."},"correctOption":"A","correctAnswer":"A business organisation that has operations, production facilities, or service outlets in more than one country.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an MNC owns or controls physical production, distribution, or service operations across two or more sovereign countries.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because selling to foreign tourists inside one country does not constitute overseas operations.","C":"Incorrect because importing or exporting from a single home base makes a firm an international trader, not an MNC.","D":"Incorrect because MNCs are private sector commercial enterprises, not UN agencies."}}},{"id":"P1_U6_MCQ_534","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_534","question":"What distinguishes a multinational company (MNC) from a purely domestic exporting business?","options":{"A":"An exporting business never sells products to overseas customers.","B":"An MNC operates physical branches, factories, or offices in foreign countries, whereas an exporter produces only in its home country and ships goods abroad.","C":"An MNC is always owned by the government, whereas an exporter is always a sole trader.","D":"An exporting business never has to convert foreign currencies."},"correctOption":"B","correctAnswer":"An MNC operates physical branches, factories, or offices in foreign countries, whereas an exporter produces only in its home country and ships goods abroad.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because MNC status requires foreign direct investment and physical operations abroad, rather than merely exporting domestic output.","distractor_reasons":{"A":"Incorrect because exporters specifically sell domestically made goods to foreign buyers.","B":"Correct selection.","C":"Incorrect because most MNCs are public limited companies (plcs), and exporters can be companies of any size.","D":"Incorrect because exporters frequently receive foreign currency payments."}}},{"id":"P1_U6_MCQ_535","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_535","question":"In the context of multinational companies, what is meant by a 'host country'?","options":{"A":"The original country where the multinational company's global headquarters is registered.","B":"Any country that bans multinational companies from entering its market.","C":"A foreign country in which a multinational company establishes operations, factories, or retail outlets.","D":"A country that exports goods without allowing any imports."},"correctOption":"C","correctAnswer":"A foreign country in which a multinational company establishes operations, factories, or retail outlets.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a host country receives inward investment from a foreign-headquartered MNC setting up local operations.","distractor_reasons":{"A":"Incorrect because the country where the MNC originates and is headquartered is the *home* country.","B":"Incorrect because a host country welcomes or permits the MNC to operate within its borders.","C":"Correct selection.","D":"Incorrect because host countries participate in international investment and trade."}}},{"id":"P1_U6_MCQ_536","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_536","question":"In the context of multinational companies, what is meant by a 'home country'?","options":{"A":"A developing country where an MNC builds a low-cost assembly factory.","B":"Any country where an MNC sells its products through independent distributors.","C":"A tax-free island where an MNC holds offshore bank accounts.","D":"The country where the multinational company was founded and where its main headquarters is located."},"correctOption":"D","correctAnswer":"The country where the multinational company was founded and where its main headquarters is located.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the home country is the MNC's country of origin and parent headquarters.","distractor_reasons":{"A":"Incorrect because a foreign country hosting an assembly factory is a *host* country.","B":"Incorrect because foreign sales markets are host or export markets, not the home country.","C":"Incorrect because offshore financial centres are not necessarily the company's home headquarters.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_537","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_537","question":"What is meant by profit repatriation by a multinational company?","options":{"A":"Transferring profits earned by an overseas subsidiary in a host country back to the parent company in its home country.","B":"Reinvesting 100% of subsidiary profits into building schools in the host country.","C":"Paying higher wages to host-country workers than to home-country workers.","D":"Lowering export prices below production costs to eliminate foreign rivals."},"correctOption":"A","correctAnswer":"Transferring profits earned by an overseas subsidiary in a host country back to the parent company in its home country.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit repatriation occurs when an MNC sends after-tax profits generated abroad back to its home headquarters and shareholders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because charitable reinvestment in the host country keeps funds locally rather than repatriating them.","C":"Incorrect because wage policies do not define profit repatriation.","D":"Incorrect because selling below cost is predatory pricing or dumping."}}},{"id":"P1_U6_MCQ_538","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_538","question":"What is an exchange rate?","options":{"A":"The interest rate charged by a central bank on loans to commercial banks.","B":"The price of one currency expressed in terms of another currency.","C":"The percentage tariff charged on goods crossing an international border.","D":"The rate at which consumer prices rise over a twelve-month period."},"correctOption":"B","correctAnswer":"The price of one currency expressed in terms of another currency.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an exchange rate measures how much of one currency is required to buy one unit of another currency.","distractor_reasons":{"A":"Incorrect because this defines the base interest rate.","B":"Correct selection.","C":"Incorrect because customs taxes on borders are import tariffs.","D":"Incorrect because rising consumer prices define the inflation rate."}}},{"id":"P1_U6_MCQ_539","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_539","question":"What is meant by currency appreciation?","options":{"A":"A fall in the value of a currency relative to other currencies.","B":"A government ban on exchanging domestic currency for foreign currency.","C":"A rise in the value of a currency relative to other currencies, allowing one unit to buy more foreign currency.","D":"A decrease in the domestic price level of consumer goods."},"correctOption":"C","correctAnswer":"A rise in the value of a currency relative to other currencies, allowing one unit to buy more foreign currency.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because currency appreciation means a currency strengthens against foreign currencies, increasing its international purchasing power.","distractor_reasons":{"A":"Incorrect because a fall in a currency's external value is currency depreciation.","B":"Incorrect because restricting currency conversion is exchange control, not appreciation.","C":"Correct selection.","D":"Incorrect because a fall in domestic consumer prices is deflation."}}},{"id":"P1_U6_MCQ_540","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_540","question":"What is meant by currency depreciation?","options":{"A":"An increase in the external value of a currency against foreign currencies.","B":"The gradual wear and tear of factory machinery over its useful life.","C":"A sustained rise in domestic consumer prices caused by excessive demand.","D":"A fall in the value of a currency relative to other currencies, meaning each unit buys less foreign currency."},"correctOption":"D","correctAnswer":"A fall in the value of a currency relative to other currencies, meaning each unit buys less foreign currency.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because currency depreciation occurs when a currency weakens in foreign exchange markets against other currencies.","distractor_reasons":{"A":"Incorrect because an increase in a currency's exchange value is currency appreciation.","B":"Incorrect because accounting depreciation of fixed assets is distinct from currency exchange depreciation.","C":"Incorrect because rising domestic consumer prices define inflation.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_541","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_541","question":"How does an appreciation of a country's currency affect the foreign-currency price of its exports?","options":{"A":"Exports become more expensive for foreign buyers, reducing international price competitiveness.","B":"Exports become cheaper for foreign buyers, boosting overseas sales.","C":"Export prices remain completely unaffected in foreign currencies.","D":"Exports are automatically exempt from foreign import tariffs."},"correctOption":"A","correctAnswer":"Exports become more expensive for foreign buyers, reducing international price competitiveness.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when the domestic currency strengthens, overseas buyers must spend more of their own currency to purchase the same domestic goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because exports become cheaper when the currency *depreciates*, not appreciates.","C":"Incorrect because converting a fixed domestic price at a higher exchange rate raises the foreign price.","D":"Incorrect because exchange rate movements do not waive foreign customs tariffs."}}},{"id":"P1_U6_MCQ_542","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_542","question":"How does an appreciation of a country's currency affect the domestic-currency cost of imports?","options":{"A":"Imports become more expensive in domestic currency, raising costs for importers.","B":"Imports become cheaper in domestic currency, lowering costs for businesses buying foreign raw materials.","C":"Import prices double automatically in domestic currency.","D":"All foreign imports are banned by customs authorities."},"correctOption":"B","correctAnswer":"Imports become cheaper in domestic currency, lowering costs for businesses buying foreign raw materials.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a stronger domestic currency buys more foreign currency, reducing the local-currency cost of imported materials and finished goods.","distractor_reasons":{"A":"Incorrect because imports become more expensive when the currency *depreciates*.","B":"Correct selection.","C":"Incorrect because appreciation reduces, rather than doubles, import prices.","D":"Incorrect because currency appreciation does not impose import bans."}}},{"id":"P1_U6_MCQ_543","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_543","question":"How does a depreciation of a country's currency affect domestic exporting businesses?","options":{"A":"Their products become more expensive abroad, causing export sales to collapse.","B":"They must pay higher corporation tax on all overseas sales.","C":"Their products become cheaper in foreign currencies, improving export price competitiveness.","D":"They can no longer sell goods to customers outside their home country."},"correctOption":"C","correctAnswer":"Their products become cheaper in foreign currencies, improving export price competitiveness.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because currency depreciation lowers the foreign-currency price of domestically produced goods, making exports more attractive overseas.","distractor_reasons":{"A":"Incorrect because exports become dearer when the currency *appreciates*.","B":"Incorrect because currency depreciation does not raise corporation tax rates.","C":"Correct selection.","D":"Incorrect because depreciation encourages rather than stops exporting."}}},{"id":"P1_U6_MCQ_544","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_544","question":"How does a depreciation of a country's currency affect domestic businesses that rely on imported raw materials?","options":{"A":"Imported raw materials become cheaper in domestic currency, increasing profit margins.","B":"Foreign suppliers are forced to give away raw materials for free.","C":"Domestic interest rates fall automatically to offset import costs.","D":"Imported raw materials become more expensive in domestic currency, increasing production costs."},"correctOption":"D","correctAnswer":"Imported raw materials become more expensive in domestic currency, increasing production costs.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a weaker domestic currency requires more domestic currency units to pay foreign-currency invoices for imported inputs.","distractor_reasons":{"A":"Incorrect because imported inputs become cheaper only when the currency *appreciates*.","B":"Incorrect because foreign suppliers still charge their full foreign-currency prices.","C":"Incorrect because currency depreciation often creates imported inflation, which can actually push interest rates *up*.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_545","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_545","question":"What is a trade embargo?","options":{"A":"A complete government ban on trade with a particular country or on specific goods.","B":"A small customs tax placed on imported agricultural products.","C":"A financial subsidy given to domestic exporters.","D":"A free trade agreement signed between two neighbouring nations."},"correctOption":"A","correctAnswer":"A complete government ban on trade with a particular country or on specific goods.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an embargo is the strictest form of trade restriction, totally prohibiting exports to or imports from a targeted nation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a tax on imports is a tariff, not an embargo.","C":"Incorrect because financial aid to exporters is an export subsidy.","D":"Incorrect because an embargo blocks trade completely rather than creating free trade."}}},{"id":"P1_U6_MCQ_546","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_546","question":"How do government subsidies to domestic producers act as a form of protectionism?","options":{"A":"They raise the production costs of domestic firms so foreign imports look cheaper.","B":"They reduce domestic firms' production costs, allowing them to charge lower prices and outcompete foreign imports.","C":"They place a physical limit on the number of domestic firms allowed to operate.","D":"They tax domestic consumers for buying locally manufactured goods."},"correctOption":"B","correctAnswer":"They reduce domestic firms' production costs, allowing them to charge lower prices and outcompete foreign imports.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because subsidies lower domestic unit costs, enabling local businesses to undercut foreign rivals without directly taxing imports.","distractor_reasons":{"A":"Incorrect because subsidies *reduce*, rather than raise, domestic production costs.","B":"Correct selection.","C":"Incorrect because subsidies encourage domestic production rather than capping firm numbers.","D":"Incorrect because subsidies are paid *by* the government to producers, not charged as a tax on local goods."}}},{"id":"P1_U6_MCQ_547","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_547","question":"Which of the following is an example of a non-tariff barrier to international trade?","options":{"A":"A 15% customs duty levied on the value of imported cars.","B":"Removing all border inspections between countries in a single market.","C":"Complex technical regulations, strict safety certifications, and slow customs paperwork designed to delay or deter imports.","D":"A central bank lowering interest rates to stimulate domestic housing demand."},"correctOption":"C","correctAnswer":"Complex technical regulations, strict safety certifications, and slow customs paperwork designed to delay or deter imports.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because non-tariff barriers restrict imports through administrative red tape, bureaucratic delays, or discriminatory product standards rather than direct taxes.","distractor_reasons":{"A":"Incorrect because a 15% customs duty is a direct *tariff* barrier.","B":"Incorrect because removing border inspections facilitates free trade.","C":"Correct selection.","D":"Incorrect because interest rate changes are domestic monetary policy."}}},{"id":"P1_U6_MCQ_548","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_548","question":"What is meant by offshoring in a globalised economy?","options":{"A":"Closing all overseas branches and selling strictly within a single local town.","B":"Imposing high import tariffs on foreign manufactured components.","C":"Borrowing money exclusively from domestic commercial banks.","D":"Relocating business processes, manufacturing, or customer service operations to another country, often to reduce costs."},"correctOption":"D","correctAnswer":"Relocating business processes, manufacturing, or customer service operations to another country, often to reduce costs.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because offshoring shifts production or service functions across national borders, typically to take advantage of lower labour or operating costs.","distractor_reasons":{"A":"Incorrect because retrenching to a local market is the opposite of offshoring.","B":"Incorrect because tariffs are government trade taxes.","C":"Incorrect because domestic borrowing relates to business finance, not international location.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_549","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_549","question":"What is meant by Foreign Direct Investment (FDI) or inward investment?","options":{"A":"Investment made by a company based in one country into physical business operations, factories, or assets located in another country.","B":"A domestic household depositing money into a local high-street savings account.","C":"A government collecting Value Added Tax from domestic retail shops.","D":"A central bank printing new banknotes to finance public spending."},"correctOption":"A","correctAnswer":"Investment made by a company based in one country into physical business operations, factories, or assets located in another country.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because FDI occurs when multinational enterprises invest capital to establish or acquire productive facilities in a host nation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local household savings are domestic personal savings, not cross-border FDI.","C":"Incorrect because VAT collection is domestic fiscal taxation.","D":"Incorrect because printing currency is domestic monetary expansion."}}},{"id":"P1_U6_MCQ_550","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_550","question":"What is the 'infant industry' argument for temporary trade protectionism?","options":{"A":"Established multinational monopolies need permanent tariffs so they never face competition.","B":"Newly established domestic industries need temporary protection from large foreign rivals until they grow large enough to achieve economies of scale.","C":"Countries should ban all exports of baby food and children's clothing.","D":"Import tariffs permanently lower consumer prices in the domestic economy."},"correctOption":"B","correctAnswer":"Newly established domestic industries need temporary protection from large foreign rivals until they grow large enough to achieve economies of scale.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because emerging domestic industries initially have higher unit costs and need breathing space to build scale and efficiency before competing globally.","distractor_reasons":{"A":"Incorrect because the infant industry argument applies to *new*, emerging industries rather than established monopolies.","B":"Correct selection.","C":"Incorrect because 'infant industry' is an economic metaphor for newly formed industries, not baby products.","D":"Incorrect because tariffs raise, rather than lower, domestic consumer prices."}}},{"id":"P1_U6_MCQ_551","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_551","question":"What is meant by environmental social responsibility in business?","options":{"A":"Maximising short-term shareholder dividends regardless of pollution or resource depletion.","B":"Paying only the lowest possible wages permitted under national labour law.","C":"A business taking accountability for the impact of its activities on the natural environment and actively working to minimise ecological harm.","D":"Lobbying governments to remove all environmental protection regulations."},"correctOption":"C","correctAnswer":"A business taking accountability for the impact of its activities on the natural environment and actively working to minimise ecological harm.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because environmentally responsible businesses consider wider ecological stakeholders and reduce emissions, waste, and resource depletion.","distractor_reasons":{"A":"Incorrect because ignoring pollution for short-term profit is environmentally irresponsible.","B":"Incorrect because wage levels relate to employment ethics rather than environmental stewardship.","C":"Correct selection.","D":"Incorrect because weakening environmental laws increases ecological risk rather than demonstrating responsibility."}}},{"id":"P1_U6_MCQ_552","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_552","question":"What are the 'private costs' of a business activity?","options":{"A":"The costs of air pollution and traffic congestion suffered by local residents.","B":"The medical expenses paid by taxpayers due to factory smoke.","C":"The benefits enjoyed by society when a business plants public trees.","D":"The direct financial expenses paid by the business itself to produce goods or services, such as wages, rent, and raw materials."},"correctOption":"D","correctAnswer":"The direct financial expenses paid by the business itself to produce goods or services, such as wages, rent, and raw materials.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because private costs are internal monetary outlays incurred directly by the producer carrying out the economic activity.","distractor_reasons":{"A":"Incorrect because pollution and congestion borne by local residents are *external* costs.","B":"Incorrect because public healthcare costs imposed on third parties are external costs.","C":"Incorrect because positive spillovers to society are external *benefits*.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_553","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_553","question":"What is meant by an 'external cost' (negative externality)?","options":{"A":"A negative impact or cost imposed on uninvolved third parties outside the business as a result of its production or consumption activities.","B":"The cost of purchasing raw materials from an overseas supplier.","C":"The salary paid to a company's Chief Executive Officer.","D":"A positive benefit gained by local shops when a new railway station opens nearby."},"correctOption":"A","correctAnswer":"A negative impact or cost imposed on uninvolved third parties outside the business as a result of its production or consumption activities.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external costs occur when third parties (such as local residents or future generations) suffer damages not paid for by the business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raw material payments are internal private costs paid by the business.","C":"Incorrect because executive salaries are internal private costs.","D":"Incorrect because positive gains to third parties are external *benefits*."}}},{"id":"P1_U6_MCQ_554","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_554","question":"Which of the following is an example of an external cost created by manufacturing activity?","options":{"A":"The electricity bill paid by the factory owner each month.","B":"Toxic chemical waste discharged into a river, killing fish and harming local fishing communities.","C":"The wages paid to factory assembly workers.","D":"The sales revenue earned by the factory from selling finished products."},"correctOption":"B","correctAnswer":"Toxic chemical waste discharged into a river, killing fish and harming local fishing communities.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because river contamination imposes ecological and financial harm on third parties outside the manufacturing firm.","distractor_reasons":{"A":"Incorrect because the factory's electricity bill is a private cost paid by the business.","B":"Correct selection.","C":"Incorrect because worker wages are internal private costs.","D":"Incorrect because sales revenue is a private financial benefit to the business."}}},{"id":"P1_U6_MCQ_555","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_555","question":"What are the 'private benefits' of a business activity?","options":{"A":"Cleaner air enjoyed by city residents when a firm switches to electric vans.","B":"Reduced traffic congestion for local commuters.","C":"The direct financial gains received by the business itself, such as sales revenue and profit.","D":"The environmental damage caused by mining non-renewable minerals."},"correctOption":"C","correctAnswer":"The direct financial gains received by the business itself, such as sales revenue and profit.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because private benefits are the internal rewards captured directly by the producer or consumer involved in the transaction.","distractor_reasons":{"A":"Incorrect because cleaner air for the public is an *external* benefit.","B":"Incorrect because reduced congestion for commuters is an external benefit.","C":"Correct selection.","D":"Incorrect because environmental damage is an external cost."}}},{"id":"P1_U6_MCQ_556","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_556","question":"What is meant by an 'external benefit' (positive externality)?","options":{"A":"The profit retained by a limited company after paying corporation tax.","B":"The noise pollution experienced by households living near a busy airport.","C":"The cost of raw materials purchased by a construction firm.","D":"A positive advantage or gain enjoyed by third parties outside the business as a result of its activities."},"correctOption":"D","correctAnswer":"A positive advantage or gain enjoyed by third parties outside the business as a result of its activities.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because external benefits arise when a business's operations create positive spillovers for wider society without receiving direct payment for them.","distractor_reasons":{"A":"Incorrect because retained profit is an internal private benefit to the company.","B":"Incorrect because airport noise is an external *cost*.","C":"Incorrect because raw material purchases are internal private costs.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_557","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_557","question":"Which of the following is the best example of an external benefit?","options":{"A":"A private training college educating skilled workers who subsequently boost productivity across other local businesses.","B":"A factory releasing thick black smoke that dirties nearby houses.","C":"A supermarket paying rent to its commercial landlord.","D":"A delivery lorry causing traffic delays on a public motorway."},"correctOption":"A","correctAnswer":"A private training college educating skilled workers who subsequently boost productivity across other local businesses.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a better-educated workforce creates productivity and tax gains for wider society beyond the college's private fee income.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because factory smoke creates an external *cost*.","C":"Incorrect because rent is a private cost paid by the supermarket.","D":"Incorrect because traffic congestion is an external *cost*."}}},{"id":"P1_U6_MCQ_558","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_558","question":"How are 'social costs' defined in economics and business studies?","options":{"A":"Private costs minus external costs.","B":"The sum of private costs paid by the business and external costs imposed on the rest of society.","C":"Only the charitable donations made by a business each year.","D":"Private benefits plus external benefits."},"correctOption":"B","correctAnswer":"The sum of private costs paid by the business and external costs imposed on the rest of society.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because social cost captures the full cost to society of an activity: Social Cost = Private Cost + External Cost.","distractor_reasons":{"A":"Incorrect because external costs must be *added* to private costs, not subtracted.","B":"Correct selection.","C":"Incorrect because charitable donations are voluntary CSR expenditure, not total social costs.","D":"Incorrect because private benefits plus external benefits equals *social benefits*."}}},{"id":"P1_U6_MCQ_559","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_559","question":"How are 'social benefits' defined?","options":{"A":"Private benefits minus external benefits.","B":"Private costs plus external costs.","C":"The sum of private benefits received by the business and external benefits gained by wider society.","D":"Government welfare payments paid to unemployed citizens."},"correctOption":"C","correctAnswer":"The sum of private benefits received by the business and external benefits gained by wider society.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social benefit measures the total positive value generated for everyone: Social Benefit = Private Benefit + External Benefit.","distractor_reasons":{"A":"Incorrect because external benefits are added to private benefits, not subtracted.","B":"Incorrect because private costs plus external costs defines *social costs*.","C":"Correct selection.","D":"Incorrect because state welfare payments are government transfer payments, not the formula for social benefits."}}},{"id":"P1_U6_MCQ_560","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_560","question":"What is the purpose of cost-benefit analysis (CBA) when evaluating a major project?","options":{"A":"To calculate only the private financial profit earned by shareholders.","B":"To ignore all environmental pollution and community impacts.","C":"To determine the exact exchange rate between two currencies.","D":"To compare total social benefits against total social costs—including external impacts—to decide whether a project benefits society overall."},"correctOption":"D","correctAnswer":"To compare total social benefits against total social costs—including external impacts—to decide whether a project benefits society overall.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cost-benefit analysis incorporates both private and external costs and benefits to assess net social welfare.","distractor_reasons":{"A":"Incorrect because private profit calculation ignores external costs and benefits.","B":"Incorrect because CBA explicitly includes environmental and community externalities.","C":"Incorrect because exchange rates are determined in foreign exchange markets.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_561","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_561","question":"What is the standard definition of sustainable development?","options":{"A":"Development that meets the needs of the present without compromising the ability of future generations to meet their own needs.","B":"Maximising rapid industrial growth today even if all natural resources are permanently exhausted.","C":"Closing all private sector businesses and returning to subsistence farming.","D":"Using exclusively non-renewable coal and oil to keep short-term electricity prices low."},"correctOption":"A","correctAnswer":"Development that meets the needs of the present without compromising the ability of future generations to meet their own needs.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainable development balances present economic needs with long-term environmental conservation and intergenerational fairness.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because exhausting finite resources destroys future capacity and is unsustainable.","C":"Incorrect because sustainable development seeks responsible growth, not halting economic progress.","D":"Incorrect because reliance on finite fossil fuels undermines long-term sustainability."}}},{"id":"P1_U6_MCQ_562","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_562","question":"What is the difference between a renewable resource and a non-renewable resource?","options":{"A":"Renewable resources cannot be used to generate electricity, whereas non-renewable resources can.","B":"Renewable resources can be naturally replenished over time, whereas non-renewable resources exist in finite quantities that are depleted when used.","C":"Renewable resources are always more expensive than non-renewable resources.","D":"Non-renewable resources include solar and wind energy, whereas renewable resources include coal and crude oil."},"correctOption":"B","correctAnswer":"Renewable resources can be naturally replenished over time, whereas non-renewable resources exist in finite quantities that are depleted when used.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because renewable resources (such as solar, wind, and sustainably managed timber) regenerate naturally, whereas finite fossil fuels and minerals do not.","distractor_reasons":{"A":"Incorrect because wind, solar, and hydro are major sources of electricity generation.","B":"Correct selection.","C":"Incorrect because renewable energy technologies often have lower operating costs once installed.","D":"Incorrect because this reverses examples of renewable and non-renewable resources."}}},{"id":"P1_U6_MCQ_563","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_563","question":"What is meant by a business's 'carbon footprint'?","options":{"A":"The physical floor area in square metres occupied by a company's factories.","B":"The total weight of paper stationery used in an office each year.","C":"The total amount of greenhouse gases, particularly carbon dioxide, released directly and indirectly by a business's activities.","D":"The amount of corporation tax paid by a company to the government."},"correctOption":"C","correctAnswer":"The total amount of greenhouse gases, particularly carbon dioxide, released directly and indirectly by a business's activities.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a carbon footprint measures total greenhouse gas emissions generated across a firm's energy use, transport, and supply chain.","distractor_reasons":{"A":"Incorrect because physical building size is floor space, not greenhouse gas emissions.","B":"Incorrect because paper weight is only one tiny input rather than total carbon emissions.","C":"Correct selection.","D":"Incorrect because corporation tax is a financial tax on profit, not an environmental measure."}}},{"id":"P1_U6_MCQ_564","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_564","question":"What is meant by the term 'greenwashing'?","options":{"A":"Using biodegradable cleaning detergents in commercial laundries.","B":"Investing genuine profits into certified reforestation projects.","C":"Recycling 100% of industrial wastewater inside a manufacturing plant.","D":"Making exaggerated, misleading, or unsubstantiated marketing claims that a business or product is more environmentally friendly than it really is."},"correctOption":"D","correctAnswer":"Making exaggerated, misleading, or unsubstantiated marketing claims that a business or product is more environmentally friendly than it really is.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because greenwashing deceives eco-conscious consumers through false environmental image-building without genuine sustainability action.","distractor_reasons":{"A":"Incorrect because using biodegradable detergents is a genuine eco-friendly practice.","B":"Incorrect because funding verified reforestation is authentic environmental stewardship.","C":"Incorrect because closed-loop water recycling is genuine pollution prevention.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_565","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_565","question":"Which of the following is an example of visual pollution caused by business activity?","options":{"A":"Unsightly open-cast mining scars, giant advertising billboards, or overflowing industrial waste tips that spoil natural landscapes.","B":"Loud night-time aircraft engines waking residents near an airport.","C":"Toxic sulphur dioxide gas released from coal power stations.","D":"Agricultural fertilisers washing into freshwater lakes."},"correctOption":"A","correctAnswer":"Unsightly open-cast mining scars, giant advertising billboards, or overflowing industrial waste tips that spoil natural landscapes.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because visual pollution occurs when human structures or industrial damage degrade the aesthetic quality of the environment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because loud aircraft engines cause *noise* pollution.","C":"Incorrect because sulphur dioxide gas causes *air* pollution.","D":"Incorrect because chemical runoff into lakes causes *water* pollution."}}},{"id":"P1_U6_MCQ_566","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_566","question":"How can climate change and global warming directly affect agricultural and tourism businesses?","options":{"A":"By guaranteeing stable, unchanging weather patterns every single year.","B":"Through more frequent droughts, floods, and extreme weather events that disrupt crop harvests and damage tourist infrastructure.","C":"By eliminating the need for commercial property insurance.","D":"By lowering global sea levels and expanding coastal farmland."},"correctOption":"B","correctAnswer":"Through more frequent droughts, floods, and extreme weather events that disrupt crop harvests and damage tourist infrastructure.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because climate instability increases physical risks, supply disruptions, and insurance costs for weather-sensitive industries.","distractor_reasons":{"A":"Incorrect because climate change causes *more* volatile and unpredictable weather.","B":"Correct selection.","C":"Incorrect because greater weather risks increase the need for—and cost of—insurance.","D":"Incorrect because warming causes sea levels to *rise*, threatening coastal properties."}}},{"id":"P1_U6_MCQ_567","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_567","question":"How does government environmental regulation protect the natural environment from business activity?","options":{"A":"By allowing businesses to release unlimited toxic waste in exchange for higher profits.","B":"By removing all fines and penalties for oil spills and deforestation.","C":"By setting legally binding limits on emissions, banning hazardous substances, and imposing fines or closures on violators.","D":"By reducing personal income tax rates for company directors."},"correctOption":"C","correctAnswer":"By setting legally binding limits on emissions, banning hazardous substances, and imposing fines or closures on violators.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because environmental laws establish mandatory rules and penalties that compel businesses to curb pollution and protect ecosystems.","distractor_reasons":{"A":"Incorrect because regulations *restrict*, rather than permit, toxic waste dumping.","B":"Incorrect because regulations enforce strict legal penalties for environmental damage.","C":"Correct selection.","D":"Incorrect because personal income tax changes are fiscal policy, not environmental law."}}},{"id":"P1_U6_MCQ_568","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_568","question":"What is the main economic purpose of a government carbon tax or pollution tax?","options":{"A":"To make fossil fuels cheaper so factories burn more coal and oil.","B":"To reward businesses that produce the highest volume of landfill waste.","C":"To eliminate all corporation tax for heavy manufacturing firms.","D":"To increase the cost of polluting activities, encouraging businesses to cut emissions and switch to cleaner technologies."},"correctOption":"D","correctAnswer":"To increase the cost of polluting activities, encouraging businesses to cut emissions and switch to cleaner technologies.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because environmental taxes internalise external costs, giving businesses a direct financial incentive to reduce pollution.","distractor_reasons":{"A":"Incorrect because carbon taxes make fossil fuels *more expensive*, not cheaper.","B":"Incorrect because green taxes penalise, rather than reward, high waste and emissions.","C":"Incorrect because pollution taxes are imposed in addition to regular profit taxes.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_569","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_569","question":"Why do governments provide subsidies or tax grants for renewable energy and electric vehicles?","options":{"A":"To lower the upfront cost of green technologies and encourage businesses and consumers to adopt sustainable alternatives.","B":"To increase the price of solar panels and wind turbines.","C":"To discourage businesses from investing in energy efficiency.","D":"To increase national dependence on imported fossil fuels."},"correctOption":"A","correctAnswer":"To lower the upfront cost of green technologies and encourage businesses and consumers to adopt sustainable alternatives.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because green subsidies make environmentally friendly investments financially attractive and accelerate the transition away from fossil fuels.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because subsidies *reduce* effective prices for buyers and producers.","C":"Incorrect because subsidies encourage, rather than discourage, green investment.","D":"Incorrect because renewable energy subsidies reduce fossil fuel reliance."}}},{"id":"P1_U6_MCQ_570","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_570","question":"How does adopting recycling and waste-reduction practices benefit both the environment and a business?","options":{"A":"It increases landfill disposal taxes and raw material purchases.","B":"It conserves natural resources, reduces landfill pollution, and lowers raw material and waste-disposal expenses for the business.","C":"It forces the business to lower product quality and lose customers.","D":"It exempts the business from obeying health and safety legislation."},"correctOption":"B","correctAnswer":"It conserves natural resources, reduces landfill pollution, and lowers raw material and waste-disposal expenses for the business.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because minimising and recycling waste cuts input and landfill costs while reducing environmental harm and enhancing brand reputation.","distractor_reasons":{"A":"Incorrect because recycling *reduces* landfill taxes and virgin material needs.","B":"Correct selection.","C":"Incorrect because efficient resource use maintains quality while lowering waste.","D":"Incorrect because health and safety laws always apply."}}},{"id":"P1_U6_MCQ_571","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_571","question":"What is the purpose of independent eco-labels (such as FSC timber or organic certifications) on consumer products?","options":{"A":"To hide the country of origin from customs inspectors.","B":"To exempt manufacturers from paying Value Added Tax.","C":"To provide credible proof that products meet verified environmental standards, helping eco-conscious consumers make informed choices.","D":"To allow businesses to charge lower prices than non-certified goods automatically."},"correctOption":"C","correctAnswer":"To provide credible proof that products meet verified environmental standards, helping eco-conscious consumers make informed choices.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because third-party eco-labels verify sustainability claims, building consumer trust and differentiating responsible products.","distractor_reasons":{"A":"Incorrect because eco-labels increase transparency rather than hiding origin details.","B":"Incorrect because environmental certification does not waive sales taxes.","C":"Correct selection.","D":"Incorrect because certified sustainable products often cost slightly more to produce and sell at a premium."}}},{"id":"P1_U6_MCQ_572","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_572","question":"How can unsustainable deforestation and mining by businesses lead to biodiversity loss?","options":{"A":"By expanding protected national parks and wildlife reserves.","B":"By increasing the number of native plant and animal species in a region.","C":"By reducing greenhouse gas concentrations in the atmosphere.","D":"By destroying natural habitats and ecosystems, driving plant and animal species toward extinction."},"correctOption":"D","correctAnswer":"By destroying natural habitats and ecosystems, driving plant and animal species toward extinction.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because clearing forests and polluting ecosystems removes vital habitats and reduces biological diversity.","distractor_reasons":{"A":"Incorrect because protected reserves conserve, rather than destroy, biodiversity.","B":"Incorrect because habitat destruction reduces, rather than increases, species numbers.","C":"Incorrect because deforestation releases stored carbon and reduces carbon absorption.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_573","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_573","question":"Why does single-use non-biodegradable plastic packaging pose a major environmental problem?","options":{"A":"It does not break down naturally in soil or oceans, persisting for centuries and harming marine and terrestrial wildlife.","B":"It dissolves completely in rainwater within twenty-four hours.","C":"It enriches agricultural soil with organic nutrients.","D":"It is made entirely from renewable rainwater and air."},"correctOption":"A","correctAnswer":"It does not break down naturally in soil or oceans, persisting for centuries and harming marine and terrestrial wildlife.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because non-biodegradable plastics accumulate in landfills and waterways, fragmenting into harmful microplastics.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because conventional plastics persist for hundreds of years rather than dissolving rapidly.","C":"Incorrect because plastic waste pollutes soil rather than fertilising it.","D":"Incorrect because conventional plastics are derived from non-renewable petrochemicals."}}},{"id":"P1_U6_MCQ_574","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_574","question":"What is meant by resource conservation in business operations?","options":{"A":"Extracting finite minerals as rapidly as possible before competitors can access them.","B":"Managing and using natural resources carefully and efficiently to avoid waste and prevent permanent depletion.","C":"Throwing away repairable machinery after a single use.","D":"Increasing water and electricity consumption per unit of output."},"correctOption":"B","correctAnswer":"Managing and using natural resources carefully and efficiently to avoid waste and prevent permanent depletion.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because resource conservation protects finite and renewable natural capital for ongoing and future use.","distractor_reasons":{"A":"Incorrect because rapid extraction accelerates depletion rather than conserving resources.","B":"Correct selection.","C":"Incorrect because throwing away repairable equipment wastes resources.","D":"Incorrect because conservation seeks to *reduce* energy and water intensity per unit."}}},{"id":"P1_U6_MCQ_575","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_575","question":"Why can there be a short-term conflict between a business's objective of profit maximisation and environmental protection?","options":{"A":"Because environmental laws guarantee higher profits for polluting companies.","B":"Because consumers always refuse to buy environmentally friendly products.","C":"Because installing clean technology, treating waste, and sourcing sustainable materials often increase short-term operating costs.","D":"Because environmentally friendly businesses are banned from advertising."},"correctOption":"C","correctAnswer":"Because installing clean technology, treating waste, and sourcing sustainable materials often increase short-term operating costs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because upgrading equipment and using certified eco-inputs require upfront expenditure that can reduce short-term profit margins.","distractor_reasons":{"A":"Incorrect because environmental laws penalise, rather than reward, polluters.","B":"Incorrect because many consumers actively prefer eco-friendly products.","C":"Correct selection.","D":"Incorrect because sustainable businesses freely promote their green credentials."}}},{"id":"P1_U6_MCQ_576","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_576","question":"What is meant by the term 'business ethics'?","options":{"A":"The legal rules passed by Parliament that every company must obey to avoid prison.","B":"The financial accounting methods used to calculate net profit and cash flow.","C":"The marketing techniques used to persuade customers to buy unnecessary products.","D":"The moral principles and values that guide business behaviour and determine what is right or wrong beyond minimum legal requirements."},"correctOption":"D","correctAnswer":"The moral principles and values that guide business behaviour and determine what is right or wrong beyond minimum legal requirements.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because business ethics involves applying moral standards of fairness, honesty, and integrity to commercial decisions.","distractor_reasons":{"A":"Incorrect because statutory laws are minimum legal obligations, whereas ethics goes beyond mere legality.","B":"Incorrect because accounting rules measure financial performance rather than moral values.","C":"Incorrect because manipulative selling is unethical rather than the definition of ethics.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_577","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_577","question":"What is the key distinction between legal compliance and ethical behaviour in business?","options":{"A":"Legal compliance means obeying the minimum rules set by law, whereas ethical behaviour means doing what is morally right even when not required by law.","B":"Legal compliance is optional for businesses, whereas ethical behaviour is enforced by the police.","C":"Ethical behaviour means breaking laws whenever doing so increases shareholder dividends.","D":"There is no difference because every unethical action is automatically illegal in every country."},"correctOption":"A","correctAnswer":"Legal compliance means obeying the minimum rules set by law, whereas ethical behaviour means doing what is morally right even when not required by law.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because actions can be technically legal (such as aggressive tax avoidance or paying barely livable minimum wages) yet still be judged unethical.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because laws are compulsory, whereas ethical standards are voluntary moral commitments.","C":"Incorrect because ethical behaviour requires obeying the law and upholding higher moral standards.","D":"Incorrect because legal gaps often allow practices that society considers unethical."}}},{"id":"P1_U6_MCQ_578","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_578","question":"What is an ethical code of conduct within a business?","options":{"A":"A secret manual explaining how managers can avoid paying taxes.","B":"A formal written document setting out the moral standards, values, and expected behaviour for all employees and managers.","C":"A government law setting the national minimum wage rate.","D":"A list of product prices offered to wholesale customers."},"correctOption":"B","correctAnswer":"A formal written document setting out the moral standards, values, and expected behaviour for all employees and managers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a corporate code of conduct clarifies acceptable integrity standards (e.g., anti-bribery, fairness, safety) across the workforce.","distractor_reasons":{"A":"Incorrect because ethical codes prohibit dishonesty and legal evasion.","B":"Correct selection.","C":"Incorrect because minimum wage laws are external government statutes, not internal company codes.","D":"Incorrect because wholesale price lists are commercial sales documents."}}},{"id":"P1_U6_MCQ_579","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_579","question":"What is meant by Corporate Social Responsibility (CSR)?","options":{"A":"A legal requirement that all private companies transfer ownership to the government.","B":"Focusing exclusively on short-term profit maximisation for shareholders while ignoring employees and communities.","C":"A business's voluntary commitment to act ethically and contribute positively to economic, social, and environmental wellbeing for all stakeholders.","D":"Paying lower wages to workers in developing countries to cut costs."},"correctOption":"C","correctAnswer":"A business's voluntary commitment to act ethically and contribute positively to economic, social, and environmental wellbeing for all stakeholders.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because CSR integrates social, ethical, and environmental accountability into a company's strategy alongside financial goals.","distractor_reasons":{"A":"Incorrect because CSR is a private sector governance approach, not state nationalisation.","B":"Incorrect because ignoring wider stakeholders is the opposite of CSR.","C":"Correct selection.","D":"Incorrect because exploiting low-wage workers violates CSR principles."}}},{"id":"P1_U6_MCQ_580","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_580","question":"What is the main purpose of the Fairtrade movement?","options":{"A":"To remove all import tariffs between wealthy industrialised nations.","B":"To help multinational corporations buy agricultural crops at the lowest possible market price.","C":"To ban all exports of coffee, cocoa, and bananas from developing countries.","D":"To ensure farmers and workers in developing countries receive fair, stable minimum prices and decent working conditions."},"correctOption":"D","correctAnswer":"To ensure farmers and workers in developing countries receive fair, stable minimum prices and decent working conditions.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Fairtrade protects smallholder producers from volatile commodity prices and unfair exploitation.","distractor_reasons":{"A":"Incorrect because removing customs tariffs is free trade, not Fairtrade.","B":"Incorrect because Fairtrade sets a guaranteed minimum price *above* exploitative lows.","C":"Incorrect because Fairtrade promotes equitable trade rather than banning exports.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_581","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_581","question":"What is the Fairtrade social premium?","options":{"A":"An additional sum of money paid on top of the Fairtrade minimum price for farmers and workers to invest in community projects such as schools, clean water, or healthcare.","B":"A tax charged by governments on imported Fairtrade products.","C":"A bonus paid to supermarket executives for selling Fairtrade chocolate.","D":"A discount deducted from farmers' payments when global crop prices fall."},"correctOption":"A","correctAnswer":"An additional sum of money paid on top of the Fairtrade minimum price for farmers and workers to invest in community projects such as schools, clean water, or healthcare.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the Fairtrade premium empowers producer cooperatives to fund collective social and environmental improvements.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because it is paid by buyers to producer communities, not collected as a government tax.","C":"Incorrect because the premium goes directly to producer cooperatives in developing countries.","D":"Incorrect because it is an *extra* payment above the minimum price, never a deduction."}}},{"id":"P1_U6_MCQ_582","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_582","question":"What is meant by ethical sourcing?","options":{"A":"Selecting whichever supplier offers the lowest price regardless of child labour or pollution.","B":"Ensuring that raw materials and products are obtained responsibly from suppliers that respect human rights, fair wages, and environmental standards.","C":"Purchasing counterfeit goods to reduce inventory expenses.","D":"Delaying supplier invoice payments for six months to improve cash flow."},"correctOption":"B","correctAnswer":"Ensuring that raw materials and products are obtained responsibly from suppliers that respect human rights, fair wages, and environmental standards.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ethical sourcing scrutinises supply chains to ensure fair labour practices and sustainable production.","distractor_reasons":{"A":"Incorrect because ignoring labour and environmental abuses is unethical procurement.","B":"Correct selection.","C":"Incorrect because buying counterfeit goods is illegal and unethical.","D":"Incorrect because withholding timely payment harms suppliers and is unethical."}}},{"id":"P1_U6_MCQ_583","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_583","question":"Why is the use of child labour in supply chains universally condemned as a major ethical violation?","options":{"A":"Because children always demand higher hourly wages than adult workers.","B":"Because employing children increases a company's corporation tax rate.","C":"Because it deprives children of their right to education, harms their physical and mental development, and exploits vulnerable families.","D":"Because child labour improves product quality too much."},"correctOption":"C","correctAnswer":"Because it deprives children of their right to education, harms their physical and mental development, and exploits vulnerable families.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because child labour violates fundamental human rights and perpetuates cycles of poverty.","distractor_reasons":{"A":"Incorrect because unethical employers use child labour specifically because children are paid very little.","B":"Incorrect because tax rates are unrelated to employee age.","C":"Correct selection.","D":"Incorrect because quality is unrelated to the moral violation of exploiting children."}}},{"id":"P1_U6_MCQ_584","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_584","question":"How does a voluntary 'living wage' differ from a statutory minimum wage?","options":{"A":"A living wage is lower than the statutory minimum wage.","B":"A living wage is set by Parliament as a criminal offence if underpaid, whereas a minimum wage is voluntary.","C":"A living wage applies only to company directors and senior managers.","D":"A living wage is voluntarily paid by ethical employers at a rate calculated to cover the real cost of basic food, housing, and living essentials."},"correctOption":"D","correctAnswer":"A living wage is voluntarily paid by ethical employers at a rate calculated to cover the real cost of basic food, housing, and living essentials.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because statutory minimum wages are legal floors that may fall short of actual living costs, whereas a living wage meets real household needs.","distractor_reasons":{"A":"Incorrect because a living wage is higher than the basic legal minimum wage.","B":"Incorrect because this reverses legal minimum wage and voluntary living wage.","C":"Incorrect because living wages specifically protect lower-paid frontline workers.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_585","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_585","question":"What is bribery in a business context?","options":{"A":"Offering or receiving money, gifts, or favours to improperly influence a decision or gain an unfair commercial advantage.","B":"Offering customers a 10% seasonal discount during a clearance sale.","C":"Paying employees an annual performance bonus based on published sales targets.","D":"Donating money to a registered public charity."},"correctOption":"A","correctAnswer":"Offering or receiving money, gifts, or favours to improperly influence a decision or gain an unfair commercial advantage.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bribery corrupts fair competition and honest governance through secret, improper inducements.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because transparent promotional discounts are standard legal marketing.","C":"Incorrect because transparent performance bonuses are legitimate HR incentives.","D":"Incorrect because registered charitable donations are legitimate philanthropy."}}},{"id":"P1_U6_MCQ_586","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_586","question":"What is a 'conflict of interest' in business decision-making?","options":{"A":"When two rival companies compete for the same customers through advertising.","B":"When an employee's or manager's personal or financial interests could improperly influence their professional judgement on behalf of the company.","C":"When a central bank raises interest rates while the government cuts taxes.","D":"When a business sells products in both domestic and foreign markets."},"correctOption":"B","correctAnswer":"When an employee's or manager's personal or financial interests could improperly influence their professional judgement on behalf of the company.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a conflict of interest compromises impartiality—for example, awarding a supply contract to a relative's firm without disclosure.","distractor_reasons":{"A":"Incorrect because market rivalry between firms is normal competition, not an internal conflict of interest.","B":"Correct selection.","C":"Incorrect because conflicting macroeconomic policies are policy conflicts, not personal ethical conflicts.","D":"Incorrect because operating in multiple markets is international expansion."}}},{"id":"P1_U6_MCQ_587","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_587","question":"What is meant by 'whistleblowing' in an organisation?","options":{"A":"Using loud sirens to signal the end of a factory shift.","B":"Spreading false rumours to damage a competitor's share price.","C":"An employee reporting illegal, unsafe, or unethical practices within their organisation to senior management or external authorities.","D":"Announcing a new product launch at a public press conference."},"correctOption":"C","correctAnswer":"An employee reporting illegal, unsafe, or unethical practices within their organisation to senior management or external authorities.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because whistleblowing exposes wrongdoing (such as fraud, safety breaches, or pollution cover-ups) in the public interest.","distractor_reasons":{"A":"Incorrect because factory shift sirens are operational signals.","B":"Incorrect because spreading false rumours is defamation/market abuse, not whistleblowing.","C":"Correct selection.","D":"Incorrect because product announcements are routine public relations."}}},{"id":"P1_U6_MCQ_588","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_588","question":"Which practice demonstrates ethical marketing?","options":{"A":"Hiding mandatory fees until the final step of online checkout.","B":"Targeting young children with misleading adverts for unhealthy snacks.","C":"Exaggerating product capabilities with false scientific claims.","D":"Providing clear, accurate, and truthful product information and pricing without deceptive fine print."},"correctOption":"D","correctAnswer":"Providing clear, accurate, and truthful product information and pricing without deceptive fine print.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ethical marketing respects consumers' right to honest information and informed choice.","distractor_reasons":{"A":"Incorrect because drip-pricing with hidden fees deceives shoppers.","B":"Incorrect because exploiting children's lack of commercial awareness is unethical.","C":"Incorrect because false claims violate advertising ethics and consumer law.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_589","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_589","question":"Why is 'predatory pricing' considered unethical and anti-competitive?","options":{"A":"Because a dominant firm deliberately prices goods below cost to drive smaller rivals out of business, intending to raise prices later once competition is eliminated.","B":"Because a business offers fair discounts on perishable food close to its expiry date.","C":"Because a new entrant sets low introductory prices to build initial brand awareness.","D":"Because a business lowers prices after reducing its costs through improved efficiency."},"correctOption":"A","correctAnswer":"Because a dominant firm deliberately prices goods below cost to drive smaller rivals out of business, intending to raise prices later once competition is eliminated.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because predatory pricing abuses market power to destroy competitors and ultimately exploit consumers with monopoly prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because discounting expiring food reduces waste and benefits consumers.","C":"Incorrect because penetration pricing by a new entrant increases competition rather than creating a monopoly.","D":"Incorrect because passing efficiency savings onto consumers is healthy competition."}}},{"id":"P1_U6_MCQ_590","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_590","question":"What is 'price gouging'?","options":{"A":"Lowering prices during an economic recession to help budget-conscious families.","B":"Charging excessively high prices for essential goods—such as water, fuel, or medicine—by exploiting emergencies or sudden supply shortages.","C":"Charging different prices for peak and off-peak train tickets.","D":"Setting prices by adding a standard percentage profit mark-up to unit cost."},"correctOption":"B","correctAnswer":"Charging excessively high prices for essential goods—such as water, fuel, or medicine—by exploiting emergencies or sudden supply shortages.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profiteering from disasters or urgent human need breaches fundamental moral standards.","distractor_reasons":{"A":"Incorrect because lowering prices in a recession helps consumers.","B":"Correct selection.","C":"Incorrect because peak/off-peak pricing manages normal capacity demand.","D":"Incorrect because standard cost-plus pricing is a routine pricing method."}}},{"id":"P1_U6_MCQ_591","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_591","question":"Why do many cosmetics and household brands adopt 'cruelty-free' product testing policies?","options":{"A":"Because cruelty-free testing eliminates all manufacturing costs.","B":"Because animal testing is required by law for all cosmetics worldwide.","C":"To respond to ethical concerns over animal welfare and attract consumers who oppose testing products on animals.","D":"Because cruelty-free products do not require any safety verification."},"correctOption":"C","correctAnswer":"To respond to ethical concerns over animal welfare and attract consumers who oppose testing products on animals.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because avoiding animal testing aligns with animal-rights ethics and meets strong consumer demand for humane products.","distractor_reasons":{"A":"Incorrect because alternative laboratory testing still incurs research costs.","B":"Incorrect because many regions have banned animal testing for cosmetics.","C":"Correct selection.","D":"Incorrect because products still undergo non-animal safety testing."}}},{"id":"P1_U6_MCQ_592","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_592","question":"What is a business's ethical responsibility regarding customer personal data?","options":{"A":"Selling customers' private contact and payment details to third-party advertisers without permission.","B":"Collecting as much personal data as possible secretly without informing users.","C":"Ignoring cybersecurity vulnerabilities to save money on IT maintenance.","D":"Protecting customer data securely, collecting only necessary information with clear consent, and being transparent about how it is used."},"correctOption":"D","correctAnswer":"Protecting customer data securely, collecting only necessary information with clear consent, and being transparent about how it is used.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because respecting digital privacy and safeguarding personal data are essential ethical obligations in modern commerce.","distractor_reasons":{"A":"Incorrect because selling private data without consent violates both ethics and data protection laws.","B":"Incorrect because covert data harvesting breaches transparency and trust.","C":"Incorrect because neglecting cybersecurity exposes customers to identity theft.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_593","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_593","question":"What is meant by an ethical equal-opportunities policy in recruitment and promotion?","options":{"A":"Ensuring all applicants and employees are judged fairly on skills, qualifications, and performance without discrimination based on gender, race, age, religion, or disability.","B":"Hiring only candidates who share the same background as the company's founder.","C":"Paying male employees higher salaries than female employees for identical work.","D":"Refusing to interview any candidate over the age of forty."},"correctOption":"A","correctAnswer":"Ensuring all applicants and employees are judged fairly on skills, qualifications, and performance without discrimination based on gender, race, age, religion, or disability.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because equal-opportunity policies uphold fairness, diversity, and meritocracy across the workplace.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because favouring one background is unfair discrimination.","C":"Incorrect because unequal pay for equal work is discriminatory and unethical.","D":"Incorrect because rejecting applicants based on age is age discrimination."}}},{"id":"P1_U6_MCQ_594","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_594","question":"Why do ethical businesses conduct independent audits of their overseas suppliers' factories?","options":{"A":"To force overseas suppliers to cut worker wages by 50%.","B":"To verify that safe working conditions, fair hours, and anti-child-labour standards are actually being upheld on the factory floor.","C":"To avoid paying import tariffs when goods arrive at domestic ports.","D":"To copy the supplier's confidential trade secrets."},"correctOption":"B","correctAnswer":"To verify that safe working conditions, fair hours, and anti-child-labour standards are actually being upheld on the factory floor.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because independent inspections ensure suppliers comply with ethical codes in practice rather than merely signing paper promises.","distractor_reasons":{"A":"Incorrect because ethical audits protect, rather than cut, worker wages.","B":"Correct selection.","C":"Incorrect because factory audits do not waive customs duties.","D":"Incorrect because audits focus on labour, safety, and environmental compliance."}}},{"id":"P1_U6_MCQ_595","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_595","question":"What is meant by 'ethical investment' (socially responsible investing)?","options":{"A":"Investing money exclusively in whichever company generates the highest profit regardless of harm.","B":"Buying shares in companies that manufacture illegal weapons and pollute rivers.","C":"Selecting investments based on moral, social, and environmental criteria alongside financial returns, avoiding harmful industries.","D":"Refusing to invest any capital in renewable energy or healthcare."},"correctOption":"C","correctAnswer":"Selecting investments based on moral, social, and environmental criteria alongside financial returns, avoiding harmful industries.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ethical investors screen out businesses involved in tobacco, arms, human rights abuses, or severe pollution.","distractor_reasons":{"A":"Incorrect because purely profit-driven investing ignores ethical screening.","B":"Incorrect because ethical funds explicitly exclude harmful and unlawful sectors.","C":"Correct selection.","D":"Incorrect because ethical investors actively support renewable energy and healthcare."}}},{"id":"P1_U6_MCQ_596","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_596","question":"How do tax evasion and aggressive tax avoidance differ in terms of legality and ethics?","options":{"A":"Both tax evasion and tax avoidance are praised as highly ethical business practices.","B":"Tax evasion is completely legal, whereas tax avoidance is a serious criminal offence.","C":"Neither tax evasion nor tax avoidance has any effect on government tax revenue.","D":"Tax evasion is illegal non-payment of taxes owed, whereas aggressive tax avoidance uses legal loopholes to minimise tax in ways often criticised as unethical."},"correctOption":"D","correctAnswer":"Tax evasion is illegal non-payment of taxes owed, whereas aggressive tax avoidance uses legal loopholes to minimise tax in ways often criticised as unethical.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because evasion breaks the law, whereas aggressive avoidance obeys the letter of tax law while undermining its spirit and public funding.","distractor_reasons":{"A":"Incorrect because both deprive public services of funding and attract strong criticism.","B":"Incorrect because this reverses illegal tax evasion and legal tax avoidance.","C":"Incorrect because both reduce the tax revenue collected by governments.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_597","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_597","question":"How does the 'stakeholder approach' to business ethics differ from a purely 'shareholder-only' approach?","options":{"A":"The stakeholder approach considers the fair interests of employees, customers, suppliers, communities, and the environment alongside shareholders, rather than focusing solely on shareholder profit.","B":"The stakeholder approach bans companies from ever earning a profit or paying dividends.","C":"The stakeholder approach ignores customers and employees completely.","D":"The stakeholder approach applies only to sole traders with no employees."},"correctOption":"A","correctAnswer":"The stakeholder approach considers the fair interests of employees, customers, suppliers, communities, and the environment alongside shareholders, rather than focusing solely on shareholder profit.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical stakeholder management balances obligations across all groups affected by the business's operations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ethical firms still aim to be profitable while treating all stakeholders fairly.","C":"Incorrect because employees and customers are primary stakeholders.","D":"Incorrect because stakeholder ethics is central to medium and large companies."}}},{"id":"P1_U6_MCQ_598","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_598","question":"Why do many businesses adopt ethical practices even when they increase short-term operating costs?","options":{"A":"Because ethical practices automatically eliminate all competition.","B":"Because strong ethical reputation boosts customer loyalty, employee motivation, and investor confidence, increasing long-term profitability.","C":"Because governments refund 100% of all business expenses to ethical firms.","D":"Because ethical businesses are exempt from paying corporation tax."},"correctOption":"B","correctAnswer":"Because strong ethical reputation boosts customer loyalty, employee motivation, and investor confidence, increasing long-term profitability.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ethical trust acts as a valuable intangible asset that supports sustainable long-term revenue and staff retention.","distractor_reasons":{"A":"Incorrect because competitors still operate in the market.","B":"Correct selection.","C":"Incorrect because governments do not refund normal business operating costs.","D":"Incorrect because ethical businesses still pay standard corporation tax on profits."}}},{"id":"P1_U6_MCQ_599","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_599","question":"Which working conditions characterise an unethical 'sweatshop' factory?","options":{"A":"Safe ventilation, living wages, paid annual leave, and reasonable working hours.","B":"Flexible remote working and employer-funded university scholarships.","C":"Extremely low wages, excessive forced overtime, unsafe or unhealthy facilities, and denial of basic worker rights.","D":"Strict compliance with international health, safety, and labour standards."},"correctOption":"C","correctAnswer":"Extremely low wages, excessive forced overtime, unsafe or unhealthy facilities, and denial of basic worker rights.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sweatshops exploit vulnerable workers through hazardous conditions, poverty pay, and exhausting hours.","distractor_reasons":{"A":"Incorrect because safe conditions and living wages describe ethical employment.","B":"Incorrect because generous benefits and flexibility reflect progressive HR management.","C":"Correct selection.","D":"Incorrect because full compliance with labour standards is the opposite of a sweatshop."}}},{"id":"P1_U6_MCQ_600","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_600","question":"How can a large retail business demonstrate ethical behaviour toward its small suppliers?","options":{"A":"By cancelling orders at the last minute without compensation.","B":"By forcing suppliers to accept retroactive price cuts after goods have already been delivered.","C":"By delaying invoice payments for over 120 days to hoard cash.","D":"By honouring agreed contracts, paying invoices promptly, and negotiating fair, transparent terms."},"correctOption":"D","correctAnswer":"By honouring agreed contracts, paying invoices promptly, and negotiating fair, transparent terms.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because prompt payment and fair contract terms protect smaller suppliers' cash flow and survival.","distractor_reasons":{"A":"Incorrect because abrupt order cancellations leave small suppliers with unsold stock and losses.","B":"Incorrect because retroactive price deductions abuse buyer power unethically.","C":"Incorrect because excessive payment delays squeeze small suppliers' working capital.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_601","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_601","question":"What is the correct definition of a pressure group?","options":{"A":"An organised group of people with shared interests or concerns who seek to influence business decisions and government policies without seeking to become the government.","B":"A political party that stands in national elections to form the government.","C":"A private limited company established to maximise profits for its shareholders.","D":"A government department responsible for collecting customs duties at borders."},"correctOption":"A","correctAnswer":"An organised group of people with shared interests or concerns who seek to influence business decisions and government policies without seeking to become the government.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pressure groups advocate for specific causes (such as environmental protection or consumer rights) by influencing businesses and policymakers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because contesting elections to govern is the role of a political party.","C":"Incorrect because pressure groups are non-profit advocacy organisations rather than commercial companies.","D":"Incorrect because border customs collection is performed by a state revenue agency."}}},{"id":"P1_U6_MCQ_602","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_602","question":"How does a pressure group differ from a political party?","options":{"A":"A pressure group has the legal power to pass laws directly, whereas a political party does not.","B":"A pressure group focuses on influencing specific issues or business practices without seeking political office, whereas a political party seeks to win elections and govern the whole country.","C":"A pressure group is always funded by the central bank, whereas political parties are funded by exports.","D":"A pressure group only exists inside private factories, whereas political parties exist only in schools."},"correctOption":"B","correctAnswer":"A pressure group focuses on influencing specific issues or business practices without seeking political office, whereas a political party seeks to win elections and govern the whole country.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because pressure groups exert external influence on targeted issues rather than governing across all national policies.","distractor_reasons":{"A":"Incorrect because neither pressure groups nor political parties outside government can unilaterally pass laws without parliamentary approval.","B":"Correct selection.","C":"Incorrect because pressure groups are funded by member subscriptions and donations, not central banks.","D":"Incorrect because both operate across wider public and political life."}}},{"id":"P1_U6_MCQ_603","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_603","question":"What is a consumer boycott?","options":{"A":"A government subsidy paid to encourage consumers to buy domestic products.","B":"A promotional loyalty card offering free gifts to repeat shoppers.","C":"An organised refusal by consumers to buy a company's products or services in order to protest against its unethical or harmful practices.","D":"A legal ban imposed by a court closing down a bankrupt business."},"correctOption":"C","correctAnswer":"An organised refusal by consumers to buy a company's products or services in order to protest against its unethical or harmful practices.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a boycott hits a targeted business directly in its sales revenue and market share until it changes its behaviour.","distractor_reasons":{"A":"Incorrect because a consumer subsidy encourages buying rather than refusing to buy.","B":"Incorrect because loyalty cards reward purchasing.","C":"Correct selection.","D":"Incorrect because a boycott is voluntary consumer action, not a court bankruptcy order."}}},{"id":"P1_U6_MCQ_604","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_604","question":"What is meant by 'lobbying' as a pressure group tactic?","options":{"A":"Physically blocking customers from entering a retail store.","B":"Lowering product prices below cost to bankrupt competitors.","C":"Buying shares in a company to receive annual dividend payments.","D":"Directly contacting and persuading politicians, ministers, or regulators to pass laws or change policies affecting businesses."},"correctOption":"D","correctAnswer":"Directly contacting and persuading politicians, ministers, or regulators to pass laws or change policies affecting businesses.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lobbying targets lawmakers and government officials to achieve regulatory change.","distractor_reasons":{"A":"Incorrect because blocking store entrances is a physical picket or protest, not lobbying.","B":"Incorrect because pricing below cost is predatory pricing.","C":"Incorrect because buying shares for income is passive investing.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_605","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_605","question":"How does a public petition help a pressure group influence a business or government?","options":{"A":"By collecting thousands or millions of signatures to demonstrate widespread public support for a demand and attract media attention.","B":"By automatically transferring ownership of the business to the pressure group.","C":"By legally arresting company directors who refuse to sign the document.","D":"By raising central bank interest rates immediately."},"correctOption":"A","correctAnswer":"By collecting thousands or millions of signatures to demonstrate widespread public support for a demand and attract media attention.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a large petition proves broad public concern, warning businesses of potential customer backlash and politicians of voter dissatisfaction.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because petitions carry moral and public pressure, not property transfer rights.","C":"Incorrect because pressure groups have no police or judicial arrest powers.","D":"Incorrect because petitions do not control monetary policy."}}},{"id":"P1_U6_MCQ_606","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_606","question":"What is the main aim of a peaceful public demonstration or protest outside a company's headquarters?","options":{"A":"To increase the company's daily retail sales.","B":"To generate news media coverage and public embarrassment that damages the company's reputation until it addresses the issue.","C":"To exempt the company from paying corporation tax.","D":"To provide free advertising for the company's newest products."},"correctOption":"B","correctAnswer":"To generate news media coverage and public embarrassment that damages the company's reputation until it addresses the issue.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because visible protests associate the brand with controversy in the media, pressuring executives to respond.","distractor_reasons":{"A":"Incorrect because protests seek to discourage, not boost, sales of targeted firms.","B":"Correct selection.","C":"Incorrect because demonstrations have no effect on tax liabilities.","D":"Incorrect because protests create negative publicity rather than positive promotion."}}},{"id":"P1_U6_MCQ_607","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_607","question":"Why do pressure groups publish investigative reports and run public awareness campaigns?","options":{"A":"To hide environmental and ethical problems from the general public.","B":"To help polluting businesses avoid government fines.","C":"To educate consumers and voters about hidden business harms, shifting purchasing habits and building support for regulation.","D":"To replace company financial statements audited by accountants."},"correctOption":"C","correctAnswer":"To educate consumers and voters about hidden business harms, shifting purchasing habits and building support for regulation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because raising public awareness empowers consumers to make ethical choices and pressures firms to reform.","distractor_reasons":{"A":"Incorrect because awareness campaigns *expose*, rather than hide, corporate misconduct.","B":"Incorrect because investigative reports frequently trigger regulatory investigations and fines.","C":"Correct selection.","D":"Incorrect because NGO reports address social/environmental impacts rather than statutory financial audits."}}},{"id":"P1_U6_MCQ_608","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_608","question":"What is meant by 'shareholder activism' by a pressure group?","options":{"A":"Refusing to buy any products sold in supermarkets.","B":"Lobbying foreign governments to impose import tariffs.","C":"Organising factory workers to go on strike for higher wages.","D":"Buying shares in a public limited company in order to attend its Annual General Meeting (AGM), question directors, and propose ethical resolutions."},"correctOption":"D","correctAnswer":"Buying shares in a public limited company in order to attend its Annual General Meeting (AGM), question directors, and propose ethical resolutions.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shareholder activism uses legal ownership rights inside the AGM to challenge board policies publicly.","distractor_reasons":{"A":"Incorrect because refusing to buy products is a consumer boycott.","B":"Incorrect because influencing politicians is political lobbying.","C":"Incorrect because organising worker strikes is trade union industrial action.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_609","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_609","question":"What is the difference between direct action and indirect lobbying by pressure groups?","options":{"A":"Direct action targets the business immediately through boycotts, protests, or blockades, whereas indirect lobbying works through persuading governments to pass laws.","B":"Direct action is always illegal, whereas indirect lobbying is always carried out by company directors.","C":"Direct action sets interest rates, whereas indirect lobbying collects taxes.","D":"There is no difference between direct action and indirect lobbying."},"correctOption":"A","correctAnswer":"Direct action targets the business immediately through boycotts, protests, or blockades, whereas indirect lobbying works through persuading governments to pass laws.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because direct action pressures the firm's sales or operations directly, while indirect action uses political channels to alter the legal environment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because peaceful protests and boycotts are legal forms of direct action.","C":"Incorrect because interest rates and taxes are controlled by central banks and governments.","D":"Incorrect because the two approaches target different channels (consumers/operations vs lawmakers)."}}},{"id":"P1_U6_MCQ_610","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_610","question":"What is the primary purpose of a consumer pressure group?","options":{"A":"To help monopolies raise prices without customer complaints.","B":"To protect buyers' rights, campaign against unsafe products or unfair charges, and promote honest business practices.","C":"To reduce statutory product safety standards for manufacturers.","D":"To represent factory owners in wage negotiations against trade unions."},"correctOption":"B","correctAnswer":"To protect buyers' rights, campaign against unsafe products or unfair charges, and promote honest business practices.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumer pressure groups advocate for product safety, fair pricing, and transparent terms for shoppers.","distractor_reasons":{"A":"Incorrect because consumer groups oppose monopoly overcharging.","B":"Correct selection.","C":"Incorrect because consumer groups campaign for *higher*, not lower, safety standards.","D":"Incorrect because employer associations represent factory owners, not consumer groups."}}},{"id":"P1_U6_MCQ_611","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_611","question":"What is the main focus of an environmental pressure group?","options":{"A":"Lowering corporate tax rates on oil and coal companies.","B":"Encouraging rapid deforestation to expand commercial cattle farming.","C":"Protecting ecosystems, reducing pollution and carbon emissions, and campaigning for sustainable business practices.","D":"Increasing single-use plastic production across retail industries."},"correctOption":"C","correctAnswer":"Protecting ecosystems, reducing pollution and carbon emissions, and campaigning for sustainable business practices.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because environmental NGOs campaign to conserve nature, combat climate change, and hold polluting businesses accountable.","distractor_reasons":{"A":"Incorrect because environmental groups favour taxing, rather than subsidising, fossil fuel pollution.","B":"Incorrect because environmental groups oppose deforestation.","C":"Correct selection.","D":"Incorrect because environmental groups campaign to reduce single-use plastics."}}},{"id":"P1_U6_MCQ_612","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_612","question":"Which issues are typically championed by human rights and ethical pressure groups?","options":{"A":"Maximising executive bonuses and reducing worker rest breaks.","B":"Removing minimum wage laws and workplace health regulations.","C":"Increasing import tariffs on Fairtrade agricultural goods.","D":"Eliminating child labour and forced labour, promoting living wages, and protecting worker dignity across global supply chains."},"correctOption":"D","correctAnswer":"Eliminating child labour and forced labour, promoting living wages, and protecting worker dignity across global supply chains.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because human rights groups monitor corporate supply chains to prevent worker exploitation and protect fundamental rights.","distractor_reasons":{"A":"Incorrect because human rights groups focus on vulnerable workers rather than executive pay.","B":"Incorrect because they campaign *for* stronger worker protections.","C":"Incorrect because they support fair trade rather than penalising it.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_613","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_613","question":"How does a business trade association act as a pressure group?","options":{"A":"By representing member businesses in an industry and lobbying the government for favourable taxes, regulations, or trade policies.","B":"By organising consumer boycotts against its own member businesses.","C":"By setting the central bank's base interest rate each month.","D":"By banning all private sector businesses from making profits."},"correctOption":"A","correctAnswer":"By representing member businesses in an industry and lobbying the government for favourable taxes, regulations, or trade policies.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because producer/business pressure groups (trade associations) lobby policymakers to protect their industry's commercial interests.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade associations promote, rather than boycott, their members' products.","C":"Incorrect because interest rates are set by the central bank.","D":"Incorrect because trade associations advocate for profitable business conditions."}}},{"id":"P1_U6_MCQ_614","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_614","question":"What is the typical objective of a local community pressure group?","options":{"A":"Negotiating international free trade treaties between continents.","B":"Influencing local planning decisions—such as opposing noisy factories, traffic congestion, or green-belt construction—to protect local residents' quality of life.","C":"Managing the national currency exchange rate.","D":"Auditing the global financial accounts of multinational banks."},"correctOption":"B","correctAnswer":"Influencing local planning decisions—such as opposing noisy factories, traffic congestion, or green-belt construction—to protect local residents' quality of life.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local community groups focus on neighbourhood externalities such as noise, traffic, pollution, and local development.","distractor_reasons":{"A":"Incorrect because international treaties are negotiated by national governments.","B":"Correct selection.","C":"Incorrect because currency policy is managed by central banks.","D":"Incorrect because financial audits are conducted by professional accounting firms."}}},{"id":"P1_U6_MCQ_615","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_615","question":"Which factor makes a consumer boycott organised by a pressure group much more likely to succeed?","options":{"A":"The targeted business holds a complete monopoly over an essential life-saving product.","B":"The pressure group has only five members and receives zero media coverage.","C":"Close, affordable substitute products are readily available from rival brands, making it easy for shoppers to switch.","D":"Consumers are completely unaware of the issue being campaigned about."},"correctOption":"C","correctAnswer":"Close, affordable substitute products are readily available from rival brands, making it easy for shoppers to switch.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when switching to an ethical alternative costs little or nothing, large numbers of consumers join the boycott.","distractor_reasons":{"A":"Incorrect because consumers cannot boycott an essential monopoly product with no substitutes.","B":"Incorrect because tiny groups without media reach rarely influence mass consumer behaviour.","C":"Correct selection.","D":"Incorrect because boycotts require widespread public awareness to succeed."}}},{"id":"P1_U6_MCQ_616","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_616","question":"Which condition limits the effectiveness of a consumer boycott against a business?","options":{"A":"Widespread national media coverage and strong public sympathy.","B":"Numerous competing brands offering cheaper, ethical substitutes.","C":"High household disposable incomes allowing consumers to afford ethical alternatives.","D":"The product is an essential necessity sold by a monopoly supplier with no practical alternatives."},"correctOption":"D","correctAnswer":"The product is an essential necessity sold by a monopoly supplier with no practical alternatives.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers cannot realistically stop buying essential utilities or medicines when there is no alternative supplier.","distractor_reasons":{"A":"Incorrect because strong media coverage and sympathy *increase* boycott success.","B":"Incorrect because readily available substitutes make boycotts easier to join.","C":"Incorrect because higher incomes make it easier for shoppers to choose ethical brands.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_617","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_617","question":"Why are well-known consumer-facing brands (B2C) generally more vulnerable to pressure group campaigns than anonymous business-to-business (B2B) raw material suppliers?","options":{"A":"Consumer brands rely heavily on public brand image and direct retail sales, whereas B2B suppliers do not sell directly to individual shoppers.","B":"B2B raw material suppliers are legally exempt from all environmental and labour laws.","C":"Consumer brands never spend money on marketing or brand reputation.","D":"B2B suppliers never have any impact on the environment."},"correctOption":"A","correctAnswer":"Consumer brands rely heavily on public brand image and direct retail sales, whereas B2B suppliers do not sell directly to individual shoppers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retail brands depend on consumer trust and can be directly boycotted at the checkout, whereas B2B firms sell to industrial buyers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all businesses must obey national laws.","C":"Incorrect because consumer brands invest heavily in brand image, making reputation risk severe.","D":"Incorrect because mining and heavy B2B industries often have large environmental footprints."}}},{"id":"P1_U6_MCQ_618","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_618","question":"How can a sustained pressure group campaign damage a business's brand reputation?","options":{"A":"By increasing the company's credit rating with commercial banks.","B":"By repeatedly linking the brand name with pollution, worker exploitation, or dishonesty in news and social media.","C":"By reducing the company's annual advertising expenses.","D":"By automatically winning industry quality awards for the business."},"correctOption":"B","correctAnswer":"By repeatedly linking the brand name with pollution, worker exploitation, or dishonesty in news and social media.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because negative publicity erodes consumer trust and tarnishes years of brand-building investment.","distractor_reasons":{"A":"Incorrect because reputational scandals increase business risk rather than improving credit ratings.","B":"Correct selection.","C":"Incorrect because firms often have to spend *more* on public relations to repair damaged reputations.","D":"Incorrect because negative campaigns undermine brand standing."}}},{"id":"P1_U6_MCQ_619","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_619","question":"What is the direct financial consequence if a pressure group successfully persuades customers to boycott a business?","options":{"A":"Sales revenue and market share fall while fixed overhead costs continue, reducing net profit.","B":"Fixed rent and salary costs drop to zero automatically.","C":"Profit margins double due to lower customer numbers.","D":"Corporation tax rates are waived by the government."},"correctOption":"A","correctAnswer":"Sales revenue and market share fall while fixed overhead costs continue, reducing net profit.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because losing customers cuts cash inflows immediately while fixed costs remain payable.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed costs do not disappear when sales drop.","C":"Incorrect because lower sales volumes reduce profit rather than doubling margins.","D":"Incorrect because tax rules do not waive taxes for boycotted firms."}}},{"id":"P1_U6_MCQ_620","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_620","question":"How can pressure group activity lead to higher operating costs for a targeted business?","options":{"A":"By forcing suppliers to give the business free raw materials.","B":"By lowering statutory minimum wages across the industry.","C":"By eliminating all quality control and safety inspections.","D":"By compelling the business to switch to more expensive ethical materials, upgrade pollution controls, or spend heavily on crisis public relations."},"correctOption":"D","correctAnswer":"By compelling the business to switch to more expensive ethical materials, upgrade pollution controls, or spend heavily on crisis public relations.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because meeting ethical and environmental demands—or defending brand reputation—adds direct and overhead expenses.","distractor_reasons":{"A":"Incorrect because suppliers charge *more*, not less, for certified ethical inputs.","B":"Incorrect because pressure groups campaign for *higher* living wages.","C":"Incorrect because pressure groups demand *stricter* safety and ethical audits.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_621","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_621","question":"How can a major pressure group scandal affect a public limited company (plc) on the stock market?","options":{"A":"Ethical investors and pension funds may sell their shares, causing the company's share price to fall and making it harder to raise equity capital.","B":"The company's share price doubles automatically due to media attention.","C":"The plc is converted into a sole trader within twenty-four hours.","D":"All existing bank loans are cancelled without repayment."},"correctOption":"A","correctAnswer":"Ethical investors and pension funds may sell their shares, causing the company's share price to fall and making it harder to raise equity capital.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because institutional investors avoid reputational and regulatory risk by divesting from companies targeted by major ethical scandals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because negative scandals depress share prices rather than doubling them.","C":"Incorrect because share price drops do not change a plc's legal structure.","D":"Incorrect because debt obligations remain legally binding."}}},{"id":"P1_U6_MCQ_622","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_622","question":"How do pressure groups influence businesses indirectly through government action?","options":{"A":"By setting product prices inside private supermarkets.","B":"By lobbying lawmakers to pass stricter environmental, safety, or consumer protection laws that all businesses must obey.","C":"By managing the daily production schedules of private factories.","D":"By setting the exchange rate of the national currency."},"correctOption":"B","correctAnswer":"By lobbying lawmakers to pass stricter environmental, safety, or consumer protection laws that all businesses must obey.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when pressure groups persuade governments to legislate, businesses are legally forced to comply.","distractor_reasons":{"A":"Incorrect because private retailers set their own shelf prices.","B":"Correct selection.","C":"Incorrect because internal operations managers schedule factory production.","D":"Incorrect because exchange rates are determined by currency markets and central banks."}}},{"id":"P1_U6_MCQ_623","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_623","question":"What is a constructive way for a business to respond to legitimate criticism from an environmental or ethical pressure group?","options":{"A":"Ignore all complaints and continue polluting illegally.","B":"Launch misleading greenwashing adverts without changing operations.","C":"Engage in dialogue with the pressure group, reform operating practices, and seek independent certification to turn ethical improvements into a brand strength.","D":"Close the entire business immediately without exploring operational improvements."},"correctOption":"C","correctAnswer":"Engage in dialogue with the pressure group, reform operating practices, and seek independent certification to turn ethical improvements into a brand strength.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because collaborating with credible NGOs resolves reputational threats and builds a sustainable competitive advantage.","distractor_reasons":{"A":"Incorrect because ignoring valid criticism escalates boycotts and regulatory penalties.","B":"Incorrect because greenwashing destroys credibility when exposed.","C":"Correct selection.","D":"Incorrect because adapting practices preserves the business profitably."}}},{"id":"P1_U6_MCQ_624","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_624","question":"What role does public relations (PR) play when a business faces pressure group criticism?","options":{"A":"Replacing all manufacturing workers with robots.","B":"Fixing the central bank's base interest rate.","C":"Hiding financial losses from the company's external auditors.","D":"Communicating factual evidence, explaining corrective actions taken, and rebuilding public trust through media channels."},"correctOption":"D","correctAnswer":"Communicating factual evidence, explaining corrective actions taken, and rebuilding public trust through media channels.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because transparent PR informs stakeholders of genuine improvements and counters inaccurate claims.","distractor_reasons":{"A":"Incorrect because automation is an operations management decision, not PR.","B":"Incorrect because PR cannot alter central bank interest rates.","C":"Incorrect because falsifying accounts is illegal accounting fraud.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_625","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_625","question":"How has the rise of social media increased the influence of pressure groups on businesses?","options":{"A":"It enables pressure groups to mobilise global audiences, share evidence virally, and organise boycotts rapidly at very low cost.","B":"It gives pressure groups legal authority to imprison company executives.","C":"It prevents consumers from ever seeing news about corporate scandals.","D":"It eliminates all competition between businesses in the same industry."},"correctOption":"A","correctAnswer":"It enables pressure groups to mobilise global audiences, share evidence virally, and organise boycotts rapidly at very low cost.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social media removes high traditional advertising barriers, allowing grassroots campaigns to reach millions within hours.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because only courts of law hold judicial sentencing powers.","C":"Incorrect because social media spreads information widely rather than concealing it.","D":"Incorrect because market competition still operates across industries."}}},{"id":"P1_U6_MCQ_626","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_626","question":"What is meant by cyclical unemployment?","options":{"A":"Unemployment caused by a fall in total demand across the economy during a recession or slump.","B":"Unemployment caused by workers changing jobs and briefly searching for new roles.","C":"Unemployment caused by predictable weather changes in tourism and agriculture.","D":"Unemployment caused by permanent long-term decline in a specific traditional industry."},"correctOption":"A","correctAnswer":"Unemployment caused by a fall in total demand across the economy during a recession or slump.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cyclical (demand-deficient) unemployment occurs when economic downturns reduce spending, forcing businesses across many sectors to lay off workers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because brief unemployment while transitioning between jobs defines frictional unemployment.","C":"Incorrect because weather-related or holiday-period joblessness defines seasonal unemployment.","D":"Incorrect because long-term industry decline and skill mismatches define structural unemployment."}}},{"id":"P1_U6_MCQ_627","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_627","question":"What is meant by structural unemployment?","options":{"A":"Temporary joblessness occurring only during the winter months each year.","B":"Long-term unemployment caused by permanent changes in industry demand, technology, or global competition leaving workers with outdated skills.","C":"Short-term unemployment experienced by university graduates during their first week of job hunting.","D":"Unemployment caused solely by a central bank raising interest rates for one month."},"correctOption":"B","correctAnswer":"Long-term unemployment caused by permanent changes in industry demand, technology, or global competition leaving workers with outdated skills.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because structural unemployment arises from fundamental shifts in the structure of the economy, such as automation or factory offshoring.","distractor_reasons":{"A":"Incorrect because annual weather-driven joblessness is seasonal unemployment.","B":"Correct selection.","C":"Incorrect because short transitions into employment represent frictional unemployment.","D":"Incorrect because downturns in aggregate demand cause cyclical unemployment."}}},{"id":"P1_U6_MCQ_628","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_628","question":"What is meant by frictional unemployment?","options":{"A":"Mass unemployment occurring during the trough of a severe economic slump.","B":"Unemployment caused by workers lacking computer skills in a modern economy.","C":"Short-term unemployment that occurs when people are between jobs or entering the labour force for the first time.","D":"Unemployment affecting ski instructors during the warm summer months."},"correctOption":"C","correctAnswer":"Short-term unemployment that occurs when people are between jobs or entering the labour force for the first time.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because frictional unemployment is temporary and inevitable in a dynamic economy as workers move between employers.","distractor_reasons":{"A":"Incorrect because mass downturn joblessness is cyclical unemployment.","B":"Incorrect because skill mismatches from technological change represent structural unemployment.","C":"Correct selection.","D":"Incorrect because summer unemployment in winter tourism is seasonal unemployment."}}},{"id":"P1_U6_MCQ_629","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_629","question":"What is meant by seasonal unemployment?","options":{"A":"Unemployment caused by permanent factory closures due to foreign imports.","B":"Unemployment caused by two consecutive quarters of falling national GDP.","C":"Unemployment caused by workers voluntarily retiring at age sixty-five.","D":"Unemployment occurring regularly at certain times of the year when demand for labour in industries such as farming, retail, or tourism falls."},"correctOption":"D","correctAnswer":"Unemployment occurring regularly at certain times of the year when demand for labour in industries such as farming, retail, or tourism falls.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because seasonal industries expand hiring during peak months (such as harvest or summer holidays) and reduce staff during off-peak seasons.","distractor_reasons":{"A":"Incorrect because permanent industry contraction causes structural unemployment.","B":"Incorrect because recession-induced job losses represent cyclical unemployment.","C":"Incorrect because retirees leave the labour force and are economically inactive rather than unemployed.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_630","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_630","question":"What causes demand-pull inflation in an economy?","options":{"A":"Total spending by consumers, businesses, and the government growing faster than the economy's capacity to produce goods and services.","B":"A sudden increase in imported raw material and energy costs.","C":"A severe recession causing household disposable incomes to collapse.","D":"A central bank raising interest rates to reduce borrowing."},"correctOption":"A","correctAnswer":"Total spending by consumers, businesses, and the government growing faster than the economy's capacity to produce goods and services.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because demand-pull inflation happens when excessive aggregate demand ('too much money chasing too few goods') bids up prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rising production input costs cause *cost-push* inflation.","C":"Incorrect because falling demand during a recession lowers inflationary pressure.","D":"Incorrect because higher interest rates cool demand to *reduce* inflation."}}},{"id":"P1_U6_MCQ_631","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_631","question":"What is meant by the economic term deflation?","options":{"A":"A slowdown in the rate at which prices are rising, while prices still increase overall.","B":"A sustained fall in the general price level of goods and services across an economy over time.","C":"A fall in the exchange rate value of a currency against foreign currencies.","D":"A rapid increase in consumer prices exceeding 10% per year."},"correctOption":"B","correctAnswer":"A sustained fall in the general price level of goods and services across an economy over time.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because deflation is negative inflation—a persistent decline in average prices across the economy.","distractor_reasons":{"A":"Incorrect because a slower positive rate of price increases is *disinflation*, not deflation.","B":"Correct selection.","C":"Incorrect because a fall in a currency's external value is currency depreciation.","D":"Incorrect because rapid price increases represent high inflation."}}},{"id":"P1_U6_MCQ_632","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_632","question":"Why is prolonged deflation generally harmful to businesses and economic growth?","options":{"A":"Because falling prices immediately double business profit margins.","B":"Because workers willingly accept large nominal wage cuts every month.","C":"Because consumers delay purchases expecting even lower prices in the future, reducing business sales, profits, and investment.","D":"Because deflation eliminates all business loan interest payments."},"correctOption":"C","correctAnswer":"Because consumers delay purchases expecting even lower prices in the future, reducing business sales, profits, and investment.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because deferred consumer spending and falling selling prices squeeze business revenues while fixed debt obligations remain unchanged in nominal terms.","distractor_reasons":{"A":"Incorrect because falling selling prices usually compress, rather than double, profit margins.","B":"Incorrect because wages are 'sticky' downwards, so falling prices raise real labour costs for firms.","C":"Correct selection.","D":"Incorrect because nominal debt repayments stay fixed and become harder to pay out of falling revenues."}}},{"id":"P1_U6_MCQ_633","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_633","question":"What is the difference between nominal GDP and real GDP?","options":{"A":"Nominal GDP includes exports, whereas real GDP excludes all international trade.","B":"Nominal GDP measures public sector output only, whereas real GDP measures private sector output only.","C":"Nominal GDP is calculated after deducting corporation tax, whereas real GDP is before tax.","D":"Nominal GDP is measured at current market prices, whereas real GDP has been adjusted to remove the effects of inflation."},"correctOption":"D","correctAnswer":"Nominal GDP is measured at current market prices, whereas real GDP has been adjusted to remove the effects of inflation.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because real GDP uses constant base-year prices so economists can measure true changes in physical output volume rather than mere price inflation.","distractor_reasons":{"A":"Incorrect because both nominal and real GDP include net exports.","B":"Incorrect because both measures cover total national output across public and private sectors.","C":"Incorrect because the distinction is inflation adjustment, not tax deduction.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_634","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_634","question":"What is meant by a current account deficit on a country's balance of payments?","options":{"A":"The total value of a country's imports of goods and services exceeds the total value of its exports.","B":"The government's annual tax revenue exceeds its public expenditure.","C":"The value of a country's exports exceeds the value of its imports.","D":"Commercial banks lend more money than households deposit."},"correctOption":"A","correctAnswer":"The total value of a country's imports of goods and services exceeds the total value of its exports.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a current account trade deficit occurs when outward payments for imports exceed inward earnings from exports.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax revenue exceeding public spending is a fiscal *budget surplus*.","C":"Incorrect because exports exceeding imports defines a current account *surplus*.","D":"Incorrect because domestic bank lending ratios are unrelated to the balance of payments."}}},{"id":"P1_U6_MCQ_635","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_635","question":"What is the difference between visible trade and invisible trade on the balance of payments?","options":{"A":"Visible trade is legal trade recorded by customs, whereas invisible trade is illegal smuggling.","B":"Visible trade involves physical goods such as cars and wheat, whereas invisible trade involves intangible services such as banking, tourism, and insurance.","C":"Visible trade occurs only within a country, whereas invisible trade occurs only across borders.","D":"Visible trade uses cash payments, whereas invisible trade uses barter."},"correctOption":"B","correctAnswer":"Visible trade involves physical goods such as cars and wheat, whereas invisible trade involves intangible services such as banking, tourism, and insurance.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because visible exports/imports are tangible merchandise goods, while invisible exports/imports are cross-border services.","distractor_reasons":{"A":"Incorrect because both visible and invisible trade are legal recorded economic transactions.","B":"Correct selection.","C":"Incorrect because both categories measure international cross-border transactions.","D":"Incorrect because both are settled through standard international financial payments."}}},{"id":"P1_U6_MCQ_636","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_636","question":"What is a government budget deficit?","options":{"A":"When a country's imports exceed its exports over a financial year.","B":"When a private limited company makes a net loss after paying expenses.","C":"When government expenditure exceeds government tax revenue in a given fiscal year, requiring government borrowing.","D":"When a central bank reduces the national money supply."},"correctOption":"C","correctAnswer":"When government expenditure exceeds government tax revenue in a given fiscal year, requiring government borrowing.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a fiscal budget deficit arises whenever public spending outstrips tax receipts.","distractor_reasons":{"A":"Incorrect because imports exceeding exports is a *trade deficit* (current account deficit), not a fiscal budget deficit.","B":"Incorrect because a company's expenses exceeding revenue is a corporate net loss.","C":"Correct selection.","D":"Incorrect because reducing the money supply is monetary contraction."}}},{"id":"P1_U6_MCQ_637","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_637","question":"What is a government budget surplus?","options":{"A":"When government spending is greater than tax revenue.","B":"When household savings exceed commercial bank loans.","C":"When a country's exports equal its imports exactly.","D":"When government tax revenue exceeds government expenditure in a fiscal year."},"correctOption":"D","correctAnswer":"When government tax revenue exceeds government expenditure in a fiscal year.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a fiscal budget surplus occurs when tax inflows exceed public spending outflows, allowing the government to repay national debt.","distractor_reasons":{"A":"Incorrect because public spending exceeding tax revenue is a budget *deficit*.","B":"Incorrect because private savings ratios do not define the government's fiscal budget.","C":"Incorrect because equal exports and imports represent balanced trade.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_638","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_638","question":"Which set of four outcomes represents the main macroeconomic objectives of most governments?","options":{"A":"Low and stable inflation, low unemployment, steady economic growth, and a sustainable balance of payments.","B":"High inflation, high unemployment, falling GDP, and permanent trade deficits.","C":"Zero exports, maximum tax rates, currency collapse, and high interest rates.","D":"Complete elimination of all private businesses, zero economic growth, and fixed wages."},"correctOption":"A","correctAnswer":"Low and stable inflation, low unemployment, steady economic growth, and a sustainable balance of payments.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Cambridge syllabus theory identifies price stability, full/high employment, sustained real GDP growth, and balance of payments equilibrium as the four core government economic objectives.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because these are economic problems that governments seek to avoid.","C":"Incorrect because these outcomes harm national living standards and business competitiveness.","D":"Incorrect because market and mixed economies encourage private enterprise and economic growth."}}},{"id":"P1_U6_MCQ_639","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_639","question":"Why can the government objective of rapid economic growth conflict with the objective of low inflation?","options":{"A":"Because rapid economic growth always lowers consumer spending and causes deflation.","B":"Because rapid economic growth boosts demand and creates labour and capacity shortages, pushing wages and prices upward.","C":"Because economic growth forces the central bank to cut interest rates to zero.","D":"Because rapid economic growth eliminates all indirect taxes on goods."},"correctOption":"B","correctAnswer":"Because rapid economic growth boosts demand and creates labour and capacity shortages, pushing wages and prices upward.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when output expands faster than productive capacity, tight labour markets and bottlenecks generate demand-pull and cost-push inflation.","distractor_reasons":{"A":"Incorrect because growth increases, rather than lowers, consumer spending.","B":"Correct selection.","C":"Incorrect because central banks typically *raise* interest rates during rapid inflationary booms.","D":"Incorrect because indirect taxes remain in place during economic growth."}}},{"id":"P1_U6_MCQ_640","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_640","question":"How does a progressive tax (such as most personal income tax systems) operate?","options":{"A":"Every citizen pays the exact same fixed dollar amount of tax regardless of income.","B":"Lower-income earners pay a higher percentage of their income in tax than higher-income earners.","C":"Higher-income earners pay a larger percentage of their income in tax as their income rises.","D":"Only loss-making businesses are required to pay the tax."},"correctOption":"C","correctAnswer":"Higher-income earners pay a larger percentage of their income in tax as their income rises.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because progressive taxation applies higher marginal tax rates to higher income brackets, redistributing income.","distractor_reasons":{"A":"Incorrect because a fixed sum per person is a lump-sum or poll tax.","B":"Incorrect because taking a higher percentage from lower earners describes a *regressive* tax impact.","C":"Correct selection.","D":"Incorrect because progressive income taxes apply to personal earnings above tax-free thresholds."}}},{"id":"P1_U6_MCQ_641","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_641","question":"Why are indirect taxes such as Value Added Tax (VAT) often described as regressive in their impact on households?","options":{"A":"Because wealthy households pay a higher VAT percentage rate than poor households.","B":"Because VAT is deducted directly from company profits.","C":"Because low-income households are exempt from paying VAT in supermarkets.","D":"Because everyone pays the same tax rate on purchases, meaning the tax takes up a larger proportion of a poor household's income than a rich household's income."},"correctOption":"D","correctAnswer":"Because everyone pays the same tax rate on purchases, meaning the tax takes up a larger proportion of a poor household's income than a rich household's income.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lower-income families spend a higher share of their total income on taxed goods, making indirect taxes proportionally heavier for them.","distractor_reasons":{"A":"Incorrect because VAT rates are uniform per product regardless of buyer wealth.","B":"Incorrect because VAT is an indirect tax on consumption expenditure, not profit.","C":"Incorrect because VAT is included in retail shelf prices paid by all shoppers.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_642","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_642","question":"What is contractionary fiscal policy?","options":{"A":"Increasing tax rates and reducing government expenditure in order to slow down aggregate demand and control inflation.","B":"Cutting income tax rates and increasing public spending to pull an economy out of recession.","C":"Lowering central bank interest rates to stimulate business borrowing.","D":"Eliminating all import tariffs to encourage international trade."},"correctOption":"A","correctAnswer":"Increasing tax rates and reducing government expenditure in order to slow down aggregate demand and control inflation.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher taxes and lower government spending withdraw demand from the economy to cool an inflationary boom or reduce a budget deficit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax cuts and higher public spending define *expansionary* fiscal policy.","C":"Incorrect because lowering interest rates is *expansionary monetary* policy.","D":"Incorrect because removing tariffs is trade liberalisation."}}},{"id":"P1_U6_MCQ_643","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_643","question":"What is expansionary monetary policy?","options":{"A":"Raising corporation tax and cutting public hospital funding.","B":"Lowering interest rates and increasing the money supply to encourage borrowing, consumer spending, and business investment.","C":"Imposing strict physical quotas on imported steel and electronics.","D":"Raising interest rates sharply to reduce consumer credit card spending."},"correctOption":"B","correctAnswer":"Lowering interest rates and increasing the money supply to encourage borrowing, consumer spending, and business investment.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cutting interest rates lowers the cost of loans and reduces the incentive to save, stimulating spending during slowdowns.","distractor_reasons":{"A":"Incorrect because raising taxes and cutting spending is contractionary fiscal policy.","B":"Correct selection.","C":"Incorrect because quotas are protectionist trade measures.","D":"Incorrect because raising interest rates is *contractionary* monetary policy."}}},{"id":"P1_U6_MCQ_644","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_644","question":"Which of the following is an example of a government supply-side policy?","options":{"A":"Increasing Value Added Tax from 15% to 20%.","B":"Raising the central bank base interest rate to 8%.","C":"Investing in vocational training programmes and removing unnecessary bureaucratic regulations to boost business productivity.","D":"Placing a total embargo on foreign imports."},"correctOption":"C","correctAnswer":"Investing in vocational training programmes and removing unnecessary bureaucratic regulations to boost business productivity.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because workforce upskilling and deregulation improve the economy's productive capacity and efficiency.","distractor_reasons":{"A":"Incorrect because raising VAT is a demand-side fiscal tax increase.","B":"Incorrect because raising interest rates is a demand-side monetary policy.","C":"Correct selection.","D":"Incorrect because a trade embargo is a protectionist restriction."}}},{"id":"P1_U6_MCQ_645","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_645","question":"How does privatisation function as a supply-side policy?","options":{"A":"By transferring private companies into state-owned monopolies.","B":"By increasing personal income tax on all private sector workers.","C":"By fixing maximum prices on all consumer goods.","D":"By selling state-owned enterprises to private investors so the profit motive and competition drive greater efficiency and innovation."},"correctOption":"D","correctAnswer":"By selling state-owned enterprises to private investors so the profit motive and competition drive greater efficiency and innovation.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because private ownership exposes businesses to market competition and profit incentives, encouraging cost efficiency.","distractor_reasons":{"A":"Incorrect because transferring private firms to state ownership is *nationalisation*.","B":"Incorrect because privatisation changes ownership rather than raising personal income taxes.","C":"Incorrect because price ceilings are market controls, not privatisation.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_646","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_646","question":"What is deregulation as a government supply-side policy?","options":{"A":"Removing unnecessary legal rules and administrative red tape to make it easier and cheaper for businesses to operate and compete.","B":"Passing hundreds of new laws restricting business opening hours.","C":"Raising corporation tax rates on small and medium enterprises.","D":"Requiring every new business to obtain twenty separate government licences."},"correctOption":"A","correctAnswer":"Removing unnecessary legal rules and administrative red tape to make it easier and cheaper for businesses to operate and compete.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because deregulation reduces compliance costs and lowers barriers to entry, stimulating competition and enterprise.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because adding new operating restrictions is *increasing* regulation.","C":"Incorrect because raising corporation tax is fiscal policy.","D":"Incorrect because adding licensing hurdles increases bureaucracy rather than deregulating."}}},{"id":"P1_U6_MCQ_647","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_647","question":"How does an increase in corporation tax directly affect a limited company?","options":{"A":"It raises the retail price of every product through a checkout sales tax.","B":"It reduces the company's after-tax profit, leaving less retained profit for reinvestment and less money for shareholder dividends.","C":"It increases employees' personal income tax deductions directly.","D":"It lowers the interest rate the company pays on existing bank loans."},"correctOption":"B","correctAnswer":"It reduces the company's after-tax profit, leaving less retained profit for reinvestment and less money for shareholder dividends.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because corporation tax is levied directly on company profits, reducing net funds available for internal growth or dividend payouts.","distractor_reasons":{"A":"Incorrect because checkout sales taxes are indirect taxes like VAT, not corporation tax.","B":"Correct selection.","C":"Incorrect because employee wage deductions come from personal income tax.","D":"Incorrect because corporation tax does not lower commercial loan interest rates."}}},{"id":"P1_U6_MCQ_648","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_648","question":"Why do higher interest rates reduce business capital investment?","options":{"A":"Because higher interest rates lower the cost of borrowing money from banks.","B":"Because higher interest rates increase consumer disposable income and retail sales.","C":"Because borrowing to fund new machinery becomes more expensive, and retained cash earns a higher return in bank deposits rather than risky projects.","D":"Because higher interest rates eliminate corporation tax on factory equipment."},"correctOption":"C","correctAnswer":"Because borrowing to fund new machinery becomes more expensive, and retained cash earns a higher return in bank deposits rather than risky projects.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because higher interest rates raise both the direct cost of debt finance and the opportunity cost of using internal cash reserves.","distractor_reasons":{"A":"Incorrect because higher interest rates *increase*, not lower, borrowing costs.","B":"Incorrect because higher interest rates squeeze mortgage holders and reduce consumer spending.","C":"Correct selection.","D":"Incorrect because interest rates do not waive corporation tax."}}},{"id":"P1_U6_MCQ_649","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_649","question":"Which stage of the business cycle immediately follows a slump as GDP begins to rise again and business confidence slowly returns?","options":{"A":"Boom","B":"Recession","C":"Stagflation","D":"Recovery"},"correctOption":"D","correctAnswer":"Recovery","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because recovery marks the turning point out of a slump when output stops falling and begins expanding again.","distractor_reasons":{"A":"Incorrect because a boom is the peak reached after sustained growth, not immediately after a slump.","B":"Incorrect because a recession is the downturn *into* a slump.","C":"Incorrect because stagflation is a combination of stagnant growth and high inflation, not a standard business cycle stage.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_650","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_650","question":"What is an excise duty?","options":{"A":"A selective indirect tax levied on specific goods such as fuel, tobacco, and alcohol to raise revenue and discourage harmful consumption.","B":"A direct tax paid on a company's annual net profit.","C":"A subsidy paid by the government to encourage renewable energy.","D":"A fee charged by commercial banks for international wire transfers."},"correctOption":"A","correctAnswer":"A selective indirect tax levied on specific goods such as fuel, tobacco, and alcohol to raise revenue and discourage harmful consumption.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because excise duties are targeted indirect taxes placed on specific demerit or price-inelastic goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax on company net profit is corporation tax.","C":"Incorrect because an excise duty is a tax, not a government subsidy.","D":"Incorrect because bank transfer fees are private financial charges."}}},{"id":"P1_U6_MCQ_651","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_651","question":"Which technological development has been a major driver of modern globalisation?","options":{"A":"The banning of international air freight and container shipping.","B":"High-speed global internet communications and standardised container shipping, which dramatically lowered cross-border coordination and transport costs.","C":"The elimination of all foreign exchange markets.","D":"Government laws requiring every factory to source materials locally."},"correctOption":"B","correctAnswer":"High-speed global internet communications and standardised container shipping, which dramatically lowered cross-border coordination and transport costs.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cheap containerised sea transport and instant digital communications enable businesses to manage global supply chains and serve overseas buyers.","distractor_reasons":{"A":"Incorrect because container shipping and air freight expanded rather than stopped.","B":"Correct selection.","C":"Incorrect because active currency markets facilitate international trade and investment.","D":"Incorrect because trade liberalisation reduced local-content restrictions."}}},{"id":"P1_U6_MCQ_652","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_652","question":"How does globalisation generally benefit consumers?","options":{"A":"By reducing product choice to only locally made items.","B":"By eliminating all quality standards on imported goods.","C":"By offering wider product variety, access to out-of-season goods, and lower prices resulting from global competition and economies of scale.","D":"By increasing import tariffs on everyday household items."},"correctOption":"C","correctAnswer":"By offering wider product variety, access to out-of-season goods, and lower prices resulting from global competition and economies of scale.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because international trade expands consumer choice and drives competitive pricing across borders.","distractor_reasons":{"A":"Incorrect because globalisation *expands* choice by bringing foreign products into domestic shops.","B":"Incorrect because imported goods must still meet domestic consumer safety regulations.","C":"Correct selection.","D":"Incorrect because globalisation is associated with falling, not rising, trade barriers."}}},{"id":"P1_U6_MCQ_653","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_653","question":"What is a major threat posed by globalisation to small domestic businesses?","options":{"A":"Complete inability to purchase imported equipment.","B":"Automatic government bans on domestic advertising.","C":"Guaranteed monopoly power in their home market.","D":"Intense price competition from giant foreign multinational companies benefiting from huge economies of scale."},"correctOption":"D","correctAnswer":"Intense price competition from giant foreign multinational companies benefiting from huge economies of scale.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opening domestic markets exposes smaller local firms to lower-cost, heavily marketed global rivals.","distractor_reasons":{"A":"Incorrect because globalisation makes importing equipment easier.","B":"Incorrect because domestic businesses remain free to advertise.","C":"Incorrect because globalisation *reduces* domestic monopoly power by introducing foreign competitors.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_654","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_654","question":"What is the difference between a free trade area and a customs union?","options":{"A":"Both remove internal tariffs between members, but a customs union also adopts a common external tariff on imports from non-member countries.","B":"A free trade area uses a single currency, whereas a customs union bans all trade.","C":"A free trade area imposes high tariffs between members, whereas a customs union removes tariffs only on services.","D":"There is no difference between a free trade area and a customs union."},"correctOption":"A","correctAnswer":"Both remove internal tariffs between members, but a customs union also adopts a common external tariff on imports from non-member countries.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in a free trade area each member sets its own tariffs toward non-members, whereas a customs union enforces a unified external tariff.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sharing a single currency defines a monetary union, not a free trade area.","C":"Incorrect because both remove internal tariffs among member states.","D":"Incorrect because the common external tariff distinguishes a customs union."}}},{"id":"P1_U6_MCQ_655","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_655","question":"What is meant by 'dumping' in international trade?","options":{"A":"Disposing of industrial waste illegally in international oceans.","B":"Exporting surplus goods to a foreign market at prices below their production cost to gain market share and drive domestic producers out of business.","C":"Refusing to export any raw materials to developing economies.","D":"Raising export prices above domestic prices to maximise profit margins."},"correctOption":"B","correctAnswer":"Exporting surplus goods to a foreign market at prices below their production cost to gain market share and drive domestic producers out of business.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because dumping is international predatory pricing, which governments frequently counter with anti-dumping tariffs.","distractor_reasons":{"A":"Incorrect because ocean waste disposal is marine pollution, not the trade term 'dumping'.","B":"Correct selection.","C":"Incorrect because restricting exports is an export ban, not dumping.","D":"Incorrect because dumping involves selling *below* cost, not at inflated prices."}}},{"id":"P1_U6_MCQ_656","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_656","question":"Why do governments sometimes use protectionism to shield 'strategic industries' such as defence, energy, or staple food production?","options":{"A":"To ensure the country is not dangerously dependent on foreign suppliers during wars, pandemics, or global supply disruptions.","B":"To force domestic consumers to pay higher prices for luxury fashion.","C":"To guarantee that domestic farms go bankrupt quickly.","D":"To eliminate all domestic employment in agriculture and energy."},"correctOption":"A","correctAnswer":"To ensure the country is not dangerously dependent on foreign suppliers during wars, pandemics, or global supply disruptions.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because national security and self-sufficiency in vital essentials justify maintaining domestic production capacity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because strategic industries concern national survival essentials rather than luxury fashion.","C":"Incorrect because protectionism aims to keep domestic farms viable.","D":"Incorrect because protecting strategic industries preserves domestic jobs."}}},{"id":"P1_U6_MCQ_657","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_657","question":"What is a major disadvantage of import tariffs for domestic consumers and businesses?","options":{"A":"Tariffs lower the cost of imported raw materials for domestic factories.","B":"Tariffs eliminate the risk of trade retaliation by foreign governments.","C":"Tariffs raise prices for consumers, increase input costs for firms using imported components, and can provoke retaliatory tariffs against domestic exporters.","D":"Tariffs guarantee that domestic firms become world leaders in innovation."},"correctOption":"C","correctAnswer":"Tariffs raise prices for consumers, increase input costs for firms using imported components, and can provoke retaliatory tariffs against domestic exporters.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because protectionism reduces consumer purchasing power, harms import-dependent manufacturers, and risks tit-for-tat trade wars.","distractor_reasons":{"A":"Incorrect because tariffs *increase*, rather than lower, the cost of imported inputs.","B":"Incorrect because tariffs frequently trigger foreign retaliation.","C":"Correct selection.","D":"Incorrect because shielding domestic firms from competition often reduces their incentive to innovate."}}},{"id":"P1_U6_MCQ_658","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_658","question":"How is a floating exchange rate determined?","options":{"A":"By the United Nations setting a fixed price for every currency each year.","B":"By commercial supermarkets setting currency values at checkout tills.","C":"By international treaties banning any movement in currency values.","D":"By the forces of demand for and supply of the currency on foreign exchange markets without direct government intervention."},"correctOption":"D","correctAnswer":"By the forces of demand for and supply of the currency on foreign exchange markets without direct government intervention.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because under a floating regime, exchange rates fluctuate continuously based on trade flows, investment flows, and interest rate differentials.","distractor_reasons":{"A":"Incorrect because the UN does not set national exchange rates.","B":"Incorrect because retailers use market exchange rates rather than setting them.","C":"Incorrect because banning currency movement describes a fixed exchange rate, not a floating one.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_659","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_659","question":"What is a fixed exchange rate system?","options":{"A":"A system where a country's government or central bank pegs its currency's value to another major currency (such as the US dollar) and intervenes to keep it constant.","B":"A system where currency values change every second based solely on private speculation.","C":"A system where businesses are banned from trading with foreign customers.","D":"A system where all prices inside domestic shops remain frozen forever."},"correctOption":"A","correctAnswer":"A system where a country's government or central bank pegs its currency's value to another major currency (such as the US dollar) and intervenes to keep it constant.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a fixed exchange rate eliminates day-to-day currency volatility by committing the central bank to maintain a target parity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because continuous market-driven fluctuation defines a *floating* exchange rate.","C":"Incorrect because fixed exchange rates are designed to facilitate stable international trade.","D":"Incorrect because domestic shop prices still change with supply, demand, and inflation."}}},{"id":"P1_U6_MCQ_660","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_660","question":"How does a sharp rise in a country's interest rates usually affect its floating exchange rate?","options":{"A":"It causes the currency to depreciate because foreign investors withdraw all their savings.","B":"It attracts inflows of foreign capital seeking higher returns, increasing demand for the currency and causing it to appreciate.","C":"It has no possible connection to foreign exchange markets.","D":"It forces the government to abolish its national currency."},"correctOption":"B","correctAnswer":"It attracts inflows of foreign capital seeking higher returns, increasing demand for the currency and causing it to appreciate.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher domestic interest rates attract international savers and investors ('hot money'), boosting demand for the domestic currency.","distractor_reasons":{"A":"Incorrect because higher interest returns attract, rather than repel, foreign financial inflows.","B":"Correct selection.","C":"Incorrect because interest rate differentials are a primary driver of currency demand.","D":"Incorrect because interest rate adjustments are normal monetary policy."}}},{"id":"P1_U6_MCQ_661","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_661","question":"Why do multinational companies often locate manufacturing plants in developing economies?","options":{"A":"Because developing economies always have higher wage rates than developed countries.","B":"Because developing economies forbid all foreign companies from exporting goods.","C":"To take advantage of lower labour and land costs, abundant raw materials, and government investment incentives.","D":"To avoid selling products to customers anywhere in the world."},"correctOption":"C","correctAnswer":"To take advantage of lower labour and land costs, abundant raw materials, and government investment incentives.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lower operating costs and tax incentives enable MNCs to reduce unit production expenses and improve global price competitiveness.","distractor_reasons":{"A":"Incorrect because wage rates in developing economies are generally lower, which is the cost advantage sought.","B":"Incorrect because host countries usually encourage MNCs to export and earn foreign currency.","C":"Correct selection.","D":"Incorrect because MNCs produce goods to sell across global and growing domestic markets."}}},{"id":"P1_U6_MCQ_662","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_662","question":"What is a 'market-seeking' motive for a business becoming a multinational company?","options":{"A":"Closing all sales offices to focus solely on mining raw minerals.","B":"Reducing the number of customers served by the business.","C":"Moving headquarters to a desert island with zero population.","D":"Setting up production or retail outlets inside fast-growing or large foreign consumer markets to boost sales and avoid import tariffs."},"correctOption":"D","correctAnswer":"Setting up production or retail outlets inside fast-growing or large foreign consumer markets to boost sales and avoid import tariffs.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when domestic markets become saturated, establishing operations inside overseas markets unlocks new revenue growth.","distractor_reasons":{"A":"Incorrect because mining raw minerals is a *resource-seeking* motive.","B":"Incorrect because market-seeking MNCs aim to *expand* their customer base.","C":"Incorrect because market-seeking firms target populous or affluent consumer markets.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_663","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_663","question":"Which benefit does inward investment by a multinational company bring to a host country's government?","options":{"A":"Increased tax revenues from corporation tax, employee income taxes, and indirect taxes, which can fund public infrastructure and services.","B":"Complete elimination of the need for any domestic businesses.","C":"Guaranteed zero unemployment across every town in the country forever.","D":"Automatic appreciation of foreign currencies against the host currency."},"correctOption":"A","correctAnswer":"Increased tax revenues from corporation tax, employee income taxes, and indirect taxes, which can fund public infrastructure and services.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because MNC operations expand formal employment and taxable business profits in the host economy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because host economies still rely heavily on domestic small and medium enterprises.","C":"Incorrect because MNCs create jobs in specific sectors/regions rather than guaranteeing zero national unemployment forever.","D":"Incorrect because inward investment inflows actually increase demand for the *host* currency."}}},{"id":"P1_U6_MCQ_664","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_664","question":"How can multinational companies benefit local suppliers in a host country?","options":{"A":"By refusing to buy any components or services from domestic firms.","B":"By creating demand for local raw materials, packaging, logistics, and catering, while helping local suppliers upgrade quality standards.","C":"By forcing all local suppliers to shut down immediately.","D":"By paying local suppliers below zero prices."},"correctOption":"B","correctAnswer":"By creating demand for local raw materials, packaging, logistics, and catering, while helping local suppliers upgrade quality standards.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because MNC supply-chain linkages create indirect jobs and transfer technical and quality-control knowledge to domestic firms.","distractor_reasons":{"A":"Incorrect because MNCs frequently source local inputs and services to cut transport costs.","B":"Correct selection.","C":"Incorrect because MNCs rely on local service and component suppliers.","D":"Incorrect because suppliers are paid commercial contract prices."}}},{"id":"P1_U6_MCQ_665","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_665","question":"Why do critics sometimes accuse multinational companies of exploiting workers and natural resources in host countries?","options":{"A":"Because MNCs always pay ten times the average local salary.","B":"Because MNCs never extract oil, timber, or minerals anywhere in the world.","C":"Because some MNCs locate in countries with weak labour or environmental laws to pay very low wages, enforce poor working conditions, or deplete finite resources.","D":"Because MNCs are legally forbidden from hiring local citizens."},"correctOption":"C","correctAnswer":"Because some MNCs locate in countries with weak labour or environmental laws to pay very low wages, enforce poor working conditions, or deplete finite resources.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because regulatory differences between nations can tempt unethical MNCs to lower labour and environmental standards abroad.","distractor_reasons":{"A":"Incorrect because paying generous wages is praised rather than criticised as exploitation.","B":"Incorrect because many major MNCs operate in extractive mining, oil, and forestry industries.","C":"Correct selection.","D":"Incorrect because MNCs employ millions of local host-country workers."}}},{"id":"P1_U6_MCQ_666","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_666","question":"Why are senior management roles in a multinational company's host-country subsidiary sometimes criticised by local communities?","options":{"A":"Because MNCs never hire any local workers for factory floor roles.","B":"Because local managers are legally banned from speaking their native language.","C":"Because MNC subsidiaries never earn any revenue.","D":"Because high-paid executive and R&D positions are often kept at the home-country headquarters, leaving mostly lower-skilled jobs for host-country workers."},"correctOption":"D","correctAnswer":"Because high-paid executive and R&D positions are often kept at the home-country headquarters, leaving mostly lower-skilled jobs for host-country workers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because concentrating top decision-making and innovation in the home country limits career progression and high-value spillovers in host nations.","distractor_reasons":{"A":"Incorrect because MNCs hire large numbers of local production and service staff.","B":"Incorrect because local languages are used in daily factory and shop operations.","C":"Incorrect because subsidiaries generate substantial sales and output.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_667","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_667","question":"What is meant by 'glocalisation' in international business strategy?","options":{"A":"Combining global brand scale and efficiency with local adaptations to products, menus, and marketing to suit each country's culture and tastes.","B":"Selling the exact same unchanged product worldwide regardless of local religious or cultural taboos.","C":"Withdrawing from all foreign markets to sell exclusively in one home city.","D":"Using only local suppliers while banning all foreign customers."},"correctOption":"A","correctAnswer":"Combining global brand scale and efficiency with local adaptations to products, menus, and marketing to suit each country's culture and tastes.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 'think global, act local' respects local preferences while preserving global economies of scale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ignoring local cultural differences is pure standardisation, which often fails abroad.","C":"Incorrect because glocalisation is a strategy for *operating* across global markets.","D":"Incorrect because glocalisation serves consumers across multiple countries."}}},{"id":"P1_U6_MCQ_668","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_668","question":"How do exchange rate fluctuations create uncertainty for importing and exporting businesses?","options":{"A":"They guarantee that export profits increase every single month.","B":"Sudden shifts in currency values alter the domestic-currency value of foreign invoices and costs between the order date and payment date, making profit margins unpredictable.","C":"They eliminate the need for businesses to keep financial accounts.","D":"They fix the price of all imported raw materials permanently."},"correctOption":"B","correctAnswer":"Sudden shifts in currency values alter the domestic-currency value of foreign invoices and costs between the order date and payment date, making profit margins unpredictable.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because exchange rate volatility introduces foreign exchange risk into international contracts and long-term pricing.","distractor_reasons":{"A":"Incorrect because currency appreciation can sharply *reduce* export profits.","B":"Correct selection.","C":"Incorrect because businesses must carefully track foreign exchange gains and losses in their accounts.","D":"Incorrect because floating exchange rates cause imported input prices to fluctuate."}}},{"id":"P1_U6_MCQ_669","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_669","question":"What is a joint venture as a method of entering an overseas market?","options":{"A":"Exporting products directly through online parcel couriers without any local partners.","B":"Acquiring 100% of a foreign competitor through a hostile takeover.","C":"Two or more businesses (often a foreign entrant and a local firm) agreeing to share capital, risks, profits, and local market knowledge in a joint business project.","D":"Lobbying the home government to impose import quotas on foreign goods."},"correctOption":"C","correctAnswer":"Two or more businesses (often a foreign entrant and a local firm) agreeing to share capital, risks, profits, and local market knowledge in a joint business project.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because partnering with an established domestic firm reduces entry risk and provides immediate local regulatory and cultural expertise.","distractor_reasons":{"A":"Incorrect because direct online shipping is exporting, not a joint venture.","B":"Incorrect because buying 100% of a firm is a full acquisition/takeover.","C":"Correct selection.","D":"Incorrect because lobbying for quotas is domestic protectionism."}}},{"id":"P1_U6_MCQ_670","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_670","question":"What is international licensing?","options":{"A":"A government ban preventing any domestic company from selling abroad.","B":"A tax paid by tourists when exchanging currency at airports.","C":"Building a wholly owned factory in a foreign country from scratch.","D":"Granting a foreign business legal permission to produce or sell a company's patented product or trademarked brand in exchange for a fee or royalty."},"correctOption":"D","correctAnswer":"Granting a foreign business legal permission to produce or sell a company's patented product or trademarked brand in exchange for a fee or royalty.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because licensing enables rapid global expansion with low capital investment while earning royalty income.","distractor_reasons":{"A":"Incorrect because licensing facilitates, rather than bans, international brand expansion.","B":"Incorrect because currency exchange fees are financial service charges.","C":"Incorrect because building a wholly owned overseas plant is greenfield foreign direct investment.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_671","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_671","question":"Why do multinational companies gain significant economies of scale compared to purely domestic firms?","options":{"A":"Because producing and purchasing for huge global markets lowers average unit costs of raw materials, R&D, and marketing.","B":"Because multinational companies never have to pay wages or taxes.","C":"Because multinational companies sell only one unit per year at a very high price.","D":"Because global operations eliminate all communication and transport expenses."},"correctOption":"A","correctAnswer":"Because producing and purchasing for huge global markets lowers average unit costs of raw materials, R&D, and marketing.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large global output volumes spread fixed research, branding, and administrative costs over millions of units.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because MNCs pay substantial global payroll and tax bills.","C":"Incorrect because economies of scale arise from *high-volume* production.","D":"Incorrect because global logistics and coordination actually increase transport and communication outlays."}}},{"id":"P1_U6_MCQ_672","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_672","question":"How can a business reduce its vulnerability to exchange rate fluctuations when operating internationally?","options":{"A":"By refusing to accept any payments from foreign customers.","B":"By producing inside key foreign markets so revenues and costs are in the same currency, or agreeing fixed forward exchange contracts with banks.","C":"By ignoring exchange rates when setting international selling prices.","D":"By keeping all cash reserves in physical gold bars inside retail shops."},"correctOption":"B","correctAnswer":"By producing inside key foreign markets so revenues and costs are in the same currency, or agreeing fixed forward exchange contracts with banks.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because natural currency matching (local production) and forward currency contracts lock in exchange rates and protect profit margins.","distractor_reasons":{"A":"Incorrect because refusing foreign payments would halt international sales.","B":"Correct selection.","C":"Incorrect because ignoring exchange rates exposes profits to severe unexpected losses.","D":"Incorrect because holding physical gold in shops is impractical and still exposes the firm to gold price volatility."}}},{"id":"P1_U6_MCQ_673","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_673","question":"What is a global supply chain?","options":{"A":"A single retail store selling goods made entirely in the same building.","B":"A government agency that regulates domestic interest rates.","C":"A worldwide network of suppliers, manufacturers, warehouses, and distributors across multiple countries involved in producing and delivering a product.","D":"A trade barrier blocking all foreign components from entering a country."},"correctOption":"C","correctAnswer":"A worldwide network of suppliers, manufacturers, warehouses, and distributors across multiple countries involved in producing and delivering a product.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because modern products frequently combine raw materials, components, and assembly across several specialised countries.","distractor_reasons":{"A":"Incorrect because single-site production is purely local rather than global.","B":"Incorrect because central banks regulate interest rates.","C":"Correct selection.","D":"Incorrect because trade barriers restrict rather than constitute global supply chains."}}},{"id":"P1_U6_MCQ_674","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_674","question":"Why are global supply chains vulnerable to external shocks?","options":{"A":"Because every component is manufactured inside the customer's home.","B":"Because global supply chains never use ships, aircraft, or lorries.","C":"Because international trade is completely unaffected by weather or politics.","D":"Because natural disasters, port congestion, pandemics, or trade wars in one country can halt component deliveries and stop assembly worldwide."},"correctOption":"D","correctAnswer":"Because natural disasters, port congestion, pandemics, or trade wars in one country can halt component deliveries and stop assembly worldwide.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lean, cross-border supply chains rely on smooth international logistics, making them sensitive to geopolitical or natural disruptions.","distractor_reasons":{"A":"Incorrect because components travel across multiple borders.","B":"Incorrect because global supply chains depend heavily on maritime, air, and road freight.","C":"Incorrect because extreme weather and political tariffs frequently disrupt trade routes.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_675","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_675","question":"How does a strong (appreciating) domestic currency affect a country's balance of trade in goods and services?","options":{"A":"It tends to worsen the trade balance (moving toward a deficit) because exports become dearer abroad while imports become cheaper domestically.","B":"It guarantees a massive trade surplus because exports become free for foreign buyers.","C":"It stops all domestic consumers from buying imported products.","D":"It has no effect on either export competitiveness or import demand."},"correctOption":"A","correctAnswer":"It tends to worsen the trade balance (moving toward a deficit) because exports become dearer abroad while imports become cheaper domestically.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dearer exports reduce export volume while cheaper imports encourage domestic buyers to purchase more foreign goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because appreciation makes exports *more expensive*, not free.","C":"Incorrect because cheaper imports actually *encourage* higher import spending.","D":"Incorrect because exchange rates directly alter relative prices of traded goods."}}},{"id":"P1_U6_MCQ_676","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_676","question":"Which business activities are major contributors to air pollution?","options":{"A":"Planting native trees and installing rooftop solar panels.","B":"Burning fossil fuels in factories and power stations, operating diesel freight fleets, and releasing industrial exhaust gases.","C":"Using digital accounting software and paperless invoicing.","D":"Recycling aluminium cans and glass bottles."},"correctOption":"B","correctAnswer":"Burning fossil fuels in factories and power stations, operating diesel freight fleets, and releasing industrial exhaust gases.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because combusting coal, oil, and diesel emits carbon dioxide, sulphur dioxide, nitrogen oxides, and harmful particulate matter.","distractor_reasons":{"A":"Incorrect because trees absorb CO2 and solar panels generate zero-emission electricity.","B":"Correct selection.","C":"Incorrect because digital administration reduces paper waste without causing air pollution.","D":"Incorrect because recycling saves energy and reduces industrial emissions."}}},{"id":"P1_U6_MCQ_677","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_677","question":"Which business practices commonly cause water pollution?","options":{"A":"Using closed-loop water filtration systems that purify and reuse factory water.","B":"Installing energy-efficient LED lighting in retail stores.","C":"Discharging untreated chemical effluent, heavy metals, oil spills, or agricultural pesticide runoff into rivers and oceans.","D":"Switching delivery fleets from diesel vans to electric bicycles."},"correctOption":"C","correctAnswer":"Discharging untreated chemical effluent, heavy metals, oil spills, or agricultural pesticide runoff into rivers and oceans.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because toxic industrial discharges and chemical agricultural runoff contaminate freshwater ecosystems and marine habitats.","distractor_reasons":{"A":"Incorrect because closed-loop filtration prevents water pollution.","B":"Incorrect because LED lighting reduces electricity consumption and has no water pollution impact.","C":"Correct selection.","D":"Incorrect because electric cargo bikes reduce air and noise emissions."}}},{"id":"P1_U6_MCQ_678","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_678","question":"Which of the following is an example of noise pollution generated by business operations?","options":{"A":"Toxic chemical waste buried in an underground landfill site.","B":"Plastic packaging littering a public beach.","C":"Carbon monoxide gas emitted from factory chimneys.","D":"Loud night-time aircraft take-offs, heavy construction machinery, or late-night freight deliveries disturbing nearby residents and wildlife."},"correctOption":"D","correctAnswer":"Loud night-time aircraft take-offs, heavy construction machinery, or late-night freight deliveries disturbing nearby residents and wildlife.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because excessive industrial, transport, or construction sound imposes health and sleep-disruption externalities on surrounding communities.","distractor_reasons":{"A":"Incorrect because buried toxic waste causes *land/soil* pollution.","B":"Incorrect because plastic litter causes *land/visual/marine* pollution.","C":"Incorrect because exhaust gases cause *air* pollution.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_679","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_679","question":"How does the 'circular economy' model differ from the traditional 'linear economy' model?","options":{"A":"A circular economy designs products to be reused, repaired, remanufactured, and recycled continuously, whereas a linear economy follows a 'take-make-dispose' path.","B":"A circular economy throws away all materials after a single use, whereas a linear economy recycles 100% of waste.","C":"A circular economy bans all manufacturing, whereas a linear economy uses only solar power.","D":"There is no difference between a circular economy and a linear economy."},"correctOption":"A","correctAnswer":"A circular economy designs products to be reused, repaired, remanufactured, and recycled continuously, whereas a linear economy follows a 'take-make-dispose' path.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because circularity eliminates waste by keeping materials and products in productive circulation for as long as possible.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses the definitions of circular and linear economies.","C":"Incorrect because circular businesses actively manufacture using recovered and renewable inputs.","D":"Incorrect because the two models represent fundamentally opposite approaches to resource use."}}},{"id":"P1_U6_MCQ_680","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_680","question":"What is meant by a 'biodegradable' material?","options":{"A":"A synthetic plastic that remains unchanged in landfills for thousands of years.","B":"A substance capable of being broken down naturally and harmlessly by bacteria and microorganisms into water, carbon dioxide, and organic matter.","C":"A toxic heavy metal that contaminates groundwater permanently.","D":"A non-renewable fossil fuel extracted from deep underground."},"correctOption":"B","correctAnswer":"A substance capable of being broken down naturally and harmlessly by bacteria and microorganisms into water, carbon dioxide, and organic matter.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because biodegradable packaging and materials decompose safely through natural biological processes.","distractor_reasons":{"A":"Incorrect because persistent synthetic plastics are *non-biodegradable*.","B":"Correct selection.","C":"Incorrect because toxic heavy metals do not decompose harmlessly.","D":"Incorrect because fossil fuels are non-renewable energy sources."}}},{"id":"P1_U6_MCQ_681","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_681","question":"What is the 'polluter pays principle' in environmental policy?","options":{"A":"The principle that taxpayers should pay to clean up pollution while polluting businesses keep all their profits.","B":"The principle that businesses receive government cash rewards for releasing toxic smoke.","C":"The principle that businesses responsible for producing pollution should bear the financial costs of preventing, controlling, or cleaning up that environmental damage.","D":"The principle that environmental laws apply only to households and never to factories."},"correctOption":"C","correctAnswer":"The principle that businesses responsible for producing pollution should bear the financial costs of preventing, controlling, or cleaning up that environmental damage.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because instruments like carbon taxes, landfill levies, and cleanup fines force businesses to internalise their external environmental costs.","distractor_reasons":{"A":"Incorrect because the principle shifts cleanup costs *onto* the polluter rather than onto innocent taxpayers.","B":"Incorrect because polluters are taxed or fined, not rewarded.","C":"Correct selection.","D":"Incorrect because industrial and commercial polluters are the primary focus of the principle."}}},{"id":"P1_U6_MCQ_682","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_682","question":"What is an Environmental Impact Assessment (EIA)?","options":{"A":"A financial calculation of a company's annual gross profit margin.","B":"A marketing survey measuring customer awareness of a new television advert.","C":"A tax return submitted to calculate personal income tax.","D":"A formal study evaluating the likely ecological, air, water, and community effects of a proposed major business project before planning permission is granted."},"correctOption":"D","correctAnswer":"A formal study evaluating the likely ecological, air, water, and community effects of a proposed major business project before planning permission is granted.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because EIAs identify potential external environmental costs early so regulators can require mitigation measures or reject harmful projects.","distractor_reasons":{"A":"Incorrect because profit margin calculations belong to financial accounting.","B":"Incorrect because advertising awareness surveys are market research.","C":"Incorrect because tax returns report financial income rather than ecological impacts.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_683","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_683","question":"What is meant by 'eco-efficiency' in business operations?","options":{"A":"Creating more goods and services while using fewer natural resources and generating less waste and pollution, thereby lowering both costs and environmental harm.","B":"Spending maximum money on unnecessary packaging to make products look larger.","C":"Increasing factory electricity consumption per unit of output.","D":"Ignoring environmental regulations to maximise short-term output."},"correctOption":"A","correctAnswer":"Creating more goods and services while using fewer natural resources and generating less waste and pollution, thereby lowering both costs and environmental harm.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because eco-efficiency achieves economic and environmental gains simultaneously ('doing more with less').","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because excess packaging wastes materials and increases costs.","C":"Incorrect because higher energy intensity is inefficient and costly.","D":"Incorrect because breaking regulations exposes the firm to fines and shutdowns."}}},{"id":"P1_U6_MCQ_684","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_684","question":"How does a 'cap-and-trade' emissions trading scheme work to limit industrial greenhouse gases?","options":{"A":"Governments allow factories to emit unlimited carbon dioxide without any permits.","B":"Governments set a strict overall ceiling (cap) on total emissions, issue tradable permits, and allow low-emitting firms to sell spare permits to high-emitting firms.","C":"Governments ban all manufacturing companies from trading shares on the stock market.","D":"Businesses pay a fixed fee to ignore all workplace safety laws."},"correctOption":"B","correctAnswer":"Governments set a strict overall ceiling (cap) on total emissions, issue tradable permits, and allow low-emitting firms to sell spare permits to high-emitting firms.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cap-and-trade guarantees an overall emissions reduction while rewarding firms that cut pollution cheapest.","distractor_reasons":{"A":"Incorrect because total emissions are strictly capped.","B":"Correct selection.","C":"Incorrect because permit trading concerns carbon allowances, not stock market listings.","D":"Incorrect because emissions schemes do not waive workplace safety laws."}}},{"id":"P1_U6_MCQ_685","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_685","question":"Which commercial activities are primary drivers of tropical deforestation?","options":{"A":"Rooftop urban gardening and bicycle courier services.","B":"Software development and online banking services.","C":"Unsustainable timber logging, clearing land for cattle ranching and monoculture plantations, and open-pit mining.","D":"Offshore wind turbine electricity generation."},"correctOption":"C","correctAnswer":"Unsustainable timber logging, clearing land for cattle ranching and monoculture plantations, and open-pit mining.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because large-scale agricultural expansion, logging, and mining destroy primary forests and release stored carbon.","distractor_reasons":{"A":"Incorrect because urban gardening and bike couriers do not clear tropical forests.","B":"Incorrect because digital services do not require forest clearance.","C":"Correct selection.","D":"Incorrect because offshore wind farms are built at sea."}}},{"id":"P1_U6_MCQ_686","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_686","question":"What is meant by 'overfishing' and why does it threaten long-term business sustainability?","options":{"A":"Farming fish sustainably in closed inland ponds without affecting wild oceans.","B":"Using selective nets that allow juvenile fish to escape and reproduce.","C":"Reducing fish prices so more families can afford healthy protein.","D":"Harvesting wild fish faster than populations can naturally reproduce, causing fish stocks to collapse and destroying future fishing livelihoods."},"correctOption":"D","correctAnswer":"Harvesting wild fish faster than populations can naturally reproduce, causing fish stocks to collapse and destroying future fishing livelihoods.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because depleting a renewable resource beyond its natural regeneration rate causes permanent ecological and commercial collapse.","distractor_reasons":{"A":"Incorrect because sustainable aquaculture avoids depleting wild stocks.","B":"Incorrect because selective nets protect juvenile fish and prevent overfishing.","C":"Incorrect because overfishing refers to unsustainable catch rates rather than consumer pricing.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_687","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_687","question":"What is 'lifecycle analysis' (cradle-to-grave assessment) of a product?","options":{"A":"Measuring the total environmental impact of a product at every stage—from raw material extraction, manufacturing, and transport, to consumer use and final disposal.","B":"Tracking only the sales revenue earned during a product's introduction stage.","C":"Calculating the exact age of every employee working on a production line.","D":"Advertising a product only to elderly consumers."},"correctOption":"A","correctAnswer":"Measuring the total environmental impact of a product at every stage—from raw material extraction, manufacturing, and transport, to consumer use and final disposal.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because full lifecycle assessment prevents shifting pollution from one stage (e.g., manufacturing) to another (e.g., toxic disposal).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sales tracking over time is the marketing *product life cycle*, not environmental lifecycle analysis.","C":"Incorrect because employee age demographics belong to human resources.","D":"Incorrect because target market segmentation is a marketing concept."}}},{"id":"P1_U6_MCQ_688","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_688","question":"How can businesses improve energy efficiency in their daily operations?","options":{"A":"Leaving factory machinery and office air conditioning running overnight when buildings are empty.","B":"Installing smart energy meters, upgrading insulation, using LED lighting, and replacing outdated motors with high-efficiency equipment.","C":"Replacing solar panels with inefficient coal-burning boilers.","D":"Increasing lorry idling times during loading and unloading."},"correctOption":"B","correctAnswer":"Installing smart energy meters, upgrading insulation, using LED lighting, and replacing outdated motors with high-efficiency equipment.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because energy efficiency measures cut kilowatt-hours consumed per unit of output, lowering both carbon emissions and utility bills.","distractor_reasons":{"A":"Incorrect because running equipment in empty buildings wastes energy and money.","B":"Correct selection.","C":"Incorrect because coal boilers increase emissions and lower efficiency.","D":"Incorrect because idling engines burn fuel wastefully."}}},{"id":"P1_U6_MCQ_689","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_689","question":"What is 'green supply chain management'?","options":{"A":"Painting all delivery lorries green without changing fuel type or routes.","B":"Sourcing raw materials from whichever distant supplier burns the most fossil fuels.","C":"Integrating environmental criteria into supplier selection, packaging design, low-carbon logistics, and reverse recycling across the entire supply network.","D":"Eliminating all quality checks on incoming raw materials."},"correctOption":"C","correctAnswer":"Integrating environmental criteria into supplier selection, packaging design, low-carbon logistics, and reverse recycling across the entire supply network.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because most of a company's environmental footprint often lies in upstream suppliers and downstream transport rather than inside its own office.","distractor_reasons":{"A":"Incorrect because superficial colour changes without operational reform are cosmetic.","B":"Incorrect because green logistics seeks to *minimise* transport emissions.","C":"Correct selection.","D":"Incorrect because quality assurance remains essential alongside environmental standards."}}},{"id":"P1_U6_MCQ_690","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_690","question":"Which of the following is an example of sustainable packaging?","options":{"A":"Wrapping single bananas in three layers of non-recyclable polystyrene and PVC film.","B":"Using oversized cardboard boxes filled with non-biodegradable foam peanuts.","C":"Adding toxic heavy-metal inks to disposable plastic bags.","D":"Using minimal, lightweight, compostable, or 100% post-consumer recycled packaging that can be easily reused or recycled."},"correctOption":"D","correctAnswer":"Using minimal, lightweight, compostable, or 100% post-consumer recycled packaging that can be easily reused or recycled.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sustainable packaging reduces material weight, avoids hazardous chemicals, and supports circular recovery.","distractor_reasons":{"A":"Incorrect because multi-layer non-recyclable plastic on whole fruit creates unnecessary waste.","B":"Incorrect because oversized boxes waste transport space and foam peanuts pollute landfills.","C":"Incorrect because heavy-metal inks contaminate recycling streams and soil.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_691","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_691","question":"How do changing social attitudes toward the environment create new market opportunities for businesses?","options":{"A":"Rising demand for electric vehicles, renewable energy, plant-based foods, and zero-waste products allows innovative firms to capture fast-growing green markets.","B":"Consumers stop buying all goods and services completely.","C":"Governments ban all entrepreneurs from starting environmentally friendly businesses.","D":"Eco-conscious consumers refuse to pay for any sustainable innovations."},"correctOption":"A","correctAnswer":"Rising demand for electric vehicles, renewable energy, plant-based foods, and zero-waste products allows innovative firms to capture fast-growing green markets.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because environmental awareness acts as an external catalyst for product innovation and premium brand positioning.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumers shift spending toward sustainable alternatives rather than stopping consumption.","C":"Incorrect because governments actively support green entrepreneurship.","D":"Incorrect because growing consumer segments actively seek out and pay for sustainable goods."}}},{"id":"P1_U6_MCQ_692","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_692","question":"Why do institutional investors and banks increasingly assess a business's environmental risks before lending money or buying shares?","options":{"A":"Because heavily polluting firms face higher profits and zero legal risks.","B":"Because polluting businesses face severe risks of government fines, carbon taxes, stranded fossil-fuel assets, and consumer boycotts that threaten loan repayment and share value.","C":"Because banks are legally forbidden from lending to environmentally sustainable businesses.","D":"Because environmental risks never affect a company's financial performance."},"correctOption":"B","correctAnswer":"Because polluting businesses face severe risks of government fines, carbon taxes, stranded fossil-fuel assets, and consumer boycotts that threaten loan repayment and share value.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because environmental liabilities directly translate into financial and credit risks for lenders and shareholders.","distractor_reasons":{"A":"Incorrect because heavy polluters face escalating regulatory and reputational risks.","B":"Correct selection.","C":"Incorrect because banks increasingly offer preferential 'green loans' to sustainable businesses.","D":"Incorrect because fines, cleanup costs, and lost sales directly damage financial results."}}},{"id":"P1_U6_MCQ_693","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_693","question":"What is meant by 'carbon offsetting' by a business?","options":{"A":"Doubling factory greenhouse gas emissions without taking any action.","B":"Hiding carbon emission figures from government regulators.","C":"Compensating for unavoidable carbon emissions by funding verified external projects—such as reforestation or renewable energy—that absorb or prevent an equivalent amount of CO2.","D":"Replacing all renewable energy sources with coal power."},"correctOption":"C","correctAnswer":"Compensating for unavoidable carbon emissions by funding verified external projects—such as reforestation or renewable energy—that absorb or prevent an equivalent amount of CO2.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because carbon offsetting balances residual emissions through verified external carbon-reduction projects, ideally alongside direct emission cuts.","distractor_reasons":{"A":"Incorrect because offsetting seeks to net out emissions rather than double them.","B":"Incorrect because credible offsetting requires transparent carbon accounting.","C":"Correct selection.","D":"Incorrect because offsetting supports clean energy rather than coal."}}},{"id":"P1_U6_MCQ_694","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_694","question":"What is 'land pollution' caused by industrial and commercial activity?","options":{"A":"Excessive noise from late-night airport flights.","B":"Smoke plumes rising from diesel lorry exhaust pipes.","C":"Untreated sewage flowing into coastal bathing waters.","D":"Contamination and degradation of soil and land surfaces through toxic chemical spills, hazardous waste dumping, mining tailings, and non-biodegradable landfill waste."},"correctOption":"D","correctAnswer":"Contamination and degradation of soil and land surfaces through toxic chemical spills, hazardous waste dumping, mining tailings, and non-biodegradable landfill waste.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because land pollution poisons soil ecosystems, harms agriculture, and can leach toxins into groundwater.","distractor_reasons":{"A":"Incorrect because aircraft sound is *noise* pollution.","B":"Incorrect because exhaust smoke is *air* pollution.","C":"Incorrect because coastal sewage is *water* pollution.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_695","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_695","question":"How does adopting 'lean production' techniques help protect the environment?","options":{"A":"By minimising wasted raw materials, defective products, excess energy use, and unnecessary transport across manufacturing operations.","B":"By producing huge stockpiles of defective goods that are thrown into landfills.","C":"By using the maximum possible amount of packaging for every item.","D":"By keeping factory machines running idle twenty-four hours a day."},"correctOption":"A","correctAnswer":"By minimising wasted raw materials, defective products, excess energy use, and unnecessary transport across manufacturing operations.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lean production focuses on eliminating all forms of waste ('muda'), aligning cost efficiency with resource conservation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lean production aims for zero defects and minimal inventory.","C":"Incorrect because lean operations eliminate excess packaging.","D":"Incorrect because idle running wastes electricity and fuel."}}},{"id":"P1_U6_MCQ_696","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_696","question":"Why might a government combine environmental regulations with green taxes rather than relying on only one policy tool?","options":{"A":"Because regulations never apply to manufacturing businesses.","B":"Because regulations set strict maximum safety ceilings for dangerous toxins, while green taxes provide ongoing financial incentives to keep cutting emissions below legal limits.","C":"Because green taxes eliminate the need for any environmental laws.","D":"Because combining policies guarantees that businesses pay zero taxes."},"correctOption":"B","correctAnswer":"Because regulations set strict maximum safety ceilings for dangerous toxins, while green taxes provide ongoing financial incentives to keep cutting emissions below legal limits.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because regulations prevent catastrophic harm while market-based green taxes reward continuous innovation and efficiency.","distractor_reasons":{"A":"Incorrect because industrial manufacturers are heavily regulated.","B":"Correct selection.","C":"Incorrect because toxic hazards still require outright legal bans or caps.","D":"Incorrect because green taxes raise revenue from remaining pollution."}}},{"id":"P1_U6_MCQ_697","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_697","question":"What is 'electronic waste' (e-waste) and why is it a growing environmental concern for technology businesses?","options":{"A":"Spam emails sent to office computers that consume paper.","B":"Biodegradable cardboard boxes used to ship laptops.","C":"Discarded smartphones, computers, and appliances containing toxic heavy metals (like lead and mercury) alongside valuable rare-earth minerals that are lost if not recycled.","D":"Electricity generated by offshore wind turbines."},"correctOption":"C","correctAnswer":"Discarded smartphones, computers, and appliances containing toxic heavy metals (like lead and mercury) alongside valuable rare-earth minerals that are lost if not recycled.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because rapid device replacement generates hazardous e-waste unless manufacturers design for durability and take-back recycling.","distractor_reasons":{"A":"Incorrect because e-waste refers to discarded physical electrical and electronic hardware.","B":"Incorrect because cardboard boxes are paper packaging waste, not electronic hardware.","C":"Correct selection.","D":"Incorrect because wind electricity is clean renewable energy."}}},{"id":"P1_U6_MCQ_698","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_698","question":"How can environmental sustainability strengthen a business's recruitment and employee motivation?","options":{"A":"By allowing the business to pay workers below the statutory minimum wage.","B":"By eliminating all staff training and career development.","C":"By forcing employees to work unsafe overtime hours.","D":"By attracting talented applicants and boosting pride and morale among employees who want to work for a purposeful, environmentally responsible employer."},"correctOption":"D","correctAnswer":"By attracting talented applicants and boosting pride and morale among employees who want to work for a purposeful, environmentally responsible employer.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because strong environmental values enhance employer branding, improving staff retention and productivity.","distractor_reasons":{"A":"Incorrect because environmental responsibility does not waive minimum wage laws.","B":"Incorrect because sustainable firms invest in training staff on green practices.","C":"Incorrect because responsible businesses uphold safe working hours.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_699","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_699","question":"What is meant by 'net-zero carbon emissions' as a corporate environmental target?","options":{"A":"Cutting greenhouse gas emissions as close to zero as possible and balancing any remaining unavoidable emissions through verified carbon removal.","B":"Increasing carbon emissions every year while ignoring climate targets.","C":"Closing down all business operations and ceasing all production permanently.","D":"Refusing to measure or report any factory energy usage."},"correctOption":"A","correctAnswer":"Cutting greenhouse gas emissions as close to zero as possible and balancing any remaining unavoidable emissions through verified carbon removal.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because net-zero combines deep decarbonisation across operations and supply chains with verified removal of residual emissions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because net-zero requires aggressive emission reductions.","C":"Incorrect because businesses achieve net-zero through clean energy and efficiency while continuing to operate.","D":"Incorrect because net-zero requires rigorous measurement and reporting."}}},{"id":"P1_U6_MCQ_700","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_700","question":"Why do environmental externalities represent a form of 'market failure' when left unregulated?","options":{"A":"Because private businesses always pay double for all external costs voluntarily.","B":"Because profit-maximising firms consider only their internal private costs and ignore external pollution costs imposed on society, leading to overproduction of polluting goods.","C":"Because consumers never buy products that cause pollution.","D":"Because free markets automatically eliminate all pollution without any laws."},"correctOption":"B","correctAnswer":"Because profit-maximising firms consider only their internal private costs and ignore external pollution costs imposed on society, leading to overproduction of polluting goods.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when external costs are omitted from market prices, society suffers welfare losses, justifying government intervention.","distractor_reasons":{"A":"Incorrect because unregulated firms generally do not pay for external damages unless compelled by law or taxes.","B":"Correct selection.","C":"Incorrect because consumers often buy cheaper polluting goods when external costs are not reflected in prices.","D":"Incorrect because unregulated markets tend to underprice polluting activities."}}},{"id":"P1_U6_MCQ_701","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_701","question":"What are the three pillars of the 'Triple Bottom Line' framework in responsible business?","options":{"A":"Price, Promotion, and Place.","B":"Land, Labour, and Capital.","C":"People (social impact), Planet (environmental impact), and Profit (economic performance).","D":"Revenue, Cost, and Tax."},"correctOption":"C","correctAnswer":"People (social impact), Planet (environmental impact), and Profit (economic performance).","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the Triple Bottom Line measures business success across social equity, environmental stewardship, and financial viability.","distractor_reasons":{"A":"Incorrect because Price, Promotion, and Place are elements of the marketing mix.","B":"Incorrect because Land, Labour, and Capital are factors of production.","C":"Correct selection.","D":"Incorrect because Revenue, Cost, and Tax are purely financial accounting terms."}}},{"id":"P1_U6_MCQ_702","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_702","question":"What is an 'ethical dilemma' for a business manager?","options":{"A":"Choosing between two equally ethical and profitable suppliers.","B":"Calculating the exact amount of Value Added Tax owed on monthly sales.","C":"Selecting the colour of stationery used in the head office.","D":"A difficult situation where choosing the morally right course of action conflicts with maximising short-term profit or cutting costs."},"correctOption":"D","correctAnswer":"A difficult situation where choosing the morally right course of action conflicts with maximising short-term profit or cutting costs.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ethical dilemmas arise when moral obligations (such as fair wages or product recalls) involve short-term financial sacrifices.","distractor_reasons":{"A":"Incorrect because choosing between two good options involves no moral conflict.","B":"Incorrect because calculating tax is a routine technical accounting task.","C":"Incorrect because stationery colour is a trivial operational choice.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_703","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_703","question":"What is 'planned obsolescence' and why is it criticised on ethical and environmental grounds?","options":{"A":"Deliberately designing products to break down, wear out, or become software-incompatible prematurely so consumers are forced to buy replacements sooner.","B":"Designing durable products with replaceable parts and ten-year warranties.","C":"Offering free repairs to customers whose products break after warranty.","D":"Recycling old electronics into new components at zero cost to consumers."},"correctOption":"A","correctAnswer":"Deliberately designing products to break down, wear out, or become software-incompatible prematurely so consumers are forced to buy replacements sooner.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because artificially shortening product lifespans exploits consumers financially and generates unnecessary electronic and landfill waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because durable, repairable design is the ethical alternative to planned obsolescence.","C":"Incorrect because free repairs extend product life responsibly.","D":"Incorrect because take-back recycling supports sustainability rather than obsolescence."}}},{"id":"P1_U6_MCQ_704","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_704","question":"Why is collusion or price-fixing between rival businesses considered both unethical and illegal in most countries?","options":{"A":"Because it lowers prices to zero and gives consumers free products.","B":"Because competitors secretly agree to keep prices artificially high or divide up markets, cheating consumers and destroying fair competition.","C":"Because it encourages rivals to compete fiercely on quality and innovation.","D":"Because it reduces business profits to zero."},"correctOption":"B","correctAnswer":"Because competitors secretly agree to keep prices artificially high or divide up markets, cheating consumers and destroying fair competition.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cartels deceive buyers into believing prices are competitive while extracting unfair monopoly profits.","distractor_reasons":{"A":"Incorrect because price-fixing raises, rather than lowers, prices for consumers.","B":"Correct selection.","C":"Incorrect because collusion eliminates genuine competition.","D":"Incorrect because cartels inflate business profits at consumers' expense."}}},{"id":"P1_U6_MCQ_705","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_705","question":"What is 'forced labour' (modern slavery) in global supply chains?","options":{"A":"Employees voluntarily working paid overtime during a busy holiday week.","B":"Workers joining a trade union to negotiate higher wages.","C":"Work extracted from individuals under threat of penalty, violence, debt bondage, or confiscation of identity documents, where people cannot leave freely.","D":"Paid internships offered to university students during summer."},"correctOption":"C","correctAnswer":"Work extracted from individuals under threat of penalty, violence, debt bondage, or confiscation of identity documents, where people cannot leave freely.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because forced labour denies basic human freedom and dignity, making supply-chain due diligence an essential ethical obligation.","distractor_reasons":{"A":"Incorrect because voluntary paid overtime is consensual employment.","B":"Incorrect because trade union membership protects worker rights.","C":"Correct selection.","D":"Incorrect because paid internships are voluntary educational placements."}}},{"id":"P1_U6_MCQ_706","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_706","question":"How does 'strategic CSR' differ from simple 'corporate philanthropy'?","options":{"A":"Corporate philanthropy is illegal, whereas strategic CSR is required by criminal law.","B":"Strategic CSR ignores all social and environmental issues completely.","C":"Corporate philanthropy involves reforming core supply chains, whereas strategic CSR is only donating small coins to charity boxes.","D":"Corporate philanthropy involves ad-hoc charitable donations, whereas strategic CSR integrates ethical and sustainable practices directly into core business operations and long-term strategy."},"correctOption":"D","correctAnswer":"Corporate philanthropy involves ad-hoc charitable donations, whereas strategic CSR integrates ethical and sustainable practices directly into core business operations and long-term strategy.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because strategic CSR embeds responsibility into how a firm sources, manufactures, and treats workers rather than relying solely on separate charity cheques.","distractor_reasons":{"A":"Incorrect because both philanthropy and CSR are voluntary.","B":"Incorrect because strategic CSR places social and environmental impact at the core of strategy.","C":"Incorrect because this reverses philanthropy and strategic CSR.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_707","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_707","question":"What is meant by 'supply-chain traceability' in ethical business management?","options":{"A":"The ability to identify, track, and verify the origin, working conditions, and environmental practices at every tier of production from raw materials to finished goods.","B":"Hiding the names of overseas factories so competitors and consumers cannot inspect them.","C":"Delivering parcels to customers without providing tracking numbers.","D":"Buying raw materials from anonymous middlemen with no documentation."},"correctOption":"A","correctAnswer":"The ability to identify, track, and verify the origin, working conditions, and environmental practices at every tier of production from raw materials to finished goods.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because full traceability ensures ethical abuses cannot hide in lower-tier sub-contractors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because traceability increases openness rather than secrecy.","C":"Incorrect because parcel tracking is a logistics service, not ethical supply-chain traceability.","D":"Incorrect because undocumented sourcing prevents ethical verification."}}},{"id":"P1_U6_MCQ_708","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_708","question":"What is the ethical obligation of a business regarding workplace health and safety?","options":{"A":"Cutting safety equipment budgets to increase quarterly profit margins.","B":"Going beyond bare statutory minimums to provide safe machinery, protective gear, mental health support, and proper training so no worker is harmed.","C":"Blaming injured workers for accidents caused by poorly maintained equipment.","D":"Refusing to record workplace accidents to keep insurance premiums low."},"correctOption":"B","correctAnswer":"Going beyond bare statutory minimums to provide safe machinery, protective gear, mental health support, and proper training so no worker is harmed.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because protecting employees' physical and mental wellbeing is a fundamental moral duty of an employer.","distractor_reasons":{"A":"Incorrect because sacrificing safety for profit is deeply unethical.","B":"Correct selection.","C":"Incorrect because employers bear primary responsibility for maintaining a safe workplace.","D":"Incorrect because hiding accidents is both illegal and unethical."}}},{"id":"P1_U6_MCQ_709","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_709","question":"Why is 'insider trading' considered an unethical and illegal financial practice?","options":{"A":"Because employees buy shares in their company through an approved public share-save scheme.","B":"Because a company publishes its audited annual financial results to all investors simultaneously.","C":"Because individuals use confidential, non-public company information to buy or sell shares for unfair personal profit at the expense of ordinary investors.","D":"Because institutional pension funds invest in ethical renewable energy companies."},"correctOption":"C","correctAnswer":"Because individuals use confidential, non-public company information to buy or sell shares for unfair personal profit at the expense of ordinary investors.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because insider trading destroys market fairness and investor trust by exploiting privileged secret information.","distractor_reasons":{"A":"Incorrect because regulated employee share schemes are legal and transparent.","B":"Incorrect because simultaneous public disclosure ensures market fairness.","C":"Correct selection.","D":"Incorrect because ethical investing is legitimate portfolio management."}}},{"id":"P1_U6_MCQ_710","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_710","question":"What is meant by 'ethical leadership' ('tone from the top') in a company?","options":{"A":"Senior executives telling employees to obey ethical rules while breaking those same rules themselves.","B":"Focusing exclusively on short-term share price targets regardless of legal violations.","C":"Delegating all ethical decisions to unpaid interns.","D":"Senior leaders consistently demonstrating honesty, fairness, and integrity in their own decisions and holding everyone accountable to ethical standards."},"correctOption":"D","correctAnswer":"Senior leaders consistently demonstrating honesty, fairness, and integrity in their own decisions and holding everyone accountable to ethical standards.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because corporate culture mirrors the values modelled and rewarded by the board and senior executives.","distractor_reasons":{"A":"Incorrect because hypocrisy from leaders undermines ethical culture across the firm.","B":"Incorrect because narrow focus on short-term share prices often encourages unethical shortcuts.","C":"Incorrect because ethical governance is a core responsibility of top leadership.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_711","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_711","question":"What is a 'sustainability report' (or CSR/ESG report) published by a company?","options":{"A":"A public document disclosing the company's environmental, social, and ethical performance, targets, and impacts alongside its financial results.","B":"A confidential marketing plan outlining how to raise prices on loyal customers.","C":"A list of tax loopholes used to avoid paying corporation tax.","D":"An internal memo announcing staff redundancies."},"correctOption":"A","correctAnswer":"A public document disclosing the company's environmental, social, and ethical performance, targets, and impacts alongside its financial results.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because transparent non-financial reporting enables stakeholders and investors to verify ethical and environmental progress.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pricing strategies are confidential commercial plans.","C":"Incorrect because CSR reporting promotes accountability rather than tax avoidance.","D":"Incorrect because redundancy announcements are internal HR communications."}}},{"id":"P1_U6_MCQ_712","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_712","question":"Why do ethical businesses respect intellectual property (IP) rights such as patents, copyrights, and trademarks?","options":{"A":"Because copying competitors' patented designs reduces R&D costs.","B":"Because respecting IP rewards genuine innovation and creativity rather than stealing the ideas and brand investments of others.","C":"Because intellectual property laws allow businesses to sell counterfeit goods.","D":"Because patents and trademarks are completely free to copy worldwide."},"correctOption":"B","correctAnswer":"Because respecting IP rewards genuine innovation and creativity rather than stealing the ideas and brand investments of others.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fair competition requires respecting legal and moral ownership of inventions, creative works, and brand identities.","distractor_reasons":{"A":"Incorrect because copying protected designs is piracy/infringement, not ethical practice.","B":"Correct selection.","C":"Incorrect because IP laws *prohibit* counterfeit goods.","D":"Incorrect because registered IP is legally protected against unauthorised copying."}}},{"id":"P1_U6_MCQ_713","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_713","question":"How can unethical behaviour by a business negatively affect its ability to recruit and retain skilled employees?","options":{"A":"Talented workers are eager to join companies famous for worker exploitation.","B":"Unethical scandals increase employee pride and job satisfaction.","C":"High-calibre applicants avoid employers with poor ethical reputations, and existing staff may resign due to low morale and embarrassment.","D":"Unethical companies never need to hire skilled workers."},"correctOption":"C","correctAnswer":"High-calibre applicants avoid employers with poor ethical reputations, and existing staff may resign due to low morale and embarrassment.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because reputational damage harms employer branding, increasing recruitment costs and labour turnover.","distractor_reasons":{"A":"Incorrect because skilled candidates prefer reputable, fair employers.","B":"Incorrect because scandals damage employee morale rather than improving it.","C":"Correct selection.","D":"Incorrect because modern businesses depend heavily on skilled talent."}}},{"id":"P1_U6_MCQ_714","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_714","question":"What is 'drip pricing' and why is it considered an unethical sales practice?","options":{"A":"Offering transparent all-inclusive prices upfront with zero hidden charges.","B":"Gradually lowering prices during a seasonal clearance sale.","C":"Charging different prices based on verified bulk order volumes.","D":"Advertising an artificially low headline price and adding unavoidable mandatory fees step-by-step during checkout to mislead buyers."},"correctOption":"D","correctAnswer":"Advertising an artificially low headline price and adding unavoidable mandatory fees step-by-step during checkout to mislead buyers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because drip pricing deceives shoppers and prevents fair price comparison across competitors.","distractor_reasons":{"A":"Incorrect because transparent upfront pricing is ethical.","B":"Incorrect because seasonal clearance markdowns are honest promotional pricing.","C":"Incorrect because published bulk discounts are standard B2B pricing.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_715","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_715","question":"What is an ethical 'product recall' obligation?","options":{"A":"Promptly withdrawing a defective or unsafe product from sale, alerting consumers, and offering full refunds or repairs even when doing so reduces short-term profits.","B":"Continuing to sell faulty products quietly until existing warehouse stock runs out.","C":"Blaming customers for injuries caused by a manufacturing defect.","D":"Changing the product's packaging colour without fixing the safety fault."},"correctOption":"A","correctAnswer":"Promptly withdrawing a defective or unsafe product from sale, alerting consumers, and offering full refunds or repairs even when doing so reduces short-term profits.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer safety takes absolute priority over short-term inventory revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because knowingly selling unsafe goods is reckless and unethical.","C":"Incorrect because manufacturers are morally and legally accountable for product defects.","D":"Incorrect because cosmetic relabelling fails to protect consumers."}}},{"id":"P1_U6_MCQ_716","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_716","question":"How can a business support its local community ethically beyond simply obeying the law?","options":{"A":"By blocking public roads with delivery lorries every day.","B":"By creating local apprenticeships, sourcing from local small businesses, supporting community facilities, and minimising local noise and traffic disruption.","C":"By sending all profits offshore while ignoring local pollution complaints.","D":"By refusing to hire any workers living within ten miles of its factory."},"correctOption":"B","correctAnswer":"By creating local apprenticeships, sourcing from local small businesses, supporting community facilities, and minimising local noise and traffic disruption.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because constructive community engagement builds a 'social licence to operate' and shared local prosperity.","distractor_reasons":{"A":"Incorrect because causing traffic disruption harms local residents.","B":"Correct selection.","C":"Incorrect because ignoring community externalities damages local trust.","D":"Incorrect because excluding local residents denies employment opportunities to the host community."}}},{"id":"P1_U6_MCQ_717","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_717","question":"Why do multinational businesses often apply a 'zero-tolerance policy' toward bribery and facilitation payments?","options":{"A":"Because paying small bribes is an efficient way to win government contracts.","B":"Because bribery laws apply only inside a company's home country and never abroad.","C":"Because bribery corrupts fair markets, exposes the company and executives to international criminal prosecution, and destroys corporate integrity.","D":"Because zero-tolerance policies allow managers to accept expensive gifts from suppliers."},"correctOption":"C","correctAnswer":"Because bribery corrupts fair markets, exposes the company and executives to international criminal prosecution, and destroys corporate integrity.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because anti-corruption laws (such as the UK Bribery Act and US FCPA) punish overseas bribery severely, making strict zero tolerance vital.","distractor_reasons":{"A":"Incorrect because paying bribes is illegal and corrupt.","B":"Incorrect because major anti-bribery statutes have extraterritorial reach.","C":"Correct selection.","D":"Incorrect because zero-tolerance policies strictly ban accepting improper gifts."}}},{"id":"P1_U6_MCQ_718","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_718","question":"How does 'fair competition' benefit consumers and the economy from an ethical perspective?","options":{"A":"By allowing a single monopoly to overcharge all customers.","B":"By encouraging firms to use fake online reviews to smear rivals.","C":"By eliminating product innovation and consumer choice.","D":"By motivating businesses to win customers honestly through better quality, lower prices, and genuine innovation rather than deception or market abuse."},"correctOption":"D","correctAnswer":"By motivating businesses to win customers honestly through better quality, lower prices, and genuine innovation rather than deception or market abuse.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ethical competition channels business rivalry into creating genuine value for consumers.","distractor_reasons":{"A":"Incorrect because monopoly overcharging harms consumers.","B":"Incorrect because fake reviews are deceptive and unethical.","C":"Incorrect because fair competition *stimulates* innovation and choice.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_719","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_719","question":"Why is posting fake positive customer reviews or paying influencers to hide sponsorships considered unethical marketing?","options":{"A":"Because it deceives consumers by disguising paid promotion as independent, genuine customer opinion.","B":"Because genuine customer reviews are illegal on e-commerce websites.","C":"Because influencers are never allowed to promote legal products.","D":"Because honest advertising reduces consumer trust."},"correctOption":"A","correctAnswer":"Because it deceives consumers by disguising paid promotion as independent, genuine customer opinion.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because transparency requires paid endorsements to be clearly disclosed so buyers are not misled.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because authentic, unmanipulated customer reviews are completely legal and helpful.","C":"Incorrect because influencers can promote products ethically when paid partnerships are clearly labelled.","D":"Incorrect because honest advertising *builds* consumer trust."}}},{"id":"P1_U6_MCQ_720","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_720","question":"What is the purpose of providing regular 'ethics training' to employees?","options":{"A":"To teach staff how to hide accounting errors from auditors.","B":"To help staff recognise ethical dilemmas, understand the company's code of conduct, and know how to report misconduct safely.","C":"To replace all technical job skills training.","D":"To encourage employees to accept bribes from overseas clients."},"correctOption":"B","correctAnswer":"To help staff recognise ethical dilemmas, understand the company's code of conduct, and know how to report misconduct safely.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because written codes only work when employees are trained to apply ethical principles in real workplace situations.","distractor_reasons":{"A":"Incorrect because ethics training promotes honesty and audit transparency.","B":"Correct selection.","C":"Incorrect because ethics training complements technical job training.","D":"Incorrect because ethics training reinforces anti-bribery compliance."}}},{"id":"P1_U6_MCQ_721","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_721","question":"How do non-governmental organisations (NGOs) and certification bodies (such as Fairtrade or Rainforest Alliance) help ethical businesses?","options":{"A":"By setting the central bank's base interest rate.","B":"By paying 100% of the business's employee wages.","C":"By providing independent standards, audits, and trusted certification marks that prove a business's ethical claims to consumers.","D":"By exempting certified companies from paying corporation tax."},"correctOption":"C","correctAnswer":"By providing independent standards, audits, and trusted certification marks that prove a business's ethical claims to consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because independent third-party verification overcomes consumer scepticism toward corporate self-claims.","distractor_reasons":{"A":"Incorrect because central banks set monetary interest rates.","B":"Incorrect because businesses pay their own payroll expenses.","C":"Correct selection.","D":"Incorrect because ethical certification does not waive corporate taxes."}}},{"id":"P1_U6_MCQ_722","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_722","question":"Why might a business's commitment to ethical sourcing lead to higher unit costs in the short term?","options":{"A":"Because ethical suppliers use slave labour to reduce wages.","B":"Because ethical sourcing eliminates all shipping and customs fees.","C":"Because ethical businesses are forced to pay double the VAT rate.","D":"Because paying fair living wages, maintaining safe factories, and funding independent supplier audits cost more than using exploitative low-cost suppliers."},"correctOption":"D","correctAnswer":"Because paying fair living wages, maintaining safe factories, and funding independent supplier audits cost more than using exploitative low-cost suppliers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because decent labour standards and environmental safeguards involve genuine operating expenses that uncertified sweatshops avoid.","distractor_reasons":{"A":"Incorrect because ethical suppliers strictly prohibit forced or slave labour.","B":"Incorrect because standard logistics and customs fees still apply.","C":"Incorrect because VAT rates are not doubled for ethical firms.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_723","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_723","question":"What is 'ethical divestment' by shareholders and pension funds?","options":{"A":"Selling shares and withdrawing investment capital from companies involved in unethical, harmful, or environmentally destructive industries.","B":"Buying controlling stakes in tobacco and weapons manufacturers.","C":"Increasing dividend payouts to company directors.","D":"Refusing to audit company financial accounts."},"correctOption":"A","correctAnswer":"Selling shares and withdrawing investment capital from companies involved in unethical, harmful, or environmentally destructive industries.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because divestment removes financial backing and signals investor disapproval, pressuring firms to reform.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because divestment involves *selling* shares in harmful sectors, not buying them.","C":"Incorrect because divestment is an investor portfolio decision, not a board dividend policy.","D":"Incorrect because ethical investors demand *stricter* auditing and transparency."}}},{"id":"P1_U6_MCQ_724","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_724","question":"What is meant by 'social auditing' in a business?","options":{"A":"Checking only whether the company paid the correct amount of corporation tax.","B":"An independent assessment and report measuring how well a business meets its social, ethical, and environmental responsibilities toward stakeholders.","C":"Counting the number of social media followers a brand has.","D":"Calculating daily cash register totals in retail stores."},"correctOption":"B","correctAnswer":"An independent assessment and report measuring how well a business meets its social, ethical, and environmental responsibilities toward stakeholders.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a social audit evaluates non-financial ethical performance across worker welfare, community impact, and sustainability.","distractor_reasons":{"A":"Incorrect because checking tax payments is a financial/tax audit.","B":"Correct selection.","C":"Incorrect because follower counts are social media marketing metrics.","D":"Incorrect because till reconciliation is routine cash accounting."}}},{"id":"P1_U6_MCQ_725","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_725","question":"Which statement best summarises the relationship between business ethics and long-term profitability?","options":{"A":"Unethical companies always survive longer and earn higher profits than ethical companies.","B":"Ethical behaviour guarantees immediate short-term profit without any extra effort or cost.","C":"While ethical decisions may raise short-term costs, they protect against scandals and fines while building lasting customer trust, staff loyalty, and sustainable long-term profit.","D":"Business ethics applies only to non-profit charities and never to commercial companies."},"correctOption":"C","correctAnswer":"While ethical decisions may raise short-term costs, they protect against scandals and fines while building lasting customer trust, staff loyalty, and sustainable long-term profit.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because balanced evaluation recognises short-term cost trade-offs alongside long-term reputational and commercial gains.","distractor_reasons":{"A":"Incorrect because unethical practices frequently lead to scandals, boycotts, fines, and collapse.","B":"Incorrect because ethical standards often require upfront investment before long-term returns materialise.","C":"Correct selection.","D":"Incorrect because business ethics is central to commercial decision-making."}}},{"id":"P1_U6_MCQ_726","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_726","question":"What is the difference between a 'sectional (interest) pressure group' and a 'promotional (cause) pressure group'?","options":{"A":"Sectional groups promote universal causes for everyone, whereas promotional groups protect only factory owners.","B":"Sectional groups are always illegal, whereas promotional groups are government departments.","C":"Promotional groups seek to win general elections, whereas sectional groups are multinational companies.","D":"Sectional groups protect the specific self-interests of their own members (such as trade unions or trade associations), whereas promotional groups campaign for wider public causes (such as environmental or animal welfare)."},"correctOption":"D","correctAnswer":"Sectional groups protect the specific self-interests of their own members (such as trade unions or trade associations), whereas promotional groups campaign for wider public causes (such as environmental or animal welfare).","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sectional groups represent defined occupational or economic groups, whereas promotional groups welcome anyone supporting a broader moral or social cause.","distractor_reasons":{"A":"Incorrect because this reverses the definitions of sectional and promotional groups.","B":"Incorrect because both types of pressure groups are legal civil-society organisations.","C":"Incorrect because neither type seeks to form the government like a political party.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_727","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_727","question":"What is the difference between an 'insider' pressure group and an 'outsider' pressure group?","options":{"A":"Insider groups are regularly consulted by government ministers and civil servants, whereas outsider groups lack close government access and rely on public protests, media stunts, and boycotts.","B":"Insider groups operate inside private factories only, whereas outsider groups operate only in foreign countries.","C":"Insider groups are illegal secret societies, whereas outsider groups are elected members of Parliament.","D":"Insider groups never try to influence policy, whereas outsider groups write all national laws."},"correctOption":"A","correctAnswer":"Insider groups are regularly consulted by government ministers and civil servants, whereas outsider groups lack close government access and rely on public protests, media stunts, and boycotts.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because insider groups work behind closed doors through expert consultation, whereas outsider groups mobilise external public pressure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 'insider' and 'outsider' refer to access to government policymakers, not factory walls.","C":"Incorrect because insider groups include respected industry bodies and major established NGOs.","D":"Incorrect because both seek to influence policy through different channels."}}},{"id":"P1_U6_MCQ_728","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_728","question":"What is a 'secondary boycott' organised by a pressure group?","options":{"A":"Refusing to buy a product only on Tuesdays.","B":"Pressuring third-party business partners—such as banks, insurers, sponsors, or retail stockists—to stop doing business with a targeted company.","C":"Buying twice as many products from an ethical company.","D":"Lobbying the central bank to lower interest rates."},"correctOption":"B","correctAnswer":"Pressuring third-party business partners—such as banks, insurers, sponsors, or retail stockists—to stop doing business with a targeted company.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because targeting commercial partners isolates a controversial firm even when consumers do not buy from it directly.","distractor_reasons":{"A":"Incorrect because a secondary boycott targets third-party commercial partners rather than specific days of the week.","B":"Correct selection.","C":"Incorrect because buying more from ethical brands is a 'buycott' or positive consumer support.","D":"Incorrect because central bank interest rates are unrelated to secondary boycotts."}}},{"id":"P1_U6_MCQ_729","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_729","question":"Why do pressure groups sometimes use high-visibility 'media stunts' or creative public demonstrations?","options":{"A":"To hide their campaign message from television and newspaper journalists.","B":"To increase sales revenue for the targeted polluting company.","C":"To capture dramatic news headlines and viral social media attention without spending millions on paid advertising.","D":"To comply with government tax auditing rules."},"correctOption":"C","correctAnswer":"To capture dramatic news headlines and viral social media attention without spending millions on paid advertising.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because eye-catching peaceful stunts generate free earned media coverage that amplifies public awareness rapidly.","distractor_reasons":{"A":"Incorrect because media stunts are specifically designed to attract journalists.","B":"Incorrect because stunts aim to embarrass or pressure the targeted firm into changing.","C":"Correct selection.","D":"Incorrect because media campaigning is unrelated to tax audits."}}},{"id":"P1_U6_MCQ_730","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_730","question":"How can a pressure group use legal action (such as judicial review or environmental lawsuits) to influence business projects?","options":{"A":"By arresting company directors personally without a judge.","B":"By passing new criminal laws inside the pressure group's office.","C":"By setting the central bank's base interest rate.","D":"By challenging planning permissions or environmental permits in court, causing costly project delays or forcing stricter compliance."},"correctOption":"D","correctAnswer":"By challenging planning permissions or environmental permits in court, causing costly project delays or forcing stricter compliance.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because court challenges can halt construction, increase legal expenses, and compel stricter environmental safeguards.","distractor_reasons":{"A":"Incorrect because private groups have no police arrest powers.","B":"Incorrect because only legislatures pass laws.","C":"Incorrect because monetary policy belongs to the central bank.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_731","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_731","question":"Why do governments often listen to and consult well-established pressure groups when drafting business regulations?","options":{"A":"Because pressure groups represent large numbers of voters and often possess specialist scientific, consumer, or industry expertise.","B":"Because pressure groups have the constitutional power to dismiss the prime minister.","C":"Because pressure groups pay all government civil servants' salaries.","D":"Because governments are legally forbidden from consulting businesses."},"correctOption":"A","correctAnswer":"Because pressure groups represent large numbers of voters and often possess specialist scientific, consumer, or industry expertise.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because politicians value voter support and technical data provided by credible advocacy and trade organisations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because voters and parliaments—not pressure groups—hold constitutional authority over governments.","C":"Incorrect because civil servants are paid out of public tax revenue.","D":"Incorrect because governments consult both business associations and civic pressure groups."}}},{"id":"P1_U6_MCQ_732","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_732","question":"Which factor can limit the influence of a pressure group on a business?","options":{"A":"Strong backing from millions of consumers and major national newspapers.","B":"Limited financial resources, low public awareness, or well-funded counter-lobbying by powerful business trade associations.","C":"Clear scientific evidence proving the business is breaking environmental laws.","D":"Availability of cheap ethical alternatives for consumers."},"correctOption":"B","correctAnswer":"Limited financial resources, low public awareness, or well-funded counter-lobbying by powerful business trade associations.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because underfunded groups struggle to sustain campaigns against wealthy corporate lobbying and public indifference.","distractor_reasons":{"A":"Incorrect because mass consumer and media support *increases* pressure group power.","B":"Correct selection.","C":"Incorrect because strong evidence of illegality strengthens the pressure group's leverage.","D":"Incorrect because cheap substitutes make consumer boycotts far easier to sustain."}}},{"id":"P1_U6_MCQ_733","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_733","question":"Why does resorting to violent or unlawful property damage often backfire on a pressure group?","options":{"A":"Because unlawful violence guarantees immediate government tax cuts for the pressure group.","B":"Because consumers always reward violent protesters by joining their cause.","C":"Because illegal violence alienates moderate public sympathy, leads to arrests and fines, and shifts media focus onto criminal behaviour rather than the ethical issue.","D":"Because peaceful protests are illegal in democratic countries."},"correctOption":"C","correctAnswer":"Because illegal violence alienates moderate public sympathy, leads to arrests and fines, and shifts media focus onto criminal behaviour rather than the ethical issue.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because peaceful, lawful campaigning maintains moral legitimacy, whereas violence destroys public support.","distractor_reasons":{"A":"Incorrect because unlawful acts result in criminal prosecution, not tax cuts.","B":"Incorrect because mainstream consumers generally reject violence and vandalism.","C":"Correct selection.","D":"Incorrect because peaceful protest is a protected democratic right."}}},{"id":"P1_U6_MCQ_734","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_734","question":"How can a trade union act similarly to a pressure group in relation to business decisions?","options":{"A":"By setting retail prices in supermarkets.","B":"By auditing company corporation tax returns.","C":"By banning all consumers from buying imported goods.","D":"By representing workers collectively to press employers for fair wages, safe working conditions, and job security, and lobbying governments on labour laws."},"correctOption":"D","correctAnswer":"By representing workers collectively to press employers for fair wages, safe working conditions, and job security, and lobbying governments on labour laws.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade unions are sectional employee interest groups that exert collective pressure on both employers and lawmakers.","distractor_reasons":{"A":"Incorrect because retail management sets shop prices.","B":"Incorrect because external accountants and tax authorities audit tax returns.","C":"Incorrect because trade unions represent employees rather than enforcing import bans.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_735","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_735","question":"What is 'industry self-regulation' and why do businesses sometimes adopt it in response to pressure groups?","options":{"A":"Businesses in an industry voluntarily agreeing to enforce common ethical or environmental standards to satisfy public concerns and pre-empt stricter government laws.","B":"Businesses refusing to obey any national laws passed by Parliament.","C":"Governments nationalising every private company in the industry.","D":"Pressure groups taking over the daily management of private factories."},"correctOption":"A","correctAnswer":"Businesses in an industry voluntarily agreeing to enforce common ethical or environmental standards to satisfy public concerns and pre-empt stricter government laws.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because voluntary industry codes allow firms greater flexibility than rigid statutory legislation while defusing campaign pressure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because self-regulation operates *above* mandatory statutory laws.","C":"Incorrect because self-regulation keeps businesses in private hands.","D":"Incorrect because industry associations, not external activists, manage self-regulatory codes."}}},{"id":"P1_U6_MCQ_736","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_736","question":"Why might price-sensitive consumers during an economic recession ignore a pressure group's call to boycott a low-cost retailer?","options":{"A":"Because consumers never care about prices during a recession.","B":"Because falling household incomes force shoppers to prioritise low prices and affordability over ethical or environmental preferences.","C":"Because low-cost retailers are legally exempt from consumer boycotts.","D":"Because pressure groups stop campaigning during recessions."},"correctOption":"B","correctAnswer":"Because falling household incomes force shoppers to prioritise low prices and affordability over ethical or environmental preferences.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because economic constraints limit consumers' willingness or ability to switch to more expensive ethical alternatives.","distractor_reasons":{"A":"Incorrect because shoppers become *more* price-sensitive during recessions.","B":"Correct selection.","C":"Incorrect because any retailer can be targeted by a boycott.","D":"Incorrect because pressure groups continue campaigning regardless of economic cycles."}}},{"id":"P1_U6_MCQ_737","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_737","question":"How can pressure group campaigns influence a business's product design and R&D priorities?","options":{"A":"By forcing businesses to stop all product innovation.","B":"By requiring products to use more toxic and non-recyclable materials.","C":"By pushing businesses to invest in safer ingredients, lower-sugar recipes, recyclable packaging, or energy-efficient features to retain market appeal.","D":"By eliminating all quality testing before product launch."},"correctOption":"C","correctAnswer":"By pushing businesses to invest in safer ingredients, lower-sugar recipes, recyclable packaging, or energy-efficient features to retain market appeal.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sustained external advocacy shifts consumer expectations and compels firms to reformulate and redesign products.","distractor_reasons":{"A":"Incorrect because pressure groups stimulate green and ethical product innovation.","B":"Incorrect because pressure groups campaign *against* toxic and non-recyclable materials.","C":"Correct selection.","D":"Incorrect because consumer groups demand *more rigorous* safety testing."}}},{"id":"P1_U6_MCQ_738","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_738","question":"Why is 'greenwashing' a particularly dangerous response when a business is challenged by an environmental pressure group?","options":{"A":"Because environmental pressure groups never investigate corporate advertising claims.","B":"Because greenwashing lowers production costs to zero.","C":"Because advertising regulators reward exaggerated environmental claims.","D":"Because pressure groups and regulators quickly expose false claims, turning a manageable issue into a major scandal over corporate dishonesty."},"correctOption":"D","correctAnswer":"Because pressure groups and regulators quickly expose false claims, turning a manageable issue into a major scandal over corporate dishonesty.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because investigative NGOs scrutinise corporate claims closely, and proven deception inflicts lasting brand damage and advertising bans.","distractor_reasons":{"A":"Incorrect because watchdog groups actively fact-check corporate sustainability claims.","B":"Incorrect because greenwashing still incurs marketing expenses without solving operational risks.","C":"Incorrect because advertising authorities ban misleading green adverts and fine offenders.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_739","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_739","question":"How can partnering with a respected NGO or pressure group benefit a business?","options":{"A":"It provides credible technical advice on improving sustainability, enhances brand trust, and turns potential critics into constructive allies.","B":"It legally exempts the business from paying all taxes and wages.","C":"It guarantees that competitors will exit the market immediately.","D":"It allows the business to hide unsafe working conditions."},"correctOption":"A","correctAnswer":"It provides credible technical advice on improving sustainability, enhances brand trust, and turns potential critics into constructive allies.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because collaborative partnerships leverage NGO expertise and lend third-party credibility to corporate reforms.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because NGO partnerships do not waive statutory taxes or payroll obligations.","C":"Incorrect because rivals remain active in the market.","D":"Incorrect because credible NGOs require transparency and genuine improvements."}}},{"id":"P1_U6_MCQ_740","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_740","question":"Why do pressure groups often use celebrity endorsements or prominent public figures in their campaigns?","options":{"A":"Because celebrities have legal power to pass environmental laws.","B":"Because celebrity involvement attracts mainstream media attention and reaches broad audiences who might not normally follow policy debates.","C":"Because celebrities pay all of the pressure group's operating costs.","D":"Because businesses are legally required to obey any demand made by a celebrity."},"correctOption":"B","correctAnswer":"Because celebrity involvement attracts mainstream media attention and reaches broad audiences who might not normally follow policy debates.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high-profile supporters amplify campaign visibility and cultural momentum across mass media.","distractor_reasons":{"A":"Incorrect because celebrities have no legislative authority.","B":"Correct selection.","C":"Incorrect because pressure groups rely on broad membership funding and grants.","D":"Incorrect because celebrity backing creates reputational pressure, not legal compulsion."}}},{"id":"P1_U6_MCQ_741","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_741","question":"What is a 'buycott' (positive consumer campaigning) organised by ethical pressure groups?","options":{"A":"Refusing to buy any products from any business in the economy.","B":"Stealing products from unethical supermarkets.","C":"Encouraging consumers to actively seek out and purchase products from ethical, Fairtrade, or environmentally certified businesses to reward responsible behaviour.","D":"Lobbying governments to ban all retail shops."},"correctOption":"C","correctAnswer":"Encouraging consumers to actively seek out and purchase products from ethical, Fairtrade, or environmentally certified businesses to reward responsible behaviour.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because 'buycotts' reward ethical leaders with higher sales and market share, motivating rivals to adopt similar standards.","distractor_reasons":{"A":"Incorrect because refusing to buy is a *boycott*.","B":"Incorrect because theft is illegal and rejected by legitimate pressure groups.","C":"Correct selection.","D":"Incorrect because buycotts promote ethical shopping rather than banning retail."}}},{"id":"P1_U6_MCQ_742","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_742","question":"How can pressure group scrutiny affect a business's supplier selection decisions?","options":{"A":"By encouraging businesses to choose suppliers with the worst safety records.","B":"By eliminating all supplier contracts completely.","C":"By forcing businesses to buy only from unverified anonymous traders.","D":"By compelling businesses to terminate contracts with abusive or polluting suppliers and switch to audited, ethical suppliers."},"correctOption":"D","correctAnswer":"By compelling businesses to terminate contracts with abusive or polluting suppliers and switch to audited, ethical suppliers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because brands face reputational damage for supplier misconduct, driving stricter ethical procurement criteria.","distractor_reasons":{"A":"Incorrect because pressure groups expose and oppose unsafe suppliers.","B":"Incorrect because businesses still need suppliers, but require ethical compliance.","C":"Incorrect because pressure groups demand *transparent, verified* supply chains.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_743","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_743","question":"What is a 'single-issue pressure group'?","options":{"A":"An organisation formed to campaign intensively on one specific cause or local decision—such as stopping a proposed airport runway or banning single-use plastic bags.","B":"A political party contesting every seat in a national parliament.","C":"A multinational conglomerate operating across fifty different industries.","D":"A government ministry responsible for national defence, health, and education."},"correctOption":"A","correctAnswer":"An organisation formed to campaign intensively on one specific cause or local decision—such as stopping a proposed airport runway or banning single-use plastic bags.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because single-issue groups concentrate all their energy and publicity on one clearly defined objective.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because political parties develop policies across all areas of national governance.","C":"Incorrect because diversified businesses are commercial conglomerates, not advocacy groups.","D":"Incorrect because government ministries administer broad public policy."}}},{"id":"P1_U6_MCQ_744","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_744","question":"Why can ignoring a growing pressure group campaign be risky for business managers?","options":{"A":"Because pressure group campaigns always disappear automatically after one day.","B":"Because unchecked criticism can snowball across social media, trigger a wider consumer boycott, attract regulatory investigation, and cause lasting brand damage.","C":"Because ignoring protests automatically lowers the business's corporation tax bill.","D":"Because pressure groups have the legal right to confiscate company factories."},"correctOption":"B","correctAnswer":"Because unchecked criticism can snowball across social media, trigger a wider consumer boycott, attract regulatory investigation, and cause lasting brand damage.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because early engagement allows managers to resolve issues before reputational and regulatory costs escalate.","distractor_reasons":{"A":"Incorrect because persistent campaigns often intensify when met with silence or arrogance.","B":"Correct selection.","C":"Incorrect because ignoring public criticism has no tax benefit.","D":"Incorrect because pressure groups cannot confiscate private property."}}},{"id":"P1_U6_MCQ_745","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_745","question":"How do consumer watchdog pressure groups empower individual shoppers?","options":{"A":"By hiding product defect reports from the public.","B":"By advising shoppers to pay higher prices without checking quality.","C":"By publishing independent product comparisons, exposing hidden contract traps, and helping consumers claim refunds or legal redress.","D":"By banning consumers from complaining about faulty goods."},"correctOption":"C","correctAnswer":"By publishing independent product comparisons, exposing hidden contract traps, and helping consumers claim refunds or legal redress.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consumer watchdogs reduce information asymmetry between large corporations and individual buyers.","distractor_reasons":{"A":"Incorrect because watchdogs *publish* defect findings widely.","B":"Incorrect because they help shoppers find fair value and safe products.","C":"Correct selection.","D":"Incorrect because watchdogs actively champion consumers' right to redress."}}},{"id":"P1_U6_MCQ_746","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_746","question":"Why do pressure groups sometimes target a company's Annual General Meeting (AGM)?","options":{"A":"Because AGMs are secret meetings where no shareholders are allowed.","B":"Because attending an AGM gives pressure groups legal ownership of the company's bank accounts.","C":"Because AGMs are where central banks set national interest rates.","D":"Because asking pointed questions and proposing ethical resolutions at an AGM attracts financial journalists and puts board directors directly on the spot."},"correctOption":"D","correctAnswer":"Because asking pointed questions and proposing ethical resolutions at an AGM attracts financial journalists and puts board directors directly on the spot.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the AGM is a high-profile public governance event covered by business media and institutional investors.","distractor_reasons":{"A":"Incorrect because AGMs are open to all shareholders.","B":"Incorrect because owning a small number of shares grants voting/questioning rights, not control over company bank accounts.","C":"Incorrect because AGMs are corporate governance meetings, not central bank policy meetings.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_747","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_747","question":"How does 'counter-lobbying' by business associations affect the outcome of pressure group campaigns?","options":{"A":"Industry associations present opposing economic arguments—such as warning of job losses or higher consumer prices—to persuade governments not to impose strict regulations.","B":"Business associations help environmental groups shut down their own member factories.","C":"Counter-lobbying makes it illegal for pressure groups to speak to journalists.","D":"Counter-lobbying automatically eliminates all pollution from factories."},"correctOption":"A","correctAnswer":"Industry associations present opposing economic arguments—such as warning of job losses or higher consumer prices—to persuade governments not to impose strict regulations.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because policymakers weigh competing arguments from civic pressure groups and business trade bodies before legislating.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade associations defend their members' commercial interests.","C":"Incorrect because freedom of expression allows pressure groups to engage with media.","D":"Incorrect because counter-lobbying is political persuasion, not pollution-control technology."}}},{"id":"P1_U6_MCQ_748","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_748","question":"What is 'reputational risk management' in relation to external pressure groups?","options":{"A":"Ignoring all external stakeholders until a boycott destroys sales.","B":"Proactively monitoring social, ethical, and environmental expectations, maintaining high standards, and preparing transparent communication plans to protect brand trust.","C":"Spending zero money on product safety or quality control.","D":"Changing the company's legal name every month to confuse customers."},"correctOption":"B","correctAnswer":"Proactively monitoring social, ethical, and environmental expectations, maintaining high standards, and preparing transparent communication plans to protect brand trust.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because brand reputation is a vital intangible asset that requires ongoing ethical vigilance and stakeholder engagement.","distractor_reasons":{"A":"Incorrect because ignoring stakeholders creates severe reputational risk.","B":"Correct selection.","C":"Incorrect because neglecting quality and safety invites major reputational crises.","D":"Incorrect because frequent rebranding destroys brand recognition and trust."}}},{"id":"P1_U6_MCQ_749","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_749","question":"Why are pressure groups considered an important external stakeholder influence on business decision-making?","options":{"A":"Because pressure groups own 100% of shares in all private companies.","B":"Because pressure groups manage daily factory payroll and inventory.","C":"Because they represent wider societal, environmental, and consumer interests, influencing customer demand, brand image, and government regulation.","D":"Because pressure groups set commercial bank interest rates."},"correctOption":"C","correctAnswer":"Because they represent wider societal, environmental, and consumer interests, influencing customer demand, brand image, and government regulation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because even without internal management authority, pressure groups shape the external commercial and regulatory environment in which businesses operate.","distractor_reasons":{"A":"Incorrect because private shareholders, not pressure groups, own companies.","B":"Incorrect because internal managers handle payroll and inventory.","C":"Correct selection.","D":"Incorrect because banks and central banks set interest rates."}}},{"id":"P1_U6_MCQ_750","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_750","question":"Which statement provides the most balanced evaluation of how pressure groups affect businesses?","options":{"A":"Pressure groups always bankrupt every business they criticise within one week.","B":"Pressure groups have zero influence on modern businesses or governments.","C":"Pressure groups only target small sole traders and never challenge multinational corporations.","D":"While pressure group campaigns can impose higher compliance costs and disrupt sales through boycotts, they also push businesses to innovate, reduce risks, and build stronger ethical brands."},"correctOption":"D","correctAnswer":"While pressure group campaigns can impose higher compliance costs and disrupt sales through boycotts, they also push businesses to innovate, reduce risks, and build stronger ethical brands.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a balanced evaluation weighs short-term cost and reputational threats against long-term improvements in sustainability, risk management, and brand differentiation.","distractor_reasons":{"A":"Incorrect because most targeted businesses adapt and survive rather than going bankrupt immediately.","B":"Incorrect because pressure groups have driven major changes in environmental laws, Fairtrade, and corporate behaviour.","C":"Incorrect because high-profile multinational corporations are the primary targets of major pressure groups.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_751","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_751","question":"What causes cost-push inflation in an economy?","options":{"A":"Rising business production costs—such as higher wages, energy bills, or imported raw material prices—forcing firms to raise selling prices to protect profit margins.","B":"A sudden surge in consumer confidence leading to excessive retail spending.","C":"A central bank lowering interest rates to stimulate housing demand.","D":"A sharp fall in the price of crude oil and industrial electricity."},"correctOption":"A","correctAnswer":"Rising business production costs—such as higher wages, energy bills, or imported raw material prices—forcing firms to raise selling prices to protect profit margins.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost-push inflation originates on the supply side when higher input expenses force businesses to pass costs onto consumers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because excessive consumer spending causes *demand-pull* inflation.","C":"Incorrect because lower interest rates stimulate spending, contributing to demand-pull pressure.","D":"Incorrect because falling energy prices reduce business costs and ease inflationary pressure."}}},{"id":"P1_U6_MCQ_752","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_752","question":"Which economic condition is described as 'stagflation'?","options":{"A":"Rapid economic growth combined with falling prices and zero unemployment.","B":"Stagnant or falling economic growth and rising unemployment occurring at the same time as high inflation.","C":"A mild recession accompanied by sustained deflation.","D":"Steady GDP growth with low and stable 2% annual inflation."},"correctOption":"B","correctAnswer":"Stagnant or falling economic growth and rising unemployment occurring at the same time as high inflation.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because stagflation combines economic stagnation (weak growth/high joblessness) with persistent price inflation, often triggered by severe supply shocks.","distractor_reasons":{"A":"Incorrect because rapid growth with falling prices is an economic boom with deflation, not stagflation.","B":"Correct selection.","C":"Incorrect because stagflation involves high inflation rather than falling prices.","D":"Incorrect because steady growth and low inflation represent healthy macroeconomic stability."}}},{"id":"P1_U6_MCQ_753","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_753","question":"Why do economists use 'real GDP per capita' rather than total nominal GDP to compare average living standards between countries?","options":{"A":"Because real GDP per capita ignores all service-sector output.","B":"Because real GDP per capita measures only government tax receipts.","C":"Because it adjusts for inflation and divides national output by population size, showing average real output per person.","D":"Because total nominal GDP is always lower than real GDP per capita."},"correctOption":"C","correctAnswer":"Because it adjusts for inflation and divides national output by population size, showing average real output per person.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because accounting for both price changes and population differences gives a much clearer picture of individual material living standards.","distractor_reasons":{"A":"Incorrect because GDP includes primary, secondary, and tertiary service output.","B":"Incorrect because GDP measures total economic output, not tax revenues.","C":"Correct selection.","D":"Incorrect because total nominal GDP is an aggregate national figure, whereas per capita divides by millions of residents."}}},{"id":"P1_U6_MCQ_754","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_754","question":"Which set of conditions typically occurs during the 'boom' stage of the business cycle?","options":{"A":"Falling GDP, widespread factory closures, and rising cyclical unemployment.","B":"Declining consumer confidence, falling retail prices, and rising business bankruptcies.","C":"Zero investment, high spare capacity, and falling wage rates.","D":"High consumer spending, low unemployment, skill shortages, high capacity utilisation, and rising inflationary pressures."},"correctOption":"D","correctAnswer":"High consumer spending, low unemployment, skill shortages, high capacity utilisation, and rising inflationary pressures.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an economic boom represents peak demand where factories operate near full capacity and labour markets tighten.","distractor_reasons":{"A":"Incorrect because falling GDP and factory closures characterise a recession or slump.","B":"Incorrect because declining confidence and bankruptcies occur during a downturn.","C":"Incorrect because high spare capacity occurs in a slump, whereas booms face capacity bottlenecks.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_755","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_755","question":"How does an economic recession typically affect a business selling basic, low-priced staple foods compared to a business selling luxury sports cars?","options":{"A":"Sales of basic staple foods remain relatively stable or may even rise as households trade down, whereas sales of luxury sports cars fall sharply.","B":"Luxury sports car sales double during recessions while staple food sales collapse.","C":"Both businesses experience identical percentage increases in sales revenue.","D":"Recessions affect only manufacturing companies and never touch retail or car dealers."},"correctOption":"A","correctAnswer":"Sales of basic staple foods remain relatively stable or may even rise as households trade down, whereas sales of luxury sports cars fall sharply.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because staple foods are income-inelastic necessities, whereas luxury cars are highly income-elastic discretionary purchases.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because falling disposable incomes cause consumers to postpone expensive luxury purchases.","C":"Incorrect because product sensitivity to income changes (income elasticity) varies widely across sectors.","D":"Incorrect because retail and automotive dealers are directly affected by household spending cuts."}}},{"id":"P1_U6_MCQ_756","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_756","question":"Which of the following is an example of a 'direct tax'?","options":{"A":"Value Added Tax (VAT) charged on restaurant meals.","B":"Personal income tax deducted from employees' wages and corporation tax paid on company profits.","C":"Import tariffs levied on foreign electronics at customs.","D":"Excise duty added to the retail price of petrol."},"correctOption":"B","correctAnswer":"Personal income tax deducted from employees' wages and corporation tax paid on company profits.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because direct taxes are levied straight onto the income or wealth of individuals and businesses and cannot be shifted to someone else.","distractor_reasons":{"A":"Incorrect because VAT is an *indirect* tax on spending.","B":"Correct selection.","C":"Incorrect because import tariffs are *indirect* taxes on traded goods.","D":"Incorrect because fuel excise duty is an *indirect* consumption tax."}}},{"id":"P1_U6_MCQ_757","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_757","question":"How does an increase in Value Added Tax (VAT) affect a business selling products with price-elastic demand?","options":{"A":"The business can raise prices by the full tax amount without losing any customers.","B":"VAT increases reduce the business's corporation tax rate to zero.","C":"Passing the full VAT hike onto consumers causes a large drop in sales volume, so the business may have to absorb part of the tax, squeezing profit margins.","D":"Higher VAT automatically lowers the cost of imported raw materials."},"correctOption":"C","correctAnswer":"Passing the full VAT hike onto consumers causes a large drop in sales volume, so the business may have to absorb part of the tax, squeezing profit margins.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when demand is price-elastic, higher retail prices trigger a proportionally larger fall in quantity demanded.","distractor_reasons":{"A":"Incorrect because only products with highly price-inelastic demand retain volume after full price pass-through.","B":"Incorrect because indirect VAT changes do not eliminate corporation tax.","C":"Correct selection.","D":"Incorrect because VAT has no downward effect on import input prices."}}},{"id":"P1_U6_MCQ_758","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_758","question":"Why do central bank cuts in interest rates particularly boost businesses selling furniture, cars, and residential homes?","options":{"A":"Because furniture and cars cannot be bought without government permission.","B":"Because lower interest rates make banks ban all consumer savings accounts.","C":"Because lower interest rates reduce corporate income tax on car manufacturers.","D":"Because high-value durable goods and homes are frequently purchased using mortgages, car loans, or credit, which become cheaper to repay."},"correctOption":"D","correctAnswer":"Because high-value durable goods and homes are frequently purchased using mortgages, car loans, or credit, which become cheaper to repay.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because credit-financed big-ticket items are highly sensitive to monthly loan and mortgage interest rates.","distractor_reasons":{"A":"Incorrect because consumer durable purchases do not require government permits.","B":"Incorrect because savings accounts remain open, though they offer lower interest returns.","C":"Incorrect because monetary interest rates do not alter statutory corporate tax rates.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_759","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_759","question":"How does high domestic inflation damage the international competitiveness of a country's exporting businesses?","options":{"A":"Rising domestic wages and input costs push export prices above foreign competitors' prices, reducing overseas orders unless the currency depreciates.","B":"High inflation makes exported goods cheaper in foreign supermarkets.","C":"High inflation automatically removes all foreign import tariffs.","D":"High inflation lowers domestic interest rates to zero."},"correctOption":"A","correctAnswer":"Rising domestic wages and input costs push export prices above foreign competitors' prices, reducing overseas orders unless the currency depreciates.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when domestic prices rise faster than trading partners' prices, exports lose price competitiveness.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because domestic inflation makes exports *more expensive*, not cheaper.","C":"Incorrect because domestic inflation does not alter foreign tariff schedules.","D":"Incorrect because central banks normally *raise* interest rates to fight high inflation."}}},{"id":"P1_U6_MCQ_760","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_760","question":"What happens to workers' real purchasing power if nominal wages rise by 3% while consumer price inflation is 7%?","options":{"A":"Workers' real purchasing power increases by 4%.","B":"Workers' real purchasing power falls by approximately 4% because prices are rising faster than pay.","C":"Workers' real purchasing power remains completely unchanged.","D":"Workers stop paying any personal income tax."},"correctOption":"B","correctAnswer":"Workers' real purchasing power falls by approximately 4% because prices are rising faster than pay.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because real wage growth equals nominal wage growth minus inflation (3% - 7% = -4%), reducing household spending power.","distractor_reasons":{"A":"Incorrect because real purchasing power rises only when nominal pay grows *faster* than inflation.","B":"Correct selection.","C":"Incorrect because the 4-percentage-point gap erodes what wages can buy.","D":"Incorrect because income tax still applies and can even rise via fiscal drag."}}},{"id":"P1_U6_MCQ_761","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_761","question":"How does government investment in transport infrastructure (such as high-speed railways, ports, and broadband networks) act as a supply-side policy?","options":{"A":"It raises retail sales taxes on household groceries.","B":"It restricts private businesses from trading online.","C":"It lowers business logistics and communication costs, speeds up deliveries, and increases the economy's long-term productive capacity.","D":"It forces central banks to raise interest rates permanently."},"correctOption":"C","correctAnswer":"It lowers business logistics and communication costs, speeds up deliveries, and increases the economy's long-term productive capacity.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because better infrastructure reduces bottlenecks and enhances private-sector productivity across all regions.","distractor_reasons":{"A":"Incorrect because infrastructure spending is public capital expenditure, not a grocery tax.","B":"Incorrect because broadband expansion *enables* online commerce.","C":"Correct selection.","D":"Incorrect because infrastructure upgrades improve supply capacity rather than forcing permanent rate hikes."}}},{"id":"P1_U6_MCQ_762","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_762","question":"Why does high unemployment place a double financial burden on a government's budget?","options":{"A":"Because unemployed workers pay double the normal rate of income tax.","B":"Because unemployed workers buy twice as many luxury goods.","C":"Because unemployment reduces the central bank's gold reserves.","D":"Because tax receipts from income tax and VAT fall while government spending on unemployment and welfare benefits rises."},"correctOption":"D","correctAnswer":"Because tax receipts from income tax and VAT fall while government spending on unemployment and welfare benefits rises.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because joblessness simultaneously shrinks tax inflows and expands social security outflows, widening a budget deficit.","distractor_reasons":{"A":"Incorrect because unemployed individuals earn no wages and pay no income tax.","B":"Incorrect because unemployed households cut discretionary spending sharply.","C":"Incorrect because domestic unemployment does not directly deplete central bank gold.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_763","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_763","question":"What is meant by 'spare capacity' (or an output gap) during an economic slump?","options":{"A":"Factories, offices, and workers are underutilised because total demand in the economy is well below maximum potential output.","B":"Every factory in the country is running at 100% capacity twenty-four hours a day.","C":"Businesses have zero unsold stock and long customer waiting lists.","D":"There are severe shortages of raw materials and skilled engineers."},"correctOption":"A","correctAnswer":"Factories, offices, and workers are underutilised because total demand in the economy is well below maximum potential output.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because weak aggregate demand during a slump leaves machinery idle and workers underemployed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 100% capacity operation occurs at the peak of a boom.","C":"Incorrect because long waiting lists reflect excess demand rather than spare capacity.","D":"Incorrect because input bottlenecks occur during rapid expansions, not slumps."}}},{"id":"P1_U6_MCQ_764","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_764","question":"How can cutting personal income tax rates stimulate business sales?","options":{"A":"It reduces households' take-home pay, forcing them to save more.","B":"It increases workers' disposable income, encouraging higher consumer spending on goods and services.","C":"It directly lowers commercial bank mortgage interest rates.","D":"It prevents consumers from buying any imported products."},"correctOption":"B","correctAnswer":"It increases workers' disposable income, encouraging higher consumer spending on goods and services.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because lower income tax leaves households with more net income to spend across retail, hospitality, and service businesses.","distractor_reasons":{"A":"Incorrect because tax cuts *increase*, rather than reduce, take-home pay.","B":"Correct selection.","C":"Incorrect because income tax is fiscal policy, whereas interest rates are monetary policy.","D":"Incorrect because higher disposable income often increases spending on both domestic and imported goods."}}},{"id":"P1_U6_MCQ_765","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_765","question":"Why might a sharp increase in the statutory national minimum wage create challenges for labour-intensive small businesses?","options":{"A":"Because minimum wage laws apply only to government ministries and never to private firms.","B":"Because higher wages immediately eliminate all utility and rent bills.","C":"Because payroll expenses rise significantly; if the business cannot boost productivity or raise prices, profit margins fall or staff hours may be cut.","D":"Because workers are legally forbidden from spending higher wages in local shops."},"correctOption":"C","correctAnswer":"Because payroll expenses rise significantly; if the business cannot boost productivity or raise prices, profit margins fall or staff hours may be cut.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because industries like hospitality and retail have high labour-cost ratios and face margin pressure unless productivity or demand rises.","distractor_reasons":{"A":"Incorrect because statutory minimum wages bind private-sector employers.","B":"Incorrect because rent and utility bills remain payable.","C":"Correct selection.","D":"Incorrect because workers are free to spend their earnings anywhere."}}},{"id":"P1_U6_MCQ_766","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_766","question":"What is 'hyperinflation' and how does it disrupt normal business operations?","options":{"A":"A gentle 1.5% annual rise in consumer prices that helps businesses plan budgets.","B":"A temporary 2% drop in supermarket food prices during summer.","C":"A fixed exchange rate between two neighbouring countries.","D":"Extremely rapid, out-of-control price increases (often exceeding 50% per month) that destroy currency confidence, distort pricing, and halt long-term business investment."},"correctOption":"D","correctAnswer":"Extremely rapid, out-of-control price increases (often exceeding 50% per month) that destroy currency confidence, distort pricing, and halt long-term business investment.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because hyperinflation makes financial planning impossible and forces businesses to change prices daily or resort to foreign currencies.","distractor_reasons":{"A":"Incorrect because 1.5% inflation represents ideal price stability.","B":"Incorrect because falling prices represent deflation, not hyperinflation.","C":"Incorrect because exchange rate pegs are currency policies.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_767","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_767","question":"Why do governments often experience a 'time lag' between changing interest rates and seeing the full impact on business investment and inflation?","options":{"A":"Because existing fixed-rate loans take time to expire, and businesses and households adjust spending and investment plans gradually over 12 to 24 months.","B":"Because commercial banks are legally barred from changing loan rates for ten years.","C":"Because businesses never borrow money from banks.","D":"Because interest rate changes only apply to foreign tourists."},"correctOption":"A","correctAnswer":"Because existing fixed-rate loans take time to expire, and businesses and households adjust spending and investment plans gradually over 12 to 24 months.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because monetary policy transmission works through multi-month contracts, mortgage resets, and capital budgeting cycles.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because variable-rate loans adjust quickly while fixed-rate deals roll off over time.","C":"Incorrect because bank loans and overdrafts are major sources of business finance.","D":"Incorrect because domestic households and firms are the primary borrowers and savers."}}},{"id":"P1_U6_MCQ_768","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_768","question":"How does sustained economic growth benefit businesses in an economy?","options":{"A":"It forces all businesses to cut staff and close branches.","B":"Rising household incomes expand market demand, boost sales revenues and profits, and encourage investment in new products and technology.","C":"It eliminates all competition from domestic and foreign rivals.","D":"It permanently freezes employee wages at minimum levels."},"correctOption":"B","correctAnswer":"Rising household incomes expand market demand, boost sales revenues and profits, and encourage investment in new products and technology.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because expanding national income creates a growing customer base and stronger business confidence.","distractor_reasons":{"A":"Incorrect because economic growth prompts hiring and expansion rather than closures.","B":"Correct selection.","C":"Incorrect because growing markets actually attract new entrants and competition.","D":"Incorrect because economic growth typically drives real wage growth."}}},{"id":"P1_U6_MCQ_769","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_769","question":"Why might a business delay signing long-term fixed-price supplier or customer contracts during periods of unpredictable inflation?","options":{"A":"Because fixed-price contracts are illegal in every country.","B":"Because inflation guarantees that supplier costs will fall by half every year.","C":"Because unexpected surges in input costs could lock the business into unprofitable fixed selling prices, causing heavy financial losses.","D":"Because inflation eliminates the need for business invoices."},"correctOption":"C","correctAnswer":"Because unexpected surges in input costs could lock the business into unprofitable fixed selling prices, causing heavy financial losses.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because inflation uncertainty makes forecasting future production costs hazardous, prompting firms to include index-linked clauses or shorten contract durations.","distractor_reasons":{"A":"Incorrect because fixed-price contracts are standard commercial agreements.","B":"Incorrect because inflation means rising, not falling, costs.","C":"Correct selection.","D":"Incorrect because formal invoicing remains essential regardless of inflation."}}},{"id":"P1_U6_MCQ_770","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_770","question":"Which policy combination would a government most likely use to pull an economy out of a deep recession?","options":{"A":"Raising income tax, cutting public spending, and raising interest rates.","B":"Increasing VAT to 30% and banning commercial bank lending.","C":"Raising corporation tax and imposing strict price ceilings on all exports.","D":"Cutting interest rates, lowering taxes, and increasing government capital spending on public projects."},"correctOption":"D","correctAnswer":"Cutting interest rates, lowering taxes, and increasing government capital spending on public projects.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because combining expansionary monetary policy (rate cuts) with expansionary fiscal policy (tax cuts and public spending) stimulates aggregate demand.","distractor_reasons":{"A":"Incorrect because raising taxes, cutting spending, and raising rates are *contractionary* policies used to fight inflation, not recession.","B":"Incorrect because higher VAT and lending bans would worsen a recession.","C":"Incorrect because higher business taxes discourage investment during a downturn.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_771","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_771","question":"How does a rise in interest rates affect a business that holds large cash reserves in the bank and has zero debt?","options":{"A":"It increases the interest income earned on the business's bank deposits, boosting its net finance income.","B":"It forces the business to pay huge monthly loan interest penalties.","C":"It immediately confiscates the business's cash reserves.","D":"It doubles the business's annual electricity bill."},"correctOption":"A","correctAnswer":"It increases the interest income earned on the business's bank deposits, boosting its net finance income.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash-rich, debt-free firms benefit directly from higher deposit interest rates, even if consumer demand softens slightly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a business with zero debt pays no loan interest.","C":"Incorrect because higher interest rates reward depositors rather than confiscating funds.","D":"Incorrect because interest rates do not directly double utility tariffs."}}},{"id":"P1_U6_MCQ_772","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_772","question":"What is meant by 'menu costs' of inflation for businesses?","options":{"A":"The cost of providing free lunches to factory employees.","B":"The administrative and printing costs of frequently updating price lists, catalogues, websites, and till systems when prices keep rising.","C":"The tax paid by restaurants on imported food ingredients.","D":"The fee paid to register a new company trademark."},"correctOption":"B","correctAnswer":"The administrative and printing costs of frequently updating price lists, catalogues, websites, and till systems when prices keep rising.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high inflation forces firms to devote time and money to repeatedly repricing goods and informing customers.","distractor_reasons":{"A":"Incorrect because staff meals are employee fringe benefits.","B":"Correct selection.","C":"Incorrect because import levies are customs tariffs.","D":"Incorrect because trademark fees are intellectual property registration costs."}}},{"id":"P1_U6_MCQ_773","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_773","question":"Why do governments offer research and development (R&D) tax credits or grants to businesses?","options":{"A":"To discourage companies from inventing new technologies.","B":"To raise immediate tax revenue by taxing innovation heavily.","C":"As a supply-side policy to encourage private investment in innovation, new products, and higher long-term productivity.","D":"To force businesses to rely solely on manual labour."},"correctOption":"C","correctAnswer":"As a supply-side policy to encourage private investment in innovation, new products, and higher long-term productivity.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because R&D incentives lower the after-tax cost of innovation, boosting competitiveness and long-run economic growth.","distractor_reasons":{"A":"Incorrect because R&D tax credits actively *encourage* invention.","B":"Incorrect because tax credits reduce, rather than increase, a firm's tax liability.","C":"Correct selection.","D":"Incorrect because R&D supports technological advancement."}}},{"id":"P1_U6_MCQ_774","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_774","question":"How does a government budget deficit financed by heavy state borrowing potentially affect private businesses ('crowding out')?","options":{"A":"It guarantees zero interest rates for all private startups.","B":"It eliminates all corporation tax for five years.","C":"It forces commercial banks to give away free loans.","D":"Heavy government borrowing can push up market interest rates, making it more expensive for private businesses to borrow funds for expansion."},"correctOption":"D","correctAnswer":"Heavy government borrowing can push up market interest rates, making it more expensive for private businesses to borrow funds for expansion.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because high public-sector demand for loanable funds can drive up borrowing costs for private firms.","distractor_reasons":{"A":"Incorrect because heavy borrowing tends to put upward pressure on yields and rates.","B":"Incorrect because large deficits often lead to higher future taxes rather than tax abolition.","C":"Incorrect because commercial banks charge market interest on loans.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_775","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_775","question":"Why is 'low and stable inflation' (such as around 2% per year) preferred by businesses over both high inflation and deflation?","options":{"A":"It provides predictable prices for planning investment, avoids wage-price spirals, and encourages consumers to spend steadily rather than delaying purchases.","B":"It ensures that businesses never face any competition.","C":"It guarantees that every business makes a net profit regardless of efficiency.","D":"It eliminates all exchange rate movements."},"correctOption":"A","correctAnswer":"It provides predictable prices for planning investment, avoids wage-price spirals, and encourages consumers to spend steadily rather than delaying purchases.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because modest, predictable inflation supports business confidence, real wage adjustments, and steady consumption without distorting economic decisions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because market competition persists under stable inflation.","C":"Incorrect because poorly managed businesses can still make losses even in a stable macroeconomy.","D":"Incorrect because floating currencies still move in response to trade and capital flows."}}},{"id":"P1_U6_MCQ_776","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_776","question":"If the exchange rate changes from $1 = €0.80 to $1 = €0.95, how has the US dollar moved and how does this affect a US exporter selling into Europe?","options":{"A":"The US dollar has depreciated, making US exports cheaper in Europe.","B":"The US dollar has appreciated, making US exports more expensive in euros for European buyers and potentially reducing US export sales.","C":"The euro has appreciated, making European goods more expensive in the USA.","D":"Neither currency has changed in value."},"correctOption":"B","correctAnswer":"The US dollar has appreciated, making US exports more expensive in euros for European buyers and potentially reducing US export sales.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because $1 now buys more euros (€0.95 instead of €0.80), meaning the dollar appreciated and euro prices of US goods rise.","distractor_reasons":{"A":"Incorrect because buying *more* foreign currency per dollar is an appreciation, not a depreciation.","B":"Correct selection.","C":"Incorrect because the euro weakened against the dollar, making European goods *cheaper* in the USA.","D":"Incorrect because the rate shifted from 0.80 to 0.95."}}},{"id":"P1_U6_MCQ_777","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_777","question":"How does a depreciation of a country's currency affect a domestic manufacturer that relies heavily on imported raw materials?","options":{"A":"Imported raw materials become cheaper in domestic currency, lowering production costs.","B":"Imported raw materials become completely free of charge.","C":"Imported raw materials become more expensive in domestic currency, increasing production costs and potentially causing cost-push price rises.","D":"Depreciation prevents the manufacturer from exporting any finished goods."},"correctOption":"C","correctAnswer":"Imported raw materials become more expensive in domestic currency, increasing production costs and potentially causing cost-push price rises.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a weaker domestic currency buys less foreign currency, raising the domestic-currency bill for foreign components and materials.","distractor_reasons":{"A":"Incorrect because imports become cheaper only when the domestic currency *appreciates*.","B":"Incorrect because foreign suppliers still require payment in full.","C":"Correct selection.","D":"Incorrect because depreciation actually makes *exports* more price-competitive abroad."}}},{"id":"P1_U6_MCQ_778","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_778","question":"What is the key difference in government revenue between an import tariff and an import quota?","options":{"A":"An import quota raises huge tax revenue for the government, whereas a tariff raises zero revenue.","B":"Both tariffs and quotas are paid directly to foreign exporters.","C":"Neither tariffs nor quotas restrict foreign imports in any way.","D":"An import tariff generates tax revenue for the importing country's government, whereas a standard quota restricts import volume without directly generating tax revenue."},"correctOption":"D","correctAnswer":"An import tariff generates tax revenue for the importing country's government, whereas a standard quota restricts import volume without directly generating tax revenue.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a tariff is a customs tax collected by the state, whereas a quota is a physical quantity ceiling.","distractor_reasons":{"A":"Incorrect because this reverses tariffs and quotas.","B":"Incorrect because tariffs are paid to the importing country's customs authority.","C":"Incorrect because both tools restrict imports and raise domestic market prices.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_779","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_779","question":"What is an 'infant industry' argument for temporary protectionism?","options":{"A":"Protecting newly established domestic industries from giant established foreign competitors until the local firms grow large enough to achieve economies of scale and compete independently.","B":"Imposing tariffs exclusively on baby food and children's toys.","C":"Protecting inefficient, declining industries permanently so they never need to modernise.","D":"Banning all domestic entrepreneurs from starting new businesses."},"correctOption":"A","correctAnswer":"Protecting newly established domestic industries from giant established foreign competitors until the local firms grow large enough to achieve economies of scale and compete independently.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because young domestic industries initially have higher unit costs and need breathing space to build scale and expertise.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 'infant' refers to newly emerging industries, not baby products.","C":"Incorrect because permanent protection for declining industries is the 'sunset industry' argument and breeds inefficiency.","D":"Incorrect because the policy aims to nurture new domestic enterprises."}}},{"id":"P1_U6_MCQ_780","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_780","question":"Which of the following is an example of a 'non-tariff barrier' to international trade?","options":{"A":"A 15% customs duty charged on every imported car.","B":"Complex product safety testing rules, strict technical regulations, or slow customs paperwork designed to make it harder for foreign goods to enter the market.","C":"Removing all border checks between neighbouring countries.","D":"Lowering domestic corporation tax rates for all companies."},"correctOption":"B","correctAnswer":"Complex product safety testing rules, strict technical regulations, or slow customs paperwork designed to make it harder for foreign goods to enter the market.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-tariff barriers restrict trade through regulatory, administrative, or quota hurdles rather than explicit customs taxes.","distractor_reasons":{"A":"Incorrect because a 15% customs duty is a direct *tariff*.","B":"Correct selection.","C":"Incorrect because removing border checks promotes free trade.","D":"Incorrect because domestic corporate tax cuts are general fiscal measures."}}},{"id":"P1_U6_MCQ_781","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_781","question":"What is meant by 'repatriation of profits' by a multinational company (MNC)?","options":{"A":"Reinvesting 100% of subsidiary profits into building new schools in the host country.","B":"Donating all overseas earnings to international environmental charities.","C":"Sending profits earned by an overseas subsidiary back to the MNC's home-country headquarters and shareholders, which reduces funds retained in the host economy.","D":"Paying higher wages to host-country factory workers."},"correctOption":"C","correctAnswer":"Sending profits earned by an overseas subsidiary back to the MNC's home-country headquarters and shareholders, which reduces funds retained in the host economy.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because profit repatriation represents a financial outflow from the host country's balance of payments back to the parent company.","distractor_reasons":{"A":"Incorrect because reinvesting locally keeps capital inside the host economy rather than repatriating it.","B":"Incorrect because repatriation transfers earnings back to the parent firm.","C":"Correct selection.","D":"Incorrect because wage payments stay with local workers in the host nation."}}},{"id":"P1_U6_MCQ_782","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_782","question":"Why are some multinational companies criticised for 'transfer pricing' practices?","options":{"A":"Because they charge customers double the advertised retail price at checkout tills.","B":"Because they give away all their products free to developing countries.","C":"Because they pay all their taxes voluntarily in the highest-tax country.","D":"Because they manipulate internal prices charged between subsidiaries in different countries to shift declared profits into low-tax havens, reducing tax paid in host countries."},"correctOption":"D","correctAnswer":"Because they manipulate internal prices charged between subsidiaries in different countries to shift declared profits into low-tax havens, reducing tax paid in host countries.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because artificial internal pricing between related subsidiaries erodes the corporate tax base of countries where real economic value was created.","distractor_reasons":{"A":"Incorrect because retail checkout overcharging is unrelated to intra-company transfer pricing.","B":"Incorrect because MNCs operate for commercial profit.","C":"Incorrect because abusive transfer pricing aims to *minimise* global tax bills.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_783","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_783","question":"How does 'technology and skills transfer' from multinational companies benefit a host country's economy?","options":{"A":"Local workers and domestic partner firms learn advanced manufacturing techniques, modern management systems, and digital skills, raising long-term national productivity.","B":"Foreign engineers keep all machines locked in secret rooms so no local worker ever learns how to use them.","C":"It forces domestic universities to close down science and engineering courses.","D":"It replaces all modern computers with manual typewriters."},"correctOption":"A","correctAnswer":"Local workers and domestic partner firms learn advanced manufacturing techniques, modern management systems, and digital skills, raising long-term national productivity.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because knowledge spillovers upgrade human capital and help domestic businesses become more competitive over time.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because training local staff to operate modern equipment is how technology transfer occurs.","C":"Incorrect because MNC presence typically increases demand for STEM graduates.","D":"Incorrect because MNCs introduce modern, rather than outdated, technology."}}},{"id":"P1_U6_MCQ_784","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_784","question":"Why are 'footloose' multinational companies a potential risk for a host country's government and workforce?","options":{"A":"Because footloose MNCs only manufacture shoes and footwear.","B":"Because they can rapidly close factories and relocate production to another country if local wages rise or tax holidays expire, causing sudden regional unemployment.","C":"Because they are legally required to stay in one location for 200 years.","D":"Because they never hire any local workers."},"correctOption":"B","correctAnswer":"Because they can rapidly close factories and relocate production to another country if local wages rise or tax holidays expire, causing sudden regional unemployment.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because assembly plants with low sunk relocation costs can shift quickly whenever relative costs change abroad.","distractor_reasons":{"A":"Incorrect because 'footloose' means geographically mobile, not footwear-related.","B":"Correct selection.","C":"Incorrect because footloose firms are defined by their lack of long-term locational ties.","D":"Incorrect because sudden job losses occur precisely because they employ many local workers."}}},{"id":"P1_U6_MCQ_785","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_785","question":"How does a 'single market' (such as the European Union) go further than a basic free trade area?","options":{"A":"It bans all trade between member countries.","B":"It imposes 50% tariffs on goods traded between member states.","C":"In addition to tariff-free trade in goods and services, it harmonises product standards and allows the free movement of labour and capital across member borders.","D":"It requires every business in the region to be owned by the state."},"correctOption":"C","correctAnswer":"In addition to tariff-free trade in goods and services, it harmonises product standards and allows the free movement of labour and capital across member borders.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a single market removes non-tariff regulatory barriers and integrates factor markets (workers and investment) alongside goods and services.","distractor_reasons":{"A":"Incorrect because a single market maximises internal trade.","B":"Incorrect because internal tariffs are completely abolished.","C":"Correct selection.","D":"Incorrect because single markets promote private cross-border enterprise."}}},{"id":"P1_U6_MCQ_786","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_786","question":"What is 'reshoring' (or nearshoring) in international business strategy?","options":{"A":"Moving a company's domestic factories to a distant overseas country for the first time.","B":"Building beachfront luxury hotels for international tourists.","C":"Eliminating all domestic suppliers and buying 100% from overseas.","D":"Bringing previously offshored manufacturing or services back to the home country (or a nearby region) to shorten supply chains, improve quality control, and reduce transport risks."},"correctOption":"D","correctAnswer":"Bringing previously offshored manufacturing or services back to the home country (or a nearby region) to shorten supply chains, improve quality control, and reduce transport risks.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because rising overseas wages, automation, and global shipping disruptions have prompted many firms to bring production closer to end consumers.","distractor_reasons":{"A":"Incorrect because moving production abroad is *offshoring*.","B":"Incorrect because reshoring refers to supply chain relocation, not coastal real estate.","C":"Incorrect because reshoring *increases* domestic or regional sourcing.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_787","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_787","question":"How does a strong appreciation of a country's currency affect its domestic tourism and hotel industry?","options":{"A":"It harms domestic hotels because holidays become more expensive for foreign tourists while domestic residents find foreign holidays cheaper and travel abroad instead.","B":"It doubles the number of foreign tourists visiting the country immediately.","C":"It makes domestic hotel rooms completely free for international visitors.","D":"It stops domestic citizens from ever travelling abroad."},"correctOption":"A","correctAnswer":"It harms domestic hotels because holidays become more expensive for foreign tourists while domestic residents find foreign holidays cheaper and travel abroad instead.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tourism is an invisible traded service: an appreciated currency reduces inbound tourist spending and increases outbound holiday travel.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a stronger currency makes visiting the country *dearer* for foreign visitors.","C":"Incorrect because hotel room rates still must be paid in the stronger domestic currency.","D":"Incorrect because cheaper foreign currency encourages *more* outbound travel by residents."}}},{"id":"P1_U6_MCQ_788","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_788","question":"Why might a fast-food or retail brand choose 'international franchising' rather than building wholly owned stores abroad?","options":{"A":"Because franchising gives the parent company zero brand control.","B":"Because local franchisees provide the capital investment and local market knowledge, enabling rapid global expansion with lower financial risk for the franchisor.","C":"Because franchising is the only legal way to sell food in foreign countries.","D":"Because franchisees never pay any fees or royalties to the parent brand."},"correctOption":"B","correctAnswer":"Because local franchisees provide the capital investment and local market knowledge, enabling rapid global expansion with lower financial risk for the franchisor.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because franchising leverages local entrepreneurs' capital and cultural familiarity while generating upfront fees and ongoing royalties.","distractor_reasons":{"A":"Incorrect because franchisors retain strict contractual control over menus, branding, and quality.","B":"Correct selection.","C":"Incorrect because companies can also open wholly owned outlets or joint ventures.","D":"Incorrect because franchisees pay initial franchise fees and ongoing royalty percentages."}}},{"id":"P1_U6_MCQ_789","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_789","question":"What is a 'resource-seeking' motive for a business investing in foreign operations?","options":{"A":"Opening software sales offices in wealthy capital cities.","B":"Reducing the business's total output by closing all mines.","C":"Establishing mines, oil wells, timber plantations, or agricultural estates abroad to secure reliable supplies of raw materials unavailable or scarce at home.","D":"Avoiding all international trade by operating only in one home village."},"correctOption":"C","correctAnswer":"Establishing mines, oil wells, timber plantations, or agricultural estates abroad to secure reliable supplies of raw materials unavailable or scarce at home.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extractive and agricultural MNCs must locate where natural deposits or suitable climates exist.","distractor_reasons":{"A":"Incorrect because targeting wealthy consumer cities is a *market-seeking* motive.","B":"Incorrect because resource-seeking firms expand access to raw inputs.","C":"Correct selection.","D":"Incorrect because resource-seeking FDI is inherently cross-border."}}},{"id":"P1_U6_MCQ_790","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_790","question":"How can a business's home country be negatively affected when one of its major manufacturers offshores factory production to a lower-wage nation?","options":{"A":"The home country immediately experiences a shortage of unemployed workers.","B":"Home-country consumers are forced to pay double for imported goods.","C":"The home government receives triple the amount of employee income tax.","D":"Factory closures cause structural unemployment in home-country industrial towns, reducing local spending and domestic tax revenues."},"correctOption":"D","correctAnswer":"Factory closures cause structural unemployment in home-country industrial towns, reducing local spending and domestic tax revenues.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because while offshoring boosts corporate competitiveness, it can hollow out domestic manufacturing employment and regional communities.","distractor_reasons":{"A":"Incorrect because offshoring *increases* domestic unemployment among displaced factory workers.","B":"Incorrect because lower offshore production costs typically make goods *cheaper* for home consumers.","C":"Incorrect because lost domestic factory jobs reduce employee income tax receipts.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_791","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_791","question":"What is 'political risk' for a business expanding into a foreign country?","options":{"A":"The risk that sudden government changes, civil unrest, nationalisation of foreign assets, or abrupt tax and regulatory shifts disrupt operations and threaten profits.","B":"The risk that customers prefer blue packaging over red packaging.","C":"The risk that a delivery van runs out of fuel on a local motorway.","D":"The risk that domestic interest rates stay completely constant."},"correctOption":"A","correctAnswer":"The risk that sudden government changes, civil unrest, nationalisation of foreign assets, or abrupt tax and regulatory shifts disrupt operations and threaten profits.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unstable governance or sudden policy reversals in host countries can severely damage foreign investments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because packaging colour preference is a marketing/cultural factor, not political risk.","C":"Incorrect because running out of fuel is a routine operational logistics issue.","D":"Incorrect because stable interest rates reduce, rather than create, risk."}}},{"id":"P1_U6_MCQ_792","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_792","question":"Why do some host governments impose 'local content requirements' on foreign multinational factories?","options":{"A":"To prevent local suppliers from selling anything to multinational firms.","B":"To require MNCs to source a minimum percentage of components, materials, or services from domestic businesses, stimulating local industry and jobs.","C":"To force MNCs to import 100% of their raw materials from overseas.","D":"To ban local citizens from applying for jobs at the factory."},"correctOption":"B","correctAnswer":"To require MNCs to source a minimum percentage of components, materials, or services from domestic businesses, stimulating local industry and jobs.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local content rules ensure foreign investment creates deeper supply-chain linkages within the host economy.","distractor_reasons":{"A":"Incorrect because the policy is designed to *increase* purchases from local suppliers.","B":"Correct selection.","C":"Incorrect because local content rules restrict, rather than mandate, total reliance on imports.","D":"Incorrect because governments aim to maximise local employment."}}},{"id":"P1_U6_MCQ_793","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_793","question":"How does a currency depreciation contribute to 'imported cost-push inflation' in an economy?","options":{"A":"By making imported oil, gas, food, and factory components cheaper in domestic currency.","B":"By stopping all domestic consumers from buying any goods.","C":"By raising the domestic-currency price of imported energy, food, and raw materials, which pushes up production costs and retail prices across the economy.","D":"By forcing foreign governments to pay for domestic imports."},"correctOption":"C","correctAnswer":"By raising the domestic-currency price of imported energy, food, and raw materials, which pushes up production costs and retail prices across the economy.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when a currency loses external value, every imported input costs more in local currency, feeding through into consumer inflation.","distractor_reasons":{"A":"Incorrect because depreciation makes imports *more expensive*, not cheaper.","B":"Incorrect because consumers still purchase essential food and energy at higher prices.","C":"Correct selection.","D":"Incorrect because domestic importers must pay the higher converted price themselves."}}},{"id":"P1_U6_MCQ_794","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_794","question":"What is the primary role of the World Trade Organization (WTO) in the global business environment?","options":{"A":"To set retail prices for supermarkets in every country.","B":"To lend money to private startups at zero interest.","C":"To impose high import tariffs on all developing countries.","D":"To promote free trade by negotiating lower trade barriers, enforcing international trade rules, and resolving trade disputes between member governments."},"correctOption":"D","correctAnswer":"To promote free trade by negotiating lower trade barriers, enforcing international trade rules, and resolving trade disputes between member governments.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the WTO provides a rules-based multilateral framework that reduces arbitrary protectionism and trade uncertainty for businesses.","distractor_reasons":{"A":"Incorrect because private retailers set their own prices.","B":"Incorrect because the WTO is a trade-rules body, not a commercial or startup bank.","C":"Incorrect because the WTO works to *reduce* tariffs and promote fair market access.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_795","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_795","question":"Why might a small domestic business focus on a 'niche market' or unique local heritage to survive competition from global multinationals?","options":{"A":"Because global MNCs rely on standardised mass production, leaving specialised, customised, or culturally authentic segments where small local firms can build strong customer loyalty.","B":"Because small local firms always have lower unit production costs than giant multinationals.","C":"Because global multinationals are legally banned from advertising on television.","D":"Because niche customers refuse to pay for specialised quality."},"correctOption":"A","correctAnswer":"Because global MNCs rely on standardised mass production, leaving specialised, customised, or culturally authentic segments where small local firms can build strong customer loyalty.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because differentiation, personal service, and local authenticity allow smaller firms to avoid head-on price wars with global giants.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because MNCs typically enjoy superior economies of scale and lower unit costs.","C":"Incorrect because MNCs have massive global advertising budgets.","D":"Incorrect because niche buyers often pay premium prices for tailored or authentic products."}}},{"id":"P1_U6_MCQ_796","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_796","question":"How does Foreign Direct Investment (FDI) by a multinational company initially affect a host country's balance of payments?","options":{"A":"It creates an immediate capital outflow from the host country.","B":"It brings an inward capital inflow as the MNC transfers foreign funds into the host country to build factories, buy land, and purchase equipment.","C":"It stops all exports from leaving the host country.","D":"It forces the host country to abandon its national currency."},"correctOption":"B","correctAnswer":"It brings an inward capital inflow as the MNC transfers foreign funds into the host country to build factories, buy land, and purchase equipment.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because building or acquiring productive facilities represents an inward investment flow that helps finance a current account deficit.","distractor_reasons":{"A":"Incorrect because initial FDI is an *inflow* of capital into the host nation (though later profit repatriation is an outflow).","B":"Correct selection.","C":"Incorrect because MNCs frequently increase the host country's export output.","D":"Incorrect because FDI operates within the host country's monetary system."}}},{"id":"P1_U6_MCQ_797","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_797","question":"What is 'cultural homogenisation' as a criticism of rapid globalisation?","options":{"A":"The preservation and revival of traditional local crafts and languages.","B":"The refusal of consumers to buy any foreign films, music, or food.","C":"The concern that dominant global brands, media, and lifestyles erode unique local traditions, languages, and independent domestic retailers.","D":"The requirement that every multinational company translate its manuals into local dialects."},"correctOption":"C","correctAnswer":"The concern that dominant global brands, media, and lifestyles erode unique local traditions, languages, and independent domestic retailers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because critics argue ubiquitous global chains and entertainment can weaken local cultural diversity.","distractor_reasons":{"A":"Incorrect because cultural homogenisation refers to increasing uniformity rather than preserving local uniqueness.","B":"Incorrect because homogenisation happens precisely when consumers embrace global brands widely.","C":"Correct selection.","D":"Incorrect because translating manuals respects local language rather than erasing it."}}},{"id":"P1_U6_MCQ_798","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_798","question":"Why do exporting businesses sometimes use an overseas 'sales agent' or 'distributor' when entering a new foreign market?","options":{"A":"Because overseas agents guarantee zero shipping costs.","B":"Because selling through an agent eliminates the need to manufacture the product.","C":"Because agents are government officials who waive all import duties.","D":"Because local agents already understand the foreign market's language, regulations, and retail buyers, lowering upfront entry costs compared to setting up a foreign branch."},"correctOption":"D","correctAnswer":"Because local agents already understand the foreign market's language, regulations, and retail buyers, lowering upfront entry costs compared to setting up a foreign branch.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because leveraging established local distribution channels speeds up market entry without heavy fixed capital commitment.","distractor_reasons":{"A":"Incorrect because international freight and insurance costs still apply.","B":"Incorrect because the exporting firm still manufactures the goods.","C":"Incorrect because agents are commercial intermediaries, not customs officials.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_799","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_799","question":"How does international trade allow countries and businesses to benefit from 'specialisation'?","options":{"A":"Businesses focus on producing goods and services where they have natural, skill, or cost advantages, achieving higher efficiency and trading surplus output for other goods.","B":"Every country is forced to produce every single item it consumes in tiny, inefficient quantities.","C":"Specialisation prevents businesses from using modern machinery.","D":"Specialisation eliminates all international transport and shipping."},"correctOption":"A","correctAnswer":"Businesses focus on producing goods and services where they have natural, skill, or cost advantages, achieving higher efficiency and trading surplus output for other goods.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because concentrating resources on core strengths raises global productivity and expands total output available to consumers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because producing everything domestically is self-sufficiency (autarky), the opposite of specialisation.","C":"Incorrect because specialising at high volume justifies investment in specialised machinery.","D":"Incorrect because international specialisation increases cross-border trade and shipping."}}},{"id":"P1_U6_MCQ_800","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_800","question":"When evaluating whether a host government should offer generous tax holidays to attract a multinational factory, which drawback must be weighed carefully?","options":{"A":"The multinational factory will never hire any local citizens.","B":"The host government forgoes substantial corporate tax revenue for years, and the MNC might leave as soon as the tax holiday ends.","C":"Tax holidays automatically cause hyperinflation across the host economy.","D":"Tax holidays prevent the MNC from exporting any products."},"correctOption":"B","correctAnswer":"The host government forgoes substantial corporate tax revenue for years, and the MNC might leave as soon as the tax holiday ends.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fiscal incentives carry an opportunity cost in lost public funds and risk attracting short-term, footloose investors.","distractor_reasons":{"A":"Incorrect because job creation is the primary reason governments offer such incentives.","B":"Correct selection.","C":"Incorrect because targeted corporate tax breaks do not automatically trigger hyperinflation.","D":"Incorrect because tax holidays are often specifically aimed at export-oriented factories."}}},{"id":"P1_U6_MCQ_801","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_801","question":"What is the key difference between renewable and non-renewable natural resources used by businesses?","options":{"A":"Renewable resources like coal and crude oil regenerate within hours, whereas solar power runs out permanently.","B":"Renewable resources are always free to harness with zero equipment costs.","C":"Renewable resources (such as solar, wind, and sustainably managed timber) replenish naturally over human timescales, whereas non-renewable resources (such as fossil fuels and metal ores) exist in finite stocks that deplete permanently.","D":"There is no difference between renewable and non-renewable resources."},"correctOption":"C","correctAnswer":"Renewable resources (such as solar, wind, and sustainably managed timber) replenish naturally over human timescales, whereas non-renewable resources (such as fossil fuels and metal ores) exist in finite stocks that deplete permanently.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because long-term environmental sustainability requires transitioning away from finite fossil fuels toward replenishable energy and materials.","distractor_reasons":{"A":"Incorrect because this reverses fossil fuels and solar energy.","B":"Incorrect because harnessing wind and solar energy requires upfront capital investment in turbines and panels.","C":"Correct selection.","D":"Incorrect because resource regeneration rates determine whether industrial use is sustainable."}}},{"id":"P1_U6_MCQ_802","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_802","question":"What is meant by 'sustainable development' in a business context?","options":{"A":"Maximising short-term extraction of minerals regardless of environmental destruction.","B":"Stopping all economic growth and closing all businesses permanently.","C":"Focusing solely on increasing annual shareholder dividends without considering ecology.","D":"Meeting the economic and consumer needs of the present without compromising the ability of future generations to meet their own needs."},"correctOption":"D","correctAnswer":"Meeting the economic and consumer needs of the present without compromising the ability of future generations to meet their own needs.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sustainable development balances economic progress, social wellbeing, and ecological preservation across generations.","distractor_reasons":{"A":"Incorrect because rapid resource depletion sacrifices future generations' needs.","B":"Incorrect because sustainable development seeks responsible growth rather than halting economic activity.","C":"Incorrect because sustainability requires integrating environmental stewardship alongside financial returns.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_803","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_803","question":"What is a business's 'carbon footprint'?","options":{"A":"The total amount of greenhouse gases (measured in carbon dioxide equivalents) emitted directly and indirectly by the business's operations, energy use, transport, and supply chain.","B":"The physical area of land occupied by the business's head office car park.","C":"The weight of coal stored inside a factory warehouse.","D":"The total profit earned by an oil and gas company."},"correctOption":"A","correctAnswer":"The total amount of greenhouse gases (measured in carbon dioxide equivalents) emitted directly and indirectly by the business's operations, energy use, transport, and supply chain.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because measuring a business's carbon footprint is the essential first step toward setting reduction targets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because land area is physical site size, not greenhouse gas emissions.","C":"Incorrect because coal inventory is a raw material stock, not total emissions.","D":"Incorrect because profit is a financial metric."}}},{"id":"P1_U6_MCQ_804","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_804","question":"How do government 'green subsidies' or grants encourage businesses to adopt cleaner technologies?","options":{"A":"By taxing solar panels heavily while making coal free.","B":"By lowering the upfront purchase and installation cost of electric delivery vans, heat pumps, or renewable energy systems, making green investment financially attractive.","C":"By banning businesses from upgrading outdated polluting machinery.","D":"By imposing fines on businesses that reduce their carbon emissions."},"correctOption":"B","correctAnswer":"By lowering the upfront purchase and installation cost of electric delivery vans, heat pumps, or renewable energy systems, making green investment financially attractive.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because financial subsidies overcome the high initial capital hurdle of clean technologies and accelerate adoption.","distractor_reasons":{"A":"Incorrect because green subsidies support clean energy rather than coal.","B":"Correct selection.","C":"Incorrect because grants encourage, rather than ban, equipment upgrades.","D":"Incorrect because emission cuts are rewarded rather than fined."}}},{"id":"P1_U6_MCQ_805","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_805","question":"What is the correct order of priorities in the 'waste management hierarchy' from most environmentally preferable to least preferable?","options":{"A":"Landfill disposal -> Incineration -> Recycling -> Reuse -> Reduce.","B":"Recycle -> Landfill -> Reduce -> Reuse.","C":"Reduce (prevent waste at source) -> Reuse -> Recycle -> Energy recovery -> Landfill disposal.","D":"Incineration -> Landfill -> Reduce -> Recycle."},"correctOption":"C","correctAnswer":"Reduce (prevent waste at source) -> Reuse -> Recycle -> Energy recovery -> Landfill disposal.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because preventing waste creation in the first place saves the most resources, while landfilling is the last resort.","distractor_reasons":{"A":"Incorrect because this lists the hierarchy completely backwards.","B":"Incorrect because reducing and reusing are superior to recycling and landfilling.","C":"Correct selection.","D":"Incorrect because incineration and landfill sit near the bottom of the hierarchy."}}},{"id":"P1_U6_MCQ_806","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_806","question":"How does a government 'landfill tax' influence business waste practices?","options":{"A":"It makes dumping waste in landfills completely free for factories.","B":"It encourages businesses to generate more non-recyclable plastic waste.","C":"It pays businesses a cash bonus for every tonne of rubbish buried underground.","D":"It increases the cost per tonne of sending waste to landfill, creating a strong financial incentive for firms to minimise waste, reuse materials, and recycle."},"correctOption":"D","correctAnswer":"It increases the cost per tonne of sending waste to landfill, creating a strong financial incentive for firms to minimise waste, reuse materials, and recycle.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because taxing landfill disposal makes recycling and waste prevention cheaper alternatives for businesses.","distractor_reasons":{"A":"Incorrect because the tax *raises* disposal fees.","B":"Incorrect because higher landfill fees discourage waste generation.","C":"Incorrect because businesses pay the tax rather than receiving a bonus.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_807","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_807","question":"What is the purpose of independent 'eco-labelling' schemes (such as FSC for sustainable timber or Energy Star for appliances)?","options":{"A":"To help consumers easily identify and choose genuinely environmentally friendly products, rewarding businesses that meet strict sustainability standards.","B":"To hide the country of origin of imported goods.","C":"To exempt labelled products from all consumer safety laws.","D":"To force consumers to buy the most polluting products available."},"correctOption":"A","correctAnswer":"To help consumers easily identify and choose genuinely environmentally friendly products, rewarding businesses that meet strict sustainability standards.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because credible eco-labels reduce buyer confusion and allow sustainable producers to differentiate their brands.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because eco-labels increase transparency rather than hiding origins.","C":"Incorrect because consumer safety laws remain fully enforceable.","D":"Incorrect because eco-labels guide shoppers *toward* low-impact choices."}}},{"id":"P1_U6_MCQ_808","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_808","question":"Why can investing in environmentally friendly production technology create a short-term conflict between shareholders and local community stakeholders?","options":{"A":"Because local residents want factories to pollute local rivers as much as possible.","B":"Because purchasing clean filtration and renewable equipment requires high upfront capital spending that may reduce short-term profits and dividends, even though it benefits local residents immediately.","C":"Because clean technology always increases factory smoke and noise.","D":"Because shareholders are legally banned from receiving dividends if a firm recycles."},"correctOption":"B","correctAnswer":"Because purchasing clean filtration and renewable equipment requires high upfront capital spending that may reduce short-term profits and dividends, even though it benefits local residents immediately.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because capital expenditure on pollution control hits short-term cash flow and dividends before long-term reputation and efficiency gains pay back.","distractor_reasons":{"A":"Incorrect because local communities strongly oppose pollution.","B":"Correct selection.","C":"Incorrect because clean technology *reduces* smoke and noise.","D":"Incorrect because sustainable businesses regularly pay dividends to shareholders."}}},{"id":"P1_U6_MCQ_809","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_809","question":"How can a food retailer reduce its 'food miles' and transport-related carbon emissions?","options":{"A":"By air-freighting fresh strawberries from across the globe every winter.","B":"By sending half-empty delivery lorries on longer routes.","C":"By sourcing seasonal produce from local and regional farms and optimising delivery vehicle loads and routes.","D":"By replacing electric delivery vans with older diesel trucks."},"correctOption":"C","correctAnswer":"By sourcing seasonal produce from local and regional farms and optimising delivery vehicle loads and routes.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local seasonal sourcing and route optimisation cut long-haul freight distances and fuel consumption.","distractor_reasons":{"A":"Incorrect because air freight generates very high carbon emissions per kilogram of food.","B":"Incorrect because half-empty trucks increase emissions per unit delivered.","C":"Correct selection.","D":"Incorrect because diesel trucks emit more greenhouse gases and particulates than electric vans."}}},{"id":"P1_U6_MCQ_810","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_810","question":"What is an 'environmental audit' conducted by a business?","options":{"A":"A check on whether employees arrive at work on time every morning.","B":"A calculation of the business's annual Value Added Tax bill.","C":"A survey measuring customer satisfaction with retail store music.","D":"A systematic internal or external review of the business's energy use, water consumption, waste generation, emissions, and compliance with environmental laws."},"correctOption":"D","correctAnswer":"A systematic internal or external review of the business's energy use, water consumption, waste generation, emissions, and compliance with environmental laws.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because regular environmental audits identify resource inefficiencies, legal compliance gaps, and opportunities to cut pollution.","distractor_reasons":{"A":"Incorrect because staff punctuality is an HR attendance matter.","B":"Incorrect because VAT calculation is financial tax accounting.","C":"Incorrect because store atmosphere feedback is customer market research.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_811","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_811","question":"How does climate change pose direct physical and operational risks to businesses and their supply chains?","options":{"A":"Extreme weather events—such as floods, droughts, heatwaves, and severe storms—can damage factories, disrupt crop harvests, and halt shipping and road transport.","B":"Climate change guarantees stable, mild weather for all farms every year.","C":"Climate change lowers business insurance premiums to zero.","D":"Climate change affects only polar bears and never touches commercial ports or agriculture."},"correctOption":"A","correctAnswer":"Extreme weather events—such as floods, droughts, heatwaves, and severe storms—can damage factories, disrupt crop harvests, and halt shipping and road transport.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because climate volatility threatens raw material availability, infrastructure resilience, and insurance costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because climate change *increases* weather extremes and harvest volatility.","C":"Incorrect because higher flood and storm risks *raise* commercial insurance premiums.","D":"Incorrect because agriculture, tourism, logistics, and coastal infrastructure face direct physical risks."}}},{"id":"P1_U6_MCQ_812","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_812","question":"What is the 'product-as-a-service' (leasing/subscription) business model and how does it support environmental sustainability?","options":{"A":"Selling cheap disposable appliances designed to be thrown away after six months.","B":"Retaining ownership of equipment (such as lighting, tyres, or washing machines) and leasing usage to customers, motivating the manufacturer to design durable, repairable, and recyclable products.","C":"Refusing to repair any broken machines and telling customers to buy new ones.","D":"Banning customers from returning used equipment at the end of a contract."},"correctOption":"B","correctAnswer":"Retaining ownership of equipment (such as lighting, tyres, or washing machines) and leasing usage to customers, motivating the manufacturer to design durable, repairable, and recyclable products.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when the manufacturer bears maintenance and end-of-life costs, durability and modular recycling become directly profitable.","distractor_reasons":{"A":"Incorrect because cheap disposable items reflect the wasteful linear model.","B":"Correct selection.","C":"Incorrect because service contracts include repair and maintenance.","D":"Incorrect because take-back recovery is central to product-as-a-service."}}},{"id":"P1_U6_MCQ_813","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_813","question":"How does 'upcycling' differ from basic 'downcycling' in industrial waste management?","options":{"A":"Upcycling burns waste in open pits, whereas downcycling buries waste in landfills.","B":"Upcycling reduces material quality, whereas downcycling destroys materials completely.","C":"Upcycling transforms waste materials into new products of higher quality or environmental value, whereas downcycling reprocesses waste into lower-grade materials (such as turning high-grade plastic into park benches).","D":"There is no difference between upcycling and downcycling."},"correctOption":"C","correctAnswer":"Upcycling transforms waste materials into new products of higher quality or environmental value, whereas downcycling reprocesses waste into lower-grade materials (such as turning high-grade plastic into park benches).","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because upcycling preserves or elevates material value rather than degrading it over successive cycles.","distractor_reasons":{"A":"Incorrect because open burning and landfilling are disposal rather than recycling.","B":"Incorrect because this reverses upcycling and downcycling.","C":"Correct selection.","D":"Incorrect because the resulting material quality distinguishes the two processes."}}},{"id":"P1_U6_MCQ_814","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_814","question":"Why do many governments introduce urban 'Low Emission Zones' or 'congestion charges' affecting delivery businesses?","options":{"A":"To encourage more heavy diesel lorries to drive through city centres at rush hour.","B":"To eliminate all public buses and trains.","C":"To raise the price of electric bicycles.","D":"To reduce city-centre air pollution and traffic congestion by charging polluting vehicles and incentivising businesses to switch to zero-emission electric vans."},"correctOption":"D","correctAnswer":"To reduce city-centre air pollution and traffic congestion by charging polluting vehicles and incentivising businesses to switch to zero-emission electric vans.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because daily charges on high-emission vehicles internalise urban air-quality externalities and accelerate fleet electrification.","distractor_reasons":{"A":"Incorrect because the charges are designed to *deter* polluting lorries.","B":"Incorrect because congestion revenues typically fund *expanded* public transit.","C":"Incorrect because clean transport modes like cargo bikes are exempt and encouraged.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_815","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_815","question":"How can water-intensive businesses (such as beverage bottlers, textile dyers, or semiconductor plants) reduce their environmental water footprint?","options":{"A":"By installing greywater treatment and closed-loop recycling systems, fixing leaks, and adopting water-efficient dyeing or cooling technologies.","B":"By pumping untreated chemical wastewater directly into local rivers.","C":"By leaving factory taps running continuously overnight.","D":"By locating exclusively in severe desert regions without water conservation plans."},"correctOption":"A","correctAnswer":"By installing greywater treatment and closed-loop recycling systems, fixing leaks, and adopting water-efficient dyeing or cooling technologies.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because water recycling and efficiency protect local freshwater supplies and lower water utility expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because untreated discharge causes severe water pollution.","C":"Incorrect because running taps continuously wastes freshwater.","D":"Incorrect because operating in water-stressed regions without conservation creates major operational and community risk."}}},{"id":"P1_U6_MCQ_816","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_816","question":"What is 'visual pollution' caused by commercial or industrial operations?","options":{"A":"Toxic chemical fumes entering workers' lungs.","B":"Unsightly industrial eyesores—such as overflowing rubbish tips, abandoned derelict factories, or excessive giant billboards—that spoil natural landscapes and local surroundings.","C":"Loud machinery vibrations keeping neighbours awake at night.","D":"Fertiliser runoff causing algae blooms in lakes."},"correctOption":"B","correctAnswer":"Unsightly industrial eyesores—such as overflowing rubbish tips, abandoned derelict factories, or excessive giant billboards—that spoil natural landscapes and local surroundings.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because visual degradation lowers local property values, harms tourism, and provokes community opposition.","distractor_reasons":{"A":"Incorrect because toxic fumes represent *air* pollution.","B":"Correct selection.","C":"Incorrect because loud machinery represents *noise* pollution.","D":"Incorrect because fertiliser runoff causes *water* pollution."}}},{"id":"P1_U6_MCQ_817","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_817","question":"Why is 'biodiversity loss' a growing concern for agricultural, pharmaceutical, and food businesses?","options":{"A":"Because insects, soil microbes, and diverse plant species are completely unnecessary for farming or medicine.","B":"Because biodiversity loss lowers the price of all fertilizers to zero.","C":"Because ecosystems provide vital services—such as crop pollination, fertile soil, clean water, and genetic compounds for medicines—whose collapse threatens long-term production.","D":"Because governments reward businesses that destroy wildlife habitats."},"correctOption":"C","correctAnswer":"Because ecosystems provide vital services—such as crop pollination, fertile soil, clean water, and genetic compounds for medicines—whose collapse threatens long-term production.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because business operations depend heavily on healthy natural ecosystems ('natural capital').","distractor_reasons":{"A":"Incorrect because pollinators and healthy soils are essential for global crop yields.","B":"Incorrect because degraded soils actually require *more* costly inputs.","C":"Correct selection.","D":"Incorrect because governments increasingly restrict habitat destruction."}}},{"id":"P1_U6_MCQ_818","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_818","question":"What is a 'green bond' issued by a company?","options":{"A":"A loan used exclusively to build new coal-fired power stations.","B":"A government tax penalty levied on polluting factories.","C":"An insurance policy covering shoplifting losses in retail stores.","D":"A fixed-income debt instrument issued to raise capital specifically earmarked for environmentally beneficial projects such as renewable energy, clean transport, or energy efficiency."},"correctOption":"D","correctAnswer":"A fixed-income debt instrument issued to raise capital specifically earmarked for environmentally beneficial projects such as renewable energy, clean transport, or energy efficiency.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because green bonds tap into growing sustainable investor demand to finance low-carbon capital projects.","distractor_reasons":{"A":"Incorrect because green bonds exclude fossil-fuel expansion.","B":"Incorrect because a bond is a voluntary borrowing instrument, not a tax fine.","C":"Incorrect because shoplifting cover is commercial theft insurance.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_819","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_819","question":"How can installing rooftop solar panels on a large warehouse or factory benefit a business financially over the medium to long term?","options":{"A":"After paying off the initial installation cost, generating free on-site electricity sharply lowers monthly utility bills and insulates the business from volatile fossil-fuel energy prices.","B":"It guarantees that the business never has to pay employee wages again.","C":"It doubles the business's annual electricity bill every year.","D":"It exempts the business from obeying workplace health and safety laws."},"correctOption":"A","correctAnswer":"After paying off the initial installation cost, generating free on-site electricity sharply lowers monthly utility bills and insulates the business from volatile fossil-fuel energy prices.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because on-site solar generation turns a recurring variable utility cost into a predictable, low-cost asset.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because solar panels reduce electricity expenses, not payroll obligations.","C":"Incorrect because solar generation *reduces* grid electricity bills.","D":"Incorrect because workplace safety laws remain fully binding."}}},{"id":"P1_U6_MCQ_820","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_820","question":"Why do governments sometimes pass outright legal bans on single-use plastic items (such as plastic straws, stirrers, and carrier bags)?","options":{"A":"Because single-use plastics decompose harmlessly within two days.","B":"Because market prices alone failed to stop massive marine plastic litter, making direct legal prohibition faster and more certain than voluntary appeals.","C":"To increase profits for petrochemical plastic manufacturers.","D":"To force supermarkets to stop selling fresh fruit and vegetables."},"correctOption":"B","correctAnswer":"Because market prices alone failed to stop massive marine plastic litter, making direct legal prohibition faster and more certain than voluntary appeals.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when cheap disposable products cause severe persistent pollution, direct command-and-control bans drive immediate industry switching to paper, bamboo, or reusable alternatives.","distractor_reasons":{"A":"Incorrect because conventional plastics persist for centuries in oceans and landfills.","B":"Correct selection.","C":"Incorrect because bans reduce demand for single-use plastics.","D":"Incorrect because supermarkets switch to paper, compostable, or reusable packaging."}}},{"id":"P1_U6_MCQ_821","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_821","question":"What is 'regenerative agriculture' increasingly adopted by responsible food and beverage companies?","options":{"A":"Clearing rainforests every two years to plant single crops with heavy chemical pesticides.","B":"Replacing all farmland with concrete industrial warehouses.","C":"Farming methods (such as crop rotation, cover crops, and reduced tillage) that restore soil health, increase biodiversity, retain water, and capture carbon in the soil.","D":"Importing all food by supersonic aircraft."},"correctOption":"C","correctAnswer":"Farming methods (such as crop rotation, cover crops, and reduced tillage) that restore soil health, increase biodiversity, retain water, and capture carbon in the soil.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because regenerative farming actively heals degraded ecosystems while securing long-term agricultural resilience.","distractor_reasons":{"A":"Incorrect because deforestation and heavy chemical monoculture deplete soil rather than regenerating it.","B":"Incorrect because paving over farmland destroys agricultural capacity.","C":"Correct selection.","D":"Incorrect because air transport is unrelated to regenerative soil management."}}},{"id":"P1_U6_MCQ_822","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_822","question":"How does 'dematerialisation' (replacing physical products with digital services, such as streaming music or e-tickets) benefit the environment?","options":{"A":"It increases the mining of metals and plastics needed for physical discs and paper tickets.","B":"It requires shipping millions of plastic cases across oceans by diesel cargo ships.","C":"It forces consumers to buy larger petrol-powered cars.","D":"It drastically cuts raw material extraction, manufacturing waste, packaging, and physical freight transport per consumer experience."},"correctOption":"D","correctAnswer":"It drastically cuts raw material extraction, manufacturing waste, packaging, and physical freight transport per consumer experience.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because delivering value digitally eliminates physical material throughput and transport emissions.","distractor_reasons":{"A":"Incorrect because digital delivery *replaces* physical discs and paper.","B":"Incorrect because digital files move electronically rather than on container ships.","C":"Incorrect because digital services do not require car purchases.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_823","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_823","question":"Why is international cooperation (such as global climate summits) essential when regulating business carbon emissions?","options":{"A":"Because greenhouse gases affect the entire global atmosphere, and unilateral strict rules in one country could simply push polluting factories to relocate to countries with weak laws ('carbon leakage').","B":"Because carbon dioxide stays strictly inside the borders of the city where it was emitted.","C":"Because individual national governments have no legal power to tax domestic factories.","D":"Because international agreements ban all renewable energy projects."},"correctOption":"A","correctAnswer":"Because greenhouse gases affect the entire global atmosphere, and unilateral strict rules in one country could simply push polluting factories to relocate to countries with weak laws ('carbon leakage').","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because climate change is a global commons problem requiring coordinated standards to prevent 'carbon leakage' and unfair cost disadvantages.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because greenhouse gases mix globally in the atmosphere.","C":"Incorrect because national governments can tax domestic firms, though coordination prevents offshoring of pollution.","D":"Incorrect because climate treaties strongly promote renewable energy."}}},{"id":"P1_U6_MCQ_824","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_824","question":"What is 'design for disassembly' (modular design) in sustainable manufacturing?","options":{"A":"Gluing all smartphone and appliance parts together permanently so they can never be opened or repaired.","B":"Engineering products with standardised fasteners and separable components so faulty parts can be easily repaired, upgraded, or separated for pure recycling at end of life.","C":"Designing products that fall apart accidentally during normal customer use.","D":"Using twenty different incompatible plastics melted together in a single casing."},"correctOption":"B","correctAnswer":"Engineering products with standardised fasteners and separable components so faulty parts can be easily repaired, upgraded, or separated for pure recycling at end of life.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because modular assembly extends product lifespan and prevents material contamination during recycling.","distractor_reasons":{"A":"Incorrect because permanent gluing prevents repair and hinders recycling.","B":"Correct selection.","C":"Incorrect because design for disassembly ensures durability during use alongside easy servicing when needed.","D":"Incorrect because mixed fused plastics are nearly impossible to recycle cleanly."}}},{"id":"P1_U6_MCQ_825","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_825","question":"Which statement best evaluates the financial trade-off faced by a small business considering a switch to 100% sustainable materials and renewable energy?","options":{"A":"Sustainable materials are always completely free, so there is never any financial trade-off.","B":"Small businesses are legally prohibited from using renewable energy.","C":"Higher upfront capital and unit material costs can squeeze short-term cash flow, though lower energy bills, green grants, and eco-conscious customer loyalty can improve long-term profitability.","D":"Switching to sustainable materials guarantees immediate bankruptcy within one month."},"correctOption":"C","correctAnswer":"Higher upfront capital and unit material costs can squeeze short-term cash flow, though lower energy bills, green grants, and eco-conscious customer loyalty can improve long-term profitability.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a balanced business evaluation weighs short-term liquidity and cost pressures against medium-to-long-term efficiency and brand differentiation.","distractor_reasons":{"A":"Incorrect because sustainable inputs and clean equipment typically carry higher initial prices.","B":"Incorrect because small businesses are actively encouraged to adopt clean energy.","C":"Correct selection.","D":"Incorrect because phased, well-planned sustainability transitions often strengthen small business resilience."}}},{"id":"P1_U6_MCQ_826","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_826","question":"Why is the use of 'child labour' in a business's supply chain universally condemned on ethical grounds?","options":{"A":"Because employing children deprives them of schooling, harms their physical and mental development, and exploits vulnerable families to cut labour costs.","B":"Because children always demand higher salaries than adult engineers.","C":"Because child labour laws apply only to software companies.","D":"Because employing children increases a business's corporation tax rate to 90%."},"correctOption":"A","correctAnswer":"Because employing children deprives them of schooling, harms their physical and mental development, and exploits vulnerable families to cut labour costs.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because exploiting underage workers violates fundamental human rights and perpetuates generational poverty.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because unethical employers use child labour specifically because children are paid little or nothing.","C":"Incorrect because child labour protections apply across all sectors, especially agriculture, garments, and mining.","D":"Incorrect because child labour is a human rights and criminal/regulatory breach, not a tax bracket."}}},{"id":"P1_U6_MCQ_827","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_827","question":"How does the 'Fairtrade' system ensure ethical treatment of small-scale farmers in developing countries?","options":{"A":"By forcing farmers to sell crops below production cost whenever world market prices crash.","B":"By guaranteeing a fair minimum price that covers sustainable production costs plus an additional Fairtrade Premium for community health, education, and farming projects.","C":"By banning farmers from forming agricultural cooperatives.","D":"By eliminating all quality standards for exported coffee and cocoa."},"correctOption":"B","correctAnswer":"By guaranteeing a fair minimum price that covers sustainable production costs plus an additional Fairtrade Premium for community health, education, and farming projects.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the guaranteed minimum price protects farmers against volatile commodity crashes while the social premium funds local development.","distractor_reasons":{"A":"Incorrect because Fairtrade protects farmers *against* below-cost market prices.","B":"Correct selection.","C":"Incorrect because Fairtrade encourages democratic farmer cooperatives.","D":"Incorrect because Fairtrade enforces strict environmental and quality criteria."}}},{"id":"P1_U6_MCQ_828","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_828","question":"What is 'whistleblowing' inside a business and why do ethical companies establish confidential whistleblowing hotlines?","options":{"A":"Using loud whistles to signal the start and end of factory shifts.","B":"Leaking confidential customer passwords to cybercriminals for money.","C":"An employee reporting illegal, unsafe, or unethical misconduct within the organisation; confidential channels allow issues to be fixed internally without fear of retaliation.","D":"Spreading false rumours to get a rival colleague fired."},"correctOption":"C","correctAnswer":"An employee reporting illegal, unsafe, or unethical misconduct within the organisation; confidential channels allow issues to be fixed internally without fear of retaliation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because protecting whistleblowers uncovers fraud, safety hazards, or corruption early before catastrophic harm occurs.","distractor_reasons":{"A":"Incorrect because factory shift signals are operational timekeeping, not ethical reporting.","B":"Incorrect because stealing customer data is malicious cybercrime.","C":"Correct selection.","D":"Incorrect because whistleblowing involves good-faith disclosure of genuine wrongdoing."}}},{"id":"P1_U6_MCQ_829","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_829","question":"What is the purpose of a formal 'Corporate Code of Ethics' (Code of Conduct)?","options":{"A":"To list the secret recipes of the company's best-selling products.","B":"To replace all national criminal laws so employees cannot be prosecuted.","C":"To instruct managers on how to hide product defects from regulators.","D":"To set clear written standards of moral behaviour—covering honesty, anti-bribery, fairness, conflicts of interest, and respect—guiding daily decisions by all staff."},"correctOption":"D","correctAnswer":"To set clear written standards of moral behaviour—covering honesty, anti-bribery, fairness, conflicts of interest, and respect—guiding daily decisions by all staff.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a clear code defines acceptable conduct across global offices and holds employees accountable.","distractor_reasons":{"A":"Incorrect because product formulas are trade secrets, not ethical codes.","B":"Incorrect because corporate codes supplement rather than replace national laws.","C":"Incorrect because ethical codes require honesty and safety transparency.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_830","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_830","question":"Why is aggressive advertising of high-sugar junk food or loot-box gambling mechanics directly to young children widely viewed as unethical?","options":{"A":"Because young children lack the cognitive maturity to evaluate persuasive commercial intent critically and are vulnerable to long-term health or financial harm.","B":"Because young children control multinational corporate budgets.","C":"Because advertising to adults is illegal in every country.","D":"Because sugary snacks are healthier than fresh vegetables."},"correctOption":"A","correctAnswer":"Because young children lack the cognitive maturity to evaluate persuasive commercial intent critically and are vulnerable to long-term health or financial harm.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical marketing avoids exploiting vulnerable audiences who cannot make fully informed choices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because children do not manage corporate finances.","C":"Incorrect because lawful advertising to adults is standard practice.","D":"Incorrect because high-sugar diets contribute to childhood obesity and tooth decay."}}},{"id":"P1_U6_MCQ_831","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_831","question":"What is the ethical responsibility of a technology or retail business regarding customer personal data?","options":{"A":"Selling customers' private medical and financial records to third-party data brokers without consent.","B":"Collecting only necessary data with transparent consent, securing it strongly against cyber breaches, and never misusing or selling private information.","C":"Publishing customer home addresses publicly on the company website.","D":"Deleting all data security firewalls to save IT maintenance costs."},"correctOption":"B","correctAnswer":"Collecting only necessary data with transparent consent, securing it strongly against cyber breaches, and never misusing or selling private information.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because respecting customer privacy and data security upholds trust and goes beyond minimal legal compliance.","distractor_reasons":{"A":"Incorrect because covertly selling sensitive personal data violates privacy ethics and data protection laws.","B":"Correct selection.","C":"Incorrect because exposing customer addresses endangers personal safety.","D":"Incorrect because cutting cybersecurity negligently exposes users to identity theft."}}},{"id":"P1_U6_MCQ_832","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_832","question":"Why do extreme pay gaps between top Chief Executive Officers (CEOs) and lowest-paid frontline workers often spark ethical criticism?","options":{"A":"Because CEOs never make any strategic business decisions.","B":"Because frontline workers earn millions of dollars per hour.","C":"Because paying executives hundreds of times more than full-time workers struggling to afford basic living costs is seen as unfair and damages employee morale.","D":"Because high executive bonuses are required by international human rights treaties."},"correctOption":"C","correctAnswer":"Because paying executives hundreds of times more than full-time workers struggling to afford basic living costs is seen as unfair and damages employee morale.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because fairness in reward distribution affects internal perceptions of justice, industrial relations, and public reputation.","distractor_reasons":{"A":"Incorrect because CEOs carry major strategic responsibility, though critics question disproportionate reward ratios.","B":"Incorrect because frontline retail, warehouse, and care workers typically earn modest wages.","C":"Correct selection.","D":"Incorrect because human rights treaties protect basic worker dignity rather than executive bonuses."}}},{"id":"P1_U6_MCQ_833","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_833","question":"What is the difference between 'tax evasion' and 'aggressive tax avoidance' in business ethics?","options":{"A":"Tax evasion is completely legal, whereas tax avoidance is a violent crime.","B":"Both terms mean voluntarily paying extra tax to fund local schools.","C":"Tax evasion applies only to households, whereas tax avoidance applies only to charities.","D":"Tax evasion is illegally hiding income or falsifying records to dodge tax, whereas aggressive tax avoidance uses legal loopholes to shift profits artificially—which is legal in letter but often criticised as unethical."},"correctOption":"D","correctAnswer":"Tax evasion is illegally hiding income or falsifying records to dodge tax, whereas aggressive tax avoidance uses legal loopholes to shift profits artificially—which is legal in letter but often criticised as unethical.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ethics asks not merely 'is it legal?' but 'is it fair to contribute properly to the public infrastructure our business relies upon?'","distractor_reasons":{"A":"Incorrect because this reverses legality: evasion is illegal, whereas avoidance exploits legal loopholes.","B":"Incorrect because both reduce tax payments rather than making voluntary extra contributions.","C":"Incorrect because corporations can engage in either practice.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_834","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_834","question":"How does paying a voluntary 'living wage' differ from paying the bare statutory 'minimum wage'?","options":{"A":"A living wage is calculated to cover the real cost of essential housing, food, healthcare, and transport for a decent standard of living, often exceeding the legal minimum floor.","B":"A living wage is lower than the statutory minimum wage.","C":"A living wage pays workers exclusively in company vouchers instead of money.","D":"There is never any difference between a living wage and a legal minimum wage."},"correctOption":"A","correctAnswer":"A living wage is calculated to cover the real cost of essential housing, food, healthcare, and transport for a decent standard of living, often exceeding the legal minimum floor.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical employers choose to pay a genuine living wage to prevent in-work poverty and boost staff retention.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because paying below the statutory minimum is illegal.","C":"Incorrect because wages are paid in standard currency.","D":"Incorrect because legal minimum wages are often set below true living costs."}}},{"id":"P1_U6_MCQ_835","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_835","question":"Why is 'late payment of invoices' by a large corporation to its small suppliers considered an unethical business practice?","options":{"A":"Because small suppliers prefer waiting twelve months to be paid.","B":"Because large corporations use their dominant bargaining power to hoard cash at the expense of vulnerable small suppliers, starving them of working capital and risking their bankruptcy.","C":"Because paying suppliers on time is illegal under commercial law.","D":"Because small suppliers never have wages or rent to pay."},"correctOption":"B","correctAnswer":"Because large corporations use their dominant bargaining power to hoard cash at the expense of vulnerable small suppliers, starving them of working capital and risking their bankruptcy.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ethical supply-chain partnership includes fair, prompt payment terms rather than abusing market dominance.","distractor_reasons":{"A":"Incorrect because small businesses need timely cash inflows to survive.","B":"Correct selection.","C":"Incorrect because prompt payment is encouraged and increasingly required by prompt-payment codes.","D":"Incorrect because small suppliers face immediate payroll and overhead bills."}}},{"id":"P1_U6_MCQ_836","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_836","question":"What is 'shrinkflation' and when does it raise ethical concerns in retail?","options":{"A":"Increasing the weight of a chocolate bar by 20% while keeping the price unchanged.","B":"Lowering retail prices during an economic deflation.","C":"Reducing the weight, volume, or quantity of a product inside its packaging while keeping the retail price the same—especially if done without clear labelling so shoppers do not notice.","D":"Offering free sample sizes to shoppers inside supermarkets."},"correctOption":"C","correctAnswer":"Reducing the weight, volume, or quantity of a product inside its packaging while keeping the retail price the same—especially if done without clear labelling so shoppers do not notice.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because covertly shrinking pack sizes while maintaining identical-looking boxes misleads consumers about unit value.","distractor_reasons":{"A":"Incorrect because giving more product for the same price is a bonus pack, not shrinkflation.","B":"Incorrect because falling shelf prices represent deflation.","C":"Correct selection.","D":"Incorrect because free promotional samples are transparent marketing."}}},{"id":"P1_U6_MCQ_837","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_837","question":"What are 'conflict minerals' (such as tantalum, tin, tungsten, and gold from war-torn regions) and what is an electronics company's ethical duty regarding them?","options":{"A":"Minerals mined exclusively in peaceful university laboratories.","B":"Minerals used only to make children's wooden toys.","C":"Synthetic plastics that contain zero metal content.","D":"Minerals whose extraction finances armed conflict and severe human rights abuses; ethical firms audit smelters and source only certified conflict-free minerals."},"correctOption":"D","correctAnswer":"Minerals whose extraction finances armed conflict and severe human rights abuses; ethical firms audit smelters and source only certified conflict-free minerals.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because responsible supply-chain due diligence ensures corporate purchasing does not fund violence or forced labour.","distractor_reasons":{"A":"Incorrect because conflict minerals are mined in regions suffering armed militia violence.","B":"Incorrect because these metals are critical components in smartphones, laptops, and circuit boards.","C":"Incorrect because conflict minerals are metallic ores, not plastics.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_838","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_838","question":"How does 'shareholder theory' (associated with Milton Friedman) differ from 'stakeholder theory' (associated with R. Edward Freeman) regarding business ethics?","options":{"A":"Shareholder theory argues a business's primary social responsibility is to maximise profits legally for owners, whereas stakeholder theory argues managers must balance ethical obligations to employees, customers, suppliers, communities, and the environment alongside owners.","B":"Shareholder theory bans companies from making any profit, whereas stakeholder theory bans hiring employees.","C":"Shareholder theory requires companies to donate 100% of revenue to charity.","D":"There is no difference between shareholder theory and stakeholder theory."},"correctOption":"A","correctAnswer":"Shareholder theory argues a business's primary social responsibility is to maximise profits legally for owners, whereas stakeholder theory argues managers must balance ethical obligations to employees, customers, suppliers, communities, and the environment alongside owners.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because this classic contrast explains why different boards prioritise short-term financial returns versus broader social responsibility.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shareholder theory focuses *specifically* on profit maximisation for owners.","C":"Incorrect because donating 100% of revenue would eliminate shareholder returns.","D":"Incorrect because the two frameworks define corporate purpose very differently."}}},{"id":"P1_U6_MCQ_839","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_839","question":"What is 'cause-related marketing' and how can a business ensure it remains ethical?","options":{"A":"Claiming a product cures serious diseases without any medical evidence.","B":"Partnering with a charity so a clearly disclosed portion of each product sale supports a social or environmental cause, backed by genuine donations rather than empty slogans.","C":"Pocketing money collected in charity donation boxes to pay executive bonuses.","D":"Hiding the exact donation amount so consumers wrongly think 100% goes to charity."},"correctOption":"B","correctAnswer":"Partnering with a charity so a clearly disclosed portion of each product sale supports a social or environmental cause, backed by genuine donations rather than empty slogans.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because transparent cause-related campaigns create mutual benefit for the charity, the brand, and socially conscious shoppers.","distractor_reasons":{"A":"Incorrect because false medical claims are fraudulent marketing.","B":"Correct selection.","C":"Incorrect because misappropriating charity funds is theft and fraud.","D":"Incorrect because ethical campaigns disclose exact donation terms clearly."}}},{"id":"P1_U6_MCQ_840","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_840","question":"How can a business handle unavoidable factory redundancies in an ethical manner?","options":{"A":"Locking the factory gates overnight without warning and refusing to pay owed wages.","B":"Blaming the redundant workers publicly for management's strategic mistakes.","C":"Consulting employees early, applying fair objective selection criteria, offering generous severance pay, and providing career retraining and job-placement support.","D":"Firing only older workers or pregnant employees to save pension costs."},"correctOption":"C","correctAnswer":"Consulting employees early, applying fair objective selection criteria, offering generous severance pay, and providing career retraining and job-placement support.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because compassionate, transparent restructuring respects worker dignity and preserves trust among remaining staff and the community.","distractor_reasons":{"A":"Incorrect because sudden lockouts without notice or owed pay are unethical and unlawful.","B":"Incorrect because scapegoating staff is unfair and damages reputation.","C":"Correct selection.","D":"Incorrect because targeting age or pregnancy is unlawful discrimination."}}},{"id":"P1_U6_MCQ_841","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_841","question":"Why do cosmetic and household product companies increasingly adopt 'cruelty-free' (no animal testing) policies?","options":{"A":"Because animal testing is cheaper than computer modelling in every laboratory.","B":"Because consumers are indifferent to animal welfare.","C":"Because cruelty-free products are exempt from all ingredient safety checks.","D":"Because modern non-animal testing alternatives are scientifically reliable, avoid animal suffering, and meet growing ethical expectations from consumers and regulators."},"correctOption":"D","correctAnswer":"Because modern non-animal testing alternatives are scientifically reliable, avoid animal suffering, and meet growing ethical expectations from consumers and regulators.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ethical product development avoids unnecessary animal harm while ensuring human safety through validated alternative testing.","distractor_reasons":{"A":"Incorrect because ethical companies choose cruelty-free methods on moral and consumer-demand grounds.","B":"Incorrect because strong consumer and pressure-group opposition drove cruelty-free bans in many markets.","C":"Incorrect because products still undergo rigorous non-animal safety assessments.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_842","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_842","question":"What is 'B-Corp' (Certified B Corporation) status achieved by certain ethical businesses?","options":{"A":"A rigorous independent certification verifying that a for-profit business meets high standards of verified social and environmental performance, public transparency, and legal accountability to balance profit and purpose.","B":"A tax status that exempts a business from paying any wages or taxes.","C":"A label given to businesses that have declared bankruptcy twice.","D":"A government licence allowing a company to pollute rivers legally."},"correctOption":"A","correctAnswer":"A rigorous independent certification verifying that a for-profit business meets high standards of verified social and environmental performance, public transparency, and legal accountability to balance profit and purpose.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because B-Corp certification embeds stakeholder accountability into a company's legal governance and verifies holistic ethical impact.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because B-Corps are tax-paying commercial businesses.","C":"Incorrect because 'B' stands for 'Benefit' (for all stakeholders), not bankruptcy.","D":"Incorrect because B-Corps must meet strict environmental stewardship benchmarks."}}},{"id":"P1_U6_MCQ_843","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_843","question":"Why is 'algorithmic bias' in automated recruitment software an ethical issue for human resource managers?","options":{"A":"Because recruitment software never screens job applications.","B":"Because AI tools trained on biased historical hiring data can unfairly reject qualified candidates based on gender, ethnicity, age, or postcode without human oversight.","C":"Because automated software always hires every single applicant who applies.","D":"Because ethical hiring requires judging applicants solely on their social media photos."},"correctOption":"B","correctAnswer":"Because AI tools trained on biased historical hiring data can unfairly reject qualified candidates based on gender, ethnicity, age, or postcode without human oversight.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ethical equality of opportunity requires auditing digital HR tools to prevent hidden discrimination.","distractor_reasons":{"A":"Incorrect because many large employers use automated applicant-tracking algorithms.","B":"Correct selection.","C":"Incorrect because screening software filters *out* applicants.","D":"Incorrect because ethical recruitment evaluates relevant skills and merit objectively."}}},{"id":"P1_U6_MCQ_844","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_844","question":"What is 'ethical relativism' versus 'ethical absolutism' when a multinational operates across countries with different cultural norms?","options":{"A":"Ethical absolutism means breaking all local laws, whereas ethical relativism means obeying every international treaty.","B":"Both terms mean paying workers zero wages in foreign branches.","C":"Ethical relativism adapts practices to local customs ('when in Rome'), whereas ethical absolutism enforces universal core human-rights and anti-bribery standards across every country regardless of local norms.","D":"Multinational companies never encounter differing cultural or ethical standards abroad."},"correctOption":"C","correctAnswer":"Ethical relativism adapts practices to local customs ('when in Rome'), whereas ethical absolutism enforces universal core human-rights and anti-bribery standards across every country regardless of local norms.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because leading ethical MNCs respect harmless local cultural customs while upholding universal core standards on safety, anti-corruption, and human dignity.","distractor_reasons":{"A":"Incorrect because ethical absolutism upholds universal moral rules, not lawbreaking.","B":"Incorrect because universal ethical standards require fair wages.","C":"Correct selection.","D":"Incorrect because differing norms around gifts, labour, and environment are major global management challenges."}}},{"id":"P1_U6_MCQ_845","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_845","question":"Why do corporate boards appoint 'independent non-executive directors' (NEDs) as part of ethical corporate governance?","options":{"A":"To manage daily factory assembly lines and delivery routes.","B":"To approve every executive's personal holiday expenses without question.","C":"To keep the company's financial accounts hidden from shareholders.","D":"To provide objective external oversight, challenge executive decisions, prevent conflicts of interest, and ensure the board acts ethically in the long-term interests of shareholders and stakeholders."},"correctOption":"D","correctAnswer":"To provide objective external oversight, challenge executive decisions, prevent conflicts of interest, and ensure the board acts ethically in the long-term interests of shareholders and stakeholders.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because independent directors act as an internal check against executive self-interest, fraud, and short-termism.","distractor_reasons":{"A":"Incorrect because executive managers—not non-executive directors—run daily operations.","B":"Incorrect because NEDs scrutinise and restrain excessive executive perks.","C":"Incorrect because NEDs sit on audit committees to ensure financial transparency.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_846","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_846","question":"What is an ethical approach to 'debt collection' by banks, utilities, or buy-now-pay-later lenders?","options":{"A":"Identifying vulnerable or financially struggling customers early, freezing punitive penalty fees, and agreeing affordable, realistic repayment plans rather than using aggressive harassment.","B":"Sending threatening messages to customers' employers and neighbours to shame them.","C":"Adding hidden 200% daily late fees without notifying the borrower.","D":"Lending large sums knowingly to people who have zero ability to repay."},"correctOption":"A","correctAnswer":"Identifying vulnerable or financially struggling customers early, freezing punitive penalty fees, and agreeing affordable, realistic repayment plans rather than using aggressive harassment.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because responsible lending and compassionate arrears support protect vulnerable consumers while improving long-term debt recovery.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because public shaming and third-party harassment are unethical and unlawful.","C":"Incorrect because hidden punitive fees are predatory.","D":"Incorrect because irresponsible lending violates ethical credit standards."}}},{"id":"P1_U6_MCQ_847","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_847","question":"Why can 'short-termism' (judging managers purely on quarterly profit targets) encourage unethical behaviour?","options":{"A":"Because quarterly targets always reward long-term environmental restoration.","B":"Because intense pressure to hit immediate profit numbers can tempt managers to cut safety maintenance, mislead customers, pressure suppliers unfairly, or manipulate accounts.","C":"Because short-termism eliminates all pressure to earn profits.","D":"Because quarterly reporting is required only by non-profit charities."},"correctOption":"B","correctAnswer":"Because intense pressure to hit immediate profit numbers can tempt managers to cut safety maintenance, mislead customers, pressure suppliers unfairly, or manipulate accounts.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because linking bonuses solely to short-term financial metrics creates moral hazard and neglects long-term stakeholder trust.","distractor_reasons":{"A":"Incorrect because environmental investments take years to pay back and may look like costs in a single quarter.","B":"Correct selection.","C":"Incorrect because short-termism *intensifies* immediate profit pressure.","D":"Incorrect because listed public limited companies report quarterly or half-yearly results."}}},{"id":"P1_U6_MCQ_848","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_848","question":"How does fostering 'workplace diversity and inclusion' represent an ethical strength as well as a business advantage?","options":{"A":"It ensures all managers come from the exact same narrow background.","B":"It allows the business to pay different wages for the exact same job based on gender.","C":"It upholds fairness and equal opportunity for all individuals regardless of background while bringing varied perspectives, creativity, and wider customer understanding to the firm.","D":"It eliminates the need for fair recruitment interviews."},"correctOption":"C","correctAnswer":"It upholds fairness and equal opportunity for all individuals regardless of background while bringing varied perspectives, creativity, and wider customer understanding to the firm.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because inclusive workplaces respect human dignity and outperform homogeneous teams in innovation and market insight.","distractor_reasons":{"A":"Incorrect because diversity expands representation across backgrounds.","B":"Incorrect because equal pay for equal work is a core ethical and legal requirement.","C":"Correct selection.","D":"Incorrect because inclusive hiring uses structured, fair interviews to remove bias."}}},{"id":"P1_U6_MCQ_849","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_849","question":"What is a 'conflict of interest' in business ethics?","options":{"A":"Two competing supermarkets lowering their bread prices on the same day.","B":"An employee asking their manager for annual holiday leave.","C":"A customer returning a faulty pair of shoes for a refund.","D":"A situation where a manager's personal financial or family interest could improperly influence their professional decision—such as awarding a company contract to a relative's firm."},"correctOption":"D","correctAnswer":"A situation where a manager's personal financial or family interest could improperly influence their professional decision—such as awarding a company contract to a relative's firm.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ethical governance requires declaring and stepping aside from decisions where personal ties compromise objectivity.","distractor_reasons":{"A":"Incorrect because rival price cuts represent normal market competition.","B":"Incorrect because requesting leave is a routine HR procedure.","C":"Incorrect because returning faulty goods is a consumer statutory right.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_850","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_850","question":"Why is 'doing the minimum required by law' often insufficient for a business seeking a strong ethical reputation?","options":{"A":"Because laws often lag behind society's moral expectations and vary across countries, so stakeholders judge businesses on whether they act fairly and responsibly even when no law forces them to.","B":"Because obeying national laws is always unethical.","C":"Because consumers never care how workers or the environment are treated as long as no law is broken.","D":"Because legal compliance automatically guarantees maximum customer loyalty."},"correctOption":"A","correctAnswer":"Because laws often lag behind society's moral expectations and vary across countries, so stakeholders judge businesses on whether they act fairly and responsibly even when no law forces them to.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethics governs voluntary moral choices *above* the legal floor, especially in countries with weak statutory enforcement.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because obeying fair laws is the baseline foundation of ethical conduct.","C":"Incorrect because consumers regularly boycott firms over legal-but-unethical practices like tax loopholes or sweatshop wages.","D":"Incorrect because mere legal compliance is expected rather than admired."}}},{"id":"P1_U6_MCQ_851","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_851","question":"Why is a 'consumer boycott' generally much more effective against a well-known high-street fashion or coffee brand than against a business-to-business (B2B) industrial chemical manufacturer?","options":{"A":"Because B2B chemical manufacturers never sell products to other businesses.","B":"Because consumer-facing brands rely directly on mass retail shoppers and brand image, whereas ordinary shoppers do not buy B2B industrial chemicals directly.","C":"Because consumer boycotts are illegal against chemical companies.","D":"Because high-street coffee brands have zero competitors."},"correctOption":"B","correctAnswer":"Because consumer-facing brands rely directly on mass retail shoppers and brand image, whereas ordinary shoppers do not buy B2B industrial chemicals directly.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because direct retail visibility and close substitute brands make B2C firms immediately vulnerable to lost checkout sales.","distractor_reasons":{"A":"Incorrect because B2B firms sell inputs to other businesses rather than retail consumers.","B":"Correct selection.","C":"Incorrect because peaceful boycotts are legal, though shoppers cannot boycott a firm they never buy from directly.","D":"Incorrect because coffee and fashion retailers face intense competition, making switching easy for shoppers."}}},{"id":"P1_U6_MCQ_852","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_852","question":"How has the rise of social media transformed the campaigning power of small grassroots pressure groups?","options":{"A":"It has prevented small pressure groups from communicating with the public.","B":"It has forced pressure groups to spend millions of dollars on print newspapers before launching any campaign.","C":"It allows small groups to share videos, launch viral hashtags, and gather hundreds of thousands of online petition signatures almost instantly at very low cost.","D":"It has made businesses completely immune to public criticism."},"correctOption":"C","correctAnswer":"It allows small groups to share videos, launch viral hashtags, and gather hundreds of thousands of online petition signatures almost instantly at very low cost.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because digital virality lowers the financial barrier to organising mass public pressure and attracts mainstream news coverage.","distractor_reasons":{"A":"Incorrect because social media dramatically *expanded* public reach.","B":"Incorrect because social platforms allow free or low-cost organic mobilisation.","C":"Correct selection.","D":"Incorrect because real-time social media scrutiny makes corporate misconduct harder to hide."}}},{"id":"P1_U6_MCQ_853","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_853","question":"What is 'shareholder activism' as a tactic used by ethical and environmental pressure groups?","options":{"A":"Burning down a company's retail stores during a protest.","B":"Refusing to buy any shares in any public limited company.","C":"Stealing confidential product blueprints from a company's research lab.","D":"Buying shares in a targeted public company to gain legal voting rights, propose ethical board resolutions, and persuade large institutional investors to force policy changes."},"correctOption":"D","correctAnswer":"Buying shares in a targeted public company to gain legal voting rights, propose ethical board resolutions, and persuade large institutional investors to force policy changes.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shareholder activism uses internal corporate governance mechanisms to push directors toward sustainable reforms.","distractor_reasons":{"A":"Incorrect because arson is violent criminal destruction, not shareholder activism.","B":"Incorrect because shareholder activism requires *purchasing* shares to exercise ownership rights.","C":"Incorrect because stealing trade secrets is industrial espionage.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_854","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_854","question":"How do 'local community pressure groups' (often called NIMBY—Not In My Back Yard—or local resident action groups) influence business location decisions?","options":{"A":"By campaigning against proposed new factories, quarries, supermarkets, or warehouses near residential areas due to noise, traffic, and environmental concerns, pressuring local councils to refuse planning permission.","B":"By encouraging businesses to dump toxic waste inside local parks.","C":"By setting national income tax rates for the entire country.","D":"By banning all local residents from shopping in town centres."},"correctOption":"A","correctAnswer":"By campaigning against proposed new factories, quarries, supermarkets, or warehouses near residential areas due to noise, traffic, and environmental concerns, pressuring local councils to refuse planning permission.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because local resident groups mobilise voters and council objections that can block or force costly redesigns of site developments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because resident groups fight *against* local pollution.","C":"Incorrect because national tax rates are set by central government.","D":"Incorrect because local groups seek to protect community amenities."}}},{"id":"P1_U6_MCQ_855","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_855","question":"What is 'direct lobbying' of politicians and government departments by a pressure group?","options":{"A":"Organising a consumer boycott outside supermarket doors.","B":"Meeting with ministers, civil servants, and parliamentary committees to present research evidence and persuade them to pass stricter laws or taxes affecting businesses.","C":"Painting protest slogans on corporate delivery vans.","D":"Paying consumers cash to stop buying a rival's product."},"correctOption":"B","correctAnswer":"Meeting with ministers, civil servants, and parliamentary committees to present research evidence and persuade them to pass stricter laws or taxes affecting businesses.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because lobbying targets lawmakers directly so statutory regulation compels the entire industry to change.","distractor_reasons":{"A":"Incorrect because picketing shops is public consumer campaigning rather than parliamentary lobbying.","B":"Correct selection.","C":"Incorrect because graffiti is vandalism, not lobbying.","D":"Incorrect because lobbying involves persuading policymakers through arguments and data."}}},{"id":"P1_U6_MCQ_856","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_856","question":"Why do pressure groups often form 'coalitions' (alliances between multiple NGOs, unions, and community groups) when campaigning against a major multinational?","options":{"A":"Because each pressure group wants to reduce its total number of supporters.","B":"Because coalitions are legally exempt from obeying court orders.","C":"Because pooling expertise, funding, media contacts, and millions of combined members creates far greater political and public leverage than campaigning alone.","D":"Because multinational companies are legally required to obey any coalition immediately."},"correctOption":"C","correctAnswer":"Because pooling expertise, funding, media contacts, and millions of combined members creates far greater political and public leverage than campaigning alone.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because broad coalitions demonstrate wide societal consensus and amplify campaigning resources.","distractor_reasons":{"A":"Incorrect because coalitions *expand* total supporter reach.","B":"Incorrect because coalitions remain bound by national laws.","C":"Correct selection.","D":"Incorrect because companies respond to commercial and regulatory pressure rather than automatic legal compulsion from NGOs."}}},{"id":"P1_U6_MCQ_857","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_857","question":"How do 'public health pressure groups' influence food, beverage, and tobacco businesses?","options":{"A":"By campaigning for lower taxes on cigarettes and sugary drinks.","B":"By advising food companies to hide nutrition labels from packaging.","C":"By encouraging children to consume more high-caffeine energy drinks.","D":"By campaigning for sugar taxes, plain packaging, advertising bans, and clear traffic-light nutrition labels, pushing companies to reformulate healthier recipes."},"correctOption":"D","correctAnswer":"By campaigning for sugar taxes, plain packaging, advertising bans, and clear traffic-light nutrition labels, pushing companies to reformulate healthier recipes.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because health advocacy drives both regulatory restrictions and voluntary recipe reformulation (such as low-sugar beverages).","distractor_reasons":{"A":"Incorrect because health groups campaign for *higher* taxes on demerit goods like tobacco and sugar.","B":"Incorrect because health groups demand *clearer* front-of-pack nutrition labelling.","C":"Incorrect because health groups campaign to restrict energy drink sales to minors.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_858","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_858","question":"Why might a government reject the demands of an environmental pressure group opposing a major new industrial or mining project?","options":{"A":"Because the government prioritises macroeconomic objectives—such as creating thousands of local jobs, boosting GDP growth, and increasing export tax revenues—over environmental objections.","B":"Because environmental pressure groups never submit any arguments to governments.","C":"Because governments are legally forbidden from approving industrial projects.","D":"Because mining projects never create any employment or tax revenue."},"correctOption":"A","correctAnswer":"Because the government prioritises macroeconomic objectives—such as creating thousands of local jobs, boosting GDP growth, and increasing export tax revenues—over environmental objections.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because policymakers constantly weigh competing stakeholder goals, particularly economic growth and jobs versus ecological preservation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because environmental groups actively submit detailed objections.","C":"Incorrect because governments routinely approve projects after weighing economic and environmental trade-offs.","D":"Incorrect because large projects generate significant jobs and royalties."}}},{"id":"P1_U6_MCQ_859","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_859","question":"How can 'peaceful direct action' (such as sit-ins, peaceful blockades, or banner unfurling) disrupt a targeted business?","options":{"A":"By increasing daily factory output and lowering shipping costs.","B":"By temporarily halting store openings, construction work, or deliveries while generating dramatic news photos that pressure management to negotiate.","C":"By automatically transferring ownership of the company to the protesters.","D":"By lowering the business's insurance premiums."},"correctOption":"B","correctAnswer":"By temporarily halting store openings, construction work, or deliveries while generating dramatic news photos that pressure management to negotiate.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-violent physical disruption creates immediate operational delays alongside intense media visibility.","distractor_reasons":{"A":"Incorrect because blockades interrupt operations rather than boosting output.","B":"Correct selection.","C":"Incorrect because protests do not transfer legal share ownership.","D":"Incorrect because operational disruptions tend to raise security and insurance costs."}}},{"id":"P1_U6_MCQ_860","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_860","question":"What is a constructive 'crisis communication' response when a business faces valid criticism from a reputable pressure group?","options":{"A":"Attacking the pressure group with personal insults on social media while denying obvious facts.","B":"Deleting all customer comments and refusing to speak to journalists forever.","C":"Acknowledging the issue transparently, publishing an independent investigation, committing to measurable corrective targets with timelines, and engaging openly with stakeholders.","D":"Blaming junior factory workers for company-wide procurement policies."},"correctOption":"C","correctAnswer":"Acknowledging the issue transparently, publishing an independent investigation, committing to measurable corrective targets with timelines, and engaging openly with stakeholders.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because accountability, transparency, and verifiable reform rebuild stakeholder trust far faster than denial or hostility.","distractor_reasons":{"A":"Incorrect because aggressive denial inflames public anger and prolongs negative headlines.","B":"Incorrect because stonewalling creates a vacuum filled by critics' narratives.","C":"Correct selection.","D":"Incorrect because senior leadership must take responsibility for corporate policies."}}},{"id":"P1_U6_MCQ_861","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_861","question":"How do 'investigative reports and undercover exposés' published by pressure groups affect targeted businesses?","options":{"A":"They serve as free positive advertisements that boost share prices.","B":"They have no impact because journalists never read NGO reports.","C":"They exempt the company from government safety inspections.","D":"They provide concrete visual and documentary evidence of supply-chain abuses or pollution, triggering sudden share price drops, retail contract cancellations, and regulatory probes."},"correctOption":"D","correctAnswer":"They provide concrete visual and documentary evidence of supply-chain abuses or pollution, triggering sudden share price drops, retail contract cancellations, and regulatory probes.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because hard evidence from investigative NGOs makes corporate denial impossible and forces rapid supply-chain reform.","distractor_reasons":{"A":"Incorrect because exposés inflict severe reputational and share-price damage.","B":"Incorrect because major media outlets frequently headline credible NGO investigations.","C":"Incorrect because exposés typically *trigger* official regulatory inspections.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_862","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_862","question":"Why do some pressure groups use 'crowdfunding' platforms to finance their campaigns?","options":{"A":"To raise money from thousands of small individual donors so the group remains financially independent of corporations and governments and can fund legal challenges or media adverts.","B":"To sell shares on the New York Stock Exchange.","C":"To lend money to polluting oil companies.","D":"To avoid paying any staff or legal fees."},"correctOption":"A","correctAnswer":"To raise money from thousands of small individual donors so the group remains financially independent of corporations and governments and can fund legal challenges or media adverts.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because grassroots crowdfunding preserves independence and mobilises rapid financial backing for high-impact campaigns.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because non-profit pressure groups do not list shares on stock exchanges.","C":"Incorrect because pressure groups use funds for advocacy rather than corporate lending.","D":"Incorrect because crowdfunded money specifically pays for legal, research, and campaign costs."}}},{"id":"P1_U6_MCQ_863","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_863","question":"How can a business's 'share price' on the stock market be affected by a major pressure group campaign?","options":{"A":"Share prices always rise by 50% during a consumer boycott.","B":"Investors may sell shares due to fears of falling sales, legal fines, and permanent brand damage, causing the company's share price and market value to fall.","C":"Stock markets automatically freeze trading in any company criticised by an NGO.","D":"Shareholders receive double dividends whenever a protest occurs."},"correctOption":"B","correctAnswer":"Investors may sell shares due to fears of falling sales, legal fines, and permanent brand damage, causing the company's share price and market value to fall.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because financial markets discount future expected profits when reputational and regulatory risks rise.","distractor_reasons":{"A":"Incorrect because boycotts threaten revenue and normally depress share prices.","B":"Correct selection.","C":"Incorrect because stock markets remain open and reflect investor sentiment through price changes.","D":"Incorrect because lost sales threaten, rather than double, dividends."}}},{"id":"P1_U6_MCQ_864","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_864","question":"Why are 'international pressure groups' (such as Greenpeace, Amnesty International, or Oxfam) particularly influential on multinational corporations?","options":{"A":"Because they operate in only one small village.","B":"Because they own 51% of shares in every multinational corporation.","C":"Because their global networks can expose abuses in a remote developing-country factory and simultaneously organise consumer boycotts and media pressure across the MNC's wealthy home markets.","D":"Because they control international customs tariffs."},"correctOption":"C","correctAnswer":"Because their global networks can expose abuses in a remote developing-country factory and simultaneously organise consumer boycotts and media pressure across the MNC's wealthy home markets.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because global NGOs bridge the geographic gap between remote supply-chain sites and western retail shoppers.","distractor_reasons":{"A":"Incorrect because international NGOs operate across dozens of countries.","B":"Incorrect because NGOs are independent advocacy organisations, not majority shareholders.","C":"Correct selection.","D":"Incorrect because national governments set customs tariffs."}}},{"id":"P1_U6_MCQ_865","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_865","question":"What is 'proactive CSR' as a strategy to prevent a business from becoming a pressure group target in the first place?","options":{"A":"Waiting until a major scandal occurs before making any ethical improvements.","B":"Hiring private detectives to spy on peaceful environmental charities.","C":"Reducing product safety testing to cut operating expenses.","D":"Voluntarily adopting high ethical, labour, and environmental standards early—before protests or laws force change—turning responsibility into a competitive advantage."},"correctOption":"D","correctAnswer":"Voluntarily adopting high ethical, labour, and environmental standards early—before protests or laws force change—turning responsibility into a competitive advantage.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because proactive leaders anticipate stakeholder expectations and build resilient, admired brands rather than reacting defensively to crises.","distractor_reasons":{"A":"Incorrect because waiting for a scandal describes *reactive* crisis management.","B":"Incorrect because spying on charities is unethical and damages reputation.","C":"Incorrect because cutting safety invites scandals and boycotts.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_866","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_866","question":"Why is the 'availability of close substitutes' critical to the success of a pressure group's consumer boycott?","options":{"A":"If consumers can easily switch to an equally affordable rival brand without inconvenience, boycott participation is high; if the targeted firm is a monopoly selling an essential utility, shoppers struggle to boycott it.","B":"If there are no substitutes, consumers always stop using electricity and water permanently.","C":"Substitutes make boycotts impossible because shoppers become confused.","D":"Monopolies are always easiest to boycott because consumers have zero alternatives."},"correctOption":"A","correctAnswer":"If consumers can easily switch to an equally affordable rival brand without inconvenience, boycott participation is high; if the targeted firm is a monopoly selling an essential utility, shoppers struggle to boycott it.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because low switching costs enable ordinary consumers to translate moral sympathy into sustained purchasing changes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because households cannot stop using essential monopoly utilities.","C":"Incorrect because clear ethical substitutes *facilitate* consumer switching.","D":"Incorrect because lack of alternatives makes boycotting a monopoly very difficult."}}},{"id":"P1_U6_MCQ_867","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_867","question":"How do 'business trade associations' (such as a Confederation of Industry or Chamber of Commerce) operate as sectional pressure groups?","options":{"A":"By campaigning for higher corporation taxes and stricter red tape on their own members.","B":"By representing member businesses collectively to lobby governments for lower business taxes, deregulation, better infrastructure, and supportive trade policies.","C":"By organising strikes against private employers.","D":"By boycotting all private-sector products."},"correctOption":"B","correctAnswer":"By representing member businesses collectively to lobby governments for lower business taxes, deregulation, better infrastructure, and supportive trade policies.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because business associations are powerful insider sectional groups advocating for a favourable commercial climate.","distractor_reasons":{"A":"Incorrect because business associations lobby *against* heavy taxes and excessive regulation.","B":"Correct selection.","C":"Incorrect because trade unions, not business associations, organise worker strikes.","D":"Incorrect because business associations promote commercial enterprise."}}},{"id":"P1_U6_MCQ_868","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_868","question":"How can pressure groups influence 'bank lending and institutional investment' policies toward polluting industries?","options":{"A":"By forcing central banks to print unlimited money for coal mines.","B":"By banning pension funds from investing in renewable energy.","C":"By campaigning outside major banks and pension funds to adopt ethical lending criteria, starving controversial projects (such as Arctic oil drilling) of finance and insurance.","D":"By guaranteeing zero interest rates on loans for deforestation projects."},"correctOption":"C","correctAnswer":"By campaigning outside major banks and pension funds to adopt ethical lending criteria, starving controversial projects (such as Arctic oil drilling) of finance and insurance.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because targeting the financial supply chain raises the cost of capital for environmentally or socially controversial ventures.","distractor_reasons":{"A":"Incorrect because campaigns seek to *end* financing for coal projects.","B":"Incorrect because campaigns encourage pension funds to *increase* green investments.","C":"Correct selection.","D":"Incorrect because campaigns pressure lenders to withdraw funding from deforestation."}}},{"id":"P1_U6_MCQ_869","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_869","question":"Why do pressure groups often publish 'ethical league tables' or 'scorecards' ranking major brands in an industry?","options":{"A":"To hide which companies are performing well on sustainability.","B":"To calculate companies' annual Value Added Tax liabilities.","C":"To exempt low-scoring companies from consumer criticism.","D":"To create transparent peer competition—praising top-ranked ethical leaders while publicly naming and shaming laggards at the bottom so rivals race to improve."},"correctOption":"D","correctAnswer":"To create transparent peer competition—praising top-ranked ethical leaders while publicly naming and shaming laggards at the bottom so rivals race to improve.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because comparative scorecards give shoppers simple buying guidance and motivate laggard brands to catch up.","distractor_reasons":{"A":"Incorrect because scorecards *publicise* top ethical performers.","B":"Incorrect because scorecards evaluate ethical/environmental criteria, not VAT.","C":"Incorrect because low-scoring firms face heightened public pressure to reform.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_870","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_870","question":"How can a pressure group campaign create long-term 'industry-wide standard shifts' even after initial media headlines fade?","options":{"A":"By embedding ethical expectations into consumer habits, retail procurement rules, and government legislation so responsible practices become the permanent new normal.","B":"By ensuring all businesses return to polluting practices as soon as cameras leave.","C":"By banning all new entrepreneurs from entering the industry.","D":"By eliminating all consumer protection laws."},"correctOption":"A","correctAnswer":"By embedding ethical expectations into consumer habits, retail procurement rules, and government legislation so responsible practices become the permanent new normal.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lasting institutional and regulatory changes (such as cage-free eggs, dolphin-safe tuna, or carrier bag charges) permanently reshape industry norms.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lasting regulatory and procurement rules lock in improvements.","C":"Incorrect because ethical standards encourage innovative new entrants.","D":"Incorrect because advocacy strengthens rather than removes consumer protections."}}},{"id":"P1_U6_MCQ_871","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_871","question":"Why might a business choose to join a 'multi-stakeholder initiative' (MSI) alongside NGOs, trade unions, and competitors?","options":{"A":"To fix retail prices illegally across the industry.","B":"To tackle complex shared industry problems (such as deforestation or garment factory safety) collaboratively, sharing audit costs and preventing any single firm from being undercut on ethics.","C":"To abolish all workplace safety inspections.","D":"To ensure that NGOs never criticise any member company again regardless of misconduct."},"correctOption":"B","correctAnswer":"To tackle complex shared industry problems (such as deforestation or garment factory safety) collaboratively, sharing audit costs and preventing any single firm from being undercut on ethics.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because collective sector-wide standards level the playing field and solve systemic supply-chain challenges no single firm can fix alone.","distractor_reasons":{"A":"Incorrect because price-fixing cartels are illegal and unrelated to ethical MSIs.","B":"Correct selection.","C":"Incorrect because MSIs *strengthen* independent factory and environmental inspections.","D":"Incorrect because NGOs continue holding member firms accountable to agreed commitments."}}},{"id":"P1_U6_MCQ_872","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_872","question":"What is the main difference between how a pressure group influences a business directly versus indirectly?","options":{"A":"Direct influence involves passing laws in Parliament, whereas indirect influence involves boycotting shops.","B":"There is no difference between direct and indirect pressure group influence.","C":"Direct influence targets the business's sales and reputation immediately (through boycotts, pickets, and media campaigns), whereas indirect influence lobbies governments to pass laws and taxes that compel businesses to change.","D":"Direct influence applies only to charities, whereas indirect influence applies only to sports clubs."},"correctOption":"C","correctAnswer":"Direct influence targets the business's sales and reputation immediately (through boycotts, pickets, and media campaigns), whereas indirect influence lobbies governments to pass laws and taxes that compel businesses to change.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because pressure groups pursue both market pressure against firms and political pressure on lawmakers.","distractor_reasons":{"A":"Incorrect because this reverses direct market pressure and indirect legislative lobbying.","B":"Incorrect because the two channels operate through different mechanisms (consumers vs government).","C":"Correct selection.","D":"Incorrect because both channels target commercial businesses."}}},{"id":"P1_U6_MCQ_873","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_873","question":"Why do 'animal welfare pressure groups' often target supermarkets and restaurant chains rather than thousands of individual farms?","options":{"A":"Because farms never raise animals.","B":"Because supermarkets have zero influence over how farmers treat livestock.","C":"Because supermarkets are legally prohibited from selling meat or dairy products.","D":"Because a handful of major supermarkets and restaurant chains hold huge buyer power and can instantly enforce higher animal-welfare standards across thousands of supplier farms."},"correctOption":"D","correctAnswer":"Because a handful of major supermarkets and restaurant chains hold huge buyer power and can instantly enforce higher animal-welfare standards across thousands of supplier farms.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because targeting high-visibility retail gatekeepers creates rapid cascade effects throughout agricultural supply chains.","distractor_reasons":{"A":"Incorrect because farms produce livestock and dairy products.","B":"Incorrect because supermarkets dictate strict procurement specifications to farm suppliers.","C":"Incorrect because supermarkets are the primary retail sellers of animal products.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_874","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_874","question":"How can a business measure whether its response to a pressure group campaign has successfully restored stakeholder trust?","options":{"A":"By tracking recovering sales revenues, improved social media sentiment, positive third-party NGO audit scores, and stable employee retention.","B":"By ignoring all customer feedback and cancelling all sustainability audits.","C":"By raising product prices by 50% without improving quality.","D":"By refusing to publish any annual reports."},"correctOption":"A","correctAnswer":"By tracking recovering sales revenues, improved social media sentiment, positive third-party NGO audit scores, and stable employee retention.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because combining commercial recovery metrics with independent ethical verification confirms genuine reputational repair.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ignoring feedback prevents measuring trust recovery.","C":"Incorrect because arbitrary price hikes alienate customers further.","D":"Incorrect because transparency, not secrecy, restores trust."}}},{"id":"P1_U6_MCQ_875","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_875","question":"When comparing consumer boycotts with government legislation as methods of changing business behaviour, which evaluation is most accurate?","options":{"A":"Consumer boycotts always force every single business in an industry to obey instantly without exception.","B":"Consumer boycotts can generate rapid publicity and market pressure, but their impact fades if shoppers lose interest or lack cheap alternatives—whereas government legislation permanently binds every business in the market equally.","C":"Government legislation is voluntary and businesses can freely choose to ignore laws.","D":"Neither boycotts nor government legislation ever affects business decisions."},"correctOption":"B","correctAnswer":"Consumer boycotts can generate rapid publicity and market pressure, but their impact fades if shoppers lose interest or lack cheap alternatives—whereas government legislation permanently binds every business in the market equally.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because boycotts rely on voluntary, often temporary consumer action, whereas statutory laws enforce uniform, permanent compliance across all rivals.","distractor_reasons":{"A":"Incorrect because boycotts rarely achieve 100% participation across an entire sector.","B":"Correct selection.","C":"Incorrect because legislation is legally binding and backed by state penalties.","D":"Incorrect because both forces regularly reshape corporate strategy and operations."}}},{"id":"P1_U6_MCQ_876","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_876","question":"What does Gross Domestic Product (GDP) measure in an economy?","options":{"A":"The total value of goods and services produced within a country over a given period of time, usually one year.","B":"The total amount of tax collected by the government from private businesses.","C":"The average price level of everyday household groceries.","D":"The total value of foreign currency held by commercial banks."},"correctOption":"A","correctAnswer":"The total value of goods and services produced within a country over a given period of time, usually one year.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because GDP is the standard syllabus measure of national output and economic activity over a year.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax receipts represent government fiscal revenue, not total national output.","C":"Incorrect because the average price level of consumer goods is measured by the Consumer Price Index (CPI).","D":"Incorrect because foreign currency holdings are foreign exchange reserves, not GDP."}}},{"id":"P1_U6_MCQ_877","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_877","question":"Which characteristic best describes the 'growth' stage of the business cycle?","options":{"A":"Falling GDP, widespread business failures, and rapidly rising unemployment.","B":"Rising GDP, increasing consumer spending, falling unemployment, and growing business confidence and investment.","C":"Extremely high inflation caused by severe shortages of skilled workers and raw materials.","D":"Two consecutive quarters of declining national output."},"correctOption":"B","correctAnswer":"Rising GDP, increasing consumer spending, falling unemployment, and growing business confidence and investment.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because during the growth stage, output expands steadily, incomes rise, and firms invest to meet higher demand.","distractor_reasons":{"A":"Incorrect because falling GDP and business failures describe a slump.","B":"Correct selection.","C":"Incorrect because overheating capacity and severe bottlenecks characterise the peak of a boom.","D":"Incorrect because two consecutive quarters of falling GDP defines a recession."}}},{"id":"P1_U6_MCQ_878","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_878","question":"How is an economic 'recession' defined in the Cambridge IGCSE Business Studies syllabus?","options":{"A":"A period of rapid GDP expansion accompanied by rising wages.","B":"A prolonged, severe collapse in output lasting several years with mass unemployment.","C":"A period when Gross Domestic Product (GDP) falls, reducing consumer spending, business sales, and profits.","D":"A period when inflation remains steady at 2% per year."},"correctOption":"C","correctAnswer":"A period when Gross Domestic Product (GDP) falls, reducing consumer spending, business sales, and profits.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a recession occurs when national output contracts, leading to falling demand and rising unemployment.","distractor_reasons":{"A":"Incorrect because rapid expansion describes growth or a boom.","B":"Incorrect because a prolonged, extreme downturn defines a *slump*.","C":"Correct selection.","D":"Incorrect because steady 2% inflation represents macroeconomic price stability."}}},{"id":"P1_U6_MCQ_879","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_879","question":"Which combination of conditions typically occurs during a 'slump' in the business cycle?","options":{"A":"Full employment, high inflation, and rising business profits.","B":"Rapidly rising GDP and widespread shortages of factory workers.","C":"Rising interest rates to cool excessive consumer borrowing.","D":"Very low consumer demand, high unemployment, many business closures, and very low business confidence."},"correctOption":"D","correctAnswer":"Very low consumer demand, high unemployment, many business closures, and very low business confidence.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a slump is the lowest trough of the business cycle where prolonged weak demand forces firms to cut output or close.","distractor_reasons":{"A":"Incorrect because full employment and high inflation occur during a boom.","B":"Incorrect because rising GDP and labour shortages occur during a boom.","C":"Incorrect because central banks typically *cut* interest rates during a slump to stimulate spending.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_880","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_880","question":"Why do businesses often face higher wage costs during the 'boom' stage of the business cycle?","options":{"A":"Low unemployment creates shortages of skilled workers, forcing employers to offer higher pay to recruit and retain staff.","B":"Governments double corporation tax rates during every boom.","C":"Consumer demand collapses, forcing businesses to pay redundancy bonuses.","D":"High unemployment allows workers to demand triple wages."},"correctOption":"A","correctAnswer":"Low unemployment creates shortages of skilled workers, forcing employers to offer higher pay to recruit and retain staff.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tight labour markets during a boom increase worker bargaining power and push up wage rates.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because corporation tax is a tax on profits, not a wage cost.","C":"Incorrect because consumer demand is at its highest during a boom.","D":"Incorrect because booms are characterised by *low*, not high, unemployment."}}},{"id":"P1_U6_MCQ_881","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_881","question":"How can rising unemployment in an economy benefit a business that is looking to expand?","options":{"A":"It automatically increases household spending on luxury holidays.","B":"There is a larger pool of available job applicants, making it easier to recruit staff without having to offer excessive wage increases.","C":"It lowers the business's corporation tax rate to zero.","D":"It eliminates all competition from overseas businesses."},"correctOption":"B","correctAnswer":"There is a larger pool of available job applicants, making it easier to recruit staff without having to offer excessive wage increases.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher unemployment increases labour supply, reducing recruitment difficulties and wage inflation pressure.","distractor_reasons":{"A":"Incorrect because higher unemployment reduces household incomes and luxury spending.","B":"Correct selection.","C":"Incorrect because unemployment levels do not automatically waive corporate tax.","D":"Incorrect because foreign competitors remain active in the market."}}},{"id":"P1_U6_MCQ_882","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_882","question":"What is the main negative impact of rising unemployment on most consumer-facing businesses?","options":{"A":"It becomes impossible to find any workers to fill vacant jobs.","B":"Government interest rates rise sharply to 20%.","C":"Total household disposable income falls, reducing consumer demand and lowering business sales revenues.","D":"Raw material suppliers lower their prices to zero."},"correctOption":"C","correctAnswer":"Total household disposable income falls, reducing consumer demand and lowering business sales revenues.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unemployed workers lose wage income and employed workers often save more out of caution, shrinking retail demand.","distractor_reasons":{"A":"Incorrect because higher unemployment makes recruiting *easier*, not impossible.","B":"Incorrect because governments usually *cut* interest rates when unemployment rises.","C":"Correct selection.","D":"Incorrect because suppliers still charge market prices for inputs."}}},{"id":"P1_U6_MCQ_883","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_883","question":"What is meant by 'inflation'?","options":{"A":"A sustained fall in the general price level of goods and services.","B":"An increase in the external value of a country's currency.","C":"A rise in the rate of corporation tax paid by limited companies.","D":"An increase in the general price level of goods and services in an economy over time, which reduces the purchasing power of money."},"correctOption":"D","correctAnswer":"An increase in the general price level of goods and services in an economy over time, which reduces the purchasing power of money.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because inflation means average prices rise across the economy, so each unit of currency buys fewer goods.","distractor_reasons":{"A":"Incorrect because a sustained fall in average prices is *deflation*.","B":"Incorrect because a rise in currency value is *appreciation*.","C":"Incorrect because a tax increase is a fiscal policy change, not inflation.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_884","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_884","question":"How does high inflation in Country X affect a business in Country X that exports furniture to Country Y (where inflation is low)?","options":{"A":"Country X's furniture becomes more expensive relative to Country Y's products, reducing Country X's export competitiveness and overseas sales.","B":"Country X's furniture automatically becomes cheaper in Country Y.","C":"Country X's exporter pays zero shipping and customs duties.","D":"Inflation has no effect on business costs or export selling prices."},"correctOption":"A","correctAnswer":"Country X's furniture becomes more expensive relative to Country Y's products, reducing Country X's export competitiveness and overseas sales.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher domestic inflation pushes up wages and material costs, forcing exporters to raise prices and lose international price competitiveness.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rising domestic costs make exports *more expensive*, not cheaper.","C":"Incorrect because logistics and tariff costs are unaffected by domestic inflation.","D":"Incorrect because inflation directly raises input costs and selling prices."}}},{"id":"P1_U6_MCQ_885","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_885","question":"Why do workers often demand higher wages during periods of high inflation?","options":{"A":"Because higher prices reduce the real value of their existing wages, lowering their standard of living unless pay rises to match inflation.","B":"Because income tax rates fall to zero during inflation.","C":"Because businesses make zero profits during inflation.","D":"Because high inflation makes all household goods cheaper."},"correctOption":"A","correctAnswer":"Because higher prices reduce the real value of their existing wages, lowering their standard of living unless pay rises to match inflation.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising living costs erode real purchasing power, leading employees and trade unions to press for cost-of-living pay increases.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because income tax rates are not abolished during inflation.","C":"Incorrect because wage demands are driven by workers' rising living expenses.","D":"Incorrect because inflation means household goods are becoming *more expensive*."}}},{"id":"P1_U6_MCQ_886","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_886","question":"Which set of four outcomes represents the main economic objectives of most governments?","options":{"A":"High inflation, high unemployment, falling GDP, and a large balance of payments deficit.","B":"Low inflation, low unemployment, economic growth (increasing GDP), and balance of payments stability.","C":"Zero exports, maximum tax rates, falling GDP, and high interest rates.","D":"Complete ban on imports, zero economic growth, and fixed wages."},"correctOption":"B","correctAnswer":"Low inflation, low unemployment, economic growth (increasing GDP), and balance of payments stability.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Cambridge IGCSE 0264 identifies low inflation, low unemployment, economic growth, and a stable balance of payments as the four core government economic objectives.","distractor_reasons":{"A":"Incorrect because these are economic problems that governments aim to avoid.","B":"Correct selection.","C":"Incorrect because these policies would harm living standards and international trade.","D":"Incorrect because modern economies seek steady growth and balanced international trade."}}},{"id":"P1_U6_MCQ_887","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_887","question":"What is meant by a 'balance of payments' surplus on the current account?","options":{"A":"Government tax revenue is greater than government spending.","B":"The value of a country's imports is greater than the value of its exports.","C":"The total value of a country's exports of goods and services exceeds the total value of its imports.","D":"Commercial banks hold more customer deposits than loans."},"correctOption":"C","correctAnswer":"The total value of a country's exports of goods and services exceeds the total value of its imports.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a current account surplus occurs when export earnings flowing into the country exceed import spending flowing out.","distractor_reasons":{"A":"Incorrect because tax revenue exceeding public expenditure is a government *budget surplus*.","B":"Incorrect because imports exceeding exports defines a balance of payments *deficit*.","C":"Correct selection.","D":"Incorrect because commercial bank deposit-to-loan ratios do not define the balance of payments."}}},{"id":"P1_U6_MCQ_888","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_888","question":"Which policy tool is an example of government 'fiscal policy'?","options":{"A":"Changing the central bank's base interest rate.","B":"Allowing the exchange rate to float freely on currency markets.","C":"Banning private companies from advertising on television.","D":"Changing rates of income tax, corporation tax, or VAT, and altering levels of government spending."},"correctOption":"D","correctAnswer":"Changing rates of income tax, corporation tax, or VAT, and altering levels of government spending.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fiscal policy involves government decisions on taxation and public expenditure.","distractor_reasons":{"A":"Incorrect because changing interest rates is *monetary policy*.","B":"Incorrect because exchange rate management is currency/monetary policy.","C":"Incorrect because advertising restrictions are legal/regulatory controls.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_889","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_889","question":"How does an increase in personal 'income tax' affect businesses in an economy?","options":{"A":"Consumers have less disposable income after tax, which reduces spending on goods and services—especially non-essential luxury items.","B":"Companies immediately pay lower corporation tax on their net profits.","C":"Exported goods become cheaper in foreign currencies.","D":"Businesses can borrow money from banks at 0% interest."},"correctOption":"A","correctAnswer":"Consumers have less disposable income after tax, which reduces spending on goods and services—especially non-essential luxury items.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher income tax reduces household take-home pay, lowering consumer demand across retail and service sectors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because personal income tax applies to individual earnings, not company profits.","C":"Incorrect because income tax does not directly alter exchange rates or export prices.","D":"Incorrect because income tax changes do not eliminate bank loan interest."}}},{"id":"P1_U6_MCQ_890","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_890","question":"How does a reduction in 'corporation tax' (profits tax) affect a private or public limited company?","options":{"A":"It raises the retail price of products sold in supermarkets.","B":"It leaves the company with higher profit after tax, providing more retained profit for investment and more funds for shareholder dividends.","C":"It increases employees' personal income tax deductions.","D":"It forces the company to cut its workforce immediately."},"correctOption":"B","correctAnswer":"It leaves the company with higher profit after tax, providing more retained profit for investment and more funds for shareholder dividends.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because corporation tax is levied directly on company profits; cutting it boosts internal finance available for growth.","distractor_reasons":{"A":"Incorrect because retail sales taxes are indirect taxes like VAT, not corporation tax.","B":"Correct selection.","C":"Incorrect because employee payroll deductions come from personal income tax.","D":"Incorrect because lower profit taxes encourage investment and hiring rather than redundancies."}}},{"id":"P1_U6_MCQ_891","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_891","question":"What is an 'indirect tax' such as Value Added Tax (VAT) or goods and services tax (GST)?","options":{"A":"A tax deducted directly from a worker's monthly salary.","B":"A tax paid solely on the value of a company's factory buildings.","C":"A tax added to the price of goods and services when they are purchased by consumers, collected by businesses and passed on to the government.","D":"A grant paid by the government to help new startups."},"correctOption":"C","correctAnswer":"A tax added to the price of goods and services when they are purchased by consumers, collected by businesses and passed on to the government.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because indirect taxes are levied on expenditure rather than income and are included in retail selling prices.","distractor_reasons":{"A":"Incorrect because tax deducted from salary is *direct* personal income tax.","B":"Incorrect because tax on property value is property tax/business rates.","C":"Correct selection.","D":"Incorrect because a grant is government financial support, not a tax."}}},{"id":"P1_U6_MCQ_892","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_892","question":"How can an increase in 'government spending' on roads, hospitals, and schools benefit private businesses?","options":{"A":"It reduces total demand in the economy and causes a slump.","B":"It prevents private businesses from hiring skilled graduates.","C":"It eliminates all competition between private companies.","D":"Construction and supply firms receive direct government contracts, while employees in public services spend their wages at private shops and businesses."},"correctOption":"D","correctAnswer":"Construction and supply firms receive direct government contracts, while employees in public services spend their wages at private shops and businesses.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because higher public spending injects demand into the economy, creating direct B2G orders and indirect consumer spending.","distractor_reasons":{"A":"Incorrect because higher government spending *increases* aggregate demand.","B":"Incorrect because spending on education actually *increases* the supply of skilled graduates.","C":"Incorrect because private firms still compete for both public contracts and private customers.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_893","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_893","question":"What is meant by an 'interest rate' in the economy?","options":{"A":"The cost of borrowing money and the reward for saving money, expressed as a percentage per year.","B":"The percentage of company profit paid to the government as corporation tax.","C":"The rate at which consumer prices rise each year.","D":"The price of one currency expressed in terms of another currency."},"correctOption":"A","correctAnswer":"The cost of borrowing money and the reward for saving money, expressed as a percentage per year.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because interest rates determine both the expense of loans/overdrafts and the return earned on bank deposits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax on profits is the corporation tax rate.","C":"Incorrect because the rate of price increases is the inflation rate.","D":"Incorrect because the relative price of currencies is the exchange rate."}}},{"id":"P1_U6_MCQ_894","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_894","question":"How does a significant rise in 'interest rates' affect businesses that have large variable-rate bank loans?","options":{"A":"Their monthly loan interest repayments fall, increasing net profit.","B":"Their loan interest expenses increase, raising fixed overhead costs and reducing net profit.","C":"Their bank loans are automatically cancelled by the central bank.","D":"Their customers receive higher disposable incomes to spend in shops."},"correctOption":"B","correctAnswer":"Their loan interest expenses increase, raising fixed overhead costs and reducing net profit.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher interest rates directly raise debt-servicing costs for leveraged businesses.","distractor_reasons":{"A":"Incorrect because higher interest rates *increase*, not lower, loan repayments.","B":"Correct selection.","C":"Incorrect because loans remain payable at the higher interest rate.","D":"Incorrect because higher interest rates raise mortgage payments and *reduce* household disposable income."}}},{"id":"P1_U6_MCQ_895","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_895","question":"Why do higher interest rates reduce consumer spending in an economy?","options":{"A":"Because higher interest rates lower personal income tax rates.","B":"Because higher interest rates make all retail goods completely free.","C":"Because borrowing on credit cards and loans becomes more expensive, mortgage repayments rise (leaving less disposable income), and saving in banks becomes more attractive than spending.","D":"Because higher interest rates cause rapid deflation in food prices."},"correctOption":"C","correctAnswer":"Because borrowing on credit cards and loans becomes more expensive, mortgage repayments rise (leaving less disposable income), and saving in banks becomes more attractive than spending.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because higher interest rates simultaneously penalise credit-financed spending, squeeze mortgage holders, and reward saving.","distractor_reasons":{"A":"Incorrect because interest rates are monetary policy and do not change income tax.","B":"Incorrect because retail goods still carry full market prices.","C":"Correct selection.","D":"Incorrect because higher rates slow demand growth rather than instantly causing food deflation."}}},{"id":"P1_U6_MCQ_896","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_896","question":"How might a manufacturing business respond appropriately to a sharp rise in interest rates?","options":{"A":"Take out large new bank loans to fund high-risk speculative expansion.","B":"Double its selling prices immediately regardless of competitors.","C":"Increase its inventory levels using an expensive bank overdraft.","D":"Delay borrowing for major capital expansion, use retained profits instead of bank loans, and focus on paying down existing expensive debt."},"correctOption":"D","correctAnswer":"Delay borrowing for major capital expansion, use retained profits instead of bank loans, and focus on paying down existing expensive debt.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shifting from debt finance to internal retained profit and postponing non-urgent borrowing protects cash flow and profitability.","distractor_reasons":{"A":"Incorrect because borrowing heavily when interest rates surge increases financial risk and interest expenses.","B":"Incorrect because raising prices sharply when consumer demand is cooling would cause a severe loss of sales.","C":"Incorrect because funding extra stock via an overdraft incurs higher interest charges.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_897","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_897","question":"How might a supermarket chain respond to an economic recession when household incomes are falling?","options":{"A":"Expand its range of affordable 'own-label' value products, offer price promotions, and focus on cost control to retain price-sensitive shoppers.","B":"Stop selling basic groceries and sell only imported luxury caviar.","C":"Raise prices on all staple foods by 30%.","D":"Ignore falling sales and increase head-office luxury spending."},"correctOption":"A","correctAnswer":"Expand its range of affordable 'own-label' value products, offer price promotions, and focus on cost control to retain price-sensitive shoppers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shoppers trade down to value ranges during downturns, allowing supermarkets to maintain volume and market share.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because luxury demand falls sharply in a recession while basic food demand remains steady.","C":"Incorrect because large price hikes during a recession would drive customers to discount rivals.","D":"Incorrect because cost control is vital when profit margins come under pressure."}}},{"id":"P1_U6_MCQ_898","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_898","question":"Why do governments sometimes use 'contractionary' policies (such as raising interest rates or increasing taxes) during an economic boom?","options":{"A":"To increase unemployment to 50%.","B":"To slow down excessive total spending and bring high inflation back under control.","C":"To force all domestic businesses into bankruptcy.","D":"To double the rate of consumer price inflation."},"correctOption":"B","correctAnswer":"To slow down excessive total spending and bring high inflation back under control.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cooling overheated demand prevents runaway inflation and an unsustainable boom-and-bust cycle.","distractor_reasons":{"A":"Incorrect because governments aim for low unemployment, not mass joblessness.","B":"Correct selection.","C":"Incorrect because the goal is sustainable economic stability, not business collapse.","D":"Incorrect because raising rates and taxes *reduces*, rather than doubles, inflation."}}},{"id":"P1_U6_MCQ_899","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_899","question":"How can a business respond constructively to an increase in Value Added Tax (VAT) on its products?","options":{"A":"Refuse to collect VAT and ignore tax authorities.","B":"Close down all profitable branches immediately.","C":"Look for ways to cut internal production costs so it can absorb part of the tax increase rather than passing the full price rise onto price-sensitive customers.","D":"Stop keeping any accounting records of sales."},"correctOption":"C","correctAnswer":"Look for ways to cut internal production costs so it can absorb part of the tax increase rather than passing the full price rise onto price-sensitive customers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because improving efficiency helps protect retail competitiveness and sales volume when indirect taxes rise.","distractor_reasons":{"A":"Incorrect because failing to collect and remit VAT is illegal tax evasion.","B":"Incorrect because profitable branches should be kept open and made more cost-efficient.","C":"Correct selection.","D":"Incorrect because proper financial record-keeping is a legal requirement."}}},{"id":"P1_U6_MCQ_900","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_900","question":"Which business is most likely to see its sales *increase* during an economic recession?","options":{"A":"A luxury five-star cruise holiday operator.","B":"A high-end designer jewellery boutique.","C":"A sports car dealership.","D":"A discount budget supermarket chain selling low-cost everyday essentials."},"correctOption":"D","correctAnswer":"A discount budget supermarket chain selling low-cost everyday essentials.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because budget retailers gain customers who switch away from expensive supermarkets when disposable incomes fall.","distractor_reasons":{"A":"Incorrect because luxury cruises are income-elastic and are among the first expenses households cut.","B":"Incorrect because designer jewellery is a non-essential luxury purchase.","C":"Incorrect because expensive cars are postponed during recessions.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_901","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_901","question":"How does a government cut in 'interest rates' encourage businesses to invest in new machinery and factories?","options":{"A":"It lowers the cost of borrowing funds from banks and reduces the interest earned on idle cash deposits, making capital investment projects more profitable.","B":"It increases corporation tax rates on new machinery.","C":"It forces consumers to stop buying goods.","D":"It makes imported machinery twice as expensive."},"correctOption":"A","correctAnswer":"It lowers the cost of borrowing funds from banks and reduces the interest earned on idle cash deposits, making capital investment projects more profitable.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lower loan interest reduces project financing costs while lower deposit returns encourage firms to put cash to productive use.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because interest rate cuts are monetary policy and do not raise corporation tax.","C":"Incorrect because rate cuts stimulate, rather than reduce, consumer spending.","D":"Incorrect because rate cuts do not directly double import prices."}}},{"id":"P1_U6_MCQ_902","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_902","question":"Why might a business respond to rising domestic inflation and higher domestic wage costs by investing in automated machinery?","options":{"A":"Because automated machinery increases the number of manual workers needed per unit.","B":"Because automation increases labour productivity and reduces unit labour costs over time, helping the business keep prices competitive.","C":"Because automation guarantees zero electricity costs.","D":"Because governments ban businesses from hiring workers during inflation."},"correctOption":"B","correctAnswer":"Because automation increases labour productivity and reduces unit labour costs over time, helping the business keep prices competitive.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because substituting capital equipment for expensive labour controls unit production costs when wages rise.","distractor_reasons":{"A":"Incorrect because automation *reduces* manual labour per unit of output.","B":"Correct selection.","C":"Incorrect because automated factories still pay electricity bills.","D":"Incorrect because hiring workers remains completely legal."}}},{"id":"P1_U6_MCQ_903","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_903","question":"What is a 'balance of payments deficit' on the current account?","options":{"A":"When a business's total expenses exceed its sales revenue.","B":"When government spending exceeds tax revenue.","C":"When the value of a country's imports of goods and services is greater than the value of its exports.","D":"When a country exports more goods than it imports."},"correctOption":"C","correctAnswer":"When the value of a country's imports of goods and services is greater than the value of its exports.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a current account deficit means more money is leaving the country to pay for imports than is entering from export sales.","distractor_reasons":{"A":"Incorrect because a single firm's expenses exceeding revenue is a business net loss.","B":"Incorrect because government spending exceeding tax receipts is a fiscal *budget deficit*.","C":"Correct selection.","D":"Incorrect because exports exceeding imports is a current account *surplus*."}}},{"id":"P1_U6_MCQ_904","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_904","question":"How does a government 'subsidy' paid to domestic renewable energy or manufacturing firms affect those businesses?","options":{"A":"It increases their production costs and forces them to raise prices.","B":"It requires them to pay higher corporation tax.","C":"It bans them from exporting products abroad.","D":"It lowers their effective production costs, allowing them to charge lower, more competitive prices or increase output and investment."},"correctOption":"D","correctAnswer":"It lowers their effective production costs, allowing them to charge lower, more competitive prices or increase output and investment.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a government subsidy is a financial grant that offsets operating or capital costs.","distractor_reasons":{"A":"Incorrect because subsidies *reduce*, rather than increase, production costs.","B":"Incorrect because subsidies provide financial support rather than higher taxes.","C":"Incorrect because subsidies often help firms compete in domestic and export markets.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_905","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_905","question":"How can a business respond if its home economy enters a prolonged recession while overseas economies are growing strongly?","options":{"A":"Diversify into exporting to faster-growing overseas markets so the business is less dependent on weak domestic demand.","B":"Raise domestic prices sharply to recover lost sales volume.","C":"Stop all marketing and customer service activities.","D":"Borrow heavily at high interest rates to build extra warehouses for unsold stock."},"correctOption":"A","correctAnswer":"Diversify into exporting to faster-growing overseas markets so the business is less dependent on weak domestic demand.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expanding into growing international markets spreads risk and offsets stagnant domestic revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raising prices in a domestic recession would reduce sales even further.","C":"Incorrect because cutting all marketing weakens brand visibility when competition for scarce customer spending is fierce.","D":"Incorrect because stockpiling unsold inventory ties up working capital and increases debt risk."}}},{"id":"P1_U6_MCQ_906","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_906","question":"Why do governments aim for 'economic growth' (a steady rise in real GDP)?","options":{"A":"Because higher output creates more jobs, raises average incomes and living standards, and generates higher tax revenues to fund public services.","B":"Because economic growth causes mass unemployment and falling living standards.","C":"Because economic growth eliminates the need for any private businesses.","D":"Because economic growth forces all prices to fall by half every year."},"correctOption":"A","correctAnswer":"Because higher output creates more jobs, raises average incomes and living standards, and generates higher tax revenues to fund public services.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustained real GDP growth improves material prosperity and strengthens public finances.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because growth *reduces* unemployment and *raises* living standards.","C":"Incorrect because private-sector business expansion is the main engine of economic growth.","D":"Incorrect because growth is not intended to cause severe deflation."}}},{"id":"P1_U6_MCQ_907","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_907","question":"Which type of business is LEAST affected by an increase in interest rates?","options":{"A":"A housebuilder whose customers rely heavily on large mortgages.","B":"A cash-rich software company with no bank loans selling low-cost subscription apps paid out of regular monthly budgets.","C":"A car dealership where 80% of buyers purchase vehicles on credit finance.","D":"A heavily indebted airline paying variable interest on large aircraft loans."},"correctOption":"B","correctAnswer":"A cash-rich software company with no bank loans selling low-cost subscription apps paid out of regular monthly budgets.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a debt-free firm selling inexpensive, non-credit-financed items avoids both higher loan interest costs and big-ticket credit demand drops.","distractor_reasons":{"A":"Incorrect because housebuilding depends heavily on affordable mortgage rates.","B":"Correct selection.","C":"Incorrect because car finance becomes more expensive when interest rates rise.","D":"Incorrect because an airline with large variable-rate debt faces steep increases in interest payments."}}},{"id":"P1_U6_MCQ_908","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_908","question":"What happens to a business's 'break-even point' if high inflation causes raw material and energy costs to rise while the business keeps its selling price unchanged?","options":{"A":"The break-even point falls because unit contribution increases.","B":"The break-even point rises because higher variable costs reduce contribution per unit, meaning more units must be sold to cover fixed costs.","C":"The break-even point stays completely unchanged.","D":"The business immediately makes a profit from selling zero units."},"correctOption":"B","correctAnswer":"The break-even point rises because higher variable costs reduce contribution per unit, meaning more units must be sold to cover fixed costs.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because rising variable costs per unit shrink unit contribution ($\\text{Price} - \\text{Variable Cost}$), requiring higher sales volume to break even.","distractor_reasons":{"A":"Incorrect because higher variable costs *reduce*, not increase, unit contribution.","B":"Correct selection.","C":"Incorrect because variable cost increases directly alter the break-even calculation.","D":"Incorrect because fixed costs must still be covered before any profit is earned."}}},{"id":"P1_U6_MCQ_909","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_909","question":"How can a government use 'training and education spending' to reduce unemployment and support businesses?","options":{"A":"By raising income tax on workers who attend training courses.","B":"By banning businesses from using modern computers.","C":"By equipping unemployed workers with modern technical and digital skills needed by growing industries, reducing skill shortages and raising productivity.","D":"By lowering the school-leaving age to ten years old."},"correctOption":"C","correctAnswer":"By equipping unemployed workers with modern technical and digital skills needed by growing industries, reducing skill shortages and raising productivity.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because upgrading workforce skills matches jobseekers to employer vacancies and boosts output per worker.","distractor_reasons":{"A":"Incorrect because governments subsidise rather than penalise skills training.","B":"Incorrect because training prepares workers *for* modern technology.","C":"Correct selection.","D":"Incorrect because reducing education would harm workforce skills."}}},{"id":"P1_U6_MCQ_910","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_910","question":"Why does uncertainty about future inflation and interest rates make businesses hesitant to invest in new factories?","options":{"A":"Because factories can never earn any profit when interest rates change.","B":"Because unpredictable future borrowing costs and consumer demand make it difficult to forecast whether a long-term investment will be profitable.","C":"Because banks are legally forbidden from lending money during inflation.","D":"Because businesses prefer to keep all their money in physical cash under office desks."},"correctOption":"B","correctAnswer":"Because unpredictable future borrowing costs and consumer demand make it difficult to forecast whether a long-term investment will be profitable.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because capital investment requires long-term financial forecasting, which becomes much riskier under volatile macroeconomic conditions.","distractor_reasons":{"A":"Incorrect because factories can be profitable, though forecasting returns is harder.","B":"Correct selection.","C":"Incorrect because banks continue lending at adjusted rates.","D":"Incorrect because holding physical cash loses real value during inflation."}}},{"id":"P1_U6_MCQ_911","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_911","question":"If a government cuts 'government spending' on public sector infrastructure and welfare benefits to reduce a budget deficit, what is the likely short-term impact on private businesses?","options":{"A":"Total spending in the economy falls, leading to lower sales for construction contractors and reduced retail demand from households.","B":"Retail sales double immediately across every town.","C":"Interest rates automatically rise to 25%.","D":"Private businesses no longer have to pay any wages."},"correctOption":"A","correctAnswer":"Total spending in the economy falls, leading to lower sales for construction contractors and reduced retail demand from households.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting public expenditure withdraws aggregate demand from both public-sector suppliers and household consumers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower public spending and transfers reduce, rather than double, retail demand.","C":"Incorrect because fiscal spending cuts typically ease pressure on interest rates rather than spiking them.","D":"Incorrect because private firms remain responsible for employee wages."}}},{"id":"P1_U6_MCQ_912","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_912","question":"How can a business respond to a reduction in corporation tax rates?","options":{"A":"Use the higher after-tax retained profits to invest in new product development, upgrade machinery, or increase dividends to attract investors.","B":"Deliberately make losses so it pays no tax.","C":"Stop selling products to customers completely.","D":"Raise prices by 50% to reduce demand."},"correctOption":"A","correctAnswer":"Use the higher after-tax retained profits to invest in new product development, upgrade machinery, or increase dividends to attract investors.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lower corporate taxes increase internal funds and improve the after-tax return on investment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commercial businesses aim to maximise after-tax profit, not create losses.","C":"Incorrect because businesses expand operations when taxes fall.","D":"Incorrect because lower taxes reduce pressure to hike prices."}}},{"id":"P1_U6_MCQ_913","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_913","question":"Why might a central bank keep interest rates low during a slow economic recovery?","options":{"A":"To discourage households from buying homes and cars.","B":"To make borrowing cheap for businesses and consumers, encouraging investment and spending so GDP growth and employment continue to rise.","C":"To force businesses to lay off workers.","D":"To eliminate all exports from the country."},"correctOption":"B","correctAnswer":"To make borrowing cheap for businesses and consumers, encouraging investment and spending so GDP growth and employment continue to rise.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because supportive low interest rates nurture fragile demand and business confidence until recovery is firmly established.","distractor_reasons":{"A":"Incorrect because low interest rates *encourage* mortgage and car borrowing.","B":"Correct selection.","C":"Incorrect because cheap credit supports business expansion and job creation.","D":"Incorrect because low rates tend to keep the currency competitive, aiding exports."}}},{"id":"P1_U6_MCQ_914","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_914","question":"What happens to a consumer's real savings in a bank account if the bank pays 2% annual interest while inflation is 6% per year?","options":{"A":"The real purchasing power of the savings increases by 4%.","B":"The real purchasing power of the savings stays exactly the same.","C":"The real purchasing power of the savings falls because prices are rising faster than the interest earned.","D":"The bank doubles the customer's deposit balance."},"correctOption":"C","correctAnswer":"The real purchasing power of the savings falls because prices are rising faster than the interest earned.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when inflation exceeds the nominal deposit interest rate, saved money buys fewer goods over time.","distractor_reasons":{"A":"Incorrect because real value grows only when interest exceeds inflation.","B":"Incorrect because the 4% gap erodes real purchasing power.","C":"Correct selection.","D":"Incorrect because the nominal balance grows by 2%, not 100%."}}},{"id":"P1_U6_MCQ_915","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_915","question":"How does a government decision to raise 'business rates' (property taxes on shops, offices, and factories) affect a high-street retailer?","options":{"A":"It lowers the retailer's variable raw material costs.","B":"It increases the retailer's fixed overhead costs regardless of sales volume, squeezing net profit margins.","C":"It increases customers' disposable incomes.","D":"It exempts the retailer from paying employee wages."},"correctOption":"B","correctAnswer":"It increases the retailer's fixed overhead costs regardless of sales volume, squeezing net profit margins.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because property taxes must be paid even if store sales drop, raising the retailer's fixed costs and break-even point.","distractor_reasons":{"A":"Incorrect because business rates are property overheads, not variable material costs.","B":"Correct selection.","C":"Incorrect because commercial property taxes do not raise household incomes.","D":"Incorrect because staff wages remain payable."}}},{"id":"P1_U6_MCQ_916","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_916","question":"Why do businesses closely monitor official forecasts of GDP growth, inflation, and interest rates?","options":{"A":"To plan future production capacity, staffing levels, pricing strategies, and financing decisions proactively rather than being caught unprepared.","B":"Because businesses have the legal power to vote on central bank interest rates.","C":"Because GDP forecasts determine the exact profit every business is guaranteed to make.","D":"To avoid paying any indirect taxes."},"correctOption":"A","correctAnswer":"To plan future production capacity, staffing levels, pricing strategies, and financing decisions proactively rather than being caught unprepared.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because macroeconomic indicators signal upcoming shifts in customer demand, input costs, and borrowing conditions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because independent central bank committees set interest rates.","C":"Incorrect because macroeconomic forecasts guide planning rather than guaranteeing individual firm profits.","D":"Incorrect because monitoring economic data does not waive tax obligations."}}},{"id":"P1_U6_MCQ_917","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_917","question":"Which statement best evaluates the impact of an economic boom on a manufacturing business?","options":{"A":"A boom guarantees zero business risks and falling costs forever.","B":"A boom causes sales and profits to collapse across every industry.","C":"While strong consumer demand boosts sales revenue and profits, capacity shortages, rising raw material prices, and higher wage demands can push up unit costs.","D":"A boom affects only government departments and has no impact on private manufacturers."},"correctOption":"C","correctAnswer":"While strong consumer demand boosts sales revenue and profits, capacity shortages, rising raw material prices, and higher wage demands can push up unit costs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a balanced evaluation recognises both booming revenue opportunities and overheating cost pressures.","distractor_reasons":{"A":"Incorrect because booms bring rising input and wage costs and often precede slowdowns.","B":"Incorrect because falling sales occur during a recession, not a boom.","C":"Correct selection.","D":"Incorrect because private manufacturers directly experience higher orders and tighter supply inputs."}}},{"id":"P1_U6_MCQ_918","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_918","question":"How are 'social costs' calculated in relation to business activity?","options":{"A":"$\\text{Social Costs} = \\text{Private Costs} + \\text{External Costs}$","B":"$\\text{Social Costs} = \\text{Private Benefits} - \\text{External Benefits}$","C":"$\\text{Social Costs} = \\text{Total Revenue} - \\text{Total Costs}$","D":"$\\text{Social Costs} = \\text{Fixed Costs} + \\text{Variable Costs}$"},"correctOption":"A","correctAnswer":"$\\text{Social Costs} = \\text{Private Costs} + \\text{External Costs}$","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social costs represent the total cost to society of a business decision, combining the firm's internal private costs and external spillover costs on third parties.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this mixes benefits rather than summing costs.","C":"Incorrect because total revenue minus total costs is *profit*.","D":"Incorrect because fixed plus variable costs equals *private total costs* only."}}},{"id":"P1_U6_MCQ_919","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_919","question":"A chemical factory spends $500,000 per year on wages, raw materials, and electricity (private costs), and its river pollution causes $120,000 per year in cleanup and health costs to local residents (external costs). What is the factory's annual social cost?","options":{"A":"$380,000","B":"$620,000","C":"$500,000","D":"$120,000"},"correctOption":"B","correctAnswer":"$620,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because $\\text{Social Costs} = \\text{Private Costs } (\\$500,000) + \\text{External Costs } (\\$120,000) = \\$620,000$.","distractor_reasons":{"A":"Incorrect because external costs are *added* to private costs, not subtracted.","B":"Correct selection.","C":"Incorrect because $500,000 includes only the factory's private costs.","D":"Incorrect because $120,000 includes only the external costs."}}},{"id":"P1_U6_MCQ_920","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_920","question":"Which of the following is an example of an 'external benefit' generated by a business building a new training centre and access road in a deprived town?","options":{"A":"The construction costs paid by the business to build the centre.","B":"The sales revenue earned by the business from its customers.","C":"Improved local road access for neighbouring residents and higher local workforce skills that also benefit other nearby employers.","D":"Increased traffic noise and dust during construction."},"correctOption":"C","correctAnswer":"Improved local road access for neighbouring residents and higher local workforce skills that also benefit other nearby employers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because external benefits are positive spillover gains enjoyed by third parties outside the business without paying for them.","distractor_reasons":{"A":"Incorrect because construction expenses are *private costs* to the business.","B":"Incorrect because sales revenue is a *private benefit* to the business.","C":"Correct selection.","D":"Incorrect because noise and dust are *external costs*."}}},{"id":"P1_U6_MCQ_921","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_921","question":"How are 'social benefits' defined?","options":{"A":"$\\text{Social Benefits} = \\text{Private Costs} + \\text{External Costs}$","B":"$\\text{Social Benefits} = \\text{Private Benefits} - \\text{Private Costs}$","C":"$\\text{Social Benefits} = \\text{External Costs} - \\text{External Benefits}$","D":"$\\text{Social Benefits} = \\text{Private Benefits} + \\text{External Benefits}$"},"correctOption":"D","correctAnswer":"$\\text{Social Benefits} = \\text{Private Benefits} + \\text{External Benefits}$","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because social benefits equal the private gains to the business and its consumers plus positive spillover benefits to wider society.","distractor_reasons":{"A":"Incorrect because private plus external costs defines *social costs*.","B":"Incorrect because private benefits minus private costs defines *private net profit*.","C":"Incorrect because social benefits sum private and external benefits.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_922","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_922","question":"Why do governments conduct a cost-benefit analysis comparing social costs and social benefits before approving a major airport or motorway expansion?","options":{"A":"To ensure the project generates a net overall benefit to society (social benefits exceed social costs) rather than considering private company profits alone.","B":"To guarantee that the construction company pays zero taxes.","C":"To ignore all noise and carbon emissions caused by aircraft.","D":"To ban local residents from expressing any opinions."},"correctOption":"A","correctAnswer":"To ensure the project generates a net overall benefit to society (social benefits exceed social costs) rather than considering private company profits alone.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public planners weigh wider environmental and community externalities alongside economic gains.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because contractors still pay standard taxes.","C":"Incorrect because noise and emissions are explicitly counted under external costs.","D":"Incorrect because public consultations feed into social cost assessments."}}},{"id":"P1_U6_MCQ_923","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_923","question":"How does business activity contribute to 'global warming' (climate change)?","options":{"A":"By switching factories from coal power to solar and wind electricity.","B":"By burning fossil fuels (coal, oil, natural gas) in factories, power stations, and transport fleets, releasing carbon dioxide and other greenhouse gases that trap heat in the atmosphere.","C":"By recycling aluminium and cardboard packaging.","D":"By planting new native forests to absorb carbon dioxide."},"correctOption":"B","correctAnswer":"By burning fossil fuels (coal, oil, natural gas) in factories, power stations, and transport fleets, releasing carbon dioxide and other greenhouse gases that trap heat in the atmosphere.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because greenhouse gas emissions from fossil fuel combustion and deforestation drive global temperature rise.","distractor_reasons":{"A":"Incorrect because renewable electricity *reduces* greenhouse gas emissions.","B":"Correct selection.","C":"Incorrect because recycling lowers energy demand and emissions.","D":"Incorrect because reforestation absorbs atmospheric carbon."}}},{"id":"P1_U6_MCQ_924","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_924","question":"Which action demonstrates a business actively contributing to 'sustainable development'?","options":{"A":"Discharging untreated chemical waste into rivers to save filtration costs.","B":"Using single-use non-recyclable plastic for all product packaging.","C":"Sourcing certified sustainable raw materials, powering factories with renewable energy, and designing products to be easily recycled.","D":"Clearing tropical rainforests without replanting trees."},"correctOption":"C","correctAnswer":"Sourcing certified sustainable raw materials, powering factories with renewable energy, and designing products to be easily recycled.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sustainable development preserves natural resources and ecosystems for future generations while meeting present needs.","distractor_reasons":{"A":"Incorrect because river pollution destroys ecosystems and harms future generations.","B":"Incorrect because non-recyclable single-use plastics create persistent waste.","C":"Correct selection.","D":"Incorrect because unmitigated deforestation depletes vital natural capital."}}},{"id":"P1_U6_MCQ_925","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_925","question":"Which legal control might a government use to reduce pollution caused by manufacturing businesses?","options":{"A":"Abolishing all environmental inspections on factories.","B":"Giving cash rewards to factories that dump toxic waste.","C":"Removing all speed limits and emissions tests on diesel lorries.","D":"Setting strict legal limits on factory emissions, imposing heavy fines on polluters, and requiring planning permission before building near sensitive habitats."},"correctOption":"D","correctAnswer":"Setting strict legal limits on factory emissions, imposing heavy fines on polluters, and requiring planning permission before building near sensitive habitats.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because command-and-control regulations and financial penalties compel firms to invest in cleaner production.","distractor_reasons":{"A":"Incorrect because removing inspections would increase pollution.","B":"Incorrect because governments fine or tax polluters rather than rewarding them.","C":"Incorrect because emissions testing is tightened, not removed.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_926","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_926","question":"How can a 'pollution permit' (emissions trading) scheme encourage a factory to cut its carbon emissions?","options":{"A":"If the factory reduces its emissions below its allocated permit limit, it can sell its spare permits to higher-polluting firms for extra revenue.","B":"Pollution permits allow factories to release unlimited toxic chemicals free of charge.","C":"Pollution permits exempt factories from paying employee wages.","D":"Pollution permits guarantee that the factory never faces competition."},"correctOption":"A","correctAnswer":"If the factory reduces its emissions below its allocated permit limit, it can sell its spare permits to higher-polluting firms for extra revenue.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tradable permits cap total industry emissions while creating a direct financial reward for clean innovation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because permits strictly limit allowable emissions, and exceeding them incurs heavy fines or requires buying extra permits.","C":"Incorrect because environmental permits have no connection to payroll obligations.","D":"Incorrect because market competition continues unaffected."}}},{"id":"P1_U6_MCQ_927","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_927","question":"What is a 'pressure group' in relation to business activity?","options":{"A":"A government department that collects corporation tax.","B":"An organised group of people who share a common interest or concern (such as environmental protection or animal welfare) and seek to influence business decisions and government policy.","C":"A board of directors elected by a company's shareholders.","D":"A commercial bank that lends money to startups."},"correctOption":"B","correctAnswer":"An organised group of people who share a common interest or concern (such as environmental protection or animal welfare) and seek to influence business decisions and government policy.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because pressure groups represent external societal or sectional interests without seeking to become the government themselves.","distractor_reasons":{"A":"Incorrect because tax collection is carried out by a government revenue agency.","B":"Correct selection.","C":"Incorrect because directors are internal corporate leaders.","D":"Incorrect because commercial banks are private financial institutions."}}},{"id":"P1_U6_MCQ_928","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_928","question":"Which action is a 'consumer boycott' organised by a pressure group?","options":{"A":"Buying extra products from a company to help increase its profits.","B":"Working unpaid overtime inside the company's factory.","C":"Persuading consumers to refuse to buy a company's products until it stops an environmentally harmful or unethical practice.","D":"Passing a new Act of Parliament inside a pressure group meeting."},"correctOption":"C","correctAnswer":"Persuading consumers to refuse to buy a company's products until it stops an environmentally harmful or unethical practice.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a consumer boycott directly threatens a business's sales revenue and brand reputation.","distractor_reasons":{"A":"Incorrect because buying more supports rather than boycotts a firm.","B":"Incorrect because working unpaid overtime is unrelated to consumer protests.","C":"Correct selection.","D":"Incorrect because only Parliament can enact legislation."}}},{"id":"P1_U6_MCQ_929","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_929","question":"Why do environmental concerns represent an 'opportunity' as well as a 'constraint' for businesses?","options":{"A":"Because environmental laws allow businesses to pollute rivers whenever they want.","B":"Because eco-friendly products always cost zero money to manufacture.","C":"Because consumers no longer care about product quality or price.","D":"While regulations and clean technology raise compliance costs (constraints), growing consumer demand for eco-friendly products allows innovative businesses to gain new customers and build a strong green brand image (opportunities)."},"correctOption":"D","correctAnswer":"While regulations and clean technology raise compliance costs (constraints), growing consumer demand for eco-friendly products allows innovative businesses to gain new customers and build a strong green brand image (opportunities).","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Cambridge IGCSE 6.2.1 explicitly examines environmental and ethical issues as both opportunities and constraints.","distractor_reasons":{"A":"Incorrect because environmental laws restrict rather than permit pollution.","B":"Incorrect because sustainable products still require production inputs.","C":"Incorrect because consumers still evaluate price and quality alongside sustainability.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_930","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_930","question":"What is meant by 'business ethics'?","options":{"A":"The moral principles and values that guide whether a business's decisions and behaviour are considered right or wrong, fair or unfair.","B":"Maximising short-term profit by any means possible as long as nobody finds out.","C":"Calculating the break-even level of output for a new factory.","D":"Setting the lowest possible price to drive all competitors out of business."},"correctOption":"A","correctAnswer":"The moral principles and values that guide whether a business's decisions and behaviour are considered right or wrong, fair or unfair.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethics concerns doing what is morally right toward workers, customers, suppliers, communities, and the environment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hiding wrongdoing violates ethical principles.","C":"Incorrect because break-even calculation is a financial operations tool.","D":"Incorrect because predatory pricing is anti-competitive and unethical."}}},{"id":"P1_U6_MCQ_931","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_931","question":"Which situation illustrates a conflict between 'profit' and 'ethics' for a clothing retailer?","options":{"A":"Installing energy-efficient LED lights that immediately reduce electricity bills and cut carbon emissions.","B":"Choosing between buying cheap shirts from a foreign factory that uses unsafe working conditions and low wages, or paying more to an ethical factory that guarantees safe conditions and fair wages.","C":"Improving website checkout speed so customers can order faster.","D":"Training sales staff to greet customers politely."},"correctOption":"B","correctAnswer":"Choosing between buying cheap shirts from a foreign factory that uses unsafe working conditions and low wages, or paying more to an ethical factory that guarantees safe conditions and fair wages.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ethical sourcing raises unit purchase costs in the short term, creating a direct trade-off with short-term profit margins.","distractor_reasons":{"A":"Incorrect because LED lighting saves money *and* helps the environment (a win-win with no conflict).","B":"Correct selection.","C":"Incorrect because faster checkout improves both customer satisfaction and sales without an ethical conflict.","D":"Incorrect because polite service is good business practice with no moral trade-off."}}},{"id":"P1_U6_MCQ_932","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_932","question":"Why is 'bribery' to win a government or corporate supply contract considered unethical?","options":{"A":"Because it rewards the company with the highest product quality.","B":"Because it lowers prices for ordinary consumers.","C":"Because it corrupts fair competition, leads to inferior or overpriced public projects, and is illegal in most jurisdictions.","D":"Because bribery is required by international trade agreements."},"correctOption":"C","correctAnswer":"Because it corrupts fair competition, leads to inferior or overpriced public projects, and is illegal in most jurisdictions.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because bribery distorts merit-based decision-making, harms society, and exposes firms to severe legal and reputational damage.","distractor_reasons":{"A":"Incorrect because bribes allow inferior suppliers to win contracts unfairly.","B":"Incorrect because the cost of bribes is usually inflated into higher contract prices.","C":"Correct selection.","D":"Incorrect because international treaties actively prohibit bribery."}}},{"id":"P1_U6_MCQ_933","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_933","question":"How can a business's strong ethical reputation help its 'human resource management'?","options":{"A":"It allows the business to pay workers below the legal minimum wage.","B":"It eliminates the need to train new employees.","C":"It forces workers to work unpaid overtime without complaint.","D":"It makes it easier to attract talented applicants and improves employee morale, loyalty, and productivity."},"correctOption":"D","correctAnswer":"It makes it easier to attract talented applicants and improves employee morale, loyalty, and productivity.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because employees feel proud to work for an honest, fair, and socially responsible employer, reducing labour turnover.","distractor_reasons":{"A":"Incorrect because ethical businesses pay fair wages above statutory minimums.","B":"Incorrect because ethical employers invest strongly in staff training and development.","C":"Incorrect because ethical treatment respects fair working hours and pay.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_934","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_934","question":"What is a 'code of ethics' (ethical code of conduct) drawn up by a business?","options":{"A":"A formal written document stating the moral standards, rules, and values that all managers and employees are expected to follow in their work.","B":"A secret price list shared illegally with competitors.","C":"A tax return filed with the government revenue authority.","D":"A list of technical specifications for factory machinery."},"correctOption":"A","correctAnswer":"A formal written document stating the moral standards, rules, and values that all managers and employees are expected to follow in their work.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because publishing and enforcing a code of ethics embeds consistent moral standards across the organisation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because secret price-fixing is illegal collusion.","C":"Incorrect because a tax return is a financial filing.","D":"Incorrect because machine specs are engineering documents."}}},{"id":"P1_U6_MCQ_935","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_935","question":"Why is 'misleading advertising' (making false claims about a product's performance or health benefits) both unethical and damaging to a business?","options":{"A":"It increases repeat customer purchases over the long term.","B":"It deceives consumers into spending money under false pretences, leads to legal fines or advert bans, and destroys customer trust and brand loyalty.","C":"It lowers the business's advertising production costs to zero.","D":"It is encouraged by consumer protection laws."},"correctOption":"B","correctAnswer":"It deceives consumers into spending money under false pretences, leads to legal fines or advert bans, and destroys customer trust and brand loyalty.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because dishonest promotion violates consumer rights and permanently alienates disappointed buyers.","distractor_reasons":{"A":"Incorrect because deceived buyers do not make repeat purchases.","B":"Correct selection.","C":"Incorrect because misleading adverts still cost money to produce and broadcast.","D":"Incorrect because consumer protection laws strictly prohibit deceptive claims."}}},{"id":"P1_U6_MCQ_936","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_936","question":"How can a business reduce 'depletion of natural resources' in its manufacturing process?","options":{"A":"By using virgin timber from uncertified forests for disposable boxes.","B":"By designing products that cannot be repaired or recycled.","C":"By using recycled metals and plastics, minimising excess packaging, and switching from finite fossil fuels to renewable energy.","D":"By increasing raw material wastage on the factory floor."},"correctOption":"C","correctAnswer":"By using recycled metals and plastics, minimising excess packaging, and switching from finite fossil fuels to renewable energy.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because recycling, material efficiency, and renewable energy preserve finite resource stocks.","distractor_reasons":{"A":"Incorrect because uncertified virgin logging accelerates resource depletion.","B":"Incorrect because unrepairable products waste raw materials.","C":"Correct selection.","D":"Incorrect because higher wastage depletes resources faster."}}},{"id":"P1_U6_MCQ_937","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_937","question":"Why do pressure groups sometimes target a business's 'reputation' through negative publicity rather than taking legal action?","options":{"A":"Because negative publicity is completely illegal in democratic societies.","B":"Because businesses never care about their public brand image.","C":"Because negative publicity automatically transfers company shares to the pressure group.","D":"Because even when a business has not broken a strict technical law, bad publicity can frighten away customers, investors, and retail partners, forcing the firm to change."},"correctOption":"D","correctAnswer":"Because even when a business has not broken a strict technical law, bad publicity can frighten away customers, investors, and retail partners, forcing the firm to change.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because brand reputation is vital to sales and investor confidence, making public exposure a potent lever.","distractor_reasons":{"A":"Incorrect because peaceful public criticism is lawful free expression.","B":"Incorrect because consumer-facing brands invest heavily in protecting their reputation.","C":"Incorrect because publicity does not transfer legal share ownership.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_938","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_938","question":"What is an ethical approach by a large supermarket toward its small agricultural suppliers?","options":{"A":"Paying fair prices that cover farmers' production costs, honouring agreed contracts, and paying invoices promptly on time.","B":"Cancelling orders at the last minute without compensation after crops are harvested.","C":"Delaying invoice payments for nine months to boost the supermarket's cash balance.","D":"Forcing farmers to sell produce below cost price."},"correctOption":"A","correctAnswer":"Paying fair prices that cover farmers' production costs, honouring agreed contracts, and paying invoices promptly on time.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical supply-chain relationships avoid abusing dominant buyer power against smaller suppliers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because arbitrary last-minute cancellations unfairly ruin farmers.","C":"Incorrect because excessive late payment starves small farms of working capital.","D":"Incorrect because below-cost pricing threatens supplier survival."}}},{"id":"P1_U6_MCQ_939","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_939","question":"How can 'eco-friendly' product positioning create a competitive advantage for a business?","options":{"A":"It allows the business to sell faulty products without offering refunds.","B":"It differentiates the product from traditional rivals, attracts environmentally conscious customers, and may allow the business to charge a premium price.","C":"It eliminates the need for any market research or quality control.","D":"It exempts the business from paying Value Added Tax."},"correctOption":"B","correctAnswer":"It differentiates the product from traditional rivals, attracts environmentally conscious customers, and may allow the business to charge a premium price.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because genuine sustainability adds perceived value and brand differentiation in growing green consumer segments.","distractor_reasons":{"A":"Incorrect because consumer protection rights still apply fully.","B":"Correct selection.","C":"Incorrect because quality and market research remain essential.","D":"Incorrect because eco-friendly goods are still subject to standard sales taxes."}}},{"id":"P1_U6_MCQ_940","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_940","question":"What is 'greenwashing'?","options":{"A":"Cleaning factory machinery using biodegradable soap and rainwater.","B":"Investing 50% of company profits into solar and wind energy projects.","C":"Making exaggerated or misleading marketing claims to make a business or product appear more environmentally friendly than it really is.","D":"Recycling 100% of office paper and cardboard waste."},"correctOption":"C","correctAnswer":"Making exaggerated or misleading marketing claims to make a business or product appear more environmentally friendly than it really is.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because greenwashing deceives eco-conscious shoppers and backfires severely when exposed by regulators or pressure groups.","distractor_reasons":{"A":"Incorrect because using eco-friendly cleaning methods is genuine green practice.","B":"Incorrect because major renewable energy investment is authentic sustainability.","C":"Correct selection.","D":"Incorrect because thorough office recycling is genuine waste reduction."}}},{"id":"P1_U6_MCQ_941","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_941","question":"Why might a business choose to locate a noisy, 24-hour logistics warehouse in an out-of-town industrial park rather than near residential housing?","options":{"A":"Because out-of-town industrial parks never have any road access.","B":"Because residential areas always have cheaper industrial land.","C":"Because businesses are legally forbidden from operating logistics warehouses.","D":"To avoid external noise and traffic congestion costs on local residents, prevent community pressure-group protests, and comply with local zoning regulations."},"correctOption":"D","correctAnswer":"To avoid external noise and traffic congestion costs on local residents, prevent community pressure-group protests, and comply with local zoning regulations.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because separating heavy transport operations from residential neighbourhoods reduces negative externalities and planning conflicts.","distractor_reasons":{"A":"Incorrect because industrial parks are specifically built near major highway links.","B":"Incorrect because industrial park sites are usually more suitable and affordable for large warehouses.","C":"Incorrect because logistics warehouses are essential commercial facilities.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_942","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_942","question":"How does a government 'environmental tax' (such as a carbon tax on fossil fuels) change business behaviour?","options":{"A":"It makes polluting energy sources more expensive, motivating businesses to save energy and switch to cleaner renewable alternatives to reduce their tax bill.","B":"It makes coal and diesel completely free for factories.","C":"It forces businesses to increase their carbon dioxide emissions.","D":"It eliminates all competition in the energy sector."},"correctOption":"A","correctAnswer":"It makes polluting energy sources more expensive, motivating businesses to save energy and switch to cleaner renewable alternatives to reduce their tax bill.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because green taxes internalise external pollution costs into business expenses, creating a financial incentive to decarbonise.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the tax *raises* the price of fossil fuels.","C":"Incorrect because higher taxes penalise emissions and encourage reductions.","D":"Incorrect because green taxes encourage competition among clean-energy providers."}}},{"id":"P1_U6_MCQ_943","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_943","question":"Why do some businesses resist adopting strict ethical and environmental standards voluntarily?","options":{"A":"Because ethical practices always cause immediate bankruptcy.","B":"Because higher ethical wages, safer factories, and clean technology increase short-term costs, which can make the business less price-competitive against unethical rivals.","C":"Because consumers dislike businesses that treat workers fairly.","D":"Because governments fine businesses that pay fair wages."},"correctOption":"B","correctAnswer":"Because higher ethical wages, safer factories, and clean technology increase short-term costs, which can make the business less price-competitive against unethical rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unilateral ethical upgrades can place a firm at a short-term cost disadvantage if rivals cut corners.","distractor_reasons":{"A":"Incorrect because many ethical businesses are highly profitable and sustainable.","B":"Correct selection.","C":"Incorrect because consumers generally favour fair treatment of workers.","D":"Incorrect because governments encourage fair wages and safe workplaces."}}},{"id":"P1_U6_MCQ_944","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_944","question":"Which stakeholder group is most directly harmed when a factory dumps toxic chemical waste into a local river?","options":{"A":"Foreign tourists visiting a different continent.","B":"Online software subscribers living 2,000 miles away.","C":"Local residents, downstream fishermen, and local wildlife who suffer health risks, contaminated drinking water, and loss of fishing livelihoods.","D":"The factory's overseas shareholders who never visit the town."},"correctOption":"C","correctAnswer":"Local residents, downstream fishermen, and local wildlife who suffer health risks, contaminated drinking water, and loss of fishing livelihoods.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local communities and ecosystems bear the immediate external costs of water pollution.","distractor_reasons":{"A":"Incorrect because distant tourists are not directly affected by local river water.","B":"Incorrect because distant software users do not rely on that local river.","C":"Correct selection.","D":"Incorrect because local residents and fishermen experience the direct physical and economic harm."}}},{"id":"P1_U6_MCQ_945","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_945","question":"How can a business ensure its overseas suppliers comply with its ethical code of conduct?","options":{"A":"By never visiting or inspecting overseas supplier factories.","B":"By demanding impossibly low prices that force suppliers to cut worker safety.","C":"By accepting verbal promises without checking wage or safety records.","D":"By carrying out regular independent factory audits and ending contracts with suppliers that fail to correct unsafe conditions or unfair wages."},"correctOption":"D","correctAnswer":"By carrying out regular independent factory audits and ending contracts with suppliers that fail to correct unsafe conditions or unfair wages.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because monitoring, auditing, and enforcing contractual consequences ensure ethical codes are upheld in practice.","distractor_reasons":{"A":"Incorrect because failing to inspect suppliers leaves ethical abuses undetected.","B":"Incorrect because squeezing supplier prices encourages sweatshop shortcuts.","C":"Incorrect because unverified promises cannot guarantee compliance.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_946","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_946","question":"What is 'landfill waste' and why do governments discourage businesses from sending waste to landfill sites?","options":{"A":"Burying rubbish in the ground, which uses up scarce land, releases methane greenhouse gas, and can leak toxic chemicals into soil and groundwater.","B":"Converting factory scraps into reusable raw materials.","C":"Generating clean electricity from rooftop solar panels.","D":"Selling surplus stock to discount outlets."},"correctOption":"A","correctAnswer":"Burying rubbish in the ground, which uses up scarce land, releases methane greenhouse gas, and can leak toxic chemicals into soil and groundwater.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because landfilling creates long-term environmental externalities and wastes recoverable resources.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because reprocessing scraps is *recycling*.","C":"Incorrect because solar panels generate clean energy without waste.","D":"Incorrect because selling surplus inventory prevents waste."}}},{"id":"P1_U6_MCQ_947","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_947","question":"Why do pressure groups sometimes lobby governments for stricter environmental laws rather than relying only on consumer boycotts?","options":{"A":"Because consumer boycotts are illegal in every country.","B":"Because laws apply equally to every business in the industry permanently, whereas consumer boycotts may only affect certain brands temporarily.","C":"Because governments never listen to pressure groups.","D":"Because laws allow businesses to pollute more than before."},"correctOption":"B","correctAnswer":"Because laws apply equally to every business in the industry permanently, whereas consumer boycotts may only affect certain brands temporarily.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because statutory legislation creates a binding, industry-wide legal floor that prevents unethical firms from undercutting responsible ones.","distractor_reasons":{"A":"Incorrect because peaceful boycotts are legal.","B":"Correct selection.","C":"Incorrect because governments regularly enact reforms following sustained pressure-group campaigns.","D":"Incorrect because environmental legislation restricts pollution."}}},{"id":"P1_U6_MCQ_948","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_948","question":"A solar farm project generates $800,000 in private electricity sales revenue (private benefits) and reduces regional air pollution health costs by $250,000 (external benefits). What is the project's total social benefit?","options":{"A":"$550,000","B":"$800,000","C":"$1,050,000","D":"$250,000"},"correctOption":"C","correctAnswer":"$1,050,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because $\\text{Social Benefits} = \\text{Private Benefits } (\\$800,000) + \\text{External Benefits } (\\$250,000) = \\$1,050,000$.","distractor_reasons":{"A":"Incorrect because external benefits are *added* to private benefits, not subtracted.","B":"Incorrect because $800,000 counts only private revenue.","C":"Correct selection.","D":"Incorrect because $250,000 counts only external benefits."}}},{"id":"P1_U6_MCQ_949","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_949","question":"How can reducing excess product packaging benefit both the environment and a business's profit margin?","options":{"A":"It increases shipping weight and doubles raw material expenses.","B":"It forces the business to pay higher landfill taxes.","C":"It prevents customers from opening the product.","D":"Using less cardboard and plastic cuts material purchasing costs, lowers transport fuel expenses due to lighter loads, and reduces packaging waste."},"correctOption":"D","correctAnswer":"Using less cardboard and plastic cuts material purchasing costs, lowers transport fuel expenses due to lighter loads, and reduces packaging waste.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lean, minimal packaging is a classic 'win-win' that simultaneously lowers unit costs and environmental impact.","distractor_reasons":{"A":"Incorrect because using *less* packaging reduces weight and material costs.","B":"Incorrect because less packaging reduces waste disposal taxes.","C":"Incorrect because well-designed minimal packaging is easier for shoppers to open.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_950","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_950","question":"Which statement best evaluates the impact of behaving ethically on a business's long-term financial performance?","options":{"A":"Although ethical sourcing and fair wages may increase operating costs in the short term, they build customer loyalty, attract motivated staff, prevent legal fines, and support sustainable long-term profits.","B":"Behaving ethically eliminates all business costs and guarantees monopoly profits.","C":"Unethical businesses never face consumer boycotts or government fines.","D":"Ethical issues apply only to charities and have no impact on commercial businesses."},"correctOption":"A","correctAnswer":"Although ethical sourcing and fair wages may increase operating costs in the short term, they build customer loyalty, attract motivated staff, prevent legal fines, and support sustainable long-term profits.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a balanced IGCSE evaluation contrasts short-term cost constraints with long-term reputational and commercial benefits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ethical practices involve real costs and do not create monopolies.","C":"Incorrect because unethical firms frequently suffer boycotts, scandals, and penalties.","D":"Incorrect because ethical decisions directly affect commercial reputation, costs, and sales."}}},{"id":"P1_U6_MCQ_951","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_951","question":"What is meant by 'sustainable sourcing' of raw materials such as timber, fish, or palm oil?","options":{"A":"Harvesting resources as fast as possible until the entire supply is exhausted.","B":"Obtaining raw materials in ways that protect ecosystems, replant or replenish stocks, and respect local communities so supplies remain available for future generations.","C":"Buying only from unverified suppliers with the lowest prices.","D":"Replacing all natural materials with non-biodegradable toxic plastics."},"correctOption":"B","correctAnswer":"Obtaining raw materials in ways that protect ecosystems, replant or replenish stocks, and respect local communities so supplies remain available for future generations.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sustainable sourcing maintains ecological balance and secures long-term raw material availability.","distractor_reasons":{"A":"Incorrect because rapid exhaustion causes resource depletion.","B":"Correct selection.","C":"Incorrect because unverified cheap sourcing often involves deforestation or overfishing.","D":"Incorrect because toxic plastics harm the environment."}}},{"id":"P1_U6_MCQ_952","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_952","question":"How can 'noise pollution' from a business negatively affect nearby stakeholders?","options":{"A":"It contaminates underground drinking water with heavy metals.","B":"It increases the nutritional value of local crops.","C":"Constant loud machinery or night-time delivery lorries disrupt local residents' sleep and concentration, causing stress, complaints, and potential council restrictions on operating hours.","D":"It lowers electricity bills for neighbouring houses."},"correctOption":"C","correctAnswer":"Constant loud machinery or night-time delivery lorries disrupt local residents' sleep and concentration, causing stress, complaints, and potential council restrictions on operating hours.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because noise pollution is a negative external cost that harms community wellbeing and can trigger regulatory limits.","distractor_reasons":{"A":"Incorrect because chemical contamination is *water/land* pollution.","B":"Incorrect because noise has no benefit to crops.","C":"Correct selection.","D":"Incorrect because noise imposes a nuisance cost rather than lowering utility bills."}}},{"id":"P1_U6_MCQ_953","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_953","question":"Why might a business choose to publish an annual 'Corporate Social Responsibility (CSR) / Sustainability Report'?","options":{"A":"To hide all pollution data from environmental regulators.","B":"To avoid paying corporation tax on its net profits.","C":"To replace its audited income statement and statement of financial position.","D":"To communicate its ethical and environmental achievements transparently to customers, pressure groups, and ethical investors, strengthening brand trust."},"correctOption":"D","correctAnswer":"To communicate its ethical and environmental achievements transparently to customers, pressure groups, and ethical investors, strengthening brand trust.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because transparent reporting demonstrates accountability and differentiates responsible businesses.","distractor_reasons":{"A":"Incorrect because sustainability reports disclose environmental metrics publicly.","B":"Incorrect because CSR reporting does not reduce tax obligations.","C":"Incorrect because CSR reports supplement, rather than replace, statutory financial statements.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_954","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_954","question":"What is an ethical conflict regarding 'data privacy' for an online e-commerce business?","options":{"A":"Deciding between earning extra revenue by selling customers' personal browsing and contact details to third-party advertisers, or protecting customer privacy by keeping data strictly confidential.","B":"Choosing between cardboard boxes and paper bags for shipping.","C":"Calculating the break-even point for a new warehouse.","D":"Offering free shipping on orders over $50."},"correctOption":"A","correctAnswer":"Deciding between earning extra revenue by selling customers' personal browsing and contact details to third-party advertisers, or protecting customer privacy by keeping data strictly confidential.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because monetising personal data without clear consent sacrifices customer trust and privacy for short-term revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because packaging choice is an environmental/cost decision, not data privacy.","C":"Incorrect because break-even calculation is a financial tool.","D":"Incorrect because free shipping thresholds are promotional pricing."}}},{"id":"P1_U6_MCQ_955","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_955","question":"How does 'recycling' factory scrap materials benefit a manufacturing business?","options":{"A":"It increases the amount of waste sent to expensive landfill sites.","B":"It reduces spending on new virgin raw materials, lowers waste disposal fees, and improves the company's environmental image.","C":"It lowers product quality and increases customer complaints.","D":"It forces the factory to pay higher environmental taxes."},"correctOption":"B","correctAnswer":"It reduces spending on new virgin raw materials, lowers waste disposal fees, and improves the company's environmental image.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because recovering production offcuts saves input costs and reduces landfill levies.","distractor_reasons":{"A":"Incorrect because recycling *reduces* landfill waste.","B":"Correct selection.","C":"Incorrect because properly reprocessed materials maintain quality standards.","D":"Incorrect because recycling lowers waste-disposal tax liabilities."}}},{"id":"P1_U6_MCQ_956","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_956","question":"Why do pressure groups sometimes organise public 'protests or demonstrations' outside a company's flagship store or headquarters?","options":{"A":"To help customers find parking spaces outside the shop.","B":"To increase the store's daily sales revenue.","C":"To attract television, newspaper, and social media coverage that embarrasses the company and alerts shoppers to ethical or environmental concerns.","D":"To conduct an official government tax audit."},"correctOption":"C","correctAnswer":"To attract television, newspaper, and social media coverage that embarrasses the company and alerts shoppers to ethical or environmental concerns.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because visible public demonstrations generate media headlines and reputational pressure.","distractor_reasons":{"A":"Incorrect because protests draw public attention to grievances rather than assisting store parking.","B":"Incorrect because protests aim to deter shoppers and pressure management.","C":"Correct selection.","D":"Incorrect because tax authorities, not pressure groups, conduct tax audits."}}},{"id":"P1_U6_MCQ_957","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_957","question":"Which business decision best illustrates 'external costs exceeding private costs'?","options":{"A":"A bakery spends $200 on flour and sells bread for $400 with zero pollution.","B":"A software designer works from home using a laptop powered by rooftop solar panels.","C":"A bookstore donates free books to a local primary school.","D":"An unregulated logging company spends $100,000 cutting down a protected hillside forest, causing $900,000 in landslide and flood damage to villages below."},"correctOption":"D","correctAnswer":"An unregulated logging company spends $100,000 cutting down a protected hillside forest, causing $900,000 in landslide and flood damage to villages below.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the $900,000 external flood damage imposed on innocent villagers is nine times larger than the firm's $100,000 private operating cost.","distractor_reasons":{"A":"Incorrect because the bakery creates zero external pollution costs.","B":"Incorrect because solar-powered remote software work causes negligible external costs.","C":"Incorrect because donating books creates *external benefits*, not external costs.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_958","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_958","question":"What is a 'conflict of interest' between shareholders and environmental pressure groups over a company's profit allocation?","options":{"A":"Shareholders may want higher short-term cash dividends, whereas environmental pressure groups want profits reinvested into expensive carbon-capture and pollution-control equipment.","B":"Both groups want the company to go bankrupt immediately.","C":"Environmental pressure groups want the factory to burn more coal.","D":"Shareholders want the company to give away all its products free."},"correctOption":"A","correctAnswer":"Shareholders may want higher short-term cash dividends, whereas environmental pressure groups want profits reinvested into expensive carbon-capture and pollution-control equipment.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because different stakeholder groups hold competing priorities over how company profits are used.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because neither group wants business collapse (pressure groups want cleaner operations).","C":"Incorrect because environmental groups oppose fossil fuel expansion.","D":"Incorrect because shareholders invest to earn financial returns."}}},{"id":"P1_U6_MCQ_959","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.3 Business and the environment","questionNumber":"P1_U6_MCQ_959","question":"Why do many governments require 'planning permission' before a business can build a new factory or quarry?","options":{"A":"To prevent any new businesses from ever being created.","B":"To assess environmental impacts, traffic congestion, and local community effects so developments are placed in suitable locations with environmental safeguards.","C":"To force all factories to locate inside city-centre shopping malls.","D":"To eliminate the need for any environmental laws."},"correctOption":"B","correctAnswer":"To assess environmental impacts, traffic congestion, and local community effects so developments are placed in suitable locations with environmental safeguards.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because land-use planning controls external environmental and community impacts before construction begins.","distractor_reasons":{"A":"Incorrect because planning systems approve suitable developments while protecting sensitive areas.","B":"Correct selection.","C":"Incorrect because heavy factories are directed toward designated industrial zones, not shopping malls.","D":"Incorrect because planning permission works alongside ongoing environmental regulations."}}},{"id":"P1_U6_MCQ_960","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_960","question":"What is meant by 'globalisation'?","options":{"A":"The process by which countries and businesses across the world become increasingly interconnected through international trade, investment, technology, and cultural exchange.","B":"A government policy that bans all foreign imports and exports.","C":"Selling products exclusively within a single local village.","D":"Replacing all private businesses with state-owned monopolies."},"correctOption":"A","correctAnswer":"The process by which countries and businesses across the world become increasingly interconnected through international trade, investment, technology, and cultural exchange.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because globalisation describes the growing integration of national economies into a single global marketplace.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banning trade is extreme protectionism/autarky, the opposite of globalisation.","C":"Incorrect because local-only selling is purely domestic trade.","D":"Incorrect because globalisation expands private international trade and investment."}}},{"id":"P1_U6_MCQ_961","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_961","question":"Which factor is a major reason for the rapid growth of globalisation?","options":{"A":"Higher import tariffs and bans on international shipping.","B":"Advances in high-speed internet communications and cheaper container shipping and air freight, alongside trade agreements reducing tariffs.","C":"The disappearance of multinational companies.","D":"Falling consumer incomes across all developing economies."},"correctOption":"B","correctAnswer":"Advances in high-speed internet communications and cheaper container shipping and air freight, alongside trade agreements reducing tariffs.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cheaper transport, instant global communications, and trade liberalisation allow firms to operate across borders easily.","distractor_reasons":{"A":"Incorrect because lower, not higher, tariffs drove globalisation.","B":"Correct selection.","C":"Incorrect because multinational companies expanded rapidly and accelerated globalisation.","D":"Incorrect because rising incomes in emerging economies created huge new consumer markets."}}},{"id":"P1_U6_MCQ_962","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_962","question":"Which of the following is a major 'opportunity' created by globalisation for a growing business?","options":{"A":"Loss of domestic market share to cheaper foreign imports.","B":"Higher domestic interest rates on bank loans.","C":"Access to millions of new overseas customers, lower-cost raw materials from global suppliers, and greater economies of scale.","D":"Guaranteed monopoly protection from all foreign rivals."},"correctOption":"C","correctAnswer":"Access to millions of new overseas customers, lower-cost raw materials from global suppliers, and greater economies of scale.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because globalisation opens international export markets and global supply chains that reduce unit costs.","distractor_reasons":{"A":"Incorrect because losing domestic market share is a *threat* of globalisation.","B":"Incorrect because domestic interest rates are set by the central bank.","C":"Correct selection.","D":"Incorrect because globalisation increases, rather than eliminates, competition."}}},{"id":"P1_U6_MCQ_963","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_963","question":"Which of the following is a major 'threat' of globalisation for domestic businesses?","options":{"A":"Access to cheaper imported components.","B":"Ability to sell products online to foreign buyers.","C":"Lower international container shipping rates.","D":"Increased competition from foreign firms entering the home market with lower prices or strong global brands, which can reduce domestic sales and profits."},"correctOption":"D","correctAnswer":"Increased competition from foreign firms entering the home market with lower prices or strong global brands, which can reduce domestic sales and profits.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because open borders expose domestic firms to intense price and quality competition from overseas producers.","distractor_reasons":{"A":"Incorrect because cheaper components represent a cost-saving *opportunity*.","B":"Incorrect because selling to foreign buyers is a growth *opportunity*.","C":"Incorrect because lower shipping costs benefit international trade.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_964","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_964","question":"What is an 'import tariff'?","options":{"A":"A tax placed by a government on imported goods entering the country, making foreign goods more expensive compared to domestically produced goods.","B":"A physical limit on the maximum quantity of a product that can be imported.","C":"A government grant paid to foreign exporters.","D":"A fixed exchange rate between two currencies."},"correctOption":"A","correctAnswer":"A tax placed by a government on imported goods entering the country, making foreign goods more expensive compared to domestically produced goods.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an import tariff is a customs duty that raises the price of foreign goods to protect domestic producers and raise tax revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a physical quantity limit defines an *import quota*.","C":"Incorrect because tariffs tax foreign imports rather than subsidising them.","D":"Incorrect because exchange rate pegs are monetary policies."}}},{"id":"P1_U6_MCQ_965","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_965","question":"What is an 'import quota'?","options":{"A":"A 20% sales tax charged on all domestic groceries.","B":"A physical limit set by a government on the maximum quantity or value of a specific good that may be imported into the country during a given period.","C":"A subsidy paid to domestic farmers to export wheat.","D":"A ban on domestic citizens travelling abroad on holiday."},"correctOption":"B","correctAnswer":"A physical limit set by a government on the maximum quantity or value of a specific good that may be imported into the country during a given period.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an import quota restricts foreign supply volume directly, preserving market share for domestic manufacturers.","distractor_reasons":{"A":"Incorrect because a sales tax on groceries is VAT/GST.","B":"Correct selection.","C":"Incorrect because export support is an export subsidy.","D":"Incorrect because quotas apply to imported goods, not tourist travel."}}},{"id":"P1_U6_MCQ_966","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_966","question":"Why might a government introduce import tariffs or quotas on foreign steel or clothing?","options":{"A":"To force domestic factories to close down and increase unemployment.","B":"To make foreign imports cheaper for domestic shoppers.","C":"To protect domestic industries and local jobs from cheaper foreign competition, reduce a balance of payments deficit, and (for tariffs) raise government tax revenue.","D":"To encourage foreign countries to impose retaliatory tariffs on domestic exports."},"correctOption":"C","correctAnswer":"To protect domestic industries and local jobs from cheaper foreign competition, reduce a balance of payments deficit, and (for tariffs) raise government tax revenue.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because protectionism shields domestic employment and infant industries while curbing import spending.","distractor_reasons":{"A":"Incorrect because protectionism aims to *save* domestic factories and jobs.","B":"Incorrect because tariffs and quotas make imports *more expensive*.","C":"Correct selection.","D":"Incorrect because foreign retaliation is an unwanted *drawback* of tariffs, not the government's goal."}}},{"id":"P1_U6_MCQ_967","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_967","question":"How can a government import tariff on foreign steel negatively affect a domestic car manufacturer?","options":{"A":"It lowers the price of steel bought by the car manufacturer.","B":"It guarantees that foreign buyers will buy twice as many domestic cars.","C":"It eliminates the car manufacturer's corporation tax bill.","D":"It increases the cost of imported steel inputs, raising the car manufacturer's production costs and reducing its competitiveness at home and abroad."},"correctOption":"D","correctAnswer":"It increases the cost of imported steel inputs, raising the car manufacturer's production costs and reducing its competitiveness at home and abroad.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because tariffs on raw materials and components raise costs for downstream domestic manufacturers.","distractor_reasons":{"A":"Incorrect because tariffs *increase* steel prices.","B":"Incorrect because higher production costs make exported cars less competitive.","C":"Incorrect because import tariffs do not waive corporate profit taxes.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_968","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_968","question":"What is a 'multinational company' (MNC)?","options":{"A":"A business with headquarters in one country that owns and operates production factories, offices, or retail outlets in more than one country.","B":"A small sole trader that exports handmade crafts online from a single home workshop.","C":"A government ministry that regulates international airports.","D":"A local supermarket chain operating stores in only one city."},"correctOption":"A","correctAnswer":"A business with headquarters in one country that owns and operates production factories, offices, or retail outlets in more than one country.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because merely exporting goods does not make a firm an MNC; it must operate physical production or service facilities in multiple countries.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an exporting sole trader with no overseas facilities is an exporter, not an MNC.","C":"Incorrect because a government ministry is a public sector regulator.","D":"Incorrect because single-city operation is a purely domestic local business."}}},{"id":"P1_U6_MCQ_969","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_969","question":"Why does a business often benefit from becoming a multinational company and building a factory inside a major foreign market?","options":{"A":"It avoids import tariffs and quotas on goods sold in that country, reduces transport costs to foreign customers, and gains access to lower-cost labour or raw materials.","B":"It guarantees zero competition from local businesses.","C":"It eliminates the need to pay any wages or utility bills worldwide.","D":"It allows the company to ignore all local health and safety laws."},"correctOption":"A","correctAnswer":"It avoids import tariffs and quotas on goods sold in that country, reduces transport costs to foreign customers, and gains access to lower-cost labour or raw materials.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because producing inside the target market bypasses trade barriers and lowers logistics and input costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local and rival international firms still compete in that market.","C":"Incorrect because MNCs pay substantial payroll and operating costs across host countries.","D":"Incorrect because MNC subsidiaries must comply with host-country statutory laws."}}},{"id":"P1_U6_MCQ_970","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_970","question":"Which benefit does a host country's economy gain when a multinational company builds a new car assembly plant there?","options":{"A":"Guaranteed bankruptcy of all domestic component suppliers.","B":"Creation of new local jobs, increased tax revenues for the government, higher exports, and transfer of modern technology and skills to local workers.","C":"Immediate collapse of the host country's currency.","D":"Higher unemployment across the entire region."},"correctOption":"B","correctAnswer":"Creation of new local jobs, increased tax revenues for the government, higher exports, and transfer of modern technology and skills to local workers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inward MNC investment stimulates employment, output, tax receipts, exports, and skill development.","distractor_reasons":{"A":"Incorrect because local component suppliers often *gain* new orders from the MNC.","B":"Correct selection.","C":"Incorrect because inward investment inflows actually strengthen demand for the host currency.","D":"Incorrect because building a new assembly plant *reduces* regional unemployment."}}},{"id":"P1_U6_MCQ_971","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_971","question":"Which potential drawback can a host country experience when large multinational companies enter its market?","options":{"A":"Consumers have fewer product choices than before.","B":"The government receives zero tax revenue from employee wages.","C":"Small local businesses may be forced out of business by intense MNC competition, profits may be sent back (repatriated) to the MNC's home country, and non-renewable resources may be depleted.","D":"Local workers learn too many advanced engineering skills."},"correctOption":"C","correctAnswer":"Small local businesses may be forced out of business by intense MNC competition, profits may be sent back (repatriated) to the MNC's home country, and non-renewable resources may be depleted.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Cambridge IGCSE 6.3.2 highlights local firm displacement, profit repatriation, and resource/worker exploitation as key drawbacks.","distractor_reasons":{"A":"Incorrect because MNC entry *increases* consumer product variety.","B":"Incorrect because local MNC employees pay income and consumption taxes.","C":"Correct selection.","D":"Incorrect because technology and skills transfer is a major *benefit* to the host country."}}},{"id":"P1_U6_MCQ_972","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_972","question":"What is meant by an 'exchange rate'?","options":{"A":"The rate of interest charged on international bank loans.","B":"The rate at which goods are returned by dissatisfied customers.","C":"The percentage tariff charged on imported electronics.","D":"The price of one currency in terms of another currency (for example, $1 = £0.75)."},"correctOption":"D","correctAnswer":"The price of one currency in terms of another currency (for example, $1 = £0.75).","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the exchange rate determines how much foreign currency is obtained per unit of domestic currency.","distractor_reasons":{"A":"Incorrect because loan charges are interest rates.","B":"Incorrect because product returns are quality/customer service metrics.","C":"Incorrect because import taxes are customs tariffs.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_973","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_973","question":"What is meant by currency 'appreciation'?","options":{"A":"A rise in the value of a currency against other currencies, so one unit of the currency buys more foreign currency than before.","B":"A fall in the value of a currency against other currencies.","C":"A fall in the domestic price of everyday groceries.","D":"An increase in the rate of unemployment."},"correctOption":"A","correctAnswer":"A rise in the value of a currency against other currencies, so one unit of the currency buys more foreign currency than before.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because appreciation means the currency has strengthened externally.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a fall in currency value is *depreciation*.","C":"Incorrect because falling domestic prices represent deflation.","D":"Incorrect because unemployment is a labour market indicator."}}},{"id":"P1_U6_MCQ_974","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_974","question":"What is meant by currency 'depreciation'?","options":{"A":"An increase in the value of a currency so it buys more foreign currency.","B":"A fall in the value of a currency against other currencies, so one unit of the currency buys less foreign currency than before.","C":"The annual wear and tear of factory machinery in accounting.","D":"A rise in the central bank's base interest rate."},"correctOption":"B","correctAnswer":"A fall in the value of a currency against other currencies, so one unit of the currency buys less foreign currency than before.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because in international economics (Unit 6), currency depreciation refers to a decline in a currency's external exchange value.","distractor_reasons":{"A":"Incorrect because buying more foreign currency is *appreciation*.","B":"Correct selection.","C":"Incorrect because asset wear and tear is *accounting depreciation* of non-current assets (Unit 5), not exchange rate depreciation.","D":"Incorrect because interest rate changes are monetary policy."}}},{"id":"P1_U6_MCQ_975","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_975","question":"A UK business exports bicycles priced at £400 each to the USA. If the exchange rate changes from £1 = $1.25 to £1 = $1.50, what is the new US dollar price of each bicycle?","options":{"A":"$500","B":"$400","C":"$600","D":"$267"},"correctOption":"C","correctAnswer":"$600","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because at the appreciated rate of £1 = $1.50, a £400 bicycle costs $£400 \\times 1.50 = \\$600$ (up from $\\$500$ at $£1 = \\$1.25$).","distractor_reasons":{"A":"Incorrect because $500 was the *old* price at £1 = $1.25 ($400 × 1.25).","B":"Incorrect because $400 ignores the exchange rate conversion.","C":"Correct selection.","D":"Incorrect because $267 divides 400 by 1.50 instead of multiplying."}}},{"id":"P1_U6_MCQ_976","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_976","question":"A Malaysian furniture manufacturer imports Italian leather costing €2,000 per batch. If the exchange rate changes from €1 = RM 5.00 to €1 = RM 4.50, what happens to the cost of each batch in Malaysian Ringgit (RM)?","options":{"A":"It rises from RM 9,000 to RM 10,000.","B":"It stays unchanged at RM 10,000.","C":"It rises from RM 10,000 to RM 11,000.","D":"It falls from RM 10,000 to RM 9,000 because the Ringgit appreciated against the Euro."},"correctOption":"D","correctAnswer":"It falls from RM 10,000 to RM 9,000 because the Ringgit appreciated against the Euro.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because $€2,000 \\times 5.00 = \\text{RM } 10,000$ initially, and $€2,000 \\times 4.50 = \\text{RM } 9,000$ after the Ringgit strengthens, saving RM 1,000 per batch.","distractor_reasons":{"A":"Incorrect because the cost fell rather than rose.","B":"Incorrect because the exchange rate shifted from 5.00 to 4.50.","C":"Incorrect because the Ringgit appreciated rather than depreciated.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_977","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_977","question":"How does a 'depreciation' of a country's currency affect its exporting businesses?","options":{"A":"Their exports become cheaper in foreign currencies, making them more price-competitive abroad and likely increasing export sales and profits.","B":"Their exports become much more expensive in foreign currencies, causing export sales to collapse.","C":"Their imported raw materials become much cheaper.","D":"Foreign governments automatically ban their exports."},"correctOption":"A","correctAnswer":"Their exports become cheaper in foreign currencies, making them more price-competitive abroad and likely increasing export sales and profits.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a weaker domestic currency lowers foreign-currency selling prices (or increases domestic-currency revenue per unit sold abroad).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because exports become more expensive when the currency *appreciates*, not depreciates.","C":"Incorrect because imported inputs become *more expensive* when the currency depreciates.","D":"Incorrect because market exchange rate movements do not trigger import bans."}}},{"id":"P1_U6_MCQ_978","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_978","question":"How does an 'appreciation' of a country's currency affect a domestic business that sells only in its home market and faces strong competition from foreign imports?","options":{"A":"Foreign imports become much more expensive, boosting the domestic business's sales.","B":"Foreign imports become cheaper in the home market, increasing competitive pressure and potentially reducing the domestic business's sales and market share.","C":"The domestic business pays higher interest rates on its bank loans.","D":"The appreciation has no effect on the price of imported rival goods."},"correctOption":"B","correctAnswer":"Foreign imports become cheaper in the home market, increasing competitive pressure and potentially reducing the domestic business's sales and market share.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a stronger domestic currency makes foreign goods cheaper for domestic shoppers, intensifying import competition.","distractor_reasons":{"A":"Incorrect because appreciation makes imports *cheaper*, not more expensive.","B":"Correct selection.","C":"Incorrect because exchange rate appreciation does not automatically raise domestic loan rates.","D":"Incorrect because exchange rate shifts directly alter converted import prices."}}},{"id":"P1_U6_MCQ_979","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_979","question":"Which business benefits the MOST from an 'appreciation' of its home country's currency?","options":{"A":"A domestic hotel chain relying on foreign tourists.","B":"An exporting electronics firm that sources all its parts domestically and sells 90% of its output abroad.","C":"A domestic retailer that imports 100% of its clothing stock from overseas suppliers and sells to local customers.","D":"A domestic farmer exporting wheat to world markets."},"correctOption":"C","correctAnswer":"A domestic retailer that imports 100% of its clothing stock from overseas suppliers and sells to local customers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an importing retailer pays less in domestic currency for foreign stock while earning stable domestic-currency retail revenue.","distractor_reasons":{"A":"Incorrect because foreign tourists find hotels more expensive when the host currency appreciates.","B":"Incorrect because a pure exporter suffers reduced overseas price competitiveness.","C":"Correct selection.","D":"Incorrect because agricultural exporters become less price-competitive abroad."}}},{"id":"P1_U6_MCQ_980","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_980","question":"How might an exporting manufacturer respond if its home currency appreciates sharply and makes its products more expensive abroad?","options":{"A":"Increase its domestic selling prices by 40%.","B":"Stop all quality improvements and customer service.","C":"Take out expensive loans to buy foreign currency at the worst possible rate.","D":"Cut internal production costs to absorb part of the currency rise, focus on non-price factors like quality and branding, or source cheaper imported components."},"correctOption":"D","correctAnswer":"Cut internal production costs to absorb part of the currency rise, focus on non-price factors like quality and branding, or source cheaper imported components.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lowering costs, using cheaper imported inputs (which benefit from the strong currency), and competing on quality help preserve export sales.","distractor_reasons":{"A":"Incorrect because hiking prices further would worsen its price disadvantage.","B":"Incorrect because non-price differentiation becomes *more* vital when price competitiveness falls.","C":"Incorrect because borrowing to speculate on currency increases financial risk.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_981","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_981","question":"Why do multinational companies often locate different stages of production in different countries (for example, R&D in a developed country and assembly in a developing country)?","options":{"A":"To match each business activity with the country offering the best combination of specialist skills or lowest operating costs, maximising global efficiency.","B":"Because international laws forbid R&D and assembly from taking place in the same country.","C":"To increase transport costs and delivery times as much as possible.","D":"Because developing countries have higher factory wage rates than developed countries."},"correctOption":"A","correctAnswer":"To match each business activity with the country offering the best combination of specialist skills or lowest operating costs, maximising global efficiency.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because international division of labour leverages high-skill talent hubs alongside low-cost manufacturing locations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no law prohibits keeping R&D and assembly together; firms separate them for cost and skill advantages.","C":"Incorrect because firms seek to minimise transport costs.","D":"Incorrect because developing economies typically offer lower labour costs."}}},{"id":"P1_U6_MCQ_982","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_982","question":"What is a 'free trade agreement' between two or more countries?","options":{"A":"An agreement where businesses give away their products free to foreign consumers.","B":"An agreement to remove or reduce import tariffs, quotas, and other trade barriers between member countries to encourage cross-border trade.","C":"An agreement to impose 100% tariffs on all goods traded between member states.","D":"An agreement banning multinational companies from investing in member countries."},"correctOption":"B","correctAnswer":"An agreement to remove or reduce import tariffs, quotas, and other trade barriers between member countries to encourage cross-border trade.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because free trade agreements expand market access for exporters and lower import prices for businesses and consumers.","distractor_reasons":{"A":"Incorrect because 'free' refers to trade *free from government barriers*, not zero commercial prices.","B":"Correct selection.","C":"Incorrect because 100% tariffs represent protectionism, not free trade.","D":"Incorrect because trade agreements normally encourage cross-border investment."}}},{"id":"P1_U6_MCQ_983","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_983","question":"Why might a small domestic business struggle to compete when a large foreign multinational company opens stores in its country?","options":{"A":"Because small domestic businesses are legally barred from advertising.","B":"Because multinational companies always charge higher prices than small local shops.","C":"Because the multinational benefits from massive economies of scale, huge marketing budgets, and global brand recognition, allowing it to offer lower prices and heavy promotion.","D":"Because consumers prefer businesses with smaller product ranges."},"correctOption":"C","correctAnswer":"Because the multinational benefits from massive economies of scale, huge marketing budgets, and global brand recognition, allowing it to offer lower prices and heavy promotion.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because purchasing, marketing, and technical economies of scale give MNCs major cost and promotional advantages.","distractor_reasons":{"A":"Incorrect because small firms are free to advertise within their budgets.","B":"Incorrect because MNCs frequently undercut small rivals on price due to bulk buying.","C":"Correct selection.","D":"Incorrect because large retailers often attract shoppers with wide product ranges."}}},{"id":"P1_U6_MCQ_984","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_984","question":"How can a business reduce the risk of foreign exchange rate changes when importing raw materials?","options":{"A":"By refusing to check exchange rates until after invoices are paid.","B":"By exporting zero products and keeping all cash in foreign notes.","C":"By borrowing money at high interest rates in the home country.","D":"By sourcing materials from domestic suppliers in local currency or agreeing fixed-rate forward currency contracts with its bank."},"correctOption":"D","correctAnswer":"By sourcing materials from domestic suppliers in local currency or agreeing fixed-rate forward currency contracts with its bank.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because domestic sourcing removes currency conversion entirely while forward contracts lock in known costs.","distractor_reasons":{"A":"Incorrect because ignoring currency rates exposes profit margins to unexpected cost spikes.","B":"Incorrect because holding unhedged foreign cash still exposes the business to exchange rate movements.","C":"Incorrect because high-interest domestic loans add expense without solving currency risk.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_985","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_985","question":"If a country's currency depreciates, why might the overall impact on an exporting manufacturer be smaller than expected if the manufacturer uses many imported components?","options":{"A":"Because while export selling prices become cheaper abroad, the domestic-currency cost of imported components rises, offsetting part of the competitive gain.","B":"Because currency depreciation makes imported components completely free.","C":"Because exporters are legally forbidden from raising or lowering prices.","D":"Because depreciation reduces consumer demand inside foreign countries."},"correctOption":"A","correctAnswer":"Because while export selling prices become cheaper abroad, the domestic-currency cost of imported components rises, offsetting part of the competitive gain.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high import content in manufactured exports means a weaker currency raises input costs at the same time it aids export pricing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because depreciation makes imported components *more expensive*, not free.","C":"Incorrect because businesses set their own commercial export prices.","D":"Incorrect because domestic depreciation makes goods *more attractive* to foreign buyers."}}},{"id":"P1_U6_MCQ_986","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_986","question":"How can globalisation benefit workers in a developing country where multinational companies invest?","options":{"A":"By eliminating all training opportunities in modern factories.","B":"By creating new formal employment opportunities, often paying higher wages than traditional local jobs and providing modern technical training.","C":"By forcing all workers to leave the country.","D":"By banning trade unions and workplace safety rules."},"correctOption":"B","correctAnswer":"By creating new formal employment opportunities, often paying higher wages than traditional local jobs and providing modern technical training.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because MNC investment frequently creates jobs with better pay, structured training, and career progression than informal local alternatives.","distractor_reasons":{"A":"Incorrect because MNCs invest in training local staff to operate modern machinery.","B":"Correct selection.","C":"Incorrect because MNCs bring jobs *to* the host country's workforce.","D":"Incorrect because responsible MNCs adhere to formal safety standards."}}},{"id":"P1_U6_MCQ_987","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_987","question":"What is a major risk for a business that relies on a single foreign supplier in a distant country for a vital component?","options":{"A":"Transport distances are too short to achieve economies of scale.","B":"Domestic customers will refuse to buy products made with reliable parts.","C":"Port strikes, extreme weather, sudden import tariffs, or exchange rate surges can interrupt component deliveries and halt production.","D":"The foreign supplier will never charge any money for components."},"correctOption":"C","correctAnswer":"Port strikes, extreme weather, sudden import tariffs, or exchange rate surges can interrupt component deliveries and halt production.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because long international supply lines without backup suppliers increase vulnerability to external disruptions.","distractor_reasons":{"A":"Incorrect because distant global sourcing involves *long* transport distances.","B":"Incorrect because reliable parts enhance product quality.","C":"Correct selection.","D":"Incorrect because suppliers charge commercial prices."}}},{"id":"P1_U6_MCQ_988","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_988","question":"Why do governments sometimes use 'retaliatory tariffs' when another country imposes tariffs on their exports?","options":{"A":"To reward the foreign country for blocking their exports.","B":"To make foreign imports cheaper for domestic shoppers.","C":"To eliminate all domestic tax revenues.","D":"To pressure the foreign government to remove its trade barriers by imposing matching tariffs on that country's exports."},"correctOption":"D","correctAnswer":"To pressure the foreign government to remove its trade barriers by imposing matching tariffs on that country's exports.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because tit-for-tat tariffs are used as negotiating leverage, though they risk escalating into a damaging trade war.","distractor_reasons":{"A":"Incorrect because retaliation penalises rather than rewards foreign trade barriers.","B":"Incorrect because tariffs raise the price of foreign imports.","C":"Incorrect because tariffs generate customs tax revenue.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_989","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_989","question":"When expanding into a new foreign market, why must a food or clothing business adapt its marketing mix to local culture?","options":{"A":"Because differences in religion, dietary laws, climate, language, and fashion tastes mean an unchanged domestic product or advert may fail or offend local consumers.","B":"Because international laws forbid selling the same brand name in two countries.","C":"Because consumers in every country have identical tastes and incomes.","D":"Because adapting products eliminates all production costs."},"correctOption":"A","correctAnswer":"Because differences in religion, dietary laws, climate, language, and fashion tastes mean an unchanged domestic product or advert may fail or offend local consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cultural and climatic differences directly shape consumer preferences and legal product requirements abroad.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because global brand names are used worldwide while recipes or styles are adapted locally.","C":"Incorrect because tastes, religions, and incomes vary substantially across nations.","D":"Incorrect because local adaptation can actually add slight R&D or packaging costs."}}},{"id":"P1_U6_MCQ_990","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_990","question":"How does inward investment by a multinational company help improve a host country's 'balance of payments'?","options":{"A":"It stops all exports from leaving the host country.","B":"The initial capital inflow to build factories and export earnings from goods produced by the MNC bring foreign currency into the host economy.","C":"It forces domestic consumers to buy only imported products.","D":"It lowers the value of the host country's exports to zero."},"correctOption":"B","correctAnswer":"The initial capital inflow to build factories and export earnings from goods produced by the MNC bring foreign currency into the host economy.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because FDI brings capital inflows and often establishes export-oriented manufacturing plants.","distractor_reasons":{"A":"Incorrect because MNCs frequently *increase* host-country exports.","B":"Correct selection.","C":"Incorrect because MNCs supply goods locally as well as exporting.","D":"Incorrect because MNC output adds to national export value."}}},{"id":"P1_U6_MCQ_991","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_991","question":"Why can low unemployment sometimes create challenges for businesses that are trying to expand rapidly?","options":{"A":"Because low unemployment means consumers have no money to spend.","B":"Because governments ban businesses from hiring workers when unemployment is low.","C":"Because very few unemployed workers are available to hire, leading to recruitment bottlenecks, skill shortages, and rising wage costs.","D":"Because low unemployment causes severe deflation across the economy."},"correctOption":"C","correctAnswer":"Because very few unemployed workers are available to hire, leading to recruitment bottlenecks, skill shortages, and rising wage costs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because near-full employment tightens labour supply and drives up recruitment and payroll expenses.","distractor_reasons":{"A":"Incorrect because low unemployment means high employment and strong household incomes.","B":"Incorrect because hiring remains completely legal.","C":"Correct selection.","D":"Incorrect because low unemployment is associated with upward wage and price pressure, not deflation."}}},{"id":"P1_U6_MCQ_992","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_992","question":"How does a government decision to 'increase welfare benefits and state pensions' affect retail businesses?","options":{"A":"It reduces household spending on food and clothing.","B":"It raises corporation tax rates on small shops.","C":"It forces banks to raise mortgage interest rates.","D":"Lower-income households and pensioners spend a high proportion of extra income immediately on everyday necessities, boosting retail sales."},"correctOption":"D","correctAnswer":"Lower-income households and pensioners spend a high proportion of extra income immediately on everyday necessities, boosting retail sales.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because transfer payments to lower-income households quickly flow into local retail consumption.","distractor_reasons":{"A":"Incorrect because higher benefits *increase* spending on necessities.","B":"Incorrect because welfare spending does not automatically alter corporate tax rates.","C":"Incorrect because fiscal transfers are separate from bank mortgage rates.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_993","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.1 Economic issues","questionNumber":"P1_U6_MCQ_993","question":"What is the main difference between 'direct taxes' and 'indirect taxes' in terms of how they affect businesses?","options":{"A":"Direct taxes (like corporation tax) are paid directly out of business profits or worker incomes, whereas indirect taxes (like VAT) are added to product selling prices and paid by consumers at purchase.","B":"Direct taxes are paid only by foreign tourists, whereas indirect taxes are paid only by charities.","C":"Direct taxes raise retail shelf prices directly, whereas indirect taxes are deducted from company net profits.","D":"There is no difference between direct taxes and indirect taxes."},"correctOption":"A","correctAnswer":"Direct taxes (like corporation tax) are paid directly out of business profits or worker incomes, whereas indirect taxes (like VAT) are added to product selling prices and paid by consumers at purchase.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because direct taxes reduce after-tax profit or disposable income, whereas indirect taxes affect retail prices and consumer demand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both tax types apply broadly across domestic residents and businesses.","C":"Incorrect because this reverses direct and indirect taxes.","D":"Incorrect because they affect different points of the economy (income/profit vs expenditure)."}}},{"id":"P1_U6_MCQ_994","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_994","question":"Why do businesses often face pressure from 'consumers' as well as 'governments' to act ethically and protect the environment?","options":{"A":"Because consumers have the legal authority to pass criminal statutes.","B":"Because growing numbers of socially conscious consumers choose to buy from ethical, eco-friendly brands and boycott businesses linked to pollution or worker exploitation.","C":"Because consumers never care about product prices.","D":"Because governments pay consumers to boycott all private companies."},"correctOption":"B","correctAnswer":"Because growing numbers of socially conscious consumers choose to buy from ethical, eco-friendly brands and boycott businesses linked to pollution or worker exploitation.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because changing consumer preferences directly reward responsible firms with market share and penalise unethical firms with lost sales.","distractor_reasons":{"A":"Incorrect because parliaments/governments pass laws, whereas consumers exercise purchasing power.","B":"Correct selection.","C":"Incorrect because consumers still weigh price alongside ethical values.","D":"Incorrect because consumer boycotts are voluntary actions, not government-paid."}}},{"id":"P1_U6_MCQ_995","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.5 Pressure groups","questionNumber":"P1_U6_MCQ_995","question":"How can a business respond if an environmental pressure group criticises its high use of plastic packaging?","options":{"A":"Double the thickness of non-recyclable plastic wrapping.","B":"Refuse to communicate with customers and close its website.","C":"Redesign packaging using recycled cardboard or biodegradable materials, reduce packaging weight, and publicise its progress clearly to restore customer trust.","D":"Dump surplus plastic packaging into a nearby river."},"correctOption":"C","correctAnswer":"Redesign packaging using recycled cardboard or biodegradable materials, reduce packaging weight, and publicise its progress clearly to restore customer trust.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because constructive operational reform addresses the root environmental concern and turns criticism into a positive brand improvement.","distractor_reasons":{"A":"Incorrect because increasing non-recyclable plastic would intensify criticism.","B":"Incorrect because shutting down communication harms sales and reputation.","C":"Correct selection.","D":"Incorrect because illegal dumping causes severe water pollution and criminal fines."}}},{"id":"P1_U6_MCQ_996","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.4 Business and ethical issues","questionNumber":"P1_U6_MCQ_996","question":"Why might a business decide *not* to use the cheapest possible raw material supplier if that supplier is known to use child labour?","options":{"A":"Because child labour laws are enforced only in rich countries.","B":"Because using child labour increases raw material purchase prices.","C":"Because suppliers using child labour always deliver higher product quality.","D":"Because using child labour is morally unacceptable and exposing the link would cause severe reputational damage, consumer boycotts, and long-term loss of sales and profits."},"correctOption":"D","correctAnswer":"Because using child labour is morally unacceptable and exposing the link would cause severe reputational damage, consumer boycotts, and long-term loss of sales and profits.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because both moral responsibility and long-term commercial survival require rejecting abusive supply chains.","distractor_reasons":{"A":"Incorrect because ethical businesses uphold human rights standards regardless of local enforcement gaps.","B":"Incorrect because unethical suppliers offer lower prices precisely by exploiting children.","C":"Incorrect because exploitative workshops rarely maintain high quality standards.","D":"Correct selection."}}},{"id":"P1_U6_MCQ_997","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_997","question":"A South African wine exporter sells a case of wine for ZAR 1,800. If the exchange rate moves from £1 = ZAR 20 to £1 = ZAR 24, what happens to the UK price in pounds (£) and the exporter's competitiveness in the UK?","options":{"A":"The UK price falls from £90 to £75, making the wine cheaper and more price-competitive for UK buyers.","B":"The UK price rises from £75 to £90, making the wine less price-competitive for UK buyers.","C":"The UK price stays unchanged at £90.","D":"The UK price rises from £90 to £120."},"correctOption":"A","correctAnswer":"The UK price falls from £90 to £75, making the wine cheaper and more price-competitive for UK buyers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because $\\text{ZAR } 1,800 \\div 20 = £90$ initially, and $\\text{ZAR } 1,800 \\div 24 = £75$ after the Rand depreciates against the pound, lowering the UK retail price.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the price fell from £90 to £75 rather than rising.","C":"Incorrect because the exchange rate shift directly lowers the pound price.","D":"Incorrect because £120 does not match either exchange rate."}}},{"id":"P1_U6_MCQ_998","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_998","question":"Why might a host country's government place certain conditions on a multinational company—such as requiring joint ventures with local firms or limits on profit repatriation—before approving its investment?","options":{"A":"To stop any jobs from being created in the host country.","B":"To ensure the host economy captures genuine benefits (such as local skill transfer, local supplier orders, and reinvested profits) while limiting potential drawbacks.","C":"To force the multinational company to pollute local rivers.","D":"To eliminate all tax revenues from the multinational's operations."},"correctOption":"B","correctAnswer":"To ensure the host economy captures genuine benefits (such as local skill transfer, local supplier orders, and reinvested profits) while limiting potential drawbacks.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because balanced host-government regulations maximise long-term developmental gains from foreign direct investment.","distractor_reasons":{"A":"Incorrect because governments aim to maximise local employment.","B":"Correct selection.","C":"Incorrect because host governments enforce environmental conditions to *prevent* pollution.","D":"Incorrect because conditions aim to protect the host country's tax base."}}},{"id":"P1_U6_MCQ_999","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_999","question":"How do 'import tariffs' and 'import quotas' differ from 'subsidies' given to domestic producers as ways to help domestic businesses compete with foreign rivals?","options":{"A":"Tariffs and quotas lower domestic taxes, whereas subsidies ban all imports.","B":"Subsidies raise retail prices for consumers, whereas tariffs lower retail prices.","C":"Tariffs and quotas restrict or tax foreign imports (raising market prices for consumers), whereas subsidies lower domestic firms' production costs without directly raising import prices.","D":"There is no difference between tariffs, quotas, and subsidies."},"correctOption":"C","correctAnswer":"Tariffs and quotas restrict or tax foreign imports (raising market prices for consumers), whereas subsidies lower domestic firms' production costs without directly raising import prices.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because trade barriers restrict foreign supply at the border, whereas domestic subsidies improve local firms' cost competitiveness directly.","distractor_reasons":{"A":"Incorrect because tariffs tax imports and subsidies grant funds rather than banning imports.","B":"Incorrect because tariffs raise consumer prices while subsidies help keep domestic prices lower.","C":"Correct selection.","D":"Incorrect because they operate through different mechanisms with different impacts on consumers and government budgets."}}},{"id":"P1_U6_MCQ_1000","section":"6","unit":"Unit 6: External influences on business activity","chapter":"6.2 Business and the international economy","questionNumber":"P1_U6_MCQ_1000","question":"Which statement provides the most balanced evaluation of how 'globalisation' affects businesses in an economy?","options":{"A":"Globalisation guarantees higher profits for every single domestic business without any risk.","B":"Globalisation destroys all domestic businesses and eliminates consumer choice.","C":"Globalisation affects only multinational banks and has no impact on manufacturers or retailers.","D":"While globalisation offers huge opportunities to expand into overseas markets, source cheaper inputs, and gain economies of scale, it also exposes businesses to fierce foreign competition and exchange rate risks."},"correctOption":"D","correctAnswer":"While globalisation offers huge opportunities to expand into overseas markets, source cheaper inputs, and gain economies of scale, it also exposes businesses to fierce foreign competition and exchange rate risks.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a strong IGCSE AO4 evaluation weighs both the growth and cost-saving opportunities of globalisation against competitive and currency threats.","distractor_reasons":{"A":"Incorrect because uncompetitive domestic firms can lose market share or fail under global competition.","B":"Incorrect because efficient, adaptable businesses thrive globally and consumers enjoy wider choice.","C":"Incorrect because manufacturers, retailers, and service providers all operate in globalised markets.","D":"Correct selection."}}}];
